-- Nooby / Elliot12-wq: original optional Hat extension. Default: disabled.
-- Custom Hat Reanimation: mobile-tuned Hat Reanimator (drops per-frame hat spin on weak devices, slow stuck timeout, light GC).
local CRM = ...
return {
	Kind = "Hat",
	Name = "Custom Hat Reanimation",
	Description = "Runs the Hats Reanimator with weak-device tuning: no per-frame hat spin, longer stuck timeout, periodic light GC.",
	TickRate = 0.2,
	Begin = function(R)
		local st = {spin = R.HatSpin, stuck = R.StuckTimeout}
		if CRM.LowEnd() then
			if R.HatSpin then R.HatSpin = false end
			if type(R.StuckTimeout) == "number" then R.StuckTimeout = math.max(R.StuckTimeout, 20) end
		end
		return st
	end,
	End = function(R, S, st)
		if not st then return end
		R.HatSpin = st.spin
		if st.stuck ~= nil then R.StuckTimeout = st.stuck end
	end,
	Tick = function() CRM.Trim() end,
}
