-- Nooby / Elliot12-wq: original optional Limb extension. Default: disabled.
-- Custom Limb Reanimation: mobile-tuned RootPart placement + 10 FPS replication on weak devices (uses the Limb Reanimator).
local CRM = ...
local lastCF, lastPos, lastT
local floor0 = -500
return {
	Kind = "Limb",
	Name = "Custom Limb Reanimation",
	Description = "Pick RootPart Mode 'Custom Limb Reanimation' (cached low-rate RootPart placement). This switch adds 10 FPS replication on weak devices + cleanup.",
	TickRate = 1,
	GetRootCFrame = function(ctx)
		local part = ctx.Torso or ctx.RootPart
		local p = part.Position
		local now = ctx.Time
		if lastCF and lastT and now - lastT < (CRM.LowEnd() and 0.05 or 0.033) and (p - lastPos).Magnitude < 4 then
			return lastCF
		end
		local fp = ctx.FallenPartsDestroyHeight
		if type(fp) ~= "number" or fp ~= fp or fp < -1e6 or fp > 1e6 then fp = floor0 end
		local y = p.Y - (ctx.Streaming and 16 or 64)
		if y < fp + 32 then y = fp + 32 end
		lastPos, lastT = p, now
		lastCF = CFrame.new(p.X, y, p.Z)
		return lastCF
	end,
	Begin = function(R)
		lastCF = nil
		local st = {fps10 = R.ReplicateFPS10}
		if CRM.LowEnd() then R.ReplicateFPS10 = true end
		return st
	end,
	End = function(R, S, st)
		if st then R.ReplicateFPS10 = st.fps10 end
		lastCF = nil
	end,
	Tick = function(R)
		for k in R._TempNotFling do
			if typeof(k) == "Instance" and not k.Parent then R._TempNotFling[k] = nil end
		end
	end,
}
