    local function snapshotWorkspaceModels()
        local result = {}
        for _, child in ipairs(workspace:GetChildren()) do
            if child:IsA("Model") then
                result[child] = true
            end
        end
        return result
    end

    local function humanoidIsDead(humanoid)
        if not humanoid or humanoid.Health <= 0 then
            return true
        end
        local ok, state = pcall(humanoid.GetState, humanoid)
        return ok and state == Enum.HumanoidStateType.Dead
    end

    local function looksLikeControllerRig(model, before, preserved)
        if not model or not model:IsA("Model") or model == originalCharacter then
            return false
        end
        if not model.Parent then
            return false
        end
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        local root = model:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or not root:IsA("BasePart") then
            return false
        end
        local bodyNames = humanoid.RigType.Name == "R15" and {
            "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
            "RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
            "RightUpperLeg", "RightLowerLeg", "RightFoot",
        } or {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"}
        for _, partName in ipairs(bodyNames) do
            local part = model:FindFirstChild(partName)
            if not part or not part:IsA("BasePart") then
                return false
            end
        end
        if humanoidIsDead(humanoid) then
            return false
        end
        local owners = environment().UhhhhhhTBZGelatekControllerOwners
        if type(owners) ~= "table"
            or owners[model] ~= activeGenerationToken
        then
            return false
        end
        -- The vendor stamps exact Instance ownership. Snapshot freshness remains
        -- a second check, except for the one deliberately preserved controller.
        return model == preserved or not before[model]
    end

    local function findControllerRig(before, preserved)
        local direct = workspace:FindFirstChild("GelatekReanimate")
            or workspace:FindFirstChild("ReanimatedRig")
            or workspace:FindFirstChild(Player.Name .. "_Fake")
        if looksLikeControllerRig(direct, before, preserved) then
            return direct
        end
        if looksLikeControllerRig(Player.Character, before, preserved) then
            return Player.Character
        end
        for _, child in ipairs(workspace:GetChildren()) do
            if looksLikeControllerRig(child, before, preserved) then
                return child
            end
        end
        return nil
    end

    local function disableBackendAnimations(rig)
        local animate = rig and rig:FindFirstChild("Animate")
        if animate and animate:IsA("LocalScript") then
            animate.Disabled = true
        end
        local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                pcall(function()
                    track:Stop(0)
                end)
            end
        end
    end

    local function captureOriginalFace(character)
        local head = character and character:FindFirstChild("Head")
        local face = head and head:FindFirstChildWhichIsA("Decal")
        if face then
            local ok, clone = pcall(function()
                return face:Clone()
            end)
            if ok then
                originalFace = clone
            end
        end
    end

    local function ensureVisibleHead(_rig)
        -- Fake controller remains invisible.
    end

    local function hideControllerBody(rig)
        if not rig then
            return
        end
        pcall(function()
            rig:SetAttribute("UhhhhhhGelatekRespawnPlaceholder", nil)
        end)
        local showController = Reanimate.ShowControllerCharacter == true
        for _, part in ipairs(rig:GetChildren()) do
            if part:IsA("BasePart") then
                part.Transparency =
                    showController and (part.Name == "HumanoidRootPart" and 1 or 0.35) or 1
            end
        end
    end

    local function destroyRespawnPlaceholder()
        table.clear(placeholderParts)
        if placeholderModel then
            pcall(function()
                placeholderModel:Destroy()
            end)
            placeholderModel = nil
        end
    end

    local function createPlaceholderPart(sourcePart)
        local ok, proxy = pcall(function()
            return sourcePart:Clone()
        end)
        if not ok or not proxy or not proxy:IsA("BasePart") then
            proxy = Instance.new("Part")
            proxy.Name = sourcePart.Name
            proxy.Size = sourcePart.Size
            pcall(function()
                proxy.Shape = sourcePart.Shape
            end)
        end
        for _, child in ipairs(proxy:GetChildren()) do
            if not child:IsA("DataModelMesh") then
                child:Destroy()
            else
                pcall(function()
                    child.TextureId = ""
                end)
            end
        end
        proxy.Name = sourcePart.Name
        proxy.Anchored = true
        proxy.CanCollide = false
        proxy.CanQuery = false
        proxy.CanTouch = false
        proxy.CastShadow = false
        proxy.Massless = true
        proxy.Color = Color3.fromRGB(255, 45, 45)
        proxy.Material = Enum.Material.SmoothPlastic
        proxy.Transparency = 1
        pcall(function()
            proxy.TextureID = ""
        end)
        pcall(function()
            proxy.LocalTransparencyModifier = 0
        end)
        return proxy
    end

    local function ensureRespawnPlaceholder(rig)
        if placeholderModel and placeholderModel.Parent then
            return placeholderModel
        end
        destroyRespawnPlaceholder()
        local model = Instance.new("Model")
        model.Name = "_UhhhhhhGelatekResetPlaceholder"
        model.Archivable = false
        model.Parent = workspace
        placeholderModel = model
        for _, sourcePart in ipairs(rig:GetChildren()) do
            if sourcePart:IsA("BasePart") and sourcePart.Name ~= "HumanoidRootPart" then
                local proxy = createPlaceholderPart(sourcePart)
                proxy.CFrame = sourcePart.CFrame
                proxy.Size = sourcePart.Size
                proxy.Parent = model
                placeholderParts[sourcePart] = proxy
            end
        end
        return model
    end

    local function ensureStaticRoot(controllerRoot)
        if not staticRootPart or not staticRootPart.Parent then
            local part = Instance.new("Part")
            part.Name = "_UhhhhhhGelatekStaticRoot"
            part.Archivable = false
            part.Anchored = true
            part.CanCollide = false
            part.CanQuery = false
            part.CanTouch = false
            part.CastShadow = false
            part.Massless = true
            part.Transparency = 1
            part.Size = controllerRoot and controllerRoot.Size or Vector3.new(2, 2, 1)
            if staticRootCFrame then
                part.CFrame = staticRootCFrame
            elseif controllerRoot then
                part.CFrame = controllerRoot.CFrame
            end
            part.Parent = workspace
            staticRootPart = part
        end
        backend.StaticRoot = staticRootPart
        return staticRootPart
    end

    local function updatePoseMirror(rig)
        local controllerRoot = rig and rig:FindFirstChild("HumanoidRootPart")
        if controllerRoot
            and controllerRoot:IsA("BasePart")
            and controllerRoot.Parent
            and not placeholderActive
            and not rebindInProgress
        then
            staticRootCFrame = controllerRoot.CFrame
            local tracker = ensureStaticRoot(controllerRoot)
            tracker.CFrame = controllerRoot.CFrame
            tracker.Size = controllerRoot.Size
            environment().UhhhhhhTBZGelatekStaticRootCFrame = staticRootCFrame
        end

        if not placeholderActive then
            if placeholderModel then
                for _, proxy in pairs(placeholderParts) do
                    if proxy and proxy.Parent then
                        proxy.Transparency = 1
                    end
                end
            end
            return
        end

        if not placeholderModel or not placeholderModel.Parent then
            ensureRespawnPlaceholder(rig)
        end
        local transparency = 1
        if Reanimate.ShowResetPlaceholder == true then
            transparency = math.min(tonumber(Reanimate.PlaceholderTransparency) or 0.5, 0.5)
        end
        for sourcePart, proxy in pairs(placeholderParts) do
            if proxy and proxy.Parent and sourcePart and sourcePart.Parent then
                -- While reset/rebind is active the placeholder is a snapshot,
                -- not a live mirror. A dying controller can fall through the
                -- map after Roblox disables/destroys it; following that fall is
                -- what previously buried the red placeholder underground.
                local sourceMesh = sourcePart:FindFirstChildWhichIsA("DataModelMesh")
                local proxyMesh = proxy:FindFirstChildWhichIsA("DataModelMesh")
                if sourceMesh and proxyMesh then
                    pcall(function()
                        proxyMesh.Scale = sourceMesh.Scale
                        proxyMesh.Offset = sourceMesh.Offset
                    end)
                end
                proxy.Color = Color3.fromRGB(255, 45, 45)
                proxy.Material = Enum.Material.SmoothPlastic
                proxy.Transparency = transparency
            elseif proxy and proxy.Parent then
                -- If Roblox destroyed the controller during a default reset, keep
                -- the final mirrored pose frozen until its replacement is ready.
                proxy.Transparency = transparency
            end
        end
    end

    local function detachPoseMirror(destroyInfrastructure)
        if poseMirrorConnection then
            pcall(function()
                poseMirrorConnection:Disconnect()
            end)
            poseMirrorConnection = nil
        end
        poseMirrorRig = nil
        if destroyInfrastructure then
            placeholderActive = false
            destroyRespawnPlaceholder()
            if staticRootPart then
                pcall(function()
                    staticRootPart:Destroy()
                end)
                staticRootPart = nil
            end
            backend.StaticRoot = nil
            staticRootCFrame = nil
        end
    end

    local function attachPoseMirror(rig)
        if poseMirrorRig == rig and poseMirrorConnection then
            updatePoseMirror(rig)
            return
        end
        detachPoseMirror(false)
        poseMirrorRig = rig
        if placeholderModel then
            destroyRespawnPlaceholder()
        end
        hideControllerBody(rig)
        updatePoseMirror(rig)
        poseMirrorConnection = RunService.PreRender:Connect(function()
            if rig and rig.Parent then
                hideControllerBody(rig)
            end
            -- Keep applying placeholder visibility even after Roblox destroys a
            -- default-reset controller; its proxy pose intentionally stays frozen.
            updatePoseMirror(rig)
        end)
    end

    local function setRespawnPlaceholderActive(active, rig)
        placeholderActive = active == true
        if placeholderActive and rig and rig.Parent then
            ensureRespawnPlaceholder(rig)
            updatePoseMirror(rig)
        elseif not placeholderActive then
            destroyRespawnPlaceholder()
        end
    end

    local function detachCameraBridge()
        if cameraBridgeBound then
            pcall(RunService.UnbindFromRenderStep, RunService, CAMERA_BRIDGE_NAME)
            cameraBridgeBound = false
        end
        if cameraBridgeConnection then
            pcall(function()
                cameraBridgeConnection:Disconnect()
            end)
            cameraBridgeConnection = nil
        end
        if type(Reanimate.CharacterLTMs) == "table" then
            -- CharacterLTMs is shared by every backend. Remove only the exact
            -- entries this Gelatek camera bridge appended.
            for _, owned in ipairs(cameraBridgeLTMs) do
                for index = #Reanimate.CharacterLTMs, 1, -1 do
                    if Reanimate.CharacterLTMs[index] == owned then
                        table.remove(Reanimate.CharacterLTMs, index)
                        break
                    end
                end
            end
        end
        table.clear(cameraBridgeLTMs)
        for part, before in pairs(gelatekVisibilityParts) do
            if part and part.Parent then
                pcall(function()
                    part.LocalTransparencyModifier = before
                end)
            end
        end
        table.clear(gelatekVisibilityParts)
    end

    local visibilityR15ToR6 = {
        UpperTorso = "Torso", LowerTorso = "Torso",
        LeftUpperArm = "Left Arm", LeftLowerArm = "Left Arm", LeftHand = "Left Arm",
        RightUpperArm = "Right Arm", RightLowerArm = "Right Arm", RightHand = "Right Arm",
        LeftUpperLeg = "Left Leg", LeftLowerLeg = "Left Leg", LeftFoot = "Left Leg",
        RightUpperLeg = "Right Leg", RightLowerLeg = "Right Leg", RightFoot = "Right Leg",
    }

    local function getControllerVisibilityPart(rig, physicalPart)
        local accessory = physicalPart:FindFirstAncestorWhichIsA("Accessory")
        if accessory then
            local targets = environment().UhhhhhhTBZGelatekAccessoryTargets
            local proxyAccessory = type(targets) == "table" and targets[accessory]
            return proxyAccessory
                and proxyAccessory:FindFirstChild(physicalPart.Name, true)
                or nil
        end
        return rig and (rig:FindFirstChild(physicalPart.Name) or rig:FindFirstChild(visibilityR15ToR6[physicalPart.Name] or physicalPart.Name))
    end

    local function updateGelatekPhysicalVisibility(rig)
        local physical = backend.RealCharacter or originalCharacter
        if not physical or not physical.Parent then
            return
        end
        local camera = workspace.CurrentCamera
        local firstPerson = false
        if camera
            and type(Reanimate.Camera) == "table"
            and type(Reanimate.Camera.IsFirstPerson) == "function"
        then
            local read, result = pcall(Reanimate.Camera.IsFirstPerson, Reanimate.Camera)
            firstPerson = read and result == true
        end
        if not firstPerson and camera then
            firstPerson = (camera.CFrame.Position - camera.Focus.Position).Magnitude < 0.75
        end
        local cameraFade = tonumber(Reanimate.LocalTransparencyModifier) or 0
        for _, part in ipairs(getPhysicalHeadIndex(physical).Descendants) do
            if part:IsA("BasePart") and not part:FindFirstAncestorWhichIsA("Tool") then
                if gelatekVisibilityParts[part] == nil then
                    gelatekVisibilityParts[part] = part.LocalTransparencyModifier
                end
                local controllerPart = getControllerVisibilityPart(rig, part)
                local modifier = cameraFade
                if controllerPart and controllerPart:IsA("BasePart") then
                    local read, controllerModifier = pcall(function()
                        return controllerPart.LocalTransparencyModifier
                    end)
                    if read and type(controllerModifier) == "number" then
                        modifier = controllerModifier
                    end
                end
                if firstPerson then
                    if Reanimate.FirstPersonBody then
                        modifier = 0
                        if part.Name == "Head" then
                            modifier = 1
                        else
                            local weld = part:FindFirstChild("AccessoryWeld")
                            if weld and weld:IsA("JointInstance") and weld.Part1
                                and weld.Part1.Name == "Head"
                            then
                                modifier = 1
                            end
                        end
                    else
                        -- Body off means OFF. Do not wait for the camera fade to
                        -- crawl to one while the physical body fills the screen.
                        modifier = 1
                    end
                end
                pcall(function()
                    if part.LocalTransparencyModifier ~= modifier then part.LocalTransparencyModifier = modifier end
                end)
                if controllerPart and controllerPart:IsA("BasePart") then
                    pcall(function()
                        if controllerPart.LocalTransparencyModifier ~= modifier then controllerPart.LocalTransparencyModifier = modifier end
                    end)
                end
            end
        end
    end

    local function attachCameraBridge(rig)
        detachCameraBridge()
        local bridgeToken = activeGenerationToken
        Reanimate.GelatekDisableDirectionalWalking =
            options.DisableDirectionalWalking == true
        local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
        if not humanoid then
            return
        end
        pcall(function()
            humanoid.AutoRotate = true
        end)
        if type(Reanimate.CharacterLTMs) == "table" then
            for _, instance in ipairs(rig:GetDescendants()) do
                local ok = pcall(function()
                    local _ = instance.LocalTransparencyModifier
                end)
                if ok then
                    table.insert(Reanimate.CharacterLTMs, instance)
                    table.insert(cameraBridgeLTMs, instance)
                end
            end
        end
        local camera = workspace.CurrentCamera
        if camera then
            pcall(function()
                camera.CameraSubject = humanoid
            end)
        end
        local function renderBridge()
            if not generationIsActive(bridgeToken, rig) then
                return
            end
            -- Player.Character is the invisible controller after handoff, so
            -- Roblox's camera fade never reaches the visible physical shell.
            updateGelatekPhysicalVisibility(rig)
            local currentCamera = workspace.CurrentCamera
            if currentCamera and currentCamera.CameraSubject ~= humanoid then
                pcall(function()
                    currentCamera.CameraSubject = humanoid
                end)
            end
            local shouldLock = false
            if type(Reanimate.ShouldRotationType) == "function" then
                local ok, result = pcall(Reanimate.ShouldRotationType, Reanimate)
                shouldLock = ok and result == true
            end
            if not shouldLock
                and Reanimate.ShiftlockEnabled ~= false
                and type(Reanimate.Camera) == "table"
                and type(Reanimate.Camera.IsMouseLocked) == "function"
                and not Reanimate.Camera.Scriptable
            then
                local ok, result =
                    pcall(Reanimate.Camera.IsMouseLocked, Reanimate.Camera)
                shouldLock = ok and result == true
            end
            if shouldLock and type(Reanimate.CameraLockCharacter) == "function" then
                pcall(Reanimate.CameraLockCharacter)
            end
        end
        local bound = pcall(
            RunService.BindToRenderStep,
            RunService,
            CAMERA_BRIDGE_NAME,
            Enum.RenderPriority.Character.Value + 1,
            renderBridge
        )
        if bound then
            cameraBridgeBound = true
        else
            -- Some executors expose PreRender but reject named render binds.
            -- Visibility and camera ownership still get one safe writer.
            cameraBridgeConnection = RunService.PreRender:Connect(renderBridge)
        end
    end

    local function normalizedDestroyHeight(value)
        if type(value) ~= "number" or value ~= value then
            return -500
        end
        return value
    end

    local function disableVoidDestruction()
        if not destroyHeightCaptured then
            originalDestroyHeight = workspace.FallenPartsDestroyHeight
            destroyHeightCaptured = true
        end
        local global = environment()
        global.UhhhhhhTBZGelatekDestroyHeight = normalizedDestroyHeight(originalDestroyHeight)
        global.UhhhhhhTBZGelatekHiddenPartsY = global.UhhhhhhTBZGelatekDestroyHeight + 5
        pcall(function()
            workspace.FallenPartsDestroyHeight = 0 / 0
        end)
    end

    local function restoreVoidDestruction()
        if destroyHeightCaptured then
            pcall(function()
                workspace.FallenPartsDestroyHeight = originalDestroyHeight
            end)
        end
        destroyHeightCaptured = false
        originalDestroyHeight = nil
        local global = environment()
        global.UhhhhhhTBZGelatekDestroyHeight = nil
        global.UhhhhhhTBZGelatekHiddenPartsY = nil
    end

    local function characterScale()
        return math.clamp(tonumber(Reanimate.CharacterScale) or 1, 0.5, 5)
    end

    local SCALE_ATTRIBUTE = "UhhhhhhCharacterSpacingScale"

    local function applyCharacterScale(rig, force)
        if not rig or not rig.Parent then
            return false
        end
        local scale = characterScale()
        environment().UhhhhhhTBZGelatekCharacterSpacingScale = scale
        local previousScale = lastAppliedScale
        if type(previousScale) ~= "number" then
            local ok, value = pcall(rig.GetScale, rig)
            previousScale = ok and type(value) == "number" and value or 1
        end
        if not force and scale == previousScale then
            return true
        end
        local scaled = pcall(function()
            -- Model:ScaleTo owns body sizes, meshes, attachments, and joint spacing.
            -- Never rewrite Motor6D frames here: VR and jointless modules own them.
            rig:ScaleTo(scale)
            rig:SetAttribute(SCALE_ATTRIBUTE, scale)
        end)
        if not scaled then
            return false
        end
        lastAppliedScale = scale
        return true
    end

    local function jumpVelocity(humanoid)
        local useJumpPower = true
        pcall(function()
            useJumpPower = humanoid.UseJumpPower
        end)
        if useJumpPower then
            return math.max(tonumber(humanoid.JumpPower) or 0, 0)
        end
        return math.sqrt(2 * workspace.Gravity * math.max(tonumber(humanoid.JumpHeight) or 0, 0))
    end

    local function updateInfiniteJump(rig)
        local jump = type(Reanimate.Control) == "table" and Reanimate.Control.Jump == true
        if jump and not lastJump and Reanimate.InfiniteJump then
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if humanoid
                and root
                and humanoid:GetState() == Enum.HumanoidStateType.Freefall
            then
                local velocity = root.AssemblyLinearVelocity
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, jumpVelocity(humanoid), velocity.Z)
                pcall(function()
                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                end)
            end
        end
        lastJump = jump
    end

    local function restoreAccessoryBodyHideWelds()
        for weld, originalEnabled in pairs(accessoryBodyHideWeldStates) do
            if typeof(weld) == "Instance" and weld.Parent then
                pcall(function()
                    weld.Enabled = originalEnabled
                end)
            end
        end
        table.clear(accessoryBodyHideWeldStates)
    end

    local function snapAccessoryHandleToWeld(handle, weld)
        if not handle
            or not handle:IsA("BasePart")
            or not weld
            or not weld:IsA("JointInstance")
        then
            return false
        end

        local part0, part1 = weld.Part0, weld.Part1
        local c0, c1
        local okFrames = pcall(function()
            c0 = weld.C0
            c1 = weld.C1
        end)
        if not okFrames or typeof(c0) ~= "CFrame" or typeof(c1) ~= "CFrame" then
            return false
        end

        local anchor, desired
        if part0 == handle and part1 and part1:IsA("BasePart") then
            anchor = part1
            -- Weld equation: Part1*C1 = Part0*C0
            desired = part1.CFrame * c1 * (c0 * (weld:IsA("Motor6D") and weld.Transform or CFrame.identity)):Inverse()
        elseif part1 == handle and part0 and part0:IsA("BasePart") then
            anchor = part0
            desired = part0.CFrame * c0 * (weld:IsA("Motor6D") and weld.Transform or CFrame.identity) * c1:Inverse()
        end

        if not desired then
            return false
        end

        -- AssemblyRootPart can still be shared just after disabling a weld.
        -- Let the repaired binding settle instead of moving that whole assembly.
        if anchor and handle.AssemblyRootPart ~= nil
            and handle.AssemblyRootPart == anchor.AssemblyRootPart then
            return true, "intact assembly"
        end
        if not ownsPhysicalPart(handle) then
            return false, "accessory assembly is not network-owned"
        end
        return pcall(function()
            handle.CFrame = desired
            if anchor then
                handle.AssemblyLinearVelocity = anchor.AssemblyLinearVelocity
                handle.AssemblyAngularVelocity = anchor.AssemblyAngularVelocity
            end
        end)
    end

    local function captureAccessoryWeldBindings(character)
        table.clear(accessoryWeldBindings)
        for _, accessory in ipairs(character:GetChildren()) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                local weld = handle and handle:FindFirstChild("AccessoryWeld")
                if handle and handle:IsA("BasePart")
                    and weld and weld:IsA("JointInstance")
                then
                    accessoryWeldBindings[handle] = {
                        Part0 = weld.Part0,
                        Part1 = weld.Part1,
                        C0 = weld.C0,
                        C1 = weld.C1,
                        Enabled = weld.Enabled ~= false,
                        ClassName = weld.ClassName, Name = weld.Name,
                        Transform = weld:IsA("Motor6D") and weld.Transform or CFrame.identity,
                        AnchorName = weld.Part0 == handle and weld.Part1 and weld.Part1.Name
                            or weld.Part1 == handle and weld.Part0 and weld.Part0.Name,
                        HandleIsPart0 = weld.Part0 == handle,
                        RootPriority = handle.RootPriority, Massless = handle.Massless,
                    }
                end
            end
        end
        backend.AccessoryLifetime.Remember(character)
    end

    function backend.AccessoryLifetime.Remember(physical)
        local index = getPhysicalHeadIndex(physical)
        index.AccessoryRecords = index.AccessoryRecords or {}
        index.TrackedAccessories = index.TrackedAccessories or {}
        for _, source in ipairs(index.Children or {}) do
            if source:IsA("Accessory") and not index.AccessoryRecords[source] then
                local handle = source:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then
                    local record = {Source=source,Handle=handle,Name=source.Name,
                        Id=#index.TrackedAccessories+1,Repairs=0,ProxyRebuilds=0,
                        Binding=accessoryWeldBindings[handle]}
                    local cloned, template = pcall(function() return source:Clone() end)
                    if cloned then record.Template = template end
                    index.AccessoryRecords[source] = record
                    table.insert(index.TrackedAccessories, source)
                    index.Recovery = nil
                    for _, item in ipairs({{source,"SourceDestroyed"},{handle,"HandleDestroyed"}}) do
                        if item[1].Destroying then
                            table.insert(index.Connections,item[1].Destroying:Connect(function()
                                record[item[2]] = true
                                record.LastEvent = item[2]
                                record.Blocked = "original " .. (item[2]=="HandleDestroyed" and "Handle" or "Accessory") .. " destroyed; server replacement required"
                                index.Recovery = nil
                            end))
                        end
                    end
                end
            end
        end
        return index
    end

    function backend.AccessoryLifetime.BodyAnchorOffset(name)
        return Context.R15Body.Anchor(name)
    end

    function backend.AccessoryLifetime.RemapBodyEndpoint(joint, key, rig)
        local part = joint[key]
        local frame = key == "Part0" and "C0" or "C1"
        local exact=rig:FindFirstChild(part.Name)
        if exact then joint[key]=exact return end
        joint[frame] = backend.AccessoryLifetime.BodyAnchorOffset(part.Name) * joint[frame]
        joint[key] = rig:FindFirstChild(visibilityR15ToR6[part.Name] or part.Name)
    end

    function backend.AccessoryLifetime.RepairControllerBodyJoints(rig)
        -- Repair the cloned controller only. Upgraded R15 already has a full
        -- AnimationConstraint skeleton; a second Motor6D fights that skeleton.
        local links={{"HumanoidRootPart","LowerTorso","Root"},{"LowerTorso","UpperTorso","Waist"},{"UpperTorso","Head","Neck"}}
        for _,side in ipairs({"Left","Right"}) do
            for _,entry in ipairs({{"UpperTorso",side.."UpperArm",side.."Shoulder"},{side.."UpperArm",side.."LowerArm",side.."Elbow"},
                {side.."LowerArm",side.."Hand",side.."Wrist"},{"LowerTorso",side.."UpperLeg",side.."Hip"},
                {side.."UpperLeg",side.."LowerLeg",side.."Knee"},{side.."LowerLeg",side.."Foot",side.."Ankle"}}) do table.insert(links,entry) end
        end
        local existing,upgraded={},false
        for _,joint in ipairs(rig:GetDescendants()) do
            if Util.IsCharacterJoint(joint) then
                local p0,p1=Util.GetCharacterJointParts(joint)
                if p0 and p1 and p0.Parent==rig and p1.Parent==rig then
                    existing[p0]=existing[p0] or {}
                    existing[p0][p1]=joint
                    joint.Enabled=true
                    if joint.ClassName=="AnimationConstraint" then joint.IsKinematic=true upgraded=true end
                end
            end
        end
        for _,entry in ipairs(links) do
            local p0,p1=rig:FindFirstChild(entry[1]),rig:FindFirstChild(entry[2])
            if p0 and p1 and not (existing[p0] and existing[p0][p1]) then
                local a0=p0:FindFirstChild(entry[3].."RigAttachment")
                local a1=p1:FindFirstChild(entry[3].."RigAttachment")
                if a0 and a1 and a0:IsA("Attachment") and a1:IsA("Attachment") then
                    local joint=Instance.new(upgraded and "AnimationConstraint" or "Motor6D")
                    joint.Name=entry[3]
                    if upgraded then
                        joint.Attachment0,joint.Attachment1=a0,a1
                        joint.IsKinematic=true
                    else
                        joint.Part0,joint.Part1=p0,p1
                        joint.C0,joint.C1=a0.CFrame,a1.CFrame
                    end
                    joint.Parent=p1
                    existing[p0]=existing[p0] or {}
                    existing[p0][p1]=joint
                end
            end
        end
    end

    function backend.AccessoryLifetime.ConvertCloneToR6(clone, template)
        local rig
        local ok,reason=pcall(function()
            rig=template:Clone()
            local contents=clone:GetDescendants()
            local body,mapped,templateObjects={},{},{}
            for _,item in ipairs(rig:GetDescendants()) do templateObjects[item]=true end
            for _,part in ipairs(clone:GetChildren()) do
                if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                    body[part]=true
                    mapped[part]=rig:FindFirstChild(visibilityR15ToR6[part.Name] or part.Name)
                end
            end
            for name,value in pairs(clone:GetAttributes()) do rig:SetAttribute(name,value) end
            -- Keep the actual head mesh/face/bones, including its attachment graph.
            local head=clone:FindFirstChild("Head")
            if head and head:IsA("BasePart") then
                local dummy=rig:FindFirstChild("Head")
                for _,joint in ipairs(rig:GetDescendants()) do
                    if joint:IsA("JointInstance") then
                        if joint.Part0==dummy then joint.Part0=head end
                        if joint.Part1==dummy then joint.Part1=head end
                    end
                end
                head.Parent=rig
                mapped[head]=head
                if dummy then dummy:Destroy() end
            end
            -- R6 body geometry and Humanoid height come from the working R6 rig;
            -- carrying R15 HipHeight into it raises the locomotion root off the floor.
            local colors={Torso="UpperTorso",["Left Arm"]="LeftUpperArm",["Right Arm"]="RightUpperArm",
                ["Left Leg"]="LeftUpperLeg",["Right Leg"]="RightUpperLeg"}
            for targetName,sourceName in pairs(colors) do
                local source=clone:FindFirstChild(sourceName) or clone:FindFirstChild(targetName)
                local target=rig:FindFirstChild(targetName)
                if source and target then
                    target.Color,target.Material,target.Reflectance=source.Color,source.Material,source.Reflectance
                end
            end
            -- Retire only the source skeleton. Preserve body-parented accessory
            -- motors before moving children, so Clone's object references stay valid.
            for _,item in ipairs(contents) do
                if item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("NoCollisionConstraint")
                    or item:IsA("Constraint") then
                    local p0,p1
                    if item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("NoCollisionConstraint") then
                        p0,p1=item.Part0,item.Part1
                    else
                        local a0,a1=item.Attachment0,item.Attachment1
                        p0=a0 and a0:FindFirstAncestorWhichIsA("BasePart")
                        p1=a1 and a1:FindFirstAncestorWhichIsA("BasePart")
                    end
                    if body[p0] and body[p1] then item:Destroy()
                    elseif item:IsA("JointInstance") then
                        for _,key in ipairs({"Part0","Part1"}) do
                            local part=item[key]
                            if mapped[part] and mapped[part]~=part then
                                local frame=key=="Part0" and "C0" or "C1"
                                item[frame]=backend.AccessoryLifetime.BodyAnchorOffset(part.Name)*item[frame]
                                item[key]=mapped[part]
                            end
                        end
                    elseif item:IsA("WeldConstraint") or item:IsA("NoCollisionConstraint") then
                        item.Part0,item.Part1=mapped[p0] or p0,mapped[p1] or p1
                    end
                elseif item:IsA("ObjectValue") and mapped[item.Value] then
                    item.Value=mapped[item.Value]
                end
            end
            for source,target in pairs(mapped) do
                if source~=target then
                    local basis=backend.AccessoryLifetime.BodyAnchorOffset(source.Name)
                    for name,value in pairs(source:GetAttributes()) do
                        if target:GetAttribute(name)==nil then target:SetAttribute(name,value) end
                    end
                    for _,child in ipairs(source:GetChildren()) do
                        if not target:IsA("MeshPart") and (child:IsA("BaseWrap")
                            or child:IsA("SurfaceAppearance") or child:IsA("FaceControls")) then
                            -- These describe the discarded R15 mesh, and cannot
                            -- follow it onto a plain R6 Part. This is a private
                            -- clone; the visible avatar's mesh data stays intact.
                            child:Destroy()
                        else
                            if child:IsA("Attachment") then
                                local existing=target:FindFirstChild(child.Name)
                                if existing and templateObjects[existing] and existing:IsA("Attachment") then existing:Destroy() end
                                child.CFrame=basis*child.CFrame
                            end
                            child.Parent=target
                        end
                    end
                end
            end
            local humanoid=rig:FindFirstChildOfClass("Humanoid")
            local original=clone:FindFirstChildOfClass("Humanoid")
            if original then
                for name,value in pairs(original:GetAttributes()) do humanoid:SetAttribute(name,value) end
                for _,name in ipairs({"WalkSpeed","JumpPower","JumpHeight","UseJumpPower","AutoJumpEnabled",
                    "MaxSlopeAngle","DisplayName","CameraOffset","DisplayDistanceType","NameDisplayDistance",
                    "HealthDisplayDistance","HealthDisplayType"}) do humanoid[name]=original[name] end
                for _,child in ipairs(original:GetChildren()) do
                    local existing=humanoid:FindFirstChild(child.Name)
                    if existing then existing:Destroy() end
                    child.Parent=humanoid
                end
            end
            -- Clothing, BodyColors, attributes, values, folders, animations, effects
            -- and the exact accessory objects all survive the skeleton conversion.
            for _,child in ipairs(clone:GetChildren()) do
                if not body[child] and child~=original then
                    local existing=rig:FindFirstChild(child.Name)
                    if existing and templateObjects[existing] and not existing:IsA("BasePart") and not existing:IsA("Humanoid") then existing:Destroy() end
                    child.Parent=rig
                end
            end
            rig.PrimaryPart=rig:FindFirstChild("HumanoidRootPart")
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
            humanoid.Health=math.max(1,humanoid.MaxHealth or 100)
            humanoid.BreakJointsOnDeath,humanoid.RequiresNeck=false,false
            humanoid.EvaluateStateMachine,humanoid.AutoRotate=true,true
            humanoid.PlatformStand,humanoid.Sit,humanoid.Jump=false,false,false
        end)
        if not ok then
            if rig then pcall(function() rig:Destroy() end) end
            pcall(function() clone:Destroy() end)
            error(reason,0)
        end
        clone:Destroy()
        return rig
    end

    function backend.AccessoryLifetime.CloneController(character, template, nativeR6)
        -- Clone the whole graph once: Clone remaps even accessory motors parented
        -- under a body part, and duplicate accessory names are not identities.
        local changed, sources, clone, targets, jointSources, jointTargets = {}, {}, nil, {}, {}, {}
        local marker = "_UhhhhhhControllerCloneId"
        local jointMarker = "_UhhhhhhControllerJointCloneId"
        local ok, reason = pcall(function()
            local items = character:GetDescendants()
            table.insert(items, character)
            for _, item in ipairs(items) do
                changed[item] = {Archivable = item.Archivable}
                item.Archivable = true
                if item:IsA("Motor6D") then
                    local id=#jointSources+1 jointSources[id]=item
                    changed[item].JointMarker=item:GetAttribute(jointMarker) changed[item].JointMarked=true
                    item:SetAttribute(jointMarker,id)
                end
                if item:IsA("Accessory") and item.Parent == character then
                    local id = #sources + 1
                    sources[id] = item
                    changed[item].Marker = item:GetAttribute(marker)
                    changed[item].Marked = true
                    item:SetAttribute(marker, id)
                end
            end
            clone = character:Clone()
            assert(clone, "avatar controller clone unavailable")
            for _,item in ipairs(clone:GetDescendants()) do
                if item:IsA("Motor6D") then
                    local id=item:GetAttribute(jointMarker) item:SetAttribute(jointMarker,nil)
                    if jointSources[id] then jointTargets[jointSources[id]]=item end
                end
            end
            for _, accessory in ipairs(clone:GetChildren()) do
                if accessory:IsA("Accessory") then
                    local id = accessory:GetAttribute(marker)
                    accessory:SetAttribute(marker, nil)
                    if sources[id] then targets[sources[id]] = accessory end
                end
            end
        end)
        for item, saved in pairs(changed) do
            pcall(function()
                item.Archivable = saved.Archivable
                if saved.JointMarked then item:SetAttribute(jointMarker,saved.JointMarker) end
                if saved.Marked then item:SetAttribute(marker, saved.Marker) end
            end)
        end
        if not ok then
            if clone then clone:Destroy() end
            error(reason)
        end
        local rig = nativeR6 and clone or backend.AccessoryLifetime.ConvertCloneToR6(clone,template)
        for _, item in ipairs(rig:GetDescendants()) do
            if item:IsA("Script") or item:IsA("LocalScript") or item:IsA("Tool")
                or item.Name == "OwnershipCheck" or item.Name == "FakeHats"
                or item:IsA("BodyMover") or item:IsA("AlignPosition") or item:IsA("AlignOrientation")
                or item:IsA("LinearVelocity") or item:IsA("AngularVelocity")
                or item:IsA("VectorForce") or item:IsA("Torque") then
                item:Destroy()
            elseif item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("NoCollisionConstraint") then
                local p0,p1=item.Part0,item.Part1
                if (p0 and not p0:IsDescendantOf(rig)) or (p1 and not p1:IsDescendantOf(rig)) then item:Destroy() end
            elseif item:IsA("BasePart") then
                item.Transparency, item.LocalTransparencyModifier = 1, 0
                item.Anchored, item.CanCollide, item.CanTouch, item.CanQuery = false, false, false, false
                item.AssemblyLinearVelocity, item.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
                -- The private controller must select its own HRP, even when a
                -- source accessory/corpse carried an elevated root priority.
                local accessory=item:FindFirstAncestorOfClass("Accessory")
                item.RootPriority=item.Name=="HumanoidRootPart" and item.Parent==rig and 127 or accessory and -127 or 0
                if accessory then item.Massless=true end
                if item.Parent==rig then item.Massless=false end
            elseif item:IsA("Constraint") then
                local a0,a1=item.Attachment0,item.Attachment1
                local p0=a0 and a0:FindFirstAncestorWhichIsA("BasePart")
                local p1=a1 and a1:FindFirstAncestorWhichIsA("BasePart")
                if (p0 and not p0:IsDescendantOf(rig)) or (p1 and not p1:IsDescendantOf(rig))
                    or (item.ClassName~="AnimationConstraint" and p0 and p1 and p0.Parent==rig and p1.Parent==rig) then
                    item:Destroy() -- a copied corpse/ragdoll must not fight the live animation skeleton
                end
            elseif item:IsA("Decal") then item.Transparency = 1 end
        end
        for _, joint in ipairs(rig:GetDescendants()) do
            if joint:IsA("JointInstance") and joint.Parent and joint.Parent:IsA("BasePart") and joint.Parent.Parent == rig then
                local p0, p1 = joint.Part0, joint.Part1
                if (p0 and p0:FindFirstAncestorOfClass("Accessory")) or (p1 and p1:FindFirstAncestorOfClass("Accessory")) then
                    joint:SetAttribute("_UhhhhhhGelatekProxyJoint", true)
                end
            end
        end
        if nativeR6 then
            -- A PD avatar may already have a dead Humanoid or missing body joints.
            -- Use a live controller Humanoid, without discarding avatar content.
            local old = rig:FindFirstChildOfClass("Humanoid")
            local r15=old and old.RigType==Enum.HumanoidRigType.R15
            local humanoid = (r15 and old or template:FindFirstChildOfClass("Humanoid")):Clone()
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
            humanoid.Health=math.max(1,humanoid.MaxHealth or 100)
            humanoid.BreakJointsOnDeath=false
            -- Copy the avatar graph, then give the controller live locomotion
            -- instead of inheriting the follower/dead shell's physics state.
            humanoid.EvaluateStateMachine=true
            humanoid.PlatformStand,humanoid.Sit,humanoid.Jump=false,false,false
            humanoid.AutoRotate=true
            local description = old and old:FindFirstChildOfClass("HumanoidDescription")
            if description then
                local duplicate=humanoid:FindFirstChildOfClass("HumanoidDescription")
                if duplicate then duplicate:Destroy() end
                description.Parent = humanoid
            end
            if old then old:Destroy() end
            humanoid.Parent = rig
            if r15 then
                backend.AccessoryLifetime.RepairControllerBodyJoints(rig)
            end
            for _, joint in ipairs(r15 and {} or template:GetDescendants()) do
                if joint:IsA("Motor6D") and joint.Part0 and joint.Part1 then
                    local p0, p1 = rig:FindFirstChild(joint.Part0.Name), rig:FindFirstChild(joint.Part1.Name)
                    local found = false
                    for _, existing in ipairs(rig:GetDescendants()) do
                        if existing:IsA("Motor6D") and existing.Part0 == p0 and existing.Part1 == p1 then found = true break end
                    end
                    if p0 and p1 and not found then
                        local added = joint:Clone()
                        added.Part0, added.Part1, added.Parent = p0, p1, p0
                    end
                end
            end
        end
        return rig, targets, jointTargets
    end

    function backend.AccessoryLifetime.CloneAccessoryTargets(character, rig)
        local copy, targets = backend.AccessoryLifetime.CloneController(character, rig, true)
        for _, joint in ipairs(rig:GetDescendants()) do
            if joint:GetAttribute("_UhhhhhhGelatekProxyJoint") == true then joint:Destroy() end
        end
        for _, joint in ipairs(copy:GetDescendants()) do
            if joint:IsA("JointInstance") then
                local p0, p1 = joint.Part0, joint.Part1
                local accessory = p0 and p0:FindFirstAncestorOfClass("Accessory")
                    or p1 and p1:FindFirstAncestorOfClass("Accessory")
                if accessory then
                    local parent = joint.Parent
                    for _, key in ipairs({"Part0", "Part1"}) do
                        local part = joint[key]
                        if part and part.Parent == copy then
                            backend.AccessoryLifetime.RemapBodyEndpoint(joint, key, rig)
                        end
                    end
                    if parent and parent.Parent == copy then
                        joint.Parent = rig:FindFirstChild(visibilityR15ToR6[parent.Name] or parent.Name) or accessory:FindFirstChild("Handle")
                        joint:SetAttribute("_UhhhhhhGelatekProxyJoint", true)
                    end
                end
            end
        end
        for _, accessory in pairs(targets) do accessory.Parent = rig end
        copy:Destroy()
        return targets
    end

    function backend.AccessoryLifetime.ControllerIndex(rig)
        if not rig then return nil end
        local index = physicalIndex.ControllerJoints
        if not index or index.Rig ~= rig then
            if index then for _, connection in ipairs(index.Connections) do connection:Disconnect() end end
            index = {Rig = rig, Dirty = true, Connections = {}}
            physicalIndex.ControllerJoints = index
            for _, name in ipairs({"DescendantAdded", "DescendantRemoving"}) do
                if rig[name] then table.insert(index.Connections, rig[name]:Connect(function(item)
                    if item:IsA("JointInstance") or item.ClassName=="AnimationConstraint"
                        or item:IsA("BasePart") and item.Parent==rig then index.Dirty = true end
                end)) end
            end
        end
        if index.Dirty then
            index.Revision = (index.Revision or 0) + 1
            index.Joints, index.BodyJoints, index.Motors, index.HandleJoints = {}, {}, {}, {}
            for _, joint in ipairs(rig:GetDescendants()) do
                if joint:IsA("JointInstance") or joint.ClassName=="AnimationConstraint" then
                    table.insert(index.Joints, joint)
                    if joint:IsA("Motor6D") then table.insert(index.Motors,joint) end
                    local p0,p1 = Util.GetCharacterJointParts(joint)
                    if p0 and p1 then
                        if p0.Parent==rig and p1.Parent==rig then table.insert(index.BodyJoints,joint) end
                        for _,part in ipairs({p0,p1}) do
                            index.HandleJoints[part] = index.HandleJoints[part] or {}
                            table.insert(index.HandleJoints[part],joint)
                        end
                    end
                end
            end
            index.Dirty = false
        end
        return index
    end

    function backend.AccessoryLifetime.ControllerBodyPoses(rig, live)
        local poses = {}
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        local index = backend.AccessoryLifetime.ControllerIndex(rig)
        if not root or not index then return poses end
        -- Disabled motors mean the moveset owns world-space parts (ragdoll/VR).
        -- Their solver results must be read live, never replayed as root offsets.
        local independent=false
        local humanoid=rig:FindFirstChildOfClass("Humanoid")
        if humanoid then
            local ok,state=pcall(humanoid.GetState,humanoid)
            local name=ok and state and state.Name
            independent=humanoid.EvaluateStateMachine==false or humanoid.PlatformStand==true
                or name=="Physics" or name=="Ragdoll" or name=="FallingDown" or name=="PlatformStanding"
        end
        for _,joint in ipairs(index.BodyJoints) do
            local p0,p1=Util.GetCharacterJointParts(joint)
            if joint.Enabled==false or not p0 or not p1 or p0.Parent~=rig or p1.Parent~=rig
                or joint.ClassName=="AnimationConstraint" and joint.IsKinematic==false then independent=true break end
        end
        if independent then
            -- Physics/VR owns world poses, even if some motors remain enabled.
            for _,part in ipairs(rig:GetChildren()) do
                if part:IsA("BasePart") then poses[part]=part.CFrame end
            end
            return poses
        end
        live=live or independent
        local committed = backend.ControllerPoseSample
        if not live and committed and committed.Rig == rig and committed.Root == root
            and os.clock() >= committed.At and os.clock() - committed.At < .25
            and committed.Revision == index.Revision then
            if committed.RootFrame == root.CFrame and committed.Poses then return committed.Poses end
            -- Every physics/render reader consumes the same completed animation
            -- pose. Rebase it onto the moving root, never pin it in world space.
            for part, offset in pairs(committed.Offsets) do
                if part.Parent == rig then poses[part] = root.CFrame * offset end
            end
            committed.RootFrame,committed.Poses = root.CFrame,poses
            return poses
        end
        local phase=environment().UhhhhhhTBZGelatekPosePhaseId
        local batch=backend.FallbackBodyPoseBatch
        if not live and phase and batch and batch.Phase==phase and batch.Rig==rig
            and batch.RootFrame==root.CFrame and batch.Revision==index.Revision then return batch.Poses end
        poses[root] = root.CFrame
        -- Transform is applied by Roblox in a later batch. Read the live joint
        -- graph now, rather than combining a fresh hat motor with an old Head.
        for _ = 1, 16 do
            local changed = false
            for _, joint in ipairs(index.BodyJoints) do
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if joint.Parent and joint.Enabled ~= false and p0 and p1 and p0 ~= p1
                    and p0.Parent == rig and p1.Parent == rig then
                    local c0,c1=Util.GetCharacterJointFrames(joint)
                    local transform = Util.IsCharacterJoint(joint) and joint.Transform or CFrame.identity
                    if poses[p0] and not poses[p1] then
                        poses[p1] = poses[p0] * c0 * transform * c1:Inverse()
                        changed = true
                    elseif poses[p1] and not poses[p0] then
                        poses[p0] = poses[p1] * c1 * (c0 * transform):Inverse()
                        changed = true
                    end
                end
            end
            if not changed then break end
        end
        for _,part in ipairs(rig:GetChildren()) do
            if part:IsA("BasePart") and not poses[part] then poses[part]=part.CFrame end
        end
        if not live and phase then backend.FallbackBodyPoseBatch={Phase=phase,Rig=rig,
            RootFrame=root.CFrame,Revision=index.Revision,Poses=poses} end
        return poses
    end

    function backend.AccessoryLifetime.RefreshR15Groups(physical)
        local state=backend.R15LinkState
        if not state or state.Physical~=physical or not physical.Parent then return end
        local index=getPhysicalHeadIndex(physical)
        if state.Revision==index.Revision then return end
        state.Repairs=(state.Repairs or 0)+Context.R15Body.RepairLinks(physical,state.Links,index.Joints,Util)
        state.Revision=getPhysicalHeadIndex(physical).Revision
    end

    function backend.AccessoryLifetime.CommitControllerPose(rig)
        backend.AccessoryLifetime.RefreshR15Groups(backend.RealCharacter)
        local root = rig and rig:FindFirstChild("HumanoidRootPart")
        if not root then backend.ControllerPoseSample = nil return end
        local poses = backend.AccessoryLifetime.ControllerBodyPoses(rig, true)
        local offsets = {}
        for part, pose in pairs(poses) do offsets[part] = root.CFrame:ToObjectSpace(pose) end
        local index = backend.AccessoryLifetime.ControllerIndex(rig)
        backend.FallbackBodyPoseBatch=nil
        backend.ControllerPoseSample = {Rig=rig, Root=root, Offsets=offsets,
            Revision=index and index.Revision, At=os.clock(), RootFrame=root.CFrame, Poses=poses,
            Serial=(backend.ControllerPoseSample and backend.ControllerPoseSample.Serial or 0)+1}
    end

    function backend.AccessoryLifetime.ControllerBodyPose(part, poses)
        if not part then return nil end
        poses = poses or backend.AccessoryLifetime.ControllerBodyPoses(part.Parent)
        return poses[part] or part.CFrame
    end

    function backend.AccessoryLifetime.ResolveAnimationPose(physicalPart,controllerPart,fallback,bodyPoses)
        if not physicalPart or physicalPart.Parent~=backend.RealCharacter
            or not backend.RealCharacter:FindFirstChild("UpperTorso")
            or not controllerPart or controllerPart.Parent~=backend.Rig then return fallback end
        local bridge=Reanimate.R15Animation
        local state=bridge and bridge.States[backend.Rig]
        if not state or not state.Active then return fallback end
        local sample=backend.ControllerPoseSample
        if not bodyPoses and sample and sample.Rig==backend.Rig and sample.Root
            and sample.RootFrame==sample.Root.CFrame and os.clock()-sample.At>=0 and os.clock()-sample.At<.25 then
            bodyPoses=sample.Poses
        end
        local pose=backend.AccessoryLifetime.ControllerBodyPose(controllerPart,bodyPoses)
        local resolved=bridge and bridge.PartPose(backend.Rig,physicalPart.Name,pose)
        return resolved or fallback,resolved~=nil
    end

    function backend.AccessoryLifetime.ControllerJoint(handle)
        local index = backend.AccessoryLifetime.ControllerIndex(handle and handle:FindFirstAncestorOfClass("Model"))
        if not index then return nil end
        local best, bestAnchor, bestScore
        for _, joint in ipairs(index.HandleJoints[handle] or {}) do
            if joint.Parent and joint.Enabled ~= false then
                local other = joint.Part0 == handle and joint.Part1 or joint.Part1 == handle and joint.Part0
                if other and other ~= handle and other.Parent then
                    -- A chain link also touches its parent's Handle. Prefer the
                    -- body anchor, then the motor's driven (Part1) endpoint.
                    local score = (joint:IsA("Motor6D") and 1000 or 0)
                        + (other:FindFirstAncestorOfClass("Accessory") and 0 or 100)
                        + (joint.Part1 == handle and 10 or 0)
                    if not bestScore or score > bestScore then best, bestAnchor, bestScore = joint, other, score end
                end
            end
        end
        return best, bestAnchor
    end

    function backend.AccessoryLifetime.ControllerPose(handle, visiting, depth, bodyPoses)
        visiting, depth = visiting or {}, depth or 0
        if visiting[handle] or depth >= 16 then return nil end
        visiting[handle] = true
        local joint, anchor = backend.AccessoryLifetime.ControllerJoint(handle)
        if not joint then visiting[handle] = nil return handle.CFrame end
        bodyPoses = bodyPoses or backend.AccessoryLifetime.ControllerBodyPoses(handle:FindFirstAncestorOfClass("Model"))
        local anchorPose = backend.AccessoryLifetime.ControllerBodyPose(anchor, bodyPoses)
        if anchor:FindFirstAncestorOfClass("Accessory") then
            anchorPose = backend.AccessoryLifetime.ControllerPose(anchor, visiting, depth + 1, bodyPoses)
        end
        if not anchorPose then visiting[handle] = nil return nil end
        local transform = joint:IsA("Motor6D") and joint.Transform or CFrame.identity
        local pose = joint.Part1 == handle
            and (anchorPose * joint.C0 * transform * joint.C1:Inverse())
            or (anchorPose * joint.C1 * (joint.C0 * transform):Inverse())
        visiting[handle] = nil
        return pose
    end

    function backend.AccessoryLifetime.MakeProxy(record, rig)
        if not record.Template then return nil, "no saved controller accessory template" end
        local proxy = record.Template:Clone()
        if not proxy then return nil, "controller accessory clone unavailable" end
        proxy.Name = record.Source.Name
        local handle = proxy:FindFirstChild("Handle")
        if not handle then proxy:Destroy() return nil, "saved controller template has no Handle" end
        for _, item in ipairs(proxy:GetDescendants()) do
            if item.Name == "OwnershipCheck" or item:IsA("BodyMover")
                or item:IsA("AlignPosition") or item:IsA("AlignOrientation")
                or item:IsA("LinearVelocity") or item:IsA("AngularVelocity") then item:Destroy()
            elseif item:IsA("BasePart") then
                item.Transparency,item.LocalTransparencyModifier = 1,0
                item.Anchored,item.CanCollide,item.CanTouch,item.CanQuery,item.Massless = false,false,false,false,true
            end
        end
        local anchor, c0, c1, reversed
        local saved = record.TargetWeld or record.Binding
        if saved and saved.AnchorName then
            anchor = rig:FindFirstChild(saved.AnchorName) or rig:FindFirstChild(visibilityR15ToR6[saved.AnchorName] or saved.AnchorName)
            c0,c1,reversed = saved.C0,saved.C1,saved.HandleIsPart0 == false
            if visibilityR15ToR6[saved.AnchorName] and anchor.Name ~= saved.AnchorName then
                local offset = scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset(saved.AnchorName))
                if reversed then c0 = offset * c0 else c1 = offset * c1 end
            end
        end
        if not anchor then
            local attachment = handle:FindFirstChildOfClass("Attachment")
            if attachment then
                for _, bodyPart in ipairs(rig:GetChildren()) do
                    if bodyPart:IsA("BasePart") then
                        local targetAttachment = bodyPart:FindFirstChild(attachment.Name)
                        if targetAttachment and targetAttachment:IsA("Attachment") then
                            anchor,c0,c1 = bodyPart,attachment.CFrame,targetAttachment.CFrame
                            break
                        end
                    end
                end
            end
        end
        if not anchor or not pdHeadFollower.FiniteCFrame(c0) or not pdHeadFollower.FiniteCFrame(c1) then
            proxy:Destroy()
            return nil, "controller accessory anchor unavailable"
        end
        local weld = handle:FindFirstChild("AccessoryWeld")
        local class = saved and saved.ClassName == "Motor6D" and "Motor6D" or "Weld"
        if not weld or not weld:IsA(class) then
            if weld then weld:Destroy() end
            weld=Instance.new(class) weld.Name=saved and saved.Name or "AccessoryWeld"
        end
        weld.C0,weld.C1 = c0,c1
        if class == "Motor6D" then weld.Transform = saved.Transform or CFrame.identity end
        weld.Part0,weld.Part1 = reversed and anchor or handle,reversed and handle or anchor
        weld.Enabled = true
        weld.Parent = handle
        local transform = class == "Motor6D" and weld.Transform or CFrame.identity
        handle.CFrame = reversed and (anchor.CFrame*c0*transform*c1:Inverse()) or (anchor.CFrame*c1*(c0*transform):Inverse())
        if record.TargetSize then handle.Size=record.TargetSize end
        proxy:SetAttribute("_UhhhhhhGelatekProxyAccessory",true)
        proxy:SetAttribute("_UhhhhhhGelatekSourceName",record.Source.Name)
        proxy.Parent = rig
        if controllerSnapshot and controllerSnapshot.Rig==rig then ControllerReset.CaptureAccessory(controllerSnapshot,record.Source,proxy) end
        return proxy
    end

    function backend.AccessoryLifetime.Refresh(rig, physical)
        if not backend.Running or rebindInProgress or rig ~= backend.Rig
            or not rig or not rig.Parent or physical ~= backend.RealCharacter then return end
        local index = backend.AccessoryLifetime.Remember(physical)
        local global = environment()
        local targets = global.UhhhhhhTBZGelatekAccessoryTargets
        if type(targets) ~= "table" then targets={} global.UhhhhhhTBZGelatekAccessoryTargets=targets index.Recovery=nil end
        for source, record in pairs(index.AccessoryRecords) do
            local handle = record.Handle
            if record.SourceDestroyed or record.HandleDestroyed then
                local state=accessoryRecoveryStates[handle]
                if state then state.LastBlockedReason=record.Blocked end
                continue
            end
            -- The physical source is an identity, not a GetChildren() result.
            -- Recover the SAME original objects if they were merely unparented;
            -- a Destroying event is terminal and never replaced with a local hat.
            if not source.Parent or handle.Parent ~= source then
                if record.RetryAt and os.clock()<record.RetryAt then continue end
                local ok, reason=pcall(function()
                    if not source.Parent then source.Parent=physical end
                    if handle.Parent~=source then handle.Parent=source end
                end)
                if not ok then
                    record.Blocked="original accessory reparent failed: " .. tostring(reason)
                    record.RetryAt=os.clock()+1
                    continue
                end
                record.Repairs+=1 record.RetryAt=nil record.LastEvent="original parent restored"
                index.Recovery=nil
            end
            local proxy=targets[source]
            local controller=proxy and proxy:FindFirstChild("Handle")
            if not proxy or not proxy.Parent or not controller or not controller.Parent then
                if record.RetryAt and os.clock()<record.RetryAt then continue end
                -- Restore a still-live target-map binding before allocating a
                -- new invisible controller target. Physical originals never clone.
                local retained=record.Controller
                if retained and retained.Parent and retained.Parent.Parent==rig then
                    proxy,controller=retained.Parent,retained
                else
                    local ok, made, reason=pcall(backend.AccessoryLifetime.MakeProxy,record,rig)
                    if not ok or not made then
                        record.Blocked="controller target rebuild failed: " .. tostring(ok and reason or made)
                        record.RetryAt=os.clock()+1
                        continue
                    end
                    proxy,controller=made,made:FindFirstChild("Handle")
                    record.ProxyRebuilds+=1 record.LastEvent="controller proxy rebuilt"
                end
                targets[source]=proxy record.RetryAt=nil index.Recovery=nil
            end
            if proxy.Parent ~= rig then proxy.Parent=rig index.Recovery=nil end
            if record.Controller ~= controller then
                record.Controller=controller
                for _, child in ipairs(proxy:GetDescendants()) do
                    if child.Name=="OwnershipCheck" then child:Destroy() end
                end
                if controllerSnapshot and controllerSnapshot.Rig==rig then ControllerReset.CaptureAccessory(controllerSnapshot,source,proxy) end
            end
            local weld=backend.AccessoryLifetime.ControllerJoint(controller)
            if weld and weld:IsA("JointInstance") then
                local anchor=weld.Part0==controller and weld.Part1 or weld.Part0
                if anchor and anchor.Parent==rig then
                    local saved=record.TargetWeld or {}
                    saved.C0,saved.C1,saved.AnchorName,saved.HandleIsPart0=weld.C0,weld.C1,anchor.Name,weld.Part0==controller
                    saved.ClassName,saved.Name = weld.ClassName,weld.Name
                    saved.Transform = weld:IsA("Motor6D") and weld.Transform or CFrame.identity
                    record.TargetWeld=saved
                    -- Keep the initial controller mount separately from live
                    -- module edits, so native R15 offsets can be rebased once.
                    if not record.TargetBaseline then record.TargetBaseline=table.clone(saved) end
                end
            end
            record.TargetSize=controller.Size
            record.Blocked=nil
            backend.RefreshOwnershipWarning(handle)
        end
    end

    function backend.AccessoryLifetime.DetachReason(handle)
        if options.BreakAccessoryWelds == true then return "explicit accessory detachment" end
        if backend.EffectivePermanentDeath == true then
            local physical=backend.RealCharacter or originalCharacter
            local humanoid=physical and physical:FindFirstChildOfClass("Humanoid")
            if environment().UhhhhhhTBZGelatekPermaReady==true or (humanoid and humanoid.Health<=0) then
                -- Death may remove the server weld while a retained local weld
                -- still renders correctly. Submit the ORIGINAL handle's pose;
                -- a local joint cannot establish its observer-side attachment.
                return "PD original-handle transport"
            end
        end
        return nil
    end
    local function shouldDetachHeadAccessory(handle)
        -- Intent must not flip when ownership changes. The writer gates the
        -- first detach and each physical sample on native ownership instead.
        return backend.AccessoryLifetime.DetachReason(handle)~=nil
    end

    function backend.AccessoryLifetime.HeadHideReady(physical, head, requested)
        backend.HeadHideAccessoryBlockedReason = nil
        backend.HeadHideAccessoryRestorePending = false
        if not requested then return false end
        local resolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
        if type(resolver) ~= "function" then return true end
        local targets = environment().UhhhhhhTBZGelatekAccessoryTargets or {}
        local index = getPhysicalHeadIndex(physical)
        local waiting
        for handle, binding in pairs(accessoryWeldBindings) do
            local ok, keep = pcall(resolver, handle, nil)
            if handle.Parent and binding.AnchorName == "Head" and ok and keep == true then
                local proxy = targets[handle.Parent]
                local controller = proxy and proxy.Parent and proxy:FindFirstChild("Handle")
                local reason
                if not ownsPhysicalPart(head) or not ownsPhysicalPart(handle) then
                    reason = "kept head accessory is not network-owned"
                elseif not controller or not controller.Parent then
                    reason = "kept head accessory target missing"
                elseif backend.HeadHideAccessoryRetryAt and os.clock() < backend.HeadHideAccessoryRetryAt then
                    reason = "waiting to retry kept head accessories"
                end
                if reason then
                    backend.HeadHideAccessoryBlockedReason = reason
                    backend.HeadHideAccessoryRestorePending = true
                    return false
                end
                local root = handle.AssemblyRootPart
                for _, part in ipairs(index.BodyParts) do
                    if not root or part.AssemblyRootPart == root then
                        waiting = "waiting for kept head accessory assembly separation"
                        break
                    end
                end
            end
        end
        backend.HeadHideAccessoryBlockedReason = waiting
        return waiting == nil
    end

    function backend.AccessoryLifetime.RollbackHeadHide()
        for handle, binding in pairs(accessoryWeldBindings) do
            if handle.Parent and binding.AnchorName == "Head" then
                if shouldDetachHeadAccessory(handle) then continue end
                local state = accessoryRecoveryStates[handle]
                -- Explicit non-PD all-break remains the torso workaround. Never
                -- fabricate its destroyed original weld or attach it back here.
                if state and state.Weld and state.Weld.Parent then
                    backend.AccessoryLifetime.RestoreManaged(handle, state)
                else
                    local weld = handle:FindFirstChild("AccessoryWeld")
                    if weld and weld:IsA("JointInstance") then
                        weld.Enabled = false
                        weld.Part0, weld.Part1, weld.C0, weld.C1 = binding.Part0, binding.Part1, binding.C0, binding.C1
                        if binding.Enabled then snapAccessoryHandleToWeld(handle, weld) end
                        weld.Enabled = binding.Enabled
                    end
                end
            end
        end
        if not backend.HeadHideAccessoryRetryAt or os.clock() >= backend.HeadHideAccessoryRetryAt then
            backend.HeadHideAccessoryRetryAt = os.clock() + 0.25
        end
    end

    local function repairAccessoryWeldBindings()
        if not backend.Running or rebindInProgress
            or options.BreakAccessoryWelds == true
        then
            return
        end
        backend.AccessoryWeldRepairError = nil
        local physical = backend.RealCharacter or originalCharacter
        -- Capture late-added accessories' actual weld offsets as well.
        if physical and physical.Parent then
            for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
                if accessory:IsA("Accessory") then
                    local handle = accessory:FindFirstChild("Handle")
                    local weld = handle and handle:FindFirstChild("AccessoryWeld")
                    if handle and not accessoryWeldBindings[handle]
                        and weld and weld:IsA("JointInstance")
                    then
                        local anchor = weld.Part0 == handle and weld.Part1
                            or weld.Part1 == handle and weld.Part0
                        if anchor and anchor.Parent == physical then
                            accessoryWeldBindings[handle] = {
                                Part0 = weld.Part0, Part1 = weld.Part1,
                                C0 = weld.C0, C1 = weld.C1,
                                Enabled = weld.Enabled ~= false,
                                ClassName = weld.ClassName, Name = weld.Name,
                                Transform = weld:IsA("Motor6D") and weld.Transform or CFrame.identity,
                                AnchorName = anchor.Name,
                                HandleIsPart0 = weld.Part0 == handle,
                                RootPriority = handle.RootPriority, Massless = handle.Massless,
                            }
                        end
                    end
                end
            end
        end
        for handle, binding in pairs(accessoryWeldBindings) do
            local ok, reason = pcall(function()
            if shouldDetachHeadAccessory(handle) then return end
            if accessoryRecoveryStates[handle]
                and accessoryRecoveryStates[handle].Managed then return end
            if physical and physical.Parent and binding.AnchorName then
                local anchor = binding.HandleIsPart0 and binding.Part1 or binding.Part0
                if not anchor or not anchor.Parent then
                    local replacement = physical:FindFirstChild(binding.AnchorName)
                    if replacement and replacement:IsA("BasePart") then
                        if binding.HandleIsPart0 then binding.Part1 = replacement
                        else binding.Part0 = replacement end
                    end
                end
            end
            if handle.Parent and binding.Part0 and binding.Part0.Parent
                and binding.Part1 and binding.Part1.Parent
            then
                local hideResolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
                if type(hideResolver) == "function" then
                    local ok, hidden = pcall(hideResolver, handle, nil)
                    if ok and hidden == true then return end
                end
                handle.Massless = true
                handle.RootPriority = -127
                local weld = handle:FindFirstChild("AccessoryWeld")
                if weld and not weld:IsA("JointInstance") then
                    -- Do not let a same-name non-joint prevent restoration.
                    weld.Name = "AccessoryWeld_Unused"
                    weld = nil
                end
                if not weld then
                    -- A local replacement Weld is not proof that the server
                    -- still has that binding. A genuinely detached original
                    -- must stay on the core owned-handle transport instead.
                    return
                end
                -- The previous repair only handled a MISSING weld. A disabled
                -- or reparented existing weld silently let the Handle fall away.
                if weld.Part0 ~= binding.Part0 or weld.Part1 ~= binding.Part1
                    or weld.C0 ~= binding.C0 or weld.C1 ~= binding.C1
                    or weld.Enabled ~= binding.Enabled then
                    weld.Enabled = false
                    weld.Part0, weld.Part1 = binding.Part0, binding.Part1
                    weld.C0, weld.C1 = binding.C0, binding.C1
                    snapAccessoryHandleToWeld(handle, weld)
                    weld.Enabled = binding.Enabled
                end
            end
            end)
            if not ok then backend.AccessoryWeldRepairError = tostring(reason) end
        end
    end

    local function updateAccessoryBodyHideWelds()
        if not backend.Running or rebindInProgress then
            return
        end

        local physical = backend.RealCharacter or originalCharacter
        if not physical or not physical.Parent then
            restoreAccessoryBodyHideWelds()
            return
        end

        local global = environment()
        local resolver =
            global.UhhhhhhTBZShouldDetachAccessoryForBodyHide
        local seen = physicalIndex.HideSeen or {}
        physicalIndex.HideSeen = seen
        table.clear(seen)
        for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then
                    local weld = handle:FindFirstChild("AccessoryWeld")
                    if weld and weld:IsA("JointInstance") then
                        seen[weld] = true

                        if accessoryBodyHideWeldStates[weld] == nil then
                            local enabled = true
                            pcall(function()
                                enabled = weld.Enabled
                            end)
                            -- A temporarily broken weld must not become the
                            -- permanent hide/show baseline and undo its repair.
                            local binding = accessoryWeldBindings[handle]
                            if binding then enabled = binding.Enabled end
                            accessoryBodyHideWeldStates[weld] = enabled
                        end

                        local shouldDetach = shouldDetachHeadAccessory(handle)
                        if type(resolver) == "function" then
                            local ok, result =
                                pcall(resolver, handle, nil)
                            shouldDetach = shouldDetach or (ok and result == true)
                        end
                        local binding = accessoryWeldBindings[handle]
                        if not ownsPhysicalPart(handle)
                            or (binding and binding.AnchorName == "Head"
                                and backend.HeadHideAccessoryRetryAt and os.clock() < backend.HeadHideAccessoryRetryAt) then
                            shouldDetach = false
                        end

                        local originalEnabled =
                            accessoryBodyHideWeldStates[weld]

                        local managed = accessoryRecoveryStates[handle]
                            and accessoryRecoveryStates[handle].Managed
                        if shouldDetach or managed then
                            pcall(function()
                                weld.Enabled = false
                            end)
                        else
                            -- The Head writer restores a visible pose first.
                            -- A PreSimulation hide callback must not reconnect a
                            -- kept hat to the previous underworld Head target.
                            if binding and binding.AnchorName == "Head" and backend.HeadHideApplied then continue end
                            local currentlyEnabled =
                                debugSafe(function()
                                    return weld.Enabled
                                end, originalEnabled)

                            if originalEnabled == true
                                and currentlyEnabled == false
                            then
                                -- Move the independent Handle onto the exact
                                -- weld solution before merging it back into the
                                -- Head/Torso assembly.
                                snapAccessoryHandleToWeld(handle, weld)
                            end

                            pcall(function()
                                weld.Enabled = originalEnabled
                            end)
                        end
                    end
                end
            end
        end

        for weld, originalEnabled in pairs(accessoryBodyHideWeldStates) do
            if not seen[weld] then
                if typeof(weld) == "Instance" and weld.Parent then
                    pcall(function()
                        weld.Enabled = originalEnabled
                    end)
                end
                accessoryBodyHideWeldStates[weld] = nil
            end
        end
    end

    function backend.AccessoryLifetime.Service(rig,physical)
        if not physical or not physical.Parent or not rig or not rig.Parent then return end
        local index= getPhysicalHeadIndex(physical)
        local controller=backend.AccessoryLifetime.ControllerIndex(rig)
        local now=os.clock()
        local hidden=type(Reanimate.ShouldBodyHidePart)=="function" and Reanimate.ShouldBodyHidePart("Head") == true
        local prior=backend.AccessoryMaintenance
        if prior and prior.Rig==rig and prior.Physical==physical
            and prior.Revision==index.Revision and prior.ControllerRevision==controller.Revision
            and prior.BreakWelds==options.BreakAccessoryWelds and prior.Hidden==hidden
            and prior.PD==backend.EffectivePermanentDeath and now>=prior.At and now-prior.At<.1 then return end
        backend.AccessoryMaintenance={Rig=rig,Physical=physical,Revision=index.Revision,
            ControllerRevision=controller.Revision,BreakWelds=options.BreakAccessoryWelds,
            Hidden=hidden,PD=backend.EffectivePermanentDeath,At=now}
        local inventoryOk,inventoryError=pcall(backend.AccessoryLifetime.Refresh,rig,physical)
        backend.AccessoryLifetimeError=not inventoryOk and tostring(inventoryError) or nil
        local repairOk,repairError=pcall(repairAccessoryWeldBindings)
        local hideOk,hideError=pcall(updateAccessoryBodyHideWelds)
        pdHeadFollower.AccessoryError=not repairOk and tostring(repairError)
            or not hideOk and tostring(hideError) or backend.AccessoryWeldRepairError
    end

    function backend.AccessoryLifetime.ClearControllerContacts()
        if contactIsolation then contactIsolation.Folder:Destroy() contactIsolation=nil end
        backend.ContactIsolationCount,backend.ControllerColliders=0,nil
    end

    function backend.AccessoryLifetime.ApplyControllerCollision(rig,humanoid,root,bodyNames)
        local state=humanoid:GetState().Name
        local passive=humanoid.EvaluateStateMachine==false
            or not table.find({"Running","Jumping","Freefall","Landed","Climbing","Swimming"},state)
        local children,selected,assemblies=rig:GetChildren(),{},{}
        local rootAssembly=root.AssemblyRootPart or root
        if not Reanimate.Noclip then
            selected[root],assemblies[rootAssembly]=true,true
            if passive then
                for _,part in ipairs(children) do
                    if part:IsA("BasePart") and bodyNames[part.Name] and not part.Anchored then
                        local assembly=part.AssemblyRootPart
                        if assembly and not assemblies[assembly] and assembly:IsDescendantOf(rig) then
                            -- A passive state alone does not make a joined R15
                            -- skeleton a ragdoll. One collider per rigid component.
                            local collider=assembly.Parent==rig and bodyNames[assembly.Name] and assembly or part
                            selected[collider],assemblies[assembly]=true,true
                        end
                    end
                end
            end
        end
        local colliders={}
        for _,part in ipairs(children) do
            if part:IsA("BasePart") then
                local enabled=selected[part]==true
                if part.CanCollide~=enabled then part.CanCollide=enabled end
                if enabled then table.insert(colliders,part) end
            end
        end
        backend.ControllerColliders=colliders
        return state,colliders
    end

    function backend.AccessoryLifetime.IsolateControllerContacts(rig,physical,colliders)
        -- Humanoid collision changes can occur after Lua's property guards.
        -- Contact exclusions protect locomotion without applying motion forces
        -- or joining the controller to a replicated/anchored follower assembly.
        local index=getPhysicalHeadIndex(physical)
        local adapter=Reanimate.ControllerRigAdapter
        local driver=adapter and adapter.States[rig]
        local desired={}
        for _,part in ipairs(colliders or {}) do desired[part]=true end
        for _,name in ipairs({"HumanoidRootPart","Head","Torso","UpperTorso","LowerTorso"}) do
            local part=rig:FindFirstChild(name)
            if part and part:IsA("BasePart") then desired[part]=true end
        end
        local state=contactIsolation
        if not state or state.Rig~=rig or not state.Folder.Parent then
            backend.AccessoryLifetime.ClearControllerContacts()
            local folder=Instance.new("Folder")
            folder.Name="_UhhhhhhFollowerContacts" folder.Parent=rig
            state={Rig=rig,Folder=folder,Rows={},Count=0}
            contactIsolation=state
            folder.ChildRemoved:Connect(function()
                if contactIsolation==state then state.Revision=nil end
            end)
        end
        local changed=state.Physical~=physical or state.Revision~=index.Revision
            or state.Driver~=driver or state.DriverRevision~=(driver and driver.ContactRevision)
        if not changed then
            for part in pairs(desired) do if not state.Rows[part] then changed=true break end end
            if not changed then for part in pairs(state.Rows) do if not desired[part] then changed=true break end end end
            if not changed then return end
        end
        local followers={}
        for _,part in ipairs(index.FollowerContacts) do if part.Parent then followers[part]=true end end
        for part in pairs(driver and driver.DriverContacts or {}) do
            if part:IsDescendantOf(driver.Driver) then followers[part]=true end
        end
        for collider,row in pairs(state.Rows) do
            for follower,constraint in pairs(row) do
                if not desired[collider] or not followers[follower] or not constraint.Parent then
                    constraint:Destroy() row[follower]=nil state.Count-=1
                end
            end
            if not desired[collider] then state.Rows[collider]=nil end
        end
        for collider in pairs(desired) do
            local row=state.Rows[collider] or {} state.Rows[collider]=row
            for follower in pairs(followers) do
                if follower~=collider and not row[follower] then
                    local constraint=Instance.new("NoCollisionConstraint")
                    constraint.Part0,constraint.Part1=collider,follower
                    constraint.Parent=state.Folder row[follower]=constraint state.Count+=1
                end
            end
        end
        state.Physical,state.Revision,state.Driver,state.DriverRevision=physical,index.Revision,driver,driver and driver.ContactRevision
        backend.ContactIsolationCount=state.Count
    end

    local function detachScaleBridge()
        backend.ControllerPoseSample,backend.FallbackBodyPoseBatch = nil,nil
        backend.AccessoryMaintenance,backend.LastOwnershipWarningAt = nil,nil
        backend.AccessoryLifetime.ClearControllerContacts()
        if backend.AccessoryLifetime.ResetBodyChain then backend.AccessoryLifetime.ResetBodyChain() end
        if controllerSettingsCleanup then controllerSettingsCleanup() controllerSettingsCleanup = nil end
        local global = environment()
        global.UhhhhhhTBZGelatekTorsoWriter = nil
        global.UhhhhhhTBZRestoreRepRoots = nil
        restoreGelatekTorsoWriter()
        restoreGelatekRootRepRoot()
        PhysicsRoot.RestoreAll()
        PhysicsRoot.Retry()
        table.clear(torsoRepRootFailures)
        global.UhhhhhhTBZGelatekAccessoryWriterActive = nil
        global.UhhhhhhTBZGelatekAccessoryWriterReady = nil
        global.UhhhhhhTBZGelatekPDHeadWriterActive = nil
        global.UhhhhhhTBZGelatekPDHeadWriterReady = nil
        global.UhhhhhhTBZGelatekRenderHeadSync = nil
        global.UhhhhhhTBZGelatekSyncFollowers = nil
        global.UhhhhhhTBZGelatekControllerBodyPose = nil
        global.UhhhhhhTBZGelatekConnectedBodyRoot = nil
        if ragdollCollisionFolder then
            ragdollCollisionFolder:Destroy()
            ragdollCollisionFolder = nil
        end
        pcall(stopReplicationLab, true)
        if scaleBridgeConnection then
            pcall(function()
                scaleBridgeConnection:Disconnect()
            end)
            scaleBridgeConnection = nil
        end
        if controllerCollisionConnection then
            pcall(function()
                controllerCollisionConnection:Disconnect()
            end)
            controllerCollisionConnection = nil
        end
        if neckBridgeConnection then
            pcall(function()
                neckBridgeConnection:Disconnect()
            end)
            neckBridgeConnection = nil
        end
        if neckBridgeLateConnection then
            pcall(function()
                neckBridgeLateConnection:Disconnect()
            end)
            neckBridgeLateConnection = nil
        end
        if neckBridgeRenderConnection then
            pcall(function()
                neckBridgeRenderConnection:Disconnect()
            end)
            neckBridgeRenderConnection = nil
        end
        restoreGelatekHeadWriter()
        resetPDHeadFollower()
        if physicalAnimatorConnection then
            pcall(function()
                physicalAnimatorConnection:Disconnect()
            end)
            physicalAnimatorConnection = nil
        end
        if safeTrackerConnection then
            pcall(function()
                safeTrackerConnection:Disconnect()
            end)
            safeTrackerConnection = nil
        end
        if limbRecoveryConnection then
            pcall(function()
                limbRecoveryConnection:Disconnect()
            end)
            limbRecoveryConnection = nil
        end
        if flingBridgeConnection then
            pcall(function()
                flingBridgeConnection:Disconnect()
            end)
            flingBridgeConnection = nil
        end
        if accessoryBodyHideConnection then
            pcall(function()
                accessoryBodyHideConnection:Disconnect()
            end)
            accessoryBodyHideConnection = nil
        end
        if accessoryRecoveryConnection then
            pcall(function()
                accessoryRecoveryConnection:Disconnect()
            end)
            accessoryRecoveryConnection = nil
        end
        restoreAccessoryRecoveryStates()
        restoreAccessoryBodyHideWelds()
        if backend.AccessoryLifetime.RestoreResetNeck then backend.AccessoryLifetime.RestoreResetNeck() end
        -- A controller bridge can restart around the same original shell.
        -- Preserve original accessory identities across that handoff; changing
        -- physical characters or final cleanup releases the registry instead.
        physicalIndex.Recovery = nil
        activeFling = nil
        table.clear(recentFlingTargets)
        global.UhhhhhhTBZGelatekFlingActive = nil
        lastAppliedScale = nil
        lastJump = false
    end

    local function gelatekTorsoWriterBlocked()
        return options.TorsoFling == true
            or (
                options.BulletEnabled == true
                and options.BulletLockTorso == true
            )
    end

    local function writeGelatekTorso(
        rig,
        physicalPart,
        controllerTorso,
        targetCFrame
    )
        local function releasePhysicalPart()
            local state = torsoRepRootStates[physicalPart]
            if state then
                local restored, reason = restoreManagedRepRoot(state)
                if restored then torsoRepRootStates[physicalPart] = nil
                else backend.TorsoRepRootLastError = reason end
            end
        end
        local requestedMethod = replicationWriters.GelatekTorso
        if backend.EffectivePermanentDeath == true
            or rebindInProgress
            or Reanimate.UsePhysicsRepRootPart == false
            or gelatekTorsoWriterBlocked()
            or requestedMethod ~= "PhysicsRepRootRef"
        then
            releasePhysicalPart()
            if requestedMethod == "Gelatek Physics" then torsoRepRootFailures[physicalPart] = nil end
            backend.TorsoRepRootBlockedReason = "inactive mode or Physics Glue disabled"
            return false
        end

        local global = environment()
        if global.UhhhhhhTBZGelatekFlingActive == true then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "fling active"
            return false
        end

        local physical = backend.RealCharacter or originalCharacter
        local physicalRoot = global.UhhhhhhTBZGelatekPhysicalRoot
        if not physical
            or not physical.Parent
            or typeof(physicalPart) ~= "Instance"
            or not physicalPart:IsA("BasePart")
            or not physicalPart:IsDescendantOf(physical)
            or typeof(controllerTorso) ~= "Instance"
            or not controllerTorso:IsA("BasePart")
            or not controllerTorso:IsDescendantOf(rig)
            or typeof(targetCFrame) ~= "CFrame"
            or typeof(physicalRoot) ~= "Instance"
            or not physicalRoot:IsA("BasePart")
            or not physicalRoot.Parent
            or not physicalRoot:IsDescendantOf(physical)
            or physicalRoot == physicalPart
        then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "invalid original part, root, controller, or pose"
            return false
        end

        local validTorsoPart = physicalPart.Name == "Torso"
            or physicalPart.Name == "UpperTorso"
            or physicalPart.Name == "LowerTorso"
        if not validTorsoPart then
            releasePhysicalPart()
            return false
        end
        if not ownsPhysicalPart(physicalRoot) or not ownsPhysicalPart(physicalPart) then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "real torso/root assembly is not network-owned"
            return false
        end
        if type(Reanimate.ShouldBodyHidePart) == "function"
            and Reanimate.ShouldBodyHidePart("Torso") == true then
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "torso intentionally hidden"
            return false
        end

        local sameAssembly = false
        pcall(function()
            sameAssembly = physicalRoot.AssemblyRootPart
                == physicalPart.AssemblyRootPart
        end)
        if sameAssembly then
            -- A replication-root link is only useful while Gelatek has split the
            -- root and torso into separate assemblies. Never fight a live root joint.
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "root and torso still share an assembly"
            return false
        end

        -- The link is an optional replication reference, never a replacement
        -- for Gelatek's per-frame CFrame target and native netless velocity.
        local rootOffset = physical:FindFirstChild("UpperTorso")
            and CFrame.new(0, 0.194 * characterScale(), 0)
            or CFrame.identity
        local expectedRootCFrame = controllerTorso.CFrame * rootOffset
        local referenceError =
            (physicalRoot.Position - expectedRootCFrame.Position).Magnitude
        local maximumReferenceError = math.max(12 * characterScale(), 8)
        if referenceError > maximumReferenceError then
            -- A voided, flinging, or temporarily unowned HRP must never drag the
            -- visible torso with it. Native Gelatek remains the per-frame fallback.
            releasePhysicalPart()
            backend.TorsoRepRootBlockedReason = "real root is separated from its controller pose"
            return false
        end

        local state = torsoRepRootStates[physicalPart]
        if not state then
            state = { Writes = 0 }
            torsoRepRootStates[physicalPart] = state
        end
        local failures = torsoRepRootFailures[physicalPart]
        if not failures or failures.Requested ~= requestedMethod
            or failures.RetrySerial ~= PhysicsRoot.RetrySerial
            or failures.NextProbe and os.clock() >= failures.NextProbe
        then
            failures = {Requested = requestedMethod, RetrySerial = PhysicsRoot.RetrySerial}
            torsoRepRootFailures[physicalPart] = failures
        end
        local linked, reason = false, failures[requestedMethod]
        local selectedMethod = requestedMethod
        if not reason then
            linked, reason = writeManagedRepRoot(state, physicalPart, physicalRoot, selectedMethod)
        end
        state.Requested = requestedMethod
        state.FallbackReason = not linked and reason or nil
        backend.TorsoRepRootFallbackReason = state.FallbackReason
        if not linked then
            failures[selectedMethod] = reason
            failures.NextProbe = os.clock() + 5
            backend.TorsoRepRootLastError = reason
            local restored, restoreError = restoreManagedRepRoot(state)
            if restored then torsoRepRootStates[physicalPart] = nil
            else backend.TorsoRepRootLastError = restoreError end
            if not backend.TorsoRepRootWarned then
                backend.TorsoRepRootWarned = true
                warn("Gelatek " .. requestedMethod .. " writer fell back: " .. tostring(reason))
                Util.Notify("Torso replication link unavailable; using Gelatek Physics")
            end
            return false
        end

        if not state.NativePhysicsActive then
            -- Drop angular carry-over from the retired root-velocity copier.
            -- Subsequent motion stays with Gelatek's existing physics pass.
            pcall(function() physicalPart.AssemblyAngularVelocity = Vector3.zero end)
            state.NativePhysicsActive = true
        end
        state.LastTarget = targetCFrame
        state.ReferenceError = referenceError
        backend.TorsoRepRootLastError = nil
        backend.TorsoRepRootWarned = false
        backend.TorsoRepRootBlockedReason = nil
        -- Returning false is intentional: CFrameAlign must execute its native
        -- correction even while the hidden link is successfully installed.
        return false
    end

    -- PD transports the detached real Head with CFrame. Non-PD keeps its Neck
    -- connected and borrows Limb's replicated joint offset/angle writer.
    pdHeadFollower = {
        Head = nil, LastTarget = nil, LastError = nil, LastOwned = nil, Writes = 0,
        LinearMover = nil, AngularMover = nil, SavedProperties = nil,
        OwnershipLossSince = nil, PositionError = 0,
        JointStates = setmetatable({}, {__mode = "k"}),
        ExternalMovers = setmetatable({}, {__mode = "k"}),
        AccessoryProperties = setmetatable({}, {__mode = "k"}),
        LastStepAt = nil, LastSuccessfulWriteAt = nil, LastBlockedReason = nil,
        LastPhase = nil, AccessoryError = nil, AccessoryWrites = 0,
        Mode = "waiting", SampledTarget = nil, AcceptedWrites = 0,
        NeckChannels = {}, NeckRevision = nil, Torso = nil, SavedTorso = nil,
        HumanoidConfigured = false, LifecycleWarning = nil, OwnedWrites = 0,
    }

    resetPDHeadFollower = function()
        backend.HeadHideApplied, backend.HeadHideAccessoryRetryAt = nil, nil
        backend.HeadHideAccessoryBlockedReason, backend.HeadHideAccessoryRestorePending = nil, nil
        for _, channel in ipairs(pdHeadFollower.NeckChannels) do
            local joint, saved = channel.Joint, channel.Saved
            if joint.Parent then
                pcall(function()
                    if joint:IsA("Motor6D") and saved.Transform then
                        Util.SetCharacterJointTransform(joint, saved.Transform, nil, true)
                    end
                end)
            end
            Util.CharacterJointTransportOnly[joint] = saved.TransportOnly
        end
        local torso, torsoSaved = pdHeadFollower.Torso, pdHeadFollower.SavedTorso
        if torso and torso.Parent and torsoSaved then
            pcall(function()
                torso.RootPriority, torso.Massless = torsoSaved.RootPriority, torsoSaved.Massless
            end)
        end
        for _, mover in pairs({pdHeadFollower.LinearMover, pdHeadFollower.AngularMover, pdHeadFollower.Attachment}) do
            if mover then pcall(function() mover:Destroy() end) end
        end
        local head, saved = pdHeadFollower.Head, pdHeadFollower.SavedProperties
        if head then PhysicsRoot.Release(head) end
        if head and head.Parent and saved then
            pcall(function()
                head.RootPriority, head.Massless = saved.RootPriority, saved.Massless
                head.CustomPhysicalProperties = saved.CustomPhysicalProperties
                head.CanCollide, head.CanTouch, head.Anchored = saved.CanCollide, saved.CanTouch, saved.Anchored
            end)
        end
        for joint, savedJoint in pairs(pdHeadFollower.JointStates) do
            if joint.Parent then pcall(function()
                if savedJoint.Attached then
                    joint.Attachment0, joint.Attachment1 = savedJoint.Attachment0, savedJoint.Attachment1
                else joint.Part0, joint.Part1 = savedJoint.Part0, savedJoint.Part1 end
                joint.Enabled = savedJoint.Enabled
            end) end
        end
        for mover, properties in pairs(pdHeadFollower.ExternalMovers) do
            if mover.Parent then
                for property, value in pairs(properties) do
                    pcall(function() mover[property] = value end)
                end
            end
        end
        for handle, properties in pairs(pdHeadFollower.AccessoryProperties) do
            if handle.Parent then
                pcall(function()
                    handle.RootPriority, handle.Massless = properties.RootPriority, properties.Massless
                end)
            end
        end
        local humanoid = pdHeadFollower.Humanoid
        if humanoid and humanoid.Parent and pdHeadFollower.SavedHumanoid then
            for property, value in pairs(pdHeadFollower.SavedHumanoid) do
                pcall(function() humanoid[property] = value end)
            end
        end
        table.clear(pdHeadFollower.JointStates)
        table.clear(pdHeadFollower.ExternalMovers)
        table.clear(pdHeadFollower.AccessoryProperties)
        table.clear(pdHeadFollower.NeckChannels)
        pdHeadFollower.NeckRevision, pdHeadFollower.Torso, pdHeadFollower.SavedTorso = nil, nil, nil
        pdHeadFollower.Head, pdHeadFollower.Humanoid, pdHeadFollower.SavedHumanoid = nil, nil, nil
        pdHeadFollower.LinearMover, pdHeadFollower.AngularMover, pdHeadFollower.SavedProperties = nil, nil, nil
        pdHeadFollower.LastTarget, pdHeadFollower.SampledTarget, pdHeadFollower.LastError = nil, nil, nil
        pdHeadFollower.RelativeSample = nil
        pdHeadFollower.LocalDisplayError = nil
        pdHeadFollower.JointClass, pdHeadFollower.TransportRoot = nil, nil
        pdHeadFollower.LastOwned, pdHeadFollower.OwnershipLossSince = nil, nil
        pdHeadFollower.PositionError, pdHeadFollower.Writes, pdHeadFollower.AccessoryWrites = 0, 0, 0
        pdHeadFollower.AcceptedWrites = 0
        pdHeadFollower.LastStepAt, pdHeadFollower.LastSuccessfulWriteAt = nil, nil
        pdHeadFollower.LastBlockedReason, pdHeadFollower.LastPhase, pdHeadFollower.AccessoryError = nil, nil, nil
        pdHeadFollower.HumanoidConfigured, pdHeadFollower.LifecycleWarning = false, nil
        pdHeadFollower.Attachment, pdHeadFollower.NativeVelocity, pdHeadFollower.RepRootCleared = nil, nil, false
        pdHeadFollower.RepRootClearError = nil
        pdHeadFollower.OwnedWrites = 0
        pdHeadFollower.Mode = "waiting"
        pdHeadFollower.Route = nil
    end
    restoreGelatekHeadWriter = resetPDHeadFollower

    local function finiteCFrame(value)
        if typeof(value) ~= "CFrame" then return false end
        local x,y,z,a,b,c,d,e,f,g,h,i = value:GetComponents()
        return x==x and y==y and z==z and a==a and b==b and c==c
            and d==d and e==e and f==f and g==g and h==h and i==i
            and math.abs(x)<math.huge and math.abs(y)<math.huge and math.abs(z)<math.huge
            and math.abs(a)<math.huge and math.abs(b)<math.huge and math.abs(c)<math.huge
            and math.abs(d)<math.huge and math.abs(e)<math.huge and math.abs(f)<math.huge
            and math.abs(g)<math.huge and math.abs(h)<math.huge and math.abs(i)<math.huge
    end

    local function finiteVector3(value)
        if typeof(value) ~= "Vector3" then return false end
        return value.X == value.X and value.Y == value.Y and value.Z == value.Z
            and math.abs(value.X) < math.huge and math.abs(value.Y) < math.huge
            and math.abs(value.Z) < math.huge
    end
    pdHeadFollower.FiniteCFrame = finiteCFrame

    -- R15 retains its internal elbow/wrist, knee/ankle and waist links. Each
    -- limb follows as one assembly, matching R6's physical limb granularity.
    local bodyChain = {Joints={}, Targets={}, Properties={}}
    backend.BodyChain = bodyChain
    local function captureBodyChainJoint(joint)
        local saved={Enabled=joint.Enabled}
        if Util.IsCharacterJoint(joint) then saved.Transform=joint.Transform end
        if joint.ClassName=="AnimationConstraint" then saved.IsKinematic=joint.IsKinematic end
        return saved
    end
    function backend.AccessoryLifetime.ConnectedBodyRoot(physical, part)
        if not physical or not part or part.Parent ~= physical then return nil end
        local root = part.AssemblyRootPart
        if not root then return nil end
        if root ~= part then return root end
        local index = getPhysicalHeadIndex(physical)
        local phase = environment().UhhhhhhTBZGelatekPosePhaseId
        local counts = index.BodyAssemblyCounts
        if not counts then counts={} index.BodyAssemblyCounts=counts end
        local groups=index.BodyAssemblyGroups
        if not groups then groups={} index.BodyAssemblyGroups=groups end
        if phase==nil or index.BodyAssemblyPhase~=phase or index.BodyAssemblyRevision~=index.Revision then
            table.clear(counts)
            table.clear(groups)
            for _, other in ipairs(index.BodyParts) do
                local assembly=other.Parent==physical and other.AssemblyRootPart
                if assembly then
                    local group=Context.R15Body.Group(other.Name)
                    if other.Name=="Head" and backend.EffectivePermanentDeath~=true then group="Torso" end
                    groups[assembly]=counts[assembly]==nil and group or groups[assembly]==group and group or false
                    counts[assembly]=(counts[assembly] or 0)+1
                end
            end
            index.BodyAssemblyPhase,index.BodyAssemblyRevision=phase,index.Revision
        end
        if (counts[root] or 0)>1 then
            if physical:FindFirstChild("UpperTorso") and groups[root]==Context.R15Body.Group(part.Name) then return nil end
            local head=physical:FindFirstChild("Head")
            if backend.EffectivePermanentDeath~=true and (part.Name=="Torso" or part.Name=="UpperTorso")
                and counts[root]==2 and head and head.AssemblyRootPart==root then
                for _,joint in ipairs(index.Joints) do
                    if joint:IsA("Motor6D") and joint.Enabled then
                        local a,b=Util.GetCharacterJointParts(joint)
                        if (a==part and b==head) or (b==part and a==head) then return nil end
                    end
                end
            end
            return root
        end
        return nil
    end
    function backend.AccessoryLifetime.ResetBodyChain()
        for joint, saved in pairs(bodyChain.Joints) do
            if saved.Connection then saved.Connection:Disconnect() end
            if joint.Parent then pcall(function()
                if saved.DetachedForPD then
                    if saved.Attached then joint.Attachment0,joint.Attachment1=saved.Attachment0,saved.Attachment1
                    else joint.Part0,joint.Part1=saved.Part0,saved.Part1 end
                end
                if saved.Transform~=nil then joint.Transform=saved.Transform end
                joint.Enabled = saved.Enabled
                if saved.IsKinematic~=nil then joint.IsKinematic=saved.IsKinematic end
            end) end
        end
        for part, saved in pairs(bodyChain.Properties) do
            if part.Parent then pcall(function() part.RootPriority, part.Massless = saved.RootPriority, saved.Massless end) end
        end
        table.clear(bodyChain.Joints) table.clear(bodyChain.Properties) table.clear(bodyChain.Targets)
        bodyChain.Physical, bodyChain.Suspended, bodyChain.LastError = nil, nil, nil
        bodyChain.RoutePhysical, bodyChain.RouteRevision = nil, nil
        bodyChain.RouteRootAssembly,bodyChain.RouteTorsoAssembly=nil,nil
        bodyChain.PDPhysical,bodyChain.PDPreviousKeep,bodyChain.PDRevision=nil,nil,nil
    end
    function backend.AccessoryLifetime.RootFlingReady(physical,root)
        if not physical or not root or root.Parent~=physical or not ownsPhysicalPart(root) then
            return false,"physical root is not network-owned"
        end
        local assembly=root.AssemblyRootPart
        if not assembly or not assembly:IsDescendantOf(physical) or assembly.Anchored then
            return false,"physical root assembly is unavailable"
        end
        for _,part in ipairs(getPhysicalHeadIndex(physical).BodyParts) do
            if part~=root and controllerBodyNames[part.Name] and part.AssemblyRootPart==assembly then
                return false,"waiting for the physical root to separate from the body"
            end
        end
        return true
    end
    function backend.AccessoryLifetime.DetachBodyChainForPD(physical)
        local index=getPhysicalHeadIndex(physical)
        if bodyChain.PDPhysical==physical and bodyChain.PDRevision==index.Revision then return end
        quiesceGelatekFollowerSupport()
        if bodyChain.PDPhysical~=physical then
            local retained=backend.KeepBodyChain
            restoreGelatekTorsoWriter()
            restoreGelatekRootRepRoot()
            backend.AccessoryLifetime.ResetBodyChain()
            bodyChain.PDPhysical,bodyChain.PDPreviousKeep=physical,retained
        end
        for _,joint in ipairs(index.Joints) do
            local p0,p1=Util.GetCharacterJointParts(joint)
            if joint.Parent and p0 and p1 and p0.Parent==physical and p1.Parent==physical
                and not (physical:FindFirstChild("UpperTorso") and Context.R15Body.KeepJoint(joint,p0,p1)) then
                local saved=bodyChain.Joints[joint]
                if not saved then
                    saved=captureBodyChainJoint(joint)
                    saved.DetachedForPD=true
                    if joint.ClassName=="AnimationConstraint" or joint.ClassName=="RigidConstraint" then
                        saved.Attached,saved.Attachment0,saved.Attachment1=true,joint.Attachment0,joint.Attachment1
                    else saved.Part0,saved.Part1=joint.Part0,joint.Part1 end
                    bodyChain.Joints[joint] = saved
                end
                joint.Enabled = false
                if saved.Attached then joint.Attachment1=nil
                else joint.Part1 = nil end -- release the actual rigid endpoint during PD
            end
        end
        -- Ragdoll constraints do not share AssemblyRootPart, but can still pull
        -- independent followers together. Preserve accessory mechanics and stop
        -- only constraints between the physical avatar's own body parts.
        for _,joint in ipairs(index.Descendants) do
            if joint:IsA("Constraint") and joint.ClassName~="AnimationConstraint" then
                local a0,a1=joint.Attachment0,joint.Attachment1
                local p0=a0 and a0:FindFirstAncestorWhichIsA("BasePart")
                local p1=a1 and a1:FindFirstAncestorWhichIsA("BasePart")
                if p0 and p1 and p0.Parent==physical and p1.Parent==physical then
                    local saved=bodyChain.Joints[joint] or {Enabled=joint.Enabled}
                    bodyChain.Joints[joint]=saved
                    if not saved.Connection then
                        saved.Connection=joint:GetPropertyChangedSignal("Enabled"):Connect(function()
                            if bodyChain.Joints[joint]==saved and joint.Enabled then joint.Enabled=false end
                        end)
                    end
                    joint.Enabled=false
                end
            end
        end
        backend.KeepBodyChain = false
        bodyChain.PDRevision=getPhysicalHeadIndex(physical).Revision
        local config=environment().GelatekReanimateConfig
        if config then config.CurrentAngleBodyChain,config.CurrentAngleHeadOnly=false,false end
    end
    function backend.AccessoryLifetime.PDBodyIsDetached(physical)
        local roots={}
        for _,part in ipairs(getPhysicalHeadIndex(physical).BodyParts) do
            if part.Parent==physical then
                local root=part.AssemblyRootPart
                local group=physical:FindFirstChild("UpperTorso") and Context.R15Body.Group(part.Name) or part.Name
                if not root or not root:IsDescendantOf(physical) or roots[root] and roots[root]~=group then return false end
                roots[root]=group
            end
        end
        return true
    end
    local function headStillSharesBodyAssembly(physical, head)
        local root = head.AssemblyRootPart
        if not root then return true end
        for _, part in ipairs(getPhysicalHeadIndex(physical).BodyParts) do
            if part ~= head and part:IsA("BasePart") and part.AssemblyRootPart == root then
                return true
            end
        end
        return false
    end

    function pdHeadFollower.IsDetachedFromBody(physical, head)
        if not physical or not physical.Parent or not head or not head:IsA("BasePart")
            or head.Parent ~= physical or head ~= physical:FindFirstChild("Head")
            or headStillSharesBodyAssembly(physical, head) then return false end
        -- Assembly information can lag a joint edit. Require both a separate
        -- assembly and no surviving body link before rescuing a non-PD Head.
        -- Accessory welds are allowed: they should travel with this Head.
        for _, joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
            if joint.Parent then
                local p0, p1 = Util.GetCharacterJointParts(joint)
                if not p0 and (joint.ClassName == "RigidConstraint" or joint.ClassName == "AnimationConstraint") then
                    p0 = joint.Attachment0 and joint.Attachment0:FindFirstAncestorWhichIsA("BasePart")
                    p1 = joint.Attachment1 and joint.Attachment1:FindFirstAncestorWhichIsA("BasePart")
                end
                local other = p0 == head and p1 or (p1 == head and p0 or nil)
                if other and other.Parent == physical and other:IsA("BasePart") then return false end
            end
        end
        return true
    end

    function pdHeadFollower.PhysicalHumanoidIsDead(physical)
        local humanoid = physical and physical:FindFirstChildOfClass("Humanoid")
        if not humanoid then return false end
        return debugSafe(function() return humanoid.Health <= 0 end, false)
            or (Enum.HumanoidStateType.Dead ~= nil
                and debugSafe(function() return humanoid:GetState() end, nil) == Enum.HumanoidStateType.Dead)
    end

    function backend.ModePolicy.ResetHandoffReady(physical)
        if backend.ResetPDIntent~=true or options.ResetTurnsPD~=true
            or backend.ResetPDRequestSerial~=resetRequestSerial or backend.ResetPDPhysical~=physical then return false end
        -- A successful executor signal and a respawn deadline are requests,
        -- not evidence that this physical shell died. Keep its working non-PD
        -- transport until death is observed or CharacterAdded replaces it.
        return pdHeadFollower.PhysicalHumanoidIsDead(physical)
    end

    function backend.AccessoryLifetime.PrepareResetNeck(physical,head)
        if not head or not head.Parent then return end
        backend.ResetPDNeckStates=backend.ResetPDNeckStates or {}
        for _,joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
            local p0,p1=Util.GetCharacterJointParts(joint)
            local other=p0==head and p1 or p1==head and p0
            if other and other.Parent==physical and (other.Name=="Torso" or other.Name=="UpperTorso")
                and not (physical:FindFirstChild("UpperTorso") and Context.R15Body.KeepJoint(joint,p0,p1)) then
                local attached=joint.ClassName=="AnimationConstraint" or joint.ClassName=="RigidConstraint"
                if not backend.ResetPDNeckStates[joint] then
                    backend.ResetPDNeckStates[joint]=attached and {
                        Attached=true,Attachment0=joint.Attachment0,Attachment1=joint.Attachment1,Enabled=joint.Enabled,
                    } or {Part0=joint.Part0,Part1=joint.Part1,Enabled=joint.Enabled}
                end
                joint.Enabled=false
                if attached then joint.Attachment1=nil else joint.Part1=nil end
            end
        end
    end
    function backend.AccessoryLifetime.RestoreResetNeck()
        for joint,saved in pairs(backend.ResetPDNeckStates or {}) do
            if joint.Parent then pcall(function()
                if saved.Attached then joint.Attachment0,joint.Attachment1=saved.Attachment0,saved.Attachment1
                else joint.Part0,joint.Part1=saved.Part0,saved.Part1 end
                joint.Enabled=saved.Enabled
            end) end
        end
        backend.ResetPDNeckStates=nil
    end

    function backend.AccessoryLifetime.CancelResetHandoff()
        if environment().UhhhhhhTBZGelatekPDTransitionPending and backend.EffectivePermanentDeath~=true then
            if bodyChain.PDPhysical then
                local retained=bodyChain.PDPreviousKeep
                backend.AccessoryLifetime.ResetBodyChain()
                backend.KeepBodyChain=retained==true
                local config=environment().GelatekReanimateConfig
                if config then config.CurrentAngleBodyChain,config.CurrentAngleHeadOnly=backend.KeepBodyChain,not backend.KeepBodyChain end
            end
            backend.AccessoryLifetime.RestoreResetNeck()
        end
        environment().UhhhhhhTBZGelatekPDTransitionPending=nil
        backend.ResetPDIntent=false
        backend.ResetPDReadyAt,backend.ResetPDPhysical,backend.ResetPDRequestSerial=nil,nil,nil
    end

    function pdHeadFollower.UpdateResetHandoff(physical, head)
        local current=backend.ResetPDIntent==true and options.ResetTurnsPD==true
            and backend.ResetPDRequestSerial==resetRequestSerial and backend.ResetPDPhysical==physical
            and physical~=nil and physical.Parent~=nil
        if not current and (backend.ResetPDIntent or environment().UhhhhhhTBZGelatekPDTransitionPending) then
            backend.AccessoryLifetime.CancelResetHandoff()
        end
        if backend.ModePolicy.ResetHandoffReady(physical)
            and backend.Running and not rebindInProgress
            and head and head.Parent==physical and head==physical:FindFirstChild("Head")
            and environment().UhhhhhhTBZGelatekPDTransitionPending ~= true then
            environment().UhhhhhhTBZGelatekPDTransitionPending = true
            quiesceGelatekFollowerSupport()
            backend.AccessoryLifetime.PrepareResetNeck(physical,head)
        end
        if not backend.ModePolicy.ResetHandoffReady(physical)
            or rebindInProgress or not backend.Running
            or not (pdHeadFollower.IsDetachedFromBody(physical, head)
                or backend.AccessoryLifetime.RetainedR15Neck(physical,head)) then
            return false
        end
        local promote = environment().UhhhhhhTBZGelatekPromoteResetPD
        if type(promote) ~= "function" then return false end
        local ok, promoted = pcall(promote, physical, head)
        backend.ResetPDLastError = not ok and tostring(promoted) or nil
        if not ok or promoted ~= true then return false end
        backend.ResetPDIntent = false
        backend.ResetPDReadyAt,backend.ResetPDPhysical,backend.ResetPDRequestSerial=nil,nil,nil
        backend.ResetPDCompletedSerial = resetRequestSerial
        if type(Util.Notify) == "function" then Util.Notify("Reset -> PD") end
        return true
    end

    local function suspendCompetingHeadMovers(part)
        for _, mover in ipairs(getPhysicalHeadIndex(backend.RealCharacter or originalCharacter).Movers) do
            if mover.Parent == part and mover ~= pdHeadFollower.LinearMover and mover ~= pdHeadFollower.AngularMover then
                local property, replacement
                if mover:IsA("BodyVelocity") or mover:IsA("BodyPosition") then
                    property, replacement = "MaxForce", Vector3.zero
                elseif mover:IsA("BodyAngularVelocity") or mover:IsA("BodyGyro") then
                    property, replacement = "MaxTorque", Vector3.zero
                elseif mover:IsA("AlignPosition") or mover:IsA("AlignOrientation")
                    or mover:IsA("LinearVelocity") or mover:IsA("AngularVelocity")
                    or mover:IsA("VectorForce") or mover:IsA("Torque") then
                    property, replacement = "Enabled", false
                end
                if property then
                    if not pdHeadFollower.ExternalMovers[mover] then
                        pdHeadFollower.ExternalMovers[mover] = {[property] = mover[property]}
                    end
                    mover[property] = replacement
                end
            end
        end
    end

    local function suspendGelatekHeadLifecycle(reason)
        environment().UhhhhhhTBZGelatekFollowersPaused = true
        pdHeadFollower.LifecycleWarning = reason
        quiesceGelatekFollowerSupport()
        if type(Reanimate.SuspendPhysicsHead) == "function" then
            pcall(Reanimate.SuspendPhysicsHead, reason or "Gelatek character transition")
        elseif type(Reanimate.ReleasePhysicsHead) == "function" then
            pcall(Reanimate.ReleasePhysicsHead)
        end
    end
    local function resumeGelatekHeadLifecycle()
        environment().UhhhhhhTBZGelatekFollowersPaused = false
        pdHeadFollower.LifecycleWarning = nil
        if type(Reanimate.ResumePhysicsHead) == "function" then pcall(Reanimate.ResumePhysicsHead) end
    end

    function backend.AccessoryLifetime.HeadTorsoPose(physical,torso,controllerTorso,bodyPoses,ignoreHide)
        local basis=controllerTorso and backend.AccessoryLifetime.ControllerBodyPose(controllerTorso,bodyPoses) or torso.CFrame
        if controllerTorso and torso.Name=="UpperTorso" and controllerTorso.Name=="Torso" then
            basis*=scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset("UpperTorso"))
        end
        -- Match the torso target actually used by the body follower, including
        -- an R15 waist pose and an independently hidden torso.
        basis=backend.AccessoryLifetime.ResolveAnimationPose(torso,controllerTorso,basis,bodyPoses)
        if backend.KeepBodyChain and bodyChain.Physical==physical and bodyChain.Targets[torso] then basis=bodyChain.Targets[torso] end
        if not ignoreHide and type(Reanimate.ResolveBodyHideTargetCFrame)=="function" then
            basis=Reanimate.ResolveBodyHideTargetCFrame(torso,basis,torso.Name,false)
        end
        return basis
    end

    function backend.AccessoryLifetime.ResolveHeadTarget(physical,controllerHead,fallback,bodyPoses)
        local target,nativeR15=backend.AccessoryLifetime.ResolveAnimationPose(physical and physical:FindFirstChild("Head"),controllerHead,fallback,bodyPoses)
        if not backend.EffectivePermanentDeath or nativeR15 then
            backend.HeadAlignmentSource=nativeR15 and "native R15 animation pose" or "controller pose"
            return target
        end
        local alignment=Context.HeadAlignment
        if not alignment or not physical or not controllerHead then return target end
        local rig=controllerHead.Parent
        local physicalIndex=getPhysicalHeadIndex(physical)
        local binding,why=alignment.Capture(physical,physicalIndex.Joints,Util,backend.HeadAlignmentBinding)
        backend.HeadAlignmentBinding=binding
        local index=rig and backend.AccessoryLifetime.ControllerIndex(rig)
        local controller,controllerWhy=alignment.Controller(rig,index and index.BodyJoints,Util,controllerSnapshot,backend.HeadAlignmentController)
        backend.HeadAlignmentController=controller
        if not binding or not controller then
            backend.HeadAlignmentSource="controller pose: "..tostring(why or controllerWhy)
            return target
        end
        local controllerTorso=controller.Torso
        local controllerPose=backend.AccessoryLifetime.ControllerBodyPose(controllerTorso,bodyPoses)
        -- The Head has its own hide selection. A hidden torso must not pull a
        -- visible detached PD Head underground while resolving its rest mount.
        local torsoTarget=backend.AccessoryLifetime.HeadTorsoPose(physical,binding.Torso,controllerTorso,bodyPoses,true)
        local resolved,reason=alignment.Resolve(binding,controller,torsoTarget,controllerPose,target,characterScale())
        backend.HeadAlignmentSource=resolved and binding.Source or ("controller pose: "..tostring(reason))
        return resolved or target
    end

    function backend.AccessoryLifetime.RetainedR15Neck(physical,head)
        local torso=physical and physical:FindFirstChild("UpperTorso")
        if not torso or not head or head.Parent~=physical then return false end
        for _,joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
            if joint.Parent then
                local p0,p1=Util.GetCharacterJointParts(joint)
                if ((p0==torso and p1==head) or (p0==head and p1==torso))
                    and Context.R15Body.KeepJoint(joint,p0,p1) then return true end
            end
        end
        return false
    end

    local function writeGelatekCurrentAngleHead(physical, head, target, controllerTorso, bodyPoses, poseOnly)
        if not physical or not physical.Parent or not head or not head.Parent or not finiteCFrame(target) then
            pdHeadFollower.LastBlockedReason = "missing real Head or invalid joint target"
            return false
        end
        local torso = physical:FindFirstChild("UpperTorso") or physical:FindFirstChild("Torso")
        if not torso or not finiteCFrame(torso.CFrame) then
            pdHeadFollower.LastBlockedReason = "non-PD joint transport needs the real torso"
            return false
        end
        if pdHeadFollower.Head ~= head or pdHeadFollower.Torso ~= torso
            or pdHeadFollower.Mode ~= "ReplicateCurrentAngle6D" then
            resetPDHeadFollower()
            pdHeadFollower.Head, pdHeadFollower.Torso = head, torso
            pdHeadFollower.Mode = "ReplicateCurrentAngle6D"
            pdHeadFollower.SavedProperties = {
                RootPriority = head.RootPriority, Massless = head.Massless,
                CustomPhysicalProperties = head.CustomPhysicalProperties,
                CanCollide = head.CanCollide, CanTouch = head.CanTouch, Anchored = head.Anchored,
            }
            pdHeadFollower.SavedTorso = {RootPriority = torso.RootPriority, Massless = torso.Massless}
        end
        local index = getPhysicalHeadIndex(physical)
        if pdHeadFollower.NeckRevision ~= index.Revision then
            local channels = pdHeadFollower.NeckChannels
            for i = #channels, 1, -1 do
                local channel = channels[i]
                local p0, p1 = Util.GetCharacterJointParts(channel.Joint)
                if not channel.Joint.Parent or not ((p0 == torso and p1 == head) or (p0 == head and p1 == torso)) then
                    Util.CharacterJointTransportOnly[channel.Joint] = channel.Saved.TransportOnly
                    table.remove(channels, i)
                end
            end
            for _, joint in ipairs(index.Joints) do
                if joint.Parent and (joint:IsA("Motor6D") or joint.ClassName == "AnimationConstraint") then
                    local part0, part1 = Util.GetCharacterJointParts(joint)
                    if (part0 == torso and part1 == head) or (part0 == head and part1 == torso) then
                        local found = false
                        for _, channel in ipairs(channels) do if channel.Joint == joint then found = true break end end
                        if not found then
                            table.insert(channels, {
                                Joint = joint,
                                Saved = {
                                    Transform = debugSafe(function() return joint.Transform end, CFrame.identity),
                                    TransportOnly = Util.CharacterJointTransportOnly[joint],
                                },
                            })
                            Util.CharacterJointTransportOnly[joint] = true
                        end
                    end
                end
            end
            pdHeadFollower.NeckRevision = index.Revision
        end
        local motorCount, unsupportedClass = 0, nil
        for _, channel in ipairs(pdHeadFollower.NeckChannels) do
            local joint = channel.Joint
            local p0, p1 = Util.GetCharacterJointParts(joint)
            if joint.Parent and ((p0 == torso and p1 == head) or (p0 == head and p1 == torso)) then
                if joint:IsA("Motor6D") then motorCount += 1
                else unsupportedClass = joint.ClassName end
            end
        end
        if motorCount ~= 1 or unsupportedClass then
            pdHeadFollower.JointClass = unsupportedClass or (motorCount > 0 and "Motor6D" or nil)
            pdHeadFollower.LastBlockedReason = unsupportedClass and ("real Neck is " .. unsupportedClass .. "; Motor6D replication channels unavailable")
                or (motorCount == 0 and "real Neck joint missing" or "multiple real Neck motors; transport is ambiguous")
            return false
        end
        -- Keep the body as this assembly's root. The connected Head receives
        -- no physical CFrame/velocity or local Transform writes. Its original
        -- joint remains connected and is driven only by the transport channels.
        if head.RootPriority~=-127 then head.RootPriority=-127 end
        if head.Massless~=true then head.Massless=true end
        local torsoPriority=backend.KeepBodyChain and not bodyChain.Suspended and 0 or 127
        local torsoMassless=backend.KeepBodyChain == true and not bodyChain.Suspended
        if torso.RootPriority~=torsoPriority then torso.RootPriority=torsoPriority end
        if torso.Massless~=torsoMassless then torso.Massless=torsoMassless end
        -- Derive the intended pose from the controller's torso. Compensating
        -- against a fallen, unowned physical torso hid ownership loss locally
        -- and sent a huge compensating Neck offset instead of the actual pose.
        local basis=backend.AccessoryLifetime.HeadTorsoPose(physical,torso,controllerTorso,bodyPoses)
        if not finiteCFrame(basis) then
            pdHeadFollower.LastBlockedReason = "invalid controller torso pose"
            return false
        end
        local relative = basis:ToObjectSpace(target)
        local wrote, channelsPresent, writeError = false, false, nil
        local torsoRoot, headRoot = torso.AssemblyRootPart or torso, head.AssemblyRootPart or head
        local connectedAssembly = torsoRoot == headRoot
        -- A native false blocks submission. A missing/unsupported probe returns
        -- nil: try the joint channels, but never report ownership from that.
        local assemblyOwned = connectedAssembly and not torsoRoot.Anchored and ownsPhysicalPart(torso, true)
        pdHeadFollower.TransportRoot = torsoRoot
        pdHeadFollower.JointClass = nil
        for _, channel in ipairs(pdHeadFollower.NeckChannels) do
            local joint = channel.Joint
            if joint.Parent then
                local part0, part1 = Util.GetCharacterJointParts(joint)
                if (part0 == torso and part1 == head) or (part0 == head and part1 == torso) then
                    channelsPresent = true
                    pdHeadFollower.JointClass = joint.ClassName
                    local offset = part0 == head and relative:Inverse() or relative
                    -- A local Transform on this joint changes the motor path
                    -- being tested. Rendering never writes the physical Neck.
                    if not joint:IsA("Motor6D") then
                        writeError = "real Neck is " .. joint.ClassName .. "; Motor6D replication channels unavailable"
                    elseif not joint.Enabled then
                        writeError = "original Neck is disabled"
                    elseif not poseOnly and assemblyOwned~=false then
                        local accepted = Util.SetCharacterJointOffset(joint, offset, nil, true)
                        wrote = accepted == true or wrote
                        if accepted ~= true then
                            local stats = Util.CharacterJointReplicationStats
                            local record = stats and stats.Joints and stats.Joints[joint]
                            writeError = record and record.LastError or "Neck replication submission failed"
                        end
                    end
                end
            end
        end
        pdHeadFollower.LastOwned = assemblyOwned
        pdHeadFollower.PositionError = (head.Position - target.Position).Magnitude
        pdHeadFollower.LocalDisplayError = nil
        if poseOnly then
            return channelsPresent and not writeError and pdHeadFollower.LastOwned == true
                and pdHeadFollower.LastSuccessfulWriteAt ~= nil
                and os.clock() - pdHeadFollower.LastSuccessfulWriteAt < .25
                and pdHeadFollower.LastBlockedReason == nil
        end
        pdHeadFollower.LastError = not wrote and writeError or nil
        if not channelsPresent then
            pdHeadFollower.LastBlockedReason = "real Neck joint missing"
            return false
        end
        if writeError and not wrote then
            pdHeadFollower.LastBlockedReason = writeError
            return false
        end
        if not connectedAssembly then
            pdHeadFollower.LastBlockedReason = "real Head and torso are not in the same connected assembly"
            return false
        end
        if pdHeadFollower.LastOwned==false then
            pdHeadFollower.OwnershipLossSince = pdHeadFollower.OwnershipLossSince or os.clock()
            pdHeadFollower.LastBlockedReason = "real torso/head assembly is not owned"
            return false
        end
        if not wrote then pdHeadFollower.LastBlockedReason = "Neck writer rejected target" return false end
        pdHeadFollower.AcceptedWrites += 1
        pdHeadFollower.OwnershipLossSince = nil
        pdHeadFollower.LastTarget, pdHeadFollower.LastSuccessfulWriteAt = target, os.clock()
        pdHeadFollower.LastBlockedReason = nil
        pdHeadFollower.Writes += 1
        return true
    end

    local function writeGelatekPhysicsHead(physical, physicalHead, controllerHead, target, dt, poseOnly, renderOnly)
        if not physical or not physical.Parent or not physicalHead or not physicalHead.Parent
            or not controllerHead or not controllerHead.Parent or not finiteCFrame(target) then
            pdHeadFollower.LastBlockedReason = "missing real/controller Head or invalid target"
            return false
        end
        if poseOnly then
            local ready=pdHeadFollower.Head==physicalHead and pdHeadFollower.Mode=="CFrame-first owned Head"
                and pdHeadFollower.LastOwned==true and ownsPhysicalPart(physicalHead)
                and pdHeadFollower.LastSuccessfulWriteAt~=nil
                and os.clock()-pdHeadFollower.LastSuccessfulWriteAt<.25
                and pdHeadFollower.LastError==nil and pdHeadFollower.LastBlockedReason==nil
            if ready and renderOnly and not physicalHead:IsGrounded()
                and not headStillSharesBodyAssembly(physical,physicalHead) then
                physicalHead.CFrame=target
                pdHeadFollower.LastRenderTarget,pdHeadFollower.LastRenderAt=target,os.clock()
            end
            return ready
        end
        if pdHeadFollower.Head ~= physicalHead or pdHeadFollower.Mode ~= "CFrame-first owned Head" then
            local nativeVelocity = pdHeadFollower.NativeVelocity
            resetPDHeadFollower()
            pdHeadFollower.NativeVelocity = nativeVelocity
            pdHeadFollower.Mode = "CFrame-first owned Head"
            pdHeadFollower.Head = physicalHead
            pdHeadFollower.LastTarget = physicalHead.CFrame
            pdHeadFollower.SavedProperties = {
                RootPriority = physicalHead.RootPriority, Massless = physicalHead.Massless,
                CustomPhysicalProperties = physicalHead.CustomPhysicalProperties,
                CanCollide = physicalHead.CanCollide, CanTouch = physicalHead.CanTouch,
                Anchored = physicalHead.Anchored,
            }
        end
        local humanoid = physical:FindFirstChildOfClass("Humanoid")
        if humanoid and pdHeadFollower.Humanoid ~= humanoid then
            pdHeadFollower.Humanoid = humanoid
            pdHeadFollower.HumanoidConfigured, pdHeadFollower.LifecycleWarning = false, nil
            pdHeadFollower.SavedHumanoid = {
                RequiresNeck = humanoid.RequiresNeck, BreakJointsOnDeath = humanoid.BreakJointsOnDeath,
                AutoRotate = humanoid.AutoRotate,
            }
        end
        pdHeadFollower.PositionError = (physicalHead.Position - target.Position).Magnitude
        local ok, reason = pcall(function()
            if humanoid then
                humanoid.RequiresNeck, humanoid.BreakJointsOnDeath, humanoid.AutoRotate = false, false, false
            end
            -- Release the actual rigid endpoints, not only Enabled. A revived
            -- Neck, upgraded joint or attachment link must not keep this Head
            -- in the corpse assembly. The original handles and their welds stay.
            for _, joint in ipairs(getPhysicalHeadIndex(physical).Joints) do
                if joint.Parent and (joint:IsA("JointInstance") or joint:IsA("WeldConstraint")
                    or joint.ClassName == "AnimationConstraint" or joint.ClassName == "RigidConstraint") then
                    local p0, p1 = Util.GetCharacterJointParts(joint)
                    local attached = joint.ClassName == "RigidConstraint" or joint.ClassName == "AnimationConstraint"
                    if attached and not p0 then
                        p0 = joint.Attachment0 and joint.Attachment0:FindFirstAncestorWhichIsA("BasePart")
                        p1 = joint.Attachment1 and joint.Attachment1:FindFirstAncestorWhichIsA("BasePart")
                    end
                    local other = p0 == physicalHead and p1 or (p1 == physicalHead and p0 or nil)
                    if other and not other:FindFirstAncestorOfClass("Accessory") then
                        if not pdHeadFollower.JointStates[joint] then
                            pdHeadFollower.JointStates[joint] = attached
                                and {Enabled = joint.Enabled ~= false, Attached = true,
                                    Attachment0 = joint.Attachment0, Attachment1 = joint.Attachment1}
                                or {Enabled = joint.Enabled ~= false, Part0 = joint.Part0, Part1 = joint.Part1}
                        end
                        joint.Enabled = false
                        if attached then joint.Attachment1 = nil else joint.Part1 = nil end
                    end
                end
            end
            physicalHead.Anchored, physicalHead.CanCollide, physicalHead.CanTouch = false, false, false
            physicalHead.RootPriority, physicalHead.Massless = 127, false
            physicalHead.CustomPhysicalProperties = pdHeadFollower.SavedProperties.CustomPhysicalProperties
            suspendCompetingHeadMovers(physicalHead)
            if headStillSharesBodyAssembly(physical, physicalHead) then
                if pdHeadFollower.LinearMover then pdHeadFollower.LinearMover.Enabled = false end
                if pdHeadFollower.AngularMover then pdHeadFollower.AngularMover.Enabled = false end
                pdHeadFollower.LastBlockedReason = "waiting for Head/body assembly separation"
                return false
            end
            -- A successful local target assignment is NOT an ownership claim.
            -- Never let an unowned head mark this writer ready and suppress
            -- native recovery. Also never move a still-connected body through it.
            pdHeadFollower.LastOwned = ownsPhysicalPart(physicalHead)
            local marker = physicalHead:FindFirstChild("OwnershipCheck")
            if marker then marker.Transparency = pdHeadFollower.LastOwned and 1 or 0 marker.SurfaceTransparency = 1 end
            if not pdHeadFollower.LastOwned then
                pdHeadFollower.OwnershipLossSince = pdHeadFollower.OwnershipLossSince or os.clock()
                pdHeadFollower.LastBlockedReason = "real Head assembly is not network-owned; remote pose unavailable"
                return false
            end
            pdHeadFollower.OwnershipLossSince = nil
            local antiSleep = options.AntiSleep == true and math.sin(os.clock() * 15) * 0.0015 or 0
            local corrected = target + Vector3.new(0, antiSleep, 0)
            physicalHead.CFrame = corrected
            if not poseOnly then
                -- Pose distance never becomes a chase force or a launch velocity.
                local netless = tonumber(Reanimate.NetlessVelocity) or 25.1
                if netless ~= netless or math.abs(netless) == math.huge then netless = 25.1 end
                netless = math.clamp(netless, 25.01, 50)
                local root = controllerHead.Parent:FindFirstChild("HumanoidRootPart")
                local velocity = root and root.AssemblyLinearVelocity or Vector3.zero
                if not finiteVector3(velocity) then velocity = Vector3.zero end
                local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
                if horizontal.Magnitude > netless then horizontal = horizontal.Unit * netless end
                physicalHead.AssemblyLinearVelocity = Vector3.new(horizontal.X, netless, horizontal.Z)
                physicalHead.AssemblyAngularVelocity = Vector3.zero
            end
            if not pdHeadFollower.RepRootCleared then
                local ok, cleared, reason = pcall(Util.ClearPhysicsRepRootRef, physicalHead)
                pdHeadFollower.RepRootCleared = ok and cleared == true
                if pdHeadFollower.RepRootCleared then
                    pdHeadFollower.RepRootClearError = nil
                else
                    pdHeadFollower.RepRootClearError = tostring(ok and reason or cleared)
                end
            end
            return true
        end)
        pdHeadFollower.LastError = not ok and tostring(reason) or nil
        if not ok or reason ~= true then return false end
        pdHeadFollower.LastTarget, pdHeadFollower.LastSuccessfulWriteAt = target, os.clock()
        pdHeadFollower.LastBlockedReason = nil
        pdHeadFollower.Writes += 1
        pdHeadFollower.OwnedWrites += 1
        for _, accessory in ipairs(getPhysicalHeadIndex(physical).Children) do
            if accessory:IsA("Accessory") then
                local handle = accessory:FindFirstChild("Handle")
                local weld = handle and handle:FindFirstChild("AccessoryWeld")
                if handle and handle:IsA("BasePart") and weld and weld:IsA("JointInstance")
                    and weld.Enabled ~= false and (weld.Part0 == physicalHead or weld.Part1 == physicalHead) then
                    if not pdHeadFollower.AccessoryProperties[handle] then
                        pdHeadFollower.AccessoryProperties[handle] = {RootPriority = handle.RootPriority, Massless = handle.Massless}
                    end
                    handle.RootPriority, handle.Massless = -127, true
                    suspendCompetingHeadMovers(handle)
                end
            end
        end
        return true
    end

    quiesceGelatekFollowerSupport = function(headOnly)
        if not headOnly then
            local pause=environment().UhhhhhhTBZGelatekPauseOwnershipSupport
            if type(pause)=="function" then pcall(pause) end
        end
        -- Stop only movers created by this follower. Pausing or rejecting a
        -- target never rewrites an assembly's linear or angular velocity.
        for _, mover in pairs({pdHeadFollower.LinearMover, pdHeadFollower.AngularMover}) do
            if mover.Parent then pcall(function()
                if mover.Enabled then mover.Enabled = false end
            end) end
        end
        if headOnly then return end
        for _, state in pairs(accessoryRecoveryStates) do
            if state.Managed then pcall(function()
                if state.LinearMover and state.LinearMover.MaxForce ~= Vector3.zero then
                    state.LinearMover.MaxForce = Vector3.zero
                end
                if state.AngularMover and state.AngularMover.MaxTorque ~= Vector3.zero then
                    state.AngularMover.MaxTorque = Vector3.zero
                end
            end) end
        end
    end

    local function updateGelatekBodyChain(rig, dt, poseOnly, bodyPoses, phase)
        if not backend.Running or rebindInProgress or not rig or not rig.Parent
            or environment().UhhhhhhTBZGelatekFollowersPaused then
            pdHeadFollower.LastBlockedReason = "bridge paused or controller missing"
            return false
        end
        local physical = backend.RealCharacter or originalCharacter
        if not physical or not physical.Parent then
            pdHeadFollower.LastBlockedReason = "real character missing"
            return false
        end
        local controllerHead = rig:FindFirstChild("Head")
        local head = physical and physical.Parent and physical:FindFirstChild("Head")
        pdHeadFollower.UpdateResetHandoff(physical, head)
        if backend.EffectivePermanentDeath then
            backend.AccessoryLifetime.DetachBodyChainForPD(physical)
            if not backend.AccessoryLifetime.PDBodyIsDetached(physical) then
                pdHeadFollower.LastBlockedReason="waiting for PD body assembly separation"
                return false
            end
        end
        bodyPoses=bodyPoses or backend.AccessoryLifetime.ControllerBodyPoses(rig,poseOnly and options.ShowMeHowILook~=true)
        if not controllerHead or not head then
            pdHeadFollower.LastBlockedReason = "real or controller Head missing"
            quiesceGelatekFollowerSupport(true)
            return false
        end
        if environment().UhhhhhhTBZGelatekPDTransitionPending then
            pdHeadFollower.LastBlockedReason = "follower handoff paused"
            return false
        end
        if backend.EffectivePermanentDeath == true and environment().UhhhhhhTBZGelatekPermaReady ~= true then
            pdHeadFollower.LastBlockedReason = "PD handoff not ready"
            return false
        end
        local detached = pdHeadFollower.IsDetachedFromBody(physical, head)
        local target = backend.AccessoryLifetime.ControllerBodyPose(controllerHead, bodyPoses)
        target=backend.AccessoryLifetime.ResolveHeadTarget(physical,controllerHead,target,bodyPoses)
        local requestedHide = type(Reanimate.ShouldBodyHidePart) == "function" and Reanimate.ShouldBodyHidePart("Head") == true
        local hidden = backend.AccessoryLifetime.HeadHideReady(physical, head, requestedHide)
        if hidden and type(Reanimate.ResolveBodyHideTargetCFrame) == "function" then
            target = Reanimate.ResolveBodyHideTargetCFrame(head, target, "Head", false)
        end
        local controllerTorso = rig:FindFirstChild("UpperTorso") or rig:FindFirstChild("Torso")
        local anchor = (backend.EffectivePermanentDeath == true or detached)
            and rig:FindFirstChild("HumanoidRootPart") or controllerTorso
        local basis = anchor and backend.AccessoryLifetime.ControllerBodyPose(anchor, bodyPoses)
        local realTorso = physical:FindFirstChild("UpperTorso") or physical:FindFirstChild("Torso")
        if anchor==controllerTorso and realTorso and finiteCFrame(basis) then
            basis=backend.AccessoryLifetime.HeadTorsoPose(physical,realTorso,controllerTorso,bodyPoses)
        end
        local now, sample = os.clock(), nil
        if finiteCFrame(basis) and finiteCFrame(target) then
            local relative = basis:ToObjectSpace(target)
            -- Roblox handles transport cadence. A local 20 Hz sample-and-hold
            -- made smooth Neck animation visibly step, even with frame smoothing.
            sample = {Head=head, Anchor=anchor, Offset=relative, At=now,
                Show=options.ShowMeHowILook == true, Hidden=hidden, Detached=detached,
                PD=backend.EffectivePermanentDeath}
        end
        pdHeadFollower.FrameTarget,pdHeadFollower.FramePoses,pdHeadFollower.FrameHidden=target,bodyPoses,hidden
        local written
        if (backend.EffectivePermanentDeath == true or detached)
            and not backend.AccessoryLifetime.RetainedR15Neck(physical,head) then
            written = writeGelatekPhysicsHead(physical, head, controllerHead, target, dt, poseOnly,phase=="RenderPose")
            pdHeadFollower.Route = backend.EffectivePermanentDeath == true and "PD" or "detached Head recovery"
        else
            written = writeGelatekCurrentAngleHead(physical, head, target,
                controllerTorso, bodyPoses, poseOnly and phase~="PreSimulation")
            pdHeadFollower.Route = backend.EffectivePermanentDeath and "connected R15 PD Neck" or "connected non-PD joint"
        end
        if written and not poseOnly then
            pdHeadFollower.SampledTarget = target
            pdHeadFollower.RelativeSample = sample
            backend.HeadHideApplied = hidden
            if backend.HeadHideAccessoryRestorePending and (head.Position - controllerHead.Position).Magnitude <= 4 then
                backend.AccessoryLifetime.RollbackHeadHide()
            end
        end
        return written
    end

    local function pdHeadWriterIsCurrent(head)
        return pdHeadFollower.Mode == "CFrame-first owned Head" and not rebindInProgress and head ~= nil and head.Parent ~= nil
            and pdHeadFollower.Head == head and pdHeadFollower.LastSuccessfulWriteAt ~= nil
            and os.clock() - pdHeadFollower.LastSuccessfulWriteAt < 0.25
            and pdHeadFollower.LastError == nil and pdHeadFollower.LastBlockedReason == nil
            and pdHeadFollower.LastOwned == true and ownsPhysicalPart(head)
            and not headStillSharesBodyAssembly(backend.RealCharacter or originalCharacter, head)
    end
    local function stepGelatekHeadBridge(rig, dt, phase, bodyPoses)
        if phase~="PreSimulation" and phase~="RenderPose" then
            backend.AccessoryLifetime.Service(rig,backend.RealCharacter or originalCharacter)
        end
        local headOk, result = pcall(updateGelatekBodyChain, rig, dt,
            phase=="PreSimulation" or phase=="RenderPose" or phase=="ControllerPose",bodyPoses,phase)
        pdHeadFollower.LastStepAt, pdHeadFollower.LastPhase = os.clock(), phase
        if not headOk then pdHeadFollower.LastError = tostring(result) end
        if not headOk or result ~= true then quiesceGelatekFollowerSupport(true) end
        environment().UhhhhhhTBZGelatekPDHeadWriterActive = headOk and result == true
            and pdHeadWriterIsCurrent(pdHeadFollower.Head) or false
        return headOk and result == true
    end

    local function resolveGelatekAccessoryTargetCFrame(handle, controllerHandle, bodyPoses)
        local targetCFrame = backend.AccessoryLifetime.ControllerPose(controllerHandle, nil, nil, bodyPoses) or controllerHandle.CFrame
        local physical=backend.RealCharacter or originalCharacter
        local index=getPhysicalHeadIndex(physical)
        local record=index.AccessoryRecords and index.AccessoryRecords[handle.Parent]
        local binding=accessoryWeldBindings[handle]
        local baseline=record and record.TargetBaseline
        local joint,anchor=backend.AccessoryLifetime.ControllerJoint(controllerHandle)
        local physicalAnchor=binding and binding.AnchorName and physical and physical:FindFirstChild(binding.AnchorName)
        if baseline and binding and physicalAnchor and joint and anchor and anchor.Parent==backend.Rig
            and baseline.AnchorName==anchor.Name then
            local anchorPose=backend.AccessoryLifetime.ControllerBodyPose(anchor,bodyPoses)
            local desired=anchorPose
            if physicalAnchor.Name~=anchor.Name then desired*=scaledRecoveryOffset(backend.AccessoryLifetime.BodyAnchorOffset(physicalAnchor.Name)) end
            desired=backend.AccessoryLifetime.ResolveAnimationPose(physicalAnchor,anchor,desired,bodyPoses)
            local hidden=backend.HeadHideApplied
            if pdHeadFollower.FramePoses==bodyPoses then hidden=pdHeadFollower.FrameHidden end
            if physicalAnchor.Name=="Head" and hidden~=true then
                if ownsPhysicalPart(physicalAnchor) then
                    -- Use the same current animation sample as the Head. The
                    -- previous observed-Head retarget delayed the working hat.
                    if pdHeadFollower.FramePoses==bodyPoses and finiteCFrame(pdHeadFollower.FrameTarget)then
                        desired=pdHeadFollower.FrameTarget
                    end
                else
                    if not finiteCFrame(physicalAnchor.CFrame)then return nil end
                    desired=physicalAnchor.CFrame
                end
            end
            local function localMount(saved)
                local transform=saved.ClassName=="Motor6D" and saved.Transform or CFrame.identity
                if saved.HandleIsPart0==false then return saved.C0*transform*saved.C1:Inverse() end
                return saved.C1*(saved.C0*transform):Inverse()
            end
            -- Preserve live accessory animation as an anchor-space delta, but
            -- use the original avatar's mount instead of an R6 head's offset.
            local liveLocal=anchorPose:ToObjectSpace(targetCFrame)
            targetCFrame=desired*liveLocal*localMount(baseline):Inverse()*localMount(binding)
        end
        local global = environment()
        local resolver = global.UhhhhhhTBZGetBodyHideTargetInfo

        if type(resolver) == "function" then
            local ok, shouldHide, anchorName =
                pcall(resolver, handle, controllerHandle, nil, true)
            if ok and shouldHide == true
                and type(Reanimate.ResolveBodyHideTargetCFrame) == "function"
            then
                targetCFrame =
                    Reanimate.ResolveBodyHideTargetCFrame(
                        handle,
                        targetCFrame,
                        anchorName,
                        false
                    )
            end
        end
        return targetCFrame
    end

    local function restoreAccessoryRecoveryState(handle, state)
        PhysicsRoot.Release(handle)
            if type(state) == "table" then
                if state.LinearMover then state.LinearMover:Destroy() end
                if state.AngularMover then state.AngularMover:Destroy() end
                for mover, properties in pairs(state.ExternalMovers or {}) do
                    if mover.Parent then for key, value in pairs(properties) do mover[key] = value end end
                end
            end
            if handle and handle.Parent and type(state) == "table" then
                pcall(function()
                    if state.Massless ~= nil then
                        handle.Massless = state.Massless
                    end
                    handle.CustomPhysicalProperties =
                        state.CustomPhysicalProperties
                    if state.RootPriority ~= nil then handle.RootPriority = state.RootPriority end
                    if state.Anchored ~= nil then handle.Anchored = state.Anchored end
                    if state.CanCollide ~= nil then handle.CanCollide = state.CanCollide end
                    if state.CanTouch ~= nil then handle.CanTouch = state.CanTouch end
                end)
            end
            if type(state) == "table" and state.Weld and state.Weld.Parent then
                local weld = state.Weld
                weld.Enabled = false
                local binding = accessoryWeldBindings[handle]
                if binding and binding.Part0 and binding.Part0.Parent
                    and binding.Part1 and binding.Part1.Parent then
                    weld.Part0, weld.Part1 = binding.Part0, binding.Part1
                    weld.C0, weld.C1 = binding.C0, binding.C1
                    if weld:IsA("Motor6D") and binding.Transform then weld.Transform = binding.Transform end
                end
                -- Place only a separate, owned Handle on the saved weld's
                -- exact solution before merging it with the visible Head.
                if state.WeldEnabled then snapAccessoryHandleToWeld(handle, weld) end
                weld.Enabled = state.WeldEnabled
            end
    end
    function backend.AccessoryLifetime.RestoreManaged(handle, state)
        restoreAccessoryRecoveryState(handle, state)
        accessoryRecoveryStates[handle] = nil
    end
    restoreAccessoryRecoveryStates = function()
        for handle, state in pairs(accessoryRecoveryStates) do restoreAccessoryRecoveryState(handle, state) end
        table.clear(accessoryRecoveryStates)
    end

    local function writeCFrameGelatekAccessory(pair, dt, poseOnly, bodyPoses)
        local handle, controller = pair.Physical, pair.Controller
        if not handle or not handle.Parent or not controller or not controller.Parent then return false end
        if environment().UhhhhhhTBZGelatekFollowersPaused then return false end
        local state = accessoryRecoveryStates[handle]
        local target = resolveGelatekAccessoryTargetCFrame(handle, controller, bodyPoses)
        if not finiteCFrame(target) then
            if state and not poseOnly then
                state.LastBlockedReason = "invalid controller accessory pose"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            return false
        end
        if poseOnly then
            if not state or not state.Managed or state.LastBlockedReason
                or ownsPhysicalPart(handle,true)~=true or handle:IsGrounded()then return false end
            local root=handle.AssemblyRootPart
            if not root then return false end
            for _,part in ipairs(getPhysicalHeadIndex(backend.RealCharacter or originalCharacter).BodyParts)do
                if part.AssemblyRootPart==root then return false end
            end
            local weld=handle:FindFirstChild("AccessoryWeld")
            if weld and weld:IsA("JointInstance")and weld.Enabled~=false then return false end
            handle.CFrame=target
            state.LastRenderTarget,state.LastRenderAt=target,os.clock()
            return true
        end
        local initiallyOwned=ownsPhysicalPart(handle,true)
        if (not state or not state.Managed) and initiallyOwned~=true then
            state=state or {Managed=false,Writes=0}
            accessoryRecoveryStates[handle]=state
            state.Controller,state.LastOwned=controller,initiallyOwned
            state.LastBlockedReason="waiting for native accessory ownership before detaching"
            state.Policy=backend.AccessoryLifetime.DetachReason(handle) or "lost or hidden binding"
            return false
        end
        if not state or not state.Managed then
            state = {Managed = true, LastCFrame = handle.CFrame, Writes = 0, ExternalMovers = {},
                RootPriority = handle.RootPriority, Massless = handle.Massless,
                CustomPhysicalProperties = handle.CustomPhysicalProperties,
                Anchored = handle.Anchored, CanCollide = handle.CanCollide, CanTouch = handle.CanTouch,
                Physics = PhysicalProperties.new(0.05, 0, 0, 0, 0)}
            accessoryRecoveryStates[handle] = state
            local binding = accessoryWeldBindings[handle]
            if binding then
                if binding.RootPriority ~= nil then state.RootPriority = binding.RootPriority end
                if binding.Massless ~= nil then state.Massless = binding.Massless end
            end
        end
        state.Controller = controller
        state.Policy=backend.AccessoryLifetime.DetachReason(handle) or "lost or hidden binding"
        local weld = handle:FindFirstChild("AccessoryWeld")
        if weld and weld:IsA("JointInstance") then
            if state.Weld ~= weld then
                state.Weld, state.WeldEnabled = weld, weld.Enabled ~= false
                local binding = accessoryWeldBindings[handle]
                if binding then state.WeldEnabled = binding.Enabled end
            end
            if weld.Enabled~=false then
                weld.Enabled = false
                state.DetachedAt=state.DetachedAt or os.clock()
            end
        end
        local index, root = getPhysicalHeadIndex(backend.RealCharacter or originalCharacter), handle.AssemblyRootPart
        local sharesBody = root == nil
        for _, part in ipairs(index.BodyParts) do
            if part.AssemblyRootPart == root then sharesBody = true break end
        end
        local assemblyAccessory = root and root:FindFirstAncestorOfClass("Accessory")
        if assemblyAccessory and assemblyAccessory ~= handle.Parent then sharesBody = true end
        if sharesBody then
            if state.LinearMover then state.LinearMover.MaxForce = Vector3.zero end
            if state.AngularMover then state.AngularMover.MaxTorque = Vector3.zero end
            state.LastBlockedReason = "waiting for accessory/body assembly separation"
            state.SampleCFrame, state.SampleAt = nil, nil
            return false
        end
        -- No head-only exception: hair, face, neck, back and other handles all
        -- use their original server part and exact invisible-controller target.
        for _, mover in ipairs(index.Movers) do
            if mover.Parent == handle and mover ~= state.LinearMover and mover ~= state.AngularMover then
                local property, replacement
                if mover:IsA("BodyVelocity") or mover:IsA("BodyPosition") then property, replacement = "MaxForce", Vector3.zero
                elseif mover:IsA("BodyAngularVelocity") or mover:IsA("BodyGyro") then property, replacement = "MaxTorque", Vector3.zero
                else property, replacement = "Enabled", false end
                if not state.ExternalMovers[mover] then state.ExternalMovers[mover] = {[property] = mover[property]} end
                mover[property] = replacement
            end
        end
        handle.Anchored, handle.CanCollide, handle.CanTouch = false, false, false
        handle.RootPriority, handle.Massless = 127, false
        handle.CustomPhysicalProperties = state.Physics
        -- This path has no velocity/position chase mover. Copy the original
        -- server handle only once it has its own, locally owned assembly.
        for _, key in ipairs({"LinearMover", "AngularMover"}) do
            if state[key] then state[key]:Destroy(); state[key] = nil end
        end
        state.LastOwned = ownsPhysicalPart(handle,true)
        state.OwnershipSource = state.LastOwned==nil and "native ownership unavailable"
            or state.LastOwned and "owned assembly" or "unowned assembly"
        if state.LastOwned~=true then
            state.OwnershipLossSince=state.OwnershipLossSince or os.clock()
            state.LastBlockedReason = "accessory assembly is not network-owned"
            state.SampleCFrame, state.SampleAt = nil, nil
            return false
        end
        if state.OwnershipLossSince then state.OwnershipRecoveries=(state.OwnershipRecoveries or 0)+1 end
        state.OwnershipLossSince=nil
        local now = os.clock()
        local netless = tonumber(Reanimate.NetlessVelocity) or 25.1
        if netless ~= netless or math.abs(netless) == math.huge then netless = 25.1 end
        netless = math.clamp(netless, 25.01, 50)
        local rig = controller:FindFirstAncestorOfClass("Model")
        local rootPart = rig and rig:FindFirstChild("HumanoidRootPart")
        local velocity = rootPart and rootPart.AssemblyLinearVelocity or Vector3.zero
        if not finiteVector3(velocity) then velocity = Vector3.zero end
        local angular = Vector3.zero
        local elapsed = state.SampleAt and now - state.SampleAt or 0
        if finiteCFrame(state.SampleCFrame) and elapsed > 1e-5 and elapsed <= .25 then
            local displacement = target.Position - state.SampleCFrame.Position
            -- A teleport/hide transition is a discontinuity, not a launch impulse.
            if displacement.Magnitude <= math.max(6, netless * elapsed * 4) then
                velocity = displacement / elapsed
                if not finiteVector3(velocity) then velocity = Vector3.zero end
                if Reanimate.UseAngularVelocity == true then
                    local axis, angle = (target.Rotation * state.SampleCFrame.Rotation:Inverse()):ToAxisAngle()
                    if finiteVector3(axis) and angle == angle and math.abs(angle) < math.huge then
                        angular = axis * math.min(angle / elapsed, 40)
                        if not finiteVector3(angular) then angular = Vector3.zero end
                    end
                end
            end
        end
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
        if horizontal.Magnitude > netless then horizontal = horizontal.Unit * netless end
        handle.AssemblyLinearVelocity = Vector3.new(horizontal.X, netless, horizontal.Z)
        handle.AssemblyAngularVelocity = angular
        local antiSleep = options.AntiSleep and math.sin(now * 15) * .0015 or 0
        handle.CFrame = target + Vector3.new(0, antiSleep, 0)
        local clearOk, cleared, clearReason = pcall(Util.ClearPhysicsRepRootRef, handle)
        state.RepRootCleared = clearOk and cleared == true
        state.RepRootClearError = not state.RepRootCleared and tostring(clearOk and (clearReason or "root reference clear unverified") or cleared) or nil
        state.SampleCFrame, state.SampleAt = target, now
        state.LinearVelocity, state.AngularVelocity = handle.AssemblyLinearVelocity, angular
        state.LastCFrame, state.LastBlockedReason, state.LastWriteError = target, nil, nil
        state.LastSuccessfulWriteAt = now
        state.Writes += 1
        return true
    end

    local function writeDetachedGelatekAccessory(pair, dt, poseOnly, bodyPoses)
        local handle = pair and pair.Physical
        local controllerHandle = pair and pair.Controller
        if pair and pair.Lifetime and (pair.Lifetime.SourceDestroyed or pair.Lifetime.HandleDestroyed) then
            local state=handle and accessoryRecoveryStates[handle]
            if state then state.LastBlockedReason=pair.Lifetime.Blocked end
            return false
        end
        if not handle
            or not handle:IsA("BasePart")
            or not handle.Parent
            or not controllerHandle
            or not controllerHandle:IsA("BasePart")
            or not controllerHandle.Parent
        then
            local state = handle and accessoryRecoveryStates[handle]
            if state then
                state.LastBlockedReason = "missing real or controller accessory Handle"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            return false
        end
        -- Core transport is not permission to sever an intact real weld.
        -- Preserve the original assembly unless
        -- the user explicitly enabled detachment or this handle is hidden.
        local resolver = environment().UhhhhhhTBZShouldDetachAccessoryForBodyHide
        local hiddenOk, hidden = false, false
        if type(resolver) == "function" then hiddenOk, hidden = pcall(resolver, handle, controllerHandle) end
        local binding = accessoryWeldBindings[handle]
        local detachRequested=shouldDetachHeadAccessory(handle)
        if poseOnly then
            if not detachRequested and not(hiddenOk and hidden==true)then return false end
            return writeCFrameGelatekAccessory(pair,dt,true,bodyPoses)
        end
        local rollback = not detachRequested and binding and binding.AnchorName == "Head"
            and backend.HeadHideAccessoryRestorePending
        if rollback then
            local state = accessoryRecoveryStates[handle]
            if state then
                state.LastOwned = ownsPhysicalPart(handle) state.LastBlockedReason = "accessory handoff paused"
                state.SampleCFrame, state.SampleAt = nil, nil
            end
            if not (binding and binding.AnchorName == "Head" and backend.HeadHideApplied) then
                if state and state.Weld and state.Weld.Parent then backend.AccessoryLifetime.RestoreManaged(handle, state) end
            end
            local weld = handle:FindFirstChild("AccessoryWeld")
            if weld and weld:IsA("JointInstance") then return false end
        end
        if not detachRequested and not (hiddenOk and hidden == true and not rollback) then
            local state = accessoryRecoveryStates[handle]
            if state and state.Managed and state.Weld and state.Weld.Parent then
                restoreAccessoryRecoveryState(handle, state)
                accessoryRecoveryStates[handle] = nil
                repairAccessoryWeldBindings()
            end
            local weld = handle:FindFirstChild("AccessoryWeld")
            if weld and weld:IsA("JointInstance") and weld.Enabled ~= false
                and weld.Part0 and weld.Part0.Parent and weld.Part1 and weld.Part1.Parent then
                return false
            end
        end
        local ok, result = pcall(writeCFrameGelatekAccessory, pair, dt, poseOnly, bodyPoses)
        if not ok then
            local state = accessoryRecoveryStates[handle]
            if state then state.LastWriteError = tostring(result) end
            backend.AccessoryTransportError = tostring(result)
        end
        return ok and result == true
    end

    local function attachScaleBridge(rig)
        detachScaleBridge()
        backend.LastControllerPoseAt = nil
        local bridgeToken = activeGenerationToken
        assert(bridgeToken ~= nil, "Gelatek bridge has no generation owner")
        local function bridgeIsActive()
            return generationIsActive(bridgeToken, rig)
        end
        local global = environment()
        global.UhhhhhhTBZGelatekControllerBodyPose = function(part)
            if bridgeIsActive() and part and part.Parent == rig then
                return backend.AccessoryLifetime.ControllerBodyPose(part)
            end
            return nil
        end
        global.UhhhhhhTBZGelatekConnectedBodyRoot = function(part)
            if not bridgeIsActive() then return nil end
            local physical=backend.RealCharacter or originalCharacter
            local root=backend.AccessoryLifetime.ConnectedBodyRoot(physical,part)
            return root
        end
        global.UhhhhhhTBZGelatekPDHeadWriterActive = false
        global.UhhhhhhTBZGelatekPDHeadWriterReady = function(head)
            return bridgeIsActive() and pdHeadWriterIsCurrent(head)
        end
        global.UhhhhhhTBZRestoreRepRoots = function()
            restoreGelatekTorsoWriter()
            restoreGelatekRootRepRoot()
            PhysicsRoot.RestoreAll()
        end
        global.UhhhhhhTBZGelatekTorsoWriter = function(
            physicalPart,
            controllerPart,
            targetCFrame
        )
            if not bridgeIsActive()
                or typeof(physicalPart) ~= "Instance"
                or not (
                    physicalPart.Name == "Torso"
                    or physicalPart.Name == "UpperTorso"
                    or physicalPart.Name == "LowerTorso"
                )
            then
                return false
            end
            if backend.KeepBodyChain and not bodyChain.Suspended then
                return true -- root + CurrentAngle own this connected assembly
            end
            return writeGelatekTorso(
                rig,
                physicalPart,
                controllerPart,
                targetCFrame
            )
        end
        if replicationWriters.GelatekTorso == "PhysicsRepRootRef"
            and gelatekTorsoWriterBlocked()
        then
            backend.TorsoRepRootLastError =
                "disabled by a torso/bullet fling mode"
            backend.TorsoRepRootWarned = true
            Util.Notify("Torso replication link paused by the active Gelatek mode")
        end
        attachPhysicalAnimationSuppression(
            backend.RealCharacter or originalCharacter
        )
        applyCharacterScale(rig, true)
        controllerSettingsCleanup = Context.ControllerSettings({
            Rig = rig, Reanimate = Reanimate, RunService = RunService,
        })
        local generationSafePivot = rig:GetPivot()
        local initialRoot = rig:FindFirstChild("HumanoidRootPart")
        assert(
            initialRoot and initialRoot:IsA("BasePart"),
            "Gelatek controller lost HumanoidRootPart before bridge attachment"
        )
        local floatSafeY = initialRoot.Position.Y
        scaleBridgeConnection = RunService.Heartbeat:Connect(function()
            if not bridgeIsActive() then
                return
            end
            Reanimate.GelatekDisableDirectionalWalking =
                options.DisableDirectionalWalking == true
            applyCharacterScale(rig)
            updateInfiniteJump(rig)
            global.UhhhhhhTBZGelatekAntiSleep = options.AntiSleep == true
            if backend.EffectivePermanentDeath == true
                or Reanimate.UsePhysicsRepRootPart == false
                or gelatekTorsoWriterBlocked()
                or replicationWriters.GelatekTorso ~= "PhysicsRepRootRef"
                or global.UhhhhhhTBZGelatekFlingActive == true
            then
                restoreGelatekTorsoWriter()
            else
                local physical = backend.RealCharacter or originalCharacter
                local physicalRoot = global.UhhhhhhTBZGelatekPhysicalRoot
                local controllerTorso = rig:FindFirstChild("Torso")
                    or rig:FindFirstChild("UpperTorso")
                if not physical
                    or not physical.Parent
                    or typeof(physicalRoot) ~= "Instance"
                    or not physicalRoot.Parent
                    or not ownsPhysicalPart(physicalRoot)
                    or not controllerTorso
                then
                    restoreGelatekTorsoWriter()
                else
                    local rootOffset = physical:FindFirstChild("UpperTorso")
                        and CFrame.new(0, 0.194 * characterScale(), 0)
                        or CFrame.identity
                    local expectedRoot = controllerTorso.CFrame * rootOffset
                    if (physicalRoot.Position - expectedRoot.Position).Magnitude
                        > math.max(12 * characterScale(), 8)
                    then
                        restoreGelatekTorsoWriter()
                    end
                end
            end
        end)

        -- Compatibility notification for controller tracking. The independent
        -- phase callbacks below consume its completed controller pose.
        global.UhhhhhhTBZGelatekRenderHeadSync = function()
            if not bridgeIsActive() or rebindInProgress then
                return false
            end
            -- Tracking already changed the controller Head; this function
            -- reports readiness without introducing another writer.
            return pdHeadWriterIsCurrent(pdHeadFollower.Head)
        end

        -- Shared maintenance owns weld repair/hiding; it is invalidated by rig
        -- changes and switches, and does not run a second full accessory scan.

        -- The controller owns locomotion; follower contacts stay separate.
        local collisionErrorReported = false
        controllerCollisionConnection = RunService.PreSimulation:Connect(function(dt)
            if not bridgeIsActive() then
                return
            end
            enforcePhysicalShellIsolation(backend.RealCharacter or originalCharacter)
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if not humanoid or not root then
                return
            end
            local stateName = "Physics"
            local collisionOk, collisionResult, colliders = pcall(
                backend.AccessoryLifetime.ApplyControllerCollision,
                rig,
                humanoid,
                root,
                controllerBodyNames
            )
            if collisionOk and type(collisionResult) == "string" then
                stateName = collisionResult
            else
                local stateOk, state = pcall(humanoid.GetState, humanoid)
                if stateOk and state then
                    stateName = state.Name
                end
                if not collisionOk and not collisionErrorReported then
                    collisionErrorReported = true
                    warn("Gelatek collision bridge recovered: " .. tostring(collisionResult))
                end
            end
            backend.AccessoryLifetime.IsolateControllerContacts(rig,backend.RealCharacter or originalCharacter,colliders)
            local passive = not table.find(
                {"Running", "Jumping", "Freefall", "Landed", "Climbing", "Swimming"}, stateName)
            if options.RagdollSelfCollision == false and passive then
                if not ragdollCollisionFolder then
                    ragdollCollisionFolder = Instance.new("Folder")
                    ragdollCollisionFolder.Name = "_UhhhhhhOptionalRagdollSelfCollision"
                    ragdollCollisionFolder.Parent = rig
                    local parts = {}
                    for _, part in ipairs(rig:GetChildren()) do
                        if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                            table.insert(parts, part)
                        end
                    end
                    for i, part in ipairs(parts) do
                        for j = i + 1, #parts do
                            local exclusion = Instance.new("NoCollisionConstraint")
                            exclusion.Part0, exclusion.Part1 = part, parts[j]
                            exclusion.Parent = ragdollCollisionFolder
                        end
                    end
                end
            elseif ragdollCollisionFolder then
                ragdollCollisionFolder:Destroy()
                ragdollCollisionFolder = nil
            end
            if rebindInProgress then
                isolatePhysicalCharacter(pendingPhysicalCharacter)
            end
            if options.RecoverBeforeVoid then
                local floor = environment().UhhhhhhTBZGelatekDestroyHeight or -500
                -- A detached limb below the root must not repeatedly teleport
                -- the whole ragdoll while its controller root is still safe.
                local predictedY = root.Position.Y
                    + math.min(root.AssemblyLinearVelocity.Y, 0) * math.clamp(dt or 0, 0, 0.25)
                if math.min(root.Position.Y, predictedY) < floor + 80 then
                    -- Move the whole controller, including jointless parts.
                    pcall(function()
                        rig:PivotTo(generationSafePivot + Vector3.new(0, 3, 0))
                        for _, part in ipairs(rig:GetChildren()) do
                            if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                                part.AssemblyLinearVelocity = Vector3.zero
                                part.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                    end)
                end
            end
            pcall(function()
                rig:SetAttribute(
                    "_Uhhhhhh_SeatWeldActive",
                    stateName == "Seated" and (humanoid.Sit or humanoid.SeatPart ~= nil)
                )
            end)
        end)

        local safeParams = RaycastParams.new()
        safeParams.FilterType = Enum.RaycastFilterType.Exclude
        safeParams.RespectCanCollide = true
        safeParams.IgnoreWater = false
        safeTrackerConnection = RunService.PostSimulation:Connect(function()
            if not bridgeIsActive() or rebindInProgress then
                return
            end
            local humanoid = rig:FindFirstChildOfClass("Humanoid")
            local root = rig:FindFirstChild("HumanoidRootPart")
            if not humanoid or not root or not root:IsA("BasePart") then
                return
            end

            -- Excluding rig excludes both the controller and Gelatek's nested
            -- physical Character. Non-collidable helper parts are ignored by
            -- RespectCanCollide, so they cannot become LastSafe.
            safeParams.FilterDescendantsInstances = { rig }
            local scale = math.max(tonumber(Reanimate.CharacterScale) or 1, 0.001)
            local maximumGroundDistance = 3 * scale + 8 + humanoid.HipHeight
            local safe = true
            local void = true
            for i = 1, 8 do
                local offset =
                    CFrame.Angles(0, (i / 4) * math.pi, 0)
                        :VectorToWorldSpace(Vector3.new(0, 0, -0.5 * scale))
                local hit = workspace:Raycast(
                    root.Position + offset,
                    Vector3.new(0, -65536, 0),
                    safeParams
                )
                if hit then
                    void = false
                end
                if not hit or hit.Distance > maximumGroundDistance then
                    safe = false
                end
            end
            if safe then
                Reanimate.LastSafeCFrame = root.CFrame
                generationSafePivot = rig:GetPivot()
            end
            local stateOk, state = pcall(humanoid.GetState, humanoid)
            if (stateOk and state.Name == "Climbing") or not void then
                floatSafeY = root.Position.Y
            elseif Reanimate.PatchmaVoidFloat then
                -- Same no-ground-below trigger as Limb; translate the whole
                -- controller to retain relative jointless/ragdoll poses.
                pcall(function()
                    rig:PivotTo(rig:GetPivot() + Vector3.new(0, floatSafeY - root.Position.Y, 0))
                    for _, part in ipairs(rig:GetChildren()) do
                        if part:IsA("BasePart") and controllerBodyNames[part.Name] then
                            part.AssemblyLinearVelocity *= Vector3.new(1, 0, 1)
                        end
                    end
                end)
            end
        end)

        -- The core already corrects every owned body follower after simulation.
        -- Recovery runs only if that generation's core step failed, rather than
        -- writing an older pose over each limb before every physics step.
        limbRecoveryConnection = RunService.PostSimulation:Connect(function()
            if not bridgeIsActive() or rebindInProgress or environment().UhhhhhhTBZGelatekFollowersPaused then
                return
            end
            if not environment().UhhhhhhTBZGelatekBodyStepError then return end
            local physical = backend.RealCharacter
            if not physical or not physical.Parent then
                return
            end

            local threshold = math.clamp(tonumber(options.PhysicalRecoveryDistance) or 25, 0, 50)
            local bodyPoses=backend.AccessoryLifetime.ControllerBodyPoses(rig,phase~="PostSimulation" and options.ShowMeHowILook~=true)
            for _, pair in ipairs(getGelatekRecoveryPairs(rig, physical)) do
                local physicalPart = pair.Physical
                local controllerPart = pair.Controller
                if physicalPart.Parent
                    and controllerPart.Parent
                    and pair.Name ~= "Head"
                    and pair.IsAccessory ~= true
                    and not backend.AccessoryLifetime.ConnectedBodyRoot(physical,physicalPart)
                    and not (backend.KeepBodyChain
                        and (pair.Name=="Torso" or pair.Name=="LowerTorso" or pair.Name=="UpperTorso"))
                    and ownsPhysicalPart(physicalPart)
                    and (
                        pair.IsAccessory == true
                        or not bodyPartIsIntentionallyHidden(
                            physicalPart,
                            controllerPart
                        )
                    )
                then
                    local targetCFrame = backend.AccessoryLifetime.ControllerBodyPose(controllerPart,bodyPoses) * pair.Offset
                    targetCFrame=backend.AccessoryLifetime.ResolveAnimationPose(physicalPart,controllerPart,targetCFrame)
                    if pair.IsAccessory == true then
                        targetCFrame = resolveGelatekAccessoryTargetCFrame(physicalPart, controllerPart)
                    end
                    if not finiteCFrame(targetCFrame) then continue end
                    local positionError =
                        (physicalPart.Position - targetCFrame.Position).Magnitude

                    local pushRecoveryDistance = threshold
                    local torsoWriterOwnsCorrection = pair.DirectOnly == true
                        and backend.EffectivePermanentDeath ~= true
                        and replicationWriters.GelatekTorso == "PhysicsRepRootRef"
                    if options.DirectPositionCorrection == true
                        and not torsoWriterOwnsCorrection
                    then
                        -- Independent of Gelatek CFrame-vs-Align mode. Use the full
                        -- follower pose for owned detached pieces so an occluder cannot
                        -- leave the physical shell translated/rotated away from target.
                        pcall(function()
                            physicalPart.CFrame = targetCFrame
                        end)
                    elseif pair.DirectOnly ~= true
                        and positionError >= pushRecoveryDistance
                    then
                        pcall(function()
                            physicalPart.CFrame = targetCFrame
                        end)
                    end
                end
            end
        end)

        -- Keep outgoing velocity samples in PostSimulation. Late rendering
        -- follows the current joint graph without advancing physics history.
        local function syncFollowers(callbackRig, dt, phase)
            if not bridgeIsActive() or callbackRig ~= rig then return end
            backend.LastFollowerAt, backend.LastFollowerPhase = os.clock(), phase
            if rebindInProgress then
                quiesceGelatekFollowerSupport()
                pdHeadFollower.LastBlockedReason = "controller replacement in progress"
                return
            end
            local physical = backend.RealCharacter or originalCharacter
            if not physical or not physical.Parent then return end
            if phase == "ControllerPose" then backend.AccessoryLifetime.CommitControllerPose(rig) end
            local bodyPoses = backend.AccessoryLifetime.ControllerBodyPoses(rig,phase=="RenderPose"or phase=="PreSimulation")
            stepGelatekHeadBridge(rig, dt, phase, bodyPoses)
            local now = os.clock()
            local renderOnly=phase=="RenderPose"
            local commitAccessories = phase == "PostSimulation"or renderOnly
            if phase == "ControllerPose" then backend.LastControllerPoseAt = now end
            if not commitAccessories then return end
            -- Managed-head early returns in native CFrameAlign must not leave
            -- a previously visible ownership warning permanently stuck on.
            if not renderOnly and(not backend.LastOwnershipWarningAt or now-backend.LastOwnershipWarningAt>=.2)then
                backend.LastOwnershipWarningAt=now
                for _,part in ipairs(getPhysicalHeadIndex(physical).Descendants) do
                    if part:IsA("BasePart") then backend.RefreshOwnershipWarning(part) end
                end
            end
            for handle, state in pairs(accessoryRecoveryStates) do
                if state.Managed and handle.Parent and (not state.Controller or not state.Controller.Parent) then
                    state.LastBlockedReason = "controller accessory target missing"
                    if state.LinearMover and state.LinearMover.MaxForce ~= Vector3.zero then state.LinearMover.MaxForce = Vector3.zero end
                    if state.AngularMover and state.AngularMover.MaxTorque ~= Vector3.zero then state.AngularMover.MaxTorque = Vector3.zero end
                end
            end
            for _, pair in ipairs(getGelatekRecoveryPairs(rig, physical)) do
                if pair.IsAccessory == true then
                    local ok, written = pcall(writeDetachedGelatekAccessory, pair, dt, renderOnly, bodyPoses)
                    if ok and written then
                        if not renderOnly then pdHeadFollower.AccessoryWrites += 1 end
                        local state = accessoryRecoveryStates[pair.Physical]
                        if state then state.LastPhase = phase end
                    elseif not ok then
                        local state = accessoryRecoveryStates[pair.Physical]
                        if state then state.LastWriteError = tostring(written) end
                        backend.AccessoryTransportError = tostring(written)
                    end
                end
            end
        end
        global.UhhhhhhTBZGelatekSyncFollowers = syncFollowers
        local function followerPhase(dt, phase)
            if not bridgeIsActive() then return end
            local started=backend.Performance.Begin("head-accessory-"..phase)
            local ok, reason = pcall(syncFollowers, rig, dt, phase)
            backend.Performance.Finish("head-accessory-"..phase,started)
            backend.FollowerError = not ok and tostring(reason) or nil
        end
        -- These callbacks belong to the bridge. A native body callback can
        -- abort on another limb without stopping Head/accessory pose updates.
        neckBridgeConnection = RunService.PreSimulation:Connect(function(dt) followerPhase(dt, "PreSimulation") end)
        neckBridgeLateConnection = RunService.PostSimulation:Connect(function(dt) followerPhase(dt, "PostSimulation") end)
        local followerBinding = "Uhhhhhh_GelatekFollowers_" .. tostring(bridgeToken)
        RunService:BindToRenderStep(followerBinding, Enum.RenderPriority.Last.Value + 2,
            function(dt) followerPhase(dt, "RenderPose") end)
        neckBridgeRenderConnection = {Disconnect = function() RunService:UnbindFromRenderStep(followerBinding) end}
        environment().UhhhhhhTBZGelatekAccessoryWriterActive = true
        global.UhhhhhhTBZGelatekAccessoryWriterReady = function(handle)
            local state = accessoryRecoveryStates[handle]
            return bridgeIsActive() and state ~= nil
                and not rebindInProgress and state.Managed == true and state.LastBlockedReason == nil and state.Writes > 0
                and state.LastSuccessfulWriteAt ~= nil and os.clock() - state.LastSuccessfulWriteAt < 0.25
                and state.Controller ~= nil and state.Controller.Parent ~= nil
                and ownsPhysicalPart(handle)
        end
        -- Do not wait for another full bridge tick once the vendor handoff is ready.
        stepGelatekHeadBridge(rig, 1/60, "Initial")

        -- Gelatek's exact physical root is the network-owned flinger. Its normal
        -- follower pauses while this late PostSimulation writer is targeting.
        flingBridgeConnection = RunService.PostSimulation:Connect(function()
            local global = environment()
            local physicalRoot = global.UhhhhhhTBZGelatekPhysicalRoot
            local fling = activeFling
            if not bridgeIsActive()
                or not fling
                or typeof(physicalRoot) ~= "Instance"
                or not physicalRoot.Parent
            then
                global.UhhhhhhTBZGelatekFlingActive = nil
                restoreGelatekRootRepRoot()
                return
            end
            if os.clock() >= fling.Deadline then
                activeFling = nil
                global.UhhhhhhTBZGelatekFlingActive = nil
                restoreGelatekRootRepRoot()
                return
            end
            local targetCFrame, invalid = Util.PredictionFling(fling.Target)
            if invalid then
                activeFling = nil
                global.UhhhhhhTBZGelatekFlingActive = nil
                restoreGelatekRootRepRoot()
                return
            end
            local ready,reason=backend.AccessoryLifetime.RootFlingReady(backend.RealCharacter or originalCharacter,physicalRoot)
            if not ready then
                global.UhhhhhhTBZGelatekFlingActive=nil
                backend.LastFlingError=reason
                restoreGelatekRootRepRoot()
                return
            end
            backend.LastFlingError=nil
            global.UhhhhhhTBZGelatekFlingActive = true
            local written, writeError = pcall(function()
                physicalRoot.CFrame = targetCFrame
                    + Vector3.new(0, 0, math.random(0, 1) * 0.005)
                physicalRoot.AssemblyLinearVelocity = Vector3.new(0, -16384, 0)
                physicalRoot.AssemblyAngularVelocity = Vector3.one * 16384
            end)
            if not written then
                activeFling = nil
                global.UhhhhhhTBZGelatekFlingActive = nil
                restoreGelatekRootRepRoot()
                backend.LastFlingError = tostring(writeError)
                return
            end
