					local j2, j2m = _muscle(p0, p1, pivotcf * CFrame.Angles(0, 0, math.pi * 0.5), unpack(angledata[2]))
					local j3, j3m = _muscle(p1, part2, pivotcf * CFrame.Angles(0, math.pi * -0.5, 0), unpack(angledata[3]))
