					textvis[21] = true
				elseif eva < 13 then
					textvis[13] = true
				elseif eva < 14 then
					textvis[11] = true
				elseif eva < 15 then
					textvis[16] = true
				else
					textvis[20] = true
					textvis[7] = true
				end
			end
		elseif t < 34.5 then
			local needy = t % 6
			if needy < 4.5 then
				animator2:Step(t)
			else
				animator3:Step(needy - 3)
			end
			if needy < 0.75 then
			elseif needy < 1.5 then
				textvis[22] = true
				textvis[26] = true
			elseif needy < 2.25 then
			elseif needy < 3 then
				textvis[23] = true
				textvis[26] = true
			elseif needy < 3.75 then
				textvis[2] = true
				textvis[3] = true
			elseif needy < 4.5 then
				textvis[2] = true
				textvis[3] = true
				textvis[26] = true
			elseif needy < 5.25 then
				textvis[18] = true
				textvis[21] = true
				textvis[7] = true
				textvis[24] = true
			else
				textvis[18] = true
				textvis[21] = true
				textvis[7] = true
				textvis[25] = true
			end
		elseif t < 36 then
			animator3:Step(t - 34.5)
			for i=1, 23 do textvis[i] = math.random(3) == 1 end
		else
			local eva = (t - 36) / 0.75
			if t < 48 then
				if eva % 4 < 3 then
					textvis[24] = true
