			{ id = "rbxassetid://182435998", weight = 10 },
			{ id = "rbxassetid://182491037", weight = 10 },
			{ id = "rbxassetid://182491065", weight = 10 }
		},
		dance2 = {
			{ id = "rbxassetid://182436842", weight = 10 }, 
