	local failedAnimationLoads = {}
	local function loadAnimationTrack(humanoid, anim, transitionTime, priority)
		if not humanoid or not humanoid.Parent or not anim then return nil end
		local id = tostring(anim.AnimationId)
		local now = os.clock()
		local failure = failedAnimationLoads[id]
		if failure and now - failure < 30 then return nil end
		local track
		local ok, reason = pcall(function()
			track = humanoid:LoadAnimation(anim)
			if not track then error("LoadAnimation returned no track") end
			if priority then track.Priority = priority end
			track:Play(transitionTime)
		end)
		if not ok then
			if track then pcall(function() track:Destroy() end) end
