			m.IgnoreDancing = val
		end)
		Util_CreateSlider(parent, "Head Size", m.HeadScale, 0.5, 4, 0.5).Changed:Connect(function(val)
			m.HeadScale = val
		end)
		Util_CreateSwitch(parent, "Hitbox Visual", m.HitboxDebug).Changed:Connect(function(val)
			m.HitboxDebug = val
		end)
