					task.wait(0.16)
					if not rootu:IsDescendantOf(workspace) then
						return
					end
				end
			end
			if lol == 2 then
				animationOverride = lerps.sword5
				task.wait(0.16)
				if not rootu:IsDescendantOf(workspace) then
					return
				end
				CreateSound("92597369", 0.4)
