								elseif t[3] == -1 then
									return sig(t[2] * mul) .. "*sin(" .. sig(-t[4] % (math.pi * 2)) .. "-sine)"
								else
									return sig(t[2] * mul) .. "*sin(sine*" .. sig(t[3]) .. "+" .. sig((t[4] * t[3]) % (math.pi * 2)) .. ")"
								end
							end
						else
							if t[2] == 0 then
								return sig(t[1] * mul)
							else
								if t[3] == 0 then
									return sig(t[1] * mul)
								elseif t[3] == 1 then
									return sig(t[1] * mul) .. "+" .. sig(t[2] * mul) .. "*sin(sine+" .. sig(t[4] % (math.pi * 2)) .. ")"
								elseif t[3] == -1 then
