    ["UhhhhhhReanim/System/runtime/steve110/main/animation_apex.lua"] = [=====[
-- Uhhhhhh's interchange adapter. ApexEngine itself is unmodified MPL-2.0 code
-- by codedtocode; see apex_engine/LICENSE.txt and provenance.json.
-- Only data parsing, serialization and offline pose evaluation are used here.
return function(ctx)
    local api={}
    local function engine(path) return ctx.Require("main/apex_engine/"..path) end
    function api.Read(source)
        assert(type(source)=="string" and #source<=8*1024*1024,"text animation exceeds 8 MiB")
        local value,problem=engine("Core/Deserialize").source(source)
        assert(value~=nil,"animation data: "..tostring(problem))
        return api.Document(value)
    end
    function api.Write(track)
        return engine("Core/Serialize").module(track,{
            "Uhhhhhh animation project. Data only; do not execute this file.",
            "CFrames, keys, easing, markers, loop and priority are retained.",
        })
    end
    function api.Values(cf,previous) return engine("Shared/Pose").toValues(cf,"XYZ",previous) end
    function api.Frame(values) return engine("Shared/Pose").fromValues("XYZ",values) end
    function api.Document(doc)
        assert(type(doc)=="table","expected animation data")
        if doc.Keyframes~=nil then
            assert(doc.Format==nil or (doc.Format=="Uhhhhhh.Animation" and (doc.Version==1 or doc.Version==2)),"unsupported animation project format/version")
            return doc
        end
        assert(doc.format==nil or doc.hash==nil,
            "Apex companion data does not contain the complete native animation; export its base KeyframeSequence in Studio")
        assert(doc.kind~="Scene","Apex scenes need the Studio/runtime scene player; import one baked rig animation")
        assert(doc.joints~=nil,"expected a Steve keyframe table or a complete Apex rig document")
        local schema=engine("Core/Schema")
        local valid,problem=schema.validate(doc)
        assert(valid,"Apex document: "..tostring(problem))
        -- Without the authored rig/rest pose and a server runtime, these cannot
        -- be flattened correctly. Reject them instead of silently losing them.
        local allowed={kind=true,version=true,name=true,length=true,fps=true,loop=true,priority=true,
            joints=true,layers=true,presets=true,markers=true,bake=true,publish=true,revision=true}
        for name,value in pairs(doc) do
            assert(allowed[name] or value==nil or (type(value)=="table" and next(value)==nil),
                "Apex "..tostring(name).." requires Studio baking; this importer accepts joint curves and layers")
        end
        local names,seen={},{}
        local function joints(tracks)
            for name,joint in pairs(tracks) do
                assert(joint.spaces==nil or #joint.spaces==0,"Apex dynamic parenting requires Studio baking: "..name)
                if not seen[name] then seen[name]=true table.insert(names,name) end
            end
        end
        joints(doc.joints)
        for _,layer in ipairs(doc.layers or {}) do joints(layer.joints) end
        table.sort(names)
        assert(#names>0 and #names<=512,"Apex document has no joints or too many joints")
        local track={Name=doc.name,Looped=doc.loop,Priority=doc.priority,FPS=math.clamp(doc.fps,1,60),
            Keyframes={},Markers={},Studio={Version=1,ActiveLayer=0,Length=doc.length,
                Curves=doc.joints,Layers={},Camera={},Props={},Targets={},Presets=doc.presets or {}}}
        for _,t in ipairs({0,doc.length})do
            local frame={Time=t,Poses={}}
            for _,name in ipairs(names)do table.insert(frame.Poses,{Name=name,CFrame=CFrame.identity,Weight=1,
                EasingStyle="Linear",EasingDirection="InOut"})end
            table.insert(track.Keyframes,frame)
        end
        for _,layer in ipairs(doc.layers or {})do
            table.insert(track.Studio.Layers,{Name=layer.name,Blend=layer.blend,Weight=layer.weight,
                Muted=layer.mute==true,Solo=layer.solo==true,Mask=layer.mask or {},Curves=layer.joints,Keyframes={}})
        end
        for _,marker in ipairs(doc.markers or {})do
            assert(not marker.len or marker.len==0,"Apex marker spans need the scene/runtime player; import event markers")
            table.insert(track.Markers,{Time=marker.t,Name=marker.name,Value=marker.metadata})
        end
        return track,"Imported editable Apex joint curves and layers; .txt / .json retain the authoring data"

    end
    return api
end
