    ["UhhhhhhReanim/System/runtime/steve110/main/animation_curve.lua"] = [=====[
-- Native joint-curve import through documented curve sampling APIs.
-- Samples are baked into Steve joint CFrames; this does not install a plugin.
return function(clip,fps,options)
    assert(typeof(clip)=="Instance"and clip:IsA("CurveAnimation"),"expected a CurveAnimation")
    fps=fps or 30
    assert(type(fps)=="number"and fps>=1 and fps<=60,"curve bake rate must be 1 to 60 fps")
    local joints,names,times,seen,markers={},{},{},{},{}
    local length,total,guarded,partial=0,0,0,0
    local function number(value,label)
        assert(type(value)=="number"and value==value and math.abs(value)<1e12,"invalid curve "..label)
        return value
    end
    local function time(t)
        number(t,"time")assert(t>=0 and t<=3600,"curve time must be 0 to 3600 seconds")
        length=math.max(length,t)
        if not seen[t]then seen[t]=true table.insert(times,t)end
    end
    local function keys(curve)
        local list=curve:GetKeys()
        total+=#list assert(total<=100000,"native curve has too many keys")
        local previous
        for _,key in ipairs(list)do
            time(key.Time)
            if previous then
                assert(key.Time>previous.Time,"native curve keys must have increasing times")
                local mode=typeof(previous.Interpolation)=="EnumItem"and previous.Interpolation.Name or tostring(previous.Interpolation):match("[^%.]+$")
                if mode=="Constant"then
                    local width=math.min((key.Time-previous.Time)/4,math.max(1e-6,key.Time*2^-21))
                    time(key.Time-width)guarded+=1
                end
            end
            previous=key
        end
        return #list
    end
    local function axes(curve)
        local out={}
        for i,axis in ipairs({"X","Y","Z"})do
            local component=curve:FindFirstChild(axis)
            if component then
                assert(component:IsA("FloatCurve"),"unsupported native "..axis.." channel")
                if keys(component)>0 then out[i]=component end
            end
            if not out[i]then partial+=1 end
        end
        return out,(out[1]or out[2]or out[3])~=nil
    end
    local descendants=clip:GetDescendants()
    assert(#descendants<=10000,"native animation hierarchy is too large")
    for _,item in ipairs(descendants)do
        local class=item.ClassName
        assert(class=="Folder"or class=="Vector3Curve"or class=="EulerRotationCurve"or class=="RotationCurve"or class=="FloatCurve"or class=="MarkerCurve",
            "native "..class.." needs a separate runtime or Studio baking")
        if item:IsA("FloatCurve")then
            assert((item.Name=="X"or item.Name=="Y"or item.Name=="Z")and item.Parent and (item.Parent:IsA("Vector3Curve")or item.Parent:IsA("EulerRotationCurve")),"standalone scalar/face curves need Studio baking")
        elseif item:IsA("MarkerCurve")then
            local records=item:GetMarkers()
            assert(#records+#markers<=100000,"native animation has too many markers")
            for _,record in ipairs(records)do
                time(record.Time)
                table.insert(markers,{Time=record.Time,Name=item.Name,Value=tostring(record.Value or record.Marker or "")})
            end
        elseif item:IsA("Folder")then
            local position,rotation=item:FindFirstChild("Position"),item:FindFirstChild("Rotation")
            if position or rotation then
                assert(not names[item.Name],"duplicate native joint name: "..item.Name)
                names[item.Name]=true
                assert(not position or position:IsA("Vector3Curve"),"unsupported native Position curve")
                assert(not rotation or rotation:IsA("EulerRotationCurve")or rotation:IsA("RotationCurve"),"unsupported native Rotation curve")
                local entry={Name=item.Name,Parent=item.Parent:IsA("Folder")and item.Parent.Name or nil}
                if position then entry.Position=axes(position)end
                if rotation then
                    local active
                    if rotation:IsA("EulerRotationCurve")then local _,has=axes(rotation)active=has entry.Euler=true else active=keys(rotation)>0 end
                    if active then entry.Rotation=rotation end
                end
                table.insert(joints,entry)
            end
        elseif item:IsA("Vector3Curve")or item:IsA("EulerRotationCurve")or item:IsA("RotationCurve")then
            assert(item.Parent and item.Parent:IsA("Folder")and
                ((item.Name=="Position"and item:IsA("Vector3Curve"))or(item.Name=="Rotation"and not item:IsA("Vector3Curve"))),
                "native curves must be named Position/Rotation inside joint folders")
        end
    end
    assert(#joints>0 and #joints<=512 and total>0,"native curve has no supported joint keys or too many joints")
    local duration=length
    local count=math.ceil(duration*fps)
    assert(count+1<=100000 and (count+1)*#joints<=500000,"native curve bake is too large")
    for i=0,count do time(math.min(i/fps,duration))end
    assert(#times<=100000 and #times*#joints<=500000,"native curve bake is too large")
    table.sort(times)table.sort(joints,function(a,b)return a.Name<b.Name end)
    local track={Name=clip.Name,Looped=clip.Loop==true,Priority=clip.Priority,FPS=fps,Keyframes={},Markers=markers}
    local batch=math.max(1,math.floor(2048/#joints))
    for index,t in ipairs(times)do
        if (index-1)%batch==0 and options then
            if options.Cancelled then assert(not options.Cancelled(),"animation import cancelled")end
            if options.Progress then options.Progress(index-1,#times)end
            if options.Yield then options.Yield()end
            if options.Cancelled then assert(not options.Cancelled(),"animation import cancelled")end
        end
        local frame={Time=t,Poses={}}
        for _,joint in ipairs(joints)do
            local position={0,0,0}
            if joint.Position then for axis,curve in pairs(joint.Position)do position[axis]=number(curve:GetValueAtTime(t),"position")end end
            local rotation=CFrame.identity
            if joint.Rotation then
                rotation=joint.Euler and joint.Rotation:GetRotationAtTime(t)or joint.Rotation:GetValueAtTime(t)
                assert(typeof(rotation)=="CFrame","native rotation sample did not return a CFrame")
            end
            table.insert(frame.Poses,{Name=joint.Name,Parent=joint.Parent,Weight=1,
                CFrame=CFrame.new(table.unpack(position))*rotation,EasingStyle="Linear",EasingDirection="InOut"})
        end
        table.insert(track.Keyframes,frame)
    end
    return track,string.format("Native joint curves baked at %g fps; %d step guards; %d empty axis channels use identity. Interpolation between samples is approximate; marker curve names are retained literally.",fps,guarded,partial)
end
