    local function poseCount(track)
        local count=0 for _,frame in ipairs(track.Keyframes)do count+=#frame.Poses end
        if track.Studio then
            local function curves(rows)for _,row in pairs(rows)do for _,channel in pairs(row.channels)do count+=#channel.keys end end end
            curves(track.Studio.Curves)
