        if self.Track then remember(self.UndoStack,self:State()) end
        self.Track=nextTrack
        self.DocumentSerial+=1
        self.Time,self.Playing,self.RedoStack=0,false,{}
        self:Changed()
        return self.Track
    end
    function Editor:New(rigType)
        assert(bodies[rigType],"choose R6 or R15")
        local track={Name="New "..rigType.." animation",RigType=rigType,FPS=30,Looped=true,
            Priority="Action",Keyframes={},Markers={}}
        for _,t in ipairs({0,1}) do
            local key={Time=t,Poses={}}
            for _,name in ipairs(bodies[rigType]) do
                table.insert(key.Poses,{Name=name,Parent=(name=="Head" and rigType=="R15") and "UpperTorso" or parents[name],
                    Weight=1,CFrame=CFrame.identity,EasingStyle="Linear",EasingDirection="InOut"})
            end
            table.insert(track.Keyframes,key)
        end
        return self:Load(track)
    end
    function Editor:NewFromRig(info)
        assert(type(info)=="table"and type(info.Joints)=="table"and #info.Joints>0,"the current rig has no authorable joints")
        assert(#info.Joints<=512,"the editor supports up to 512 joints per clip")
        local track={Name="New custom rig animation",RigType="Custom",FPS=30,Looped=true,
            Priority="Action",Keyframes={},Markers={},Hats=info.Hats}
        for _,t in ipairs({0,1})do
            local key={Time=t,Poses={}}
            for _,joint in ipairs(info.Joints)do
                table.insert(key.Poses,{Name=joint.Name,Parent=joint.Parent,Weight=1,
                    CFrame=joint.Transform or CFrame.identity,EasingStyle="Linear",EasingDirection="InOut"})
            end
            table.insert(track.Keyframes,key)
        end
        return self:Load(track)
    end
    function Editor:SyncRig(info)
        assert(info and info.Joints,"start a rig before syncing its joints")
        self:Joints()local missing={}
        for _,joint in ipairs(info.Joints)do if not self.Index[joint.Name]then table.insert(missing,joint)end end
        if #missing==0 and not info.Hats then return 0 end
        self:Edit(function(track)
            track.RigType="Custom"
            if info.Hats then track.Hats=info.Hats end
            local keys=Files.Document.Keys(track)
            if #keys==0 then table.insert(keys,{Time=0,Poses={}})end
            for _,joint in ipairs(missing)do
                table.insert(keys[1].Poses,{Name=joint.Name,Parent=joint.Parent,Weight=1,
                    CFrame=joint.Transform or CFrame.identity,EasingStyle="Linear",EasingDirection="InOut"})
            end
