        self.Track=nextTrack self:Changed()
    end
    function Editor:Undo(redo)
        if self.Gesture then self:EndGesture(false)return end
        local from,to=redo and self.RedoStack or self.UndoStack,redo and self.UndoStack or self.RedoStack
        assert(#from>0,redo and "nothing to redo" or "nothing to undo")
        remember(to,self:State())
        local state=table.remove(from)
        self.Track,self.Time,self.Playing=state.Track,state.Time,false self:Changed()
        self.DocumentSerial=state.DocumentSerial or self.DocumentSerial
