        if not self.Index then
            self.Index={} self.AllIndex={} self.JointNames={}
            for _,key in ipairs(self:Keys()) do
                for _,pose in ipairs(key.Poses) do
                    if not self.Index[pose.Name] then
                        self.Index[pose.Name]={} self.AllIndex[pose.Name]={} table.insert(self.JointNames,pose.Name)
                    end
                    table.insert(self.AllIndex[pose.Name],{Time=key.Time,Pose=pose})
                    if pose.Weight>0 then table.insert(self.Index[pose.Name],{Time=key.Time,Pose=pose}) end
                end
            end
            local kind=self.Track.RigType
            if not bodies[kind] then
                for _,name in ipairs(bodies.R15)do if name~="Head"and self.Index[name]then kind="R15"break end end
                if not kind then for _,name in ipairs(bodies.R6)do if self.Index[name]then kind="R6"break end end end
            end
