    function Editor:SetPose(name,cf,style,direction,weight,parent)
        assert(type(name)=="string" and name~="","choose a joint")
        local at=math.min(math.round(self.Time*self.FPS)/self.FPS,self.Track.Time)
        self:Edit(function(track)
            local frame
            for _,key in ipairs(self:Keys(track)) do if math.abs(key.Time-at)<1e-7 then frame=key break end end
            if not frame then frame={Time=at,Poses={}} table.insert(self:Keys(track),frame) end
            for i=#frame.Poses,1,-1 do if frame.Poses[i].Name==name then table.remove(frame.Poses,i) end end
            table.insert(frame.Poses,{Name=name,CFrame=cf,Weight=weight or 1,EasingStyle=style or "Linear",
                EasingDirection=direction or "InOut",Parent=parent})
            local row=Files.Document.Curves(track,false)[name]
            if row then local values=Files.Document.Values(cf,row.rotationMode)
                for axis in pairs(row.channels)do Files.Document.KeyCurve(track,name,axis,at,values[axis])end
            end
        end)
        self.Time=at
