    function Editor:DeleteKey(joint)
        local at=math.min(math.round(self.Time*self.FPS)/self.FPS,self.Track.Time)
        self:Edit(function(track)
            local found=false
            for i=#self:Keys(track),1,-1 do
                local frame=self:Keys(track)[i]
                if math.abs(frame.Time-at)<1e-7 then
