        end
        for _,row in ipairs(ctx.ActiveTracks and ctx.ActiveTracks()or {})do
            if row.Module and not row.Author then row=table.clone(row)row.Author=author(row.Module)end
            if not module or row.Module==module then add(row,row.Track or ("native/"..tostring(row.AssetId)))end
        end
        local modules=module and {module}or (ctx.SelectedModules and ctx.SelectedModules()or {})
        for _,current in ipairs(modules)do
            local function assets(list)
                for _,reference in ipairs(list or {})do
                    local path=reference:match("^([^@]+)")or reference
                    if path:lower():match("%.anim$")or path:lower():match("%.json$")or path:lower():match("%.txt$")then
                        add({Name=path:match("([^/]+)$")or path,Reference=reference,Module=current,
                            Author=author(current),Source=current.Name.." / "..(current._UhhhhhhSource or "Loaded module")},"asset/"..reference)
                    end
                end
            end
            assets(current.Assets)assets(current.OptionalAssets)
