		ResetPoseOnStop = SavedAnimLibOptions.ResetPoseOnStop,
		OverrideWalkSpeed = SavedAnimLibOptions.OverrideWalkSpeed,
		WalkSpeed = SavedAnimLibOptions.WalkSpeed,
		PhysicsHeadTracking = SavedAnimLibOptions.PhysicsHeadTracking,
		PhysicsHeadBlendAnimation = SavedAnimLibOptions.PhysicsHeadBlendAnimation,
		PhysicsHeadStrength = SavedAnimLibOptions.PhysicsHeadStrength,
		PhysicsHeadSmoothing = SavedAnimLibOptions.PhysicsHeadSmoothing,
		KeepAccessoriesWhenHiding = SavedAnimLibOptions.KeepAccessoriesWhenHiding,
		DisabledAnimationParts = SavedAnimLibOptions.DisabledAnimationParts,
		ReplicationWriters = SavedAnimLibOptions.ReplicationWriters,
		HiddenBodyParts = SavedAnimLibOptions.HiddenBodyParts,
		DanceEffects = SavedDanceEffectsOptions,
		DanceSoundProvider = function()
			return UISound.DanceMusic
		end,
	},
}
AnimLib.JointGroups = {
	{
		Key = "Head",
		Label = "Head",
		Names = { "Head" },
	},
	{
		Key = "Torso",
		Label = "Torso / Waist",
		Names = { "Torso", "LowerTorso", "UpperTorso" },
	},
	{
		Key = "Left Arm",
		Label = "Left Arm",
		Names = { "Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand" },
	},
	{
		Key = "Right Arm",
		Label = "Right Arm",
		Names = { "Right Arm", "RightUpperArm", "RightLowerArm", "RightHand" },
	},
	{
		Key = "Left Leg",
		Label = "Left Leg",
		Names = { "Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" },
	},
	{
		Key = "Right Leg",
		Label = "Right Leg",
		Names = { "Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot" },
	},
}
AnimLib.ActiveAnimators = setmetatable({}, { __mode = "k" })
function AnimLib.GetJointGroup(key)
	for _, group in AnimLib.JointGroups do
		if group.Key == key then
			return group
		end
	end
	return nil
end
function AnimLib.IsJointGroupAnimated(key)
	local group = AnimLib.GetJointGroup(key)
	if not group then
		return false
	end
	for _, name in group.Names do
		if SavedAnimLibOptions.DisabledAnimationParts[name] == true then
			return false
		end
	end
	return true
end
function AnimLib.SetJointGroupAnimated(key, animated)
	local group = AnimLib.GetJointGroup(key)
	if not group then
		return false
	end
	for _, name in group.Names do
		-- `animated and nil or true` always evaluates to true in Lua/Luau, so
		-- the old mixer could disable a limb but could never clear it again.
		if animated == true then
			SavedAnimLibOptions.DisabledAnimationParts[name] = nil
		else
			SavedAnimLibOptions.DisabledAnimationParts[name] = true
		end
	end
	AnimLib.Settings.DisabledAnimationParts = SavedAnimLibOptions.DisabledAnimationParts
	return true
end
function AnimLib.ResetDisabledJointPoses(rig)
	if typeof(rig) ~= "Instance" then
		return
	end
	local disabled = SavedAnimLibOptions.DisabledAnimationParts
	for _, descendant in rig:GetDescendants() do
		local part=AnimatedJointPart(descendant)
		if part and disabled[part.Name] == true
		then
			descendant.Transform = CFrame.identity
		end
	end
end
function AnimLib.ApplyDisabledAnimationParts()
	AnimLib.Settings.DisabledAnimationParts = SavedAnimLibOptions.DisabledAnimationParts
	for animator in pairs(AnimLib.ActiveAnimators) do
		if not animator._destroyed then
			-- Disabled joints are a separate global layer, so live GUI changes
			-- never erase a module's own SetJointMask/Filter configuration.
			if animator.useGlobalJointSettings~=false then animator:SetDisabledJoints(SavedAnimLibOptions.DisabledAnimationParts)end
			-- Re-sample the current frame immediately. This matters when a limb is
			-- re-enabled while the same dance keeps playing: waiting for a later
			-- module tick left Gelatek looking frozen in the old neutral pose.
			if animator:IsPlaying() then
				pcall(animator.Step, animator, animator.timePosition)
			end
		end
	end
	AnimLib.ResetDisabledJointPoses(Reanimate.Character)
end
function AnimLib.NormalizePartSelections(rig)
    if not rig or not rig:FindFirstChild("UpperTorso") then return end
    local disabled=SavedAnimLibOptions.DisabledAnimationParts
    for _,group in ipairs(AnimLib.JointGroups) do
        if disabled[group.Key] and not rig:FindFirstChild(group.Key) then
            for _,name in ipairs(group.Names) do if rig:FindFirstChild(name) then disabled[name]=true end end
            disabled[group.Key]=nil
        end
    end
end
function AnimLib.ApplyJointPreset(name)
	if name == "Custom" then
		SavedAnimLibOptions.JointPreset = "Custom"
		AnimLib.Settings.JointPreset = "Custom"
		return
	end
	local animated = {
		Head = true,
		Torso = true,
		["Left Arm"] = true,
		["Right Arm"] = true,
		["Left Leg"] = true,
		["Right Leg"] = true,
	}
	if name == "Upper Body" then
		animated["Left Leg"] = false
		animated["Right Leg"] = false
	elseif name == "Lower Body" then
		animated.Head = false
		animated["Left Arm"] = false
		animated["Right Arm"] = false
	elseif name == "Arms Only" then
		for key in animated do
			animated[key] = key == "Left Arm" or key == "Right Arm"
		end
	else
		name = "Full Body"
	end
	for _, group in AnimLib.JointGroups do
		AnimLib.SetJointGroupAnimated(group.Key, animated[group.Key] == true)
	end
	SavedAnimLibOptions.JointPreset = name
	AnimLib.Settings.JointPreset = name
	AnimLib.ApplyDisabledAnimationParts()
end
if SavedAnimLibOptions.PartSelectionSchema ~= 22 then
	-- Preserve v21's semantic group migration once. Later precise R15 edits
	-- must survive reload without expanding back into a whole disabled limb.
	local legacyDisabledGroups = {}
	for _, group in AnimLib.JointGroups do
		for _, name in group.Names do
			if SavedAnimLibOptions.DisabledAnimationParts[name] == true then
				legacyDisabledGroups[group.Key] = true
			end
		end
	end
	local namedPreset = SavedAnimLibOptions.JointPreset ~= "Full Body"
		and SavedAnimLibOptions.JointPreset ~= "Custom"
	if namedPreset then
		AnimLib.ApplyJointPreset(SavedAnimLibOptions.JointPreset)
	end
	for _, group in AnimLib.JointGroups do
		if legacyDisabledGroups[group.Key] then
			AnimLib.SetJointGroupAnimated(group.Key, false)
		end
	end
	if next(legacyDisabledGroups) ~= nil then
		SavedAnimLibOptions.JointPreset = "Custom"
		AnimLib.Settings.JointPreset = "Custom"
		AnimLib.ApplyDisabledAnimationParts()
	end
    SavedAnimLibOptions.PartSelectionSchema=22
end
do
	local function CleanupItem(item)
		local success, reason = pcall(function()
			local itemType = typeof(item)
			if itemType == "RBXScriptConnection" then
				if item.Connected then
					item:Disconnect()
				end
			elseif itemType == "Instance" then
				item:Destroy()
			elseif type(item) == "thread" then
				task.cancel(item)
			elseif type(item) == "function" then
				item()
			elseif type(item) == "table" then
				if type(item.Disconnect) == "function" then
					item:Disconnect()
				elseif type(item.Destroy) == "function" then
					item:Destroy()
				end
			end
		end)
		if not success then
			warn("AnimLib cleanup failed: " .. tostring(reason))
		end
	end

	local ConnectionGroup = {}
	ConnectionGroup.__index = ConnectionGroup
	function ConnectionGroup.new()
		local self = setmetatable({}, ConnectionGroup)
		self._items = {}
		self._destroyed = false
		return self
	end
	function ConnectionGroup:Add(item)
		assert(not self._destroyed, "cannot add to a destroyed ConnectionGroup")
		if item ~= nil then
			table.insert(self._items, item)
		end
		return item
	end
	function ConnectionGroup:Remove(item, cleanup)
		local index = table.find(self._items, item)
		if not index then
			return nil
		end
		local removed = table.remove(self._items, index)
		if cleanup then
			CleanupItem(removed)
		end
		return removed
	end
	function ConnectionGroup:Count()
		return #self._items
	end
	function ConnectionGroup:Cleanup()
		local items = self._items
		self._items = {}
		for index = #items, 1, -1 do
			CleanupItem(items[index])
		end
		return self
	end
	function ConnectionGroup:LinkToInstance(instance)
		assert(typeof(instance) == "Instance", "instance must be an Instance")
		self:Add(instance.Destroying:Connect(function()
			self:Cleanup()
		end))
		return self
	end
	function ConnectionGroup:Destroy()
		if self._destroyed then
			return
		end
		self:Cleanup()
		self._destroyed = true
	end
	AnimLib.ConnectionGroup = ConnectionGroup

	local SupportedRunSignals = {
		PreAnimation = true,
		PreSimulation = true,
		PostSimulation = true,
		Heartbeat = true,
		RenderStepped = true,
	}
	local function ResolveRunSignal(signal, defaultName)
		if typeof(signal) == "RBXScriptSignal" then
			return signal, "Custom"
		end
		signal = signal or defaultName or "PreAnimation"
		assert(
			type(signal) == "string" and SupportedRunSignals[signal],
			"unsupported RunService signal: " .. tostring(signal)
		)
		local success, resolved = pcall(function()
			return RunService[signal]
		end)
		assert(success and typeof(resolved) == "RBXScriptSignal", "RunService signal is unavailable: " .. signal)
		return resolved, signal
	end

	local Track = {}
		-- Playback trusts a track only after full boundary validation. Keep this
		-- metadata outside caller tables; editors still own/mutate those tables.
		local playbackValidated = setmetatable({}, {__mode = "k"})
		local function invalidatePlayback(track)
			if track then playbackValidated[track] = nil else table.clear(playbackValidated) end
		end
	local TrackFileCache = require(script.Parent.track_cache)({Clone=function(track)return Track.clone(track)end})
    Track.FileCache=TrackFileCache
    function Track.TrimCaches()return TrackFileCache.TrimIdle(120)end
	local function SortAndUpdateTrackTime(track)
			invalidatePlayback(track)
        if Track.PoseCache then Track.PoseCache.Invalidate(track)end
        if AnimLib.StudioDocument then AnimLib.StudioDocument.Invalidate(track)end
		track.Time = 0
		table.sort(track.Keyframes, function(a, b)
			return a.Time < b.Time
		end)
		for _, keyframe in track.Keyframes do
			track.Time = math.max(track.Time, keyframe.Time)
		end
		if track.Markers then
			table.sort(track.Markers, function(a, b)
				return a.Time < b.Time
			end)
			for _, marker in track.Markers do
				track.Time = math.max(track.Time, marker.Time)
			end
		end
        if AnimLib.StudioDocument then track.Time=AnimLib.StudioDocument.Length(track)end
		return track
	end
	function Track.new(name)
		return {
			Name = name or "<unknown>",
			Time = 0,
			Keyframes = {},
			Markers = {},
		}
	end
	function Track.validate(track)
		if type(track) ~= "table" then
			return false, "track must be a table"
		end
		playbackValidated[track] = nil
		if type(track.Keyframes) ~= "table" then
			return false, "track.Keyframes must be a table"
		end
		for keyframeindex, keyframe in track.Keyframes do
			if type(keyframe) ~= "table" then
				return false, "keyframe " .. keyframeindex .. " must be a table"
			end
			if type(keyframe.Time) ~= "number" or keyframe.Time < 0 then
				return false, "keyframe " .. keyframeindex .. " has an invalid time"
			end
			if type(keyframe.Poses) ~= "table" then
				return false, "keyframe " .. keyframeindex .. " poses must be a table"
			end
			for poseindex, pose in keyframe.Poses do
				if type(pose) ~= "table" then
					return false, "pose " .. poseindex .. " in keyframe " .. keyframeindex .. " must be a table"
				end
				if type(pose.Name) ~= "string" then
					return false, "pose " .. poseindex .. " has no name"
				end
				if typeof(pose.CFrame) ~= "CFrame" then
					return false, "pose " .. poseindex .. " has no CFrame"
				end
			end
		end
		if track.Markers ~= nil then
			if type(track.Markers) ~= "table" then
				return false, "track.Markers must be a table"
			end
			for markerindex, marker in track.Markers do
				if type(marker) ~= "table" then
					return false, "marker " .. markerindex .. " must be a table"
				end
				if type(marker.Name) ~= "string" or marker.Name == "" then
					return false, "marker " .. markerindex .. " has no name"
				end
				if type(marker.Time) ~= "number" or marker.Time < 0 then
					return false, "marker " .. markerindex .. " has an invalid time"
				end
			end
		end
		playbackValidated[track] = {Keyframes=track.Keyframes, Count=#track.Keyframes,
			Markers=track.Markers, MarkerCount=track.Markers and #track.Markers or 0}
		return true
	end
	local function ensurePlaybackTrack(track)
		local known = type(track) == "table" and playbackValidated[track]
		if not known or known.Keyframes ~= track.Keyframes or known.Count ~= #track.Keyframes
			or known.Markers ~= track.Markers or known.MarkerCount ~= (track.Markers and #track.Markers or 0) then
			local valid, reason = Track.validate(track)
			assert(valid, reason)
			return true
		end
	end
	local function playbackDuration(track)
		ensurePlaybackTrack(track)
		-- Read live times rather than caching duration: a module can edit a key or
		-- marker in place without changing its table identity or array length.
		-- Pose payloads are validated at SetTrack/public mutation boundaries,
		-- first legacy assignment, and explicit Track.Invalidate calls.
		local duration = 0
		for index, keyframe in track.Keyframes do
			if type(keyframe) ~= "table" or type(keyframe.Time) ~= "number" or not (keyframe.Time >= 0) then
				error("keyframe " .. index .. " has an invalid time", 2)
			end
			duration = math.max(duration, keyframe.Time)
		end
		for index, marker in track.Markers or {} do
			if type(marker) ~= "table" or type(marker.Name) ~= "string" or marker.Name == ""
				or type(marker.Time) ~= "number" or not (marker.Time >= 0) then
				error("marker " .. index .. " is invalid", 2)
			end
			duration = math.max(duration, marker.Time)
		end
		if AnimLib.StudioDocument then duration=AnimLib.StudioDocument.Length(track) end
		track.Time = duration
		return duration
	end
	function Track.clone(track)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		return Util.DeepcopyTable(track)
	end
	function Track.getDuration(track)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		local duration = 0
		for _, keyframe in track.Keyframes do
			duration = math.max(duration, keyframe.Time)
		end
		for _, marker in track.Markers or {} do
			duration = math.max(duration, marker.Time)
		end
        if AnimLib.StudioDocument then duration=AnimLib.StudioDocument.Length(track)end
		track.Time = duration
		return duration
	end
	function Track.sort(track)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		return SortAndUpdateTrackTime(track)
	end
	function Track.addKeyframe(track, time, poses)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(time) == "number" and time >= 0, "time must be zero or greater")
		assert(poses == nil or type(poses) == "table", "poses must be a table or nil")
		local keyframe = {
			Time = time,
			Poses = poses and Util.DeepcopyTable(poses) or {},
		}
		table.insert(track.Keyframes, keyframe)
		SortAndUpdateTrackTime(track)
		return keyframe
	end
	function Track.removeKeyframe(track, index)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(index) == "number", "index must be a number")
		local removed = table.remove(track.Keyframes, index)
		SortAndUpdateTrackTime(track)
		return removed
	end
	function Track.findKeyframes(track, starttime, endtime)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		starttime = starttime or 0
		endtime = endtime or Track.getDuration(track)
		local found = {}
		for index, keyframe in track.Keyframes do
			if keyframe.Time >= starttime and keyframe.Time <= endtime then
				table.insert(found, { Index = index, Keyframe = keyframe })
			end
		end
		return found
	end
	function Track.addMarker(track, time, name, value)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(time) == "number" and time >= 0, "time must be zero or greater")
		assert(type(name) == "string" and name ~= "", "name must be a non-empty string")
		track.Markers = track.Markers or {}
		local marker = {
			Time = time,
			Name = name,
			Value = value,
		}
		table.insert(track.Markers, marker)
		SortAndUpdateTrackTime(track)
		return marker
	end
	function Track.removeMarker(track, index)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(index) == "number", "index must be a number")
		track.Markers = track.Markers or {}
		local removed = table.remove(track.Markers, index)
		SortAndUpdateTrackTime(track)
		return removed
	end
	function Track.getMarkers(track, name)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(name == nil or type(name) == "string", "name must be a string or nil")
		local markers = {}
		for _, marker in track.Markers or {} do
			if name == nil or marker.Name == name then
				table.insert(markers, marker)
			end
		end
		return markers
	end
	function Track.getMarkersBetween(track, starttime, endtime, includeStart)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(starttime) == "number" and type(endtime) == "number", "starttime and endtime must be numbers")
		local markers = {}
		for _, marker in track.Markers or {} do
			local afterStart = includeStart and marker.Time >= starttime or marker.Time > starttime
			if afterStart and marker.Time <= endtime then
				table.insert(markers, marker)
			end
		end
		return markers
	end
	function Track.frombuffer(buf)
		local needle = 0
		local buflen = buffer.len(buf)
		local function getleft()
			return buflen - needle
		end
		local function readstring()
			assert(getleft() >= 2)
			local len = buffer.readu16(buf, needle)
			needle += 2
			assert(getleft() >= len)
			local val = buffer.readstring(buf, needle, len)
			needle += len
			return val
		end
		local function readsizet()
			assert(getleft() >= 4)
			local val = buffer.readu32(buf, needle)
			needle += 4
			return val
		end
		local function readfloat()
			assert(getleft() >= 4)
			local val = buffer.readf32(buf, needle)
			needle += 4
			return val
		end
		local anim = {
			Name = "<unknown>",
			Time = 0,
			Keyframes = {},
			Markers = {},
		}
		anim.Name = readstring() -- name
		local nkeyframes = readsizet() -- # of keyframes
		for _ = 1, nkeyframes do
			local t = readfloat() -- time
			anim.Time = math.max(anim.Time, t)
			local nposes = readsizet() -- # of poses
			local keyframe = {
				Time = t,
				Poses = {},
			}
			for _ = 1, nposes do
				local pose = {}
				pose.Name = readstring() -- "bone" name
				pose.Weight = readfloat() -- weight (usually 1 or 0)
				pose.EasingStyle = readstring() -- EasingStyle
				pose.EasingDirection = readstring() -- EasingDirection
				pose.CFrame = CFrame.new(
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat(),
					readfloat()
				) -- cframe
				table.insert(keyframe.Poses, pose)
			end
			table.insert(anim.Keyframes, keyframe)
		end
		return SortAndUpdateTrackTime(anim)
	end
	function Track.fromfile(path)
		local s, data = pcall(readfile, path)
		if s and data then
			local extension=tostring(path):lower():match("%.([^.]+)$")
			local prefix=data:gsub("^\239\187\191","")
			local textInput=extension=="txt" or extension=="json" or prefix:match("^%s*return[%s{]")
				or prefix:match("^%s*%-%-") or prefix:match("^%s*[%[{]")
			if textInput and AnimLib.GetFileTools then
				local parsed,track=pcall(function() return AnimLib.GetFileTools().Decode(data) end)
				if parsed then return track end
				return nil,track
			end
			local buf = buffer.fromstring(data)
			local parsed, track = pcall(Track.frombuffer, buf)
			if parsed then
				return track
			end
			return nil, track
		end
		return nil, data
	end
	function Track.fromfilecached(path, refresh)
		local cached=not refresh and TrackFileCache.Get(path)
		if cached then
			return Track.clone(cached)
		end
		local track, reason = Track.fromfile(path)
		if not track then
			return nil, reason
		end
		TrackFileCache.Put(path,track)
		return track
	end
	function Track.clearfilecache(path)
        if AnimLib.FrameSmoothingCache then AnimLib.FrameSmoothingCache.Clear() end
		if path then
			TrackFileCache.Remove(path)
		else
			TrackFileCache.Clear()
		end
	end
	function Track.frominstance(ks)
		assert(ks and ks:IsA("KeyframeSequence"))
		local anim = {
			Name = "<unknown>",
			Time = 0,
			Keyframes = {},
			Markers = {},
		}
		anim.Name = ks.Name
		anim.Looped = ks.Loop
		anim.Priority = ks.Priority.Name
		for _, k in ks:GetKeyframes() do
			local t = k.Time
			anim.Time = math.max(anim.Time, t)
			local keyframe = {
				Name = k.Name,
				Time = t,
				Poses = {},
			}
			if k.Name ~= "" and k.Name ~= "Keyframe" then
				table.insert(anim.Markers, {
					Name = k.Name,
					Time = t,
					Source = "Keyframe",
				})
			end
			for _, marker in k:GetMarkers() do
				table.insert(anim.Markers, {
					Name = marker.Name,
					Time = t,
					Value = marker.Value,
					Source = "KeyframeMarker",
				})
			end
			for _, p in k:GetDescendants() do
				if not p:IsA("Pose") then
					continue
				end
				table.insert(keyframe.Poses, {
					Name = p.Name,
					Parent = p.Parent and p.Parent:IsA("Pose") and p.Parent.Name or nil,
					Weight = p.Weight,
					EasingStyle = p.EasingStyle.Name,
					EasingDirection = p.EasingDirection.Name,
					CFrame = p.CFrame,
				})
			end
			table.insert(anim.Keyframes, keyframe)
		end
		return SortAndUpdateTrackTime(anim)
	end
	function Track.paste(target, source, timeoffset)
		local targetvalid, targetreason = Track.validate(target)
		local sourcevalid, sourcereason = Track.validate(source)
		assert(targetvalid, targetreason)
		assert(sourcevalid, sourcereason)
		timeoffset = timeoffset or 0
		assert(type(timeoffset) == "number", "timeoffset must be a number")
		for _, keyframe in source.Keyframes do
			local newkeyframe = Util.DeepcopyTable(keyframe)
			newkeyframe.Time += timeoffset
			assert(newkeyframe.Time >= 0, "timeoffset creates a negative keyframe time")
			table.insert(target.Keyframes, newkeyframe)
		end
		target.Markers = target.Markers or {}
		for _, marker in source.Markers or {} do
			local newmarker = Util.DeepcopyTable(marker)
			newmarker.Time += timeoffset
			assert(newmarker.Time >= 0, "timeoffset creates a negative marker time")
			table.insert(target.Markers, newmarker)
		end
		return SortAndUpdateTrackTime(target)
	end
	function Track.append(target, source, gap)
		gap = gap or 0
		return Track.paste(target, source, Track.getDuration(target) + gap)
	end
	function Track.scaleTime(track, factor)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		assert(type(factor) == "number" and factor > 0, "factor must be greater than zero")
		for _, keyframe in track.Keyframes do
			keyframe.Time *= factor
		end
		for _, marker in track.Markers or {} do
			marker.Time *= factor
		end
        if AnimLib.StudioDocument then AnimLib.StudioDocument.Retime(track,factor)end
		return SortAndUpdateTrackTime(track)
	end
	function Track.reverse(track)
		local reversed = Track.clone(track)
		local duration = Track.getDuration(reversed)
		for _, keyframe in reversed.Keyframes do
			keyframe.Time = duration - keyframe.Time
			for _, pose in keyframe.Poses do
				if pose.EasingDirection == "In" then
					pose.EasingDirection = "Out"
				elseif pose.EasingDirection == "Out" then
					pose.EasingDirection = "In"
				end
			end
		end
		for _, marker in reversed.Markers or {} do
			marker.Time = duration - marker.Time
		end
		return SortAndUpdateTrackTime(reversed)
	end
	function Track.slice(track, starttime, endtime)
		local valid, reason = Track.validate(track)
		assert(valid, reason)
		starttime = math.max(starttime or 0, 0)
		endtime = math.min(endtime or Track.getDuration(track), Track.getDuration(track))
		assert(endtime >= starttime, "endtime must not be before starttime")

		local sliced = Track.new((track.Name or "<unknown>") .. " (slice)")
		local hasStartKeyframe = false
		for _, keyframe in track.Keyframes do
			if keyframe.Time >= starttime and keyframe.Time <= endtime then
				local copy = Util.DeepcopyTable(keyframe)
				copy.Time -= starttime
				if copy.Time == 0 then
					hasStartKeyframe = true
				end
				table.insert(sliced.Keyframes, copy)
			end
		end
		if not hasStartKeyframe and starttime < Track.getDuration(track) then
			local poses = {}
			for name, cframe in Track.getPoses(track, starttime, false) do
				table.insert(poses, {
					Name = name,
					Weight = 1,
					EasingStyle = "Linear",
					EasingDirection = "InOut",
					CFrame = cframe,
				})
			end
			table.insert(sliced.Keyframes, { Time = 0, Poses = poses })
		end
		for _, marker in track.Markers or {} do
			if marker.Time >= starttime and marker.Time <= endtime then
				local copy = Util.DeepcopyTable(marker)
				copy.Time -= starttime
				table.insert(sliced.Markers, copy)
			end
		end
		return SortAndUpdateTrackTime(sliced)
	end
	local function GetEasedAlpha(alpha, easingstyle, easingdirection)
		alpha = math.clamp(alpha, 0, 1)
		if easingstyle == "Constant" then
			if easingdirection == "In" then
				return 1
			end
			if easingdirection == "Out" then
				return 0
			end
			return alpha < 0.5 and 0 or 1
		end
		if easingstyle == "CubicV2" then
			easingstyle = "Cubic"
		end
		local style = Enum.EasingStyle[easingstyle] or Enum.EasingStyle.Linear
		local direction = Enum.EasingDirection[easingdirection] or Enum.EasingDirection.InOut
		return TweenService:GetValue(alpha, style, direction)
	end
    Track.PoseCache=require(script.Parent.pose_sampler)(GetEasedAlpha)
    function Track.Invalidate(track)
        invalidatePlayback(track)
        Track.PoseCache.Invalidate(track)
    end
    function Track.getPoses(track,t,looped,raw)
        if track.Studio and AnimLib.StudioDocument and not raw then
            if looped and track.Time>0 then t%=track.Time end
            return AnimLib.StudioDocument.Sample(track,t,function(source,at)return Track.getPoses(source,at,false,true)end)
        end
        assert(type(t)=="number","time must be a number")
        if looped and track.Time>0 then t%=track.Time end
        return Track.PoseCache.Sample(track,t)
    end
	AnimLib.Track = Track
    AnimLib.FrameSmoothingCache = Context.CharacterMotion and Context.CharacterMotion.CreateFrameCache(GetEasedAlpha) or nil
	local JointPresets = {
		["Full Body"] = nil,
