	local size = #text
	local index = 1
	local line = 1

	local function at(offset: number): string
		local position = index + offset
		return string.sub(text, position, position)
	end

	local function readString(quote: string)
		local pattern = if quote == '"' then '["\\\n]' else "['\\\n]"
		local pieces: { string } = {}
		local cursor = index + 1

		while true do
			local found = string.find(text, pattern, cursor)
			if not found then
				fail(line, "a quote is never closed")
			end
			local stop = found :: number
			if stop > cursor then
				table.insert(pieces, string.sub(text, cursor, stop - 1))
			end

			local character = string.sub(text, stop, stop)
			if character == quote then
				cursor = stop + 1
				break
			elseif character == "\n" then
				fail(line, "a quote runs on to the next line without being closed")
			end

			local escaped = string.sub(text, stop + 1, stop + 1)
			if escaped == "" then
				fail(line, "a quote is never closed")
			elseif string.match(escaped, "%d") then
				local digits = string.match(text, "^%d%d?%d?", stop + 1) :: string
				local byte = tonumber(digits) :: number
				if byte > 255 then
					fail(line, `'\\{digits}' inside quotes is not a character`)
				end
				table.insert(pieces, string.char(byte))
				cursor = stop + 1 + #digits
			elseif escaped == "\r" then
				line += 1
				table.insert(pieces, "\n")
				cursor = stop + 2
				if string.sub(text, cursor, cursor) == "\n" then
