local SlotCheck = require(script.Parent.Parent.Shared.SlotCheck)
local SceneSidecar = require(script.Parent.SceneSidecar)
local ReleaseMath = require(script.Parent.Parent.Shared.ReleaseMath)
local ScreenDraw = require(script.Parent.Parent.Shared.ScreenDraw)
local Path = require(script.Parent.Path)
local Serialize = require(script.Parent.Serialize)
local Sidecar = require(script.Parent.Sidecar)
local Types = require(script.Parent.Types)

local Handoff = {}

Handoff.ENGINE_NAME = "ApexEngine"
Handoff.REGISTRY_NAME = "ApexAnimations"

Handoff.LIST_LIMIT = 8

export type Options = {
	path: string?,
	rig: string?,
	rigs: { [string]: string }?,
}

local SERVER_SCRIPT = "a Script in ServerScriptService"
local LOCAL_SCRIPT = "a LocalScript in StarterPlayerScripts"

local function seconds(t: number): string
	return string.format("%.2f s", t)
end

local function literal(value: any): string
	if type(value) == "string" then
		return string.format("%q", value)
	elseif type(value) == "number" then
		return string.format("%g", value)
	end
	return tostring(value)
end

local function kindOf(value: any): string
	if type(value) == "string" then
		return "text"
	elseif type(value) == "number" then
		return "number"
	end
	return "true / false"
end

local function joined(list: { string }): string
	if #list <= 1 then
		return list[1] or ""
	end
	return table.concat(list, ", ", 1, #list - 1) .. " and " .. list[#list]
end

local function limited(list: { string }): string
	if #list <= Handoff.LIST_LIMIT then
		return table.concat(list, ", ")
	end
	local shown = table.concat(list, ", ", 1, Handoff.LIST_LIMIT)
	return `{shown} and {#list - Handoff.LIST_LIMIT} more`
end

function Handoff.spaceName(target: Types.SpaceTarget): string
	local kind = target.kind
	if kind == "Parent" then
		return "its rig parent (the default)"
	elseif kind == "World" then
		return "the world"
	elseif kind == "RigRoot" then
		return if target.slot then `the root of slot '{target.slot}'` else "the rig's root"
	end
	local joint = target.joint or "?"
	return if target.slot then `{joint} of slot '{target.slot}'` else joint
end

local function payloadFields(items: { any }?): string?
	local kinds: { [string]: { [string]: boolean } } = {}
	for _, item in items or {} do
		for field, value in item.payload or {} do
			kinds[field] = kinds[field] or {}
			kinds[field][kindOf(value)] = true
		end
	end
	local fields: { string } = {}
	for field in kinds do
		table.insert(fields, field)
	end
	if #fields == 0 then
		return nil
	end
	table.sort(fields)
	local parts: { string } = {}
	for _, field in fields do
		local list: { string } = {}
		for kind in kinds[field] do
			table.insert(list, kind)
		end
		table.sort(list)
		table.insert(parts, `{field} ({table.concat(list, " or ")})`)
	end
	return table.concat(parts, ", ")
end

local function introduction(sidecar: Sidecar.Sidecar, add: (string) -> ())
	add(`{sidecar.name} - an animation made with Apex Animator.`)
	add("Written by Apex Animator when the animation was exported. Do not edit it by hand:")
	add("change the animation in Apex Animator and export it again.")
	add("")
	add("WHAT THIS MODULE IS")
	add("  The animation itself is an ordinary Roblox animation asset. It plays anywhere,")
	add("  with or without this module. This module adds what a plain Roblox animation")
	add("  cannot do - joints that switch between spaces, gameplay states, prop changes.")
	add(`  {Handoff.ENGINE_NAME} adds it by itself, on every player's machine and on the server,`)
	add("  WHENEVER THIS ANIMATION PLAYS, however it is played (the default Animate script,")
	add("  a weapon kit, your own Animator:LoadAnimation), as long as:")
	add(
		`    - {Handoff.ENGINE_NAME} is installed (ReplicatedStorage.{Handoff.ENGINE_NAME}, started by its two`
	)
	add("      bootstrap scripts - Apex Animator's Install Engine sets this up), and")
	add(`    - this module is in the registry folder, ReplicatedStorage.{Handoff.REGISTRY_NAME}.`)
	add("  Playing it needs no code. Code is only needed to READ the states listed below.")
	add("  A rig with the attribute Apex_Ignore set to true is always left as plain Roblox.")
end

local function sceneSlot(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local scene = sidecar.scene
	if scene == nil then
		return
	end
	add("")
	add("A SLOT OF A SCENE")
	add(
		`  This is the slot '{scene.slot}' of the scene '{scene.name}', filed here on its own so that`
	)
	add("  every machine that sees this asset play - not only the one that loaded the scene -")
	add("  plays the slot enhanced. Play the scene itself with ApexEngine.LoadScene and the")
	add("  scene's own module; nothing needs this one by name.")
	local others: { string } = {}
	for _, name in scene.slots do
		if name ~= scene.slot then
			local id = scene.assets[name]
			local temp = scene.temps ~= nil and scene.temps[name] ~= nil
			table.insert(
				others,
				if id ~= nil
					then `'{name}' (asset {string.format("%d", id)})`
					elseif
						temp
					then `'{name}' (not published yet; its temporary copy in Studio tests)`
					else `'{name}' (not published yet)`
			)
		end
	end
	if #others > 0 then
		add(
			`  A joint that follows another slot's rig follows the rig playing that slot's asset: {joined(
				others
			)}.`
		)
	end
end

local function asset(sidecar: Sidecar.Sidecar, add: (string) -> ())
	add("")
	add("THE ASSET")
	local id = sidecar.assetId
	if id == nil then
		add("  No asset id here yet. Roblox's publish window does not tell Apex Animator the id,")
		add(
			`  and {Handoff.ENGINE_NAME} does not need it: it knows the published animation by the hash`
		)
		add(
			`  in its clip's __apex marker, which this module's {Sidecar.HASH_ATTRIBUTE} attribute holds.`
		)
		add("  Link id in Apex Animator fills in the id, which the PLAY IT code below needs.")
		add(
			`  Before it is published, {Handoff.ENGINE_NAME} plays it in Studio tests by the temporary id each export`
		)
		add(`  puts in this module's {Sidecar.TEMP_ATTRIBUTE} attribute.`)
		return
	end
	local idText = string.format("%d", id)
	add(`  Animation id: rbxassetid://{idText}`)
	add(`  This module's {Sidecar.ATTRIBUTE} attribute holds the same number, {idText}.`)
	add(`  {Handoff.ENGINE_NAME} finds the module by that attribute without running it, so never`)
	add("  remove it, and keep it equal to the id above. Publishing again from Apex Animator")
	add(
		`  updates both. It also knows the animation by the hash in its clip's __apex marker, which`
	)
	add(`  this module's {Sidecar.HASH_ATTRIBUTE} attribute holds.`)
end

local function modulePath(name: string, options: Options?): string
	if options ~= nil and options.path ~= nil then
		return options.path
	end
	return `game:GetService("ReplicatedStorage"):WaitForChild("{Handoff.REGISTRY_NAME}"):WaitForChild({string.format(
		"%q",
		name
	)})`
end

local function requireLine(indent: string): string
	return `{indent}local {Handoff.ENGINE_NAME} = require(game:GetService("ReplicatedStorage"):WaitForChild("{Handoff.ENGINE_NAME}"))`
end

local function playIt(sidecar: Sidecar.Sidecar, options: Options?, add: (string) -> ())
	local id = sidecar.assetId
	local rig = if options ~= nil then options.rig else nil
	add("")
	add("PLAY IT")
	if id == nil then
		add("  With no asset id here, this plays only in a Studio test, from the temporary copy")
		add("  the export made. Once it is published, Link id in Apex Animator fills the id in.")
	end
	if rig ~= nil then
		add("  This plays it on the rig it was made on. Copy the code below into")
	else
		add("  Copy the code below into")
	end
	add(`  {SERVER_SCRIPT}, without the "--" in front of each line,`)
	add("  and press Play:")
	add(requireLine("    "))
	add(`    local rig = {rig or "character -- a character Model"}`)
	add(
		`    local track = {Handoff.ENGINE_NAME}.LoadAnimation(rig, {modulePath(
			sidecar.name,
			options
		)})`
	)
	add("    track:Play()")
	add("  To play it on another character, change the rig line. (If you moved this module,")
	if id == nil then
		add("  change the path.)")
	else
		add(
			`  change the path.) Without {Handoff.ENGINE_NAME} it plays as a plain Roblox animation:`
		)
		add('    local animation = Instance.new("Animation")')
		add(`    animation.AnimationId = "rbxassetid://{string.format("%d", id)}"`)
		add('    rig:FindFirstChildWhichIsA("Animator", true):LoadAnimation(animation):Play()')
	end
	add("  For a track somebody else played - the Animate script, a weapon kit -")
	add(`  {Handoff.ENGINE_NAME}.GetTrack(animationTrack) hands you the same kind of track.`)
end

local function movement(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local track = sidecar.movement
	if track == nil or #track.keys == 0 then
		return
	end
	local walks, targets = 0, 0
	for _, key in track.keys do
		if key.kind == "Walk" then
			walks += 1
		else
			targets += 1
		end
	end
	local parts: { string } = {}
	if walks > 0 then
		table.insert(parts, if walks == 1 then "1 walk" else `{walks} walks`)
	end
	if targets > 0 then
		table.insert(parts, if targets == 1 then "1 target" else `{targets} targets`)
	end
	add("")
	add("MOVEMENT - it walks its character and places it")
	add(`  {joined(parts)}, from where the character stands as the animation starts.`)
	add(`  {Handoff.ENGINE_NAME} walks it through its Humanoid (WalkSpeed and Move), so walls`)
	add("  and gravity stay real, and sets its HumanoidRootPart's CFrame at a target and")
	add("  along a glide from one target to the next. Only the machine that simulates the")
	add("  character does this; WalkSpeed, AutoRotate and the Humanoid states go back to")
	add("  what they were when the animation ends or is stopped. Do not move the character")
	add("  yourself meanwhile (Move, MoveTo, CFrame writes), or the two fight.")
	add(`  Without {Handoff.ENGINE_NAME} the character plays the animation on the spot.`)
	if sidecar.scene ~= nil then
		add("  In its scene, LoadScene sets the HumanoidRootPart to its place in the scene")
		add("  moved by the movement, every frame, walls or not, so the characters meet where")
		add("  they were authored to.")
	end
end

local function states(sidecar: Sidecar.Sidecar, add: (string) -> ())
	add("")
	local list = sidecar.states or {}
	if #list == 0 then
		add("STATE TRACKS: none.")
		return
	end
	add(`STATE TRACKS ({#list}) - gameplay moments game code can read`)
	for _, state in list do
		if state.kind == "Span" then
			add(`  {state.name} - a span: on at some moments, off the rest of the time`)
			local ranges: { string } = {}
			for _, span in state.spans or {} do
				table.insert(ranges, string.format("%.2f-%.2f s", span.t, span.t + span.len))
			end
			add(`    on at {limited(ranges)}`)
			local fields = payloadFields(state.spans)
			if fields then
				add(`    payload fields: {fields}`)
			end
			add(
				`    track:GetSpanSignal("{state.name}"):Connect(function(began, payload, reason) end)`
			)
			add(`    track:GetState("{state.name}") --> true while on, false while off`)
			add(`    Stopping the animation early ends an open span with reason "interrupted".`)
			if state.nativeMarkers then
				add(
					`    Also native markers "{state.name}.Begin" and "{state.name}.End", which fire without {Handoff.ENGINE_NAME}.`
				)
			end
		elseif state.kind == "Stepped" then
			add(`  {state.name} - a stepped value: it changes at moments and holds in between`)
			local values: { string } = {}
			for _, step in state.steps or {} do
				table.insert(values, `{literal(step.value)} from {seconds(step.t)}`)
			end
			add(`    values: {limited(values)}`)
			local fields = payloadFields(state.steps)
			if fields then
				add(`    payload fields: {fields}`)
			end
			add(
				`    track:GetStateChangedSignal("{state.name}"):Connect(function(new, old, payload) end)`
			)
			add(`    track:GetState("{state.name}") --> the value now (nil before its first step)`)
		else
			add(`  {state.name} - a curve: a number at every moment`)
			add(`    track:GetState("{state.name}") --> a number`)
		end
	end
end

local function markers(sidecar: Sidecar.Sidecar, add: (string) -> ())
	add("")
	local list = sidecar.markers or {}
	if #list == 0 then
		add("MARKERS: none.")
		return
	end
	local order: { string } = {}
	local byName: { [string]: { Types.Marker } } = {}
	for _, marker in list do
		if byName[marker.name] == nil then
			byName[marker.name] = {}
			table.insert(order, marker.name)
		end
		table.insert(byName[marker.name], marker)
	end
	add("MARKERS - named moments; they fire with or without " .. Handoff.ENGINE_NAME)
	for _, name in order do
		local times: { string } = {}
		for _, marker in byName[name] do
			local text = seconds(marker.t)
			if marker.metadata ~= nil and marker.metadata ~= "" then
				text ..= ` (metadata {string.format("%q", marker.metadata)})`
			end
			table.insert(times, text)
		end
		add(`  {name} at {limited(times)}`)
	end
	add(`    track:GetMarkerReachedSignal("{order[1]}"):Connect(function(metadata) end)`)
end

local function joints(sidecar: Sidecar.Sidecar, add: (string) -> ())
	add("")
	local starting = sidecar.startingSpaces or {}
	local names: { string } = {}
	local seen: { [string]: boolean } = {}
	for address in sidecar.joints do
		seen[address] = true
		table.insert(names, address)
	end
	for address, target in starting do
		if not seen[address] and target.kind ~= "Parent" then
			seen[address] = true
			table.insert(names, address)
		end
	end
	if #names == 0 then
		add("SWITCHABLE JOINTS: none.")
		return
	end
	table.sort(names)
	add("SWITCHABLE JOINTS - joints this animation moves from one space to another")
	add("  (a space is what the joint follows: its rig parent, another joint, the rig's")
	add("  root, or the world)")
	for _, address in names do
		add(`  {address}`)
		local spaces: { string } = {}
		local known: { [string]: boolean } = {}
		local function remember(target: Types.SpaceTarget)
			local name = Handoff.spaceName(target)
			if not known[name] then
				known[name] = true
				table.insert(spaces, name)
			end
		end
		local first = starting[address] or { kind = "Parent" }
		remember(first)
		add(`    starts in {Handoff.spaceName(first)}`)
		local track = sidecar.joints[address]
		for _, switch in (if track then track.spaces else nil) or {} do
			remember(switch.target)
			local line = `    at {seconds(switch.t)}: {Handoff.spaceName(switch.target)}`
			if switch.blend ~= nil and switch.blend > 0 then
				line ..= `, blending over {seconds(switch.blend)}`
			end
			if switch.onEnd == "Persist" then
				line ..= ", and stays there after the animation ends"
			else
				line ..= ", until the animation ends"
			end
			add(line)
		end
		add(`    spaces it can be in: {joined(spaces)}`)
	end
	add("  Read a joint's space from code, or hear it change:")
	add(`    {Handoff.ENGINE_NAME}.GetRigState(character):GetSpace("{names[1]}")`)
	add(
		`    {Handoff.ENGINE_NAME}.GetRigState(character).SpaceChanged:Connect(function(joint, space, previous) end)`
	)
end

local function props(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local map = sidecar.props or {}
	local paths: { string } = {}
	for path in map do
		table.insert(paths, path)
	end
	if #paths == 0 then
		return
	end
	table.sort(paths)
	add("")
	add("PROPS - properties this animation changes on the rig's parts, lights and effects")
	for _, path in paths do
		local target = map[path]
		local names: { string } = {}
		for property in target.properties do
			table.insert(names, property)
		end
		table.sort(names)
		if target.cues ~= nil and #target.cues > 0 then
			table.insert(names, "play / stop")
		end
		local where = if Path.inWorkspace(path) ~= nil then ", in the Workspace" else ""
		add(`  {path} ({target.className}{where}): {table.concat(names, ", ")}`)
	end
end

local function sounds(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local list = sidecar.sounds or {}
	if #list == 0 then
		return
	end
	add("")
	add("SOUNDS - played on each player's machine in time with the animation, never on the server")
	for _, sound in list do
		local where = if sound.source ~= nil
			then `through a copy of {sound.source}, or from the root part if the rig lacks it`
			else "from the root part"
		local clips = if #sound.clips == 1 then "1 clip" else `{#sound.clips} clips`
		add(`  {sound.name} ({sound.id}): {clips}, {where}`)
	end
	add("  A sound that runs past the end plays on after the animation finishes.")
end

local function speed(n: number): string
	local text = string.format("%.2f", n)
	text = string.gsub(text, "0+$", "")
	text = string.gsub(text, "%.$", "")
	return if text == "-0" then "0" else text
end

local function releaseEvent(name: string, add: (string) -> ())
	add("    joint      - the joint that lets go (text)")
	add("    vx, vy, vz - how fast it moves, in studs per second")
	add("    wx, wy, wz - how fast it turns, in radians per second")
	add("  Both speeds are in the part's own axes (its CFrame as it lets go), and are left")
	add("  out when the rig was missing at export.")
	add(`    track:GetMarkerReachedSignal("{name}"):Connect(function(metadata)`)
	add('      local data = game:GetService("HttpService"):JSONDecode(metadata)')
	add("      local cf = part.CFrame -- the part that lets go")
	add("      local v = Vector3.new(data.vx or 0, data.vy or 0, data.vz or 0)")
	add("      local w = Vector3.new(data.wx or 0, data.wy or 0, data.wz or 0)")
	add("      -- make the real object at cf, then set its")
	add("      -- AssemblyLinearVelocity = cf:VectorToWorldSpace(v)")
	add("      -- AssemblyAngularVelocity = cf:VectorToWorldSpace(w)")
	add("    end)")
end

local function releases(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local list = sidecar.releases or {}
	if #list == 0 then
		return
	end
	add("")
	add("RELEASES - moments a part is let go of and falls, like a thrown sword or a shell")
	local events: { string } = {}
	local seen: { [string]: boolean } = {}
	local putBack: { string } = {}
	local backSeen: { [string]: boolean } = {}
	local attaches = 0
	for _, release in list do
		local line = `  {release.joint} at {seconds(release.t)}`
		if ReleaseMath.isAttach(release :: any) then
			attaches += 1
			local onto = release.onto
			local back = if onto == nil or onto.kind == "Parent"
				then "put back on its joint"
				elseif onto.kind == "RigRoot" then (if onto.slot ~= nil
					then `put on {onto.slot}'s root`
					else "put on the rig's root")
				else (if onto.slot ~= nil
					then `put on {onto.slot}'s {onto.joint}`
					else `put on {onto.joint}`)
			line ..= if release.leaveCopy == true
				then `: {back}, its copies left where they lie`
				else `: {back}, its copies taken away`
			if release.event ~= nil then
				line ..= `, event "{release.event}"`
				if not backSeen[release.event] then
					backSeen[release.event] = true
					table.insert(putBack, release.event)
				end
			end
			add(line)
			continue
		end
		if release.cosmetic == false then
			line ..= ": hidden only, for game code to make the real one"
		else
			local lifetime = release.lifetime or ReleaseMath.DEFAULT_LIFETIME
			local cap = release.cap or ReleaseMath.DEFAULT_CAP
			local through = if release.collide == false then " through everything" else ""
			line ..= `: a copy falls{through} for {seconds(lifetime)}, at most {cap} at once`
		end
		local velocity = ReleaseMath.decode(release.velocity)
		if velocity ~= nil then
			line ..= `, thrown at {speed(velocity.linear.Magnitude)} studs/s`
		end
		if release.event ~= nil then
			line ..= `, event "{release.event}"`
			if not seen[release.event] then
				seen[release.event] = true
				table.insert(events, release.event)
			end
		end
		add(line)
	end
	add(`  {Handoff.ENGINE_NAME} hides the part at that moment and, on each player's machine,`)
	add("  drops a copy of it that flies off as the animation threw it. The copies are only")
	add("  for looks: each machine has its own, none exists on the server, and game code")
	add("  never sees them. Stopping the animation before the moment lets go of nothing;")
	add("  stopping it after puts the part back or not, as IF IT IS STOPPED says below.")
	if attaches > 0 then
		add("  An attach puts the part back on its joint: it shows again, and the copies of it")
		add("  still falling are taken away, unless the attach leaves them where they lie.")
	end
	if #events == 0 and #putBack == 0 then
		return
	end
	add("  An event is a native marker: it fires with or without the engine, wherever the")
	add("  animation plays (for a player's character, usually that player's client, which")
	if #events == 0 then
		add("  can ask the server to put the object back).")
	else
		add("  can ask the server to make the object). Its metadata is JSON with the speed:")
		releaseEvent(events[1], add)
	end
	if #putBack > 0 then
		add(`  An attach's event ("{putBack[1]}") carries only the joint and attach, which is`)
		add("  true, and no speed: the part is back on its joint, so the real object can go.")
	end
end

local INTERRUPT_WORDS: { [string]: string } = {
	Revert = "joints go back to the spaces they had, props to how they were when it started, and its sounds stop.",
	Keep = "everything stays exactly where it is, and game code decides what happens next.",
	Complete = "everything jumps to where the animation would have left it, as if it had finished.",
}

local function stopping(sidecar: Sidecar.Sidecar, add: (string) -> ())
	local policies = Sidecar.policies(sidecar)
	add("")
	add("IF IT IS STOPPED BEFORE ITS END")
	add(`  ({policies.interrupt}) {INTERRUPT_WORDS[policies.interrupt] or ""}`)
	add("  A track that reaches its end has completed; one stopped earlier was interrupted.")
	add("  Every machine decides this the same way, from the track's own time.")
end

function Handoff.lines(sidecar: Sidecar.Sidecar, options: Options?): { string }
	local lines: { string } = {}
	local function add(line: string)
		table.insert(lines, line)
	end
	introduction(sidecar, add)
	sceneSlot(sidecar, add)
	asset(sidecar, add)
	playIt(sidecar, options, add)
	movement(sidecar, add)
	states(sidecar, add)
	markers(sidecar, add)
	joints(sidecar, add)
	props(sidecar, add)
	sounds(sidecar, add)
	releases(sidecar, add)
	stopping(sidecar, add)
	return lines
end

function Handoff.attributes(sidecar: Sidecar.Sidecar): { [string]: any }
	local attributes: { [string]: any } = {}
	if sidecar.assetId ~= nil then
		attributes[Sidecar.ATTRIBUTE] = sidecar.assetId
	end
	attributes[Sidecar.HASH_ATTRIBUTE] = sidecar.hash
	return attributes
end

function Handoff.module(sidecar: Sidecar.Sidecar, options: Options?): string
	return Serialize.module(sidecar, Handoff.lines(sidecar, options))
end

local KEYWORDS: { [string]: boolean } = {}
for _, word in
	string.split(
		"and break continue do else elseif end false for function if in local nil not or repeat return then true until while",
		" "
	)
do
	KEYWORDS[word] = true
end

local function isIdentifier(name: string): boolean
	return string.match(name, "^[%a_][%w_]*$") ~= nil and not KEYWORDS[name]
end

function Handoff.slotKey(name: string): string
	return if isIdentifier(name) then name else `[{string.format("%q", name)}]`
end

function Handoff.characterNames(names: { string }): { [string]: string }
	local out: { [string]: string } = {}
	local taken: { [string]: boolean } = {}
	for index, name in names do
		local cleaned = string.gsub(name, "[^%w]", "")
		local base = if cleaned ~= "" and string.match(cleaned, "^%a") ~= nil
			then string.lower(string.sub(cleaned, 1, 1)) .. string.sub(cleaned, 2) .. "Character"
			else `character{index}`
		local chosen = base
		local suffix = 2
		while taken[chosen] do
			chosen = `{base}{suffix}`
			suffix += 1
		end
		taken[chosen] = true
		out[name] = chosen
	end
	return out
end

local function hasKeys(camera: Types.CameraTrack?): boolean
	for _, channel in (if camera ~= nil then camera.channels else nil) or {} do
		if #channel.keys > 0 then
			return true
		end
	end
	return false
end

local function position(data: { number }?): string
	if data == nil then
		return "the world's origin"
	end
	return string.format("(%.1f, %.1f, %.1f)", data[1], data[2], data[3])
end

local function sceneIntroduction(
	scene: SceneSidecar.SceneSidecar,
	names: { string },
	add: (string) -> ()
)
	add(
		`{scene.name} - a scene made with Apex Animator: {#names} rigs playing together, {seconds(
			SceneSidecar.lengthOf(scene)
		)} long.`
	)
	add("Written by Apex Animator when the scene was exported. Do not edit it by hand:")
	add("change the scene in Apex Animator and export it again.")
	add("")
	add("WHAT THIS MODULE IS")
	add("  A cutscene or paired move for several characters at once. Each SLOT below is one")
	add(
		`  role. Hand {Handoff.ENGINE_NAME}.LoadScene one character per slot: it checks each one can`
	)
	add("  play its slot, places them where the scene was authored, plays every slot's")
	add("  animation on its character in step, and drives the camera only if you pass one.")
	add("  Each slot's animation is an ordinary Roblox animation asset of its own.")
end

local function sceneTakes(takes: { SceneSidecar.SceneSidecar }, add: (string) -> ())
	if #takes < 2 then
		return
	end
	local listed: { string } = {}
	for _, take in takes do
		table.insert(listed, `'{take.name}' ({seconds(SceneSidecar.endOf(take))})`)
	end
	add("")
	add(`TAKES ({#takes})`)
	add("  It plays its takes one after another, as one scene, each where the one before")
	add(`  ends: {limited(listed)}.`)
	add("  scene.Take is the name of the take playing, and scene.TimePosition and")
	add("  scene.Length count over every take. A slot only some takes play still needs its")
	add("  character when the scene loads.")
end

local function sceneSlots(
	takes: { SceneSidecar.SceneSidecar },
	names: { string },
	add: (string) -> ()
)
	add("")
	add(`SLOTS ({#names})`)
	local several = #takes > 1
	for _, name in names do
		local described = false
		local moves = false
		local tracked: { Types.StateTrack }? = nil
		for _, take in takes do
			local slot = take.slots[name]
			if slot == nil then
				continue
			end
			if not described then
				described = true
				add(`  {name} - needs {SlotCheck.describe(slot.requirement :: any)}`)
			end
			local animation = slot.animation
			local what = if several then `animation in '{take.name}'` else "animation"
			local id = animation.assetId
			if id == nil and slot.tempId ~= nil then
				add(`    {what}: not published yet. A Studio test plays it from a temporary copy;`)
				add(
					"    publish this slot and export the scene again before you publish your game."
				)
			elseif id == nil then
				add(
					`    {what}: not published yet. Publish this slot from Apex Animator and export`
				)
				add("    the scene again; until then the scene cannot play.")
			else
				add(
					`    {what}: rbxassetid://{string.format("%d", id)} ({animation.name}, {seconds(
						animation.length
					)})`
				)
				if slot.tempId ~= nil then
					add(
						"    edited since it was published: a Studio test plays it as it is now, from a"
					)
					add(
						"    temporary copy, and a published game plays the asset above until you publish"
					)
					add("    this slot again and export the scene again.")
				end
			end
			moves = moves or (animation.movement ~= nil and #animation.movement.keys > 0)
			if tracked == nil and animation.states ~= nil and #animation.states > 0 then
				tracked = animation.states
			end
		end
		if moves then
			add("    moves its character: its movement carries it from its place, and it ends")
			add("    where the movement takes it")
		end
		if tracked ~= nil then
			local stateNames: { string } = {}
			for _, state in tracked do
				table.insert(stateNames, `{state.name} ({string.lower(state.kind)})`)
			end
			add(`    state tracks: {limited(stateNames)}`)
			add(`      scene:GetTrack({string.format("%q", name)}):GetState("{tracked[1].name}")`)
		end
	end
end

local function anyShot(takes: { SceneSidecar.SceneSidecar }): boolean
	for _, take in takes do
		if hasKeys(take.camera) then
			return true
		end
	end
	return false
end

local function screenClips(takes: { SceneSidecar.SceneSidecar }): { Types.ScreenClip }
	local out: { Types.ScreenClip } = {}
	for _, take in takes do
		for _, clip in take.screen or {} do
			table.insert(out, clip)
		end
	end
	return out
end

local function sceneAnchor(scene: SceneSidecar.SceneSidecar, add: (string) -> ())
	add("")
	add("WHERE IT PLAYS")
	local anchor = scene.anchor
	if anchor.kind == "Part" then
		local path = string.gsub(anchor.part or "", "/", ".")
		add(`  At the map part Workspace.{path}: the scene is placed around it, so that part`)
		add("  must exist when the scene loads.")
	elseif anchor.kind == "Slot" then
		add(`  Where the {anchor.slot or "?"} character stands: that character is not moved, and`)
		add("  the others are placed around it, where they were authored.")
	else
		add(`  Where it was made: its origin is at {position(anchor.cframe)} in the world.`)
	end
	add("  Characters are eased to their places from wherever they stand. To play it")
	add("  somewhere else, pass { anchor = ... }: a CFrame, a part, or a slot's name.")
end

local function sceneCamera(takes: { SceneSidecar.SceneSidecar }, add: (string) -> ())
	add("")
	if not anyShot(takes) then
		add("THE CAMERA: this scene has no camera shot.")
		return
	end
	add("THE CAMERA")
	add("  This scene has a camera shot. It moves only a camera you pass, on a player's")
	add("  machine: { camera = workspace.CurrentCamera }. Without one the player's camera is")
	add("  left alone. When the scene stops, the camera is handed back as it was.")
end

local SCREEN_WORDS: { [string]: string } = {
	Bars = "bars",
	Fade = "fades",
	Edges = "dark edges",
	Subtitle = "subtitles",
}

local function sceneScreen(
	takes: { SceneSidecar.SceneSidecar },
	camera: boolean,
	add: (string) -> ()
)
	local clips = screenClips(takes)
	if #clips == 0 then
		return
	end
	local kinds: { string } = {}
	local seen: { [string]: boolean } = {}
	for _, clip in clips do
		local words = SCREEN_WORDS[clip.kind] or clip.kind
		if not seen[words] then
			seen[words] = true
			table.insert(kinds, words)
		end
	end
	add("")
	add("THE SCREEN")
	add(`  Its Screen row draws {joined(kinds)} over the player's view, in a ScreenGui`)
	add("  under their PlayerGui, and takes them away when the scene stops. Subtitles are")
	add("  TextLabels, translated like the rest of your game's text.")
	if camera then
		add("  It draws for the player whose camera you pass. { screen = false } leaves it out.")
	else
		add("  Pass { screen = true } on a player's machine to draw it.")
	end
	add(
		`  It draws at DisplayOrder {ScreenDraw.ORDER}; pass \{ screenOrder = ... } to put it under your own UI.`
	)
end

local function sceneSnippet(
	scene: SceneSidecar.SceneSidecar,
	takes: { SceneSidecar.SceneSidecar },
	names: { string },
	options: Options?,
	add: (string) -> ()
)
	add("")
	add("PLAY IT")
	local given = (if options ~= nil then options.rigs else nil) or {}
	local everyRig = true
	local studioOnly: { string } = {}
	local unpublished: { string } = {}
	for _, name in names do
		everyRig = everyRig and given[name] ~= nil
		local temp, missing = false, false
		for _, take in takes do
			local slot = take.slots[name]
			if slot ~= nil and slot.animation.assetId == nil then
				temp = temp or slot.tempId ~= nil
				missing = missing or slot.tempId == nil
			end
		end
		if missing then
			table.insert(unpublished, `'{name}'`)
		elseif temp then
			table.insert(studioOnly, `'{name}'`)
		end
	end
	local camera = anyShot(takes)
	local screen = not camera and #screenClips(takes) > 0
	local client = camera or screen
	if everyRig then
		add("  This plays the scene on the rigs it was made with. Copy the code below into")
	else
		add("  Copy the code below into")
	end
	add(
		`  {if client then LOCAL_SCRIPT else SERVER_SCRIPT}, without the "--" in front of each line,`
	)
	add("  and press Play.")
	if camera then
		add("  A LocalScript, as only a player's machine has a camera to drive: the scene plays")
		add("  for that player alone.")
	elseif screen then
		add("  A LocalScript, as only a player's machine has a screen to draw on: the scene")
		add("  plays for that player alone.")
	end
	if #unpublished > 0 then
		local one = #unpublished == 1
		add(
			`  It cannot play yet: {if one then "the slot" else "the slots"} {joined(unpublished)} {if one
				then "is"
				else "are"} not published.`
		)
		add(`  Publish {if one then "it" else "them"}, then export the scene again.`)
	elseif #studioOnly > 0 then
		local one = #studioOnly == 1
		add(
			`  {if one then "The slot" else "The slots"} {joined(studioOnly)} {if one
				then "is"
				else "are"} not published, so this plays only in a`
		)
		add("  Studio test, from temporary copies. Publish, then export the scene again, before")
		add("  you publish your game.")
	end
	local variables = Handoff.characterNames(names)
	add(requireLine("    "))
	local origin = scene.anchor.cframe
	if client then
		add('    local player = game:GetService("Players").LocalPlayer')
		add(
			"    if player.Character == nil then player.CharacterAdded:Wait() end -- the player spawned in first"
		)
		if origin ~= nil then
			add(
				`    player:RequestStreamAroundAsync(Vector3.new({speed(origin[1])}, {speed(
					origin[2]
				)}, {speed(origin[3])})) -- the rigs, streamed in first`
			)
		end
	end
	add(`    local scene = {Handoff.ENGINE_NAME}.LoadScene({modulePath(scene.name, options)}, \{`)
	for _, name in names do
		local rig = given[name]
		add(
			if rig ~= nil
				then `        {Handoff.slotKey(name)} = {rig},`
				else `        {Handoff.slotKey(name)} = {variables[name]}, -- a character Model`
		)
	end
	add("    }, {")
	if camera then
		add("        camera = workspace.CurrentCamera, -- only on a player's machine")
	elseif screen then
		add("        screen = true, -- its Screen row, on this player's screen")
	end
	add("        -- anchor = workspace.SomePart, -- to play it somewhere else")
	add("    })")
	add("    scene:Play()")
	add("    scene.Ended:Wait() -- or scene:Stop() to end it early")
	add("  To play it on other characters, change the slots' lines. (If you moved this module,")
	add("  change the path.) LoadScene says in plain words when a character cannot play its")
	add("  slot. In a game, call it where the characters are simulated: a player's own")
	add("  machine for their character, the server for characters nobody plays.")
end

function Handoff.sceneLines(scene: SceneSidecar.SceneSidecar, options: Options?): { string }
	local lines: { string } = {}
	local function add(line: string)
		table.insert(lines, line)
	end
	local names = SceneSidecar.allSlotNames(scene)
	local takes = SceneSidecar.takesOf(scene)
	sceneIntroduction(scene, names, add)
	sceneTakes(takes, add)
	sceneSlots(takes, names, add)
	sceneAnchor(scene, add)
	sceneCamera(takes, add)
	sceneScreen(takes, anyShot(takes), add)
	sceneSnippet(scene, takes, names, options, add)
	return lines
end

function Handoff.sceneModule(scene: SceneSidecar.SceneSidecar, options: Options?): string
	return Serialize.module(scene, Handoff.sceneLines(scene, options))
end

return Handoff
