--!strict

local Joint = {}

Joint.onWrite = nil :: ((instance: Instance) -> ())?

export type JointKind = "Motor6D" | "Bone" | "AnimationConstraint" | "Pivot"

export type Rest = {
	parentOffset: CFrame,
	childOffset: CFrame,
}

export type Joint = {
	kind: JointKind,
	address: string,
	instance: Instance,
	parent: Instance,
	child: Instance,
	simulated: boolean?,
	path: string?,
	outside: boolean?,

	getTransform: (self: Joint) -> CFrame,
	setTransform: (self: Joint, transform: CFrame) -> (),
	getRest: (self: Joint) -> Rest,
	worldCFrame: (self: Joint, parentWorld: CFrame, transform: CFrame?) -> CFrame,
	pivotCFrame: (self: Joint, parentWorld: CFrame, transform: CFrame?) -> CFrame,
	restWorldCFrame: (self: Joint, parentWorld: CFrame) -> CFrame,
	transformFor: (self: Joint, parentWorld: CFrame, desiredWorld: CFrame) -> CFrame,
	transformForPivot: (self: Joint, parentWorld: CFrame, desiredPivot: CFrame) -> CFrame,
}

type Driver = {
	endpoints: (instance: Instance) -> (Instance?, Instance?, string?),
	getTransform: (instance: Instance) -> CFrame,
	setTransform: (instance: Instance, transform: CFrame) -> (),
	getRest: (instance: Instance, parent: Instance) -> (CFrame, CFrame),
	simulated: ((instance: Instance) -> boolean)?,
}

local MOTOR6D: Driver = {
	endpoints = function(instance: Instance): (Instance?, Instance?, string?)
		local motor = instance :: Motor6D
		local part0, part1 = motor.Part0, motor.Part1
		if part0 == nil then
			return nil,
				nil,
				`The Motor6D '{motor.Name}' has no Part0, so it is not attached to anything.`
		end
		if part1 == nil then
			return nil, nil, `The Motor6D '{motor.Name}' has no Part1, so it moves nothing.`
		end
		if part0 == part1 then
			return nil,
				nil,
				`The Motor6D '{motor.Name}' joins '{part0.Name}' to itself, so it moves nothing.`
		end
		return part0, part1, nil
	end,
	getTransform = function(instance: Instance): CFrame
		return (instance :: Motor6D).Transform
	end,
	setTransform = function(instance: Instance, transform: CFrame)
		(instance :: Motor6D).Transform = transform
	end,
	getRest = function(instance: Instance): (CFrame, CFrame)
		local motor = instance :: Motor6D
		return motor.C0, motor.C1
	end,
}

local BONE: Driver = {
	endpoints = function(instance: Instance): (Instance?, Instance?, string?)
		local parent = instance.Parent
		if parent == nil or not (parent:IsA("BasePart") or parent:IsA("Bone")) then
			return nil,
				nil,
				`The bone '{instance.Name}' is not inside a part or another bone, so it is attached to nothing.`
		end
		return parent, instance, nil
	end,
	getTransform = function(instance: Instance): CFrame
		return (instance :: Bone).Transform
	end,
	setTransform = function(instance: Instance, transform: CFrame)
		(instance :: Bone).Transform = transform
	end,
	getRest = function(instance: Instance): (CFrame, CFrame)
		return (instance :: Bone).CFrame, CFrame.identity
	end,
}

local function partOf(attachment: Attachment): BasePart?
	local parent = attachment.Parent
	if parent ~= nil and parent:IsA("BasePart") then
		return parent :: BasePart
	end
	return nil
end

local ANIMATION_CONSTRAINT: Driver = {
	endpoints = function(instance: Instance): (Instance?, Instance?, string?)
		local constraint = instance :: AnimationConstraint
		local name = constraint.Name
		local attachment0, attachment1 = constraint.Attachment0, constraint.Attachment1
		if attachment0 == nil then
			return nil,
				nil,
				`The AnimationConstraint '{name}' has no Attachment0, so it is not attached to anything.`
		end
		if attachment1 == nil then
			return nil,
				nil,
				`The AnimationConstraint '{name}' has no Attachment1, so it moves nothing.`
		end
		local part0, part1 = partOf(attachment0), partOf(attachment1)
		if part0 == nil then
			return nil,
				nil,
				`The AnimationConstraint '{name}' hangs from '{attachment0.Name}', which is not inside a part, so it is not attached to anything.`
		end
		if part1 == nil then
			return nil,
				nil,
				`The AnimationConstraint '{name}' moves '{attachment1.Name}', which is not inside a part, so it moves nothing.`
		end
		if part0 == part1 then
			return nil,
				nil,
				`The AnimationConstraint '{name}' joins '{part0.Name}' to itself, so it moves nothing.`
		end
		return part0, part1, nil
	end,
	getTransform = function(instance: Instance): CFrame
		return (instance :: AnimationConstraint).Transform
	end,
	setTransform = function(instance: Instance, transform: CFrame)
		(instance :: AnimationConstraint).Transform = transform
	end,
	getRest = function(instance: Instance): (CFrame, CFrame)
		local constraint = instance :: AnimationConstraint
		local attachment0, attachment1 = constraint.Attachment0, constraint.Attachment1
		return if attachment0 then attachment0.CFrame else CFrame.identity,
			if attachment1 then attachment1.CFrame else CFrame.identity
	end,
	simulated = function(instance: Instance): boolean
		return not (instance :: AnimationConstraint).IsKinematic
	end,
}

function Joint.movedPartOf(unit: Instance): BasePart?
	if unit:IsA("BasePart") then
		return unit :: BasePart
	end
	if unit:IsA("Model") then
		local primary = (unit :: Model).PrimaryPart
		if primary ~= nil and primary:IsDescendantOf(unit) then
			return primary
		end
	end
	return nil
end

function Joint.pivotOf(unit: Instance): CFrame
	local ok, pivot = pcall(function()
		return (unit :: any):GetPivot()
	end)
	if ok and typeof(pivot) == "CFrame" then
		return pivot
	end
	local part = Joint.movedPartOf(unit)
	if part == nil then
		return CFrame.identity
	end
	return part.CFrame * part.PivotOffset
end

function Joint.pivotTo(unit: Instance, world: CFrame)
	local ok = pcall(function()
		(unit :: any):PivotTo(world)
	end)
	if ok then
		return
	end
	local move = world * Joint.pivotOf(unit):Inverse()
	if unit:IsA("BasePart") then
		local part = unit :: BasePart
		part.CFrame = move * part.CFrame
		return
	end
	for _, descendant in unit:GetDescendants() do
		if descendant:IsA("BasePart") then
			local part = descendant :: BasePart
			part.CFrame = move * part.CFrame
		end
	end
end

type PivotState = {
	rootPart: BasePart,
	rest: CFrame,
	anchor: CFrame?,
	transform: CFrame,
	written: CFrame?,
	posed: { CFrame },
}

local POSED_KEPT = 128

local pivots: { [Instance]: PivotState } = setmetatable({}, { __mode = "k" }) :: any

local NEAR = 1e-3

local function near(a: CFrame, b: CFrame): boolean
	local x = { a:GetComponents() }
	local y = { b:GetComponents() }
	for index = 1, 12 do
		if math.abs(x[index] - y[index]) > NEAR then
			return false
		end
	end
	return true
end

local function atRest(state: PivotState): boolean
	return near(state.transform, CFrame.identity)
end

local function restOf(state: PivotState, parent: Instance): CFrame
	local anchor = state.anchor
	if anchor == nil then
		return state.rest
	end
	local from = if parent:IsA("BasePart") then parent :: BasePart else state.rootPart
	return from.CFrame:ToObjectSpace(anchor)
end

local function restWorldOf(state: PivotState): CFrame
	return state.anchor or state.rootPart.CFrame * state.rest
end

local function settle(state: PivotState, unit: Instance)
	if not atRest(state) then
		return
	end
	local now = Joint.pivotOf(unit)
	if near(now, state.written or restWorldOf(state)) then
		return
	end
	for _, place in state.posed do
		if near(now, place) then
			return
		end
	end
	if state.anchor ~= nil then
		state.anchor = now
	else
		state.rest = state.rootPart.CFrame:ToObjectSpace(now)
	end
	state.written = now
end

local function pivotState(instance: Instance): PivotState
	local state = pivots[instance]
	if state == nil then
		error(`'{instance.Name}' has no pivot joint.`)
	end
	return state
end

local PIVOT: Driver = {
	endpoints = function(instance: Instance): (Instance?, Instance?, string?)
		local state = pivots[instance]
		local part = Joint.movedPartOf(instance)
		if state == nil or part == nil then
			return nil, nil, `'{instance.Name}' is not a part or a model with a PrimaryPart.`
		end
		return state.rootPart, part, nil
	end,
	getTransform = function(instance: Instance): CFrame
		return pivotState(instance).transform
	end,
	setTransform = function(instance: Instance, transform: CFrame)
		local state = pivotState(instance)
		settle(state, instance)
		local world = restWorldOf(state) * transform
		Joint.pivotTo(instance, world)
		state.transform = transform
		state.written = world
		if not near(transform, CFrame.identity) then
			local posed = state.posed
			table.insert(posed, world)
			if #posed > POSED_KEPT then
				table.remove(posed, 1)
			end
		end
	end,
	getRest = function(instance: Instance, parent: Instance): (CFrame, CFrame)
		local state = pivotState(instance)
		local part = Joint.movedPartOf(instance)
		local childOffset = if part ~= nil
			then part.CFrame:ToObjectSpace(Joint.pivotOf(instance))
			else CFrame.identity
		return restOf(state, parent), childOffset
	end,
}

local DRIVERS: { [JointKind]: Driver } = {
	Motor6D = MOTOR6D,
	Bone = BONE,
	AnimationConstraint = ANIMATION_CONSTRAINT,
	Pivot = PIVOT,
}

function Joint.kindOf(instance: Instance): JointKind?
	if instance:IsA("Motor6D") then
		return "Motor6D"
	elseif instance:IsA("Bone") then
		return "Bone"
	elseif instance:IsA("AnimationConstraint") then
		return "AnimationConstraint"
	end
	return nil
end

function Joint.supports(kind: JointKind): boolean
	return DRIVERS[kind] ~= nil
end

function Joint.addressOf(kind: JointKind, instance: Instance): string?
	if kind == "Motor6D" then
		local part1 = (instance :: Motor6D).Part1
		return if part1 then part1.Name else nil
	elseif kind == "Bone" then
		return instance.Name
	elseif kind == "AnimationConstraint" then
		local attachment1 = (instance :: AnimationConstraint).Attachment1
		local driven = if attachment1 then attachment1.Parent else nil
		return if driven then driven.Name else nil
	elseif kind == "Pivot" then
		return instance.Name
	end
	return nil
end

function Joint.worldCFrameOf(endpoint: Instance): CFrame?
	if endpoint:IsA("BasePart") then
		return (endpoint :: BasePart).CFrame
	end
	if endpoint:IsA("Attachment") then
		local parent = endpoint.Parent
		local parentWorld = if parent then Joint.worldCFrameOf(parent) else nil
		if parentWorld == nil then
			return nil
		end
		local offset = (endpoint :: Attachment).CFrame
		if endpoint:IsA("Bone") then
			return parentWorld * offset * (endpoint :: Bone).Transform
		end
		return parentWorld * offset
	end
	return nil
end

local Methods = {}
Methods.__index = Methods

local function driverOf(self: Joint): Driver
	return DRIVERS[self.kind]
end

function Methods.getTransform(self: Joint): CFrame
	return driverOf(self).getTransform(self.instance)
end

function Methods.setTransform(self: Joint, transform: CFrame)
	driverOf(self).setTransform(self.instance, transform)
	local hook = Joint.onWrite
	if hook ~= nil and self.kind ~= "Pivot" then
		hook(self.instance)
	end
end

function Methods.getRest(self: Joint): Rest
	local parentOffset, childOffset = driverOf(self).getRest(self.instance, self.parent)
	return { parentOffset = parentOffset, childOffset = childOffset }
end

function Methods.worldCFrame(self: Joint, parentWorld: CFrame, transform: CFrame?): CFrame
	local parentOffset, childOffset = driverOf(self).getRest(self.instance, self.parent)
	local offset = transform or self:getTransform()
	return parentWorld * parentOffset * offset * childOffset:Inverse()
end

function Methods.pivotCFrame(self: Joint, parentWorld: CFrame, transform: CFrame?): CFrame
	local parentOffset = driverOf(self).getRest(self.instance, self.parent)
	return parentWorld * parentOffset * (transform or self:getTransform())
end

function Methods.restWorldCFrame(self: Joint, parentWorld: CFrame): CFrame
	local parentOffset, childOffset = driverOf(self).getRest(self.instance, self.parent)
	return parentWorld * parentOffset * childOffset:Inverse()
end

function Methods.transformFor(self: Joint, parentWorld: CFrame, desiredWorld: CFrame): CFrame
	local parentOffset, childOffset = driverOf(self).getRest(self.instance, self.parent)
	return (parentWorld * parentOffset):Inverse() * desiredWorld * childOffset
end

function Methods.transformForPivot(self: Joint, parentWorld: CFrame, desiredPivot: CFrame): CFrame
	local parentOffset = driverOf(self).getRest(self.instance, self.parent)
	return (parentWorld * parentOffset):Inverse() * desiredPivot
end

function Joint.new(instance: Instance): (Joint?, string?)
	local kind = Joint.kindOf(instance)
	if kind == nil then
		return nil, `'{instance.Name}' is not a joint.`
	end
	local driver = DRIVERS[kind]
	if driver == nil then
		return nil, `Apex Animator cannot animate '{instance.Name}', a {kind}.`
	end
	local parent, child, problem = driver.endpoints(instance)
	if problem ~= nil or parent == nil or child == nil then
		return nil, problem
	end
	local address = Joint.addressOf(kind, instance)
	if address == nil then
		return nil, `Apex Animator cannot name the joint '{instance.Name}'.`
	end
	local simulated = if driver.simulated and driver.simulated(instance) then true else nil
	local joint = {
		kind = kind,
		address = address,
		instance = instance,
		parent = parent,
		child = child,
		simulated = simulated,
	}
	return (setmetatable(joint, Methods) :: any) :: Joint
end

function Joint.pivot(unit: Instance, rootPart: BasePart, outside: boolean?): (Joint?, string?)
	local part = Joint.movedPartOf(unit)
	if part == nil then
		return nil, `'{unit.Name}' is not a part or a model with a PrimaryPart.`
	end
	local state = pivots[unit]
	if
		state == nil
		or (state.anchor ~= nil) ~= (outside == true)
		or (not outside and state.rootPart ~= rootPart)
	then
		local world = Joint.pivotOf(unit)
		state = {
			rootPart = rootPart,
			rest = rootPart.CFrame:ToObjectSpace(world),
			anchor = if outside then world else nil,
			transform = CFrame.identity,
			written = nil,
			posed = {},
		}
		pivots[unit] = state :: PivotState
	else
		settle(state :: PivotState, unit)
	end
	local joint = {
		kind = "Pivot",
		address = unit.Name,
		instance = unit,
		parent = rootPart,
		child = part,
		outside = if outside then true else nil,
	}
	return (setmetatable(joint, Methods) :: any) :: Joint
end

return Joint
