--!strict

local Joint = require(script.Parent.Joint)

local JointGraph = {}

type Joint = Joint.Joint

export type Collision = {
	address: string,
	joints: { Joint },
	endpoints: { Instance },
}

export type Skipped = {
	instance: Instance,
	kind: Joint.JointKind,
	address: string?,
	reason: string,
}

export type Graph = {
	root: Instance,
	rootPart: BasePart?,
	joints: { Joint },
	byAddress: { [string]: Joint },
	parentOf: { [Joint]: Joint },
	childrenOf: { [Joint]: { Joint } },
	depthOf: { [Joint]: number },
	collisions: { Collision },
	unsupported: { Skipped },
	broken: { Skipped },
	detached: { Joint },
	pivots: { Joint }?,
}

export type BuildOptions = {
	pivots: boolean?,
}

local function before(a: Joint, b: Joint): boolean
	if a.address ~= b.address then
		return a.address < b.address
	end
	return a.instance:GetFullName() < b.instance:GetFullName()
end

local function markedRoot(root: Instance): BasePart?
	if root:IsA("BasePart") then
		return root :: BasePart
	end
	local humanoid = root:FindFirstChildOfClass("Humanoid")
	if humanoid and humanoid.RootPart then
		return humanoid.RootPart
	end
	local named = root:FindFirstChild("HumanoidRootPart")
	if named and named:IsA("BasePart") then
		return named :: BasePart
	end
	if root:IsA("Model") then
		return (root :: Model).PrimaryPart
	end
	return nil
end

local function findRootPart(
	root: Instance,
	drivenBy: { [Instance]: { Joint } },
	tops: { Joint },
	sizeOf: { [Joint]: number }
): BasePart?
	local marked = markedRoot(root)
	if marked then
		local node: Instance = marked
		local climbed: { [Instance]: boolean } = {}
		while drivenBy[node] and not climbed[node] do
			climbed[node] = true
			node = drivenBy[node][1].parent
		end
		return if node:IsA("BasePart") then node :: BasePart else marked
	end

	local weightOf: { [Instance]: number } = {}
	local best: Instance? = nil
	for _, top in tops do
		local base = top.parent
		weightOf[base] = (weightOf[base] or 0) + sizeOf[top]
		if best == nil or weightOf[base] > weightOf[best :: Instance] then
			best = base
		end
	end
	if best and best:IsA("BasePart") then
		return best :: BasePart
	end
	return nil
end

local function tiedEnds(instance: Instance): (Instance?, Instance?)
	if instance:IsA("WeldConstraint") then
		local weld = instance :: WeldConstraint
		return weld.Part0, weld.Part1
	end
	if instance:IsA("JointInstance") then
		if Joint.kindOf(instance) ~= nil then
			return nil, nil
		end
		local weld = instance :: JointInstance
		return weld.Part0, weld.Part1
	end
	if instance:IsA("Constraint") and Joint.kindOf(instance) == nil then
		local constraint = instance :: Constraint
		local a0, a1 = constraint.Attachment0, constraint.Attachment1
		return if a0 then a0.Parent else nil, if a1 then a1.Parent else nil
	end
	return nil, nil
end

local function partAt(instance: Instance?): BasePart?
	local node = instance
	while node ~= nil do
		if node:IsA("BasePart") then
			return node :: BasePart
		end
		node = node.Parent
	end
	return nil
end

local function looseUnits(
	root: Instance,
	rootPart: BasePart?,
	found: { Joint },
	skipped: { Skipped }
): { Instance }
	local descendants = root:GetDescendants()
	local held: { [BasePart]: boolean } = {}
	local queue: { BasePart } = {}
	local function hold(instance: Instance?)
		local part = partAt(instance)
		if part ~= nil and not held[part] then
			held[part] = true
			table.insert(queue, part)
		end
	end
	hold(rootPart)
	for _, joint in found do
		hold(joint.parent)
		hold(joint.child)
	end
	for _, skip in skipped do
		hold(skip.instance)
		if skip.instance:IsA("JointInstance") then
			local motor = skip.instance :: JointInstance
			hold(motor.Part0)
			hold(motor.Part1)
		end
	end

	local inRig: { [Instance]: boolean } = {}
	for _, instance in descendants do
		inRig[instance] = true
	end
	local ties: { [BasePart]: { BasePart } } = {}
	local function tie(a: BasePart, b: BasePart)
		local list = ties[a]
		if list == nil then
			list = {}
			ties[a] = list
		end
		table.insert(list, b)
	end
	for _, instance in descendants do
		local a, b = tiedEnds(instance)
		local partA, partB = partAt(a), partAt(b)
		if partA == nil or partB == nil or partA == partB then
			continue
		end
		tie(partA, partB)
		tie(partB, partA)
		if not inRig[partA] then
			hold(partB)
		elseif not inRig[partB] then
			hold(partA)
		end
	end
	local at = 1
	while at <= #queue do
		for _, other in ties[queue[at]] or {} do
			hold(other)
		end
		at += 1
	end

	local units: { Instance } = {}
	local function free(model: Model): boolean
		for _, instance in model:GetDescendants() do
			if Joint.kindOf(instance) ~= nil then
				return false
			end
			if instance:IsA("BasePart") then
				local part = instance :: BasePart
				if held[part] then
					return false
				end
				for _, other in ties[part] or {} do
					if not other:IsDescendantOf(model) then
						return false
					end
				end
			end
		end
		return true
	end
	local function walk(parent: Instance)
		for _, child in parent:GetChildren() do
			if child:IsA("Model") and Joint.movedPartOf(child) ~= nil and free(child :: Model) then
				table.insert(units, child)
				continue
			end
			if
				child:IsA("BasePart")
				and not held[child :: BasePart]
				and ties[child :: BasePart] == nil
			then
				table.insert(units, child)
			end
			walk(child)
		end
	end
	walk(root)
	return units
end

local function addPivots(graph: Graph, found: { Joint }, skipped: { Skipped })
	local rootPart = graph.rootPart
	local list: { Joint } = {}
	graph.pivots = list
	if rootPart == nil then
		return
	end
	for _, unit in looseUnits(graph.root, rootPart, found, skipped) do
		local name = unit.Name
		if graph.byAddress[name] ~= nil or rootPart.Name == name then
			table.insert(graph.broken, {
				instance = unit,
				kind = "Pivot",
				address = name,
				reason = `'{name}' can't be moved on its own: something else in the rig is called '{name}'. Rename it, then load the rig again.`,
			})
			continue
		end
		local joint = Joint.pivot(unit, rootPart)
		if joint == nil then
			continue
		end
		local names: { string } = {}
		local node: Instance? = unit
		while node ~= nil and node ~= graph.root do
			table.insert(names, 1, node.Name)
			node = node.Parent
		end
		joint.path = table.concat(names, "/")
		graph.byAddress[name] = joint
		graph.depthOf[joint] = 0
		graph.childrenOf[joint] = {}
		table.insert(graph.joints, joint)
		table.insert(list, joint)
	end
end

function JointGraph.build(root: Instance, options: BuildOptions?): Graph
	local found: { Joint } = {}
	local unsupported: { Skipped } = {}
	local broken: { Skipped } = {}

	for _, instance in root:GetDescendants() do
		local kind = Joint.kindOf(instance)
		if kind == nil then
			continue
		end
		local joint, reason = Joint.new(instance)
		if joint then
			table.insert(found, joint)
		else
			local skipped: Skipped = {
				instance = instance,
				kind = kind,
				address = Joint.addressOf(kind, instance),
				reason = reason or `'{instance.Name}' cannot be animated.`,
			}
			table.insert(if Joint.supports(kind) then broken else unsupported, skipped)
		end
	end
	table.sort(found, before)

	local drivenBy: { [Instance]: { Joint } } = {}
	for _, joint in found do
		local list = drivenBy[joint.child]
		if list == nil then
			list = {}
			drivenBy[joint.child] = list
		end
		table.insert(list, joint)
	end

	local parentOf: { [Joint]: Joint } = {}
	local childrenOf: { [Joint]: { Joint } } = {}
	for _, joint in found do
		childrenOf[joint] = {}
	end
	for _, joint in found do
		local drivers = drivenBy[joint.parent]
		if drivers then
			local parent = drivers[1]
			parentOf[joint] = parent
			table.insert(childrenOf[parent], joint)
		end
	end

	local tops: { Joint } = {}
	for _, joint in found do
		if parentOf[joint] == nil then
			table.insert(tops, joint)
		end
	end
	local sizeOf: { [Joint]: number } = {}
	local function measure(joint: Joint): number
		local size = 1
		for _, child in childrenOf[joint] do
			size += measure(child)
		end
		sizeOf[joint] = size
		return size
	end
	for _, top in tops do
		measure(top)
	end

	local rootPart = findRootPart(root, drivenBy, tops, sizeOf)

	local ordered: { Joint } = {}
	local depthOf: { [Joint]: number } = {}
	local detached: { Joint } = {}
	local function visit(joint: Joint, depth: number)
		depthOf[joint] = depth
		table.insert(ordered, joint)
		for _, child in childrenOf[joint] do
			if depthOf[child] == nil then
				visit(child, depth + 1)
			end
		end
	end
	for _, top in tops do
		if top.parent == rootPart then
			visit(top, 0)
		end
	end
	for _, top in tops do
		if top.parent ~= rootPart then
			table.insert(detached, top)
			visit(top, 0)
		end
	end
	for _, joint in found do
		if depthOf[joint] == nil then
			local parent = parentOf[joint]
			if parent then
				parentOf[joint] = nil
				local siblings = childrenOf[parent]
				local at = table.find(siblings, joint)
				if at then
					table.remove(siblings, at)
				end
			end
			table.insert(detached, joint)
			visit(joint, 0)
		end
	end

	local positionOf: { [Joint]: number } = {}
	for position, joint in ordered do
		positionOf[joint] = position
	end

	local sharing: { [string]: { Joint } } = {}
	local addresses: { string } = {}
	for _, joint in ordered do
		local list = sharing[joint.address]
		if list == nil then
			list = {}
			sharing[joint.address] = list
			table.insert(addresses, joint.address)
		end
		table.insert(list, joint)
	end

	local byAddress: { [string]: Joint } = {}
	for _, address in addresses do
		local list = sharing[address]
		if #list > 1 then
			table.sort(list, function(a, b)
				if depthOf[a] ~= depthOf[b] then
					return depthOf[a] < depthOf[b]
				end
				return positionOf[a] < positionOf[b]
			end)
		end
		byAddress[address] = list[1]
	end

	local collisions: { Collision } = {}
	for _, address in addresses do
		local joints = sharing[address]
		local clashesWithRoot = rootPart ~= nil and rootPart.Name == address
		if #joints < 2 and not clashesWithRoot then
			continue
		end
		local endpoints: { Instance } = {}
		local listed: { [Instance]: boolean } = {}
		if clashesWithRoot then
			local part = rootPart :: BasePart
			table.insert(endpoints, part)
			listed[part] = true
		end
		for _, joint in joints do
			if not listed[joint.child] then
				listed[joint.child] = true
				table.insert(endpoints, joint.child)
			end
		end
		if #joints < 2 and #endpoints < 2 then
			continue
		end
		table.insert(collisions, { address = address, joints = joints, endpoints = endpoints })
	end

	local graph: Graph = {
		root = root,
		rootPart = rootPart,
		joints = ordered,
		byAddress = byAddress,
		parentOf = parentOf,
		childrenOf = childrenOf,
		depthOf = depthOf,
		collisions = collisions,
		unsupported = unsupported,
		broken = broken,
		detached = detached,
	}
	if type(options) == "table" and options.pivots == true then
		local skipped = table.clone(broken)
		table.move(unsupported, 1, #unsupported, #skipped + 1, skipped)
		addPivots(graph, found, skipped)
	end
	return graph
end

function JointGraph.branchesOf(graph: Graph): { Joint }
	local rootPart = graph.rootPart
	if rootPart == nil then
		return {}
	end
	local parentOf = graph.parentOf or {}
	local sizes: { [Joint]: number } = {}
	for _, joint in graph.joints do
		local top = joint
		while parentOf[top] ~= nil do
			top = parentOf[top]
		end
		sizes[top] = (sizes[top] or 0) + 1
	end
	local branches: { Joint } = {}
	local main = 0
	for _, joint in graph.joints do
		if joint.parent == rootPart and joint.kind ~= "Pivot" then
			table.insert(branches, joint)
			if main == 0 or (sizes[joint] or 0) > (sizes[branches[main]] or 0) then
				main = #branches
			end
		end
	end
	if main > 1 then
		table.insert(branches, 1, table.remove(branches, main) :: Joint)
	end
	return branches
end

function JointGraph.worldCFrames(
	graph: Graph,
	transformOf: ((joint: Joint) -> CFrame)?,
	rootWorld: CFrame?
): { [Joint]: CFrame }
	local rootPart = graph.rootPart
	local base = rootWorld or (if rootPart then rootPart.CFrame else CFrame.identity)
	local world: { [Joint]: CFrame } = {}
	for _, joint in graph.joints do
		local parent = graph.parentOf[joint]
		local parentWorld: CFrame
		if parent then
			parentWorld = world[parent]
		elseif joint.parent == rootPart then
			parentWorld = base
		else
			parentWorld = Joint.worldCFrameOf(joint.parent) or CFrame.identity
		end
		local transform = if transformOf then transformOf(joint) else nil
		world[joint] = joint:worldCFrame(parentWorld, transform)
	end
	return world
end

return JointGraph
