--!strict

local Path = {}

Path.WORKSPACE = "@Workspace"

local WORKSPACE_PREFIX = Path.WORKSPACE .. "/"

function Path.inWorkspace(path: string): string?
	if #path > #WORKSPACE_PREFIX and string.sub(path, 1, #WORKSPACE_PREFIX) == WORKSPACE_PREFIX then
		return string.sub(path, #WORKSPACE_PREFIX + 1)
	end
	return nil
end

function Path.split(path: string): { string }
	local parts = {}
	for segment in string.gmatch(path, "[^/]+") do
		table.insert(parts, segment)
	end
	return parts
end

function Path.resolve(root: Instance, path: string): Instance?
	local parts = Path.split(path)
	if #parts == 0 or parts[1] ~= root.Name then
		return nil
	end
	local node: Instance? = root
	for i = 2, #parts do
		if node == nil then
			return nil
		end
		node = (node :: Instance):FindFirstChild(parts[i])
	end
	return node
end

function Path.of(root: Instance, instance: Instance): string?
	if instance == root then
		return root.Name
	end
	local names = { instance.Name }
	local node: Instance? = instance.Parent
	while node ~= nil and node ~= root do
		table.insert(names, (node :: Instance).Name)
		node = (node :: Instance).Parent
	end
	if node ~= root then
		return nil
	end
	table.insert(names, root.Name)
	local count = #names
	for i = 1, count // 2 do
		names[i], names[count + 1 - i] = names[count + 1 - i], names[i]
	end
	return table.concat(names, "/")
end

return Path
