local RANK: { [string]: number } = {}
for index, name in LEAD do
	RANK[name] = index
end

local KEYWORDS: { [string]: boolean } = {}
for _, word in
	{
		"and",
		"break",
		"do",
		"else",
		"elseif",
		"end",
		"false",
		"for",
		"function",
		"if",
		"in",
		"local",
		"nil",
		"not",
		"or",
		"repeat",
		"return",
		"then",
		"true",
		"until",
		"while",
	}
do
	KEYWORDS[word] = true
end

local function quote(s: string): string
	return string.format("%q", s)
end

type Trail = { any }

local function pathOf(trail: Trail): string
	local parts = { "the value" }
	for _, key in trail do
		table.insert(parts, if type(key) == "number" then `[{key}]` else `.{key}`)
	end
	return table.concat(parts)
end

local function fail(trail: Trail, what: string): never
	error(`Serialize: cannot write {what} (at {pathOf(trail)})`, 0)
end

local function isFinite(n: number): boolean
	return n == n and n ~= math.huge and n ~= -math.huge
end

local function writtenBefore(a: any, b: any): boolean
	local ta, tb = type(a), type(b)
	if ta ~= tb then
		return ta == "number"
	end
	if ta == "number" then
		return a < b
	end
	local ra, rb = RANK[a], RANK[b]
	if ra ~= nil or rb ~= nil then
		if ra == nil then
			return false
		elseif rb == nil then
			return true
		end
		return ra < rb
	end
	return a < b
end

local function keysOf(value: { [any]: any }, trail: Trail): { any }
	local keys = {}
	for key in value do
		local kind = type(key)
		if kind == "number" then
			if not isFinite(key) then
				fail(trail, "a key that is not a finite number")
			end
		elseif kind ~= "string" then
			fail(trail, `a key that is a {typeof(key)}`)
		end
		table.insert(keys, key)
	end
	table.sort(keys, writtenBefore)
	return keys
end

local function arrayLength(value: { [any]: any }): number?
	local count = 0
	for _ in value do
		count += 1
	end
	for key in value do
		if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > count then
			return nil
		end
	end
	return count
end

local function keyLiteral(key: any): string
	if type(key) == "number" then
		return "[" .. Value.numLit(key) .. "]"
	end
	if string.match(key, "^[%a_][%w_]*$") and not KEYWORDS[key] then
		return key
	end
	return "[" .. quote(key) .. "]"
end

local write: (value: any, depth: number, trail: Trail, open: { [any]: boolean }) -> string

local function scalar(value: any, trail: Trail): string
	local kind = type(value)
	if kind == "boolean" then
		return tostring(value)
	elseif kind == "number" then
		return Value.numLit(value)
	elseif kind == "string" then
		return quote(value)
	end
	local typeName = typeof(value)
	if typeName == "EnumItem" or Value.supports(typeName) then
		return Value.toLuau(typeName, value)
	end
	return fail(trail, `a {typeName}`)
end

local function writeTable(
	value: { [any]: any },
	depth: number,
	trail: Trail,
	open: { [any]: boolean }
): string
	if open[value] then
		fail(trail, "a table that contains itself")
	end
	open[value] = true

	local length = arrayLength(value)
	local keys: { any }
	if length ~= nil then
		keys = {}
		for index = 1, length do
			keys[index] = index
		end
	else
		keys = keysOf(value, trail)
	end
	if #keys == 0 then
		open[value] = nil
		return "{}"
	end

	local entries: { string } = {}
	local flat = true
	local at = #trail + 1
	for _, key in keys do
		local item = value[key]
