	if flat then
		local line = "{ " .. table.concat(entries, ", ") .. " }"
		if #line <= Serialize.INLINE_WIDTH then
			return line
		end
	end
	local inner = string.rep(Serialize.INDENT, depth + 1)
	local lines = { "{" }
	for _, entry in entries do
		table.insert(lines, inner .. entry .. ",")
	end
	table.insert(lines, string.rep(Serialize.INDENT, depth) .. "}")
	return table.concat(lines, "\n")
end

function write(value: any, depth: number, trail: Trail, open: { [any]: boolean }): string
	if type(value) == "table" then
		return writeTable(value, depth, trail, open)
	end
	return scalar(value, trail)
end

function Serialize.value(value: any): string
	if value == nil then
		return "nil"
	end
	return write(value, 0, {}, {})
end

function Serialize.module(value: any, header: { string }?): string
	local lines: { string } = {}
	for _, line in header or {} do
		local flat = string.gsub(line, "[\r\n]+", " ")
		table.insert(lines, if flat == "" then "--" else "-- " .. flat)
	end
	table.insert(lines, "return " .. Serialize.value(value))
	return table.concat(lines, "\n") .. "\n"
end

return Serialize
