--!strict

local Types = require(script.Parent.Types)
local Schema = require(script.Parent.Schema)
local Path = require(script.Parent.Path)
local PropRegistry = require(script.Parent.PropRegistry)
local Bake = require(script.Parent.Parent.Shared.Bake)
local LayerEval = require(script.Parent.Parent.Shared.LayerEval)
local NativeCurve = require(script.Parent.Parent.Shared.NativeCurve)
local NativeKeys = require(script.Parent.Parent.Shared.NativeKeys)
local Pose = require(script.Parent.Parent.Shared.Pose)
local ShareMovement = require(script.Parent.Parent.Shared.Movement)
local ReleaseMath = require(script.Parent.Parent.Shared.ReleaseMath)
local SpaceSolve = require(script.Parent.Parent.Shared.SpaceSolve)

local Sidecar = {}

Sidecar.FORMAT = 19

Sidecar.WORKSPACE_FORMAT = 19

Sidecar.BASE_FORMAT = 1

Sidecar.ATTRIBUTE = "ApexAssetId"

Sidecar.TEMP_ATTRIBUTE = "ApexTempId"

Sidecar.HASH_ATTRIBUTE = "ApexHash"

Sidecar.ENGINE_ATTRIBUTE = "ApexNeedsEngine"

export type Sidecar = {
	format: number,
	assetId: number?,
	hash: string,
	name: string,
	length: number,
	fps: number,
	loop: boolean,
	interrupt: Types.InterruptPolicy,
	spaceMismatch: Types.SpaceMismatchPolicy,
	spaceAdoptTime: number,
	joints: { [string]: Types.JointTrack },
	startingSpaces: { [string]: Types.SpaceTarget }?,
	states: { Types.StateTrack }?,
	props: { [string]: Types.PropTarget }?,
	sounds: { Types.SoundTrack }?,
	markers: { Types.Marker }?,
	presets: { [string]: Types.EasingPreset }?,
	movement: Movement?,
	releases: { Release }?,
	scene: SceneSlot?,
	pivots: { [string]: Pivot }?,
	scale: number?,
}

export type Pivot = {
	path: string,
	rotationMode: Types.RotationMode,
	channels: { [string]: Types.Channel },
}

export type Movement = {
	keys: { Types.MovementKey },
	joints: { [string]: Types.MovementJoint }?,
}

export type SceneSlot = {
	name: string,
	slot: string,
	slots: { string },
	assets: { [string]: number },
	temps: { [string]: string }?,
}

export type ReleaseVelocity = {
	linear: { number },
	angular: { number },
}

export type Release = {
	t: number,
	joint: string,
	kind: Types.ReleaseKind?,
	lifetime: number?,
	cap: number?,
	cosmetic: boolean?,
	collide: boolean?,
	event: string?,
	onEnd: Types.EndBehaviour?,
	leaveCopy: boolean?,
	onto: Types.SpaceTarget?,
	velocity: ReleaseVelocity?,
}

export type Policies = {
	interrupt: Types.InterruptPolicy,
	spaceMismatch: Types.SpaceMismatchPolicy,
	spaceAdoptTime: number,
}

export type ValueAt = (address: string, t: number) -> CFrame

export type BuildOptions = {
	assetId: number?,
	valueAt: ValueAt?,
	settings: Bake.Settings?,
	releases: { Release }?,
	movement: Types.MovementTrack?,
	pivots: { [string]: string }?,
	pivotValueAt: ValueAt?,
	scale: number?,
}

local function copy<T>(value: T): T
	if type(value) ~= "table" then
		return value
	end
	local out = {}
	for key, item in value :: any do
		out[key] = copy(item)
	end
	return out :: any
end

local function exportedMarkers(markers: { Types.Marker }?): { Types.Marker }?
	if markers == nil then
		return nil
	end
	local out: { Types.Marker } = {}
	for _, marker in markers do
		table.insert(out, {
			name = marker.name,
			t = marker.t,
			len = marker.len,
			metadata = marker.metadata,
		})
	end
	return out
end

local function isFinite(value: any): boolean
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function isWhole(value: any): boolean
	return isFinite(value) and value % 1 == 0
end

local function leavesParent(track: Types.JointTrack?, starting: Types.SpaceTarget?): boolean
	if starting ~= nil and starting.kind ~= "Parent" then
		return true
	end
	if track ~= nil then
		for _, switch in track.spaces or {} do
			if switch.target.kind ~= "Parent" then
				return true
			end
		end
	end
	return false
end

local function presetsOfKeys(keys: { any }?, into: { [string]: boolean })
	for _, key in keys or {} do
		if type(key) == "table" and type(key.preset) == "string" then
			into[key.preset] = true
		end
	end
end

local SAME = 1e-9

local function restOf(name: string): number
	return if name == "qw" then 1 else 0
end

local function toleranceOf(name: string, resolved: Bake.Resolved): number
	if name == "px" or name == "py" or name == "pz" then
		return resolved.position / math.sqrt(3)
	elseif name == "rx" or name == "ry" or name == "rz" then
		return resolved.rotation / 3
	end
	return resolved.rotation / 4
end

function Sidecar.layerValues(doc: Types.RigDocument): ValueAt
	local options = { presets = doc.presets, fps = doc.fps }
	return function(address: string, t: number): CFrame
		return LayerEval.pose(doc :: any, address, t, options :: any)
	end
end

type Sample = { t: number, values: Pose.Values }

local function trackOf(doc: Types.RigDocument, address: string): Types.JointTrack?
	local track = doc.joints[address]
	if track ~= nil then
		return track
	end
	for _, layer in doc.layers or {} do
		local found = layer.joints[address]
		if found ~= nil then
			return found
		end
	end
	return nil
end

function Sidecar.curves(
	doc: Types.RigDocument,
	address: string,
	valueAt: ValueAt,
	resolved: Bake.Resolved
): { [string]: Types.Channel }
	local track = trackOf(doc, address)
	if track == nil then
		return {}
	end
	local mode = track.rotationMode
	local names: { string } = { "px", "py", "pz" }
	for _, name in (if mode == "Quaternion" then Pose.QUATERNION_CHANNELS else Pose.EULER_CHANNELS) do
		table.insert(names, name)
	end
	local length = math.max(doc.length, 0)
	local rate = resolved.rate

	local times: { number } = {}
	local knots: { number } = {}
	for step = 0, math.floor(length * rate + SAME) do
		table.insert(times, math.min(step / rate, length))
	end
	table.insert(times, length)
	local function keyTimes(source: Types.JointTrack?)
		if source == nil then
			return
		end
		for _, channel in source.channels do
			for _, key in channel.keys do
				if key.t > SAME and key.t < length - SAME then
					table.insert(times, key.t)
					table.insert(knots, key.t)
				end
			end
		end
	end
	keyTimes(track)
	for _, layer in doc.layers or {} do
		if layer.mute ~= true then
			keyTimes(layer.joints[address])
		end
	end
	local switches: { number } = {}
	for _, switch in track.spaces or {} do
		if switch.t > SAME and switch.t <= length then
			table.insert(times, switch.t)
			table.insert(times, math.max(switch.t - Bake.JUMP_LEAD, 0))
			table.insert(switches, switch.t)
		end
	end
	table.sort(times)

	local samples: { Sample } = {}
	local previous: Pose.Values? = nil
	for _, t in times do
		if #samples > 0 and t - samples[#samples].t <= SAME then
			continue
		end
		local values = Pose.toValues(valueAt(address, t), mode, previous)
		previous = values
		table.insert(samples, { t = t, values = values })
	end

	local tolerances: { [string]: number } = {}
	local jumps: { [string]: { number } } = {}
	for _, name in names do
		tolerances[name] = toleranceOf(name, resolved)
		jumps[name] = {}
	end
	local switchAt: { [number]: boolean } = {}
	for _, s in switches do
		for index = 2, #samples do
			local sample = samples[index]
			if math.abs(sample.t - s) <= SAME then
				switchAt[sample.t] = true
				local before = samples[index - 1].values :: any
				local after = sample.values :: any
				for _, name in names do
					local a = before[name] or restOf(name)
					local b = after[name] or restOf(name)
					if math.abs(b - a) > tolerances[name] then
						table.insert(jumps[name], sample.t)
					end
				end
				break
			end
		end
	end

	local fitted: { [string]: { NativeCurve.Key } } = {}
	local function column(name: string): ({ number }, { number })
		local ts: { number } = table.create(#samples)
		local vs: { number } = table.create(#samples)
		for index, sample in samples do
			ts[index] = sample.t
			vs[index] = (sample.values :: any)[name] or restOf(name)
		end
		return ts, vs
	end
	for round = 0, Bake.REFINE_DEPTH do
		for _, name in names do
			local ts, vs = column(name)
			fitted[name] = Bake.fit(ts, vs, tolerances[name] * Bake.FIT_SHARE, knots, jumps[name])
		end
		if round == Bake.REFINE_DEPTH then
			break
		end
		local added: { Sample } = {}
		for index = 1, #samples - 1 do
			local a, b = samples[index], samples[index + 1]
			if switchAt[b.t] or b.t - a.t <= 2 * SAME then
				continue
			end
			local middle = (a.t + b.t) / 2
			local values = Pose.toValues(valueAt(address, middle), mode, a.values)
			for _, name in names do
				local want = (values :: any)[name] or restOf(name)
				if
					math.abs(NativeCurve.evaluate(fitted[name], middle) - want) > tolerances[name]
				then
					table.insert(added, { t = middle, values = values })
					break
				end
			end
		end
		if #added == 0 then
			break
		end
		for _, sample in added do
			table.insert(samples, sample)
		end
		table.sort(samples, function(x: Sample, y: Sample): boolean
			return x.t < y.t
		end)
	end

	local channels: { [string]: Types.Channel } = {}
	for _, name in names do
		local rest = restOf(name)
		local still = true
		for _, sample in samples do
			local v = (sample.values :: any)[name] or rest
			if math.abs(v - rest) > tolerances[name] * Bake.FIT_SHARE then
				still = false
				break
			end
		end
		if not still then
			channels[name] = { keys = NativeKeys.toDocument(fitted[name]) :: any }
		end
	end
	return channels
end

function Sidecar.switchedJoints(doc: Types.RigDocument): { string }
	local starting = doc.startingSpaces or {}
	local list: { string } = {}
	for address, track in doc.joints do
		if leavesParent(track, starting[address]) then
			table.insert(list, address)
		end
	end
	table.sort(list)
	return list
end

function Sidecar.build(
	doc: Types.RigDocument,
	bake: { hash: string },
	options: BuildOptions?
): Sidecar
	local resolved = Bake.settings(doc :: any, if options ~= nil then options.settings else nil)
	local valueAt: ValueAt = if options ~= nil and options.valueAt ~= nil
		then options.valueAt
		else Sidecar.layerValues(doc)
	local pivotPaths = if options ~= nil then options.pivots else nil
	local joints: { [string]: Types.JointTrack } = {}
	for _, address in Sidecar.switchedJoints(doc) do
		if pivotPaths ~= nil and pivotPaths[address] ~= nil then
			continue
		end
		local track = doc.joints[address]
		joints[address] = {
			rotationMode = track.rotationMode,
			channels = Sidecar.curves(doc, address, valueAt, resolved),
			spaces = copy(track.spaces),
		}
	end

	local pivots: { [string]: Pivot }? = nil
	if pivotPaths ~= nil then
		local pivotValueAt = (options :: BuildOptions).pivotValueAt or valueAt
		local names: { string } = {}
		for address in pivotPaths do
			table.insert(names, address)
		end
		table.sort(names)
		for _, address in names do
			local track = trackOf(doc, address)
			if track == nil then
				continue
			end
			local channels = Sidecar.curves(doc, address, pivotValueAt, resolved)
			if next(channels) ~= nil then
				pivots = pivots or {}
				(pivots :: any)[address] = {
					path = pivotPaths[address],
					rotationMode = track.rotationMode,
					channels = channels,
				}
			end
		end
	end

	local used: { [string]: boolean } = {}
	for _, track in joints do
		for _, channel in track.channels do
			presetsOfKeys(channel.keys, used)
		end
	end
	for _, pivot in pivots or {} do
		for _, channel in pivot.channels do
			presetsOfKeys(channel.keys, used)
		end
	end
	for _, state in doc.states or {} do
		if state.curve ~= nil then
			presetsOfKeys(state.curve.keys, used)
		end
	end
	for _, target in doc.props or {} do
		if PropRegistry.NATIVE[target.className] then
			continue
		end
		for _, property in target.properties do
			presetsOfKeys(property.keys, used)
		end
	end
	local sounds: { Types.SoundTrack }? = nil
	for _, sound in doc.sounds or {} do
		if #sound.clips > 0 then
			sounds = sounds or {}
			table.insert(sounds :: { Types.SoundTrack }, copy(sound))
			for _, clip in sound.clips do
				presetsOfKeys({ clip.fadeIn, clip.fadeOut }, used)
			end
		end
	end
	local presets: { [string]: Types.EasingPreset }? = nil
	if doc.presets ~= nil then
		for name in used do
			local preset = doc.presets[name]
			if preset ~= nil then
				presets = presets or {}
				(presets :: any)[name] = copy(preset)
			end
		end
	end

	local assetId = if options ~= nil and options.assetId ~= nil
		then options.assetId
		else if doc.publish ~= nil then doc.publish.assetId else nil
	local track = if options ~= nil then options.movement else nil
	local movement: Movement? = nil
	if track ~= nil and ShareMovement.keyed(track :: any) then
		local branches: { [string]: Types.MovementJoint }? = nil
		for address, branch in track.joints or {} do
			if #branch.keys > 0 then
				branches = branches or {}
				(branches :: any)[address] = { keys = copy(branch.keys) }
			end
		end
		movement = { keys = copy(track.keys), joints = branches }
	end
	local props: { [string]: Types.PropTarget }? = nil
	for path, target in doc.props or {} do
		if not PropRegistry.NATIVE[target.className] then
			props = props or {}
			(props :: any)[path] = copy(target)
		end
	end
	local releases: { Release }? = copy(
		if options ~= nil and options.releases ~= nil
			then options.releases
			else doc.releases :: { Release }?
	)

	return {
		format = Sidecar.formatOf(movement, releases, sounds, props, pivots),
		assetId = assetId,
		hash = bake.hash,
		name = doc.name,
		length = doc.length,
		fps = doc.fps,
		loop = doc.loop,
		interrupt = doc.interrupt or "Revert",
		spaceMismatch = doc.spaceMismatch or "Adopt",
		spaceAdoptTime = doc.spaceAdoptTime or Schema.DEFAULT_ADOPT_TIME,
		joints = joints,
		startingSpaces = copy(doc.startingSpaces),
		states = copy(doc.states),
		props = props,
		sounds = sounds,
		markers = exportedMarkers(doc.markers),
		presets = presets,
		movement = movement,
		releases = releases,
		pivots = pivots,
		scale = if options ~= nil then options.scale else nil,
	}
end

local function featureFormat(
	movement: Movement?,
	releases: { Release }?,
	sounds: { Types.SoundTrack }?,
	props: { [string]: Types.PropTarget }?,
	pivots: { [string]: Pivot }?
): number
	for path in props or {} do
		if Path.inWorkspace(path) ~= nil then
			return Sidecar.WORKSPACE_FORMAT
		end
	end
	for _, pivot in pivots or {} do
		if Path.inWorkspace(pivot.path) ~= nil then
			return Sidecar.WORKSPACE_FORMAT
		end
	end
	for _, target in props or {} do
		if target.properties[Schema.HEAD_PROPERTY] ~= nil then
			return 18
		end
	end
	for path in props or {} do
		if Schema.LOOK_TARGETS[path] ~= nil then
			return 17
		end
	end
	for _, target in props or {} do
		if target.layer ~= nil then
			return 16
		end
		local texture = target.properties.Texture
		for _, key in if texture ~= nil then texture.keys else {} do
			if key.fade ~= nil and key.fade > 0 then
				return 16
			end
		end
	end
	if movement ~= nil then
		local rows: { { Types.MovementKey } } = { movement.keys }
		for _, branch in movement.joints or {} do
			table.insert(rows, branch.keys)
		end
		for _, keys in rows do
			for _, key in keys do
				if key.kind == "Waypoint" then
					return 13
				end
			end
		end
	end
	if pivots ~= nil and next(pivots) ~= nil then
		return 12
	end
	for _, target in props or {} do
		if target.className == "Model" then
			return 11
		end
	end
	for _, target in props or {} do
		for _, track in target.properties do
			if track.type == "Vector3" then
				return 10
			end
		end
	end
	if sounds ~= nil and #sounds > 0 then
		return 8
	end
	if movement ~= nil and movement.joints ~= nil and next(movement.joints) ~= nil then
		return 7
	end
	for _, release in releases or {} do
		if release.kind == "Attach" then
			return 6
		end
	end
	if movement == nil then
		return Sidecar.BASE_FORMAT
	end
	local format = 3
	for _, key in movement.keys do
		if key.interp == "Bezier" or key.handles ~= nil then
			return 5
		end
		local eased = key.interp ~= nil or key.easing ~= nil or key.params ~= nil
		if key.transition ~= nil or (key.kind == "Walk" and eased) then
			format = 4
		end
	end
	return format
end

function Sidecar.formatOf(
	movement: Movement?,
	releases: { Release }?,
	sounds: { Types.SoundTrack }?,
	props: { [string]: Types.PropTarget }?,
	pivots: { [string]: Pivot }?
): number
	local format = featureFormat(movement, releases, sounds, props, pivots)
	for _, target in props or {} do
		if PropRegistry.needs14(target.className, nil) then
			return math.max(format, 14)
		end
		for property in target.properties do
			if PropRegistry.needs14(target.className, property) then
				return math.max(format, 14)
			end
		end
	end
	return format
end

function Sidecar.policies(sidecar: Sidecar): Policies
	return {
		interrupt = sidecar.interrupt or "Revert",
		spaceMismatch = sidecar.spaceMismatch or "Adopt",
		spaceAdoptTime = sidecar.spaceAdoptTime or Schema.DEFAULT_ADOPT_TIME,
	}
end

local function scaledKey<K>(key: K, factor: number): K
	local out = table.clone(key :: any)
	local value = out.v
	if type(value) == "number" then
		out.v = value * factor
	elseif type(value) == "table" then
		out.v = { value[1] * factor, value[2] * factor, value[3] * factor }
	end
	if out.handleL ~= nil then
		out.handleL = { out.handleL[1], out.handleL[2] * factor }
	end
	if out.handleR ~= nil then
		out.handleR = { out.handleR[1], out.handleR[2] * factor }
	end
	return out :: any
end

local function scaledPositions(
	channels: { [string]: Types.Channel },
	factor: number,
	keeps: ((t: number) -> boolean)?
): { [string]: Types.Channel }
	local out = table.clone(channels)
	for _, name in Pose.POSITION_CHANNELS do
		local channel = channels[name]
		if channel == nil then
			continue
		end
		local keys = table.create(#channel.keys)
		for index, key in channel.keys do
			keys[index] = if keeps ~= nil and keeps(key.t) then key else scaledKey(key, factor)
		end
		local copied = table.clone(channel)
		copied.keys = keys
		out[name] = copied
	end
	return out
end

local function scaledList(list: { number }?, factor: number, count: number): { number }?
	if list == nil then
		return nil
	end
	local out = table.clone(list)
	for index = 1, math.min(count, #out) do
		out[index] *= factor
	end
	return out
end

local function scaledMovementKeys(
	keys: { Types.MovementKey },
	factor: number
): { Types.MovementKey }
	local out = table.create(#keys)
	for index, key in keys do
		local copied = table.clone(key)
		if key.speed ~= nil then
			copied.speed = key.speed * factor
		end
		copied.cframe = scaledList(key.cframe, factor, 3)
		copied.shapeIn = scaledList(key.shapeIn, factor, 3)
		copied.shapeOut = scaledList(key.shapeOut, factor, 3)
		out[index] = copied
	end
	return out
end

function Sidecar.scaledProp(track: Types.PropTrack, factor: number): Types.PropTrack
	local out = table.clone(track)
	out.keys = table.create(#track.keys)
	for index, key in track.keys do
		out.keys[index] = scaledKey(key, factor)
	end
	return out
end

function Sidecar.factorOf(sidecar: Sidecar, rig: any): number
	local made = sidecar.scale
	if made == nil then
		return 1
	end
	local ok, now = pcall(function()
		return rig:GetScale()
	end)
	if not ok or not isFinite(now) or now <= 0 then
		return 1
	end
	local factor = now / made
	return if math.abs(factor - 1) <= SAME then 1 else factor
end

local scaledCache: { [Sidecar]: { [number]: Sidecar } } = setmetatable({} :: any, { __mode = "k" })

function Sidecar.scaled(sidecar: Sidecar, factor: number): Sidecar
	if factor == 1 then
		return sidecar
	end
	local byFactor = scaledCache[sidecar]
	if byFactor == nil then
		byFactor = {}
		scaledCache[sidecar] = byFactor
	end
	local known = byFactor[factor]
	if known ~= nil then
		return known
	end
	local out = table.clone(sidecar)
	out.scale = (sidecar.scale or 1) * factor

	local joints: { [string]: Types.JointTrack } = {}
	for address, track in sidecar.joints do
		local starting = if sidecar.startingSpaces ~= nil
			then sidecar.startingSpaces[address]
			else nil
		local copied = table.clone(track)
		copied.channels = scaledPositions(track.channels, factor, function(t: number): boolean
			local target = SpaceSolve.stateAt(track.spaces :: any, starting :: any, t).target
			return target.kind == "World" or target.slot ~= nil
		end)
		joints[address] = copied
	end
	out.joints = joints

	if sidecar.pivots ~= nil then
		local pivots: { [string]: Pivot } = {}
		for address, pivot in sidecar.pivots do
			if Path.inWorkspace(pivot.path) ~= nil then
				pivots[address] = pivot
				continue
			end
			local copied = table.clone(pivot)
			copied.channels = scaledPositions(pivot.channels, factor)
			pivots[address] = copied
		end
		out.pivots = pivots
	end

	local movement = sidecar.movement
	if movement ~= nil then
		local branches: { [string]: Types.MovementJoint }? = nil
		for address, branch in movement.joints or {} do
			branches = branches or {}
			(branches :: any)[address] = { keys = scaledMovementKeys(branch.keys, factor) }
		end
		out.movement = { keys = scaledMovementKeys(movement.keys, factor), joints = branches }
	end

	if sidecar.releases ~= nil then
		local releases: { Release } = {}
		for index, release in sidecar.releases do
			local copied = table.clone(release)
			local velocity = release.velocity
			if velocity ~= nil then
				copied.velocity = {
					linear = scaledList(velocity.linear, factor, 3) :: { number },
					angular = velocity.angular,
				}
			end
			local push = (release :: any).push
			if push ~= nil then
				(copied :: any).push = scaledList(push, factor, 3)
			end
			releases[index] = copied
		end
		out.releases = releases
	end

	if sidecar.props ~= nil then
		local props: { [string]: Types.PropTarget } = {}
		for path, target in sidecar.props do
			local lengths = PropRegistry.LENGTHS[target.className]
			if lengths == nil or Path.inWorkspace(path) ~= nil then
				props[path] = target
				continue
			end
			local copied = table.clone(target)
			copied.properties = table.clone(target.properties)
			for property, track in target.properties do
				if lengths[property] then
					copied.properties[property] = Sidecar.scaledProp(track, factor)
				end
			end
			props[path] = copied
		end
		out.props = props
	end

	byFactor[factor] = out
	return out
end

function Sidecar.newerMessage(format: number): string
	return `it was exported by a newer Apex Animator (format {format}) than this ApexEngine can read (format {Sidecar.FORMAT} at most) - update ApexEngine in this place with Apex Animator's Update Engine`
end

local function checkScene(value: any): string?
	local damaged =
		"the part saying which scene and slot it plays is damaged - export the scene again from Apex Animator"
	if type(value) ~= "table" or type(value.name) ~= "string" then
		return damaged
	end
	if type(value.slot) ~= "string" or value.slot == "" or type(value.slots) ~= "table" then
		return damaged
	end
	local names: { [string]: boolean } = {}
	for _, name in value.slots do
		if type(name) ~= "string" or name == "" or names[name] then
			return damaged
		end
		names[name] = true
	end
	if not names[value.slot] or type(value.assets) ~= "table" then
		return damaged
	end
	for name, id in value.assets do
		if not names[name] or not isWhole(id) or id <= 0 then
			return damaged
		end
	end
	if value.temps ~= nil then
		if type(value.temps) ~= "table" then
			return damaged
		end
		for name, id in value.temps do
			if not names[name] or type(id) ~= "string" or id == "" then
				return damaged
			end
		end
	end
	return nil
end

function Sidecar.checkHeader(value: any): string?
	if type(value) ~= "table" then
		return `it does not hold an Apex animation (it is a {type(value)}, not a table)`
	end
	local format = value.format
	if not isWhole(format) or format < 1 then
		return "it is damaged: it has no format number - export it again from Apex Animator"
	end
	if format > Sidecar.FORMAT then
		return Sidecar.newerMessage(format)
	end
	if value.kind == "Scene" then
		return "it is a whole scene, not an animation for one rig - play it with ApexEngine.LoadScene"
	end
	local assetId = value.assetId
	if assetId ~= nil and (not isWhole(assetId) or assetId <= 0) then
		return "its asset id is damaged (it should be the whole number of a published animation)"
	end
	if type(value.hash) ~= "string" or value.hash == "" then
		return "it has no bake fingerprint (hash) - export it again from Apex Animator"
	end
	if type(value.joints) ~= "table" then
		return "its joints are damaged - export it again from Apex Animator"
	end
	if value.scale ~= nil and not (isFinite(value.scale) and value.scale > 0) then
		return "its rig scale is damaged - export it again from Apex Animator"
	end
	if value.scene ~= nil then
		return checkScene(value.scene)
	end
	return nil
end

function Sidecar.documentOf(value: any): Types.RigDocument
	return {
		kind = "Rig",
		version = Schema.VERSION,
		name = value.name,
		length = value.length,
		fps = value.fps,
		loop = value.loop,
		priority = Schema.DEFAULT_PRIORITY,
		joints = value.joints,
		startingSpaces = value.startingSpaces,
		states = value.states,
		props = value.props,
		sounds = value.sounds,
		markers = value.markers,
		presets = value.presets,
		releases = value.releases,
		movement = value.movement,
		interrupt = value.interrupt,
		spaceMismatch = value.spaceMismatch,
		spaceAdoptTime = value.spaceAdoptTime,
	}
end

function Sidecar.validate(value: any): (boolean, string?)
	local problem = Sidecar.checkHeader(value)
	if problem ~= nil then
		return false, problem
	end
	local scene: { slots: { [string]: boolean }, slot: string }? = nil
	if value.scene ~= nil then
		local names: { [string]: boolean } = {}
		for _, name in value.scene.slots do
			names[name] = true
		end
		scene = { slots = names, slot = value.scene.slot }
	end
	local valid, invalid = Schema.validate(Sidecar.documentOf(value), scene)
	if not valid then
		return false, invalid
	end
	if value.pivots ~= nil then
		if type(value.pivots) ~= "table" then
			return false, "its moved parts are damaged - export it again from Apex Animator"
		end
		local tracks: { [string]: any } = {}
		for address, pivot in value.pivots do
			if type(pivot) ~= "table" or type(pivot.path) ~= "string" or pivot.path == "" then
				return false,
					`the moved part {tostring(address)} is damaged - export it again from Apex Animator`
			end
			tracks[address] = { rotationMode = pivot.rotationMode, channels = pivot.channels }
		end
		local view = Sidecar.documentOf({
			name = value.name,
			length = value.length,
			fps = value.fps,
			loop = value.loop,
			joints = tracks,
			presets = value.presets,
		})
		valid, invalid = Schema.validate(view, scene)
		if not valid then
			return false, invalid
		end
	end
	for _, release in value.releases or {} do
		if release.velocity ~= nil and not ReleaseMath.isData(release.velocity) then
			return false,
				`the speed of the release of {release.joint} at {string.format("%.2f", release.t)} s is damaged - export it again from Apex Animator`
		end
	end
	return true, nil
end

return Sidecar
