--!strict

local Value = {}

local function numLit(n: number): string
	if n ~= n then
		return "0/0"
	elseif n == math.huge then
		return "math.huge"
	elseif n == -math.huge then
		return "-math.huge"
	elseif n % 1 == 0 and math.abs(n) < 1e15 then
		return string.format("%d", n)
	end
	local long = string.format("%.14g", n)
	if tonumber(long) ~= n then
		return string.format("%.17g", n)
	end
	local short = string.format("%.7g", n)
	if tonumber(short) == n then
		return short
	end
	local middle = string.format("%.10g", n)
	if tonumber(middle) == n then
		return middle
	end
	return long
end

Value.numLit = numLit

local function list(parts: { string }): string
	return table.concat(parts, ", ")
end

type Codec = {
	encode: (any) -> any,
	decode: (any) -> any,
	toLuau: (any) -> string,
}

local CODECS: { [string]: Codec } = {}

CODECS.number = {
	encode = function(v)
		return v
	end,
	decode = function(v)
		return tonumber(v) or 0
	end,
	toLuau = function(v)
		return numLit(v)
	end,
}

CODECS.boolean = {
	encode = function(v)
		return v
	end,
	decode = function(v)
		return v == true
	end,
	toLuau = function(v)
		return tostring(v == true)
	end,
}

CODECS.string = {
	encode = function(v)
		return v
	end,
	decode = function(v)
		return tostring(v)
	end,
	toLuau = function(v)
		return string.format("%q", tostring(v))
	end,
}

CODECS.Vector2 = {
	encode = function(v: Vector2)
		return { v.X, v.Y }
	end,
	decode = function(v)
		return Vector2.new(v[1], v[2])
	end,
	toLuau = function(v: Vector2)
		return `Vector2.new({list({ numLit(v.X), numLit(v.Y) })})`
	end,
}

CODECS.Vector3 = {
	encode = function(v: Vector3)
		return { v.X, v.Y, v.Z }
	end,
	decode = function(v)
		return Vector3.new(v[1], v[2], v[3])
	end,
	toLuau = function(v: Vector3)
		return `Vector3.new({list({ numLit(v.X), numLit(v.Y), numLit(v.Z) })})`
	end,
}

CODECS.CFrame = {
	encode = function(v: CFrame)
		return { v:GetComponents() }
	end,
	decode = function(v)
		return CFrame.new(table.unpack(v, 1, 12))
	end,
	toLuau = function(v: CFrame)
		local parts = {}
		for _, component in { v:GetComponents() } do
			table.insert(parts, numLit(component))
		end
		return `CFrame.new({list(parts)})`
	end,
}

CODECS.Color3 = {
	encode = function(v: Color3)
		return { v.R, v.G, v.B }
	end,
	decode = function(v)
		return Color3.new(v[1], v[2], v[3])
	end,
	toLuau = function(v: Color3)
		return `Color3.new({list({ numLit(v.R), numLit(v.G), numLit(v.B) })})`
	end,
}

CODECS.NumberRange = {
	encode = function(v: NumberRange)
		return { v.Min, v.Max }
	end,
	decode = function(v)
		return NumberRange.new(v[1], v[2])
	end,
	toLuau = function(v: NumberRange)
		return `NumberRange.new({list({ numLit(v.Min), numLit(v.Max) })})`
	end,
}

CODECS.UDim = {
	encode = function(v: UDim)
		return { v.Scale, v.Offset }
	end,
	decode = function(v)
		return UDim.new(v[1], v[2])
	end,
	toLuau = function(v: UDim)
		return `UDim.new({list({ numLit(v.Scale), numLit(v.Offset) })})`
	end,
}

CODECS.UDim2 = {
	encode = function(v: UDim2)
		return { v.X.Scale, v.X.Offset, v.Y.Scale, v.Y.Offset }
	end,
	decode = function(v)
		return UDim2.new(v[1], v[2], v[3], v[4])
	end,
	toLuau = function(v: UDim2)
		return `UDim2.new({list({
			numLit(v.X.Scale),
			numLit(v.X.Offset),
			numLit(v.Y.Scale),
			numLit(v.Y.Offset),
		})})`
	end,
}

CODECS.NumberSequence = {
	encode = function(v: NumberSequence)
		local out = {}
		for _, kp in v.Keypoints do
			table.insert(out, { kp.Time, kp.Value, kp.Envelope })
		end
		return out
	end,
	decode = function(v)
		local kps = {}
		for _, kp in v do
			table.insert(kps, NumberSequenceKeypoint.new(kp[1], kp[2], kp[3] or 0))
		end
		return NumberSequence.new(kps)
	end,
	toLuau = function(v: NumberSequence)
		local parts = {}
		for _, kp in v.Keypoints do
			local args = list({ numLit(kp.Time), numLit(kp.Value), numLit(kp.Envelope) })
			table.insert(parts, `NumberSequenceKeypoint.new({args})`)
		end
		return "NumberSequence.new({ " .. list(parts) .. " })"
	end,
}

CODECS.ColorSequence = {
	encode = function(v: ColorSequence)
		local out = {}
		for _, kp in v.Keypoints do
			table.insert(out, { kp.Time, kp.Value.R, kp.Value.G, kp.Value.B })
		end
		return out
	end,
	decode = function(v)
		local kps = {}
		for _, kp in v do
			table.insert(kps, ColorSequenceKeypoint.new(kp[1], Color3.new(kp[2], kp[3], kp[4])))
		end
		return ColorSequence.new(kps)
	end,
	toLuau = function(v: ColorSequence)
		local parts = {}
		for _, kp in v.Keypoints do
			local rgb = list({ numLit(kp.Value.R), numLit(kp.Value.G), numLit(kp.Value.B) })
			table.insert(parts, `ColorSequenceKeypoint.new({numLit(kp.Time)}, Color3.new({rgb}))`)
		end
		return "ColorSequence.new({ " .. list(parts) .. " })"
	end,
}

local function enumName(enum: Enum): string
	return (string.gsub(tostring(enum), "^Enum%.", ""))
end

CODECS.EnumItem = {
	encode = function(v: EnumItem)
		return { enumName(v.EnumType), v.Name }
	end,
	decode = function(v)
		local enum = (Enum :: any)[v[1]]
		return if enum then enum[v[2]] else nil
	end,
	toLuau = function(v: EnumItem)
		return `Enum.{enumName(v.EnumType)}.{v.Name}`
	end,
}

function Value.supports(typeName: string): boolean
	return CODECS[typeName] ~= nil
end

function Value.encode(typeName: string, v: any): any
	local codec = CODECS[typeName]
	return if codec then codec.encode(v) else v
end

function Value.decode(typeName: string, v: any): any
	local codec = CODECS[typeName]
	return if codec then codec.decode(v) else v
end

function Value.toLuau(typeName: string, v: any): string
	local codec = CODECS[typeName]
	if codec == nil then
		error(`Value.toLuau: no codec for type '{typeName}'`)
	end
	return codec.toLuau(v)
end

return Value
