--!strict

local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Types = require(script.Parent.Parent.Core.Types)
local RigSolve = require(script.Parent.Parent.Shared.RigSolve)

local DocumentSource = {}

DocumentSource.HASH = "preview"

DocumentSource.ASSET_ID = 1

DocumentSource.UNBUILT = "What the engine plays could not be built from this animation."

export type State = {
	doc: Types.RigDocument,
	rig: RigSolve.Rig?,
}

export type Options = {
	state: () -> State,
	assetId: number?,
	hash: string?,
}

export type Source = {
	options: Options,
	doc: Types.RigDocument?,
	revision: number?,
	rig: RigSolve.Rig?,
	view: Sidecar.Sidecar?,
	problem: string?,
	detail: string?,
	serial: number,
	dirty: boolean,
}

function DocumentSource.new(options: Options): Source
	return {
		options = options,
		doc = nil,
		revision = nil,
		rig = nil,
		view = nil,
		problem = nil,
		detail = nil,
		serial = 0,
		dirty = true,
	}
end

function DocumentSource.valueAt(doc: Types.RigDocument, rig: RigSolve.Rig?): Sidecar.ValueAt
	if rig == nil then
		return Sidecar.layerValues(doc)
	end
	local solved = rig :: RigSolve.Rig
	return function(address: string, t: number): CFrame
		return RigSolve.value(doc :: any, address, t, solved)
	end
end

function DocumentSource.stale(source: Source): boolean
	if source.dirty then
		return true
	end
	local state = source.options.state()
	local doc = state.doc
	return doc ~= source.doc or (doc.revision or 0) ~= source.revision or state.rig ~= source.rig
end

function DocumentSource.invalidate(source: Source)
	source.dirty = true
end

local function build(source: Source, state: State): (Sidecar.Sidecar?, string?, string?)
	local doc = state.doc
	local options = source.options
	local published = doc.publish ~= nil and doc.publish.assetId ~= nil
	local ok, built = pcall(Sidecar.build, doc, { hash = options.hash or DocumentSource.HASH }, {
		assetId = if published then nil else options.assetId or DocumentSource.ASSET_ID,
		valueAt = DocumentSource.valueAt(doc, state.rig),
	})
	if ok then
		return built, nil, nil
	end
	return nil, DocumentSource.UNBUILT, tostring(built)
end

function DocumentSource.sidecar(source: Source): (Sidecar.Sidecar?, string?, string?)
	if not DocumentSource.stale(source) then
		return source.view, source.problem, source.detail
	end
	local state = source.options.state()
	local view, problem, detail = build(source, state)
	source.doc = state.doc
	source.revision = state.doc.revision or 0
	source.rig = state.rig
	source.view = view
	source.problem = problem
	source.detail = detail
	source.serial += 1
	source.dirty = false
	return view, problem, detail
end

function DocumentSource.serial(source: Source): number
	return source.serial
end

return DocumentSource
