--!strict

local Schema = require(script.Parent.Parent.Core.Schema)

local HeadSwap = {}

HeadSwap.FOLDER = Schema.HEADS_FOLDER

HeadSwap.OWN = Schema.OWN_HEAD_FOLDER

HeadSwap.PROPERTY = Schema.HEAD_PROPERTY

HeadSwap.LOOKS = table.freeze({ "SurfaceAppearance" })

type Worn = {
	shown: string,
	keep: any,
	own: any?,
	size: Vector3,
	texture: string,
	put: { any },
}

local MESH = "OwnMesh"
local SHOWN = "Shown"
local SIZE = "Size"
local TEXTURE = "TextureID"
local DEPTH = 3

local worn: { [any]: Worn } = setmetatable({}, { __mode = "k" }) :: any

function HeadSwap.applyMesh(part: any, source: any)
	part:ApplyMesh(source)
end

function HeadSwap.newInstance(className: string): any
	return Instance.new(className)
end

local function isLook(instance: any): boolean
	for _, class in HeadSwap.LOOKS do
		if instance:IsA(class) then
			return true
		end
	end
	return false
end

function HeadSwap.isOwn(instance: any): boolean
	local node = instance
	for _ = 1, DEPTH do
		if node == nil then
			return false
		end
		if node.Name == HeadSwap.OWN and node:IsA("Folder") then
			return true
		end
		node = node.Parent
	end
	return false
end

local function recall(head: any): Worn?
	local ok, state = pcall(function()
		local keep = head:FindFirstChild(HeadSwap.OWN)
		if keep == nil or not keep:IsA("Folder") then
			return nil
		end
		local own = keep:FindFirstChild(MESH)
		if own ~= nil and not own:IsA("MeshPart") then
			own = nil
		end
		local shown = keep:GetAttribute(SHOWN)
		local size = keep:GetAttribute(SIZE)
		local texture = keep:GetAttribute(TEXTURE)
		local put = {}
		for _, child in head:GetChildren() do
			if isLook(child) and not child.Archivable then
				table.insert(put, child)
			end
		end
		local base = own or head
		return {
			shown = if type(shown) == "string" then shown else "",
			keep = keep,
			own = own,
			size = if typeof(size) == "Vector3" then size else base.Size,
			texture = if type(texture) == "string" then texture else base.TextureID,
			put = put,
		}
	end)
	return if ok then state else nil
end

local function stateOf(head: any): Worn?
	return worn[head] or recall(head)
end

function HeadSwap.shown(head: any): string
	local state = stateOf(head)
	return if state ~= nil then state.shown else ""
end

function HeadSwap.find(head: any, name: string): any?
	local ok, found = pcall(function()
		local folder = head:FindFirstChild(HeadSwap.FOLDER)
		local item = if folder ~= nil then folder:FindFirstChild(name) else nil
		return if item ~= nil and item:IsA("MeshPart") then item else nil
	end)
	return if ok then found else nil
end

local function unpark(head: any, keep: any)
	local back = pcall(function()
		for _, child in keep:GetChildren() do
			if isLook(child) then
				child.Parent = head
			end
		end
	end)
	if back then
		pcall(function()
			keep:Destroy()
		end)
	else
		pcall(function()
			keep:SetAttribute(SHOWN, "")
		end)
	end
end

local function park(head: any): Worn?
	local keep: any = nil
	local ok, state = pcall(function()
		if not head:IsA("MeshPart") then
			return nil
		end
		local own = head:Clone()
		if own == nil then
			return nil
		end
		own:ClearAllChildren()
		for name in own:GetAttributes() do
			own:SetAttribute(name, nil)
		end
		for _, tag in own:GetTags() do
			own:RemoveTag(tag)
		end
		own.Name = MESH
		own.Transparency = 1
		own.CanCollide = false
		own.CanQuery = false
		own.CanTouch = false
		own.CastShadow = false
		own.Massless = true
		own.Anchored = false
		own.Locked = true
		own.CFrame = head.CFrame
		local weld = HeadSwap.newInstance("WeldConstraint")
		weld.Part0 = own
		weld.Part1 = head
		weld.Parent = own
		keep = HeadSwap.newInstance("Folder")
		keep.Name = HeadSwap.OWN
		keep:SetAttribute(SIZE, head.Size)
		keep:SetAttribute(TEXTURE, head.TextureID)
		own.Parent = keep
		keep.Parent = head
		for _, child in head:GetChildren() do
			if isLook(child) then
				child.Parent = keep
			end
		end
		return {
			shown = "",
			keep = keep,
			own = own,
			size = head.Size,
			texture = head.TextureID,
			put = {},
		}
	end)
	if ok and state ~= nil then
		return state
	end
	if keep ~= nil then
		unpark(head, keep)
	end
	return nil
end

local function wear(head: any, state: Worn, source: any)
	for _, copy in state.put do
		pcall(function()
			copy:Destroy()
		end)
	end
	table.clear(state.put)
	for _, child in source:GetChildren() do
		if isLook(child) then
			local copy = child:Clone()
			if copy ~= nil then
				copy.Archivable = false
				copy.Parent = head
				table.insert(state.put, copy)
			end
		end
	end
end

local function restore(head: any, state: Worn): boolean
	local ok = pcall(function()
		if state.own ~= nil then
			HeadSwap.applyMesh(head, state.own)
		end
		head.Size = state.size
		head.TextureID = state.texture
	end)
	if not ok then
		return false
	end
	for _, copy in state.put do
		pcall(function()
			copy:Destroy()
		end)
	end
	table.clear(state.put)
	unpark(head, state.keep)
	worn[head] = nil
	return true
end

function HeadSwap.show(head: any, name: string): boolean
	local state = stateOf(head)
	if name == "" then
		return if state ~= nil then restore(head, state) else true
	end
	if state ~= nil and state.shown == name then
		return true
	end
	local source = HeadSwap.find(head, name)
	if source == nil then
		return false
	end
	if state == nil then
		state = park(head)
		if state == nil then
			return false
		end
	end
	local now = state :: Worn
	worn[head] = now
	local ok = pcall(function()
		HeadSwap.applyMesh(head, source)
		head.Size = source.Size
		head.TextureID = source.TextureID
		wear(head, now, source)
		now.keep:SetAttribute(SHOWN, name)
	end)
	if ok then
		now.shown = name
	elseif now.shown == "" then
		restore(head, now)
	end
	return ok
end

function HeadSwap.recover(head: any): boolean
	if worn[head] ~= nil then
		return true
	end
	local state = recall(head)
	return if state ~= nil then restore(head, state) else true
end

return HeadSwap
