--!strict

local AnchorMath = require(script.Parent.Parent.Shared.AnchorMath)
local Shared = require(script.Parent.Parent.Shared.Movement)
local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local JointGraph = require(script.Parent.Parent.Core.JointGraph)
local Sidecar = require(script.Parent.Parent.Core.Sidecar)

local Movement = {}

Movement.NAME = "movement"

local PLACEMENT = "movement.placement"

local STILL = table.freeze({ keys = table.freeze({}) }) :: any

Movement.GLIDE_DISABLED_STATES = table.freeze({ "FallingDown", "Ragdoll", "Freefall" })

export type Parts = {
	model: any,
	humanoid: any?,
	rootPart: any,
}

export type Command = {
	kind: "Stand" | "Walk" | "Place",
	speed: number?,
	heading: Vector3?,
	turned: CFrame?,
	placement: CFrame?,
	glide: boolean?,
	onto: number?,
	weight: number?,
}

export type Snapshot = {
	walkSpeed: number?,
	autoRotate: boolean?,
	states: { [string]: boolean },
}

export type Placement = {
	start: CFrame,
	blend: number?,
}

export type Config = {
	isOwner: ((rootPart: any) -> boolean)?,
	warn: ((message: string) -> ())?,
}

type Held = {
	joint: any,
	rest: CFrame,
	keys: { any },
	origin: CFrame?,
	clean: CFrame?,
	wrote: CFrame?,
}

type Play = {
	track: Sidecar.Movement,
	branches: { Held }?,
	holdLaps: number?,
	parts: Parts,
	origin: CFrame?,
	start: CFrame?,
	laps: number,
	index: number?,
	onto: number?,
	offset: CFrame?,
	placement: Placement?,
	elapsed: number,
	from: CFrame?,
}

type Rig = {
	parts: Parts,
	plays: { [ApexTrack.Live]: boolean },
	snapshot: Snapshot?,
	walking: boolean,
}

function Movement.stretchOf(track: Sidecar.Movement, t: number): number?
	local found: number? = nil
	for index, key in track.keys do
		if key.t > t then
			break
		end
		found = index
	end
	return found
end

function Movement.command(
	track: Sidecar.Movement,
	t: number,
	entered: boolean,
	humanoid: boolean
): Command
	local index = Movement.stretchOf(track, t)
	if index == nil then
		return { kind = "Stand" }
	end
	local keys = track.keys :: { any }
	local key = keys[index]
	local onto, weight = Shared.transitionAt(track :: any, t)
	if onto ~= nil and keys[onto].kind ~= "Walk" then
		local walked = key.kind == "Walk" and humanoid
		return {
			kind = "Place",
			placement = Shared.at(track :: any, t),
			glide = true,
			onto = if walked then onto else nil,
			weight = if walked then weight else nil,
		}
	end
	if key.kind == "Walk" or onto ~= nil then
		if not humanoid then
			return { kind = "Place", placement = Shared.at(track :: any, t) }
		end
		local speed, heading = Shared.walkAt(track :: any, t)
		return {
			kind = "Walk",
			speed = speed,
			heading = heading,
			turned = if speed <= 0
					and key.direction ~= nil
					and onto == nil
				then Shared.at(track :: any, t)
				else nil,
		}
	end
	local following = keys[index + 1]
	local glide = following ~= nil and following.kind ~= "Walk"
	if glide or entered then
		return { kind = "Place", placement = Shared.at(track :: any, t), glide = glide }
	end
	return { kind = "Stand" }
end

function Movement.rootPartOf(model: any): any?
	local ok, part = pcall(function()
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		if humanoid ~= nil and humanoid.RootPart ~= nil then
			return humanoid.RootPart
		end
		local named = model:FindFirstChild("HumanoidRootPart")
		if named ~= nil then
			return named
		end
		return model.PrimaryPart
	end)
	return if ok then part else nil
end

local function nameOf(model: any): string
	local ok, name = pcall(function()
		return model.Name
	end)
	return if ok then tostring(name) else "a rig"
end

function Movement.partsOf(model: any): (Parts?, string?)
	local rootPart = Movement.rootPartOf(model)
	if rootPart == nil then
		return nil,
			`ApexEngine: {nameOf(model)} has no HumanoidRootPart (or PrimaryPart), so its movement cannot move it. The animation plays on the spot.`
	end
	local humanoid = nil
	pcall(function()
		humanoid = model:FindFirstChildOfClass("Humanoid")
	end)
	return { model = model, humanoid = humanoid, rootPart = rootPart }, nil
end

function Movement.place(live: ApexTrack.Live, placement: Placement)
	live.data[PLACEMENT] = placement
end

function Movement.placementOf(live: ApexTrack.Live): Placement?
	return live.data[PLACEMENT]
end

function Movement.isOwner(rootPart: any): boolean
	local ok, owns = pcall(function(): boolean
		local runService = game:GetService("RunService")
		if runService:IsServer() then
			local assembly = rootPart.AssemblyRootPart or rootPart
			return assembly.Anchored or rootPart:GetNetworkOwner() == nil
		end
		return rootPart.ReceiveAge == 0
	end)
	return ok and owns == true
end

local function branchesOf(parts: Parts, track: Sidecar.Movement?): { Held }?
	local ok, graph = pcall(JointGraph.build, parts.model)
	if not ok or graph == nil or graph.rootPart ~= parts.rootPart then
		return nil
	end
	local joints = JointGraph.branchesOf(graph)
	if #joints < 2 then
		return nil
	end
	local out: { Held } = {}
	for index = 2, #joints do
		local joint = joints[index]
		table.insert(out, {
			joint = joint,
			rest = joint:getRest().parentOffset,
			keys = Shared.keysOf(track :: any, joint.address),
		})
	end
	return out
end

local function stillOn(joint: any, rootPart: any): boolean
	local ok, on = pcall(function(): boolean
		if joint.kind == "Motor6D" then
			return joint.instance.Part0 == rootPart
		elseif joint.kind == "Bone" then
			return joint.instance.Parent == rootPart
		end
		return true
	end)
	return ok and on
end

local function same(a: CFrame, b: CFrame): boolean
	local x = { a:GetComponents() }
	local y = { b:GetComponents() }
	for index = 1, 12 do
		if math.abs(x[index] - y[index]) > 1e-5 then
			return false
		end
	end
	return true
end

local function letGo(branches: { Held })
	for _, held in branches do
		local wrote, clean = held.wrote, held.clean
		held.wrote, held.clean, held.origin = nil, nil, nil
		if wrote ~= nil and clean ~= nil then
			pcall(function()
				if same(held.joint:getTransform(), wrote) then
					held.joint:setTransform(clean)
				end
			end)
		end
	end
end

function Movement.carryOf(live: ApexTrack.Live): CFrame?
	local play: Play? = live.data[Movement.NAME]
	if play == nil or play.start == nil then
		return nil
	end
	return play.parts.rootPart.CFrame * (play.start :: CFrame):Inverse()
end

local function stateEnum(name: string): any
	return (Enum.HumanoidStateType :: any)[name]
end

local function remember(rig: Rig, field: "walkSpeed" | "autoRotate")
	local humanoid = rig.parts.humanoid
	if humanoid == nil then
		return
	end
	local snapshot = rig.snapshot or { states = {} }
	rig.snapshot = snapshot
	if (snapshot :: any)[field] ~= nil then
		return
	end
	pcall(function()
		if field == "walkSpeed" then
			snapshot.walkSpeed = humanoid.WalkSpeed
		else
			snapshot.autoRotate = humanoid.AutoRotate
		end
	end)
end

local function holdStates(rig: Rig)
	local humanoid = rig.parts.humanoid
	if humanoid == nil then
		return
	end
	local snapshot = rig.snapshot or { states = {} }
	rig.snapshot = snapshot
	for _, name in Movement.GLIDE_DISABLED_STATES do
		if snapshot.states[name] == nil then
			pcall(function()
				snapshot.states[name] = humanoid:GetStateEnabled(stateEnum(name))
				humanoid:SetStateEnabled(stateEnum(name), false)
			end)
		end
	end
end

function Movement.restore(humanoid: any, snapshot: Snapshot)
	if humanoid == nil then
		return
	end
	if snapshot.walkSpeed ~= nil then
		pcall(function()
			humanoid.WalkSpeed = snapshot.walkSpeed
		end)
	end
	if snapshot.autoRotate ~= nil then
		pcall(function()
			humanoid.AutoRotate = snapshot.autoRotate
		end)
	end
	for name, enabled in snapshot.states do
		pcall(function()
			humanoid:SetStateEnabled(stateEnum(name), enabled)
		end)
	end
end

local function move(humanoid: any, direction: Vector3)
	pcall(function()
		humanoid:Move(direction, false)
	end)
end

function Movement.new(config: Config?): Frame.Extension
	local options: Config = config or {}
	local isOwner = options.isOwner or Movement.isOwner
	local warnFn = options.warn or warn
	local warned: { [string]: boolean } = {}
	local rigs: { [any]: Rig } = setmetatable({}, { __mode = "k" }) :: any

	local function warnOnce(message: string)
		if not warned[message] then
			warned[message] = true
			warnFn(message)
		end
	end

	local function release(rig: Rig)
		local humanoid = rig.parts.humanoid
		if rig.walking and humanoid ~= nil then
			move(humanoid, Vector3.zero)
		end
		rig.walking = false
		local snapshot = rig.snapshot
		rig.snapshot = nil
		if snapshot ~= nil then
			Movement.restore(humanoid, snapshot)
		end
	end

	local function modelOf(live: ApexTrack.Live): any
		return live.rig or live.animator
	end

	local function began(live: ApexTrack.Live)
		live.data[Movement.NAME] = nil
		local placement: Placement? = live.data[PLACEMENT]
		live.data[PLACEMENT] = nil
		local track = live.sidecar.movement
		local keyed = Shared.keyed(track :: any)
		if not keyed and placement == nil then
			return
		end
		local parts, problem = Movement.partsOf(modelOf(live))
		if parts == nil then
			warnOnce(problem :: string)
			return
		end
		local start: CFrame? = nil
		if keyed and placement ~= nil then
			start = placement.start
		elseif keyed then
			local here: CFrame = parts.rootPart.CFrame
			start = if live.late then here * Shared.at(track :: any, live.time):Inverse() else here
		end
		local play: Play = {
			track = if keyed then track :: Sidecar.Movement else STILL,
			parts = parts,
			origin = nil,
			start = start,
			laps = live.laps,
			index = nil,
			placement = placement,
			elapsed = 0,
			from = nil,
			branches = branchesOf(parts, track),
		}
		live.data[Movement.NAME] = play
	end

	local holding: { [any]: { Held } } = setmetatable({}, { __mode = "k" }) :: any

	local function stopHolding(model: any)
		local branches = holding[model]
		if branches ~= nil then
			holding[model] = nil
			letGo(branches)
		end
	end

	local function hold(model: any, lead: ApexTrack.Live?)
		local play: Play? = if lead ~= nil then lead.data[Movement.NAME] else nil
		local branches = if play ~= nil then play.branches else nil
		if holding[model] ~= branches then
			stopHolding(model)
		end
		if lead == nil or play == nil or branches == nil or play.start == nil then
			return
		end
		holding[model] = branches
		local live = lead :: ApexTrack.Live
		local rootPart = play.parts.rootPart
		local start = play.start :: CFrame
		local lapped = play.holdLaps ~= nil and play.holdLaps ~= live.laps
		play.holdLaps = live.laps
		local t = live.time
		local root: CFrame = rootPart.CFrame
		for _, held in branches do
			local joint = held.joint
			if not stillOn(joint, rootPart) then
				continue
			end
			local own = { keys = held.keys } :: any
			if held.origin == nil then
				held.origin = start
			elseif lapped then
				held.origin = (held.origin :: CFrame) * Shared.at(own, live.sidecar.length)
			end
			local placement = if play.placement ~= nil
				then Shared.at(play.track :: any, t):Inverse() * Shared.at(own, t)
				else root:Inverse() * (held.origin :: CFrame) * Shared.at(own, t)
			pcall(function()
				local now: CFrame = joint:getTransform()
				local wrote = held.wrote
				local base = if wrote ~= nil and same(now, wrote) then held.clean :: CFrame else now
				joint:setTransform(Shared.fold(base, held.rest, placement))
				held.clean, held.wrote = base, joint:getTransform()
			end)
		end
	end

	local function ended(live: ApexTrack.Live)
		local play: Play? = live.data[Movement.NAME]
		live.data[Movement.NAME] = nil
		local model = modelOf(live)
		if play ~= nil and play.branches ~= nil and holding[model] == play.branches then
			stopHolding(model)
		end
		local rig = rigs[model]
		if rig == nil then
			return
		end
		rig.plays[live] = nil
		if next(rig.plays) == nil then
			release(rig)
			rigs[model] = nil
		end
	end

	local function released(frameRig: Frame.Rig)
		stopHolding(frameRig.model)
		local rig = rigs[frameRig.model]
		if rig ~= nil then
			release(rig)
			rigs[frameRig.model] = nil
		end
	end

	local function stepPlaced(record: Rig, live: ApexTrack.Live, play: Play, dt: number)
		local placement = play.placement :: Placement
		local rootPart = play.parts.rootPart
		local humanoid = play.parts.humanoid
		if play.origin == nil then
			play.origin = placement.start
			play.from = rootPart.CFrame
		elseif live.laps ~= play.laps then
			play.origin = (play.origin :: CFrame)
				* Shared.at(play.track :: any, live.sidecar.length)
		end
		play.laps = live.laps
		play.elapsed += dt
		if humanoid ~= nil then
			if record.walking then
				move(humanoid, Vector3.zero)
				record.walking = false
			end
			remember(record, "autoRotate")
			pcall(function()
				humanoid.AutoRotate = false
			end)
			holdStates(record)
		end
		local target = (play.origin :: CFrame) * Shared.at(play.track :: any, live.time)
		rootPart.CFrame =
			AnchorMath.blend(play.from :: CFrame, target, play.elapsed, placement.blend)
		rootPart.AssemblyLinearVelocity = Vector3.zero
		rootPart.AssemblyAngularVelocity = Vector3.zero
	end

	local function drive(frameRig: Frame.Rig, lead: ApexTrack.Live?, dt: number)
		local model = frameRig.model
		local rig = rigs[model]
		if lead == nil then
			if rig ~= nil then
				release(rig)
				rigs[model] = nil
			end
			return
		end
		local live = lead :: ApexTrack.Live
		local play: Play = live.data[Movement.NAME]
		if rig == nil then
			rig = { parts = play.parts, plays = {}, snapshot = nil, walking = false }
			rigs[model] = rig
		end
		local record = rig :: Rig
		record.plays[live] = true
		local rootPart = play.parts.rootPart
		if not isOwner(rootPart) then
			release(record)
			play.origin = nil
			play.index = nil
			if play.placement ~= nil then
				warnOnce(
					`ApexEngine: {nameOf(model)} plays in a scene, but this machine does not own it, so it cannot be placed. Play the scene where the character is simulated: its own player's machine, or the server for a character nobody plays.`
				)
			end
			return
		end
		if play.placement ~= nil then
			stepPlaced(record, live, play, dt)
			return
		end

		local t = live.time
		local here: CFrame = rootPart.CFrame
		if play.origin == nil then
			play.origin = if live.late
				then here * Shared.at(play.track :: any, t):Inverse()
				else here
		elseif live.laps ~= play.laps then
			play.origin = here
			play.index = nil
		end
		play.laps = live.laps
		local origin = play.origin :: CFrame
		local index = Movement.stretchOf(play.track, t)
		local entered = index ~= play.index
		play.index = index

		local humanoid = play.parts.humanoid
		local command = Movement.command(play.track, t, entered, humanoid ~= nil)
		if command.kind == "Walk" and humanoid ~= nil then
			remember(record, "walkSpeed")
			remember(record, "autoRotate")
			pcall(function()
				humanoid.WalkSpeed = command.speed or 0
				humanoid.AutoRotate = true
			end)
			local heading = command.heading
			local speed = command.speed or 0
			if speed > 0 and heading ~= nil then
				move(humanoid, origin:VectorToWorldSpace(heading))
				record.walking = true
			else
				move(humanoid, Vector3.zero)
				record.walking = false
				local turned = command.turned
				if turned ~= nil then
					rootPart.CFrame = CFrame.new(here.Position) * (origin * turned).Rotation
				end
			end
		elseif command.kind == "Place" then
			if humanoid ~= nil and record.walking then
				move(humanoid, Vector3.zero)
				record.walking = false
			end
			if command.glide == true then
				holdStates(record)
			end
			local placement = command.placement :: CFrame
			local onto = command.onto
			if onto == nil then
				play.onto, play.offset = nil, nil
			else
				if play.onto ~= onto then
					play.onto = onto
					play.offset = placement:Inverse() * origin:ToObjectSpace(here)
				end
				placement *= (play.offset :: CFrame):Lerp(CFrame.identity, command.weight or 1)
			end
			rootPart.CFrame = origin * placement
			rootPart.AssemblyLinearVelocity = Vector3.zero
			rootPart.AssemblyAngularVelocity = Vector3.zero
		elseif record.walking and humanoid ~= nil then
			move(humanoid, Vector3.zero)
			record.walking = false
		end
		if command.onto == nil then
			play.onto, play.offset = nil, nil
		end
	end

	local function step(frameRig: Frame.Rig, dt: number)
		local lead: ApexTrack.Live? = nil
		for _, live in frameRig.lives do
			if live.data[Movement.NAME] ~= nil then
				lead = live
			end
		end
		drive(frameRig, lead, dt)
		hold(frameRig.model, lead)
	end

	return {
		name = Movement.NAME,
		stage = "root",
		began = began,
		ended = ended,
		step = step,
		released = released,
	}
end

return Movement
