--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local Movement = require(script.Parent.Movement)
local Props = require(script.Parent.Props)
local Joint = require(script.Parent.Parent.Core.Joint)
local Path = require(script.Parent.Parent.Core.Path)
local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Types = require(script.Parent.Parent.Core.Types)
local Pose = require(script.Parent.Parent.Shared.Pose)

local Pivots = {}

Pivots.NAME = "pivots"

type Rest = {
	rest: CFrame,
	written: CFrame?,
}

type Slot = {
	base: CFrame,
	owners: { Item },
}

type Item = {
	address: string,
	path: string,
	track: Types.JointTrack,
	instance: any,
	rootPart: any,
	outside: boolean,
	known: Rest,
	slot: Slot,
	live: ApexTrack.Live,
	play: Play,
}

type Play = {
	active: boolean,
	items: { Item },
	options: { presets: { [string]: Types.EasingPreset }?, fps: number? },
	carry: CFrame?,
}

local rests: { [any]: Rest } = setmetatable({}, { __mode = "k" }) :: any
local anchors: { [any]: Rest } = setmetatable({}, { __mode = "k" }) :: any
local slots: { [any]: Slot } = setmetatable({}, { __mode = "k" }) :: any

local NEAR = 1e-3

local function near(a: CFrame, b: CFrame): boolean
	local x = { a:GetComponents() }
	local y = { b:GetComponents() }
	for index = 1, 12 do
		if math.abs(x[index] - y[index]) > NEAR then
			return false
		end
	end
	return true
end

local function rootCFrame(rootPart: any): CFrame?
	local ok, cframe = pcall(function()
		return rootPart.CFrame
	end)
	return if ok and typeof(cframe) == "CFrame" then cframe else nil
end

local function put(item: Item, world: CFrame)
	if pcall(Joint.pivotTo, item.instance, world) then
		item.known.written = world
	end
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[Pivots.NAME]
end

local function sortedKeys(map: { [string]: any }): { string }
	local out: { string } = {}
	for key in map do
		table.insert(out, key)
	end
	table.sort(out)
	return out
end

local function worldAt(item: Item, t: number, play: Play): CFrame?
	local pose = Pose.evaluate(item.track, t, play.options :: any)
	if item.outside then
		return item.known.rest * pose
	end
	local root = rootCFrame(item.rootPart)
	if root == nil then
		return nil
	end
	local world = root * item.known.rest * pose
	local carry = play.carry
	return if carry ~= nil then carry:Inverse() * world else world
end

local function claim(
	address: string,
	pivot: Sidecar.Pivot,
	instance: any,
	rootPart: any,
	live: ApexTrack.Live,
	play: Play
