local Sidecar = require(script.Parent.Parent.Core.Sidecar)
local Schema = require(script.Parent.Parent.Core.Schema)

local Registry = {}
Registry.__index = Registry

Registry.ATTRIBUTE = Sidecar.ATTRIBUTE
Registry.TEMP_ATTRIBUTE = Sidecar.TEMP_ATTRIBUTE
Registry.HASH_ATTRIBUTE = Sidecar.HASH_ATTRIBUTE
Registry.IGNORE_ATTRIBUTE = "Apex_Ignore"
Registry.MARKER = Schema.RESERVED_MARKER

export type Item = {
	module: any,
	id: any,
	tempId: any?,
	hash: any?,
	label: string,
}

export type Entry = {
	module: any,
	assetId: number?,
	tempId: string?,
	hash: string?,
	label: string,
}

export type Index = { [number]: Entry }
export type TempIndex = { [string]: Entry }
export type HashIndex = { [string]: Entry }

export type Config = {
	onTrack: (animator: any, track: any, late: boolean) -> (),
	onAnimatorGone: ((animator: any) -> ())?,
	onAnimator: ((animator: any) -> ())?,
	require: ((module: any) -> any)?,
	warn: ((message: string) -> ())?,
	defer: ((fn: () -> ()) -> ())?,
	spawn: ((fn: () -> ()) -> ())?,
	getClip: ((assetId: number) -> any)?,
}

type Loaded = {
	sidecar: Sidecar.Sidecar?,
	problem: string?,
}

type Waiter = {
	animator: any,
	track: any,
	connections: { any },
}

export type Registry = typeof(setmetatable(
	{} :: {
		folder: any?,
		root: any?,
		index: Index,
		tempIndex: TempIndex,
		hashIndex: HashIndex,
		unhashed: { Item },
		hashes: { [number]: string | false },
		needs: { [number]: boolean },
		fetching: { [number]: boolean },
		waiting: { [number]: { Waiter } },
		dirty: boolean,
		loaded: { [any]: Loaded },
		labels: { [any]: string },
		warned: { [string]: boolean },
		animators: { [any]: { any } },
		folderConnections: { any },
		moduleConnections: { [any]: any },
		rootConnections: { any },
		config: Config,
		require: (module: any) -> any,
		warn: (message: string) -> (),
		defer: (fn: () -> ()) -> (),
		spawn: (fn: () -> ()) -> (),
		getClip: (assetId: number) -> any,
	},
	Registry
))

local function wholeId(n: number?): number?
	if n == nil or n ~= n or n == math.huge or n % 1 ~= 0 or n <= 0 then
		return nil
	end
	return n
end

function Registry.normalizeId(value: any): number?
	if type(value) == "number" then
		return wholeId(value)
	elseif type(value) ~= "string" then
		return nil
	end
	local digits = string.match(value, "^%s*(%d+)%s*$")
		or string.match(value, "^%s*rbxassetid://(%d+)")
		or string.match(value, "[?&][iI][dD]=(%d+)")
	if digits == nil then
		return nil
	end
	return wholeId(tonumber(digits))
end

function Registry.tempIdOf(value: any): string?
	if type(value) ~= "string" then
		return nil
	end
	local trimmed = string.match(value, "^%s*(.-)%s*$") :: string
	if trimmed == "" or string.find(trimmed, "%s") ~= nil then
		return nil
	end
	if Registry.normalizeId(trimmed) ~= nil then
		return nil
	end
	return trimmed
end

function Registry.labelOf(folder: any?, module: any): string
	local names: { string } = {}
	local at = module
	local steps = 0
	while at ~= nil and steps < 32 do
		table.insert(names, 1, tostring(at.Name))
		if at == folder then
			break
		end
		at = at.Parent
		steps += 1
		if at ~= nil and at.Parent == nil and at ~= folder then
			break
		end
	end
	return table.concat(names, ".")
end

function Registry.buildIndex(items: { Item }): (Index, { string })
	local sorted = table.clone(items)
	table.sort(sorted, function(a: Item, b: Item): boolean
		return a.label < b.label
	end)
	local index: Index = {}
	local problems: { string } = {}
	for _, item in sorted do
		local id = Registry.normalizeId(item.id)
		if id == nil then
			continue
		end
		local existing = index[id]
		if existing ~= nil then
			table.insert(
				problems,
				`ApexEngine: {existing.label} and {item.label} are both registered for asset {string.format(
					"%d",
					id
				)}; {existing.label} is used. Remove or re-export the other one.`
			)
			continue
		end
		index[id] = { module = item.module, assetId = id, label = item.label }
	end
	return index, problems
end

function Registry.buildTempIndex(items: { Item }): TempIndex
	local sorted = table.clone(items)
	table.sort(sorted, function(a: Item, b: Item): boolean
		return a.label < b.label
	end)
	local index: TempIndex = {}
	for _, item in sorted do
		local id = Registry.tempIdOf(item.tempId)
		if id ~= nil and index[id] == nil then
			index[id] = {
				module = item.module,
				assetId = Registry.normalizeId(item.id),
				tempId = id,
				label = item.label,
			}
		end
	end
	return index
end

function Registry.buildHashIndex(items: { Item }): (HashIndex, { Item })
	local sorted = table.clone(items)
	table.sort(sorted, function(a: Item, b: Item): boolean
		return a.label < b.label
	end)
	local index: HashIndex = {}
	local unhashed: { Item } = {}
	for _, item in sorted do
		local hash = item.hash
		if type(hash) ~= "string" or hash == "" then
			table.insert(unhashed, item)
		elseif index[hash] == nil then
			index[hash] = {
				module = item.module,
				assetId = Registry.normalizeId(item.id),
				tempId = Registry.tempIdOf(item.tempId),
				hash = hash,
				label = item.label,
			}
		end
	end
	return index, unhashed
end

function Registry.clipHash(clip: any): (string | false, boolean)
	local ok, hash, needs = pcall(function(): (string | false, boolean)
		local marker = clip:FindFirstChild(Registry.MARKER)
		if marker == nil or not marker:IsA("MarkerCurve") then
			return false, false
		end
		local first = marker:GetMarkers()[1]
		local value = if first ~= nil then first.Value else nil
		if type(value) ~= "string" or value == "" then
			return false, false
		end
		return value, marker:GetAttribute(Sidecar.ENGINE_ATTRIBUTE) == true
	end)
	if not ok then
		return false, false
	end
	return hash, needs
end

function Registry.rigOf(animator: any): any?
	local at = animator.Parent
	local steps = 0
	while at ~= nil and steps < 32 do
		if at:IsA("WorldRoot") then
			break
		elseif at:IsA("Model") then
			return at
		end
		at = at.Parent
		steps += 1
	end
	local holder = animator.Parent
	return if holder ~= nil then holder.Parent else nil
end

function Registry.ignored(animator: any): boolean
	local rig = Registry.rigOf(animator)
	if rig == nil then
		return false
	end
	local ok, value = pcall(function()
		return rig:GetAttribute(Registry.IGNORE_ATTRIBUTE)
	end)
	return ok and value ~= nil and value ~= false
end

function Registry.trackId(track: any): number?
	local ok, id = pcall(function()
		local animation = track.Animation
		return if animation ~= nil then animation.AnimationId else nil
	end)
	if not ok then
		return nil
	end
	return Registry.normalizeId(id)
end

function Registry.trackTempId(track: any): string?
	local ok, id = pcall(function()
		local animation = track.Animation
		return if animation ~= nil then animation.AnimationId else nil
	end)
	if not ok then
		return nil
	end
	return Registry.tempIdOf(id)
end

local function defaultGetClip(assetId: number): any
	return (game :: any)
		:GetService("AnimationClipProvider")
		:GetAnimationClipAsync(string.format("rbxassetid://%d", assetId))
end

function Registry.new(config: Config): Registry
	local self = setmetatable({
		folder = nil,
		root = nil,
		index = {},
		tempIndex = {},
		hashIndex = {},
		unhashed = {},
		hashes = {},
		needs = {},
		fetching = {},
		waiting = {},
		dirty = false,
		loaded = setmetatable({}, { __mode = "k" }) :: any,
		labels = setmetatable({}, { __mode = "k" }) :: any,
		warned = {},
		animators = {},
		folderConnections = {},
		moduleConnections = {},
		rootConnections = {},
		config = config,
		require = config.require or require,
		warn = config.warn or warn,
		defer = config.defer or function(fn: () -> ())
			task.defer(fn)
		end,
		spawn = config.spawn or function(fn: () -> ())
			task.spawn(fn)
		end,
		getClip = config.getClip or defaultGetClip,
	}, Registry)
	return self :: Registry
end

local function disconnectAll(list: { any })
	for _, connection in list do
		connection:Disconnect()
	end
	table.clear(list)
end

function Registry.warnOnce(self: Registry, key: string, message: string)
	if self.warned[key] then
		return
	end
	self.warned[key] = true
	self.warn(message)
end

function Registry.setFolder(self: Registry, folder: any)
	if self.folder == folder then
		return
	end
	disconnectAll(self.folderConnections)
	for module, connection in self.moduleConnections do
		connection:Disconnect()
		self.moduleConnections[module] = nil
	end
	self.folder = folder
	self.dirty = true
	local function changed()
		self.dirty = true
	end
	table.insert(self.folderConnections, folder.DescendantAdded:Connect(changed))
	table.insert(self.folderConnections, folder.DescendantRemoving:Connect(changed))
end

function Registry.rebuild(self: Registry)
	self.dirty = false
	local folder = self.folder
	if folder == nil then
		self.index = {}
		self.tempIndex = {}
		self.hashIndex = {}
		self.unhashed = {}
		return
	end
	local items: { Item } = {}
	local present: { [any]: boolean } = {}
	for _, instance in folder:GetDescendants() do
		if not instance:IsA("ModuleScript") then
			continue
		end
		present[instance] = true
		local label = Registry.labelOf(folder, instance)
		self.labels[instance] = label
		table.insert(items, {
			module = instance,
			id = instance:GetAttribute(Registry.ATTRIBUTE),
			tempId = instance:GetAttribute(Registry.TEMP_ATTRIBUTE),
			hash = instance:GetAttribute(Registry.HASH_ATTRIBUTE),
			label = label,
		})
		if self.moduleConnections[instance] == nil then
			local function changed()
				self.dirty = true
				self.loaded[instance] = nil
			end
			local asset = instance:GetAttributeChangedSignal(Registry.ATTRIBUTE):Connect(changed)
			local temp =
				instance:GetAttributeChangedSignal(Registry.TEMP_ATTRIBUTE):Connect(changed)
			local hash =
				instance:GetAttributeChangedSignal(Registry.HASH_ATTRIBUTE):Connect(changed)
			self.moduleConnections[instance] = {
				Disconnect = function()
					asset:Disconnect()
					temp:Disconnect()
					hash:Disconnect()
				end,
			}
		end
	end
	for module, connection in self.moduleConnections do
		if not present[module] then
			connection:Disconnect()
			self.moduleConnections[module] = nil
		end
	end
	local index, problems = Registry.buildIndex(items)
	self.index = index
	self.tempIndex = Registry.buildTempIndex(items)
	self.hashIndex, self.unhashed = Registry.buildHashIndex(items)
	for _, problem in problems do
		self:warnOnce(problem, problem)
	end
end

function Registry.lookup(self: Registry, assetId: number): Entry?
	if self.dirty then
		self:rebuild()
	end
	return self.index[assetId]
end

function Registry.lookupTemp(self: Registry, tempId: string): Entry?
	if self.dirty then
		self:rebuild()
	end
	return self.tempIndex[tempId]
end

function Registry.lookupHash(self: Registry, hash: string): Entry?
	if self.dirty then
		self:rebuild()
	end
	local found = self.hashIndex[hash]
	if found ~= nil or #self.unhashed == 0 then
		return found
	end
	local items = self.unhashed
	self.unhashed = {}
	for _, item in items do
		local sidecar = self:load(item.module)
		if sidecar ~= nil and self.hashIndex[sidecar.hash] == nil then
			self.hashIndex[sidecar.hash] = {
				module = item.module,
				assetId = Registry.normalizeId(item.id),
				tempId = Registry.tempIdOf(item.tempId),
				hash = sidecar.hash,
				label = item.label,
			}
		end
	end
	return self.hashIndex[hash]
end

function Registry.label(self: Registry, module: any): string
	local label = self.labels[module]
	if label == nil then
		label = Registry.labelOf(self.folder, module)
		self.labels[module] = label
	end
	return label
end

function Registry.load(self: Registry, module: any): (Sidecar.Sidecar?, string?)
	local memo = self.loaded[module]
	if memo ~= nil then
		return memo.sidecar, memo.problem
	end
	local result: Loaded
	local ok, value = pcall(self.require, module)
	if not ok then
		result = { problem = `it could not be loaded: {tostring(value)}` }
	else
		local valid, problem = Sidecar.validate(value)
		if not valid then
			result = { problem = problem }
		else
			local sidecar = value :: Sidecar.Sidecar
			local attributeOk, raw = pcall(function()
				return module:GetAttribute(Registry.ATTRIBUTE)
			end)
			local attribute = if attributeOk then Registry.normalizeId(raw) else nil
			if attribute ~= nil and sidecar.assetId ~= nil and attribute ~= sidecar.assetId then
				result = {
					problem = `its {Registry.ATTRIBUTE} attribute says asset {string.format(
						"%d",
						attribute
					)} but the data inside it is for asset {string.format(
						"%d",
						sidecar.assetId
					)} - export it again from Apex Animator`,
				}
			else
				result = { sidecar = sidecar }
			end
		end
	end
	self.loaded[module] = result
	return result.sidecar, result.problem
end

local function playing(track: any): boolean
	local ok, yes = pcall(function()
		return track.IsPlaying
	end)
	return ok and yes == true
end

local function release(waiter: Waiter)
	for _, connection in waiter.connections do
		connection:Disconnect()
	end
	table.clear(waiter.connections)
end

local function warnUnmatched(self: Registry, id: number)
	local hash = self.hashes[id]
	if type(hash) ~= "string" or not self.needs[id] or self:lookupHash(hash) ~= nil then
		return
	end
	local where = if self.folder ~= nil
		then Registry.labelOf(nil, self.folder)
		else "the registry folder"
	local idText = string.format("%d", id)
	self:warnOnce(
		`unmatched:{idText}:{hash}`,
		`ApexEngine: asset {idText} is an Apex Animator animation with parts only ApexEngine plays, but {where} has no module for this version of it, so it plays without them. Publish it again from Apex Animator in this place to write its module.`
	)
end

local function learned(self: Registry, id: number, hash: string | false, needs: boolean?)
	if needs ~= nil then
		self.needs[id] = needs
	end
	if self.hashes[id] == nil then
		self.hashes[id] = hash
		local waiters = self.waiting[id] or {}
		self.waiting[id] = nil
		for _, waiter in waiters do
			release(waiter)
			if hash ~= false and playing(waiter.track) then
				self.config.onTrack(waiter.animator, waiter.track, true)
			end
		end
	end
	warnUnmatched(self, id)
end

local function await(self: Registry, animator: any, track: any, id: number)
	local waiters = self.waiting[id]
	if waiters == nil then
		waiters = {}
		self.waiting[id] = waiters
	end
	for _, waiter in waiters :: { Waiter } do
		if waiter.track == track then
			return
		end
	end
	local waiter: Waiter = { animator = animator, track = track, connections = {} }
	table.insert(waiters :: { Waiter }, waiter)
	pcall(function()
		local marker = track:GetMarkerReachedSignal(Registry.MARKER)
		table.insert(
			waiter.connections,
			marker:Connect(function(value: any)
				if type(value) == "string" and value ~= "" then
					learned(self, id, value, nil)
				end
			end)
		)
		table.insert(
			waiter.connections,
			track.Stopped:Connect(function()
				release(waiter)
				local list = self.waiting[id]
				local index = if list ~= nil then table.find(list, waiter) else nil
				if index ~= nil then
					table.remove(list :: { Waiter }, index)
				end
			end)
		)
	end)
	if self.fetching[id] then
		return
	end
	self.fetching[id] = true
	self.spawn(function()
		local ok, clip = pcall(self.getClip, id)
		if ok and clip ~= nil then
			learned(self, id, Registry.clipHash(clip))
		end
	end)
end

function Registry.lookupClip(self: Registry, animator: any, track: any, id: number): Entry?
	local hash = self.hashes[id]
	if hash == nil then
		await(self, animator, track, id)
		return nil
	elseif hash == false then
		return nil
	end
	local entry = self:lookupHash(hash :: string)
	if entry == nil then
		warnUnmatched(self, id)
	end
	return entry
end

function Registry.resolve(self: Registry, animator: any, track: any): (Sidecar.Sidecar?, Entry?)
	if Registry.ignored(animator) then
		return nil, nil
	end
	local id = Registry.trackId(track)
	local entry = if id ~= nil then self:lookup(id) else nil
	local played = if id ~= nil then `asset {string.format("%d", id)}` else ""
	if entry == nil then
		local tempId = Registry.trackTempId(track)
		entry = if tempId ~= nil then self:lookupTemp(tempId) else nil
		played = "its temporary copy"
	end
	if entry == nil and id ~= nil then
		entry = self:lookupClip(animator, track, id)
		played = `asset {string.format("%d", id)}`
	end
	if entry == nil then
		return nil, nil
	end
	local found = entry :: Entry
	local sidecar, problem = self:load(found.module)
	if sidecar == nil then
		self:warnOnce(
			`load:{found.label}`,
			`ApexEngine: {found.label} cannot be used, so {played} plays as a plain Roblox animation: {problem}.`
		)
		return nil, nil
	end
	return sidecar, found
end

local function isAnimator(instance: any): boolean
	local ok, yes = pcall(function()
		return instance:IsA("Animator")
	end)
	return ok and yes == true
end

function Registry.scan(self: Registry, animator: any)
	local ok, tracks = pcall(function()
		return animator:GetPlayingAnimationTracks()
	end)
	if not ok then
		return
	end
	for _, track in tracks do
		self.config.onTrack(animator, track, true)
	end
end

function Registry.watchAnimator(self: Registry, animator: any)
	if self.animators[animator] ~= nil then
		return
	end
	local connections: { any } = {}
	self.animators[animator] = connections
	local appeared = self.config.onAnimator
	if appeared ~= nil then
		appeared(animator)
	end
	table.insert(
		connections,
		animator.AnimationPlayed:Connect(function(track: any)
			self.config.onTrack(animator, track, false)
		end)
	)
	self:scan(animator)
	self.defer(function()
		if self.animators[animator] == connections then
			self:scan(animator)
		end
	end)
end

function Registry.unwatchAnimator(self: Registry, animator: any)
	local connections = self.animators[animator]
	if connections == nil then
		return
	end
	self.animators[animator] = nil
	disconnectAll(connections)
	local gone = self.config.onAnimatorGone
	if gone ~= nil then
		gone(animator)
	end
end

function Registry.watch(self: Registry, root: any)
	if self.root == root then
		return
	end
	disconnectAll(self.rootConnections)
	self.root = root
	for _, instance in root:GetDescendants() do
		if isAnimator(instance) then
			self:watchAnimator(instance)
		end
	end
	table.insert(
		self.rootConnections,
		root.DescendantAdded:Connect(function(instance: any)
			if isAnimator(instance) then
				self:watchAnimator(instance)
			end
		end)
	)
	table.insert(
		self.rootConnections,
		root.DescendantRemoving:Connect(function(instance: any)
			if self.animators[instance] ~= nil then
				self:unwatchAnimator(instance)
			end
		end)
	)
end

function Registry.destroy(self: Registry)
	disconnectAll(self.rootConnections)
	disconnectAll(self.folderConnections)
	for _, waiters in self.waiting do
		for _, waiter in waiters do
			release(waiter)
		end
	end
	table.clear(self.waiting)
	for module, connection in self.moduleConnections do
		connection:Disconnect()
		self.moduleConnections[module] = nil
	end
	local animators: { any } = {}
	for animator in self.animators do
		table.insert(animators, animator)
	end
	for _, animator in animators do
		self:unwatchAnimator(animator)
	end
	self.root = nil
end

return Registry
