--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local Props = require(script.Parent.Props)
local Joint = require(script.Parent.Parent.Core.Joint)
local Types = require(script.Parent.Parent.Core.Types)
local ReleaseMath = require(script.Parent.Parent.Shared.ReleaseMath)
local StateEval = require(script.Parent.Parent.Shared.StateEval)

local Releases = {}

Releases.NAME = "releases"

Releases.FOLDER = "ApexReleases"

Releases.COLLISION_GROUP = "ApexReleases"

export type Rule = {
	class: string,
	property: string,
	type: Types.PropValueType,
	value: any,
}

Releases.HIDE = table.freeze({
	table.freeze({ class = "BasePart", property = "Transparency", type = "number", value = 1 }),
	table.freeze({ class = "Decal", property = "Transparency", type = "number", value = 1 }),
	table.freeze({ class = "Light", property = "Enabled", type = "boolean", value = false }),
	table.freeze({ class = "Beam", property = "Enabled", type = "boolean", value = false }),
	table.freeze({ class = "Trail", property = "Enabled", type = "boolean", value = false }),
	table.freeze({
		class = "ParticleEmitter",
		property = "Enabled",
		type = "boolean",
		value = false,
	}),
}) :: { Rule }

type Piece = {
	instance: any,
	path: string,
	rule: Rule,
}

type Held = {
	hold: Props.Hold,
	piece: Piece,
	shown: any,
}

type Target = {
	address: string,
	part: any,
	entries: { ReleaseMath.Release },
	onEnd: Types.EndBehaviour?,
	pieces: { Piece },
	held: { Held }?,
}

type Play = {
	active: boolean,
	time: number?,
	speed: number,
	at: number,
	releases: { ReleaseMath.Release },
	targets: { [string]: Target },
	order: { Target },
}

local ledgers: { [any]: ReleaseMath.Ledger } = setmetatable({}, { __mode = "k" }) :: any

local function index(instance: any, property: string): any
	return instance[property]
end

local function assign(instance: any, property: string, value: any)
	instance[property] = value
end

local function isA(instance: any, class: string): boolean
	return instance:IsA(class)
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[Releases.NAME]
end

function Releases.partOf(root: any, address: string): (any?, string?)
	local ok, descendants = pcall(function()
		return root:GetDescendants()
	end)
	if not ok then
		return nil, nil
	end
	for _, instance in descendants do
		local okKind, kind = pcall(Joint.kindOf, instance)
		if not okKind or kind == nil then
			continue
		end
		local okAddress, named = pcall(Joint.addressOf, kind, instance)
		if not okAddress or named ~= address then
			continue
		end
		local okJoint, joint = pcall(Joint.new, instance)
		if not okJoint or joint == nil then
			continue
		end
		local child = (joint :: Joint.Joint).child
		local okPart, part = pcall(isA, child, "BasePart")
		if okPart and part then
			return child, nil
		end
		return nil, `{address} is a bone, and only a part can be let go`
	end
	return nil, nil
end

local function piecesOf(part: any, address: string): { Piece }
	local out: { Piece } = {}
	local all = { part }
	local ok, descendants = pcall(function()
		return part:GetDescendants()
	end)
	if ok then
		table.move(descendants, 1, #descendants, 2, all)
	end
	for position, instance in all do
		for _, rule in Releases.HIDE do
			local okIs, is = pcall(isA, instance, rule.class)
			if okIs and is then
				local name = if position == 1 then address else `{address}/{instance.Name}`
				table.insert(out, { instance = instance, path = name, rule = rule })
				break
			end
		end
	end
	return out
end

local function hide(live: ApexTrack.Live, target: Target)
	local held: { Held } = {}
	for _, piece in target.pieces do
		local rule = piece.rule
		local okRead, shown = pcall(index, piece.instance, rule.property)
		local hold = Props.hold(piece.path, rule.class, rule.property, rule.type, piece.instance)
		if hold ~= nil then
			Props.set(live, hold, rule.value)
			table.insert(held, {
				hold = hold :: Props.Hold,
				piece = piece,
				shown = if okRead then shown else nil,
			})
		end
	end
	target.held = held
end

local function show(target: Target, outcome: ApexTrack.Outcome)
	local held = target.held
	if held == nil then
		return
	end
	target.held = nil
	for _, item in held do
		Props.letGo(item.hold, outcome, if outcome == "Final" then item.piece.rule.value else nil)
	end
end

local function sync(live: ApexTrack.Live, play: Play, t: number)
	for _, target in play.order do
		local hidden = ReleaseMath.looseAt(target.entries, target.address, t)
		if hidden and target.held == nil then
			hide(live, target)
		elseif not hidden and target.held ~= nil then
			show(target, "Revert")
		end
	end
end

local function settle(
	live: ApexTrack.Live,
	target: Target,
	outcome: ApexTrack.Outcome,
	finish: number
)
	if outcome == "Final" then
		if ReleaseMath.looseAt(target.entries, target.address, finish) then
			if target.held == nil then
				hide(live, target)
			end
			show(target, "Final")
		else
			show(target, "Revert")
		end
		return
	end
	show(target, outcome)
end

local function withShown<T>(target: Target, fn: () -> T): T
	local held = target.held
	if held == nil then
		return fn()
	end
	local now: { any } = {}
	for position, item in held do
		local piece = item.piece
		local ok, value = pcall(index, piece.instance, piece.rule.property)
		now[position] = if ok then value else nil
		if item.shown ~= nil then
			pcall(assign, piece.instance, piece.rule.property, item.shown)
		end
	end
	local result = fn()
	for position, item in held do
		if now[position] ~= nil then
			pcall(assign, item.piece.instance, item.piece.rule.property, now[position])
		end
	end
	return result
end

function Releases.onServer(): boolean
	return Props.onServer()
end

function Releases.container(): any?
	local ok, folder = pcall(function()
		local world = workspace
		local found = world:FindFirstChild(Releases.FOLDER)
		if found == nil then
			found = Instance.new("Folder")
			found.Name = Releases.FOLDER
			found.Archivable = false
			found.Parent = world
		end
		return found
	end)
	return if ok then folder else nil
end

function Releases.collisionGroup(): string?
	local ok, registered = pcall(function()
		return game:GetService("PhysicsService")
			:IsCollisionGroupRegistered(Releases.COLLISION_GROUP)
	end)
	return if ok and registered == true then Releases.COLLISION_GROUP else nil
end

function Releases.prepare(clone: any, collide: boolean?)
	local inside: { [any]: boolean } = { [clone] = true }
	local all = { clone }
	for _, descendant in clone:GetDescendants() do
		inside[descendant] = true
		table.insert(all, descendant)
	end
	local function reaches(instance: any, a: string, b: string): boolean
		for _, property in { a, b } do
			local ok, other = pcall(index, instance, property)
			if ok and other ~= nil and not inside[other] then
				return true
			end
		end
		return false
	end
	local group = Releases.collisionGroup()
	for _, instance in all do
		local doomed = false
		if isA(instance, "LuaSourceContainer") then
			doomed = true
		elseif isA(instance, "JointInstance") or isA(instance, "WeldConstraint") then
			doomed = reaches(instance, "Part0", "Part1")
		elseif isA(instance, "Constraint") then
			doomed = reaches(instance, "Attachment0", "Attachment1")
		elseif isA(instance, "BasePart") then
			pcall(assign, instance, "Anchored", false)
			pcall(assign, instance, "CanCollide", collide ~= false)
			pcall(assign, instance, "CanTouch", false)
			pcall(assign, instance, "CanQuery", false)
			pcall(assign, instance, "Massless", false)
			if group ~= nil then
				pcall(assign, instance, "CollisionGroup", group)
			end
		end
		if doomed and instance ~= clone then
			pcall(function()
				instance:Destroy()
			end)
		end
	end
end

function Releases.makeClone(part: any, collide: boolean?): any?
	local container = Releases.container()
	if container == nil then
		return nil
	end
	local ok, clone = pcall(function()
		local archivable = part.Archivable
		part.Archivable = true
		local copy = part:Clone()
		part.Archivable = archivable
		return copy
	end)
	if not ok or clone == nil then
		return nil
	end
	Releases.prepare(clone, collide)
	clone.Parent = container
	return clone
end

function Releases.launch(clone: any, part: any, velocity: ReleaseMath.Velocity?)
	local okFrame, cframe = pcall(index, part, "CFrame")
	if not okFrame or typeof(cframe) ~= "CFrame" then
		return
	end
	local okCentre, centre = pcall(index, clone, "AssemblyCenterOfMass")
	local at: Vector3? = if okCentre and typeof(centre) == "Vector3" then centre else nil
	local okLinear, inheritLinear = pcall(function()
		return part:GetVelocityAtPosition(at or cframe.Position)
	end)
	local okAngular, inheritAngular = pcall(index, part, "AssemblyAngularVelocity")
	local linear, angular = ReleaseMath.launch(
		velocity,
		cframe,
		at,
		if okLinear and typeof(inheritLinear) == "Vector3" then inheritLinear else nil,
		if okAngular and typeof(inheritAngular) == "Vector3" then inheritAngular else nil
	)
	pcall(assign, clone, "AssemblyLinearVelocity", linear)
	pcall(assign, clone, "AssemblyAngularVelocity", angular)
end

function Releases.destroy(clone: any)
	pcall(function()
		clone:Destroy()
	end)
end

function Releases.delay(seconds: number, fn: () -> ())
	task.delay(seconds, fn)
end

local function ledgerOf(rig: any): ReleaseMath.Ledger
	local ledger = ledgers[rig]
	if ledger == nil then
		ledger = ReleaseMath.ledger()
		ledgers[rig] = ledger
	end
	return ledger :: ReleaseMath.Ledger
end

function Releases.alive(rig: any, sidecar: any?, which: number?): number
	local ledger = ledgers[rig]
	if ledger == nil then
		return 0
	end
	if sidecar == nil or which == nil then
		return ReleaseMath.count(ledger)
	end
	return ReleaseMath.count(ledger, `{sidecar.name}:{sidecar.hash}#{which}`)
end

local function spawn(live: ApexTrack.Live, target: Target, release: ReleaseMath.Release, at: number)
	local ledger = ledgerOf(live.rig)
	local now = live.clock()
	for _, entry in ReleaseMath.expire(ledger, now) do
		Releases.destroy(entry.id)
	end
	local clone = withShown(target, function()
		return Releases.makeClone(target.part, release.collide)
	end)
	if clone == nil then
		live.warnOnce(
			`releases:clone:{live.label}:{target.address}`,
			`ApexEngine: {live.label} cannot make a copy of {target.address} to let go of, so its release only hides it.`
		)
		return
	end
	Releases.launch(clone, target.part, ReleaseMath.decode(release.velocity))
	local lifetime = ReleaseMath.lifetimeOf(release)
	local key = `{live.sidecar.name}:{live.sidecar.hash}#{at}`
	for _, entry in ReleaseMath.admit(ledger, key, clone, now, lifetime, ReleaseMath.capOf(release)) do
		Releases.destroy(entry.id)
	end
	Releases.delay(lifetime, function()
		if ReleaseMath.remove(ledger, clone) ~= nil then
			Releases.destroy(clone)
		end
	end)
end

local function collect(live: ApexTrack.Live, play: Play, at: number)
	local ledger = ledgers[live.rig]
	if ledger == nil then
		return
	end
	local joint = play.releases[at].joint
	local keys: { [string]: boolean } = {}
	for which, release in play.releases do
		if release.joint == joint and not ReleaseMath.isAttach(release) then
			keys[`{live.sidecar.name}:{live.sidecar.hash}#{which}`] = true
		end
	end
	for _, entry in ReleaseMath.take(ledger, keys) do
		Releases.destroy(entry.id)
	end
end

local function fire(live: ApexTrack.Live, play: Play, at: number)
	local release = play.releases[at]
	if ReleaseMath.isAttach(release) then
		if release.leaveCopy ~= true then
			collect(live, play, at)
		end
		return
	end
	local target = play.targets[release.joint]
	if target == nil or release.cosmetic == false then
		return
	end
	spawn(live, target, release, at)
end

local function fireCrossed(live: ApexTrack.Live, play: Play, from: number, to: number)
	for _, at in StateEval.crossed(play.releases, from, to) do
		fire(live, play, at)
	end
end

function Releases.began(live: ApexTrack.Live)
	local releases: { ReleaseMath.Release }? = live.sidecar.releases :: any
	local root = live.rig
	if releases == nil or #releases == 0 or root == nil or Releases.onServer() then
		live.data[Releases.NAME] = nil
		return
	end
	local play: Play = {
		active = true,
		time = nil,
		speed = live.speed,
		at = live.seenClock,
		releases = releases,
		targets = {},
		order = {},
	}
	local missing: { [string]: boolean } = {}
	for _, release in releases do
		local address = release.joint
		local target = play.targets[address]
		if target ~= nil then
			table.insert(target.entries, release)
			if not ReleaseMath.isAttach(release) then
				target.onEnd = release.onEnd
			end
			continue
		end
		if missing[address] then
			continue
		end
		local part, problem = Releases.partOf(root, address)
		if part == nil then
			missing[address] = true
			if problem ~= nil then
				live.warnOnce(
					`releases:part:{live.label}:{address}`,
					`ApexEngine: {live.label} has a release that does nothing: {problem}.`
				)
			end
			continue
		end
		local made: Target = {
			address = address,
			part = part,
			entries = { release },
			onEnd = if ReleaseMath.isAttach(release) then nil else release.onEnd,
			pieces = piecesOf(part, address),
			held = nil,
		}
		play.targets[address] = made
		table.insert(play.order, made)
	end
	table.sort(play.order, function(a: Target, b: Target): boolean
		return a.address < b.address
	end)
	live.data[Releases.NAME] = play
end

function Releases.step(rig: Frame.Rig, dt: number, catchUp: boolean)
	for _, live in rig.lives do
		local play = playOf(live)
		if play == nil or not play.active or live.phase ~= "Playing" then
			continue
		end
		local t = live.time
		if not catchUp then
			local travel = StateEval.travel({
				from = play.time,
				to = t,
				speed = live.speed,
				lastSpeed = play.speed,
				dt = dt,
				looped = live.looped,
				length = live.sidecar.length,
				late = live.late,
			})
			if travel == "Forward" then
				fireCrossed(live, play, play.time or -math.huge, t)
			end
		end
		sync(live, play, t)
		play.time = t
		play.speed = live.speed
		play.at = live.seenClock
	end
end

function Releases.stopped(
	live: ApexTrack.Live,
	reason: ApexTrack.EndReason,
	policy: Types.InterruptPolicy
)
	local play = playOf(live)
	if play == nil or not play.active then
		return
	end
	play.active = false
	local length = live.sidecar.length
	local fresh = live.seenClock - play.at <= StateEval.SLACK
	if reason == "Completed" and play.speed >= 0 and fresh then
		local travel = StateEval.travel({
			from = play.time,
			to = length,
			speed = live.seenSpeed,
			lastSpeed = play.speed,
			dt = live.stoppedClock - play.at,
			looped = false,
			length = length,
			late = live.late,
		})
		if travel == "Forward" then
			fireCrossed(live, play, play.time or -math.huge, math.huge)
		end
	end
	local finish = if play.speed < 0 then 0 else length
	for _, target in play.order do
		settle(live, target, ApexTrack.outcome(reason, policy, target.onEnd), finish)
	end
end

Releases.extension = {
	name = Releases.NAME,
	stage = "releases",
	cosmetic = true,
	began = Releases.began,
	stopped = Releases.stopped,
	step = Releases.step,
} :: Frame.Extension

return Releases
