--!strict

local Signal = require(script.Parent.Parent.Signal)
local Types = require(script.Parent.Parent.Core.Types)

local RigState = {}

RigState.ATTRIBUTE = "Apex_RigState"

RigState.HOME_PART0 = "Apex_HomePart0"
RigState.HOME_C0 = "Apex_HomeC0"

RigState.SNAPSHOT_VERSION = 1

local MAX_DEPTH = 16

RigState.PARENT = table.freeze({ kind = "Parent" }) :: Types.SpaceTarget

export type Transition = {
	from: Types.SpaceTarget,
	fromValue: CFrame?,
	fromCapture: boolean?,
	start: number,
	duration: number,
}

export type Entry = {
	target: Types.SpaceTarget,
	value: CFrame?,
	capture: boolean?,
	transition: Transition?,
}

export type Held = {
	target: Types.SpaceTarget,
	value: CFrame,
}

export type State = {
	model: any,
	joints: { [string]: Entry },
	spaceChanged: Signal.Signal,
	registry: Registry,
	published: string?,
	handle: any?,
}

export type Registry = {
	states: { [any]: State },
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
	wake: (model: any) -> (),
	check: ((state: State, joint: string, target: Types.SpaceTarget) -> string?)?,
}

export type Config = {
	clock: () -> number,
	warnOnce: ((key: string, message: string) -> ())?,
	wake: ((model: any) -> ())?,
}

export type SetOptions = {
	value: CFrame?,
	capture: boolean?,
	blend: number?,
	now: number?,
}

local WORDS: { [string]: boolean } = { Parent = true, World = true, RigRoot = true }

function RigState.same(a: Types.SpaceTarget, b: Types.SpaceTarget): boolean
	return a.kind == b.kind and a.joint == b.joint and a.slot == b.slot
end

function RigState.nameOf(target: Types.SpaceTarget): string
	if target.kind == "Joint" then
		return target.joint or "?"
	end
	return target.kind
end

local function copyTarget(target: Types.SpaceTarget): Types.SpaceTarget
	return { kind = target.kind, joint = target.joint, slot = target.slot }
end

function RigState.parse(value: any): (Types.SpaceTarget?, string?)
	if type(value) == "string" then
		if value == "" then
			return nil, "a space cannot be an empty name"
		end
		if WORDS[value] then
			return { kind = value :: any }, nil
		end
		return { kind = "Joint", joint = value }, nil
	end
	if type(value) == "table" then
		local kind = value.kind
		if kind == "Joint" then
			if type(value.joint) ~= "string" or value.joint == "" then
				return nil,
					'a Joint space must name its joint, as { kind = "Joint", joint = "LeftHand" }'
			end
			return { kind = "Joint", joint = value.joint }, nil
		elseif type(kind) == "string" and WORDS[kind] then
			return { kind = kind :: any }, nil
		end
		return nil,
			`a space table's kind must be "Parent", "World", "RigRoot" or "Joint", not {tostring(
				kind
			)}`
	end
	return nil, `a space is "Parent", "World", "RigRoot" or a joint's name, not a {typeof(value)}`
end

function RigState.registry(config: Config): Registry
	local warned: { [string]: boolean } = {}
	return {
		states = setmetatable({}, { __mode = "k" }) :: any,
		clock = config.clock,
		warnOnce = config.warnOnce or function(key: string, message: string)
			if not warned[key] then
				warned[key] = true
				warn(message)
			end
		end,
		wake = config.wake or function() end,
		check = nil,
	}
end

function RigState.get(registry: Registry, model: any): State
	local state = registry.states[model]
	if state == nil then
		state = {
			model = model,
			joints = {},
			spaceChanged = Signal.new(),
			registry = registry,
			published = nil,
			handle = nil,
		}
		registry.states[model] = state
	end
	return state :: State
end

function RigState.peek(registry: Registry, model: any): State?
	return registry.states[model]
end

function RigState.targetOf(state: State, joint: string): Types.SpaceTarget
	local entry = state.joints[joint]
	return if entry ~= nil then entry.target else RigState.PARENT
end

function RigState.active(state: State): boolean
	return next(state.joints) ~= nil
end

function RigState.remember(state: State, joint: string): Entry
	local entry = state.joints[joint]
	if entry == nil then
		return { target = RigState.PARENT }
	end
	if entry.target.kind == "Parent" then
		return { target = RigState.PARENT }
	end
	if entry.value ~= nil and entry.transition == nil then
		return { target = entry.target, value = entry.value }
	end
	return { target = entry.target, capture = true }
end

function RigState.set(state: State, joint: string, target: Types.SpaceTarget, options: SetOptions?)
	local registry = state.registry
	local previous = state.joints[joint]
	local was = if previous ~= nil then previous.target else RigState.PARENT
	local blend = if options ~= nil and options.blend ~= nil then options.blend else 0

	local transition: Transition? = nil
	if blend > 0 then
		local now = if options ~= nil and options.now ~= nil then options.now else registry.clock()
		if previous == nil or previous.target.kind == "Parent" and previous.transition == nil then
			transition = { from = RigState.PARENT, start = now, duration = blend }
		elseif previous.value ~= nil and previous.transition == nil then
			transition = {
				from = previous.target,
				fromValue = previous.value,
				start = now,
				duration = blend,
			}
		else
			transition = {
				from = previous.target,
				fromCapture = true,
				start = now,
				duration = blend,
			}
		end
	end

	local parent = target.kind == "Parent"
	if parent and transition == nil then
		state.joints[joint] = nil
	else
		state.joints[joint] = {
			target = copyTarget(target),
			value = if parent then nil else (options and options.value),
			capture = if parent or (options and options.value)
				then nil
				else (options and options.capture),
			transition = transition,
		}
	end
	registry.wake(state.model)
	if not RigState.same(was, target) then
		Signal.fire(state.spaceChanged, joint, RigState.nameOf(target), RigState.nameOf(was))
	end
end

function RigState.held(state: State): { [string]: Held }
	local out: { [string]: Held } = {}
	for joint, entry in state.joints do
		if entry.target.kind ~= "Parent" and entry.value ~= nil then
			out[joint] = { target = entry.target, value = entry.value :: CFrame }
		end
	end
	return out
end

function RigState.seed(state: State, held: { [string]: Held })
	local changed: { { joint: string, now: Types.SpaceTarget, was: Types.SpaceTarget } } = {}
	for joint, entry in state.joints do
		if held[joint] == nil and entry.target.kind ~= "Parent" then
			table.insert(changed, { joint = joint, now = RigState.PARENT, was = entry.target })
		end
	end
	for joint, item in held do
		local was = RigState.targetOf(state, joint)
		if not RigState.same(was, item.target) then
			table.insert(changed, { joint = joint, now = item.target, was = was })
		end
	end
	table.clear(state.joints)
	for joint, item in held do
		state.joints[joint] = { target = copyTarget(item.target), value = item.value }
	end
	table.sort(changed, function(a, b): boolean
		return a.joint < b.joint
	end)
	if next(state.joints) ~= nil then
		state.registry.wake(state.model)
	end
	for _, change in changed do
		Signal.fire(
			state.spaceChanged,
			change.joint,
			RigState.nameOf(change.now),
			RigState.nameOf(change.was)
		)
	end
end

function RigState.appeared(registry: Registry, model: any)
	local ok, text = pcall(function()
		return model:GetAttribute(RigState.ATTRIBUTE)
	end)
	if not ok then
		return
	end
	local held, problem = RigState.decode(text)
	if problem ~= nil then
		registry.warnOnce(
			`snapshot:{problem}`,
			`ApexEngine: the spaces saved on a rig ({RigState.ATTRIBUTE}) could not all be read, so some of its joints start in their default space: {problem}.`
		)
	end
	if next(held) == nil and RigState.peek(registry, model) == nil then
		return
	end
	RigState.seed(RigState.get(registry, model), held)
end

local function number(n: number): string
	if n == 0 then
		return "0"
	end
	return string.format("%.9g", n)
end

local ESCAPES: { [string]: string } = {
	['"'] = '\\"',
	["\\"] = "\\\\",
	["\b"] = "\\b",
	["\f"] = "\\f",
	["\n"] = "\\n",
	["\r"] = "\\r",
	["\t"] = "\\t",
}

local function quote(text: string): string
	return '"'
		.. string.gsub(text, '[%c"\\]', function(char: string): string
			return ESCAPES[char] or string.format("\\u%04x", string.byte(char))
		end)
		.. '"'
end

local function finite(n: number): boolean
	return n == n and n ~= math.huge and n ~= -math.huge
end

function RigState.encode(held: { [string]: Held }): string?
	local names: { string } = {}
	for joint in held do
		table.insert(names, joint)
	end
	table.sort(names)
	local parts: { string } = {}
	for _, joint in names do
		local item = held[joint]
		local target = item.target
		if target.kind == "Parent" then
			continue
		end
		local components = { item.value:GetComponents() }
		local numbers: { string } = {}
		local ok = true
		for _, component in components do
			if not finite(component) then
				ok = false
				break
			end
			table.insert(numbers, number(component))
		end
		if not ok then
			continue
		end
		local fields = { `"space":{quote(target.kind)}` }
		if target.kind == "Joint" then
			table.insert(fields, `"joint":{quote(target.joint or "")}`)
		end
		if target.slot ~= nil then
			table.insert(fields, `"slot":{quote(target.slot)}`)
		end
		table.insert(fields, `"cframe":[{table.concat(numbers, ",")}]`)
		table.insert(parts, `{quote(joint)}:\{{table.concat(fields, ",")}\}`)
	end
	if #parts == 0 then
		return nil
	end
	return `\{"version":{RigState.SNAPSHOT_VERSION},"joints":\{{table.concat(parts, ",")}\}\}`
end

local function parse(text: string): (any, string?)
	local at = 1
	local length = #text

	local function skip()
		at = string.find(text, "[^ \t\r\n]", at) or length + 1
	end

	local value: (depth: number) -> (any, string?)

	local function stringAt(): (string?, string?)
		local out: { string } = {}
		at += 1
		while at <= length do
			local char = string.sub(text, at, at)
			if char == '"' then
				at += 1
				return table.concat(out), nil
			elseif char == "\\" then
				local kind = string.sub(text, at + 1, at + 1)
				local simple = ({
					['"'] = '"',
					["\\"] = "\\",
					["/"] = "/",
					b = "\b",
					f = "\f",
					n = "\n",
					r = "\r",
					t = "\t",
				})[kind]
				if simple ~= nil then
					table.insert(out, simple)
					at += 2
				elseif kind == "u" then
					local hex = string.match(text, "^%x%x%x%x", at + 2)
					if hex == nil then
						return nil, "a \\u escape is damaged"
					end
					local code = tonumber(hex, 16) :: number
					at += 6
					if code >= 0xD800 and code <= 0xDBFF then
						local low = string.match(text, "^\\u(%x%x%x%x)", at)
						local second = if low then tonumber(low, 16) else nil
						if second == nil or second < 0xDC00 or second > 0xDFFF then
							return nil, "a \\u escape is half of a pair"
						end
						code = 0x10000 + (code - 0xD800) * 0x400 + (second - 0xDC00)
						at += 6
					end
					table.insert(out, utf8.char(code))
				else
					return nil, "a string has an unknown escape"
				end
			elseif string.byte(char) < 0x20 then
				return nil, "a string holds a raw control character"
			else
				local run = string.match(text, '^[^"\\%c]+', at) or char
				table.insert(out, run)
				at += #run
			end
		end
		return nil, "a string is not closed"
	end

	value = function(depth: number): (any, string?)
		if depth > MAX_DEPTH then
			return nil, "it nests too deep"
		end
		skip()
		local char = string.sub(text, at, at)
		if char == "{" then
			local out = {}
			at += 1
			skip()
			if string.sub(text, at, at) == "}" then
				at += 1
				return out, nil
			end
			while true do
				skip()
				if string.sub(text, at, at) ~= '"' then
					return nil, "an object's key is not a string"
				end
				local key, problem = stringAt()
				if key == nil then
					return nil, problem
				end
				skip()
				if string.sub(text, at, at) ~= ":" then
					return nil, "an object is missing a ':'"
				end
				at += 1
				local item, inner = value(depth + 1)
				if inner ~= nil then
					return nil, inner
				end
				out[key] = item
				skip()
				local sep = string.sub(text, at, at)
				at += 1
				if sep == "}" then
					return out, nil
				elseif sep ~= "," then
					return nil, "an object is missing a ',' or '}'"
				end
			end
		elseif char == "[" then
			local out = {}
			at += 1
			skip()
			if string.sub(text, at, at) == "]" then
				at += 1
				return out, nil
			end
			while true do
				local item, inner = value(depth + 1)
				if inner ~= nil then
					return nil, inner
				end
				table.insert(out, item)
				skip()
				local sep = string.sub(text, at, at)
				at += 1
				if sep == "]" then
					return out, nil
				elseif sep ~= "," then
					return nil, "a list is missing a ',' or ']'"
				end
			end
		elseif char == '"' then
			return stringAt()
		elseif string.sub(text, at, at + 3) == "true" then
			at += 4
			return true, nil
		elseif string.sub(text, at, at + 4) == "false" then
			at += 5
			return false, nil
		elseif string.sub(text, at, at + 3) == "null" then
			at += 4
			return nil, nil
		end
		local literal = string.match(text, "^-?%d+%.?%d*[eE]?[-+]?%d*", at)
		local n = if literal then tonumber(literal) else nil
		if n == nil then
			return nil, "it holds something that is not JSON"
		end
		at += #(literal :: string)
		return n, nil
	end

	local result, problem = value(1)
	if problem ~= nil then
		return nil, problem
	end
	skip()
	if at <= length then
		return nil, "it has something after its end"
	end
	return result, nil
end

local function heldOf(joint: string, raw: any): (Held?, string?)
	if type(raw) ~= "table" then
		return nil, `'{joint}' is not described`
	end
	local kind = raw.space
	local target: Types.SpaceTarget
	if kind == "World" or kind == "RigRoot" then
		target = { kind = kind }
	elseif kind == "Joint" then
		if type(raw.joint) ~= "string" or raw.joint == "" then
			return nil, `'{joint}' follows a joint but does not say which`
		end
		target = { kind = "Joint", joint = raw.joint }
	else
		return nil, `'{joint}' is in a space this engine does not know ({tostring(kind)})`
	end
	if raw.slot ~= nil then
		if type(raw.slot) ~= "string" or raw.slot == "" then
			return nil, `'{joint}' names a damaged slot`
		end
		target.slot = raw.slot
	end
	local list = raw.cframe
	if type(list) ~= "table" or #list ~= 12 then
		return nil, `'{joint}' has no usable placement`
	end
	for _, n in list do
		if type(n) ~= "number" or not finite(n) then
			return nil, `'{joint}' has no usable placement`
		end
	end
	return {
		target = target,
		value = CFrame.new(
			list[1],
			list[2],
			list[3],
			list[4],
			list[5],
			list[6],
			list[7],
			list[8],
			list[9],
			list[10],
			list[11],
			list[12]
		),
	},
		nil
end

function RigState.decode(text: any): ({ [string]: Held }, string?)
	local out: { [string]: Held } = {}
	if text == nil then
		return out, nil
	end
	if type(text) ~= "string" then
		return out, `it is a {typeof(text)}, not text`
	end
	local data, problem = parse(text)
	if problem ~= nil then
		return out, `it is damaged: {problem}`
	end
	if type(data) ~= "table" then
		return out, "it is damaged: it is not a table of joints"
	end
	local version = data.version
	if type(version) ~= "number" then
		return out, "it is damaged: it has no version"
	end
	if version > RigState.SNAPSHOT_VERSION then
		return out,
			`it was written by a newer ApexEngine (snapshot {version}); update ApexEngine in this place`
	end
	if type(data.joints) ~= "table" then
		return out, "it is damaged: it has no joints"
	end
	local names: { string } = {}
	local first: string? = nil
	for joint in data.joints do
		if type(joint) == "string" then
			table.insert(names, joint)
		elseif first == nil then
			first = "it is damaged: its joints are not named"
		end
	end
	table.sort(names)
	for _, joint in names do
		local held, why = heldOf(joint, data.joints[joint])
		if held ~= nil then
			out[joint] = held
		elseif first == nil then
			first = `it is damaged: {why}`
		end
	end
	return out, first
end

local owners: { [any]: State } = setmetatable({}, { __mode = "k" }) :: any

local function stateOf(handle: any): State
	local state = owners[handle]
	if state == nil then
		error(
			"ApexEngine: call this on a rig state, with ':' (rigState:GetSpace(\"Sword\")), not '.'",
			3
		)
	end
	return state
end

local function jointName(joint: any, method: string): string
	if type(joint) ~= "string" or joint == "" then
		error(
			`ApexEngine: {method} needs the joint's name (the part it moves, as the animation calls it), not a {typeof(
				joint
			)}`,
			3
		)
	end
	return joint
end

--[=[
	@class RigState

	Which space each joint of a rig is in, from GetRigState. Call its methods with `:`.
]=]
local Methods = {}

--[=[
	@method GetSpace
	@within RigState

	Returns the space a joint is in: "Parent" (the default), "World", "RigRoot" or the name of
	the joint it follows.

	@param joint string
	@return string
	@return { kind: string, joint: string? } -- the same space, which tells a joint named "World" apart from World space
]=]
function Methods.GetSpace(self: any, joint: string): (string, Types.SpaceTarget)
	local state = stateOf(self)
	local target = RigState.targetOf(state, jointName(joint, "GetSpace"))
	return RigState.nameOf(target), copyTarget(target)
end

--[=[
	@method SetSpace
	@within RigState

	Moves a joint into another space, held where it is now. The change is local to this
	machine. On the server it also reaches players who join later.

	@param joint string
	@param space string | { kind: string, joint: string? } -- "Parent", "World", "RigRoot" or a joint's name
	@param blend (number | { blend: number })? -- seconds to blend over, nil is 0
	@return boolean -- false, with a warning, when the rig can't, as with joints in a loop
]=]
function Methods.SetSpace(self: any, joint: string, space: any, blend: any?): boolean
	local state = stateOf(self)
	local name = jointName(joint, "SetSpace")
	local target, problem = RigState.parse(space)
	if target == nil then
		error(`ApexEngine: SetSpace("{name}", ...): {problem}`, 2)
	end
	local seconds: number = 0
	if type(blend) == "table" then
		blend = blend.blend
	end
	if blend ~= nil then
		if type(blend) ~= "number" or blend ~= blend or blend < 0 or blend == math.huge then
			error(
				`ApexEngine: SetSpace's blend is seconds, 0 or more (or \{ blend = 0.15 \}), not {tostring(
					blend
				)}`,
				2
			)
		end
		seconds = blend
	end
	local registry = state.registry
	local check = registry.check
	if check ~= nil then
		local refused = check(state, name, target :: Types.SpaceTarget)
		if refused ~= nil then
			registry.warnOnce(
				`setspace:{refused}`,
				`ApexEngine: SetSpace("{name}") was refused: {refused}`
			)
			return false
		end
	end
	local chosen = target :: Types.SpaceTarget
	RigState.set(state, name, chosen, {
		capture = chosen.kind ~= "Parent",
		blend = seconds,
	})
	return true
end

local HandleMeta = {}

--[=[
	@prop SpaceChanged Signal
	@within RigState
	@readonly

	Fires with (joint, space, previous), as space names, whenever a joint changes space.
]=]
function HandleMeta.__index(handle: any, key: any): any
	local method = (Methods :: any)[key]
	if method ~= nil then
		return method
	end
	local state = stateOf(handle)
	if key == "SpaceChanged" then
		return state.spaceChanged
	end
	error(`ApexEngine: '{tostring(key)}' is not a member of a rig state`, 2)
end

function HandleMeta.__newindex(_: any, key: any)
	error(`ApexEngine: '{tostring(key)}' cannot be set on a rig state`, 2)
end

function HandleMeta.__tostring(handle: any): string
	local state = owners[handle]
	local ok, name = pcall(function()
		return if state ~= nil then state.model.Name else nil
	end)
	return if ok and name ~= nil then `RigState({name})` else "RigState"
end

function RigState.handle(state: State): any
	local handle = state.handle
	if handle == nil then
		handle = setmetatable({}, HandleMeta)
		owners[handle] = state
		state.handle = handle
	end
	return handle
end

return RigState
]=====],
    ["UhhhhhhReanim/System/runtime/steve110/main/apex_engine/Runtime/Sounds.lua"] = [=====[
--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local Props = require(script.Parent.Props)
local Types = require(script.Parent.Parent.Core.Types)
local SoundPlay = require(script.Parent.Parent.Shared.SoundPlay)
local StateEval = require(script.Parent.Parent.Shared.StateEval)

local Sounds = {}

Sounds.NAME = "sounds"

Sounds.VOICE_NAME = "ApexSound"

export type Context = {
	hold: (model: any, on: boolean, name: string?) -> (),
	warnOnce: (key: string, message: string) -> (),
}

type Play = {
	player: SoundPlay.Player,
	time: number?,
	speed: number,
	at: number,
}

type Handle = {
	sound: any,
}

local tails: { [any]: { SoundPlay.Player } } = {}

local function index(instance: any, key: string): any
	return instance[key]
end

local function isA(instance: any, class: string): boolean
	return instance:IsA(class)
end

function Sounds.rootOf(rig: any): any?
	local ok, part = pcall(function()
		local root = rig:FindFirstChild("HumanoidRootPart")
		if root ~= nil and root:IsA("BasePart") then
			return root
		end
		return rig.PrimaryPart
	end)
	return if ok then part else nil
end

function Sounds.newSound(): any
	return Instance.new("Sound")
end

local function makeSound(rig: any, live: ApexTrack.Live, track: Types.SoundTrack): any?
	if track.source ~= nil then
		local source = Props.resolve(rig, track.source)
		if source ~= nil then
			local ok, fits = pcall(isA, source, "Sound")
			if ok and fits then
				local made, copy = pcall(function()
					local clone = source:Clone()
					if clone == nil then
						return nil
					end
					clone.Name = Sounds.VOICE_NAME
					clone.Looped = false
					clone.Playing = false
					clone.Parent = source.Parent
					return clone
				end)
				if made and copy ~= nil then
					return copy
				end
			else
				live.warnOnce(
					`sounds:class:{live.label}:{track.source}`,
					`ApexEngine: {live.label} plays {track.source} as a Sound, but it is not one, so its sound id plays instead.`
				)
			end
		end
	end
	local ok, sound = pcall(function()
		local made = Sounds.newSound()
		made.Name = Sounds.VOICE_NAME
		made.SoundId = track.id
		made.Parent = Sounds.rootOf(rig) or rig
		return made
	end)
	return if ok then sound else nil
end

function Sounds.backend(rig: any, live: ApexTrack.Live): SoundPlay.Backend
	return {
		start = function(
			track: any,
			_clip: any,
			position: number,
			speed: number,
			volume: number
		): any?
			local sound = makeSound(rig, live, track)
			if sound == nil then
				return nil
			end
			sound.Volume = volume
			sound.PlaybackSpeed = speed
			sound.TimePosition = position
			sound:Play()
			return { sound = sound } :: Handle
		end,
		set = function(handle: Handle, volume: number, speed: number)
			local sound = handle.sound
			if sound.Volume ~= volume then
				sound.Volume = volume
			end
			if sound.PlaybackSpeed ~= speed then
				sound.PlaybackSpeed = speed
			end
		end,
		seek = function(handle: Handle, position: number)
			handle.sound.TimePosition = position
		end,
		position = function(handle: Handle): number?
			local sound = handle.sound
			if not (index(sound, "IsLoaded") and index(sound, "IsPlaying")) then
				return nil
			end
			return sound.TimePosition
		end,
		pause = function(handle: Handle)
			handle.sound:Pause()
		end,
		resume = function(handle: Handle, position: number)
			handle.sound.TimePosition = position
			handle.sound:Resume()
		end,
		stop = function(handle: Handle)
			handle.sound:Stop()
			handle.sound:Destroy()
		end,
	}
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[Sounds.NAME]
end

function Sounds.extensions(context: Context): { Frame.Extension }
	local function began(live: ApexTrack.Live)
		local sounds = live.sidecar.sounds
		local rig = live.rig
		if sounds == nil or #sounds == 0 or rig == nil or Props.onServer() then
			live.data[Sounds.NAME] = nil
			return
		end
		live.data[Sounds.NAME] = {
			player = SoundPlay.new(sounds :: any, Sounds.backend(rig, live), live.sidecar.presets),
			time = nil,
			speed = live.speed,
			at = live.seenClock,
		} :: Play
	end

	local function step(rig: Frame.Rig, dt: number)
		for _, live in rig.lives do
			local play = playOf(live)
			if play == nil or live.phase ~= "Playing" then
				continue
			end
			local t = live.time
			local travel = StateEval.travel({
				from = play.time,
				to = t,
				speed = live.speed,
				lastSpeed = play.speed,
				dt = dt,
				looped = live.looped,
				length = live.sidecar.length,
				late = live.late,
			})
			SoundPlay.step(play.player, {
				time = t,
				speed = live.speed,
				dt = dt,
				length = live.sidecar.length,
				jumped = travel == "Jump",
				wrapped = travel == "Forward" and play.time ~= nil and t < play.time - 1e-6,
			})
			play.time = t
			play.speed = live.speed
			play.at = live.seenClock
		end
		local waiting = tails[rig.model]
		if waiting == nil then
			return
		end
		for at = #waiting, 1, -1 do
			local player = waiting[at]
			SoundPlay.tick(player, dt)
			if not SoundPlay.busy(player) then
				table.remove(waiting, at)
			end
		end
		if #waiting == 0 then
			tails[rig.model] = nil
			context.hold(rig.model, false, Sounds.NAME)
		end
	end

	local function stopped(
		live: ApexTrack.Live,
		reason: ApexTrack.EndReason,
		policy: Types.InterruptPolicy
	)
		local play = playOf(live)
		if play == nil then
			return
		end
		live.data[Sounds.NAME] = nil
		local player = play.player
		if reason == "Interrupted" and policy == "Revert" then
			SoundPlay.stop(player)
			return
		end
		SoundPlay.playOut(player, play.speed)
		if SoundPlay.busy(player) then
			local model = live.rig or live.animator
			local waiting = tails[model]
			if waiting == nil then
				waiting = {}
				tails[model] = waiting
			end
			table.insert(waiting :: { SoundPlay.Player }, player)
			context.hold(model, true, Sounds.NAME)
		end
	end

	local function released(rig: Frame.Rig)
		local waiting = tails[rig.model]
		if waiting == nil then
			return
		end
		tails[rig.model] = nil
		for _, player in waiting do
