		{
			name = Sounds.NAME,
			stage = "props",
			began = began,
			stopped = stopped,
			step = function(rig: Frame.Rig, dt: number)
				step(rig, dt)
			end,
			released = released,
		} :: Frame.Extension,
	}
end

