Spaces.REBUILD_INTERVAL = 1

local SLOTS = "spaces.slots"

Spaces.HOME_PART0 = RigState.HOME_PART0
Spaces.HOME_C0 = RigState.HOME_C0

local SEAT_TOLERANCE = 1e-4

export type Topology = {
	read: (motor: any) -> (any?, CFrame),
	repoint: (motor: any, part0: any, c0: CFrame) -> (),
	published: (motor: any) -> (string?, CFrame?),
	publish: (motor: any, part0: string?, c0: CFrame?) -> (),
}

Spaces.PROPERTIES = table.freeze({
	read = function(motor: any): (any?, CFrame)
		return motor.Part0, motor.C0
	end,
	repoint = function(motor: any, part0: any, c0: CFrame)
		motor.Part0 = part0
		motor.C0 = c0
	end,
	published = function(motor: any): (string?, CFrame?)
		local name = motor:GetAttribute(RigState.HOME_PART0)
		local c0 = motor:GetAttribute(RigState.HOME_C0)
		if type(name) == "string" and name ~= "" and typeof(c0) == "CFrame" then
			return name, c0
		end
		return nil, nil
	end,
	publish = function(motor: any, part0: string?, c0: CFrame?)
		motor:SetAttribute(RigState.HOME_PART0, part0)
		motor:SetAttribute(RigState.HOME_C0, c0)
	end,
}) :: Topology

export type Context = {
	rigStates: RigState.Registry,
	hold: (model: any, on: boolean) -> (),
	clock: () -> number,
	warnOnce: (key: string, message: string) -> (),
	server: () -> boolean,
	graphOf: ((model: any) -> JointGraph.Graph?)?,
	topology: (Topology | false)?,
}

type Home = {
	address: string,
	part0: any,
	c0: CFrame,
	published: boolean,
}

export type Driver = {
	pivot: CFrame,
	weight: number,
}

type Shown = {
	target: Types.SpaceTarget,
	value: CFrame,
	pivot: CFrame,
	transform: CFrame,
}

export type Slots = {
	resolve: (slot: string) -> any?,
	label: string,
}

type Runtime = {
	model: any,
	graph: JointGraph.Graph?,
	builtAt: number,
	last: { [string]: Shown },
	claimants: { [string]: { ApexTrack.Live } },
	kept: { [string]: Slots },
	homes: { [any]: Home },
}

type LiveData = {
	claims: { [string]: RigState.Entry },
	targets: { [string]: Types.SpaceTarget },
}

type Plan = {
	address: string,
	joint: Joint.Joint,
	entry: RigState.Entry?,
	target: Types.SpaceTarget,
	drivers: { { live: ApexTrack.Live, state: SpaceSolve.State } },
	follows: { string },
