function Spaces.new(context: Context): Spaces
	local rigStates = context.rigStates
	local runtimes: { [any]: Runtime } = setmetatable({}, { __mode = "k" }) :: any
	local topology: Topology? = if context.topology == nil
		then Spaces.PROPERTIES
		elseif context.topology == false then nil
		else context.topology :: Topology

	local function runtimeOf(model: any): Runtime
		local rt = runtimes[model]
		if rt == nil then
			rt = {
				model = model,
				graph = nil,
				builtAt = -math.huge,
				last = {},
				claimants = {},
				kept = {},
				homes = setmetatable({}, { __mode = "k" }) :: any,
			}
			runtimes[model] = rt
		end
		return rt :: Runtime
	end

	local function build(rt: Runtime): JointGraph.Graph?
		rt.builtAt = context.clock()
		local ok, built = pcall(function(): JointGraph.Graph?
			if context.graphOf ~= nil then
