		local missing = graph == nil
		if graph ~= nil then
			for address in needed do
				if graph.byAddress[address] == nil then
					missing = true
					break
				end
			end
		end
		if missing and context.clock() - rt.builtAt >= Spaces.REBUILD_INTERVAL then
			graph = build(rt)
		end
		return graph
	end

	local function loose(rt: Runtime, address: string): boolean
		local graph = rt.graph
		if graph ~= nil and graph.byAddress[address] ~= nil then
			return false
		end
		return Pivots.unitOf(rt.model, address) ~= nil
	end

	local function homeParentOf(
		rt: Runtime?,
		graph: JointGraph.Graph,
		joint: Joint.Joint
	): Joint.Joint?
		local home = if rt ~= nil then rt.homes[joint.instance] else nil
		if home == nil then
			return graph.parentOf[joint]
		end
		return drivenBy(graph)[home.part0]
	end

	local function slotsFor(rt: Runtime, address: string): Slots?
		local list = rt.claimants[address]
		if list ~= nil and #list > 0 then
			return Spaces.slotsOf(list[#list])
		end
		return rt.kept[address]
	end

	local function frameOnRig(other: any, target: Types.SpaceTarget): (CFrame?, string?)
		local joint = target.joint
		local rt = runtimeOf(other)
		local needed: { [string]: boolean } = {}
		if target.kind == "Joint" and joint ~= nil and not loose(rt, joint) then
			needed[joint] = true
		end
		local graph = graphFor(rt, needed)
		if graph == nil then
			return nil, `the joints of {rigName(other)} cannot be read`
		end
		local rootPart = graph.rootPart
		if target.kind == "RigRoot" then
			if rootPart == nil then
				return nil, `{rigName(other)} has no root part`
			end
			return (rootPart :: any).CFrame, nil
		end
		local followed = if joint ~= nil then graph.byAddress[joint] else nil
		local unit = if followed == nil and joint ~= nil then Pivots.unitOf(other, joint) else nil
		if unit ~= nil then
			local world = Pivots.unitWorld(unit)
			if world ~= nil then
				return world, nil
			end
		end
		if followed == nil then
			return nil, `{rigName(other)} has no joint called '{tostring(joint)}'`
		end
		local chain: { Joint.Joint } = {}
		local at: Joint.Joint? = followed
		while at ~= nil do
			table.insert(chain, at)
			at = graph.parentOf[at]
		end
		local top = chain[#chain]
		local world = if rootPart ~= nil and top.parent == rootPart
			then (rootPart :: any).CFrame
			else Joint.worldCFrameOf(top.parent) or CFrame.identity
		for index = #chain, 1, -1 do
			world = chain[index]:worldCFrame(world)
		end
		return world, nil
	end

	local function unclaim(live: ApexTrack.Live)
		local data: LiveData? = live.data[Spaces.NAME]
		if data == nil then
			return
		end
		local rt = runtimes[live.rig]
		for address in data.claims do
			local list = if rt ~= nil then rt.claimants[address] else nil
			if list ~= nil then
				local index = table.find(list, live)
				if index ~= nil then
					table.remove(list, index)
				end
				if #list == 0 then
					local runtime = rt :: Runtime
					runtime.claimants[address] = nil
					runtime.kept[address] = Spaces.slotsOf(live)
