		if #declared == 0 then
			return
		end
		local state = RigState.get(rigStates, model)
		local rt = runtimeOf(model)
		local policies = Sidecar.policies(live.sidecar)
		local now = context.clock()
		local data: LiveData = live.data[Spaces.NAME] or { claims = {}, targets = {} }
		live.data[Spaces.NAME] = data
		for _, address in declared do
			local expected = stateOf(live, address, live.time).target
			local current = RigState.targetOf(state, address)
			local before = RigState.remember(state, address)
			if not RigState.same(expected, current) then
				if policies.spaceMismatch == "Respect" then
					continue
				end
				RigState.set(state, address, expected, {
					blend = policies.spaceAdoptTime,
					now = now,
				})
			end
			data.claims[address] = before
			data.targets[address] = expected
			local list = rt.claimants[address]
			if list == nil then
				list = {}
				rt.claimants[address] = list
			end
			table.insert(list :: { ApexTrack.Live }, live)
		end
		if RigState.active(state) then
			context.hold(model, true)
		end
	end

	local function restore(
		state: RigState.State,
		address: string,
		before: RigState.Entry,
		blend: number,
		now: number
	)
		RigState.set(state, address, before.target, {
			value = before.value,
			capture = before.capture,
			blend = blend,
			now = now,
		})
	end

	local function stopped(
		live: ApexTrack.Live,
		reason: ApexTrack.EndReason,
		policy: Types.InterruptPolicy
	)
		local data: LiveData? = live.data[Spaces.NAME]
		local model = live.rig
		if data == nil or model == nil then
			return
		end
		local rt = runtimes[model]
		local state = RigState.get(rigStates, model)
		local blend = Sidecar.policies(live.sidecar).spaceAdoptTime
		local now = context.clock()
		local addresses: { string } = {}
		for address in data.claims do
			table.insert(addresses, address)
		end
		table.sort(addresses)
		for _, address in addresses do
			local list = if rt ~= nil then rt.claimants[address] else nil
			if list == nil or list[#list] ~= live then
				continue
			end
			local had = data.targets[address]
			if had == nil or not RigState.same(had, RigState.targetOf(state, address)) then
				continue
			end
			local before = data.claims[address]
			local persist = if Spaces.persists(live.sidecar, address) then "Persist" else nil
			local outcome = ApexTrack.outcome(reason, policy, persist :: any)
			if outcome == "Final" then
				local target, at = Spaces.finalState(live.sidecar, address)
				if target == nil or at == nil then
					restore(state, address, before, blend, now)
				elseif target.kind == "Parent" then
					RigState.set(state, address, RigState.PARENT, { blend = blend, now = now })
				else
					local value = valueOf(live, address, at)
					if target.kind == "World" then
						value = (Movement.carryOf(live) or CFrame.identity) * value
					end
					RigState.set(state, address, target, {
						value = value,
						blend = blend,
						now = now,
					})
				end
			elseif outcome == "Revert" then
				restore(state, address, before, blend, now)
			else
				local current = RigState.targetOf(state, address)
				if current.kind ~= "Parent" then
					RigState.set(state, address, current, { capture = true, now = now })
				end
			end
		end
		unclaim(live)
		if RigState.active(state) then
			context.hold(model, true)
		end
	end

	local function ended(live: ApexTrack.Live)
		unclaim(live)
	end

	local function baseOf(rt: Runtime?, address: string): RigState.Held?
		local list = if rt ~= nil then rt.claimants[address] else nil
		if list == nil then
			return nil
		end
		for index = #list, 1, -1 do
			local data: LiveData? = list[index].data[Spaces.NAME]
			local before = if data ~= nil then data.claims[address] else nil
			if before == nil then
				continue
			elseif before.target.kind == "Parent" then
				return nil
			elseif before.value ~= nil then
				return { target = before.target, value = before.value :: CFrame }
			end
		end
		return nil
	end

	local function publish(state: RigState.State, rt: Runtime?)
		for _, entry in state.joints do
			if entry.capture then
				return
			end
		end
		local held = RigState.held(state)
		for address, entry in state.joints do
			if held[address] == nil and entry.target.kind ~= "Parent" then
				held[address] = baseOf(rt, address) :: any
			end
		end
		local text = RigState.encode(held)
		if text == state.published then
			return
		end
		state.published = text
		pcall(function()
			state.model:SetAttribute(RigState.ATTRIBUTE, text)
		end)
	end

	local function trackStep(rig: Frame.Rig, _dt: number, _catchUp: boolean)
		local model = rig.model
		local state = RigState.peek(rigStates, model)
		if state == nil then
			return
		end
		local rt = runtimes[model]
		if rt ~= nil then
			local addresses: { string } = {}
			for address in rt.claimants do
				table.insert(addresses, address)
			end
			table.sort(addresses)
			for _, address in addresses do
				local list = rt.claimants[address]
				local owner = list[#list]
				for _, live in list do
					local data: LiveData = live.data[Spaces.NAME]
					local now = stateOf(live, address, live.time).target
					local was = data.targets[address]
					if live == owner and was ~= nil and not RigState.same(now, was) then
						RigState.set(state, address, now)
					end
					data.targets[address] = now
				end
			end
		end
		if context.server() then
			publish(state, rt)
		end
		context.hold(model, RigState.active(state) or (rt ~= nil and next(rt.homes) ~= nil))
	end

	local function refuseLoops(
		rt: Runtime,
		graph: JointGraph.Graph,
		plans: { [string]: Plan },
		model: any
	): { [string]: boolean }
		local refused: { [string]: boolean } = {}
		local function depsOf(joint: Joint.Joint): { Joint.Joint }
			local out: { Joint.Joint } = {}
			local parent = homeParentOf(rt, graph, joint)
			if parent ~= nil then
				table.insert(out, parent)
			end
			local address = joint.address
			local plan = plans[address]
			if plan ~= nil and plan.joint == joint and not refused[address] then
				for _, followed in plan.follows do
					local other = graph.byAddress[followed]
					if other ~= nil then
						table.insert(out, other)
					end
				end
			end
			return out
		end
		local addresses: { string } = {}
		for address in plans do
			table.insert(addresses, address)
		end
		table.sort(addresses)
		while true do
			local mark: { [any]: number } = {}
			local stack: { Joint.Joint } = {}
			local cycle: { Joint.Joint }? = nil
			local function visit(joint: Joint.Joint): boolean
				mark[joint] = 1
				table.insert(stack, joint)
				for _, dep in depsOf(joint) do
					if mark[dep] == 1 then
						local from = table.find(stack, dep) :: number
						cycle = table.move(stack, from, #stack, 1, {})
						return true
					elseif mark[dep] == nil and visit(dep) then
						return true
					end
				end
				table.remove(stack)
				mark[joint] = 2
				return false
			end
			for _, address in addresses do
				local plan = plans[address]
				if not refused[address] and mark[plan.joint] == nil and visit(plan.joint) then
					break
				end
			end
			local found = cycle
			if found == nil then
				return refused
			end
			local members: { [string]: SpaceSolve.RigJoint } = {}
			for index, joint in found do
				local following = found[index % #found + 1]
				local hangs = homeParentOf(rt, graph, joint) == following
				members[joint.address] = {
					parent = if hangs then following.address else nil,
					parentOffset = CFrame.identity,
					childOffset = CFrame.identity,
					starting = if hangs then nil else { kind = "Joint", joint = following.address },
				}
				refused[joint.address] = true
			end
			local words = SpaceSolve.check({ root = CFrame.identity, joints = members })
			local names: { string } = {}
			for _, joint in found do
				table.insert(names, joint.address)
			end
			local said = if words ~= nil
				then timeless(words)
				else `{table.concat(names, ", ")} follow each other round in a loop.`
			context.warnOnce(
				`spaces:loop:{said}`,
				`ApexEngine: on {rigName(model)}, {said} Those joints are left to the plain animation until one of them changes space.`
			)
		end
	end

	local function seatOf(rt: Runtime, graph: JointGraph.Graph, plan: Plan): (any?, CFrame?)
		local target = plan.target
		if target.slot ~= nil then
			return nil, nil
		end
		local holder: any? = nil
		if target.kind == "RigRoot" then
			holder = graph.rootPart
		elseif target.kind == "Joint" then
			local followed = graph.byAddress[target.joint or ""]
			if followed ~= nil and rooted(graph, followed) then
				holder = followed.child
			end
		end
		if holder == nil or not isPart(holder) then
			return nil, nil
		end
		local entry = plan.entry
		if entry ~= nil and entry.value ~= nil then
			return holder, entry.value
		elseif entry ~= nil and entry.capture then
			return holder, nil
		end
		local owner: ApexTrack.Live? = nil
		for _, live in rt.claimants[plan.address] or {} do
			if RigState.same(stateOf(live, plan.address, live.time).target :: any, target) then
				owner = live
			end
		end
		if owner == nil then
			return holder, nil
		end
		return holder, valueOf(owner, plan.address, segmentStart(owner, plan.address))
	end

	local function place(
		rt: Runtime,
		graph: JointGraph.Graph,
		joint: Joint.Joint,
		holder: any?,
		seat: CFrame?,
		model: any
	): any?
		local seam = topology :: Topology
		local motor = joint.instance
		local read, part0, c0 = pcall(seam.read, motor)
		if not read then
			return joint.parent
		end
		local home = rt.homes[motor]
		if home == nil then
			local ok, name, homeC0 = pcall(seam.published, motor)
			if ok and name ~= nil and homeC0 ~= nil then
				local part = partNamed(graph, model, name)
				if part ~= nil and (part ~= part0 or c0 ~= homeC0) then
					home = {
						address = joint.address,
						part0 = part,
						c0 = homeC0,
						published = true,
					}
					rt.homes[motor] = home
				end
			end
		end
		local homePart = if home ~= nil then home.part0 else part0
		local onto = holder
		if onto == homePart or (seat == nil and part0 ~= onto) then
			onto = nil
		end

		local ok, problem = pcall(function()
			if onto ~= nil then
				local kept: Home = home
					or { address = joint.address, part0 = part0, c0 = c0, published = false }
				rt.homes[motor] = kept
				if seat ~= nil and (part0 ~= onto or not sameSeat(c0, seat)) then
					seam.repoint(motor, onto, seat)
					kept.published = false
				end
				if not kept.published then
					seam.publish(motor, kept.part0.Name, kept.c0)
					kept.published = true
				end
			elseif home ~= nil then
				if part0 ~= home.part0 or c0 ~= home.c0 then
					seam.repoint(motor, home.part0, home.c0)
				end
				rt.homes[motor] = nil
				seam.publish(motor, nil, nil)
			end
		end)
		if not ok then
			context.warnOnce(
				`spaces:repoint:{rigName(model)}:{joint.address}`,
				`ApexEngine: {joint.address} on {rigName(model)} could not be moved to the part that holds it ({problem}); it is kept in its space where it hangs.`
			)
		end
		local readBack, hung = pcall(seam.read, motor)
		return if readBack then hung else part0
	end

	local function settle(
		rt: Runtime,
		graph: JointGraph.Graph,
		plans: { [string]: Plan },
		refused: { [string]: boolean },
		checked: { [string]: boolean },
		model: any
	): JointGraph.Graph?
		local addresses: { string } = {}
		for address in plans do
			table.insert(addresses, address)
		end
		for address in checked do
			if plans[address] == nil then
				table.insert(addresses, address)
			end
		end
		table.sort(addresses)
		local hung: { [string]: any } = {}
		local stale = false
		for _, address in addresses do
			local joint = graph.byAddress[address]
			if joint == nil or joint.kind ~= "Motor6D" then
				continue
			end
			local plan = plans[address]
			local holder, seat = nil, nil
			if plan ~= nil and plan.joint == joint and not refused[address] then
				holder, seat = seatOf(rt, graph, plan)
			end
			local part0 = place(rt, graph, joint, holder, seat, model)
			hung[address] = part0
			if part0 ~= joint.parent then
				stale = true
			end
		end
		if not stale then
			return graph
		end
		local rebuilt = build(rt)
		if rebuilt == nil then
			return nil
		end
		for address, part0 in hung do
			local joint = rebuilt.byAddress[address]
			if joint ~= nil and joint.parent ~= part0 then
				context.warnOnce(
					`spaces:stale:{rigName(model)}`,
					`ApexEngine: the joints of {rigName(model)} were read again after '{address}' moved to another part, but still show it where it was, so what follows it may be drawn out of place.`
				)
			end
		end
		for address, plan in plans do
			local joint = rebuilt.byAddress[address]
			if joint == nil then
				plans[address] = nil
			else
				plan.joint = joint
			end
		end
		return rebuilt
	end

	local function writeStep(rig: Frame.Rig, _dt: number, _catchUp: boolean)
		local model = rig.model
		local state = RigState.peek(rigStates, model)
		local rt = runtimes[model]

		local active: { [string]: boolean } = {}
		if state ~= nil then
			for address in state.joints do
				active[address] = true
			end
		end
		if rt ~= nil then
			for address, list in rt.claimants do
				if active[address] then
					continue
				end
				for _, live in list do
					if live.weight > 0 and stateOf(live, address, live.time).from ~= nil then
						active[address] = true
						break
					end
				end
			end
		end
		local checked: { [string]: boolean } = {}
		if topology ~= nil and rt ~= nil then
			for _, home in rt.homes do
				checked[home.address] = true
			end
			for address in rt.claimants do
				checked[address] = true
			end
		end
		if next(active) == nil and next(checked) == nil then
			if rt ~= nil then
				table.clear(rt.last)
			end
			return
		end
		local runtime = rt or runtimeOf(model)
		for address in runtime.last do
			if not active[address] then
				runtime.last[address] = nil
			end
		end

		local needed: { [string]: boolean } = table.clone(active)
		local plans: { [string]: Plan } = {}
		local candidates: { Plan } = {}
		for address in active do
			local entry = if state ~= nil then state.joints[address] else nil
			local target = if entry ~= nil then entry.target else RigState.PARENT
			local drivers = {}
			local follows: { string } = {}
			local function follow(space: Types.SpaceTarget?)
				if
					space ~= nil
					and space.kind == "Joint"
					and space.slot == nil
					and space.joint ~= nil
				then
					table.insert(follows, space.joint)
					if not Pivots.moves(rig, space.joint) and not loose(runtime, space.joint) then
						needed[space.joint] = true
					end
				end
			end
			follow(target)
			if entry ~= nil and entry.transition ~= nil then
				follow(entry.transition.from)
			end
			for _, live in runtime.claimants[address] or {} do
				if live.weight <= 0 then
					continue
				end
				local st = stateOf(live, address, live.time)
				local drives = if target.kind == "Parent"
					then st.target.kind == "Parent" and st.from ~= nil
					else RigState.same(st.target :: any, target)
				if drives then
					table.insert(drivers, { live = live, state = st })
					follow(st.from :: any)
				end
			end
			table.insert(candidates, {
				address = address,
				joint = nil :: any,
				entry = entry,
				target = target,
				drivers = drivers,
				follows = follows,
			})
		end
		local found = graphFor(runtime, needed)
		if found == nil then
			return
		end
		local graph = found :: JointGraph.Graph
		for _, plan in candidates do
			local joint = graph.byAddress[plan.address]
			if joint == nil then
				context.warnOnce(
					`spaces:missing:{plan.address}`,
					`ApexEngine: {rigName(model)} has no joint called '{plan.address}', so the space it should be in cannot be kept.`
				)
				continue
			end
			plan.joint = joint
			plans[plan.address] = plan
		end

		local refused = refuseLoops(runtime, graph, plans, model)

		if topology ~= nil then
			local settled = settle(runtime, graph, plans, refused, checked, model)
			if settled == nil then
				return
			end
			graph = settled :: JointGraph.Graph
		end
		if next(plans) == nil then
			return
		end

		local now = context.clock()
		local rootPart = graph.rootPart
		local root = if rootPart ~= nil then rootPart.CFrame else CFrame.identity
		local worlds: { [any]: CFrame } = {}
		local worldOf: (joint: Joint.Joint) -> CFrame

		local function slotFrame(address: string, target: Types.SpaceTarget): CFrame?
			local slot = target.slot :: string
			local slots = slotsFor(runtime, address)
			if slots == nil then
				context.warnOnce(
					`spaces:slot:{slot}`,
					`ApexEngine: a joint on {rigName(model)} follows the rig in slot '{slot}', which only a scene can place; it is left to the plain animation.`
				)
				return nil
			end
			local other = slots.resolve(slot)
			if other == nil then
				context.warnOnce(
					`spaces:unbound:{rigName(model)}:{address}:{slot}`,
					`ApexEngine: {address} on {rigName(model)} follows the rig in slot '{slot}' of {slots.label}, but no rig plays that slot now; it is left to the plain animation.`
				)
				return nil
			end
			local frame, problem = frameOnRig(other, target)
			if frame == nil then
				local followed = if target.kind == "RigRoot"
					then "the root"
					else `'{tostring(target.joint)}'`
				context.warnOnce(
					`spaces:slotjoint:{rigName(model)}:{address}:{slot}:{tostring(target.joint)}`,
					`ApexEngine: {address} on {rigName(model)} follows {followed} of the rig in slot '{slot}' of {slots.label}, but {problem}; it is left to the plain animation.`
				)
			end
			return frame
		end

		local function frameOf(
			target: Types.SpaceTarget,
			restPivot: CFrame,
			address: string,
			live: ApexTrack.Live?
		): CFrame?
			local kind = target.kind
			if kind == "Parent" then
				return restPivot
			elseif target.slot ~= nil then
				return slotFrame(address, target)
			elseif kind == "World" then
				return if live ~= nil
					then Movement.carryOf(live) or CFrame.identity
					else CFrame.identity
			elseif kind == "RigRoot" then
				return root
			end
			local followed = if target.joint ~= nil then graph.byAddress[target.joint] else nil
			if followed == nil and Pivots.moves(rig, target.joint :: string) then
				return Pivots.partWorld(rig, target.joint :: string)
			end
			local unit = if followed == nil and target.joint ~= nil
				then Pivots.unitOf(model, target.joint :: string)
				else nil
			if unit ~= nil then
				return Pivots.unitWorld(unit)
			elseif followed == nil then
				context.warnOnce(
					`spaces:missing:{target.joint}`,
					`ApexEngine: {rigName(model)} has no joint called '{tostring(target.joint)}' to follow, so the joints following it are left to the plain animation.`
				)
				return nil
			end
			return worldOf(followed)
		end

		local function capture(
			target: Types.SpaceTarget,
			frame: CFrame,
			shown: Shown?,
			animatorPivot: CFrame
		): CFrame
			if shown ~= nil and RigState.same(shown.target, target) then
				return shown.value
			elseif shown ~= nil then
				return SpaceSolve.hold(shown.pivot, frame)
			end
			return SpaceSolve.hold(animatorPivot, frame)
		end

		local function partWorld(part: any): CFrame
			if part == rootPart then
				return root
			end
			local driver = drivenBy(graph)[part]
			if driver ~= nil then
				return worldOf(driver)
			end
			return Joint.worldCFrameOf(part) or CFrame.identity
		end

		local function solveJoint(plan: Plan, parentWorld: CFrame, rest: Joint.Rest): CFrame?
			local address = plan.address
			local joint = plan.joint
			local restPivot = parentWorld * rest.parentOffset
			local home = runtime.homes[joint.instance]
			local homePivot = if home ~= nil then partWorld(home.part0) * home.c0 else restPivot
			local written = joint:getTransform()
			local shown = runtime.last[address]
			local animator = if shown ~= nil and shown.transform == written
				then CFrame.identity
				else written
			local animatorPivot = homePivot * animator
			local target = plan.target
			local entry = plan.entry
			local frame = frameOf(target, homePivot, address)

			local function plain(): CFrame?
				if home == nil then
					return nil
				end
				local transform = restPivot:Inverse() * animatorPivot
				joint:setTransform(transform)
				runtime.last[address] = {
					target = target,
					value = CFrame.identity,
					pivot = animatorPivot,
					transform = joint:getTransform(),
				}
				return transform
			end
			if frame == nil then
				return plain()
			end

			local bottom = animatorPivot
			if entry ~= nil and target.kind ~= "Parent" then
				if entry.capture then
					entry.value = capture(target, frame, shown, animatorPivot)
					entry.capture = nil
				end
				if entry.value ~= nil then
					bottom = frame * (entry.value :: CFrame)
				end
			end

			local drivers: { Driver } = {}
			for _, driver in plan.drivers do
				local live = driver.live
				local st = driver.state
				local own = if target.kind == "World"
					then frameOf(target, homePivot, address, live) :: CFrame
					else frame
				local pivot = own * valueOf(live, address, live.time)
				local from = st.from
				if from ~= nil then
					local fromFrame = frameOf(from :: any, homePivot, address, live)
					if fromFrame ~= nil then
						local held = fromFrame
							* valueOf(live, address, (st.since :: number) - SpaceSolve.BEFORE)
						pivot = held:Lerp(pivot, st.weight)
					elseif (from :: any).slot ~= nil then
						return plain()
					end
				end
				table.insert(drivers, { pivot = pivot, weight = live.weight })
			end
			local pose = Spaces.blend(bottom, drivers)

			local transition = if entry ~= nil then entry.transition else nil
			if transition ~= nil then
				local eased = SpaceSolve.stateAt({
					{
						t = transition.start,
						target = target :: any,
						blend = transition.duration,
					},
				}, transition.from :: any, now).weight
				if eased < 1 then
					local fromFrame = frameOf(transition.from, homePivot, address)
					if transition.fromCapture and fromFrame ~= nil then
						transition.fromValue =
							capture(transition.from, fromFrame, shown, animatorPivot)
						transition.fromCapture = nil
					end
					local fromPivot: CFrame? = nil
					if transition.fromValue == nil and transition.from.kind == "Parent" then
						fromPivot = animatorPivot
					elseif fromFrame ~= nil and transition.fromValue ~= nil then
						fromPivot = fromFrame * (transition.fromValue :: CFrame)
					end
					if fromPivot ~= nil then
						pose = fromPivot:Lerp(pose, eased)
					end
				elseif state ~= nil and entry ~= nil then
					entry.transition = nil
					if target.kind == "Parent" and state.joints[address] == entry then
						state.joints[address] = nil
					end
				end
			end

			local transform = restPivot:Inverse() * pose
			joint:setTransform(transform)
			runtime.last[address] = {
				target = target,
				value = frame:Inverse() * pose,
				pivot = pose,
				transform = joint:getTransform(),
			}
			return transform
		end

		local function parentWorldOf(joint: Joint.Joint): CFrame
			local parent = graph.parentOf[joint]
			if parent ~= nil then
				return worldOf(parent)
			elseif joint.parent == rootPart then
				return root
			end
			return Joint.worldCFrameOf(joint.parent) or CFrame.identity
		end

		worldOf = function(joint: Joint.Joint): CFrame
			local known = worlds[joint]
			if known ~= nil then
				return known
			end
			local parentWorld = parentWorldOf(joint)
			local rest = joint:getRest()
			local plan = plans[joint.address]
			local transform: CFrame? = nil
			if plan ~= nil and plan.joint == joint and not refused[joint.address] then
				transform = solveJoint(plan, parentWorld, rest)
			end
			local world = parentWorld
				* rest.parentOffset
				* (transform or joint:getTransform())
				* rest.childOffset:Inverse()
			worlds[joint] = world
			return world
		end

		local order: { string } = {}
		for address in plans do
			table.insert(order, address)
		end
		table.sort(order)
		for _, address in order do
			if not refused[address] then
				worldOf(plans[address].joint)
			end
		end
	end

	local function readsOf(rig: Frame.Rig): { any }?
		local model = rig.model
		local rt = runtimes[model]
		if rt == nil then
			return nil
		end
		local state = RigState.peek(rigStates, model)
		local out: { any }? = nil
		local seen: { [any]: boolean } = {}
		local function add(slots: Slots, space: Types.SpaceTarget?)
			if space == nil or space.slot == nil then
				return
			end
			local other = slots.resolve(space.slot :: string)
			if other ~= nil and other ~= model and not seen[other] then
				seen[other] = true
				out = out or {}
				table.insert(out :: { any }, other)
			end
		end
		local function scan(address: string)
			local slots = slotsFor(rt, address)
			if slots == nil then
				return
			end
			local entry = if state ~= nil then state.joints[address] else nil
			if entry ~= nil then
				add(slots, entry.target)
				if entry.transition ~= nil then
					add(slots, entry.transition.from)
				end
			end
			for _, live in rt.claimants[address] or {} do
				if live.weight > 0 then
					local st = stateOf(live, address, live.time)
					add(slots, st.target :: any)
					add(slots, st.from :: any)
				end
			end
		end
		for address in rt.claimants do
			scan(address)
		end
		for address in rt.kept do
			if rt.claimants[address] == nil then
				scan(address)
			end
		end
		return out
	end

	local function released(rig: Frame.Rig)
		runtimes[rig.model] = nil
	end

	rigStates.check = function(
		state: RigState.State,
		joint: string,
		target: Types.SpaceTarget
	): string?
		local rt = runtimeOf(state.model)
		local needed: { [string]: boolean } = { [joint] = true }
		if target.kind == "Joint" and target.joint ~= nil then
			needed[target.joint] = true
		end
		local graph = graphFor(rt, needed)
		if graph == nil then
			return nil
		end
		local name = rigName(state.model)
		if graph.byAddress[joint] == nil then
			return `{name} has no joint called '{joint}'.`
		end
		if target.kind == "Joint" and graph.byAddress[target.joint or ""] == nil then
			return `{name} has no joint called '{tostring(target.joint)}' to follow.`
		end
		local joints: { [string]: SpaceSolve.RigJoint } = {}
		for address, item in graph.byAddress do
			local parent = homeParentOf(rt, graph, item)
			local space = if address == joint then target else RigState.targetOf(state, address)
			if space.kind == "Joint" and graph.byAddress[space.joint or ""] == nil then
				space = RigState.PARENT
			end
			joints[address] = {
				parent = if parent ~= nil then parent.address else nil,
				parentOffset = CFrame.identity,
				childOffset = CFrame.identity,
				starting = space :: any,
			}
		end
		local problem = SpaceSolve.check({ root = CFrame.identity, joints = joints })
		return if problem ~= nil then timeless(problem) else nil
	end

	return {
		track = {
			name = Spaces.NAME,
			stage = "spaces",
			began = began,
			stopped = stopped,
			ended = ended,
			step = trackStep,
			released = released,
		},
		write = {
			name = "space compensation",
			stage = "spaces",
			cosmetic = true,
			step = writeStep,
			reads = readsOf,
		},
	}
end

function Spaces.extensions(context: Context): { Frame.Extension }
	local made = Spaces.new(context)
	return { made.track, made.write }
end

return Spaces
