    ["UhhhhhhReanim/System/runtime/steve110/main/apex_engine/Runtime/States.lua"] = [=====[
--!strict

local ApexTrack = require(script.Parent.ApexTrack)
local Frame = require(script.Parent.Frame)
local Signal = require(script.Parent.Parent.Signal)
local Types = require(script.Parent.Parent.Core.Types)
local StateEval = require(script.Parent.Parent.Shared.StateEval)

local States = {}

States.NAME = "states"

States.ENDED = "ended"
States.INTERRUPTED = "interrupted"

type Play = {
	active: boolean,
	time: number?,
	speed: number,
	at: number,
	open: { [number]: number },
	values: { [number]: any },
	payloads: { [number]: any },
	options: StateEval.EvalOptions,
}

local function statesOf(live: ApexTrack.Live): { StateEval.StateTrack }
	return (live.sidecar.states or {}) :: any
end

local function playOf(live: ApexTrack.Live): Play?
	return live.data[States.NAME]
end

local function fireSpan(live: ApexTrack.Live, name: string, ...: any)
	local signal = live.spanSignals[name]
	if signal ~= nil then
		Signal.fire(signal, ...)
	end
end

local function report(
	live: ApexTrack.Live,
	play: Play,
	index: number,
	state: StateEval.StateTrack,
	value: any,
	payload: any
)
	local old, oldPayload = play.values[index], play.payloads[index]
	if value == old and payload == oldPayload then
		return
	end
	play.values[index] = value
	play.payloads[index] = payload
	local signal = live.stateSignals[state.name]
	if signal ~= nil then
		Signal.fire(signal, value, old, payload)
	end
end

local function close(
	live: ApexTrack.Live,
	play: Play,
	index: number,
	state: StateEval.StateTrack,
	reason: string
)
	local open = play.open[index]
	if open == nil then
		return
	end
	play.open[index] = nil
	local span = (state.spans :: { StateEval.Span })[open]
	fireSpan(live, state.name, false, span.payload, reason)
end

local function settle(
	live: ApexTrack.Live,
	play: Play,
	index: number,
	state: StateEval.StateTrack,
	t: number
)
	local now = StateEval.spanAt(state, t)
	if now == play.open[index] then
		return
	end
	close(live, play, index, state, States.ENDED)
	if now ~= nil then
		play.open[index] = now
		local span = (state.spans :: { StateEval.Span })[now]
		fireSpan(live, state.name, true, span.payload, nil)
	end
end

local function sweep(
	live: ApexTrack.Live,
	play: Play,
	index: number,
	state: StateEval.StateTrack,
	from: number,
	to: number,
	reverse: boolean
)
	for _, edge in StateEval.spanEdges(state, from, to, reverse) do
		if edge.began then
			close(live, play, index, state, States.ENDED)
			play.open[index] = edge.index
			fireSpan(live, state.name, true, edge.payload, nil)
		elseif play.open[index] == edge.index then
			play.open[index] = nil
			fireSpan(live, state.name, false, edge.payload, States.ENDED)
		end
	end
	settle(live, play, index, state, to)
end

local function timeNow(live: ApexTrack.Live): number
	local ok, time = pcall(function()
		return live.track.TimePosition
	end)
	return if ok and type(time) == "number" then time else live.time
end

function States.read(live: ApexTrack.Live, name: string): any
	for _, state in statesOf(live) do
		if state.name == name then
			local play = playOf(live)
			if play == nil or not play.active or live.phase ~= "Playing" then
				return StateEval.idleValue(state)
			end
			return (StateEval.valueAt(state, timeNow(live), play.options))
		end
	end
	return nil
end

function States.began(live: ApexTrack.Live)
	local states = statesOf(live)
	if #states == 0 then
		live.data[States.NAME] = nil
		return
	end
	local play: Play = {
		active = true,
		time = nil,
		speed = live.speed,
		at = live.seenClock,
		open = {},
		values = {},
		payloads = {},
		options = { presets = live.sidecar.presets :: any, fps = live.sidecar.fps },
	}
	for index, state in states do
		play.values[index] = StateEval.idleValue(state)
	end
	live.data[States.NAME] = play
	if live.readState == nil then
		live.readState = function(name: string): any
			return States.read(live, name)
		end
	end
end

local function advance(live: ApexTrack.Live, play: Play, dt: number)
	local to = live.time
	local travel = StateEval.travel({
		from = play.time,
		to = to,
		speed = live.speed,
		lastSpeed = play.speed,
		dt = dt,
		looped = live.looped,
		length = live.sidecar.length,
		late = live.late,
	})
	local reverse = travel == "Backward"
	local from = play.time or (if reverse then math.huge else -math.huge)
	for index, state in statesOf(live) do
		if state.kind == "Span" then
			if travel == "Jump" then
				settle(live, play, index, state, to)
			else
				sweep(live, play, index, state, from, to, reverse)
			end
		end
		local value, payload = StateEval.valueAt(state, to, play.options)
		report(live, play, index, state, value, payload)
	end
	play.time = to
	play.speed = live.speed
	play.at = live.seenClock
end

function States.step(rig: Frame.Rig, dt: number, _catchUp: boolean)
	for _, live in rig.lives do
		local play = playOf(live)
		if play ~= nil and play.active and live.phase == "Playing" then
			advance(live, play, dt)
		end
	end
end

function States.stopped(
	live: ApexTrack.Live,
	reason: ApexTrack.EndReason,
	_policy: Types.InterruptPolicy
)
	local play = playOf(live)
	if play == nil or not play.active then
		return
	end
	play.active = false
	local states = statesOf(live)
	local why = States.INTERRUPTED
	if reason == "Completed" then
		why = States.ENDED
		local reverse = play.speed < 0
		local length = live.sidecar.length
		local travel = StateEval.travel({
			from = play.time,
			to = if reverse then 0 else length,
			speed = live.seenSpeed,
			lastSpeed = play.speed,
			dt = live.stoppedClock - play.at,
			looped = false,
			length = length,
			late = live.late,
		})
		if travel ~= "Jump" then
			local from = play.time or (if reverse then math.huge else -math.huge)
			local to = if reverse then -math.huge else math.huge
			for index, state in states do
				if state.kind == "Span" then
					sweep(live, play, index, state, from, to, reverse)
				end
			end
		end
	end
	for index, state in states do
		if state.kind == "Span" then
			close(live, play, index, state, why)
		end
		report(live, play, index, state, StateEval.idleValue(state), nil)
	end
end

States.extension = {
	name = States.NAME,
	stage = "states",
	cosmetic = false,
	began = States.began,
	stopped = States.stopped,
	step = States.step,
} :: Frame.Extension

return States
