--!strict

local AnchorMath = require(script.Parent.Shared.AnchorMath)
local CameraEval = require(script.Parent.Shared.CameraEval)
local ScreenDraw = require(script.Parent.Shared.ScreenDraw)
local ScreenEval = require(script.Parent.Shared.ScreenEval)
local SlotCheck = require(script.Parent.Shared.SlotCheck)
local ApexTrack = require(script.Parent.Runtime.ApexTrack)
local Movement = require(script.Parent.Runtime.Movement)
local Pivots = require(script.Parent.Runtime.Pivots)
local Registry = require(script.Parent.Runtime.Registry)
local Spaces = require(script.Parent.Runtime.Spaces)
local SceneSidecar = require(script.Parent.Core.SceneSidecar)
local Sidecar = require(script.Parent.Core.Sidecar)
local Signal = require(script.Parent.Signal)

local Scene = {}

Scene.LOCKSTEP_TOLERANCE = 0.05

Scene.OPTIONS = table.freeze({ "anchor", "camera", "screen", "screenOrder", "look" })

Scene.SCREEN_NAME = "ApexScreen"

export type Phase = "Idle" | "Playing" | "Stopping"

export type Context = {
	loadTrack: (
		animator: any,
		sidecar: Sidecar.Sidecar,
		label: string,
		id: number | string
	) -> ApexTrack.Live,
	studio: (() -> boolean)?,
	jointsOf: (model: any) -> { [string]: any },
	workspace: () -> any,
	playerGui: (() -> any?)?,
	add: (scene: Scene) -> (),
	remove: (scene: Scene) -> (),
	warn: (key: string, message: string) -> (),
}

export type SlotPlay = {
	name: string,
	model: any,
	rootPart: any,
	live: ApexTrack.Live,
	length: number,
	looped: boolean,
}

export type TakePlay = {
	sidecar: SceneSidecar.SceneSidecar,
	byName: { [string]: SlotPlay },
	slots: { SlotPlay },
	start: number,
}

export type Overlay = {
	gui: any,
	canvas: ScreenDraw.Canvas,
	look: ScreenEval.Look,
}

export type Scene = {
	sidecar: SceneSidecar.SceneSidecar,
	movie: SceneSidecar.SceneSidecar,
	takes: { TakePlay },
	current: number,
	length: number,
	label: string,
	context: Context,
	byName: { [string]: SlotPlay },
	slots: { SlotPlay },
	override: () -> AnchorMath.Override?,
	camera: any?,
	borrowed: any?,
	screen: boolean,
	screenOrder: number,
	look: boolean,
	overlay: Overlay?,
	phase: Phase,
	time: number,
	speed: number,
	resolved: AnchorMath.Resolved?,
	stopped: Signal.Signal,
	ended: Signal.Signal,
	destroyed: boolean,
	handle: any?,
}

export type Lockstep = {
	time: number,
	length: number,
	looped: boolean,
	playing: boolean,
}

function Scene.corrections(
	time: number,
	slots: { Lockstep },
	tolerance: number?
): { [number]: number }
	local limit = tolerance or Scene.LOCKSTEP_TOLERANCE
	local out: { [number]: number } = {}
	for index, slot in slots do
		if not slot.playing then
			continue
		end
		local expected: number
		local drift: number
		if slot.looped and slot.length > 0 then
			expected = time % slot.length
			drift = math.abs(slot.time - expected)
			drift = math.min(drift, slot.length - drift)
		else
			if time >= slot.length then
				continue
			end
			expected = math.max(time, 0)
			drift = math.abs(slot.time - expected)
		end
		if drift > limit then
			out[index] = expected
		end
	end
	return out
end

local function nameOf(instance: any): string
	local ok, name = pcall(function()
		return instance.Name
	end)
	return if ok then tostring(name) else "a rig"
end

local function isA(value: any, class: string): boolean
	local kind = typeof(value)
	if kind ~= "Instance" and kind ~= "table" then
		return false
	end
	local ok, yes = pcall(function()
		return value:IsA(class)
	end)
	return ok and yes == true
end

local function describe(value: any): string
	local ok, className = pcall(function()
		return value.ClassName
	end)
	if ok and type(className) == "string" then
		return `a {className}`
	end
	return `a {typeof(value)}`
end

local function listOf(names: { string }): string
	local quoted: { string } = {}
	for _, name in names do
		table.insert(quoted, `'{name}'`)
	end
	if #quoted <= 1 then
		return quoted[1] or "none"
	end
	local last = table.remove(quoted) :: string
	return `{table.concat(quoted, ", ")} and {last}`
end

function Scene.worldOf(instance: any): CFrame?
	local ok, cframe = pcall(function(): CFrame?
		if isA(instance, "BasePart") then
			return instance.CFrame
		elseif isA(instance, "Bone") then
			return instance.TransformedWorldCFrame
		elseif isA(instance, "Attachment") then
			return instance.WorldCFrame
		elseif isA(instance, "Model") then
			return instance:GetPivot()
		end
		return nil
	end)
	return if ok then cframe else nil
end

function Scene.findPart(root: any, path: string): CFrame?
	local at = root
	for name in string.gmatch(path, "[^/]+") do
		local ok, child = pcall(function()
			return at:FindFirstChild(name)
		end)
		if not ok or child == nil then
			return nil
		end
		at = child
	end
	if at == root then
		return nil
	end
	return Scene.worldOf(at)
end

function Scene.overrideOf(
	anchor: any,
	slotNames: { string }
): ((() -> AnchorMath.Override?)?, string?)
	if anchor == nil then
		return function()
			return nil
		end, nil
	end
	local kind = typeof(anchor)
	if kind == "CFrame" then
		local cframe: CFrame = anchor
		return function()
			return { cframe = cframe }
		end, nil
	elseif kind == "string" then
		if table.find(slotNames, anchor) == nil then
			return nil,
				`the anchor '{anchor}' is not one of the scene's slots (they are {listOf(slotNames)}). Pass a slot's name, a CFrame, or a part.`
		end
		local slot: string = anchor
		return function()
			return { slot = slot }
		end, nil
	elseif Scene.worldOf(anchor) ~= nil then
		return function()
			local cframe = Scene.worldOf(anchor)
			return if cframe ~= nil then { cframe = cframe } else nil
		end,
			nil
	end
	return nil,
		`the anchor must be a CFrame, a part, a model, an attachment or a slot's name, not {describe(
			anchor
		)}.`
end

local borrows: { [any]: { count: number, cameraType: any, fov: number? } } = setmetatable(
	{},
	{ __mode = "k" }
) :: any

function Scene.borrowCamera(camera: any)
	local entry = borrows[camera]
	if entry == nil then
		local cameraType, fov = nil, nil
		pcall(function()
			cameraType = camera.CameraType
			fov = camera.FieldOfView
		end)
		entry = { count = 0, cameraType = cameraType, fov = fov }
		borrows[camera] = entry
		pcall(function()
			camera.CameraType = Enum.CameraType.Scriptable
		end)
	end
	local held = entry :: { count: number, cameraType: any, fov: number? }
	held.count += 1
end

function Scene.keepCamera(camera: any)
	local entry = borrows[camera]
	if entry == nil then
		return
	end
	pcall(function()
		local cameraType = camera.CameraType
		if cameraType ~= Enum.CameraType.Scriptable then
			entry.cameraType = cameraType
			camera.CameraType = Enum.CameraType.Scriptable
		end
	end)
end

function Scene.releaseCamera(camera: any)
	local entry = borrows[camera]
	if entry == nil then
		return
	end
	entry.count -= 1
	if entry.count > 0 then
		return
	end
	borrows[camera] = nil
	pcall(function()
		if entry.fov ~= nil then
			camera.FieldOfView = entry.fov
		end
		if entry.cameraType ~= nil then
			camera.CameraType = entry.cameraType
		end
	end)
end

function Scene.borrowsOf(camera: any): number
	local entry = borrows[camera]
	return if entry ~= nil then entry.count else 0
end

local function placeTarget(scene: Scene, target: any): CFrame?
	local slot = scene.byName[target.slot]
	if slot == nil then
		return nil
	end
	if target.kind == "RigRoot" then
		return Scene.worldOf(slot.rootPart)
	end
	local joint = target.joint
	if joint == nil then
		return nil
	end
	for _, instance in slot.model:GetDescendants() do
		if instance.Name == joint and (isA(instance, "BasePart") or isA(instance, "Bone")) then
			return Scene.worldOf(instance)
		end
	end
	local unit = Pivots.unitOf(slot.model, joint)
	return if unit ~= nil then Pivots.unitWorld(unit) else nil
end

local function stepCamera(scene: Scene)
	local camera = scene.borrowed
	local track = scene.sidecar.camera
	local resolved = scene.resolved
	if camera == nil or track == nil or resolved == nil or not CameraEval.hasKeys(track :: any) then
		return
	end
	Scene.keepCamera(camera)
	local t = math.clamp(scene.time, 0, SceneSidecar.endOf(scene.sidecar))
	local cframe, fov, problem = CameraEval.evaluate(track :: any, t, {
		origin = resolved.origin,
		resolve = function(target)
			return placeTarget(scene, target)
		end,
		presets = scene.sidecar.presets,
		fps = scene.sidecar.fps,
	})
	pcall(function()
		camera.FieldOfView = fov
	end)
	if cframe == nil then
		scene.context.warn(
			`scene:{scene.label}:camera`,
			`ApexEngine: the camera of {scene.label} is held where it is. {problem}`
		)
		return
	end
	pcall(function()
		camera.CFrame = cframe
	end)
end

local FALLBACK_SIZE = Vector2.new(1280, 720)

local function screenSize(scene: Scene, gui: any): Vector2
	local ok, size = pcall(function()
		return gui.AbsoluteSize
	end)
	if ok and typeof(size) == "Vector2" and size.Y > 0 then
		return size
	end
	local camera = scene.camera
	ok, size = pcall(function()
		return camera.ViewportSize
	end)
	if ok and typeof(size) == "Vector2" and size.Y > 0 then
		return size
	end
	return FALLBACK_SIZE
end

local function stepScreen(scene: Scene)
	local clips = scene.sidecar.screen
	if not scene.screen or clips == nil or #clips == 0 then
		return
	end
	local overlay = scene.overlay
	if overlay == nil then
		local find = scene.context.playerGui
		local parent = if find ~= nil then find() else nil
		if parent == nil then
			return
		end
		local gui = ScreenDraw.gui(Scene.SCREEN_NAME, scene.screenOrder)
		local made: Overlay = {
			gui = gui,
			canvas = ScreenDraw.new(gui),
			look = ScreenEval.blank(),
		}
		gui.Parent = parent
		scene.overlay = made
		overlay = made
	end
	local shown = overlay :: Overlay
	local look = ScreenEval.at(clips :: any, scene.time, shown.look)
	ScreenDraw.draw(shown.canvas, look, screenSize(scene, shown.gui))
end

local function dropScreen(scene: Scene)
	local overlay = scene.overlay
	scene.overlay = nil
	if overlay ~= nil then
		ScreenDraw.destroy(overlay.canvas)
		pcall(function()
			overlay.gui:Destroy()
		end)
	end
end

local function giveCameraBack(scene: Scene)
	local camera = scene.borrowed
	scene.borrowed = nil
	if camera ~= nil then
		Scene.releaseCamera(camera)
	end
end

local function animatorOf(model: any, slot: string): (any?, string?)
	local holder = model:FindFirstChildOfClass("Humanoid")
		or model:FindFirstChildOfClass("AnimationController")
	if holder == nil then
		return nil,
			`{nameOf(model)} has no Humanoid or AnimationController to play the slot '{slot}' on.`
	end
	local animator = holder:FindFirstChildOfClass("Animator")
	if animator == nil then
		return nil,
			`{nameOf(holder)} of {nameOf(model)} has no Animator. Add one under it (on the server, so the animation replicates).`
	end
	return animator, nil
end

local function takeLabel(
	takes: { SceneSidecar.SceneSidecar },
	take: SceneSidecar.SceneSidecar,
	label: string
): string
	return if #takes > 1 then `the take '{take.name}' of {label}` else label
end

local function bind(
	takes: { SceneSidecar.SceneSidecar },
	bindings: any,
	names: { string },
	label: string,
	jointsOf: (model: any) -> { [string]: any }
): ({ [string]: any }?, string?)
	local prefix = "ApexEngine.LoadScene"
	if type(bindings) ~= "table" then
		return nil,
			`{prefix} needs the rigs to play {label} as its second argument - a table of slot name to character, like \{ {names[1]} = character } - not a {typeof(
				bindings
			)}.`
	end
	for key in bindings do
		if type(key) ~= "string" or table.find(names, key) == nil then
			return nil,
				`{prefix}: {label} has no slot {if type(key) == "string"
					then `'{key}'`
					else `{tostring(key)}`}. Its slots are {listOf(names)}.`
		end
	end
	local models: { [string]: any } = {}
	for _, name in names do
		local model = bindings[name]
		if model == nil then
			return nil,
				`{prefix}: nothing was given to play the slot '{name}' of {label}. Every slot needs a rig: {listOf(
					names
				)}.`
		end
		if not isA(model, "Model") then
			return nil,
				`{prefix}: the slot '{name}' of {label} needs a character Model, not {describe(
					model
				)}.`
		end
		models[name] = model
	end
	local joints: { [any]: { [string]: any } } = {}
	for _, take in takes do
		local where = takeLabel(takes, take, label)
		local claimed: { [any]: string } = {}
		for _, name in SceneSidecar.slotNames(take.slots) do
			local model = models[name]
			local other = claimed[model]
			if other ~= nil then
				return nil,
					`{prefix}: {nameOf(model)} was given for both '{other}' and '{name}' of {where}; each slot needs its own rig.`
			end
			claimed[model] = name
			joints[model] = joints[model] or jointsOf(model)
			local ok, problem = SlotCheck.check(take.slots[name].requirement :: any, joints[model])
			if not ok then
				return nil,
					`{prefix}: {nameOf(model)} cannot play the slot '{name}' of {where}. {problem}`
			end
		end
	end
	return models, nil
end

local function resolve(scene: Scene, take: TakePlay): (AnchorMath.Resolved?, string?)
	local workspace = scene.context.workspace()
	return AnchorMath.resolve(take.sidecar :: any, {
		part = function(path: string): CFrame?
			return Scene.findPart(workspace, path)
		end,
		slotRoot = function(slot: string): CFrame?
			local play = take.byName[slot]
			return if play ~= nil then Scene.worldOf(play.rootPart) else nil
		end,
	}, scene.override())
end

--[=[
	@class ApexScene

	A scene loaded by LoadScene: several rigs, and maybe a camera, played together. Each take
	plays when the one before it ends. Call its methods with `:`.
]=]
local Methods = {}
local HandleMeta = {}
local owners: { [any]: Scene } = setmetatable({}, { __mode = "k" }) :: any

function Scene.new(
	context: Context,
	value: any,
	bindings: any,
	options: any,
	label: string
): (Scene?, string?)
	local prefix = "ApexEngine.LoadScene"
	local valid, invalid = SceneSidecar.validate(value)
	if not valid then
		return nil, `{prefix}: {label} cannot be used: {invalid}.`
	end
	local movie = value :: SceneSidecar.SceneSidecar
	local takes = SceneSidecar.takesOf(movie)
	local sidecar = takes[1]
	local names = SceneSidecar.allSlotNames(movie)

	if options ~= nil and type(options) ~= "table" then
		return nil,
			`{prefix}'s third argument is its options - \{ anchor = ..., camera = ... } - not a {typeof(
				options
			)}.`
	end
	local given = options or {}
	for key in given do
		if table.find(Scene.OPTIONS, key) == nil then
			return nil,
				`{prefix}: '{tostring(key)}' is not an option. Its options are anchor, camera, screen, screenOrder and look.`
		end
	end
	if given.screen ~= nil and type(given.screen) ~= "boolean" then
		return nil,
			`{prefix}: the screen option must be true or false, not {describe(given.screen)}.`
	end
	if given.look ~= nil and type(given.look) ~= "boolean" then
		return nil, `{prefix}: the look option must be true or false, not {describe(given.look)}.`
	end
	local order = given.screenOrder
	if
		order ~= nil
		and (
			type(order) ~= "number"
			or order ~= order
			or order % 1 ~= 0
			or math.abs(order) > 2 ^ 31 - 1
		)
	then
		return nil,
			`{prefix}: the screenOrder option must be a whole number, a ScreenGui's DisplayOrder, not {describe(
				order
			)}.`
	end
	local override, anchorProblem = Scene.overrideOf(given.anchor, names)
	if override == nil then
		return nil, `{prefix}: {label} cannot be placed: {anchorProblem}`
	end
	local camera = given.camera
	if camera ~= nil and not isA(camera, "Camera") then
		return nil,
			`{prefix}: the camera option must be a Camera (workspace.CurrentCamera), not {describe(
				camera
			)}.`
	end

	local models, problem = bind(takes, bindings, names, label, context.jointsOf)
	if models == nil then
		return nil, problem
	end
	local animators: { [string]: any } = {}
	local roots: { [string]: any } = {}
	local studio = context.studio ~= nil and context.studio()
	for _, name in names do
		local model = models[name]
		local animator, missing = animatorOf(model, name)
		if animator == nil then
			return nil, `{prefix}: {missing}`
		end
		animators[name] = animator
		local rootPart = Movement.rootPartOf(model)
		if rootPart == nil then
			return nil,
				`{prefix}: {nameOf(model)} has no HumanoidRootPart (or PrimaryPart), so it cannot be placed in {label}.`
		end
		roots[name] = rootPart
	end
	local ids: { { [string]: number | string } } = {}
	for index, take in takes do
		local where = takeLabel(takes, take, label)
		local found: { [string]: number | string } = {}
		for _, name in SceneSidecar.slotNames(take.slots) do
			local slot = take.slots[name]
			local tempId = Registry.tempIdOf(slot.tempId)
			local id: (number | string)? = slot.animation.assetId
			if tempId ~= nil and studio then
				id = tempId
			end
			if id == nil then
				local why = if studio
					then "Publish it from Apex Animator, or export the scene again to play it in Studio from a temporary copy."
					else "Publish it from Apex Animator and export the scene again: a temporary copy only plays in Studio."
				return nil,
					`{prefix}: the slot '{name}' of {where} has not been published yet, so there is no animation to play. {why}`
			end
			found[name] = id :: number | string
		end
		ids[index] = found
	end

	local scene: Scene = {
		sidecar = sidecar,
		movie = movie,
		takes = {},
		current = 1,
		length = SceneSidecar.lengthOf(movie),
		label = label,
		context = context,
		byName = {},
		slots = {},
		override = override,
		camera = camera,
		borrowed = nil,
		screen = given.screen == true or (given.screen == nil and camera ~= nil),
		screenOrder = order or ScreenDraw.ORDER,
		look = given.look == true or (given.look == nil and camera ~= nil),
		overlay = nil,
		phase = "Idle",
		time = 0,
		speed = 1,
		resolved = nil,
		stopped = Signal.new(),
		ended = Signal.new(),
		destroyed = false,
		handle = nil,
	}
	local placing: TakePlay = { sidecar = sidecar, byName = {}, slots = {}, start = 0 }
	for _, name in names do
		placing.byName[name] = { rootPart = roots[name] } :: any
	end
	local resolved, unplaced = resolve(scene, placing)
	if resolved == nil then
		return nil, `{prefix}: {label} cannot be placed. {unplaced}`
	end
	scene.resolved = resolved

	local slots: Spaces.Slots = {
		label = label,
		resolve = function(slot: string): any?
			if scene.destroyed or scene.phase == "Idle" then
				return nil
			end
			return models[slot]
		end,
	}
	local start = 0
	local shot, shown = false, false
	for index, take in takes do
		local play: TakePlay = { sidecar = take, byName = {}, slots = {}, start = start }
		for _, name in SceneSidecar.slotNames(take.slots) do
			local animation = take.slots[name].animation
			local trackLabel = if #takes > 1
				then `{label} (take '{take.name}', slot '{name}')`
				else `{label} (slot '{name}')`
			local live = context.loadTrack(animators[name], animation, trackLabel, ids[index][name])
			live.showsLook = scene.look
			Spaces.bindSlots(live, slots)
			local slotPlay: SlotPlay = {
				name = name,
				model = models[name],
				rootPart = roots[name],
				live = live,
				length = animation.length,
				looped = animation.loop,
			}
			play.byName[name] = slotPlay
			table.insert(play.slots, slotPlay)
		end
		table.insert(scene.takes, play)
		start += SceneSidecar.endOf(take)
		shot = shot or CameraEval.hasKeys(take.camera :: any)
		shown = shown or (take.screen ~= nil and #take.screen > 0)
	end
	scene.byName = scene.takes[1].byName
	scene.slots = scene.takes[1].slots
	if camera ~= nil and not shot then
		context.warn(
			`scene:{label}:nocamera`,
			`ApexEngine.LoadScene: {label} has no camera track, so the camera passed to it is left alone.`
		)
	end
	if given.screen == true then
		if not shown then
			context.warn(
				`scene:{label}:noscreen`,
				`ApexEngine.LoadScene: {label} has nothing on its Screen row, so there is nothing to draw.`
			)
		elseif context.playerGui == nil or context.playerGui() == nil then
			context.warn(
				`scene:{label}:screenhere`,
				`ApexEngine.LoadScene: {label}'s Screen row draws only on a player's machine, so it is left out here.`
			)
		end
	end
	return scene, nil
end

local function settled(scene: Scene): boolean
	for _, slot in scene.slots do
		if slot.live.phase ~= "Idle" or slot.live.pending ~= nil then
			return false
		end
	end
	return true
end

local function enter(scene: Scene, index: number)
	local take = scene.takes[index]
	scene.current = index
	scene.sidecar = take.sidecar
	scene.byName = take.byName
	scene.slots = take.slots
end

local function anyShot(scene: Scene): boolean
	for _, take in scene.takes do
		if CameraEval.hasKeys(take.sidecar.camera :: any) then
			return true
		end
	end
	return false
end

local function advance(scene: Scene, at: number)
	local take = scene.takes[scene.current + 1]
	local origin = (scene.resolved :: AnchorMath.Resolved).origin
	local placed: AnchorMath.Resolved =
		{ origin = origin, slots = AnchorMath.placements(take.sidecar :: any, origin) }
	local leaving = scene.slots
	enter(scene, scene.current + 1)
	scene.resolved = placed
	scene.time = at
	for _, slot in scene.slots do
		Movement.place(slot.live, { start = placed.slots[slot.name], blend = 0 })
		ApexTrack.handle(slot.live):Play(0, nil, scene.speed)
	end
	for _, slot in leaving do
		ApexTrack.handle(slot.live):Stop(0)
	end
	dropScreen(scene)
end

function Scene.play(scene: Scene, fadeTime: number?, speed: number?)
	local resolved, problem = resolve(scene, scene.takes[1])
	if resolved == nil then
		error(`ApexEngine: {scene.label} cannot be placed. {problem}`, 3)
	end
	local placed = resolved :: AnchorMath.Resolved
	if scene.current ~= 1 then
		for _, slot in scene.slots do
			ApexTrack.handle(slot.live):Stop(fadeTime)
		end
		enter(scene, 1)
	end
	scene.resolved = placed
	scene.time = 0
	scene.speed = if speed ~= nil then speed else 1
	scene.phase = "Playing"
	for _, slot in scene.slots do
		Movement.place(slot.live, {
			start = placed.slots[slot.name],
			blend = if slot.name == placed.fixed then 0 else nil,
		})
	end
	for _, slot in scene.slots do
		ApexTrack.handle(slot.live):Play(fadeTime, nil, speed)
	end
	if scene.camera ~= nil and scene.borrowed == nil and anyShot(scene) then
		scene.borrowed = scene.camera
		Scene.borrowCamera(scene.camera)
	end
	stepCamera(scene)
	stepScreen(scene)
	scene.context.add(scene)
end

local function finish(scene: Scene, reason: ApexTrack.EndReason, fadeTime: number?)
	scene.phase = "Stopping"
	for _, slot in scene.slots do
		local track = slot.live.track
		local playing = true
		pcall(function()
			playing = track.IsPlaying
		end)
		if playing and (reason == "Interrupted" or slot.looped) then
			ApexTrack.handle(slot.live):Stop(fadeTime)
		end
	end
	giveCameraBack(scene)
	dropScreen(scene)
	Signal.fire(scene.stopped, reason)
end

function Scene.stop(scene: Scene, fadeTime: number?)
	if scene.phase ~= "Playing" then
		return
	end
	finish(scene, "Interrupted", fadeTime)
end

function Scene.step(scene: Scene, dt: number)
	if scene.phase == "Playing" then
		scene.time += dt * scene.speed
		while
			scene.time >= SceneSidecar.endOf(scene.sidecar)
			and scene.takes[scene.current + 1] ~= nil
		do
			advance(scene, scene.time - SceneSidecar.endOf(scene.sidecar))
		end
		local report: { Lockstep } = {}
		for index, slot in scene.slots do
			local live = slot.live
			report[index] = {
				time = live.time,
				length = slot.length,
				looped = slot.looped,
				playing = live.phase == "Playing",
			}
		end
		for index, expected in Scene.corrections(scene.time, report) do
			local track = scene.slots[index].live.track
			pcall(function()
				track.TimePosition = expected
			end)
		end
		stepCamera(scene)
		stepScreen(scene)
		if scene.time >= SceneSidecar.endOf(scene.sidecar) then
			finish(scene, "Completed", nil)
		end
	end
	if scene.phase == "Stopping" and settled(scene) then
		scene.phase = "Idle"
		scene.context.remove(scene)
		Signal.fire(scene.ended)
	end
end

function Scene.holds(scene: Scene, model: any): boolean
	if scene.phase == "Idle" then
		return false
	end
	for _, take in scene.takes do
		for _, slot in take.slots do
			if slot.model == model then
				return true
			end
		end
	end
	return false
end

function Scene.destroy(scene: Scene)
	if scene.destroyed then
		return
	end
	if scene.phase == "Playing" then
		finish(scene, "Interrupted", 0)
	end
	giveCameraBack(scene)
	dropScreen(scene)
	scene.destroyed = true
	scene.phase = "Idle"
	scene.context.remove(scene)
end

local function sceneOf(handle: any): Scene
	local scene = owners[handle]
	if scene == nil then
		error("ApexEngine: call this on a scene, with ':' (scene:Play()), not '.'", 3)
	end
	if scene.destroyed then
		error(`ApexEngine: {scene.label} was destroyed; load it again with ApexEngine.LoadScene`, 3)
	end
	return scene
end

--[=[
	@method Play
	@within ApexScene

	Plays the scene from the start: places each rig from the anchor, plays every slot at once,
	drives the camera and draws the Screen row. A playing scene starts over.

	@param fadeTime number?
	@param speed number?
	@error string -- the scene can no longer be placed, as when the anchor part is gone
]=]
function Methods.Play(self: any, fadeTime: number?, speed: number?)
	Scene.play(sceneOf(self), fadeTime, speed)
end

--[=[
	@method Stop
	@within ApexScene

	Stops every slot at once, gives the camera back and clears the Screen row. Stopped fires
	with "Interrupted". Does nothing when the scene is not playing.

	@param fadeTime number?
]=]
function Methods.Stop(self: any, fadeTime: number?)
	Scene.stop(sceneOf(self), fadeTime)
end

--[=[
	@method Destroy
	@within ApexScene

	Stops the scene at once and lets it go. Play, Stop and GetTrack error after this.
]=]
function Methods.Destroy(self: any)
	local scene = owners[self]
	if scene ~= nil then
		Scene.destroy(scene)
	end
end

--[=[
	@method GetTrack
	@within ApexScene

	Returns the enhanced track playing a slot: the playing take's, or else the first take's
	with that slot.

	@param slot string
	@return ApexTrack
	@error string -- the scene has no slot with that name
]=]
function Methods.GetTrack(self: any, slot: string): any
	local scene = sceneOf(self)
	local play = scene.byName[slot]
	for _, take in scene.takes do
		play = play or take.byName[slot]
	end
	if play == nil then
		local names = SceneSidecar.allSlotNames(scene.movie)
		error(
			`ApexEngine: {scene.label} has no slot '{tostring(slot)}'. Its slots are {listOf(names)}.`,
			2
		)
	end
	return ApexTrack.handle(play.live)
end

--[=[
	@prop Stopped Signal
	@within ApexScene
	@readonly

	Fires with "Completed" or "Interrupted" as the scene stops.
]=]

--[=[
	@prop Ended Signal
	@within ApexScene
	@readonly

	Fires once every rig's fade-out is over.
]=]

--[=[
	@prop TimePosition number
	@within ApexScene
	@readonly

	Seconds into the scene, counted over every take.
]=]

--[=[
	@prop Length number
	@within ApexScene
	@readonly

	Seconds the whole scene lasts, over every take.
]=]

--[=[
	@prop IsPlaying boolean
	@within ApexScene
	@readonly
]=]

--[=[
	@prop Name string
	@within ApexScene
	@readonly

	The scene's name.
]=]

--[=[
	@prop Take string
	@within ApexScene
	@readonly

	The name of the take playing now.
]=]
function HandleMeta.__index(handle: any, key: any): any
	local method = (Methods :: any)[key]
	if method ~= nil then
		return method
	end
	local scene = owners[handle]
	if scene == nil then
		error("ApexEngine: this is not a scene", 2)
	end
	if key == "Stopped" then
		return scene.stopped
	elseif key == "Ended" then
		return scene.ended
	elseif key == "TimePosition" then
		local take = scene.takes[scene.current]
		return take.start + math.clamp(scene.time, 0, SceneSidecar.endOf(take.sidecar))
	elseif key == "Length" then
		return scene.length
	elseif key == "IsPlaying" then
		return scene.phase == "Playing"
	elseif key == "Name" then
		return scene.movie.name
	elseif key == "Take" then
		return scene.sidecar.name
	end
	error(`ApexEngine: '{tostring(key)}' is not a member of an ApexEngine scene`, 2)
end

function HandleMeta.__newindex(_: any, key: any)
	error(`ApexEngine: '{tostring(key)}' cannot be set on an ApexEngine scene`, 2)
end

function HandleMeta.__tostring(handle: any): string
	local scene = owners[handle]
	return if scene ~= nil then `ApexScene({scene.label})` else "ApexScene"
end

function Scene.handle(scene: Scene): any
	local handle = scene.handle
	if handle == nil then
		handle = setmetatable({}, HandleMeta)
		owners[handle] = scene
		scene.handle = handle
	end
	return handle
end

function Scene.sceneOf(handle: any): Scene?
	return owners[handle]
end

return Scene
