--!strict
--!native
--!optimize 2

local Fabrik = require(script.Parent.Fabrik)

local Aim = {}

export type JointLimit = {
	x: { number }?,
	y: { number }?,
	z: { number }?,
}

export type Link = {
	parentOffset: CFrame,
	childOffset: CFrame,
	transform: CFrame?,
	limit: JointLimit?,
	stiffness: number?,
}

export type Chain = {
	parentWorld: CFrame,
	links: { Link },
}

export type Settings = {
	pole: Vector3?,
	poleAngle: number?,
	stretch: number?,
	softness: number?,
	orientTip: (boolean | number)?,
	bend: Vector3?,
	iterations: number?,
	tolerance: number?,
	tip: CFrame?,
	share: number?,
	slideIn: (boolean | number)?,
	length: Vector3?,
	lean: number?,
}

export type Result = {
	transforms: { CFrame },
	reached: boolean,
	distance: number,
	stretch: number,
	passes: number,
}

export type PointOptions = {
	share: number?,
	toward: Vector3?,
	turn: number?,
	margin: number?,
	slide: number?,
	inward: number?,
	slideIn: number?,
	roll: (boolean | number)?,
	length: Vector3?,
	lean: number?,
}

export type Point = {
	offset: Vector3,
	rotation: CFrame,
	bend: number,
	shift: number,
	extension: number,
	natural: CFrame,
	roll: number,
	sweep: number,
}

local EPSILON = 1e-4
local REACHED = 1e-4
local SETTLED = 1e-6
local LEVER_PASSES = 12
local IDENTITY = CFrame.identity

local abs, sqrt, cos, sin, acos, atan2, clamp, max, min =
	math.abs, math.sqrt, math.cos, math.sin, math.acos, math.atan2, math.clamp, math.max, math.min

function Aim.amount(value: (boolean | number)?, default: number): number
	if value == nil then
		return default
	elseif value == true then
		return 1
	elseif value == false then
		return 0
	end
	return clamp(value :: number, 0, 1)
end

function Aim.perpendicularTo(direction: Vector3, preferred: Vector3): Vector3
	local candidate = direction:Cross(preferred)
	if candidate.Magnitude > EPSILON then
		return candidate.Unit
	end
	candidate = direction:Cross(Vector3.xAxis)
	if candidate.Magnitude > EPSILON then
		return candidate.Unit
	end
	return direction:Cross(Vector3.yAxis).Unit
end

function Aim.rotationBetween(from: Vector3, to: Vector3, preferred: Vector3): CFrame
	local dot = clamp(from:Dot(to), -1, 1)
	if dot > 1 - EPSILON then
		return IDENTITY
	end
	if dot < -1 + EPSILON then
		return CFrame.fromAxisAngle(Aim.perpendicularTo(from, preferred), math.pi)
	end
	return CFrame.fromAxisAngle(from:Cross(to).Unit, acos(dot))
end

function Aim.point(socket: Vector3, rest: CFrame, goal: CFrame, options: PointOptions?): Point
	local share = clamp((options and options.share) or 0, 0, 1)
	local margin = clamp((options and options.margin) or 0, 0, 1)
	local slide = options and options.slide
	local most = if slide == nil then math.huge else max(slide, 0)
	local inward = options and options.inward
	local deepest = if inward == nil then most else max(inward, 0)
	local rolled = Aim.amount(options and options.roll, 1)
	local sinks = Aim.amount(options and options.slideIn, 0)
	local lean = clamp((options and options.lean) or 1, 0, 1)

	local restVector = rest.Position - socket
	local reach = restVector.Magnitude
	local wish = goal.Position - socket
	local wishDistance = wish.Magnitude

	local length = if share > 0 and options ~= nil then options.length else nil
	local along = if length ~= nil then restVector:Dot(length) else 0
	if length ~= nil and along > EPSILON then
		local lever = restVector - length * along
		local onAxis = table.clone(options :: PointOptions)
		onAxis.length = nil
		local toward = options and options.toward
		local held = if rolled > 0
			then IDENTITY:Lerp(goal.Rotation * rest.Rotation:Inverse(), rolled) * lever
			else lever
		local answer: Point
		local passes = 0
		repeat
			local top = socket + held
			local across = if held.Magnitude > EPSILON then held.Unit else nil
			onAxis.toward = if toward ~= nil and across ~= nil
				then toward - across * toward:Dot(across)
				else toward
			answer = Aim.point(top, CFrame.new(top + length * along) * rest.Rotation, goal, onAxis)
			local turned = answer.rotation * lever
			local settled = (turned - held).Magnitude < SETTLED
			answer.offset = held + answer.offset - turned
			held = turned
			passes += 1
		until settled or passes >= LEVER_PASSES
		return answer
	end

	if reach < EPSILON then
		local shift = min(wishDistance, most)
		return {
			offset = if wishDistance > EPSILON then wish * (shift / wishDistance) else Vector3.zero,
			rotation = IDENTITY,
			bend = 0,
			shift = shift,
			extension = 0,
			natural = rest.Rotation,
			roll = 0,
			sweep = 0,
		}
	end

	local restDirection = restVector / reach
	local bearing = if wishDistance > EPSILON then wish / wishDistance else restDirection
	local upper = reach * share
	local lower = reach - upper

	local floor = max(abs(lower - upper), EPSILON)
	local limit = max(reach * (1 - margin), floor)
	local span = clamp(wishDistance, floor, limit)
	local shift = clamp(wishDistance - span, -deepest, most)
	if sinks > 0 then
		shift += (min(wishDistance - span, most) - shift) * sinks
	end
	if lean < 1 and upper > EPSILON then
		local slid = (1 - lean) * (limit - span)
		span += slid
		shift -= slid
	end
	local root = socket + bearing * shift

	local pivot = root
	local direction = bearing
	if upper > EPSILON then
		local toward = options and options.toward
		local side = if toward ~= nil then toward - bearing * toward:Dot(bearing) else nil
		local hang = restDirection - bearing * restDirection:Dot(bearing)
		local pole = if side ~= nil and side.Magnitude > EPSILON
			then side.Unit
			elseif hang.Magnitude > EPSILON then hang.Unit
			else Aim.perpendicularTo(bearing, rest.RightVector)
		local turn = (options and options.turn) or 0
		if turn ~= 0 then
			pole = pole * cos(turn) + bearing:Cross(pole) * sin(turn)
		end
		local cosine =
			clamp((upper * upper + span * span - lower * lower) / (2 * upper * span), -1, 1)
		local elbow = root + upper * (cosine * bearing + sqrt(1 - cosine * cosine) * pole)
		local toGoal = goal.Position - elbow
		local toGoalDistance = toGoal.Magnitude
		direction = if toGoalDistance > EPSILON then toGoal / toGoalDistance else bearing
		pivot = elbow - direction * upper
	end

	local point = Aim.rotationBetween(restDirection, direction, rest.RightVector)

	local delta = goal.Rotation * (point * rest.Rotation):Inverse()
	local axis, angle = delta:ToAxisAngle()
	local half = angle * 0.5
	local scalar = cos(half)
	local twist = axis:Dot(direction) * sin(half)
	local roll = if rolled > 0 then 2 * atan2(twist, scalar) else 0
	local rotation = if rolled > 0 then CFrame.fromAxisAngle(direction, roll) * point else point
	if rolled > 0 and rolled < 1 then
		rotation = point:Lerp(rotation, rolled)
	end

	return {
		offset = pivot - socket,
		rotation = rotation,
		bend = acos(clamp(direction:Dot(bearing), -1, 1)),
		shift = shift,
		extension = wishDistance / reach,
		natural = point * rest.Rotation,
		roll = roll,
		sweep = 2 * acos(clamp(sqrt(scalar * scalar + twist * twist), -1, 1)),
	}
end

function Aim.solve(chain: Chain, target: CFrame, settings: Settings?): Result
	assert(#chain.links == 1, "Aim.solve takes a chain of exactly one joint")
	local options: Settings = settings or {}
	local link = chain.links[1]
	local base = chain.parentWorld * link.parentOffset
	local start = link.transform or IDENTITY
	local pivot = base * start
	local tip = options.tip or IDENTITY
	local rest = pivot * tip
	local socket = pivot.Position
	local reach = (rest.Position - socket).Magnitude
	local stretch = options.stretch or 1
	local pole = options.pole

	local answer = Aim.point(socket, rest, target, {
		share = options.share,
		toward = if pole ~= nil then pole - socket else nil,
		turn = options.poleAngle,
		slide = if stretch > 1 then (stretch - 1) * reach else 0,
		inward = if Aim.amount(options.slideIn, 0) >= 1 then math.huge else nil,
		slideIn = Aim.amount(options.slideIn, 0),
		roll = options.orientTip,
		length = if options.length ~= nil then pivot.Rotation * options.length else nil,
		lean = options.lean,
	})

	local placed = CFrame.new(socket + answer.offset) * answer.rotation * pivot.Rotation
	local transform = base:Inverse() * placed
	local stiffness = link.stiffness or 0
	if stiffness > 0 then
		transform = start:Lerp(transform, 1 - min(stiffness, 1))
	end
	if link.limit then
		transform = CFrame.new(transform.Position) * Fabrik.clamp(transform.Rotation, link.limit)
	end

	local landed = (base * transform * tip).Position
	local distance = (landed - target.Position).Magnitude
	return {
		transforms = { transform },
		reached = distance <= REACHED,
		distance = distance,
		stretch = if reach >= EPSILON then (reach + answer.shift) / reach else 1,
		passes = 1,
	}
end

return Aim
