			Modifiers.clampKnots(channel, 0, length, rate, options, knots)
		end
	end
	knots = tidy(knots, SAME, length - SAME)
	return {
		name = name,
		quaternion = quaternion,
		authored = #sources > 0,
		rate = rate,
		explicit = explicit,
		tolerance = tolerance,
		knots = knots,
		steep = tidy(steep, -SAME, length + SAME),
		probes = tidy(probes, -SAME, length + SAME),
		times = merge(gridOf(rate, length), knots),
		index = {},
		owns = {},
		dropped = false,
		keys = {},
		rotationKeys = {},
	}
end

local function nearest(angle: number, target: number): number
	return angle + TAU * floor((target - angle) / TAU + 0.5)
end

local AXIS_CHANNEL: { [string]: string } = { X = "rx", Y = "ry", Z = "rz" }

function Bake.eulerFilter(order: Pose.Order, angles: { Pose.Euler })
	local letters = if AXIS_CHANNEL[order:sub(1, 1)] ~= nil and #order == 3 then order else "XYZ"
	local first = AXIS_CHANNEL[letters:sub(1, 1)]
	local second = AXIS_CHANNEL[letters:sub(2, 2)]
	local third = AXIS_CHANNEL[letters:sub(3, 3)]
	for k = 2, #angles do
		local was = angles[k - 1] :: any
		local now = angles[k] :: any
		local pa, pb, pc = was[first], was[second], was[third]
		local a, b, c = now[first], now[second], now[third]
		local a1, b1, c1 = nearest(a, pa), nearest(b, pb), nearest(c, pc)
		local a2, b2, c2 = nearest(a + pi, pa), nearest(pi - b, pb), nearest(c + pi, pc)
		if
			abs(a2 - pa) + abs(b2 - pb) + abs(c2 - pc)
			< abs(a1 - pa) + abs(b1 - pb) + abs(c1 - pc)
		then
			a1, b1, c1 = a2, b2, c2
		end
		now[first], now[second], now[third] = a1, b1, c1
	end
end

local function quaternionAngle(
	aw: number,
	ax: number,
	ay: number,
	az: number,
	bw: number,
	bx: number,
	by: number,
	bz: number
): number
	if aw * bw + ax * bx + ay * by + az * bz < 0 then
		bw, bx, by, bz = -bw, -bx, -by, -bz
	end
	local dw, dx, dy, dz = aw - bw, ax - bx, ay - by, az - bz
	return 4 * asin(min(1, sqrt(dw * dw + dx * dx + dy * dy + dz * dz) / 2))
end

local function poseError(a: CFrame, b: CFrame): (number, number)
	local ax, ay, az, a00, a01, a02, a10, a11, a12, a20, a21, a22 = a:GetComponents()
	local bx, by, bz, b00, b01, b02, b10, b11, b12, b20, b21, b22 = b:GetComponents()
	local sum = (a00 - b00) ^ 2
		+ (a01 - b01) ^ 2
		+ (a02 - b02) ^ 2
		+ (a10 - b10) ^ 2
		+ (a11 - b11) ^ 2
		+ (a12 - b12) ^ 2
		+ (a20 - b20) ^ 2
		+ (a21 - b21) ^ 2
		+ (a22 - b22) ^ 2
	return 2 * asin(min(1, sqrt(sum) / (2 * sqrt(2)))),
		sqrt((ax - bx) ^ 2 + (ay - by) ^ 2 + (az - bz) ^ 2)
end

type Fitter = (i: number, e: number) -> (NativeCurve.Interp?, number, number)

type Segment = {
	offset: number,
	interp: NativeCurve.Interp,
	m0: number,
	m1: number,
}

type Memo = {
	get: (a: number, b: number) -> { Segment }?,
	put: (a: number, b: number, segments: { Segment }) -> (),
	touch: (lo: number, hi: number) -> (),
}

local function plan(
	n: number,
	knot: { boolean },
	jumpAfter: { boolean },
	flat: (lo: number, hi: number) -> boolean,
	fit: Fitter,
	memo: Memo?
): { Step }
	local steps: { Step } = {}
	local pendingLeft: number? = nil
	local lastInterp: NativeCurve.Interp = "Linear"

	local function emit(index: number, interp: NativeCurve.Interp, right: number?)
		table.insert(steps, { index = index, interp = interp, left = pendingLeft, right = right })
		pendingLeft = nil
	end

	local function segment(i: number, interp: NativeCurve.Interp, m0: number, m1: number)
		if interp == "Cubic" then
			emit(i, "Cubic", m0)
			pendingLeft = m1
		else
			emit(i, interp, nil)
		end
		lastInterp = interp
	end

	local function cover(a: number, b: number)
		local made: { Segment }? = nil
		if memo ~= nil then
			local known = memo.get(a, b)
			if known ~= nil then
				for _, piece in known do
					segment(a + piece.offset, piece.interp, piece.m0, piece.m1)
				end
				return
			end
			made = {}
		end
		local cur = a
		local whole = true
		while cur < b do
			local interp: NativeCurve.Interp?, m0: number, m1: number = nil, 0, 0
			local e = b
			local bad = b + 1
			if whole then
				whole = false
				interp, m0, m1 = fit(cur, b)
				if interp == nil then
					bad = b
				end
			end
			if interp == nil then
				local good = cur + 1
				interp, m0, m1 = fit(cur, good)
				local reach = 1
				while true do
					reach *= 2
					local probe = min(cur + reach, b)
					if probe >= bad or probe <= good then
						break
					end
					local kind, p0, p1 = fit(cur, probe)
					if kind == nil then
						bad = probe
						break
					end
					good, interp, m0, m1 = probe, kind, p0, p1
				end
				while bad - good > 1 do
					local mid = (good + bad) // 2
					local kind, p0, p1 = fit(cur, mid)
					if kind == nil then
						bad = mid
					else
						good, interp, m0, m1 = mid, kind, p0, p1
					end
				end
				e = good
			end
			segment(cur, interp or "Linear", m0, m1)
			if made ~= nil then
				table.insert(
					made,
					{ offset = cur - a, interp = interp or "Linear", m0 = m0, m1 = m1 }
				)
			end
			cur = e
		end
		if memo ~= nil and made ~= nil then
			memo.put(a, b, made)
		end
	end

	local lo = 1
	while lo <= n do
		local hi = lo
		while hi < n and not jumpAfter[hi] do
			hi += 1
		end
		local bridged = hi < n
		if flat(lo, hi) then
			if memo ~= nil then
				memo.touch(lo, hi)
			end
			emit(lo, "Constant", nil)
			lastInterp = "Constant"
			if not bridged and hi > lo then
				emit(hi, "Constant", nil)
			end
		else
			local a = lo
			for b = lo + 1, hi do
				if b == hi or knot[b] then
					cover(a, b)
					a = b
				end
			end
			emit(hi, if bridged then "Constant" else lastInterp, nil)
		end
		lo = hi + 1
	end
	return steps
end

local function fitScalar(
	times: { number },
	values: { number },
	tolerance: number,
	knot: { boolean },
	jumpAfter: { boolean },
	memo: Memo?
): { NativeCurve.Key }
	local a: NativeCurve.Key = { t = 0, v = 0, interp = "Linear" }
	local b: NativeCurve.Key = { t = 0, v = 0, interp = "Linear" }

	local function within(i: number, e: number): boolean
		for k = i + 1, e - 1 do
			if abs(NativeCurve.segment(a, b, times[k]) - values[k]) > tolerance then
				return false
			end
		end
		return true
	end

	local function fit(i: number, e: number): (NativeCurve.Interp?, number, number)
		a.t, a.v, b.t, b.v = times[i], values[i], times[e], values[e]
		a.interp, a.rightTangent, b.leftTangent = "Linear", nil, nil
		if within(i, e) then
			return "Linear", 0, 0
		end
		local duration = b.t - a.t
		local saa, sab, sbb, sar, sbr = 0, 0, 0, 0, 0
		for k = i + 1, e - 1 do
			local w0, w1, wa, wb = NativeCurve.cubicBasis((times[k] - a.t) / duration, duration)
			local r = values[k] - w0 * a.v - w1 * b.v
			saa += wa * wa
			sab += wa * wb
			sbb += wb * wb
			sar += wa * r
			sbr += wb * r
		end
		local ridge = RIDGE * (saa + sbb)
		local p0 = (values[i + 1] - a.v) / (times[i + 1] - a.t)
		local p1 = (b.v - values[e - 1]) / (b.t - times[e - 1])
		saa += ridge
		sbb += ridge
		sar += ridge * p0
		sbr += ridge * p1
		local det = saa * sbb - sab * sab
		if not (det > 0) then
			return nil, 0, 0
		end
		local m0 = (sar * sbb - sbr * sab) / det
		local m1 = (saa * sbr - sab * sar) / det
		a.interp, a.rightTangent, b.leftTangent = "Cubic", m0, m1
		if within(i, e) then
			return "Cubic", m0, m1
		end
		return nil, 0, 0
	end

	local function flat(lo: number, hi: number): boolean
		local v = values[lo]
		for k = lo + 1, hi do
			if abs(values[k] - v) > tolerance then
				return false
			end
		end
		return true
	end

	local steps = plan(#times, knot, jumpAfter, flat, fit, memo)
	local keys: { NativeCurve.Key } = table.create(#steps)
	for i, step in steps do
		keys[i] = {
			t = times[step.index],
			v = values[step.index],
			interp = step.interp,
			leftTangent = step.left,
			rightTangent = step.right,
		}
	end
	return keys
end

local function fitRotation(
	times: { number },
	records: { Record },
	tolerance: number,
	knot: { boolean },
	jumpAfter: { boolean },
	memo: Memo?
): { NativeCurve.RotationKey }
	local a: NativeCurve.RotationKey = { t = 0, w = 1, x = 0, y = 0, z = 0, interp = "Linear" }
	local b: NativeCurve.RotationKey = { t = 0, w = 1, x = 0, y = 0, z = 0, interp = "Linear" }

	local function set(key: NativeCurve.RotationKey, i: number)
		local record = records[i]
		key.t, key.w, key.x, key.y, key.z = times[i], record.qw, record.qx, record.qy, record.qz
	end

	local function fit(i: number, e: number): (NativeCurve.Interp?, number, number)
		set(a, i)
		set(b, e)
		for k = i + 1, e - 1 do
			local w, x, y, z = NativeCurve.rotationSegment(a, b, times[k])
			local record = records[k]
			if
				quaternionAngle(w, x, y, z, record.qw, record.qx, record.qy, record.qz) > tolerance
			then
				return nil, 0, 0
			end
		end
		return "Linear", 0, 0
	end

	local function flat(lo: number, hi: number): boolean
		local r = records[lo]
		for k = lo + 1, hi do
			local s = records[k]
			if quaternionAngle(r.qw, r.qx, r.qy, r.qz, s.qw, s.qx, s.qy, s.qz) > tolerance then
				return false
			end
		end
		return true
	end

	local steps = plan(#times, knot, jumpAfter, flat, fit, memo)
	local keys: { NativeCurve.RotationKey } = table.create(#steps)
	for i, step in steps do
		local record = records[step.index]
		keys[i] = {
			t = times[step.index],
			w = record.qw,
			x = record.qx,
			y = record.qy,
			z = record.qz,
			interp = step.interp,
		}
	end
	return keys
end

local function cutJumps(
	samples: Samples,
	judge: Judge,
	probed: { boolean }?,
	fresh: { [number]: boolean }?
): Samples
	local times, records, knot, bridged =
		samples.times, samples.records, samples.knot, samples.jumpAfter
	local distance, tolerance, evaluateAt = judge.distance, judge.tolerance, judge.evaluateAt
	local n = #times
	local steps: { [number]: number } = {}
	local function stepAt(k: number): number
		local step = steps[k]
		if step == nil then
			step = if bridged[k] then 0 else distance(records[k], records[k + 1])
			steps[k] = step
		end
		return step
	end

	local function holds(t: number, side: number, at: Record, near: Record, step: number): boolean
		local width = Bake.JUMP_WIDTH
		while width > STEEP_FLOOR do
			width /= 4
			local closer = distance(evaluateAt(t + side * width, near), at)
			if closer > SHRINK * step then
				return true
			elseif closer <= judge.jump then
				return false
			end
			step = closer
		end
		return true
	end

	type Jump = { t: number, record: Record, near: Record }
	local jumps: { [number]: Jump } = {}
	local found = false
	for k = 1, n - 1 do
		if bridged[k] or fresh ~= nil and not fresh[k] then
			continue
		end
		if probed ~= nil and probed[k + 1] then
			local t = times[k + 1]
			local justBefore = judge.probeAt(t - Bake.JUMP_WIDTH, records[k])
			local step = distance(justBefore, records[k + 1])
			if step > judge.jump and holds(t, -1, records[k + 1], justBefore, step) then
				jumps[k] = { t = t, record = records[k + 1], near = justBefore }
				found = true
				continue
			end
		end
		if probed ~= nil and probed[k] then
			local justAfter = judge.probeAt(times[k] + Bake.JUMP_WIDTH, records[k])
			local step = distance(records[k], justAfter)
			if step > judge.jump and holds(times[k], 1, records[k], justAfter, step) then
				local t = min(times[k] + Bake.JUMP_LEAD, (times[k] + times[k + 1]) / 2)
				jumps[k] = { t = t, record = evaluateAt(t, justAfter), near = records[k] }
				found = true
				continue
			end
		end
		local step = stepAt(k)
		if step <= tolerance then
			continue
		end
		local suspect = knot[k + 1]
		if not suspect then
			local speed, count = 0, 0
			if k > 1 and not bridged[k - 1] then
				speed += stepAt(k - 1) / (times[k] - times[k - 1])
				count += 1
			end
			if k < n - 1 and not bridged[k + 1] then
				speed += stepAt(k + 1) / (times[k + 2] - times[k + 1])
				count += 1
			end
			local expected = if count > 0 then (times[k + 1] - times[k]) * speed / count else 0
			suspect = step - expected > max(tolerance, 0.5 * step)
		end
		if not suspect then
			continue
		end
		local l, r = times[k], times[k + 1]
		local left, right = records[k], records[k + 1]
		local jump = false
		local width, held = Bake.JUMP_WIDTH, math.huge
		while distance(left, right) > tolerance do
			if r - l <= width then
				local narrow = distance(left, right)
				if narrow <= judge.jump then
					break
				elseif narrow > SHRINK * held or width <= STEEP_FLOOR then
					jump = true
					break
				end
				width, held = width / 4, narrow
			end
			local m = (l + r) / 2
			local middle = evaluateAt(m, left)
			if distance(middle, right) >= distance(left, middle) then
				l, left = m, middle
			else
				r, right = m, middle
			end
		end
		if jump then
			jumps[k] = { t = r, record = right, near = left }
			found = true
		end
	end
	if not found then
		return samples
	end

	local outTimes: { number } = table.create(n + 8)
	local outRecords: { Record } = table.create(n + 8)
	local outKnot: { boolean } = table.create(n + 8, false)
	local jumpAfter: { boolean } = {}
	local depth, outDepth = samples.depth, {}
	local function push(t: number, record: Record, isKnot: boolean, deep: number?)
		table.insert(outTimes, t)
		table.insert(outRecords, record)
		outKnot[#outTimes] = isKnot
		outDepth[#outTimes] = deep
	end
	for k = 1, n do
		push(times[k], records[k], knot[k], depth[k])
		if bridged[k] then
			jumpAfter[#outTimes] = true
		end
		local jump = jumps[k]
		if jump ~= nil then
			local lead = jump.t - Bake.JUMP_LEAD
			if lead > times[k] + SAME then
				local record = evaluateAt(lead, jump.near)
				push(lead, record, false, depth[k])
				judge.added(lead, record)
			end
			jumpAfter[#outTimes] = true
			if times[k + 1] - jump.t > 2 * Bake.JUMP_WIDTH then
				push(jump.t, jump.record, false, depth[k])
				judge.added(jump.t, jump.record)
			end
		end
	end
	return {
		times = outTimes,
		records = outRecords,
		knot = outKnot,
		jumpAfter = jumpAfter,
		depth = outDepth,
	}
end

function Bake.fit(
	times: { number },
	values: { number },
	tolerance: number,
	knots: { number }?,
	jumps: { number }?
): { NativeCurve.Key }
	local n = #times
	local knot: { boolean } = table.create(n, false)
	local jumpAfter: { boolean } = {}
	local rising = true
	for k = 2, n do
		if not (times[k] > times[k - 1]) then
			rising = false
			break
		end
	end
	local function mark(list: { number }?, each: (number) -> ())
		if list == nil then
			return
		end
		for _, t in list do
			local from = 1
			if rising then
				local below = t - 2 * SAME
				local lo, hi = 1, n + 1
				while lo < hi do
					local mid = (lo + hi) // 2
					if times[mid] < below then
						lo = mid + 1
					else
						hi = mid
					end
				end
				from = lo
			end
			for k = from, n do
				if abs(times[k] - t) <= SAME then
					each(k)
					break
				elseif rising and times[k] > t + 2 * SAME then
					break
				end
			end
		end
	end
	mark(knots, function(k)
		knot[k] = true
	end)
	mark(jumps, function(k)
		if k > 1 then
			jumpAfter[k - 1] = true
		end
	end)
	return fitScalar(times, values, tolerance, knot, jumpAfter)
end

local function owned(output: Output, index: number?, owner: Output?): boolean
	if not output.explicit or owner == output then
		return true
	end
	return index ~= nil and output.owns[index] == true
end

local function rotationDistance(a: Record, b: Record): number
	return quaternionAngle(a.qw, a.qx, a.qy, a.qz, b.qw, b.qx, b.qy, b.qz)
end

local function flagged(times: { number }, marks: { number }): { boolean }
	local out: { boolean } = table.create(#times, false)
	local cursor = 1
	for k, t in times do
		while cursor <= #marks and marks[cursor] < t - SAME do
			cursor += 1
		end
		out[k] = cursor <= #marks and abs(marks[cursor] - t) <= SAME
	end
	return out
end

type Store = {
	stretches: { [number]: { last: number, count: number, segments: { Segment } } },
	touched: { number },
}

local function memoOver(store: Store, times: { number }): Memo
	local function touch(lo: number, hi: number)
		table.insert(store.touched, times[lo])
		table.insert(store.touched, times[hi])
	end
	return {
		get = function(a: number, b: number): { Segment }?
			local entry = store.stretches[times[a]]
			if entry ~= nil and entry.count == b - a and entry.last == times[b] then
				return entry.segments
			end
			return nil
		end,
		put = function(a: number, b: number, segments: { Segment })
			store.stretches[times[a]] = { last = times[b], count = b - a, segments = segments }
			touch(a, b)
		end,
		touch = touch,
	}
end

local function fitOutput(output: Output, samples: Samples, tolerance: number, store: Store?)
	local times, records = samples.times, samples.records
	local memo = if store ~= nil then memoOver(store, times) else nil
	if output.quaternion then
		output.rotationKeys =
			fitRotation(times, records, tolerance, samples.knot, samples.jumpAfter, memo)
	else
		local name = output.name
		local values: { number } = table.create(#records)
		for k, record in records do
			values[k] = record[name]
		end
		output.keys = fitScalar(times, values, tolerance, samples.knot, samples.jumpAfter, memo)
	end
end

local function offBy(output: Output, t: number, record: Record): number
	if output.quaternion then
		local w, x, y, z = NativeCurve.evaluateRotation(output.rotationKeys, t)
		return quaternionAngle(w, x, y, z, record.qw, record.qx, record.qy, record.qz)
	end
	return abs(NativeCurve.evaluate(output.keys, t) - record[output.name])
end

local function refine(
	output: Output,
	samples: Samples,
	judge: Judge,
	sampleAt: (number, Record) -> Record
)
	local store: Store = { stretches = {}, touched = {} }
	fitOutput(output, samples, judge.tolerance, store)
	local limit = output.tolerance * Bake.FIT_SHARE
	local rounds = 2 * Bake.REFINE_DEPTH + (if #output.steep > 0 then Bake.STEEP_DEPTH else 0)
	for round = 0, rounds do
		local times, records, knot, jumpAfter, depth =
			samples.times, samples.records, samples.knot, samples.jumpAfter, samples.depth
		local n = #times
		local touched = store.touched
		store.touched = {}
		local split: { [number]: Record } = {}
		local any = false
		local range = 1
		for k = 1, n - 1 do
			if jumpAfter[k] then
				continue
			end
			local t0 = times[k]
			while range < #touched and touched[range + 1] <= t0 do
				range += 2
			end
			if range > #touched or touched[range] > t0 then
				continue
			end
			local t = (t0 + times[k + 1]) / 2
			local record = sampleAt(t, records[k])
			if
				round < rounds
				and (depth[k] or 0) < Bake.REFINE_DEPTH
				and offBy(output, t, record) > limit
			then
				split[k] = record
				any = true
			end
		end
		if not any then
			return
		end
		local held: { [number]: boolean } = {}
		if round >= Bake.REFINE_DEPTH then
			if output.quaternion then
				for _, key in output.rotationKeys do
					held[key.t] = true
				end
			else
				for _, key in output.keys do
					held[key.t] = true
				end
			end
		end
		local grown: Samples = {
			times = table.create(2 * n),
			records = table.create(2 * n),
			knot = table.create(2 * n, false),
			jumpAfter = {},
			depth = {},
		}
		local fresh: { [number]: boolean } = {}
		for k = 1, n do
			table.insert(grown.times, times[k])
			table.insert(grown.records, records[k])
			local at = #grown.times
			grown.knot[at] = knot[k] or held[times[k]] == true
			if jumpAfter[k] then
				grown.jumpAfter[at] = true
			end
			local middle = split[k]
			if middle ~= nil then
				local deeper = (depth[k] or 0) + 1
				table.insert(grown.times, (times[k] + times[k + 1]) / 2)
				table.insert(grown.records, middle)
				grown.depth[at], grown.depth[at + 1] = deeper, deeper
				fresh[at], fresh[at + 1] = true, true
			else
				grown.depth[at] = depth[k]
			end
		end
		samples = cutJumps(grown, judge, nil, fresh)
		fitOutput(output, samples, judge.tolerance, store)
	end
end

local function bakeJoint(
	track: Pose.JointTrack,
	length: number,
	resolved: Resolved,
	options: EvalOptions
): (Joint?, { Output })
	local mode = track.rotationMode
	local quaternion = mode == "Quaternion"
	local channels = track.channels
	local base = resolved.rate

	local outputs: { Output } = {}
	local axisTolerance = resolved.position / sqrt(3)
	for _, name in Pose.POSITION_CHANNELS do
		local channel = channels[name]
		if channel ~= nil then
			table.insert(
				outputs,
				newOutput(name, { channel }, base, axisTolerance, length, false, options)
			)
		end
	end
	if quaternion then
		local sources: { Modifiers.Channel } = {}
		for _, name in Pose.QUATERNION_CHANNELS do
			local channel = channels[name]
			if channel ~= nil then
				table.insert(sources, channel)
			end
		end
		if #sources > 0 then
			table.insert(
				outputs,
				newOutput(
					Bake.ROTATION_CURVE,
					sources,
					base,
					resolved.rotation,
					length,
					true,
					options
				)
			)
		end
	elseif channels.rx ~= nil or channels.ry ~= nil or channels.rz ~= nil then
		for _, name in Pose.EULER_CHANNELS do
			local channel = channels[name]
			local sources = if channel ~= nil then { channel } else {}
			table.insert(
				outputs,
				newOutput(name, sources, base, resolved.rotation / 3, length, false, options)
			)
		end
	end
	if #outputs == 0 then
		return nil, outputs
	end

	local union: { number } = {}
	for _, output in outputs do
		union = merge(union, output.times)
		if not output.explicit then
			union = merge(union, midpoints(output.times))
		end
	end
	for _, output in outputs do
		output.index = indexIn(union, output.times)
		if output.explicit then
			for _, i in output.index do
				output.owns[i] = true
			end
		end
	end

	local previous: Pose.Values? = nil
	if not quaternion then
		local t0 = union[1]
		local rx, ry, rz = channels.rx, channels.ry, channels.rz
		previous = {
			rx = if rx ~= nil then evaluateChannel(rx, t0, options) else 0,
			ry = if ry ~= nil then evaluateChannel(ry, t0, options) else 0,
			rz = if rz ~= nil then evaluateChannel(rz, t0, options) else 0,
		}
	end
	local records: { Record } = table.create(#union)
	local poses: { CFrame } = table.create(#union)
	local posed: { [number]: CFrame } = {}
	for i, t in union do
		local pose = evaluatePose(track, t, options)
		local values = Pose.toValues(pose, mode, previous)
		records[i] = values :: any
		poses[i] = pose
		if t == t then
			posed[t] = pose
		end
		previous = values
	end
	if not quaternion then
		Bake.eulerFilter(mode :: Pose.Order, records :: any)
	end
	local function evaluateAt(t: number, near: Record): Record
		local pose = posed[t]
		if pose == nil then
			pose = evaluatePose(track, t, options)
			if t == t then
				posed[t] = pose
			end
		end
		return Pose.toValues(pose, mode, near :: any) :: any
	end

	for _, output in outputs do
		if not output.authored and not output.quaternion then
			local name = output.name
			local moves = false
			for _, i in output.index do
				if abs(records[i][name]) > output.tolerance then
					moves = true
					break
				end
			end
			output.dropped = not moves
		end
	end

	local extras: { Extra } = {}
	local known: { [number]: Record } = {}
	for i, t in union do
		known[t] = records[i]
	end
	local beside: { [number]: Record } = {}
	local function probeAt(t: number, near: Record): Record
		local record = beside[t]
		if record == nil then
			record = evaluateAt(t, near)
			beside[t] = record
		end
		return record
	end
	for _, output in outputs do
		if output.dropped then
			continue
		end
		local n = #output.index
		local times: { number } = table.create(n)
		local samples: { Record } = table.create(n)
		for k, i in output.index do
			times[k] = union[i]
			samples[k] = records[i]
		end
		local name = output.name
		local judge: Judge = {
			distance = if output.quaternion
				then rotationDistance
				else function(a: Record, b: Record): number
					return abs(a[name] - b[name])
				end,
			tolerance = output.tolerance * Bake.FIT_SHARE,
			jump = output.tolerance,
			evaluateAt = evaluateAt,
			probeAt = probeAt,
			added = function(t: number, record: Record)
				table.insert(extras, { t = t, record = record, owner = output })
			end,
		}
		local depth: { [number]: number } = {}
		if #output.steep > 0 then
			local steep = flagged(times, output.steep)
			for k = 1, n - 1 do
				if steep[k] or steep[k + 1] then
					depth[k] = -Bake.STEEP_DEPTH
				end
			end
		end
		local cut = cutJumps({
			times = times,
			records = samples,
			knot = flagged(times, output.knots),
			jumpAfter = {},
			depth = depth,
		}, judge, if #output.probes > 0 then flagged(times, output.probes) else nil)
		if output.explicit then
			fitOutput(output, cut, judge.tolerance)
		else
			refine(output, cut, judge, function(t: number, near: Record): Record
				local record = known[t]
				if record == nil then
					record = evaluateAt(t, near)
					known[t] = record
					judge.added(t, record)
				end
				return record
			end)
		end
	end

	local byName: { [string]: Output } = {}
	for _, output in outputs do
		if not output.dropped then
			byName[output.name] = output
		end
	end
	local rotationOrder = if quaternion then nil else NativeCurve.rotationOrder(mode)
	local explicit = false
	for _, output in outputs do
		explicit = explicit or output.explicit
	end
	local worstRotation, rotationAt, worstPosition, positionAt = 0, 0, 0, 0
	local reference: Record = {}

	local function channelAt(
		name: string,
		t: number,
		record: Record,
		index: number?,
		owner: Output?
	): (number, number)
		local authored = record[name] or 0
		local output = byName[name]
		if output == nil then
			return 0, authored
		end
		local native = NativeCurve.evaluate(output.keys, t)
		return native, if owned(output, index, owner) then authored else native
	end

	local function check(t: number, record: Record, index: number?, owner: Output?)
		local npx, rpx = channelAt("px", t, record, index, owner)
		local npy, rpy = channelAt("py", t, record, index, owner)
		local npz, rpz = channelAt("pz", t, record, index, owner)
		reference.px, reference.py, reference.pz = rpx, rpy, rpz
		local nativeRotation: CFrame
		if quaternion then
			local rw, rx, ry, rz = record.qw, record.qx, record.qy, record.qz
			local output = byName[Bake.ROTATION_CURVE]
			if output ~= nil then
				local w, x, y, z = NativeCurve.evaluateRotation(output.rotationKeys, t)
				nativeRotation = NativeCurve.quaternionRotation(w, x, y, z)
				if not owned(output, index, owner) then
					rw, rx, ry, rz = w, x, y, z
				end
			else
				nativeRotation = NativeCurve.quaternionRotation(1, 0, 0, 0)
			end
			reference.qw, reference.qx, reference.qy, reference.qz = rw, rx, ry, rz
		else
			local nrx, rrx = channelAt("rx", t, record, index, owner)
			local nry, rry = channelAt("ry", t, record, index, owner)
			local nrz, rrz = channelAt("rz", t, record, index, owner)
			nativeRotation = NativeCurve.eulerRotation(nrx, nry, nrz, rotationOrder :: string)
			reference.rx, reference.ry, reference.rz = rrx, rry, rrz
		end
		local native = NativeCurve.pose(npx, npy, npz, nativeRotation)
		local authored = if index ~= nil and not explicit
			then poses[index]
			else Pose.fromValues(mode, reference :: any)
		local rotationError, positionError = poseError(native, authored)
		if positionError > worstPosition then
			worstPosition, positionAt = positionError, t
		end
		if rotationError > worstRotation then
			worstRotation, rotationAt = rotationError, t
		end
	end
	for i, t in union do
		check(t, records[i], i, nil)
	end
	for _, extra in extras do
		check(extra.t, extra.record, nil, extra.owner)
	end

	local joint: Joint = {
		rotationMode = mode,
		rotationOrder = rotationOrder,
		channels = {},
		rotation = nil,
		error = {
			rotation = worstRotation,
			rotationAt = rotationAt,
			position = worstPosition,
			positionAt = positionAt,
		},
	}
	for _, output in outputs do
		if output.dropped then
			continue
		elseif output.quaternion then
			joint.rotation = output.rotationKeys
		else
			joint.channels[output.name] = output.keys
		end
	end
	return joint, outputs
end

local function number3(x: number): string
	return string.format("%.3g", x)
end

local function problem(
	joint: string,
	kind: "Rotation" | "Position",
	amount: number,
	t: number
): Problem
	local words = if kind == "Rotation"
		then `{number3(math.deg(amount))}°`
		else `{number3(amount)} studs`
	return {
		joint = joint,
		kind = kind,
		error = amount,
		t = t,
		message = `{joint}: {words} max error at {string.format("%.2f", t)} s`,
	}
end

local FNV_OFFSET = 2166136261
local WORD = 4294967296

local function quantised(x: number?, scale: number): string
	if x == nil then
		return "-"
	elseif x ~= x then
		return "nan"
	end
	local whole = floor(x * scale + 0.5)
	if abs(whole) >= 2 ^ 52 then
		return string.format("%.17g", whole)
	end
	return string.format("%d", whole)
end

function Bake.hash(joints: { [string]: Joint }, face: Face?): string
	local h = FNV_OFFSET
	local function feed(text: string)
		for i = 1, #text do
			h = bxor(h, string.byte(text, i))
			h = (lshift(h, 24) + h * 403) % WORD
		end
	end
	local function feedCurves(channels: { [string]: { NativeCurve.Key } })
		local curves: { string } = {}
		for curve in channels do
			table.insert(curves, curve)
		end
		table.sort(curves)
		for _, curve in curves do
			feed("C" .. curve .. "\0")
			for _, key in channels[curve] do
				feed(
					quantised(key.t, 1e6)
						.. ","
						.. quantised(key.v, 1e6)
						.. ","
						.. key.interp
						.. ","
						.. quantised(key.leftTangent, 1e4)
						.. ","
						.. quantised(key.rightTangent, 1e4)
						.. ";"
				)
			end
		end
	end
	local names: { string } = {}
	for name in joints do
		table.insert(names, name)
	end
	table.sort(names)
	for _, name in names do
		local joint = joints[name]
		feed(
			"J" .. name .. "\0" .. joint.rotationMode .. "\0" .. (joint.rotationOrder or "") .. "\0"
		)
		feedCurves(joint.channels)
		local rotation = joint.rotation
		if rotation ~= nil then
			feed("R\0")
			for _, key in rotation do
				local sign = if key.w < 0 then -1 else 1
				feed(
					quantised(key.t, 1e6)
						.. ","
						.. quantised(sign * key.w, 1e6)
						.. ","
						.. quantised(sign * key.x, 1e6)
						.. ","
						.. quantised(sign * key.y, 1e6)
						.. ","
						.. quantised(sign * key.z, 1e6)
						.. ","
						.. key.interp
						.. ","
						.. quantised(key.leftTangent, 1e4)
						.. ","
						.. quantised(key.rightTangent, 1e4)
						.. ";"
				)
			end
		end
	end
	if face ~= nil then
		feed("F" .. face.name .. "\0")
		feedCurves(face.curves)
	end
	return string.format("%08x", h)
end

function Bake.scalars(
	channels: { [string]: Interp.Channel },
	length: number,
	rate: number,
	tolerance: number,
	presets: { [string]: any }?
): { [string]: { NativeCurve.Key } }
	length = max(length, 0)
	local grid = gridOf(max(rate, 1), length)
	local options: Interp.EvalOptions = { presets = presets } :: any
	local out: { [string]: { NativeCurve.Key } } = {}
	for name, channel in channels do
		local keys = channel.keys
		if #keys == 0 then
			continue
		end
		local keyTimes: { number } = {}
		local jumps: { number } = {}
		for index, key in keys do
			table.insert(keyTimes, key.t)
			local after = keys[index + 1]
			if after ~= nil and (key.interp or channel.interp) == "Constant" then
				table.insert(jumps, after.t)
			end
		end
		local extra = table.clone(keyTimes)
		table.move(midpoints(keyTimes), 1, #keyTimes - 1, #extra + 1, extra)
		local times = merge(grid, tidy(extra, 0, length))
		local values = table.create(#times)
		for k, t in times do
			values[k] = Interp.evaluate(channel, t, options)
		end
		out[name] = Bake.fit(times, values, tolerance, keyTimes, jumps)
	end
	return out
end

function Bake.face(doc: Document, rate: number, presets: { [string]: any }?): Face?
	local paths: { string } = {}
	for path, target in doc.props or {} do
		if target.className == "FaceControls" then
			table.insert(paths, path)
		end
	end
	table.sort(paths)
	for _, path in paths do
		local channels: { [string]: Interp.Channel } = {}
		for property, track in (doc.props :: any)[path].properties do
			if track.type == "number" and #track.keys > 0 then
				channels[property] = { keys = track.keys, interp = track.interp }
			end
		end
		if next(channels) ~= nil then
			return {
				name = string.match(path, "([^/]+)$") or path,
				curves = Bake.scalars(
					channels,
					doc.length,
					rate,
					Bake.FACE_TOLERANCE * Bake.FIT_SHARE,
					presets
				),
			}
		end
	end
	return nil
end

function Bake.document(doc: Document, settings: Settings?, options: Options?): Result
	local resolved = Bake.settings(doc, settings)
	local length = max(doc.length, 0)
	local evalOptions: EvalOptions = {
		presets = if options ~= nil and options.presets ~= nil
			then options.presets
			else doc.presets,
		fps = doc.fps,
	}
	local face = Bake.face(doc, resolved.rate, evalOptions.presets)
	local rig = if options ~= nil then options.rig else nil
	if rig ~= nil then
		doc = RigSolve.flatten(doc :: any, rig, evalOptions) :: any
	end
	doc = LayerEval.flatten(doc :: any, evalOptions) :: any
	for _, spec in if options ~= nil then options.movement or {} else {} do
		doc = MovementFold.flatten(doc, spec, evalOptions)
	end
	local limit = if options ~= nil and options.offenders ~= nil
		then options.offenders
		else Bake.OFFENDERS
	local onJoint = if options ~= nil then options.onJoint else nil

	local names: { string } = {}
	for name in doc.joints do
		table.insert(names, name)
	end
	table.sort(names)

	local joints: { [string]: Joint } = {}
	local rows: { ChannelReport } = {}
	local problems: { Problem } = {}
	local totalKeys, bytes = 0, Bake.SIZE.clip
	for done, name in names do
		local joint, outputs = bakeJoint(doc.joints[name], length, resolved, evalOptions)
		if onJoint ~= nil then
			onJoint(done, #names)
		end
		if joint == nil then
			continue
		end
		joints[name] = joint
		bytes += Bake.SIZE.joint
		for _, output in outputs do
			if output.dropped then
				continue
			end
			local count = if output.quaternion then #output.rotationKeys else #output.keys
			local size = Bake.SIZE.curve
				+ count
					* (if output.quaternion then Bake.SIZE.rotationKey else Bake.SIZE.floatKey)
			table.insert(rows, {
				joint = name,
				channel = output.name,
				keys = count,
				bytes = size,
				rate = output.rate,
			})
			totalKeys += count
			bytes += size
		end
		local stray = joint.error
		if stray.rotation > resolved.rotation + Bake.SLACK then
			table.insert(problems, problem(name, "Rotation", stray.rotation, stray.rotationAt))
		end
		if stray.position > resolved.position + Bake.SLACK then
			table.insert(problems, problem(name, "Position", stray.position, stray.positionAt))
		end
	end

	local offenders = table.clone(rows)
	table.sort(offenders, function(a: ChannelReport, b: ChannelReport): boolean
		if a.keys ~= b.keys then
			return a.keys > b.keys
		elseif a.joint ~= b.joint then
			return a.joint < b.joint
		end
		return a.channel < b.channel
	end)
	for i = #offenders, max(limit, 0) + 1, -1 do
		offenders[i] = nil
	end

	return {
		joints = joints,
		report = {
			channels = rows,
			offenders = offenders,
			overTolerance = problems,
			totalKeys = totalKeys,
			bytes = bytes,
			rate = resolved.rate,
			position = resolved.position,
			rotation = resolved.rotation,
		},
		hash = Bake.hash(joints, face),
		length = length,
		face = face,
	}
end

return Bake
