--!strict
--!native
--!optimize 2

local Modifiers = require(script.Parent.Modifiers)
local Pose = require(script.Parent.Pose)
local SpaceSolve = require(script.Parent.SpaceSolve)

local CameraEval = {}

export type CameraTrack = {
	rotationMode: Pose.RotationMode,
	channels: { [string]: Modifiers.Channel },
	spaces: { SpaceSolve.SpaceSegment }?,
}

export type Resolver = (target: SpaceSolve.SpaceTarget) -> CFrame?

export type Context = {
	origin: CFrame?,
	resolve: Resolver?,
	presets: { [string]: any }?,
	fps: number?,
}

CameraEval.DEFAULT_FOV = 70
CameraEval.MIN_FOV = 1
CameraEval.MAX_FOV = 120

CameraEval.FOV_CHANNEL = "fov"

CameraEval.WORLD = table.freeze({ kind = "World" }) :: SpaceSolve.SpaceTarget

local ADDRESS = "Camera"

local EMPTY: Context = table.freeze({})

local function optionsOf(context: Context): Modifiers.EvalOptions
	return { presets = context.presets, fps = context.fps }
end

function CameraEval.hasKeys(camera: CameraTrack?): boolean
	if camera == nil then
		return false
	end
	for _, channel in camera.channels do
		if #channel.keys > 0 then
			return true
		end
	end
	return false
end

function CameraEval.clampFov(fov: number): number
	if fov ~= fov then
		return CameraEval.DEFAULT_FOV
	end
	return math.clamp(fov, CameraEval.MIN_FOV, CameraEval.MAX_FOV)
end

function CameraEval.fovAt(camera: CameraTrack, t: number, context: Context?): number
	local channel = camera.channels[CameraEval.FOV_CHANNEL]
	if channel == nil then
		return CameraEval.DEFAULT_FOV
	end
	return CameraEval.clampFov(Modifiers.evaluate(channel, t, optionsOf(context or EMPTY)))
end

function CameraEval.valueAt(camera: CameraTrack, t: number, context: Context?): CFrame
	return Pose.evaluate(camera :: any, t, optionsOf(context or EMPTY))
end

function CameraEval.stateAt(camera: CameraTrack, t: number): SpaceSolve.State
	return SpaceSolve.stateAt(camera.spaces, CameraEval.WORLD, t)
end

local function remembering(resolve: Resolver?): Resolver
	local seen: { [SpaceSolve.SpaceTarget]: CFrame | false } = {}
	return function(target: SpaceSolve.SpaceTarget): CFrame?
		local hit = seen[target]
		if hit == nil then
			local placed = if resolve ~= nil then resolve(target) else nil
			seen[target] = placed or false
			return placed
		end
		return if hit == false then nil else hit
	end
end

local function rigOf(camera: CameraTrack, context: Context, resolve: Resolver): SpaceSolve.Rig
	local origin = context.origin or CFrame.identity
	return {
		root = origin,
		world = origin,
		joints = {
			[ADDRESS] = {
				parentOffset = CFrame.identity,
				childOffset = CFrame.identity,
				spaces = camera.spaces,
				starting = CameraEval.WORLD,
			},
		},
		elsewhere = resolve,
	}
end

local function seconds(t: number): string
	return string.format("%.2f s", t)
end

local function describe(target: SpaceSolve.SpaceTarget): string
	if target.kind == "Joint" then
		return `{target.joint or "a joint"} of the rig in slot '{target.slot or "?"}'`
	end
	return `the rig in slot '{target.slot or "?"}'`
end

local function unplaced(camera: CameraTrack, t: number, resolve: Resolver): string?
	local state = CameraEval.stateAt(camera, t)
	for _, target in { state.target, state.from } do
		if target ~= nil and target.slot ~= nil and resolve(target) == nil then
			return `At {seconds(t)} the camera follows {describe(target)}, which is not placed yet.`
		end
	end
	return nil
end

function CameraEval.evaluate(
	camera: CameraTrack,
	t: number,
	context: Context?
): (CFrame?, number, string?)
	local ctx = context or EMPTY
	local fov = CameraEval.fovAt(camera, t, ctx)
	local resolve = remembering(ctx.resolve)
	local missing = unplaced(camera, t, resolve)
	if missing ~= nil then
		return nil, fov, missing
	end
	local solved, problem = SpaceSolve.solve(
		rigOf(camera, ctx, resolve),
		t,
		function(_, time: number): CFrame
			return CameraEval.valueAt(camera, time, ctx)
		end
	)
	if solved == nil then
		return nil, fov, `The camera cannot be placed at {seconds(t)}: {problem}`
	end
	return solved.pivots[ADDRESS], fov, nil
end

local function frameOf(target: SpaceSolve.SpaceTarget, context: Context, resolve: Resolver): CFrame?
	if target.slot ~= nil then
		return resolve(target)
	end
	return context.origin or CFrame.identity
end

function CameraEval.toValue(
	camera: CameraTrack,
	t: number,
	world: CFrame,
	context: Context?
): (CFrame?, string?)
	local ctx = context or EMPTY
	local resolve = remembering(ctx.resolve)
	local target = CameraEval.stateAt(camera, t).target
	local frame = frameOf(target, ctx, resolve)
	if frame == nil then
		return nil,
			`At {seconds(t)} the camera follows {describe(target)}, which is not placed yet.`
	end
	return SpaceSolve.hold(world, frame), nil
end

function CameraEval.compensate(
	camera: CameraTrack,
	t: number,
	target: SpaceSolve.SpaceTarget,
	context: Context?
): (CFrame?, string?)
	local ctx = context or EMPTY
	local resolve = remembering(ctx.resolve)
	local missing = unplaced(camera, t, resolve)
	if missing == nil and target.slot ~= nil and resolve(target) == nil then
		missing =
			`At {seconds(t)} the camera would follow {describe(target)}, which is not placed yet.`
	end
	if missing ~= nil then
		return nil, missing
	end
	local value, problem = SpaceSolve.compensate(
		rigOf(camera, ctx, resolve),
		t,
		function(_, time: number): CFrame
			return CameraEval.valueAt(camera, time, ctx)
		end,
		ADDRESS,
		target
	)
	if value == nil then
		return nil, `The camera cannot be placed at {seconds(t)}: {problem}`
	end
	return value, nil
end

return CameraEval
