--!strict
--!native
--!optimize 2

local Pose = require(script.Parent.Pose)

local Fabrik = {}

export type JointLimit = {
	x: { number }?,
	y: { number }?,
	z: { number }?,
}

export type Link = {
	parentOffset: CFrame,
	childOffset: CFrame,
	transform: CFrame?,
	limit: JointLimit?,
	stiffness: number?,
}

export type Chain = {
	parentWorld: CFrame,
	links: { Link },
}

export type Settings = {
	pole: Vector3?,
	poleAngle: number?,
	stretch: number?,
	softness: number?,
	orientTip: (boolean | number)?,
	bend: Vector3?,
	iterations: number?,
	tolerance: number?,
	tip: CFrame?,
	share: number?,
	slideIn: (boolean | number)?,
	length: Vector3?,
	lean: number?,
}

export type Result = {
	transforms: { CFrame },
	reached: boolean,
	distance: number,
	stretch: number,
	passes: number,
}

Fabrik.ITERATIONS = 20

Fabrik.TOLERANCE = 1e-3

Fabrik.BEND = Vector3.new(0, 0, -1)

local NUDGE = 0.05

local STALL = 1e-7

local CRAWL = 0.9

local EPSILON = 1e-6

local abs, atan2, sin, pi = math.abs, math.atan2, math.sin, math.pi

local function unit(v: Vector3): Vector3?
	local length = v.Magnitude
	if length < EPSILON then
		return nil
	end
	return v / length
end

local function perpendicular(v: Vector3): Vector3
	local other = if abs(v.X) < 0.9 then Vector3.xAxis else Vector3.yAxis
	return v:Cross(other).Unit
end

local function across(v: Vector3, axis: Vector3): Vector3?
	return unit(v - axis * v:Dot(axis))
end

local function arc(a: Vector3, b: Vector3): CFrame
	local axis = a:Cross(b)
	local sine = axis.Magnitude
	local cosine = a:Dot(b)
	if sine < EPSILON then
		if cosine > 0 then
			return CFrame.identity
		end
		return CFrame.fromAxisAngle(perpendicular(a), pi)
	end
	return CFrame.fromAxisAngle(axis / sine, atan2(sine, cosine))
end

function Fabrik.clamp(rotation: CFrame, limit: JointLimit): CFrame
	local angles = Pose.toEuler(rotation, "XYZ")
	local changed = false
	local function clampAxis(value: number, range: { number }?): number
		if range == nil then
			return value
		end
		local low, high = range[1], range[2]
		if value < low then
			changed = true
			return low
		elseif value > high then
			changed = true
			return high
		end
		return value
	end
	local rx = clampAxis(angles.rx, limit.x)
	local ry = clampAxis(angles.ry, limit.y)
	local rz = clampAxis(angles.rz, limit.z)
	if not changed then
		return rotation
	end
	return Pose.fromValues("XYZ", { rx = rx, ry = ry, rz = rz })
end

function Fabrik.within(rotation: CFrame, limit: JointLimit, slack: number?): boolean
	local angles = Pose.toEuler(rotation, "XYZ")
	local give = slack or 1e-4
	for axis, value in { x = angles.rx, y = angles.ry, z = angles.rz } do
		local range = (limit :: any)[axis]
		if range ~= nil and (value < range[1] - give or value > range[2] + give) then
			return false
		end
	end
	return true
end

function Fabrik.frames(chain: Chain, transforms: { CFrame }?): { CFrame }
	local frames: { CFrame } = {}
	local parentEnd = chain.parentWorld
	for index, link in chain.links do
		local transform = if transforms then transforms[index] else link.transform
		local frame = parentEnd * link.parentOffset * (transform or CFrame.identity)
		frames[index] = frame
		parentEnd = frame * link.childOffset:Inverse()
	end
	return frames
end

function Fabrik.solve(chain: Chain, target: CFrame, settings: Settings?): Result
	local options: Settings = settings or {}
	local links = chain.links
	local count = #links
	assert(count >= 2, "Fabrik.solve takes a chain of at least two joints")
	local goal = target.Position
	local tolerance = options.tolerance or Fabrik.TOLERANCE
	local iterations = options.iterations or Fabrik.ITERATIONS

	local offsets: { Vector3 } = {}
	local start: { CFrame } = {}
	for index, link in links do
		local transform = link.transform or CFrame.identity
		offsets[index] = transform.Position
		start[index] = transform.Rotation
	end
	local between: { CFrame } = {}
	local bones: { Vector3 } = {}
	local lengths: { number } = {}
	local total = 0
	for index = 1, count - 1 do
		between[index] = links[index].childOffset:Inverse() * links[index + 1].parentOffset
		bones[index] = between[index] * offsets[index + 1]
		lengths[index] = bones[index].Magnitude
		total += lengths[index]
	end

	local rotations = table.clone(start)
	local bases: { CFrame } = table.create(count)
	local pivots: { Vector3 } = table.create(count)

	local function place(from: number)
		for index = from, count do
			if index == 1 then
				bases[1] = chain.parentWorld * links[1].parentOffset * CFrame.new(offsets[1])
			else
				local parent = index - 1
				bases[index] = bases[parent]
					* rotations[parent]
					* between[parent]
					* CFrame.new(offsets[index])
