	local away = goal - root
	local distance = away.Magnitude

	local scale = 1
	local stretch = options.stretch or 1
	if stretch > 1 and distance > total and total >= EPSILON then
		scale = math.min(stretch, distance / total)
		for index = 1, count - 1 do
			bones[index] *= scale
			lengths[index] *= scale
			offsets[index + 1] = between[index]:PointToObjectSpace(bones[index])
		end
		total *= scale
		place(2)
	end

	local function aim(index: number, point: Vector3): CFrame
