		local want = unit(bases[index]:VectorToObjectSpace(point - pivots[index]))
		if lengths[index] >= EPSILON and want ~= nil then
			local from = (start[index] * bones[index]) / lengths[index]
			rotation = arc(from, want) * start[index]
		end
		local link = links[index]
		local stiffness = link.stiffness or 0
		if stiffness > 0 then
			rotation = start[index]:Lerp(rotation, 1 - math.min(stiffness, 1))
		end
		if link.limit then
			rotation = Fabrik.clamp(rotation, link.limit)
		end
