		elseif bend == nil then
			local toward = side
			if toward == nil then
				local hint = (bases[1] * rotations[1]):VectorToWorldSpace(
					options.bend or Fabrik.BEND
				)
				toward = across(hint, axis) or perpendicular(axis)
			end
			for index = 2, count - 1 do
				local along = (index - 1) / (count - 1)
				points[index] += (toward :: Vector3) * (NUDGE * total * sin(pi * along))
			end
		end

		local limited = false
		for _, link in links do
			limited = limited or link.limit ~= nil
		end

		local gap = (pivots[count] - goal).Magnitude
		while passes < iterations and gap > tolerance do
			passes += 1
			points[count] = goal
			for index = count - 1, 1, -1 do
				local back = unit(points[index] - points[index + 1])
					or unit(pivots[index] - pivots[index + 1])
