			for index = 1, count - 1 do
				rotations[index] = aim(index, points[index + 1])
				place(index + 1)
			end
			points = table.clone(pivots)
			local now = (pivots[count] - goal).Magnitude
			local stalled = gap - now < STALL or (limited and now > CRAWL * gap)
			gap = now
			if stalled then
