--!optimize 2

local Aim = require(script.Parent.Aim)
local Fabrik = require(script.Parent.Fabrik)
local Modifiers = require(script.Parent.Modifiers)
local Pose = require(script.Parent.Pose)
local TwoBone = require(script.Parent.TwoBone)

local IkFk = {}

export type Solver = "TwoBone" | "FABRIK" | "Aim"

export type Chain = TwoBone.Chain
export type Settings = TwoBone.Settings
export type Result = TwoBone.Result

export type Snap = {
	target: CFrame,
	pole: Vector3,
	transforms: { CFrame },
	residual: number,
	residualPosition: number,
	blend: number,
}

local EPSILON = 1e-6

function IkFk.weight(
	channel: Modifiers.Channel?,
	t: number,
	options: Modifiers.EvalOptions?
): number
	if channel == nil then
		return 0
	end
	return math.clamp(Modifiers.evaluate(channel, t, options), 0, 1)
end

function IkFk.blend(fk: CFrame, ik: CFrame, w: number, move: number?): CFrame
	if move == nil or move == w then
		if w <= 0 then
			return fk
		elseif w >= 1 then
			return ik
		end
		return fk:Lerp(ik, w)
	end
	local turn = if w <= 0
		then fk.Rotation
		elseif w >= 1 then ik.Rotation
		else fk.Rotation:Lerp(ik.Rotation, w)
	local at = if move <= 0
		then fk.Position
		elseif move >= 1 then ik.Position
		else fk.Position:Lerp(ik.Position, move)
	return CFrame.new(at) * turn
end

function IkFk.pose(fk: { CFrame }, ik: { CFrame }, w: number, move: number?): { CFrame }
	local out: { CFrame } = table.create(#fk)
	for index, transform in fk do
		out[index] = IkFk.blend(transform, ik[index] or transform, w, move)
	end
	return out
end

local function atOrigin(chain: Chain): (Chain, Vector3)
	local origin = chain.parentWorld.Position
	return { parentWorld = chain.parentWorld - origin, links = chain.links }, origin
end

function IkFk.solve(chain: Chain, solver: Solver, target: CFrame, settings: Settings?): Result
	local near, origin = atOrigin(chain)
	local goal = target - origin
	local options = settings
	if settings ~= nil and settings.pole ~= nil then
		options = table.clone(settings)
		options.pole = settings.pole - origin
	end
	if solver == "TwoBone" then
		return TwoBone.solve(near, goal, options)
	elseif solver == "Aim" then
		return Aim.solve(near, goal, options)
	end
	return Fabrik.solve(near, goal, options)
end

local function posedAs(chain: Chain, transforms: { CFrame }): Chain
	local links = table.create(#chain.links)
	for index, link in chain.links do
		local copy = table.clone(link)
		copy.transform = transforms[index]
		links[index] = copy
	end
	return { parentWorld = chain.parentWorld, links = links }
end

function IkFk.evaluate(
	chain: Chain,
	solver: Solver,
	fk: { CFrame },
	target: CFrame,
	w: number,
	settings: Settings?,
	move: number?
): { CFrame }
	if w <= 0 and (move == nil or move <= 0) then
		return fk
	end
	local ik = IkFk.solve(posedAs(chain, fk), solver, target, settings).transforms
	return IkFk.pose(fk, ik, w, move)
end

function IkFk.snapFk(
	shown: { CFrame },
	rotationModes: { Pose.RotationMode },
	previous: { Pose.Values }?
): { Pose.Values }
	local out: { Pose.Values } = table.create(#shown)
	for index, transform in shown do
		out[index] = Pose.toValues(
			transform,
			rotationModes[index],
			if previous then previous[index] else nil
		)
	end
	return out
end

local function bendNear(
	chain: Chain,
	solver: Solver,
	settings: Settings?
): (Vector3, Vector3, Vector3, Vector3)
	if solver == "TwoBone" and #chain.links == 3 then
		local side, axis, root, middle = TwoBone.bendOf(chain, settings)
		return side, axis, root, middle - side * (middle - root):Dot(side)
	end
	local frames = Fabrik.frames(chain)
	local count = #frames
	local root = frames[1].Position
	local tip = frames[count].Position
	local line = tip - root
	if line.Magnitude < EPSILON then
		line = frames[2].Position - root
	end
	local axis = if line.Magnitude >= EPSILON then line.Unit else Vector3.yAxis
	local sum = Vector3.zero
	local along = 0
	for index = 2, count - 1 do
		local offset = frames[index].Position - root
		sum += offset - axis * offset:Dot(axis)
		along += offset:Dot(axis)
	end
	local level = root + axis * (if count > 2 then along / (count - 2) else 0)
	if sum.Magnitude >= EPSILON then
		return sum.Unit, axis, root, level
	end
	local hint = frames[1]:VectorToWorldSpace((settings and settings.bend) or Fabrik.BEND)
	local side = hint - axis * hint:Dot(axis)
	if side.Magnitude < EPSILON then
		local other = if math.abs(axis.X) < 0.9 then Vector3.xAxis else Vector3.yAxis
		side = axis:Cross(other)
	end
	return side.Unit, axis, root, level
end

local function bendOf(
	chain: Chain,
	solver: Solver,
	settings: Settings?
): (Vector3, Vector3, Vector3, Vector3)
	local near, origin = atOrigin(chain)
	local side, axis, root, level = bendNear(near, solver, settings)
	return side, axis, root + origin, level + origin
end

local function residuals(chain: Chain, a: { CFrame }, b: { CFrame }): (number, number)
	local turned = 0
	for index, transform in a do
		local _, angle = (transform.Rotation:Inverse() * b[index].Rotation):ToAxisAngle()
		turned = math.max(turned, math.abs(angle))
	end
	local moved = 0
	local framesA, framesB = Fabrik.frames(chain, a), Fabrik.frames(chain, b)
	for index, frame in framesA do
		moved = math.max(moved, (frame.Position - framesB[index].Position).Magnitude)
	end
	return turned, moved
end

function IkFk.snapIk(chain: Chain, solver: Solver, settings: Settings?, shown: { CFrame }?): Snap
	local onScreen: { CFrame } = shown or table.create(#chain.links)
	if shown == nil then
		for index, link in chain.links do
			onScreen[index] = link.transform or CFrame.identity
		end
	end
	local showing = posedAs(chain, onScreen)
	local frames = Fabrik.frames(showing)
	local target = frames[#frames]
	local pole: Vector3

	if solver == "Aim" then
		target = target * ((settings and settings.tip) or CFrame.identity)
		local given = settings and settings.pole
		if given ~= nil then
			pole = given
		else
			local root = frames[1].Position
			local line = target.Position - root
			local length = line.Magnitude
			local axis = if length >= EPSILON then line / length else Vector3.yAxis
			local side = Aim.perpendicularTo(axis, target.RightVector)
			local angle = -((settings and settings.poleAngle) or 0)
			local turned = side * math.cos(angle) + axis:Cross(side) * math.sin(angle)
			pole = root + line * 0.5 + turned * math.max(length, 1)
		end
	else
		local side, axis, root, level = bendOf(showing, solver, settings)
		local length = 0
		for index = 2, #frames do
			length += (frames[index].Position - frames[index - 1].Position).Magnitude
		end
		local along = root + axis * (level - root):Dot(axis)
		local away = level - along + side * math.max(length, 1)
		local angle = -((settings and settings.poleAngle) or 0)
		pole = along + away * math.cos(angle) + axis:Cross(away) * math.sin(angle)
	end

	local solveWith: Settings = table.clone(settings or {})
	solveWith.pole = pole
	local transforms = IkFk.solve(chain, solver, target, solveWith).transforms
	local residual, residualPosition = residuals(chain, onScreen, transforms)
	return {
		target = target,
		pole = pole,
		transforms = transforms,
		residual = residual,
		residualPosition = residualPosition,
		blend = 1,
	}
end

return IkFk
