local Interp = {}

export type Interp =
	"Constant"
	| "Linear"
	| "Bezier"
	| "Sine"
	| "Quad"
	| "Cubic"
	| "Quart"
	| "Quint"
	| "Expo"
	| "Circ"
	| "Back"
	| "Bounce"
	| "Elastic"

export type Easing = "In" | "Out" | "InOut" | "OutIn" | "Auto"

export type HandleType = "Free" | "Aligned" | "Vector" | "Auto" | "AutoClamped"

export type Params = { back: number?, amplitude: number?, period: number? }

export type Key = {
	t: number,
	v: number,
	interp: Interp?,
	easing: Easing?,
	handleL: { number }?,
	handleR: { number }?,
	handleType: HandleType?,
	params: Params?,
	preset: string?,
}

export type Channel = { keys: { Key }, modifiers: { any }?, interp: Interp? }

export type PresetPoint = {
	x: number,
	y: number,
	handleL: { number }?,
	handleR: { number }?,
}

export type EasingPreset = { points: { PresetPoint } }

export type Smoothing = "None" | "ContinuousAcceleration"

export type HandleOptions = {
	smoothing: Smoothing?,
	cyclic: boolean?,
	leading: { [number]: "L" | "R" }?,
	fps: number?,
}

export type EvalOptions = {
	presets: { [string]: EasingPreset }?,
	smoothing: Smoothing?,
	cyclic: boolean?,
	leading: { [number]: "L" | "R" }?,
	fps: number?,
}

Interp.INTERPS = {
	"Constant",
	"Linear",
	"Bezier",
	"Sine",
	"Quad",
	"Cubic",
	"Quart",
	"Quint",
	"Expo",
	"Circ",
	"Back",
	"Bounce",
	"Elastic",
}
Interp.EASINGS = { "Auto", "In", "Out", "InOut", "OutIn" }
Interp.HANDLE_TYPES = { "AutoClamped", "Auto", "Vector", "Aligned", "Free" }
Interp.SMOOTHINGS = { "ContinuousAcceleration", "None" }

Interp.DEFAULT_INTERP = "Bezier" :: Interp
Interp.DEFAULT_EASING = "Auto" :: Easing
Interp.DEFAULT_HANDLE_TYPE = "AutoClamped" :: HandleType
Interp.DEFAULT_SMOOTHING = "ContinuousAcceleration" :: Smoothing

Interp.DEFAULTS = {
	back = 1.70158,
	amplitude = 0.8,
	period = 4.1 / 24,
}

local KNOWN_INTERP: { [string]: boolean } = {}
for _, name in Interp.INTERPS do
	KNOWN_INTERP[name] = true
end
local KNOWN_EASING: { [string]: boolean } = {}
for _, name in Interp.EASINGS do
	KNOWN_EASING[name] = true
end
local KNOWN_HANDLE: { [string]: boolean } = {}
for _, name in Interp.HANDLE_TYPES do
	KNOWN_HANDLE[name] = true
end

function Interp.isInterp(name: any): boolean
	return type(name) == "string" and KNOWN_INTERP[name] == true
end

function Interp.isEasing(name: any): boolean
	return type(name) == "string" and KNOWN_EASING[name] == true
end

function Interp.isHandleType(name: any): boolean
	return type(name) == "string" and KNOWN_HANDLE[name] == true
end

local abs, sqrt, sin, cos, asin = math.abs, math.sqrt, math.sin, math.cos, math.asin
local min, max = math.min, math.max
local pi = math.pi

type EaseFn = (
	time: number,
	begin: number,
	change: number,
	duration: number,
	back: number,
	amplitude: number,
	period: number
) -> number

local function sqrt0(x: number): number
	return sqrt(max(0, x))
end

local function bounceOut(time: number, begin: number, change: number, duration: number): number
	time /= duration
	if time < 1 / 2.75 then
		return change * (7.5625 * time * time) + begin
	elseif time < 2 / 2.75 then
		time -= 1.5 / 2.75
		return change * (7.5625 * time * time + 0.75) + begin
	elseif time < 2.5 / 2.75 then
		time -= 2.25 / 2.75
		return change * (7.5625 * time * time + 0.9375) + begin
	end
	time -= 2.625 / 2.75
	return change * (7.5625 * time * time + 0.984375) + begin
end

local function bounceIn(time: number, begin: number, change: number, duration: number): number
	return change - bounceOut(duration - time, 0, change, duration) + begin
end

local function elasticBlend(
	time: number,
	change: number,
	duration: number,
	amplitude: number,
	s: number
): number
	local f = 1
	if change ~= 0 then
		local reach = abs(s)
		if amplitude ~= 0 then
			f *= amplitude / abs(change)
		else
			f = 0
		end
		local d = abs(time * duration)
		if d < reach then
			local l = d / reach
			f = f * l + (1 - l)
		end
	end
	return f
end

local function elasticShape(
	time: number,
	change: number,
	duration: number,
	amplitude: number,
	period: number,
	autoPeriod: number
): (number, number, number, number)
	if period == 0 then
		period = duration * autoPeriod
	end
	if amplitude == 0 or amplitude < abs(change) then
		local s = period / 4
		return period, change, s, elasticBlend(time, change, duration, amplitude, s)
	end
	return period, amplitude, period / (2 * pi) * asin(change / amplitude), 1
end

local POW_MIN = 2 ^ -10
local POW_SCALE = 1 / (1 - POW_MIN)

local function expoIn(time: number, begin: number, change: number, duration: number): number
	if time == 0 then
		return begin
	end
	return change * (2 ^ (10 * (time / duration - 1)) - POW_MIN) * POW_SCALE + begin
end

local function expoOut(time: number, begin: number, change: number, duration: number): number
	if time == 0 then
		return begin
	end
	return change * (1 - (2 ^ (-10 * time / duration) - POW_MIN) * POW_SCALE) + begin
end

local function elasticIn(autoPeriod: number): EaseFn
	return function(time, begin, change, duration, _, amplitude, period)
		if time == 0 then
			return begin
		end
		time /= duration
		if time == 1 then
			return begin + change
		end
		time -= 1
		local p, a, s, f = elasticShape(time, change, duration, amplitude, period, autoPeriod)
		return -f * (a * 2 ^ (10 * time) * sin((time * duration - s) * (2 * pi) / p)) + begin
