			time /= duration
			return change * time * time * time + begin
		end,
		function(time, begin, change, duration)
			time = time / duration - 1
			return change * (time * time * time + 1) + begin
		end,
		function(time, begin, change, duration)
			time /= duration / 2
			if time < 1 then
				return change / 2 * time * time * time + begin
			end
			time -= 2
			return change / 2 * (time * time * time + 2) + begin
		end,
	},
	Quart = {
		function(time, begin, change, duration)
			time /= duration
			return change * time * time * time * time + begin
		end,
		function(time, begin, change, duration)
			time = time / duration - 1
			return -change * (time * time * time * time - 1) + begin
		end,
		function(time, begin, change, duration)
			time /= duration / 2
			if time < 1 then
				return change / 2 * time * time * time * time + begin
			end
			time -= 2
			return -change / 2 * (time * time * time * time - 2) + begin
		end,
	},
	Quint = {
		function(time, begin, change, duration)
			time /= duration
			return change * time * time * time * time * time + begin
		end,
		function(time, begin, change, duration)
			time = time / duration - 1
			return change * (time * time * time * time * time + 1) + begin
		end,
		function(time, begin, change, duration)
			time /= duration / 2
			if time < 1 then
				return change / 2 * time * time * time * time * time + begin
			end
			time -= 2
			return change / 2 * (time * time * time * time * time + 2) + begin
		end,
	},
	Expo = {
		expoIn,
		expoOut,
		function(time, begin, change, duration)
			local half, changeHalf = duration / 2, change / 2
			if time <= half then
				return expoIn(time, begin, changeHalf, half)
			end
			return expoOut(time - half, begin + changeHalf, changeHalf, half)
		end,
	},
	Circ = {
		function(time, begin, change, duration)
			time /= duration
			return -change * (sqrt0(1 - time * time) - 1) + begin
		end,
		function(time, begin, change, duration)
			time = time / duration - 1
			return change * sqrt0(1 - time * time) + begin
		end,
		function(time, begin, change, duration)
			time /= duration / 2
			if time < 1 then
				return -change / 2 * (sqrt0(1 - time * time) - 1) + begin
			end
			time -= 2
			return change / 2 * (sqrt0(1 - time * time) + 1) + begin
		end,
	},
	Back = {
		function(time, begin, change, duration, s)
			time /= duration
			return change * time * time * ((s + 1) * time - s) + begin
		end,
		function(time, begin, change, duration, s)
			time = time / duration - 1
			return change * (time * time * ((s + 1) * time + s) + 1) + begin
		end,
		function(time, begin, change, duration, s)
			s *= 1.525
			time /= duration / 2
			if time < 1 then
				return change / 2 * (time * time * ((s + 1) * time - s)) + begin
			end
			time -= 2
			return change / 2 * (time * time * ((s + 1) * time + s) + 2) + begin
		end,
	},
	Bounce = {
		bounceIn,
		bounceOut,
		function(time, begin, change, duration)
			if time < duration / 2 then
				return bounceIn(time * 2, 0, change, duration) * 0.5 + begin
			end
			return bounceOut(time * 2 - duration, 0, change, duration) * 0.5 + change * 0.5 + begin
		end,
	},
	Elastic = {
		elasticIn(0.3),
		elasticOut(0.3),
		function(time, begin, change, duration, _, amplitude, period)
			if time == 0 then
				return begin
			end
			time /= duration / 2
			if time == 2 then
				return begin + change
			end
			time -= 1
			local p, a, s, f = elasticShape(time, change, duration, amplitude, period, 0.45)
			if time < 0 then
				f *= -0.5
				return f * (a * 2 ^ (10 * time) * sin((time * duration - s) * (2 * pi) / p)) + begin
			end
			time = -time
			f *= 0.5
			return f * (a * 2 ^ (10 * time) * sin((time * duration - s) * (2 * pi) / p))
				+ change
				+ begin
		end,
	},
}

local function outIn(out: EaseFn, into: EaseFn, backScale: number): EaseFn
	return function(time, begin, change, duration, back, amplitude, period)
		back *= backScale
		if time < duration / 2 then
			return out(time * 2, 0, change, duration, back, amplitude, period) * 0.5 + begin
		end
		return into(time * 2 - duration, 0, change, duration, back, amplitude, period) * 0.5
			+ change * 0.5
			+ begin
	end
end

for name, set in EASE do
	if name == "Elastic" then
		set[4] = outIn(elasticOut(0.45), elasticIn(0.45), 1)
	else
		set[4] = outIn(set[2], set[1], if name == "Back" then 1.525 else 1)
	end
end

local AUTO_OUT: { [string]: boolean } = { Back = true, Bounce = true, Elastic = true }

local DIRECTION: { [string]: number } = { In = 1, Out = 2, InOut = 3, OutIn = 4 }

function Interp.ease(
	mode: Interp,
	easing: Easing?,
	time: number,
	begin: number,
	change: number,
	duration: number,
	params: Params?
): number
	local set = EASE[mode]
	if set == nil or duration <= 0 then
		return begin
	end
	local direction = easing or "Auto"
	local index = if direction == "Auto"
		then (if AUTO_OUT[mode] then 2 else 1)
		else DIRECTION[direction] or 1
	local defaults = Interp.DEFAULTS
	local back, amplitude, period = defaults.back, defaults.amplitude, defaults.period
	if params ~= nil then
		back = params.back or back
		amplitude = params.amplitude or amplitude
		period = params.period or period
	end
	return set[index](time, begin, change, duration, back, amplitude, period)
end

local FLAT_EPSILON = 1.1920929e-07

function Interp.bezier(
	x0: number,
	y0: number,
	x1: number,
	y1: number,
	x2: number,
	y2: number,
	x3: number,
	y3: number,
	t: number
): number
	if
		abs(y0 - y3) < FLAT_EPSILON
		and abs(y1 - y2) < FLAT_EPSILON
		and abs(y2 - y3) < FLAT_EPSILON
	then
		return y0
	end
	local len = x3 - x0
	if len <= 0 then
		return y0
	end
	local reach1, reach2 = abs(x0 - x1), abs(x3 - x2)
	if reach1 + reach2 ~= 0 then
		if reach1 > len then
			local f = len / reach1
			x1 = x0 - f * (x0 - x1)
			y1 = y0 - f * (y0 - y1)
		end
		if reach2 > len then
			local f = len / reach2
			x2 = x3 - f * (x3 - x2)
			y2 = y3 - f * (y3 - y2)
		end
	end

	local a1, a2 = (x1 - x0) / len, (x2 - x0) / len
	local target = (t - x0) / len
	if target <= 0 then
		return y0
	elseif target >= 1 then
		return y3
	end
	local c1 = 3 * a1
	local c2 = 3 * (a2 - 2 * a1)
	local c3 = 1 - 3 * a2 + 3 * a1

	local lo, hi = 0, 1
	local u = target
	for _ = 1, 60 do
		local f = ((c3 * u + c2) * u + c1) * u - target
		if abs(f) < 1e-13 then
			break
		end
		if f < 0 then
			lo = u
		else
			hi = u
		end
		local slope = (3 * c3 * u + 2 * c2) * u + c1
		local nextU = if slope ~= 0 then u - f / slope else -1
		if nextU <= lo or nextU >= hi then
			nextU = (lo + hi) / 2
		end
		u = nextU
		if hi - lo < 1e-15 then
			break
		end
	end

	local s = 1 - u
	return s * s * s * y0 + 3 * s * s * u * y1 + 3 * s * u * u * y2 + u * u * u * y3
end

local function shapeAt(points: { PresetPoint }, x: number): number
	local n = #points
	local first, last = points[1], points[n]
	if x <= first.x then
		return first.y
	elseif x >= last.x then
		return last.y
	end
	local lo, hi = 1, n
	while hi - lo > 1 do
		local mid = (lo + hi) // 2
		if points[mid].x <= x then
			lo = mid
		else
			hi = mid
		end
	end
	local p, q = points[lo], points[lo + 1]
	local right, left = p.handleR, q.handleL
	if right == nil and left == nil then
		return p.y + (q.y - p.y) * (x - p.x) / (q.x - p.x)
	end
	local dx, dy = q.x - p.x, q.y - p.y
	local rx, ry = dx / 3, dy / 3
	if right ~= nil then
		rx, ry = right[1], right[2]
	end
	local lx, ly = -dx / 3, -dy / 3
	if left ~= nil then
		lx, ly = left[1], left[2]
	end
	return Interp.bezier(p.x, p.y, p.x + rx, p.y + ry, q.x + lx, q.y + ly, q.x, q.y, x)
end

function Interp.presetAt(preset: EasingPreset, x: number): number
	local points = preset.points
	if points == nil or #points < 2 then
		return x
	end
	return shapeAt(points, x)
end

local BOUNCE_KNOTS: { [string]: { number } } = {
	Out = { 1 / 2.75, 2 / 2.75, 2.5 / 2.75 },
	In = { 0.25 / 2.75, 0.75 / 2.75, 1.75 / 2.75 },
}

local SEAMED: { [string]: boolean } = {
	Quad = true,
	Cubic = true,
	Quart = true,
	Quint = true,
	Expo = true,
	Circ = true,
	Back = true,
	Bounce = true,
	Elastic = true,
}

local SMOOTH = 1e-6

local function directionOf(mode: string, easing: string?): string
	if easing == nil or easing == "Auto" then
		return if AUTO_OUT[mode] then "Out" else "In"
	elseif easing == "Out" or easing == "InOut" or easing == "OutIn" then
		return easing
	end
	return "In"
end

local function presetKnots(
	points: { PresetPoint },
	from: number,
	duration: number,
	into: { number },
	steep: { number }?
)
	local n = #points
	for i, p in points do
		local t = from + p.x * duration
		if p.x < 0 or p.x > 1 then
			continue
		end
		local before, after = points[i - 1], points[i + 1]
		local lx, ly, rx, ry = 0, 0, 0, 0
		if before ~= nil then
			local handle = p.handleL
			if handle ~= nil then
				lx, ly = handle[1], handle[2]
			else
				lx, ly = (before.x - p.x) / 3, (before.y - p.y) / 3
			end
		end
		if after ~= nil then
			local handle = p.handleR
			if handle ~= nil then
				rx, ry = handle[1], handle[2]
			else
				rx, ry = (after.x - p.x) / 3, (after.y - p.y) / 3
			end
		end
		if i > 1 and i < n and p.x > 0 and p.x < 1 then
			local left, right = sqrt(lx * lx + ly * ly), sqrt(rx * rx + ry * ry)
			local smooth = left > 0
				and right > 0
				and abs(lx * ry - ly * rx) <= SMOOTH * left * right
				and lx * rx + ly * ry < 0
			if not smooth then
				table.insert(into, t)
			end
		end
		if (before ~= nil and lx == 0 and ly ~= 0) or (after ~= nil and rx == 0 and ry ~= 0) then
			table.insert(into, t)
			if steep ~= nil then
				table.insert(steep, t)
			end
		end
	end
end

function Interp.easingKnots(
	channel: Channel,
	presets: { [string]: EasingPreset }?,
	into: { number }?,
	steep: { number }?
): { number }
	local out: { number } = into or {}
	local keys = channel.keys
	for i = 1, #keys - 1 do
		local a, b = keys[i], keys[i + 1]
		local duration = b.t - a.t
		if not (duration > 0) then
			continue
		end
		local preset = if a.preset ~= nil and presets ~= nil then presets[a.preset] else nil
		local points = if preset ~= nil then preset.points else nil
		if points ~= nil and #points >= 2 then
			presetKnots(points, a.t, duration, out, steep)
			continue
		end
		local mode: string = a.interp or channel.interp or "Bezier"
		if EASE[mode] == nil then
			continue
		end
		local direction = directionOf(mode, a.easing)
		if not SEAMED[mode] and direction ~= "OutIn" then
			continue
		end
		local middle = a.t + duration / 2
		if direction == "InOut" or direction == "OutIn" then
			table.insert(out, middle)
		end
		if mode == "Circ" then
			local verticals = if direction == "In"
				then { b.t }
				elseif direction == "Out" then { a.t }
				elseif direction == "OutIn" then { a.t, b.t }
				else { middle }
			for _, vertical in verticals do
				table.insert(out, vertical)
				if steep ~= nil then
					table.insert(steep, vertical)
				end
			end
		elseif mode == "Bounce" then
			if direction == "InOut" or direction == "OutIn" then
				local first = if direction == "InOut" then BOUNCE_KNOTS.In else BOUNCE_KNOTS.Out
				local second = if direction == "InOut" then BOUNCE_KNOTS.Out else BOUNCE_KNOTS.In
				for _, fraction in first do
					table.insert(out, a.t + fraction * duration / 2)
				end
				for _, fraction in second do
					table.insert(out, middle + fraction * duration / 2)
				end
			else
				for _, fraction in BOUNCE_KNOTS[direction] do
					table.insert(out, a.t + fraction * duration)
				end
			end
		elseif mode == "Elastic" then
			local params = a.params
			local amplitude = if params ~= nil and params.amplitude ~= nil
				then params.amplitude
				else Interp.DEFAULTS.amplitude
			local period = if params ~= nil and params.period ~= nil
				then params.period
				else Interp.DEFAULTS.period
			if period == 0 then
				period = duration
					* (if direction == "InOut" or direction == "OutIn" then 0.45 else 0.3)
			end
			local change = abs(b.v - a.v)
			if change > 0 and amplitude < change then
				local reach = abs(period) / 4
				local corners = if direction == "Out"
					then { a.t + reach }
					elseif direction == "In" then { b.t - reach }
					elseif direction == "OutIn" then { a.t + reach / 2, b.t - reach / 2 }
					else { middle - reach / 2, middle + reach / 2 }
				for _, t in corners do
					if t > a.t and t < b.t then
						table.insert(out, t)
					end
				end
			end
		end
	end
	return out
end

local AUTO_LENGTH = 2.5614

local function typeOf(key: Key): HandleType
	return key.handleType or "AutoClamped"
end

local function isAuto(kind: HandleType): boolean
	return kind == "Auto" or kind == "AutoClamped"
end

type Work = {
	lx: { number },
	ly: { number },
	rx: { number },
	ry: { number },
	locked: { boolean },
}

local function newWork(): Work
	return { lx = {}, ly = {}, rx = {}, ry = {}, locked = {} }
end

type Resolved = {
	smooth: boolean,
	cyclic: boolean,
	leading: { [number]: "L" | "R" }?,
	fps: number,
}

local function resolve(keys: { Key }, options: HandleOptions?): Resolved
	local n = #keys
	local smoothing = options and options.smoothing or Interp.DEFAULT_SMOOTHING
	local cyclic = options ~= nil
		and options.cyclic == true
		and n >= 2
		and isAuto(typeOf(keys[1]))
		and isAuto(typeOf(keys[n]))
	return {
		smooth = smoothing == "ContinuousAcceleration",
		cyclic = cyclic,
		leading = options and options.leading,
		fps = options and options.fps or 60,
	}
end

local function neighbour(
	keys: { Key },
	i: number,
	step: number,
	cyclic: boolean
): (number?, number?)
	local n = #keys
	local j = i + step
	if j >= 1 and j <= n then
		local k = keys[j]
		return k.t, k.v
	end
	if not cyclic then
		return nil, nil
	end
	local first, last = keys[1], keys[n]
	if step < 0 then
		local k = keys[n - 1]
		return k.t + first.t - last.t, k.v + first.v - last.v
	end
	local k = keys[2]
	return k.t + last.t - first.t, k.v + last.v - first.v
end

local function autoHandles(
	clamped: boolean,
	smooth: boolean,
	y2: number,
	py: number?,
	ny: number?,
	dax: number,
	day: number,
	dbx: number,
	dby: number
): (number?, number, number, number, boolean)
	local lenA = if dax == 0 then 1 else dax
	local lenB = if dbx == 0 then 1 else dbx
	local tx = dbx / lenB + dax / lenA
	local ty = dby / lenB + day / lenA
	local len = if smooth then 6 else tx * AUTO_LENGTH
	if len == 0 then
		return nil, 0, 0, 0, false
	end
	if not smooth then
		lenA = min(lenA, 5 * lenB)
		lenB = min(lenB, 5 * lenA)
	end
	local fa, fb = lenA / len, lenB / len
	local lx, ly, rx, ry = -tx * fa, -ty * fa, tx * fb, ty * fb
	local locked = false
	if clamped and py ~= nil and ny ~= nil then
		local below1, below2 = py - y2, ny - y2
		if (below1 <= 0 and below2 <= 0) or (below1 >= 0 and below2 >= 0) then
			ly, ry, locked = 0, 0, true
		else
			local leftCut, rightCut = false, false
			if below1 <= 0 then
				if py > y2 + ly then
					ly, leftCut = py - y2, true
				end
				if ny < y2 + ry then
					ry, rightCut = ny - y2, true
				end
			else
				if py < y2 + ly then
					ly, leftCut = py - y2, true
				end
				if ny > y2 + ry then
					ry, rightCut = ny - y2, true
				end
			end
			if leftCut and lx ~= 0 then
				ry = ly / lx * rx
			elseif rightCut and rx ~= 0 then
				ly = ry / rx * lx
			end
		end
	end
	return lx, ly, rx, ry, locked
end

local function align(w: Work, i: number, leadLeft: boolean, fps: number)
	local lx, ly, rx, ry = w.lx[i], w.ly[i], w.rx[i], w.ry[i]
	local lenA = sqrt((lx * fps) ^ 2 + ly * ly)
	local lenB = sqrt((rx * fps) ^ 2 + ry * ry)
	if lenA == 0 then
		lenA = 1
	end
	if lenB == 0 then
		lenB = 1
	end
	local ratio = lenA / lenB
	if leadLeft then
		if lenA > 1e-5 then
			rx, ry = -lx / ratio, -ly / ratio
		end
		if lenB > 1e-5 then
			lx, ly = -rx * ratio, -ry * ratio
		end
	else
		if lenB > 1e-5 then
			lx, ly = -rx * ratio, -ry * ratio
		end
		if lenA > 1e-5 then
			rx, ry = -lx / ratio, -ly / ratio
		end
	end
	w.lx[i], w.ly[i], w.rx[i], w.ry[i] = lx, ly, rx, ry
end

local function localPass(keys: { Key }, i: number, r: Resolved, w: Work)
	local n = #keys
	local key = keys[i]
	local kind = typeOf(key)
	local x2, y2 = key.t, key.v
	local px, py = neighbour(keys, i, -1, r.cyclic)
	local nx, ny = neighbour(keys, i, 1, r.cyclic)
	w.locked[i] = false

	local stored = key.handleL
	local storedR = key.handleR
	if px == nil and nx == nil then
		w.lx[i] = if stored then stored[1] else 0
		w.ly[i] = if stored then stored[2] else 0
		w.rx[i] = if storedR then storedR[1] else 0
		w.ry[i] = if storedR then storedR[2] else 0
		return
	end
	local x1, y1, x3, y3
	if px == nil then
		x1, y1 = 2 * x2 - (nx :: number), 2 * y2 - (ny :: number)
	else
		x1, y1 = px, py :: number
	end
	if nx == nil then
		x3, y3 = 2 * x2 - x1, 2 * y2 - y1
	else
		x3, y3 = nx, ny :: number
	end
	local dax, day = x2 - x1, y2 - y1
	local dbx, dby = x3 - x2, y3 - y2

	if kind == "Vector" then
		w.lx[i], w.ly[i] = -dax / 3, -day / 3
		w.rx[i], w.ry[i] = dbx / 3, dby / 3
		return
	end

	local lx, ly, rx, ry, locked =
		autoHandles(kind ~= "Auto", r.smooth, y2, py, ny, dax, day, dbx, dby)
	if lx == nil then
		lx, ly, rx, ry, locked = 0, 0, 0, 0, false
	end

	if isAuto(kind) then
		if not r.cyclic and (i == 1 or i == n) then
			ly, ry, locked = 0, 0, true
		end
		w.lx[i], w.ly[i], w.rx[i], w.ry[i] = lx :: number, ly, rx, ry
		w.locked[i] = locked
		return
	end

	w.lx[i] = if stored then stored[1] else lx :: number
	w.ly[i] = if stored then stored[2] else ly
	w.rx[i] = if storedR then storedR[1] else rx
	w.ry[i] = if storedR then storedR[2] else ry
	if kind == "Aligned" then
		local lead = r.leading and r.leading[i]
		local leadLeft = if stored and not storedR
			then true
			elseif storedR and not stored then false
			else lead == "L"
		align(w, i, leadLeft, r.fps)
	end
end

local function lockDuplicates(keys: { Key }, w: Work, from: number, to: number)
	for i = math.max(2, from), to do
		if keys[i - 1].t >= keys[i].t then
			w.locked[i - 1] = true
			w.locked[i] = true
		end
	end
end

local function solveTridiagonal(
	a: { number },
	b: { number },
	c: { number },
	d: { number },
	x: { number },
	count: number
): boolean
	local cp, dp = table.create(count, 0), table.create(count, 0)
	cp[1] = c[1] / b[1]
	dp[1] = d[1] / b[1]
	for i = 2, count do
		local den = b[i] - a[i] * cp[i - 1]
		cp[i] = c[i] / den
		dp[i] = (d[i] - a[i] * dp[i - 1]) / den
	end
	x[count] = dp[count]
	for i = count - 1, 1, -1 do
		x[i] = dp[i] - cp[i] * x[i + 1]
	end
	local first = x[1]
	return first == first and abs(first) ~= math.huge
end

local function solveCyclic(
	a: { number },
	b: { number },
	c: { number },
	d: { number },
	x: { number },
	count: number
): boolean
	if count < 1 then
		return false
	elseif count == 1 then
		x[1] = d[1] / (a[1] + b[1] + c[1])
		return x[1] == x[1] and abs(x[1]) ~= math.huge
	elseif count == 2 then
		return solveTridiagonal({ 0, a[2] + c[2] }, b, { a[1] + c[1], 0 }, d, x, 2)
	end
	local a1, cn = a[1], c[count]
	if a1 == 0 and cn == 0 then
		return solveTridiagonal(a, b, c, d, x, count)
	end
	local b2 = table.clone(b)
	b2[1] -= a1
	b2[count] -= cn
	local u = table.create(count, 0)
	u[1] = a1
	u[count] = cn
	local z = table.create(count, 0)
	if not solveTridiagonal(a, b2, c, u, z, count) then
		return false
	end
	if not solveTridiagonal(a, b2, c, d, x, count) then
		return false
	end
	local coeff = (x[1] + x[count]) / (1 + z[1] + z[count])
	for i = 1, count do
		x[i] -= coeff * z[i]
	end
	return true
end

local function solveWithLimits(
	a: { number },
	b: { number },
	c: { number },
	d: { number },
	h: { number },
	hmin: { number },
	hmax: { number },
	count: number
): boolean
	local a0, b0, c0, d0 = table.clone(a), table.clone(b), table.clone(c), table.clone(d)
	local pinned = table.create(count, false)
	local releases = table.create(count, 0)
	for _ = 1, 16 * count + 16 do
		if not solveCyclic(a, b, c, d, h, count) then
			return false
		end
		local overshoot, released = false, false
		local all, pinnedAny = false, false
		repeat
			for i = 1, count do
				local value = h[i]
				if value >= hmin[i] and value <= hmax[i] then
					continue
				end
				overshoot = true
				local target = if value > hmax[i] then hmax[i] else hmin[i]
				if target ~= 0 or all then
					pinned[i] = true
					a[i], b[i], c[i], d[i] = 0, 1, 0, target
					pinnedAny = true
				end
			end
			all = true
		until not overshoot or pinnedAny
		if not pinnedAny then
			for i = 1, count do
				if not pinned[i] or releases[i] >= 2 then
					continue
				end
				local before = if i == 1 then count else i - 1
				local after = if i == count then 1 else i + 1
				local state = a0[i] * h[before] + b0[i] * h[i] + c0[i] * h[after] - d0[i]
				local relax = -state * b0[i]
				if (relax > 0 and h[i] < hmax[i]) or (relax < 0 and h[i] > hmin[i]) then
					a[i], b[i], c[i], d[i] = a0[i], b0[i], c0[i], d0[i]
					pinned[i] = false
					releases[i] += 1
					released = true
				end
			end
		end
		if not overshoot and not released then
			return true
		end
	end
	return true
end

local function writeRight(keys: { Key }, w: Work, k: number, dv: number, mirror: boolean)
	local kind = typeOf(keys[k])
	if not (isAuto(kind) or kind == "Vector") then
		return
	end
	w.ry[k] = dv
	if mirror then
		w.lx[k], w.ly[k] = -w.rx[k], -w.ry[k]
	end
end

local function writeLeft(keys: { Key }, w: Work, k: number, dv: number, mirror: boolean)
	local kind = typeOf(keys[k])
	if not (isAuto(kind) or kind == "Vector") then
		return
	end
	w.ly[k] = dv
	if mirror then
		w.rx[k], w.ry[k] = -w.lx[k], -w.ly[k]
	end
end

local function smoothRun(
	keys: { Key },
	w: Work,
	lk: { number },
	rk: { number },
	count: number,
	fullCycle: boolean
)
	if count < 2 then
		return
	end
	local n = #keys
	local startsCurve = rk[1] == 1
	local endsCurve = lk[count] == n

	local function solvesEnd(k: number, atCurveEnd: boolean): boolean
		local kind = typeOf(keys[k])
		return kind == "Vector" or (atCurveEnd and isAuto(kind) and not w.locked[k])
	end
	local solveFirst = fullCycle or solvesEnd(rk[1], startsCurve)
	local solveLast = fullCycle or solvesEnd(lk[count], endsCurve)
	if count == 2 and not fullCycle and solveFirst == solveLast then
		return
	end

	local dx, dy = table.create(count, 0), table.create(count, 0)
	for r = 2, count do
		dx[r] = keys[lk[r]].t - keys[rk[r - 1]].t
		dy[r] = keys[lk[r]].v - keys[rk[r - 1]].v
	end
	local l = table.create(count, 1)
	if fullCycle then
		dx[1], dy[1] = dx[count], dy[count]
		l[1] = dx[2] / dx[1]
		l[count] = l[1]
	end
	for r = 2, count - 1 do
		l[r] = dx[r + 1] / dx[r]
	end

	local hmin, hmax = table.create(count, -math.huge), table.create(count, math.huge)
	local function clamp(r: number, delta: number)
		if delta > 0 then
			hmax[r] = min(hmax[r], delta)
			hmin[r] = 0
		elseif delta < 0 then
			hmax[r] = 0
			hmin[r] = max(hmin[r], delta)
		else
			hmax[r], hmin[r] = 0, 0
		end
	end
	local function clampedAt(r: number): boolean
		return typeOf(keys[lk[r]]) == "AutoClamped" or typeOf(keys[rk[r]]) == "AutoClamped"
	end
	local clampedCur = clampedAt(1)
	for r = 2, count do
		local clampedPrev = clampedCur
		clampedCur = clampedAt(r)
		if clampedPrev then
			clamp(r - 1, dy[r])
		end
		if clampedCur then
			clamp(r, dy[r] * l[r])
		end
	end

	local a, b, c, d =
		table.create(count, 0),
		table.create(count, 0),
		table.create(count, 0),
		table.create(count, 0)
	local function lock(r: number, value: number)
		a[r], b[r], c[r], d[r] = 0, 1, 0, value
	end
	local function continuous(r: number)
		local lr = l[r]
		a[r] = lr * lr
		b[r] = 2 * (lr + 1)
		c[r] = 1 / l[r + 1]
		d[r] = dy[r] * lr * lr + dy[r + 1]
	end
	local function reachCorrection(hx: number, hy: number, span: number): (number, number)
		local fac = span / (hx + span / 3)
		if fac < 1 then
			hx *= fac
			hy *= fac
		end
		return 1 - 3 * hx / span, hy
	end

	local solveCount = count
	if fullCycle then
		solveCount = count - 1
		hmin[1] = max(hmin[1], hmin[count])
		hmax[1] = min(hmax[1], hmax[count])
		continuous(1)
	else
		local firstAdj, lastAdj = 0, 0
		if solveFirst then
			a[1], b[1], c[1], d[1] = 0, 2, 1 / l[2], dy[2]
		else
			local adj, hy = reachCorrection(w.rx[rk[1]], w.ry[rk[1]], dx[2])
			firstAdj = adj
			lock(1, hy)
		end
		if solveLast then
			local lr = l[count]
			a[count], b[count], c[count], d[count] = lr * lr, 2 * lr, 0, dy[count] * lr * lr
		else
			local adj, hy = reachCorrection(-w.lx[lk[count]], -w.ly[lk[count]], dx[count])
			lastAdj = adj
			lock(count, hy)
		end
		for r = 2, count - 1 do
			continuous(r)
		end
		if count > 2 or solveLast then
			b[2] += l[2] * firstAdj
		end
		if count > 2 or solveFirst then
			b[count - 1] += lastAdj
		end
	end
	if fullCycle then
		for r = 2, count - 1 do
			continuous(r)
		end
	end

	local h = table.create(count, 0)
	if not solveWithLimits(a, b, c, d, h, hmin, hmax, solveCount) then
		return
	end
	if fullCycle then
		h[count] = h[1]
	end
	for r = 2, count - 1 do
		local seam = lk[r] == n
		writeLeft(keys, w, lk[r], -h[r] / l[r], seam)
		writeRight(keys, w, rk[r], h[r], seam)
	end
	if solveFirst then
		writeRight(keys, w, rk[1], h[1], startsCurve)
	end
	if solveLast then
		writeLeft(keys, w, lk[count], -h[count] / l[count], endsCurve)
	end
end

local function freeAuto(keys: { Key }, w: Work, i: number): boolean
	return isAuto(typeOf(keys[i])) and not w.locked[i]
end

local function smoothAll(keys: { Key }, w: Work, cyclic: boolean)
	local n = #keys
	if cyclic and freeAuto(keys, w, 1) and freeAuto(keys, w, n) then
		local base = 0
		for i = 2, n - 1 do
			if not freeAuto(keys, w, i) then
				base = i
				break
			end
		end
		if base == 0 then
			local ids = table.create(n, 0)
			for i = 1, n do
				ids[i] = i
			end
			smoothRun(keys, w, ids, ids, n, true)
			return
		end
		local lk, rk = { base }, { base }
		for step = 1, n - 1 do
			local p = base + step
			if p > n - 1 then
				p -= n - 1
			end
			table.insert(lk, if p == 1 then n else p)
			table.insert(rk, p)
			if not freeAuto(keys, w, p) then
				smoothRun(keys, w, lk, rk, #lk, false)
				lk, rk = { p }, { p }
			end
		end
		return
	end

	local lk = { 1 }
	for j = 2, n do
		table.insert(lk, j)
		if not freeAuto(keys, w, j) then
			smoothRun(keys, w, lk, lk, #lk, false)
			lk = { j }
		end
	end
end

local function computeAll(keys: { Key }, r: Resolved): Work
	local n = #keys
	local w = newWork()
	for i = 1, n do
		localPass(keys, i, r, w)
	end
	lockDuplicates(keys, w, 2, n)
	if r.cyclic and n >= 2 and (w.locked[1] or w.locked[n]) then
		w.ly[1], w.ry[1], w.ly[n], w.ry[n] = 0, 0, 0, 0
		w.locked[1], w.locked[n] = true, true
	end
	if r.smooth and n >= 2 then
		smoothAll(keys, w, r.cyclic)
	end
	return w
end

function Interp.recalcHandles(keys: { Key }, options: HandleOptions?)
	local n = #keys
	if n < 2 then
		return
	end
	local w = computeAll(keys, resolve(keys, options))
	for i = 1, n do
		local key = keys[i]
		if typeOf(key) == "Free" then
			if key.handleL == nil then
				key.handleL = { w.lx[i], w.ly[i] }
			end
			if key.handleR == nil then
				key.handleR = { w.rx[i], w.ry[i] }
			end
		else
			key.handleL = { w.lx[i], w.ly[i] }
			key.handleR = { w.rx[i], w.ry[i] }
		end
	end
end

function Interp.handlesAt(
	keys: { Key },
	index: number,
	options: HandleOptions?
): ({ number }, { number })
	local key = keys[index]
	local left, right = key.handleL, key.handleR
	if left ~= nil and right ~= nil then
		return left, right
	end
	local w = computeAll(keys, resolve(keys, options))
	return left or { w.lx[index], w.ly[index] }, right or { w.rx[index], w.ry[index] }
end

local function computedSegment(
	keys: { Key },
	i: number,
	r: Resolved
): (number, number, number, number)
	local n = #keys
	if r.cyclic then
		local w = computeAll(keys, r)
		return w.rx[i], w.ry[i], w.lx[i + 1], w.ly[i + 1]
	end
	local w = newWork()
	if not r.smooth then
		localPass(keys, i, r, w)
		localPass(keys, i + 1, r, w)
		return w.rx[i], w.ry[i], w.lx[i + 1], w.ly[i + 1]
	end

	local function isFree(j: number): boolean
		localPass(keys, j, r, w)
		if (j > 1 and keys[j - 1].t >= keys[j].t) or (j < n and keys[j].t >= keys[j + 1].t) then
			w.locked[j] = true
		end
		return freeAuto(keys, w, j)
	end
	local lo = i
	while isFree(lo) do
		lo -= 1
	end
	local hi = i + 1
	while isFree(hi) do
		hi += 1
	end
	local ids = table.create(hi - lo + 1, 0)
	for j = lo, hi do
		ids[j - lo + 1] = j
	end
	smoothRun(keys, w, ids, ids, #ids, false)
	return w.rx[i], w.ry[i], w.lx[i + 1], w.ly[i + 1]
end

local function segmentOf(keys: { Key }, t: number): number
	local lo, hi = 1, #keys
	while hi - lo > 1 do
		local mid = (lo + hi) // 2
		if keys[mid].t <= t then
			lo = mid
		else
			hi = mid
		end
	end
	return lo
end

function Interp.evaluate(channel: Channel, t: number, options: EvalOptions?): number
	local keys = channel.keys
	local n = #keys
	if n == 0 then
		return 0
	end
	local first = keys[1]
	if t <= first.t then
		return first.v
	end
	local last = keys[n]
	if t >= last.t then
		return last.v
	end
	local i = segmentOf(keys, t)
	local a, b = keys[i], keys[i + 1]
	if a.t == t then
		return a.v
	end
	local duration = b.t - a.t
	if duration <= 0 then
		return a.v
	end
	local presetName = a.preset
	if presetName ~= nil and options ~= nil then
		local presets = options.presets
		local preset = if presets ~= nil then presets[presetName] else nil
		local points = if preset ~= nil then preset.points else nil
		if points ~= nil and #points >= 2 then
			return a.v + (b.v - a.v) * shapeAt(points, (t - a.t) / duration)
		end
	end
	local mode = a.interp or channel.interp or "Bezier"
	if mode == "Constant" then
		return a.v
	elseif mode == "Linear" then
		return a.v + (b.v - a.v) * (t - a.t) / duration
	elseif mode == "Bezier" then
		local right, left = a.handleR, b.handleL
		local rx, ry, lx, ly
		if right ~= nil and left ~= nil then
			rx, ry, lx, ly = right[1], right[2], left[1], left[2]
		else
			rx, ry, lx, ly = computedSegment(keys, i, resolve(keys, options))
			if right ~= nil then
				rx, ry = right[1], right[2]
			end
			if left ~= nil then
				lx, ly = left[1], left[2]
			end
		end
		return Interp.bezier(a.t, a.v, a.t + rx, a.v + ry, b.t + lx, b.v + ly, b.t, b.v, t)
	end
	return Interp.ease(mode, a.easing, t - a.t, a.v, b.v - a.v, duration, a.params)
end

return Interp
