--!strict
--!native
--!optimize 2

local Interp = require(script.Parent.Interp)
local Modifiers = require(script.Parent.Modifiers)
local Pose = require(script.Parent.Pose)

local LayerEval = {}

export type LayerBlend = "Additive" | "Override"

export type Layer = {
	name: string,
	blend: LayerBlend,
	weight: number,
	mask: { [string]: number }?,
	mute: boolean?,
	solo: boolean?,
	joints: { [string]: Pose.JointTrack },
}

export type Document = {
	length: number,
	fps: number,
	joints: { [string]: Pose.JointTrack },
	layers: { Layer }?,
	presets: { [string]: any }?,
}

export type Options = {
	presets: { [string]: any }?,
	fps: number?,
	solo: boolean?,
}

export type FlatChannel = {
	keys: { { t: number, v: number, interp: string } },
	bakeRate: number?,
	steep: { number }?,
}

export type FlatTrack = {
	rotationMode: Pose.RotationMode,
	channels: { [string]: FlatChannel },
	sample: (t: number) -> CFrame,
}

local IDENTITY = CFrame.identity

local POSITION = Pose.POSITION_CHANNELS
local EULER = Pose.EULER_CHANNELS
local QUATERNION = Pose.QUATERNION_CHANNELS
local ROTATIONS = { "rx", "ry", "rz", "qw", "qx", "qy", "qz" }

local SAME = 1e-9

function LayerEval.factor(layer: Layer, address: string): number
	local mask = layer.mask
	local share = if mask == nil then 1 else (mask[address] or 0)
	return math.clamp(layer.weight * share, 0, 1)
end

function LayerEval.soloing(doc: Document, options: Options?): boolean
	local layers = doc.layers
	if options == nil or options.solo ~= true or layers == nil then
		return false
	end
	for _, layer in layers do
		if layer.solo == true then
			return true
		end
	end
	return false
end

function LayerEval.plays(layer: Layer, soloing: boolean): boolean
	return layer.mute ~= true and (not soloing or layer.solo == true)
end

local function rotates(channels: { [string]: any }): boolean
	for _, name in ROTATIONS do
		if channels[name] ~= nil then
			return true
		end
	end
	return false
end

local function lay(
	below: CFrame,
	value: CFrame,
	blend: LayerBlend,
	factor: number,
	channels: { [string]: any }
): CFrame
	local p = below.Position
	local l = value.Position
	local rotation = below.Rotation
	local x: number, y: number, z: number
	if blend == "Additive" then
		x, y, z = p.X + factor * l.X, p.Y + factor * l.Y, p.Z + factor * l.Z
		if rotates(channels) then
			local turn = if factor >= 1
				then value.Rotation
				else IDENTITY:Lerp(value.Rotation, factor)
			rotation = rotation * turn
		end
	else
		x = if channels.px ~= nil then p.X + factor * (l.X - p.X) else p.X
		y = if channels.py ~= nil then p.Y + factor * (l.Y - p.Y) else p.Y
		z = if channels.pz ~= nil then p.Z + factor * (l.Z - p.Z) else p.Z
		if rotates(channels) then
			rotation = if factor >= 1 then value.Rotation else rotation:Lerp(value.Rotation, factor)
		end
	end
	return CFrame.new(x, y, z) * rotation
end

local function stack(
	doc: Document,
	address: string,
	t: number,
	options: Options?,
	soloing: boolean,
	upto: number?
): CFrame
	local base = doc.joints[address]
	local pose = if base ~= nil then Pose.evaluate(base, t, options :: any) else IDENTITY
	local layers = doc.layers
	if layers == nil then
		return pose
	end
	for index = 1, math.min(upto or #layers, #layers) do
		local layer = layers[index]
		if not LayerEval.plays(layer, soloing) then
			continue
		end
		local track = layer.joints[address]
		if track == nil then
			continue
		end
		local factor = LayerEval.factor(layer, address)
		if factor <= 0 then
			continue
		end
		pose =
			lay(pose, Pose.evaluate(track, t, options :: any), layer.blend, factor, track.channels)
	end
	return pose
end

function LayerEval.pose(doc: Document, address: string, t: number, options: Options?): CFrame
	return stack(doc, address, t, options, LayerEval.soloing(doc, options))
end

function LayerEval.sample(
	doc: Document,
	t: number,
	options: Options?,
	into: { [string]: CFrame }?
): { [string]: CFrame }
	local out: { [string]: CFrame } = into or {}
	table.clear(out)
	local soloing = LayerEval.soloing(doc, options)
	for address in doc.joints do
		out[address] = stack(doc, address, t, options, soloing)
	end
	local layers = doc.layers
	if layers ~= nil then
		for _, layer in layers do
			if LayerEval.plays(layer, soloing) then
				for address in layer.joints do
					if out[address] == nil then
						out[address] = stack(doc, address, t, options, soloing)
					end
				end
			end
		end
	end
	return out
end

export type Hidden = { [string]: string }

local function power(rotation: CFrame, s: number): CFrame
	local axis, angle = rotation:ToAxisAngle()
	if angle ~= angle or math.abs(angle) < 1e-12 then
		return IDENTITY
	end
	if angle > math.pi then
		angle -= 2 * math.pi
	end
	return CFrame.fromAxisAngle(axis, angle * s)
end

local function unlay(
	above: CFrame,
	value: CFrame,
	layer: Layer,
	factor: number,
	channels: { [string]: any },
	hidden: Hidden
): CFrame
	local q = above.Position
	local l = value.Position
	local rotation = above.Rotation
	local x: number, y: number, z: number
	if layer.blend == "Additive" then
		x, y, z = q.X - factor * l.X, q.Y - factor * l.Y, q.Z - factor * l.Z
		if rotates(channels) then
			local turn = if factor >= 1
				then value.Rotation
				else IDENTITY:Lerp(value.Rotation, factor)
			rotation = rotation * turn:Inverse()
		end
	else
		local function axis(name: string, out: number, own: number): number
			if channels[name] == nil then
				return out
			end
			if factor >= 1 then
				hidden[name] = hidden[name] or layer.name
				return out
			end
			return (out - factor * own) / (1 - factor)
		end
		x, y, z = axis("px", q.X, l.X), axis("py", q.Y, l.Y), axis("pz", q.Z, l.Z)
		if rotates(channels) then
			if factor >= 1 then
				hidden.rotation = hidden.rotation or layer.name
			else
				rotation = value.Rotation
					* power(value.Rotation:Inverse() * rotation, 1 / (1 - factor))
			end
		end
	end
	return CFrame.new(x, y, z) * rotation
end

local function solve(below: CFrame, wanted: CFrame, blend: LayerBlend, factor: number): CFrame
	local p = below.Position
	local a = wanted.Position
	local turn = below.Rotation:Inverse() * wanted.Rotation
	if blend == "Additive" then
		local rotation = if factor >= 1 then turn else power(turn, 1 / factor)
		return CFrame.new((a - p) / factor) * rotation
	end
	local position = if factor >= 1 then a else p + (a - p) / factor
	local rotation = if factor >= 1
		then wanted.Rotation
		else below.Rotation * power(turn, 1 / factor)
	return CFrame.new(position) * rotation
end

function LayerEval.deltaFor(
	doc: Document,
	index: number,
	address: string,
	t: number,
	posed: CFrame,
	options: Options?
): (CFrame?, string?, Hidden)
	local layers = doc.layers or {}
	local soloing = LayerEval.soloing(doc, options)
	local hidden: Hidden = {}
	local wanted = posed
	for above = #layers, index + 1, -1 do
		local layer = layers[above]
		if not LayerEval.plays(layer, soloing) then
			continue
		end
		local track = layer.joints[address]
		if track == nil then
			continue
		end
		local factor = LayerEval.factor(layer, address)
		if factor <= 0 then
			continue
		end
		wanted = unlay(
			wanted,
			Pose.evaluate(track, t, options :: any),
			layer,
			factor,
			track.channels,
			hidden
		)
	end
	if index <= 0 then
		return wanted, nil, hidden
	end

	local layer = layers[index]
	if layer == nil then
		return nil, "That layer is not in the animation any more.", hidden
	end
	if layer.mute == true then
		return nil,
			`The layer '{layer.name}' is muted, so a key on it would not show. Unmute it first.`,
			hidden
	end
	if not LayerEval.plays(layer, soloing) then
		return nil,
			`Another layer is soloed, so a key on '{layer.name}' would not show. Solo it too, or turn solo off.`,
			hidden
	end
	local factor = LayerEval.factor(layer, address)
	if factor <= 0 then
		return nil,
			`The layer '{layer.name}' leaves {address} alone (its weight or its joint mask is 0 there), so a key on it would not show.`,
			hidden
	end
	local below = stack(doc, address, t, options, soloing, index - 1)
	return solve(below, wanted, layer.blend, factor), nil, hidden
end

local function movesTime(channel: Modifiers.Channel): boolean
	for _, modifier in channel.modifiers or {} do
		if modifier.mute ~= true then
			local kind = modifier.kind
			if kind == "Cycles" or kind == "Stepped" then
				return true
			elseif kind == "Limits" and (modifier.minTime ~= nil or modifier.maxTime ~= nil) then
				return true
			end
		end
	end
	return false
end

local function rateOf(channel: Modifiers.Channel, best: number?): number?
	for _, modifier in channel.modifiers or {} do
		local rate = modifier.bakeRate
		if
			modifier.mute ~= true
			and type(rate) == "number"
			and rate > 0
			and rate < math.huge
			and (best == nil or rate > best)
		then
			best = rate
		end
	end
	return best
end

local function uniqueTimes(times: { number }, length: number): { number }
	table.sort(times)
	local out: { number } = {}
	for _, t in times do
		if t >= -SAME and t <= length + SAME and (#out == 0 or t - out[#out] > SAME) then
			table.insert(out, math.clamp(t, 0, length))
		end
	end
	return out
end

local function flatTrack(
	doc: Document,
	address: string,
	base: Pose.JointTrack?,
	sources: { Pose.JointTrack },
	options: Options
): FlatTrack
	local mode: Pose.RotationMode = if base ~= nil
		then base.rotationMode
		else sources[1].rotationMode
	local length = math.max(doc.length, 0)
	local tracks: { Pose.JointTrack } = table.clone(sources)
	if base ~= nil then
		table.insert(tracks, 1, base)
	end

	local rotationNames = if mode == "Quaternion" then QUATERNION else EULER
	local names: { string } = {}
	local turned, turns = false, false
	for _, track in tracks do
		turns = turns or rotates(track.channels)
	end
	for _, list in { POSITION, rotationNames } do
		for _, name in list do
			for _, track in tracks do
				if track.channels[name] ~= nil then
					table.insert(names, name)
					turned = turned or list == rotationNames
					break
				end
			end
		end
	end
	if turns and not turned then
		table.move(rotationNames, 1, #rotationNames, #names + 1, names)
	end

	local knotsOf: { [string]: { number } } = {}
	local steepOf: { [string]: { number } } = {}
	local rateFor: { [string]: number? } = {}
	local every: { number } = { 0, length }
	local scan = if options.fps ~= nil and options.fps > 0 then options.fps else 60
	for _, name in names do
		local shaping = if table.find(POSITION, name) ~= nil then { name } else ROTATIONS
		local times: { number } = { 0, length }
		local steep: { number } = {}
		local rate: number? = nil
		for _, track in tracks do
			for _, source in shaping do
				local channel = track.channels[source]
				if channel ~= nil then
					rate = rateOf(channel, rate)
					if not movesTime(channel) then
						for _, key in channel.keys do
							table.insert(times, key.t)
						end
						Interp.easingKnots(channel, options.presets, times, steep)
						Modifiers.clampKnots(channel, 0, length, scan, options :: any, times)
					end
				end
			end
		end
		knotsOf[name] = uniqueTimes(times, length)
		steepOf[name] = uniqueTimes(steep, length)
		rateFor[name] = rate
		table.move(knotsOf[name], 1, #knotsOf[name], #every + 1, every)
	end
	every = uniqueTimes(every, length)

	local previous: Pose.Values? = nil
	if base ~= nil then
		local seed: { [string]: number } = {}
		for _, name in rotationNames do
			local channel = base.channels[name]
			if channel ~= nil then
				seed[name] = Modifiers.evaluate(channel, every[1], options :: any)
			end
		end
		previous = seed :: any
	end
	local valuesAt: { [number]: Pose.Values } = {}
	for _, t in every do
		local values = Pose.toValues(stack(doc, address, t, options, false), mode, previous)
		valuesAt[t] = values
		previous = values
	end

	local channels: { [string]: FlatChannel } = {}
	for _, name in names do
		local keys = {}
		for _, t in knotsOf[name] do
			local values = valuesAt[t]
			if values == nil then
				for at, found in valuesAt do
					if math.abs(at - t) <= SAME then
						values = found
						break
					end
				end
			end
			local value = ((values :: any) or {})[name] or 0
			table.insert(keys, { t = t, v = value, interp = "Linear" })
		end
		local steep = steepOf[name]
		channels[name] = {
			keys = keys,
			bakeRate = rateFor[name],
			steep = if #steep > 0 then steep else nil,
		}
	end

	return {
		rotationMode = mode,
		channels = channels,
		sample = function(t: number): CFrame
			return stack(doc, address, t, options, false)
		end,
	}
end

function LayerEval.flatten(doc: Document, options: Options?): Document
	local layers = doc.layers
	if layers == nil or #layers == 0 then
		return doc
	end
	local touched: { [string]: { Pose.JointTrack } } = {}
	local any = false
	for _, layer in layers do
		if not LayerEval.plays(layer, false) then
			continue
		end
		for address, track in layer.joints do
			if next(track.channels) ~= nil and LayerEval.factor(layer, address) > 0 then
				local list = touched[address]
				if list == nil then
					list = {}
					touched[address] = list
				end
				table.insert(list, track)
				any = true
			end
		end
	end
	if not any then
		return doc
	end

	local evalOptions: Options = {
		presets = if options ~= nil and options.presets ~= nil
			then options.presets
			else doc.presets,
		fps = if options ~= nil and options.fps ~= nil then options.fps else doc.fps,
		solo = false,
	}
	local joints: { [string]: Pose.JointTrack } = table.clone(doc.joints)
	for address, sources in touched do
		joints[address] = flatTrack(doc, address, doc.joints[address], sources, evalOptions) :: any
	end
	local out = table.clone(doc)
	out.joints = joints
	out.layers = nil
	return out
end

return LayerEval
