local SNAP = 1e-9

local function snapped(q: number): (number, boolean)
	local nearest = floor(q + 0.5)
	if abs(q - nearest) < SNAP then
		return nearest, true
	end
	return q, false
end

local function cyclesTime(modifier: Modifier, keys: { Interp.Key }, t: number): (number, number)
	local n = #keys
	if n == 0 then
		return t, 0
	end
	local first, last = keys[1], keys[n]
	local side, mode, count, origin = 0, "None", 0, 0
	if t < first.t then
		mode = modifier.beforeMode or CYCLES.beforeMode
		side, count, origin = -1, modifier.beforeCount or 0, first.t
	elseif t > last.t then
		mode = modifier.afterMode or CYCLES.afterMode
		side, count, origin = 1, modifier.afterCount or 0, last.t
	end
	if side == 0 or mode == "None" then
		return t, 0
	end
	local span = last.t - first.t
	if span == 0 then
		return t, 0
	end
	local q, onBoundary = snapped((t - origin) / span)
	local cycle = side * q
	if count ~= 0 and cycle > count then
		return t, 0
	end
	local offset = 0
	if mode == "RepeatOffset" then
		offset = (if side < 0 then floor(q) else ceil(q)) * (last.v - first.v)
	end
	local within = if onBoundary then 0 else fmod(t - origin, span)
	local mirrored = mode == "RepeatMirrored"
	local read: number
	if within == 0 then
		read = if side == 1 then last.t else first.t
		if mirrored and floor(cycle) % 2 == 1 then
			read = if side == 1 then first.t else last.t
		end
	elseif mirrored and floor(cycle + 1) % 2 == 1 then
		read = (if side < 0 then first.t else last.t) - within
	else
		read = first.t + within
	end
	if read < first.t then
		read += span
	end
	return read, offset
end

local function steppedTime(modifier: Modifier, t: number): number
	local startTime, endTime = modifier.startTime, modifier.endTime
	if startTime ~= nil and t < startTime then
		return t
	end
	if endTime ~= nil and t > endTime then
		return t
