function Modifiers.isCyclic(channel: Channel): boolean
	local stack = channel.modifiers
	local first = if stack ~= nil then stack[1] else nil
	if first == nil or first.kind ~= "Cycles" or first.mute == true or first.range ~= nil then
		return false
	end
	if first.influence ~= nil and first.influence ~= 1 then
		return false
	end
	if (first.beforeCount or 0) ~= 0 or (first.afterCount or 0) ~= 0 then
		return false
	end
	local before = first.beforeMode or CYCLES.beforeMode
	local after = first.afterMode or CYCLES.afterMode
	return (before == "Repeat" or before == "RepeatOffset")
		and (after == "Repeat" or after == "RepeatOffset")
end

function Modifiers.recalcHandles(channel: Channel, options: Interp.HandleOptions?)
	local merged: { [string]: any } = {}
	if options ~= nil then
		for name, value in options :: { [string]: any } do
			merged[name] = value
		end
	end
	merged.cyclic = Modifiers.isCyclic(channel)
	Interp.recalcHandles(channel.keys, merged :: any)
end

local function keyOptionsFor(channel: Channel, options: EvalOptions?): EvalOptions?
	local cyclic = Modifiers.isCyclic(channel)
	if options == nil then
		if cyclic then
			return CYCLIC_OPTIONS
		end
		return nil
	end
	if (options.cyclic == true) == cyclic then
		return options
	end
	return withCyclic(options, cyclic)
end

function Modifiers.evaluate(channel: Channel, t: number, options: EvalOptions?): number
	local stack = channel.modifiers
	if stack == nil or #stack == 0 then
		return Interp.evaluate(
			channel,
			t,
			if options ~= nil and options.cyclic == true
				then withCyclic(options, false)
				else options
		)
	end
	local keys = channel.keys
	local count = #stack

	local time = t
	local cycleOffset = 0
	for i = count, 1, -1 do
		local modifier = stack[i]
		local kind = modifier.kind
		if TIME_KIND[kind] and modifier.mute ~= true and inRange(modifier, time) then
			local remapped: number
			if kind == "Cycles" then
				if i ~= 1 then
					continue
				end
				remapped, cycleOffset = cyclesTime(modifier, keys, time)
			elseif kind == "Stepped" then
				remapped = steppedTime(modifier, time)
			else
				remapped = limitsTime(modifier, time)
			end
			local influence = influenceAt(modifier, time)
			time = influence * remapped + (1 - influence) * time
		end
	end

	local value = Interp.evaluate(channel, time, keyOptionsFor(channel, options))

	for i = 1, count do
		local modifier = stack[i]
		local kind = modifier.kind
		if kind ~= "Stepped" and modifier.mute ~= true and inRange(modifier, time) then
			local result: number
			if kind == "Noise" then
				result = noiseValue(modifier, value, time)
			elseif kind == "Cycles" then
				if i ~= 1 then
					continue
				end
				result = value + cycleOffset
			elseif kind == "Limits" then
				result = value
				local minValue, maxValue = modifier.minValue, modifier.maxValue
				if minValue ~= nil and result < minValue then
					result = minValue
				end
				if maxValue ~= nil and result > maxValue then
					result = maxValue
				end
			elseif kind == "Envelope" then
				result = envelopeValue(modifier, value, time)
			elseif kind == "Generator" then
				result = generatorValue(modifier, value, time)
			else
				continue
			end
			local influence = influenceAt(modifier, time)
			value = influence * result + (1 - influence) * value
		end
	end
	return value
end

local CLAMP_WIDTH = 1e-9

function Modifiers.clampKnots(
	channel: Channel,
	from: number,
	to: number,
	rate: number,
	options: EvalOptions?,
	into: { number }?
): { number }
	local out: { number } = into or {}
	local stack = channel.modifiers
	if stack == nil or not (to > from) or not (rate > 0) then
		return out
	end
	for _, modifier in stack do
		local kind = modifier.kind
		if modifier.mute == true then
			continue
		elseif
			kind == "Cycles"
			or kind == "Stepped"
			or (kind == "Limits" and (modifier.minTime ~= nil or modifier.maxTime ~= nil))
		then
			return out
		end
	end
	for index, modifier in stack do
		local low, high = modifier.minValue, modifier.maxValue
		if modifier.kind ~= "Limits" or modifier.mute == true or (low == nil and high == nil) then
			continue
		end
		local below: Channel = {
			keys = channel.keys,
			interp = channel.interp,
			modifiers = table.move(stack, 1, index - 1, 1, {}),
		}
		local range = modifier.range
		local lo = if range ~= nil then max(from, range.from) else from
		local hi = if range ~= nil then min(to, range.to) else to
		if not (hi > lo) then
			continue
		end
		local function clamps(t: number): number
			local value = Modifiers.evaluate(below, t, options)
			return if low ~= nil and value < low
				then -1
				elseif high ~= nil and value > high then 1
				else 0
		end
		local function locate(l: number, r: number, before: (state: number) -> boolean)
			while r - l > CLAMP_WIDTH do
				local m = (l + r) / 2
				if before(clamps(m)) then
					l = m
				else
					r = m
				end
			end
			table.insert(out, (l + r) / 2)
		end
		local count = max(1, ceil((hi - lo) * rate - 1e-9))
		local t0, state0 = lo, clamps(lo)
		for step = 1, count do
			local t1 = if step == count then hi else lo + (hi - lo) * step / count
			local state1 = clamps(t1)
			if state0 ~= state1 and state0 ~= 0 then
				locate(t0, t1, function(state: number): boolean
					return state == state0
				end)
			end
			if state0 ~= state1 and state1 ~= 0 then
				locate(t0, t1, function(state: number): boolean
					return state ~= state1
				end)
			end
			t0, state0 = t1, state1
		end
	end
	return out
end

local function finite(x: any): boolean
	return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
end

local function whole(x: any): boolean
	return finite(x) and x % 1 == 0
end

local function optionalNumber(m: Modifier, field: string, what: string): string?
	local x = m[field]
	if x ~= nil and not finite(x) then
		return `{what} '{field}' must be a number`
	end
	return nil
end

local function optionalAtLeast(m: Modifier, field: string, least: number, what: string): string?
	local x = m[field]
	if x ~= nil and not (finite(x) and x >= least) then
		return `{what} '{field}' must be a number, {least} or more`
	end
	return nil
end

local function optionalName(
	m: Modifier,
	field: string,
	known: { [string]: boolean },
	list: { string },
	what: string
): string?
	local x = m[field]
	if x ~= nil and not (type(x) == "string" and known[x]) then
		return `{what} '{field}' must be one of {table.concat(list, ", ")}`
	end
	return nil
end

local function optionalCount(m: Modifier, field: string, what: string): string?
	local x = m[field]
	if x ~= nil and not (whole(x) and x >= 0) then
		return `{what} '{field}' must be a whole number, 0 or more (0 repeats forever)`
	end
	return nil
end

local function firstProblem(...: string?): string?
	for i = 1, select("#", ...) do
		local problem = select(i, ...)
		if problem ~= nil then
			return problem
		end
	end
	return nil
end

local function orderedPair(m: Modifier, low: string, high: string, what: string): string?
	local a, b = m[low], m[high]
	if a ~= nil and b ~= nil and a > b then
		return `{what} '{low}' is after its '{high}'`
	end
	return nil
end

local function validateNoise(m: Modifier): string?
	local what = "a Noise modifier's"
	local problem = firstProblem(
		optionalAtLeast(m, "scale", 0, what),
		optionalNumber(m, "strength", what),
		optionalNumber(m, "phase", what),
		optionalNumber(m, "offset", what),
		optionalAtLeast(m, "lacunarity", 0, what),
		optionalAtLeast(m, "roughness", 0, what),
		optionalName(m, "blend", KNOWN_BLEND, Modifiers.BLENDS, what)
	)
	if problem ~= nil then
		return problem
	end
	local depth = m.depth
	if
		depth ~= nil and not (whole(depth) and depth >= 0 and depth <= Modifiers.MAX_NOISE_DEPTH)
	then
		return `{what} 'depth' must be a whole number from 0 to {Modifiers.MAX_NOISE_DEPTH}`
	end
	return nil
end

local function validateCycles(m: Modifier): string?
	local what = "a Cycles modifier's"
	return firstProblem(
		optionalName(m, "beforeMode", KNOWN_EXTEND, Modifiers.EXTENDS, what),
		optionalName(m, "afterMode", KNOWN_EXTEND, Modifiers.EXTENDS, what),
		optionalCount(m, "beforeCount", what),
		optionalCount(m, "afterCount", what)
	)
end

local function validateStepped(m: Modifier): string?
	local what = "a Stepped modifier's"
	local step = m.step
	if step ~= nil and not (finite(step) and step > 0) then
		return `{what} 'step' must be a number of seconds greater than 0`
	end
	return firstProblem(
		optionalNumber(m, "offset", what),
		optionalNumber(m, "startTime", what),
		optionalNumber(m, "endTime", what),
		orderedPair(m, "startTime", "endTime", what)
	)
end

local function validateLimits(m: Modifier): string?
	local what = "a Limits modifier's"
	return firstProblem(
		optionalNumber(m, "minTime", what),
		optionalNumber(m, "maxTime", what),
		optionalNumber(m, "minValue", what),
		optionalNumber(m, "maxValue", what),
		orderedPair(m, "minTime", "maxTime", what),
		orderedPair(m, "minValue", "maxValue", what)
	)
end

local function validateEnvelope(m: Modifier): string?
	local what = "an Envelope modifier's"
	local problem = firstProblem(
		optionalNumber(m, "reference", what),
		optionalNumber(m, "min", what),
		optionalNumber(m, "max", what)
	)
	if problem ~= nil then
		return problem
	end
	if (m.min or ENVELOPE.min) == (m.max or ENVELOPE.max) then
		return `{what} 'min' and 'max' must differ: the band they make is what is rescaled`
	end
	local points = m.points
	if points == nil then
		return nil
	end
	if type(points) ~= "table" then
		return `{what} 'points' must be a list`
	end
	local previous = -math.huge
	for i, point in points do
		if
			type(point) ~= "table"
			or not (finite(point.t) and finite(point.min) and finite(point.max))
		then
			return `{what} point {i} must have numbers for its time, 'min' and 'max'`
		end
		if point.t <= previous then
			return `{what} points must be in increasing time (point {i} is at {point.t} s)`
		end
		previous = point.t
	end
	return nil
end

local function validateGenerator(m: Modifier): string?
	local what = "a Generator modifier's"
	local problem = firstProblem(
		optionalName(m, "mode", KNOWN_MODE, Modifiers.GENERATOR_MODES, what),
		optionalName(m, "fn", KNOWN_FN, Modifiers.FUNCTIONS, what),
		optionalNumber(m, "amplitude", what),
		optionalNumber(m, "phaseMultiplier", what),
		optionalNumber(m, "phaseOffset", what),
		optionalNumber(m, "valueOffset", what)
	)
	if problem ~= nil then
		return problem
	end
	if m.additive ~= nil and type(m.additive) ~= "boolean" then
		return `{what} 'additive' must be true or false`
	end
	local coefficients = m.coefficients
	if coefficients ~= nil then
		if type(coefficients) ~= "table" or #coefficients < 2 then
			return `{what} 'coefficients' must list at least two numbers (a constant and a slope)`
		end
		for i, c in coefficients do
			if not finite(c) then
				return `{what} coefficient {i} must be a number`
			end
		end
	end
	local factors = m.factors
	if factors ~= nil then
		if type(factors) ~= "table" or #factors < 1 then
			return `{what} 'factors' must list at least one pair`
		end
		for i, factor in factors do
			if type(factor) ~= "table" or not (finite(factor[1]) and finite(factor[2])) then
				return `{what} factor {i} must be a pair of numbers a, b - the factor (a t + b)`
			end
		end
	end
	return nil
end

local VALIDATE: { [string]: (Modifier) -> string? } = {
	Noise = validateNoise,
	Cycles = validateCycles,
	Stepped = validateStepped,
	Limits = validateLimits,
	Envelope = validateEnvelope,
	Generator = validateGenerator,
}

function Modifiers.validate(modifier: any): (boolean, string?)
	if type(modifier) ~= "table" then
		return false, `a modifier must be a table, got {type(modifier)}`
	end
	local kind = modifier.kind
	if type(kind) ~= "string" or not KNOWN_KIND[kind] then
		return false,
			`a modifier's 'kind' must be one of {table.concat(Modifiers.KINDS, ", ")}, got {tostring(
				kind
			)}`
	end
	if modifier.mute ~= nil and type(modifier.mute) ~= "boolean" then
		return false, `a {kind} modifier's 'mute' must be true or false`
	end
	local influence = modifier.influence
	if influence ~= nil and not (finite(influence) and influence >= 0 and influence <= 1) then
		return false, `a {kind} modifier's 'influence' must be a number from 0 to 1`
	end
	local bakeRate = modifier.bakeRate
	if bakeRate ~= nil and not (finite(bakeRate) and bakeRate > 0) then
		return false,
			`a {kind} modifier's 'bakeRate' must be a number of samples per second above 0`
	end
	local range = modifier.range
	if range ~= nil then
		if type(range) ~= "table" or not (finite(range.from) and finite(range.to)) then
			return false, `a {kind} modifier's 'range' must have numbers 'from' and 'to'`
		end
		if range.from > range.to then
			return false, `a {kind} modifier's range starts after it ends`
		end
		local blendIn, blendOut = range.blendIn or 0, range.blendOut or 0
		if not (finite(blendIn) and blendIn >= 0 and finite(blendOut) and blendOut >= 0) then
			return false, `a {kind} modifier's 'blendIn' and 'blendOut' must be 0 or more seconds`
		end
		if blendIn + blendOut > range.to - range.from then
			return false, `a {kind} modifier's blend in and out are longer than its range`
		end
	end
	local problem = VALIDATE[kind](modifier)
	if problem ~= nil then
		return false, problem
	end
	return true, nil
end

function Modifiers.validateStack(stack: any): (boolean, string?)
	if stack == nil then
		return true, nil
	end
	if type(stack) ~= "table" then
		return false, `a channel's 'modifiers' must be a list, got {type(stack)}`
	end
	for i, modifier in stack do
		local ok, problem = Modifiers.validate(modifier)
		if not ok then
			return false, `modifier {i}: {problem}`
		end
		if modifier.kind == "Cycles" and i ~= 1 then
			return false, `modifier {i}: a Cycles modifier must be the first in the stack`
		end
	end
	return true, nil
end

return Modifiers
