--!strict
--!native
--!optimize 2

local Interp = require(script.Parent.Interp)
local PathSpline = require(script.Parent.PathSpline)

local Movement = {}

export type MovementKey = {
	t: number,
	kind: "Walk" | "Target" | "Waypoint",
	speed: number?,
	direction: number?,
	turn: number?,
	cframe: { number }?,
	transition: number?,
	interp: Interp.Interp?,
	easing: Interp.Easing?,
	params: Interp.Params?,
	handles: { number }?,
	shape: string?,
	shapeIn: { number }?,
	shapeOut: { number }?,
	face: string?,
	lean: number?,
}

export type MovementTrack = {
	keys: { MovementKey },
	joints: { [string]: { keys: { MovementKey } } }?,
}

local NO_KEYS: { MovementKey } = table.freeze({}) :: any

Movement.DEFAULT_TURN = 0.2

Movement.TRANSITION_STEPS = 16

Movement.DEFAULT_HANDLES = table.freeze({ 1 / 3, 0, 2 / 3, 1 })

local TAU = 2 * math.pi

function Movement.heading(direction: number): Vector3
	return Vector3.new(-math.sin(direction), 0, -math.cos(direction))
end

function Movement.facing(cframe: CFrame): number
	local look = cframe.LookVector
	if look.X * look.X + look.Z * look.Z < 1e-12 then
		look = if look.Y < 0 then cframe.UpVector else -cframe.UpVector
	end
	return math.atan2(-look.X, -look.Z)
end

function Movement.cframeOf(key: MovementKey): CFrame
	local data = key.cframe
	if data == nil then
		return CFrame.identity
	end
	return CFrame.new(table.unpack(data, 1, 12))
end

local function headingOf(key: MovementKey, start: CFrame): number
	return key.direction or Movement.facing(start)
end

local function wrapped(angle: number): number
	return (angle + math.pi) % TAU - math.pi
end

local function glided(key: MovementKey, elapsed: number, duration: number): number
	return PathSpline.share(key :: any, elapsed, duration)
end

function Movement.runOf(keys: { MovementKey }, index: number): (number, number)
	local first, last = index, index
	while first > 1 and keys[first - 1].kind == "Waypoint" do
		first -= 1
	end
	while keys[last + 1] ~= nil and keys[last + 1].kind == "Waypoint" do
		last += 1
	end
	return first, last
end

function Movement.pathOf(keys: { MovementKey }, index: number): (PathSpline.Built, number)
	local first, last = Movement.runOf(keys, index)
	local points = table.move(keys, first, last, 1, table.create(last - first + 1))
	return PathSpline.build(points :: any), first
end

function Movement.placeOf(keys: { MovementKey }, index: number): CFrame
	local key = keys[index]
	if key.kind ~= "Waypoint" then
		return Movement.cframeOf(key)
	end
	local path, first = Movement.pathOf(keys, index)
	if #path.points < 2 then
		return Movement.cframeOf(key)
	end
	return PathSpline.frameAt(path, path.at[index - first + 1], 0)
end

function Movement.transitionOf(keys: { MovementKey }, index: number): number
	local key, following = keys[index], keys[index + 1]
	if following == nil or key.interp == "Constant" then
		return 0
	end
	local span = math.max(following.t - key.t, 0)
	local length = key.transition
	if length == nil then
		length = if key.kind ~= "Walk" and following.kind ~= "Walk" then span else 0
	end
	return math.clamp(length, 0, span)
end

local function own(keys: { MovementKey }, index: number, start: CFrame, elapsed: number): CFrame
	local key = keys[index]
	if key.kind ~= "Walk" then
		return Movement.placeOf(keys, index)
	end
	local speed = key.speed or 0
	local position = start.Position
	if speed > 0 then
		position += Movement.heading(headingOf(key, start)) * (speed * elapsed)
	end
