local function blendOf(keys: { MovementKey }, index: number, start: CFrame, length: number): Blend
	local key, following = keys[index], keys[index + 1]
	local begins = following.t - key.t - length
	local from = own(keys, index, start, begins)
	local faced = Movement.facing(from)
