	local speed = if key.kind == "Walk" then key.speed or 0 else 0
	local heading = if key.kind == "Walk" then headingOf(key, start) else toward
	return {
		from = from,
		length = length,
		speed = speed,
		gain = (following.speed or 0) - speed,
		heading = heading,
		swing = wrapped(toward - heading),
		turn = wrapped(toward - faced),
	}
