local function blendWalk(key: MovementKey, blend: Blend, into: number): (number, number)
	local weight = glided(key, into, blend.length)
	return blend.speed + blend.gain * weight, blend.heading + blend.swing * weight
end

local function walkInto(key: MovementKey, blend: Blend, into: number): CFrame
	local from = blend.from
	local position = from.Position
	if into > 0 then
		local steps = Movement.TRANSITION_STEPS
		local step = into / steps
		local sum = Vector3.zero
		for index = 0, steps do
			local speed, heading = blendWalk(key, blend, index * step)
			local factor = if index == 0 or index == steps then 1 elseif index % 2 == 1 then 4 else 2
			sum += Movement.heading(heading) * (speed * factor)
