local function within(keys: { MovementKey }, index: number, start: CFrame, elapsed: number): CFrame
	local length = Movement.transitionOf(keys, index)
	if length <= 0 then
		return own(keys, index, start, elapsed)
	end
	local key, following = keys[index], keys[index + 1]
	local begins = following.t - key.t - length
	if elapsed <= begins then
		return own(keys, index, start, elapsed)
	end
	if key.kind == "Waypoint" and following.kind == "Waypoint" then
		local path, first = Movement.pathOf(keys, index)
		local stretch = index - first + 1
		local into = elapsed - begins
		local distance = path.lengths[stretch]
		local share = glided(key, into, length)
