local function locate(keys: { MovementKey }, t: number): (number?, CFrame)
	local here = CFrame.identity
	for index, key in keys do
		if key.t > t then
			return nil, here
		end
		local following = keys[index + 1]
		if following == nil or following.t > t then
			return index, here
		end
		if following.kind == "Walk" then
			here = within(keys, index, here, following.t - key.t)
