--!strict

local Interp = require(script.Parent.Interp)
local Modifiers = require(script.Parent.Modifiers)
local Movement = require(script.Parent.Movement)
local Pose = require(script.Parent.Pose)

local MovementFold = {}

export type Spec = {
	joint: string,
	rest: CFrame,
	keys: { Movement.MovementKey },
}

export type Options = {
	presets: { [string]: any }?,
	fps: number?,
}

export type FlatTrack = {
	rotationMode: Pose.RotationMode,
	channels: {
		[string]: {
			keys: { { t: number, v: number, interp: string } },
			bakeRate: number?,
			steep: { number }?,
		},
	},
	sample: (t: number) -> CFrame,
}

local SAME = 1e-9
local STILL = 1e-6

local EULER_ORDER: Pose.RotationMode = "XYZ"

function MovementFold.inAnimation(doc: { movement: any? }?): boolean
	local track = if doc ~= nil then doc.movement else nil
	return track ~= nil and track.export == "Animation" and Movement.keyed(track)
end

local function movesTime(channel: Modifiers.Channel): boolean
	for _, modifier in channel.modifiers or {} do
		if modifier.mute ~= true then
			local kind = modifier.kind
			if kind == "Cycles" or kind == "Stepped" then
				return true
			elseif kind == "Limits" and (modifier.minTime ~= nil or modifier.maxTime ~= nil) then
				return true
			end
		end
	end
	return false
end

local function rateOf(channel: Modifiers.Channel, best: number?): number?
	local rates = { (channel :: any).bakeRate }
	for _, modifier in channel.modifiers or {} do
		if modifier.mute ~= true then
			table.insert(rates, modifier.bakeRate)
		end
	end
	for _, rate in rates do
		if
			type(rate) == "number"
			and rate > 0
			and rate < math.huge
			and (best == nil or rate > best)
		then
			best = rate
		end
	end
	return best
end

local function uniqueTimes(times: { number }, length: number): { number }
	table.sort(times)
	local out: { number } = {}
	for _, t in times do
		if t >= -SAME and t <= length + SAME and (#out == 0 or t - out[#out] > SAME) then
			table.insert(out, math.clamp(t, 0, length))
		end
	end
	return out
end

local function movementKnots(
	keys: { Movement.MovementKey },
	presets: { [string]: any }?,
	times: { number },
	steep: { number }
)
	for index, key in keys do
		table.insert(times, key.t)
		local following = keys[index + 1]
		if key.kind == "Walk" and key.direction ~= nil then
			local ends = key.t + (key.turn or Movement.DEFAULT_TURN)
			if following == nil or ends < following.t then
				table.insert(times, ends)
			end
		end
		local length = Movement.transitionOf(keys, index)
		if length > 0 then
			local begins = following.t - length
			table.insert(times, begins)
			local transition = {
				keys = {
					{
						t = begins,
						v = 0,
						interp = key.interp or "Linear",
						easing = key.easing,
						params = key.params,
					},
					{ t = following.t, v = 1 },
				},
			}
			Interp.easingKnots(transition :: any, presets, times, steep)
		end
	end
end

local function offRest(values: Pose.Values, name: string): number
	local value = (values :: any)[name] or 0
	return if name == "qw" then math.abs(value - 1) else math.abs(value)
end

function MovementFold.flatten<D>(doc: D, spec: Spec, options: Options?): D
	local source = doc :: any
	if #spec.keys == 0 then
		return doc
	end
	local movement: Movement.MovementTrack = { keys = spec.keys }
	local length = math.max(source.length, 0)
	local evalOptions: Options = {
		presets = if options ~= nil and options.presets ~= nil
			then options.presets
			else source.presets,
		fps = if options ~= nil and options.fps ~= nil then options.fps else source.fps,
	}
	local track: any = source.joints[spec.joint]
	local mode: Pose.RotationMode = if track ~= nil then track.rotationMode else EULER_ORDER
	local rest = spec.rest
	local function poseAt(t: number): CFrame
		if track == nil then
			return CFrame.identity
		end
		local own = track.sample
		if own ~= nil then
			return own(t)
		end
		return (Pose.evaluate :: any)(track, t, evalOptions)
	end
	local function sample(t: number): CFrame
		return Movement.fold(poseAt(t), rest, Movement.at(movement, t))
	end

	local times: { number } = { 0, length }
	local steep: { number } = {}
	local rate: number? = nil
	local scan = if evalOptions.fps ~= nil and evalOptions.fps > 0 then evalOptions.fps else 60
	local owned: { [string]: boolean } = {}
	if track ~= nil then
		for name, channel in track.channels do
			owned[name] = true
			rate = rateOf(channel, rate)
			local carried = channel.steep
			if carried ~= nil then
				table.move(carried, 1, #carried, #steep + 1, steep)
				table.move(carried, 1, #carried, #times + 1, times)
			end
			if not movesTime(channel) then
				for _, key in channel.keys do
					table.insert(times, key.t)
				end
				Interp.easingKnots(channel, evalOptions.presets, times, steep)
				Modifiers.clampKnots(channel, 0, length, scan, evalOptions :: any, times)
			end
		end
	end
	movementKnots(movement.keys, evalOptions.presets, times, steep)
	local knots = uniqueTimes(times, length)
	local steepTimes = uniqueTimes(steep, length)

	local function valuesAt(list: { number }): { Pose.Values }
		local previous: Pose.Values? = nil
		if mode ~= "Quaternion" and track ~= nil then
			local seed: { [string]: number } = {}
			for _, name in Pose.EULER_CHANNELS do
				local channel = track.channels[name]
				if channel ~= nil then
					seed[name] = Modifiers.evaluate(channel, list[1], evalOptions :: any)
				end
			end
			previous = seed :: any
		end
		local out: { Pose.Values } = table.create(#list)
		for index, t in list do
			local read = Pose.toValues(sample(t), mode, previous)
			out[index] = read
			previous = read
		end
		return out
	end
	local values = valuesAt(knots)

	local grid = table.clone(knots)
	for step = 1, math.floor(length * scan + 1e-9) do
		table.insert(grid, step / scan)
	end
	local gridValues = valuesAt(uniqueTimes(grid, length))
	local rotations = if mode == "Quaternion" then Pose.QUATERNION_CHANNELS else Pose.EULER_CHANNELS
	local function moved(name: string): boolean
		if owned[name] then
			return true
		end
		for _, read in gridValues do
			if offRest(read, name) > STILL then
				return true
			end
		end
		return false
	end
	local names: { string } = {}
	for _, name in Pose.POSITION_CHANNELS do
		if moved(name) then
			table.insert(names, name)
		end
	end
	local turned = false
	for _, name in rotations do
		if moved(name) then
			turned = true
			if mode ~= "Quaternion" then
				table.insert(names, name)
			end
		end
	end
	if turned and mode == "Quaternion" then
		table.move(rotations, 1, #rotations, #names + 1, names)
	end

	local channels = {}
	for _, name in names do
		local keys = table.create(#knots)
		for index, t in knots do
			keys[index] = { t = t, v = (values[index] :: any)[name] or 0, interp = "Linear" }
		end
		channels[name] = {
			keys = keys,
			bakeRate = rate,
			steep = if #steepTimes > 0 then steepTimes else nil,
		}
	end
	local flat: FlatTrack = {
		rotationMode = mode,
		channels = channels,
		sample = sample,
	}

	local joints = table.clone(source.joints)
	joints[spec.joint] = flat
	local out = table.clone(source)
	out.joints = joints
	return out :: any
end

return MovementFold
