--!strict
--!native
--!optimize 2

local NativeCurve = {}

export type Interp = "Constant" | "Linear" | "Cubic"

export type Key = {
	t: number,
	v: number,
	interp: Interp,
	leftTangent: number?,
	rightTangent: number?,
}

export type RotationKey = {
	t: number,
	w: number,
	x: number,
	y: number,
	z: number,
	interp: Interp,
	leftTangent: number?,
	rightTangent: number?,
}

NativeCurve.INTERPS = { "Constant", "Linear", "Cubic" }

local sqrt, sin, atan2 = math.sqrt, math.sin, math.atan2

function NativeCurve.cubicBasis(u: number, duration: number): (number, number, number, number)
	local u2 = u * u
	local u3 = u2 * u
	return 2 * u3 - 3 * u2 + 1, 3 * u2 - 2 * u3, (u3 - 2 * u2 + u) * duration, (u3 - u2) * duration
end

function NativeCurve.segment(a: Key, b: Key, t: number): number
	if t <= a.t then
		return a.v
	elseif t >= b.t then
		return b.v
	end
	local interp = a.interp
	if interp == "Constant" then
		return a.v
	end
	local duration = b.t - a.t
	local u = (t - a.t) / duration
	if interp == "Cubic" then
		local w0, w1, wLeft, wRight = NativeCurve.cubicBasis(u, duration)
		return w0 * a.v + w1 * b.v + wLeft * (a.rightTangent or 0) + wRight * (b.leftTangent or 0)
	end
	return a.v + (b.v - a.v) * u
end

local function segmentOf(keys: { any }, t: number): number
	local lo, hi = 1, #keys
	while hi - lo > 1 do
		local mid = (lo + hi) // 2
		if keys[mid].t <= t then
			lo = mid
		else
			hi = mid
		end
	end
	return lo
end

function NativeCurve.evaluate(keys: { Key }, t: number): number
	local n = #keys
	if n == 0 then
		return 0
	end
	local first = keys[1]
	if t <= first.t then
		return first.v
	end
	local last = keys[n]
	if t >= last.t then
		return last.v
	end
	local i = segmentOf(keys, t)
	return NativeCurve.segment(keys[i], keys[i + 1], t)
end

function NativeCurve.rotationOrder(order: string): string
	return order
end

local orderItems: { [string]: any } = {}

function NativeCurve.eulerRotation(x: number, y: number, z: number, rotationOrder: string): CFrame
	local item = orderItems[rotationOrder]
	if item == nil then
		item = (Enum.RotationOrder :: any)[rotationOrder]
		orderItems[rotationOrder] = item
	end
	return CFrame.fromEulerAngles(x, y, z, item)
end

local function slerp(
	aw: number,
	ax: number,
	ay: number,
	az: number,
	bw: number,
	bx: number,
	by: number,
	bz: number,
	u: number
): (number, number, number, number)
	if aw * bw + ax * bx + ay * by + az * bz < 0 then
		bw, bx, by, bz = -bw, -bx, -by, -bz
	end
	local dw, dx, dy, dz = aw - bw, ax - bx, ay - by, az - bz
	local sw, sx, sy, sz = aw + bw, ax + bx, ay + by, az + bz
	local theta = 2
		* atan2(
			sqrt(dw * dw + dx * dx + dy * dy + dz * dz),
			sqrt(sw * sw + sx * sx + sy * sy + sz * sz)
		)
	local wa: number, wb: number
	if theta < 1e-9 then
		wa, wb = 1 - u, u
	else
		local s = sin(theta)
		wa, wb = sin((1 - u) * theta) / s, sin(u * theta) / s
	end
	local w, x, y, z = wa * aw + wb * bw, wa * ax + wb * bx, wa * ay + wb * by, wa * az + wb * bz
	local length = sqrt(w * w + x * x + y * y + z * z)
	if length == 0 then
		return 1, 0, 0, 0
	end
	return w / length, x / length, y / length, z / length
end

function NativeCurve.rotationSegment(
	a: RotationKey,
	b: RotationKey,
	t: number
): (number, number, number, number)
	if t <= a.t or a.interp == "Constant" and t < b.t then
		return a.w, a.x, a.y, a.z
	elseif t >= b.t then
		return b.w, b.x, b.y, b.z
	end
	local u = (t - a.t) / (b.t - a.t)
	if a.interp == "Cubic" then
		local _, w1, wLeft, wRight = NativeCurve.cubicBasis(u, 1)
		u = w1 + wLeft * (a.rightTangent or 0) + wRight * (b.leftTangent or 0)
	end
	return slerp(a.w, a.x, a.y, a.z, b.w, b.x, b.y, b.z, u)
end

function NativeCurve.evaluateRotation(
	keys: { RotationKey },
	t: number
): (number, number, number, number)
	local n = #keys
	if n == 0 then
		return 1, 0, 0, 0
	end
	local first = keys[1]
	if t <= first.t then
		return first.w, first.x, first.y, first.z
	end
	local last = keys[n]
	if t >= last.t then
		return last.w, last.x, last.y, last.z
	end
	local i = segmentOf(keys, t)
	return NativeCurve.rotationSegment(keys[i], keys[i + 1], t)
end

function NativeCurve.quaternionRotation(w: number, x: number, y: number, z: number): CFrame
	return CFrame.new(0, 0, 0, x, y, z, w)
end

function NativeCurve.pose(x: number, y: number, z: number, rotation: CFrame): CFrame
	return CFrame.new(x, y, z) * rotation
end

return NativeCurve
