function PathSpline.locate(built: Built, s: number): (number, number)
	local n = #built.points
	if n < 2 then
		return 1, 0
	end
	local at = built.at
	local low, high = 1, n - 1
	while low < high do
		local middle = (low + high + 1) // 2
		if at[middle] <= s then
			low = middle
		else
			high = middle - 1
		end
	end
	local index = low
	local into = math.clamp(s - at[index], 0, built.lengths[index])
	local arc = built.arcs[index]
	local pieces = PathSpline.PIECES
	local k = 1
	while k < pieces and arc[k + 1] < into do
		k += 1
	end
	local from, to = arc[k], arc[k + 1]
	local part = if to - from > NEAR then (into - from) / (to - from) else 0
	return index, math.clamp((k - 1 + part) / pieces, 0, 1)
