function PathSpline.directionAt(built: Built, s: number): Vector3
	local n = #built.points
	if n < 2 then
		return if n == 1 then lookOf(built, 1) else -Vector3.zAxis
	end
	local at = math.clamp(s, 0, built.total)
	for index = 2, n - 1 do
		local radius = built.radius[index]
		local mark = built.at[index]
		if radius > NEAR and math.abs(at - mark) < radius then
			local share = smooth((at - mark + radius) / (2 * radius))
