function PathSpline.leanAt(built: Built, s: number, speed: number, lean: number): number
	if lean <= 0 or speed <= 0 then
		return 0
	end
	local index = PathSpline.locate(built, s)
	local reach = LEAN_REACH
	local before = math.max(s - reach, 0)
	local after = math.min(s + reach, built.total)
	if after - before <= NEAR then
		return 0
	end
	local turning = wrapped(headingAt(built, after, index) - headingAt(built, before, index))
		/ (after - before)
	local angle = lean * math.atan(speed * speed * turning / PathSpline.GRAVITY)
	return math.clamp(angle, -PathSpline.MAX_LEAN, PathSpline.MAX_LEAN)
