local function slopeUp(built: Built, index: number, u: number, along: Vector3): Vector3
	local ups = built.ups[index]
	if ups == nil then
		return carriedUp(Vector3.yAxis, along) or Vector3.xAxis
	end
	local pieces = PathSpline.PIECES
	local scaled = u * pieces
	local k = math.clamp(math.floor(scaled), 0, pieces - 1)
	local up = ups[k + 1]:Lerp(ups[k + 2], scaled - k)
	up = carriedUp(up, along) or carriedUp(Vector3.yAxis, along) or Vector3.xAxis
	return rolled(up, along, (built.twist[index] or 0) * u)
