function PathSpline.frameAt(built: Built, s: number, speed: number?, forward: string?): CFrame
	local n = #built.points
	if n == 0 then
		return CFrame.identity
	elseif n == 1 then
		return PathSpline.cframeOf(built.points[1])
	end
	local at = math.clamp(s, 0, built.total)
	local index, u = PathSpline.locate(built, at)
	local point = built.points[index]
	local p0, p1, p2, p3 = PathSpline.piece(built, index)
	local position = bezier(p0, p1, p2, p3, u)
	local face = point.face or "Turn"
	if face == "Own" then
		local length = built.lengths[index]
		local share = if length > NEAR then (at - built.at[index]) / length else 1
