	end
	local bank = PathSpline.leanAt(built, at, speed or 0, point.lean or 0)
	local fix = PathSpline.forwardFix(forward)
	if face == "Slope" then
		local along = PathSpline.directionAt(built, at)
		local up = slopeUp(built, index, u, along)
		local right = along:Cross(up)
		local rotation = CFrame.fromMatrix(Vector3.zero, right, up, -along)
		return CFrame.new(position) * rotation * CFrame.Angles(0, 0, bank) * fix
	end
