function PathSpline.share(point: Point, elapsed: number, duration: number): number
	local mode = point.interp or "Linear"
	if mode == "Constant" then
		return 0
	elseif duration <= 0 then
		return 1
	elseif mode == "Linear" then
		return math.clamp(elapsed / duration, 0, 1)
	elseif mode == "Bezier" then
		local handles = point.handles or PathSpline.DEFAULT_HANDLES
		return Interp.bezier(
			0,
			0,
			handles[1],
			handles[2],
			handles[3],
			handles[4],
			1,
			1,
			math.clamp(elapsed / duration, 0, 1)
		)
	end
	return Interp.ease(
		mode,
		point.easing,
		math.clamp(elapsed, 0, duration),
		0,
		1,
		duration,
		point.params
	)
end

function PathSpline.speed(point: Point, elapsed: number, duration: number, length: number): number
	if duration <= 0 or length <= 0 or point.interp == "Constant" then
		return 0
	end
	local step = math.min(1 / 240, duration / 4)
	local from = math.max(elapsed - step, 0)
	local to = math.min(elapsed + step, duration)
	if to - from <= 0 then
		return 0
	end
	local gone = PathSpline.share(point, to, duration) - PathSpline.share(point, from, duration)
	return math.abs(gone) * length / (to - from)
