--!strict

local StateEval = require(script.Parent.StateEval)

local ReleaseMath = {}

ReleaseMath.DEFAULT_LIFETIME = 10
ReleaseMath.DEFAULT_CAP = 30

ReleaseMath.DECIMALS = 4

ReleaseMath.MAX_POINTS = 256

local EPSILON = 1e-9

local function round(value: number): number
	local back = tonumber(string.format(`%.{ReleaseMath.DECIMALS}f`, value)) :: number
	return if back == 0 then 0 else back
end

local function triple(vector: Vector3): { number }
	return { round(vector.X), round(vector.Y), round(vector.Z) }
end

local function isTriple(value: any): boolean
	if type(value) ~= "table" or #value ~= 3 then
		return false
	end
	for index = 1, 3 do
		local n = value[index]
		if type(n) ~= "number" or n ~= n or n == math.huge or n == -math.huge then
			return false
		end
	end
	return true
end

export type EndBehaviour = "Persist" | "Revert"

export type ReleaseKind = "Release" | "Attach"

export type Release = {
	t: number,
	joint: string,
	kind: ReleaseKind?,
	lifetime: number?,
	cap: number?,
	cosmetic: boolean?,
	collide: boolean?,
	event: string?,
	onEnd: EndBehaviour?,
	push: { number }?,
	spin: { number }?,
	leaveCopy: boolean?,
	onto: { kind: string, joint: string?, slot: string? }?,
	velocity: VelocityData?,
}

export type Velocity = {
	linear: Vector3,
	angular: Vector3,
}

export type VelocityData = {
	linear: { number },
	angular: { number },
}

export type WorldAt = (t: number) -> CFrame?

export type Entry = {
	key: string,
	id: any,
	born: number,
	dies: number,
}

export type Ledger = {
	entries: { Entry },
}

export type NativeMarker = StateEval.NativeMarker

local function turnBetween(a: CFrame, b: CFrame): (Vector3, number)
	local _, _, _, a00, a01, a02, a10, a11, a12, a20, a21, a22 = a:GetComponents()
	local _, _, _, b00, b01, b02, b10, b11, b12, b20, b21, b22 = b:GetComponents()
	local d00 = b00 * a00 + b01 * a01 + b02 * a02
	local d01 = b00 * a10 + b01 * a11 + b02 * a12
	local d02 = b00 * a20 + b01 * a21 + b02 * a22
	local d10 = b10 * a00 + b11 * a01 + b12 * a02
	local d11 = b10 * a10 + b11 * a11 + b12 * a12
	local d12 = b10 * a20 + b11 * a21 + b12 * a22
	local d20 = b20 * a00 + b21 * a01 + b22 * a02
	local d21 = b20 * a10 + b21 * a11 + b22 * a12
	local d22 = b20 * a20 + b21 * a21 + b22 * a22
	local w, x, y, z
	local trace = d00 + d11 + d22
	if trace > 0 then
		local s = math.sqrt(trace + 1) * 2
		w, x, y, z = s / 4, (d21 - d12) / s, (d02 - d20) / s, (d10 - d01) / s
	elseif d00 > d11 and d00 > d22 then
		local s = math.sqrt(1 + d00 - d11 - d22) * 2
		w, x, y, z = (d21 - d12) / s, s / 4, (d01 + d10) / s, (d02 + d20) / s
	elseif d11 > d22 then
		local s = math.sqrt(1 + d11 - d00 - d22) * 2
		w, x, y, z = (d02 - d20) / s, (d01 + d10) / s, s / 4, (d12 + d21) / s
	else
		local s = math.sqrt(1 + d22 - d00 - d11) * 2
		w, x, y, z = (d10 - d01) / s, (d02 + d20) / s, (d12 + d21) / s, s / 4
	end
	if w < 0 then
		w, x, y, z = -w, -x, -y, -z
	end
	local sine = math.sqrt(x * x + y * y + z * z)
	if sine < EPSILON then
		return Vector3.zero, 0
	end
	return Vector3.new(x / sine, y / sine, z / sine), 2 * math.atan2(sine, w)
end

function ReleaseMath.angularBetween(a: CFrame, b: CFrame, dt: number): Vector3
	if dt <= 0 then
		return Vector3.zero
	end
	local axis, angle = turnBetween(a, b)
	return axis * (angle / dt)
end

function ReleaseMath.window(t: number, length: number, rate: number): (number, number)
	local h = 1 / math.max(rate, EPSILON)
	local before = math.max(t - h, 0)
	if t - before > EPSILON then
		return before, t
	end
	if t + h <= length + EPSILON then
		return t, t + h
	end
	return 0, length
end

function ReleaseMath.velocity(worldAt: WorldAt, t: number, length: number, rate: number): Velocity?
	local from, to = ReleaseMath.window(t, length, rate)
	local a, b = worldAt(from), worldAt(to)
	if a == nil or b == nil then
		return nil
	end
	local dt = to - from
	if dt <= EPSILON then
		return { linear = Vector3.zero, angular = Vector3.zero }
	end
	return {
		linear = ((b :: CFrame).Position - (a :: CFrame).Position) / dt,
		angular = ReleaseMath.angularBetween(a :: CFrame, b :: CFrame, dt),
	}
end

function ReleaseMath.localize(velocity: Velocity, cframe: CFrame): Velocity
	return {
		linear = cframe:VectorToObjectSpace(velocity.linear),
		angular = cframe:VectorToObjectSpace(velocity.angular),
	}
end

function ReleaseMath.toWorld(velocity: Velocity, cframe: CFrame): Velocity
	return {
		linear = cframe:VectorToWorldSpace(velocity.linear),
		angular = cframe:VectorToWorldSpace(velocity.angular),
	}
end

function ReleaseMath.vectorOf(data: { number }?): Vector3
	if data == nil or not isTriple(data) then
		return Vector3.zero
	end
	return Vector3.new(data[1], data[2], data[3])
end

function ReleaseMath.tripleOf(vector: Vector3): { number }?
	local out = triple(vector)
	if out[1] == 0 and out[2] == 0 and out[3] == 0 then
		return nil
	end
	return out
end

function ReleaseMath.plus(
	velocity: Velocity,
	release: Release,
	part: CFrame,
	root: CFrame
): Velocity
	return {
		linear = velocity.linear + root:VectorToWorldSpace(ReleaseMath.vectorOf(release.push)),
		angular = velocity.angular + part:VectorToWorldSpace(ReleaseMath.vectorOf(release.spin)),
	}
end

function ReleaseMath.isAttach(release: Release): boolean
	return release.kind == "Attach"
end

function ReleaseMath.looseAt(releases: { Release }, joint: string, t: number): boolean
	local loose = false
	for _, release in releases do
		if release.t > t + EPSILON then
			break
		end
		if release.joint == joint then
			loose = not ReleaseMath.isAttach(release)
		end
	end
	return loose
end

export type Span = {
	from: number,
	to: number?,
	open: number,
	close: number?,
}

function ReleaseMath.spans(releases: { Release }, joint: string): { Span }
	local out: { Span } = {}
	local current: Span? = nil
	for index, release in releases do
		if release.joint ~= joint then
			continue
		end
		if ReleaseMath.isAttach(release) then
			if current ~= nil then
				current.to = release.t
				current.close = index
				current = nil
			end
		elseif current == nil then
			local span: Span = { from = release.t, open = index }
			table.insert(out, span)
			current = span
		end
	end
	return out
end

function ReleaseMath.outOfTurn(releases: { Release }): { [number]: boolean }
	local loose: { [string]: boolean } = {}
	local out: { [number]: boolean } = {}
	for index, release in releases do
		local attach = ReleaseMath.isAttach(release)
		if attach == (loose[release.joint] == true) then
			loose[release.joint] = not attach
		else
			out[index] = true
		end
	end
	return out
end

function ReleaseMath.switchTimes(releases: { Release }, joint: string): { number }
	local out: { number } = {}
	for _, span in ReleaseMath.spans(releases, joint) do
		table.insert(out, span.from)
		if span.to ~= nil then
			table.insert(out, span.to :: number)
		end
	end
	return out
end

function ReleaseMath.attachAfter(releases: { Release }, index: number): number?
	local release = releases[index]
	if release == nil then
		return nil
	end
	for next = index + 1, #releases do
		local other = releases[next]
		if other.joint == release.joint and ReleaseMath.isAttach(other) then
			return next
		end
	end
	return nil
end

function ReleaseMath.launch(
	velocity: Velocity?,
	cframe: CFrame,
	centre: Vector3?,
	inheritLinear: Vector3?,
	inheritAngular: Vector3?
): (Vector3, Vector3)
	local linear, angular = Vector3.zero, Vector3.zero
	if velocity ~= nil then
		local world = ReleaseMath.toWorld(velocity, cframe)
		linear, angular = world.linear, world.angular
		if centre ~= nil then
			linear += angular:Cross(centre - cframe.Position)
		end
	end
	return linear + (inheritLinear or Vector3.zero), angular + (inheritAngular or Vector3.zero)
end

function ReleaseMath.encode(velocity: Velocity): VelocityData
	return { linear = triple(velocity.linear), angular = triple(velocity.angular) }
end

function ReleaseMath.isData(value: any): boolean
	return type(value) == "table" and isTriple(value.linear) and isTriple(value.angular)
end

function ReleaseMath.decode(data: any): Velocity?
	if not ReleaseMath.isData(data) then
		return nil
	end
	local l, a = data.linear, data.angular
	return {
		linear = Vector3.new(l[1], l[2], l[3]),
		angular = Vector3.new(a[1], a[2], a[3]),
	}
end

function ReleaseMath.arcAt(start: CFrame, velocity: Velocity, gravity: number, s: number): CFrame
	local position = start.Position
		+ velocity.linear * s
		+ Vector3.new(0, -0.5 * gravity * s * s, 0)
	local rotation = start - start.Position
	local spin = velocity.angular.Magnitude
	if spin > EPSILON then
		rotation = CFrame.fromAxisAngle(velocity.angular / spin, spin * s) * rotation
	end
	return CFrame.new(position) * rotation
end

function ReleaseMath.fallTime(
	linear: Vector3,
	gravity: number,
	drop: number,
	longest: number
): number
	if gravity <= EPSILON then
		return longest
	end
	local up = linear.Y
	local s = (up + math.sqrt(up * up + 2 * gravity * math.max(drop, 0))) / gravity
	return math.min(s, longest)
end

function ReleaseMath.arcPoints(
	origin: Vector3,
	linear: Vector3,
	gravity: number,
	duration: number,
	step: number
): { Vector3 }
	local span = math.max(duration, 0)
	local stride = math.max(step, EPSILON)
	local count = math.ceil(span / stride - EPSILON)
	if count > ReleaseMath.MAX_POINTS - 1 then
		count = ReleaseMath.MAX_POINTS - 1
	end
	local points: { Vector3 } = table.create(count + 1)
	points[1] = origin
	for index = 1, count do
		local s = if index == count then span else index * stride
		points[index + 1] = origin + linear * s + Vector3.new(0, -0.5 * gravity * s * s, 0)
	end
	return points
end

function ReleaseMath.lifetimeOf(release: Release): number
	return release.lifetime or ReleaseMath.DEFAULT_LIFETIME
end

function ReleaseMath.capOf(release: Release): number
	return release.cap or ReleaseMath.DEFAULT_CAP
end

function ReleaseMath.ledger(): Ledger
	return { entries = {} }
end

function ReleaseMath.count(ledger: Ledger, key: string?): number
	if key == nil then
		return #ledger.entries
	end
	local count = 0
	for _, entry in ledger.entries do
		if entry.key == key then
			count += 1
		end
	end
	return count
end

function ReleaseMath.admit(
	ledger: Ledger,
	key: string,
	id: any,
	now: number,
	lifetime: number,
	cap: number
): { Entry }
	local entries = ledger.entries
	table.insert(entries, { key = key, id = id, born = now, dies = now + math.max(lifetime, 0) })
	local limit = math.max(math.floor(cap), 1)
	local over = ReleaseMath.count(ledger, key) - limit
	local evicted: { Entry } = {}
	local index = 1
	while over > 0 and index <= #entries do
		if entries[index].key == key then
			table.insert(evicted, table.remove(entries, index) :: Entry)
			over -= 1
		else
			index += 1
		end
	end
	return evicted
end

function ReleaseMath.expire(ledger: Ledger, now: number): { Entry }
	local kept: { Entry } = {}
	local expired: { Entry } = {}
	for _, entry in ledger.entries do
		if entry.dies <= now + EPSILON then
			table.insert(expired, entry)
		else
			table.insert(kept, entry)
		end
	end
	ledger.entries = kept
	return expired
end

function ReleaseMath.take(ledger: Ledger, keys: { [string]: boolean }): { Entry }
	local kept: { Entry } = {}
	local taken: { Entry } = {}
	for _, entry in ledger.entries do
		if keys[entry.key] then
			table.insert(taken, entry)
		else
			table.insert(kept, entry)
		end
	end
	ledger.entries = kept
	return taken
end

function ReleaseMath.remove(ledger: Ledger, id: any): Entry?
	for index, entry in ledger.entries do
		if entry.id == id then
			return table.remove(ledger.entries, index)
		end
	end
	return nil
end

function ReleaseMath.payload(release: Release): StateEval.Payload
	local payload: StateEval.Payload = { joint = release.joint }
	if ReleaseMath.isAttach(release) then
		payload.attach = true
		return payload
	end
	local data = release.velocity
	if data ~= nil and ReleaseMath.isData(data) then
		local l, a = data.linear, data.angular
		payload.vx, payload.vy, payload.vz = l[1], l[2], l[3]
		payload.wx, payload.wy, payload.wz = a[1], a[2], a[3]
	end
	return payload
end

function ReleaseMath.nativeMarkers(releases: { Release }?): { NativeMarker }
	local out: { NativeMarker } = {}
	for _, release in releases or {} do
		local name = release.event
		if name ~= nil and name ~= "" then
			table.insert(out, {
				name = name,
				t = release.t,
				value = StateEval.encodePayload(ReleaseMath.payload(release)),
			})
		end
	end
	local order: { [NativeMarker]: number } = {}
	for index, marker in out do
		order[marker] = index
	end
	table.sort(out, function(a: NativeMarker, b: NativeMarker): boolean
		if a.t ~= b.t then
			return a.t < b.t
		end
		return order[a] < order[b]
	end)
	return out
end

return ReleaseMath
