local IDENTITY = CFrame.identity
local PARENT = SpaceSolve.PARENT
local BEFORE = SpaceSolve.BEFORE

local POSITION = Pose.POSITION_CHANNELS
local EULER = Pose.EULER_CHANNELS
local QUATERNION = Pose.QUATERNION_CHANNELS
local ROTATIONS = { "rx", "ry", "rz", "qw", "qx", "qy", "qz" }

local SAME = 1e-9

local MOST_ORDERS = 64

local NO_OPTIONS: Options = table.freeze({}) :: any

local function seconds(t: number): string
	return string.format("%.2f s", t)
end

local function sortedKeys(map: { [string]: any }): { string }
	local list: { string } = {}
	for key in map do
		table.insert(list, key)
	end
	table.sort(list)
	return list
end

local function ease(u: number): number
	if u <= 0 then
		return 0
	elseif u >= 1 then
		return 1
	end
	return u * u * (3 - 2 * u)
end

local function stateOf(
	spaces: { SpaceSegment }?,
	starting: SpaceTarget?,
	t: number
): (SpaceTarget, SpaceTarget?, number, number)
	local initial = starting or PARENT
	if spaces == nil then
		return initial, nil, 0, 1
	end
	local index = 0
	for position, switch in spaces do
		if switch.t <= t then
			index = position
		else
			break
		end
	end
	if index == 0 then
		return initial, nil, 0, 1
	end
	local switch = spaces[index]
	local blend = switch.blend or 0
	if blend > 0 and t < switch.t + blend then
		local from = if index > 1 then spaces[index - 1].target else initial
		return switch.target, from, switch.t, ease((t - switch.t) / blend)
	end
	return switch.target, nil, 0, 1
end

local function movesTime(channel: Modifiers.Channel): boolean
	for _, modifier in channel.modifiers or {} do
		if modifier.mute ~= true then
			local kind = modifier.kind
			if kind == "Cycles" or kind == "Stepped" then
				return true
			elseif kind == "Limits" and (modifier.minTime ~= nil or modifier.maxTime ~= nil) then
				return true
			end
		end
	end
	return false
end

local function uniqueTimes(times: { number }, length: number): { number }
	table.sort(times)
	local out: { number } = {}
	for _, t in times do
		if t >= -SAME and t <= length + SAME and (#out == 0 or t - out[#out] > SAME) then
			table.insert(out, math.clamp(t, 0, length))
		end
	end
	return out
end

local function fkValue(doc: Document, address: string, t: number, options: Options): CFrame
	local layers = doc.layers
	if layers ~= nil and #layers > 0 then
		return LayerEval.pose(doc :: any, address, t, options)
	end
	local track = doc.joints[address]
	if track == nil then
		return IDENTITY
	end
	return Pose.evaluate(track, t, options :: any)
end

local SCRATCH: Options = {}

local function optionsFor(doc: Document, options: Options?): Options
	if options ~= nil and options.presets ~= nil and options.fps ~= nil then
		return options
	end
	SCRATCH.presets = if options ~= nil and options.presets ~= nil
		then options.presets
		else doc.presets
	SCRATCH.fps = if options ~= nil and options.fps ~= nil then options.fps else doc.fps
	SCRATCH.solo = if options ~= nil then options.solo else nil
	return SCRATCH
end

local function hierarchyOf(rig: Rig, addresses: { string }): { string }
	local order: { string } = {}
	local seen: { [string]: boolean } = {}
	local function visit(address: string)
		if seen[address] then
			return
		end
		seen[address] = true
		local parent = rig.joints[address].parent
		if parent ~= nil and rig.joints[parent] ~= nil then
			visit(parent)
		end
		table.insert(order, address)
	end
	for _, address in addresses do
		visit(address)
	end
	return order
end

local function restOf(rig: Rig, hierarchy: { string }): ({ [string]: CFrame }, { [string]: CFrame })
	local pivots: { [string]: CFrame } = {}
	local worlds: { [string]: CFrame } = {}
	for _, address in hierarchy do
		local joint = rig.joints[address]
		local parent = joint.parent
		local parentWorld = (if parent ~= nil then worlds[parent] else nil)
			or joint.parentWorld
			or rig.root
		local pivot = parentWorld * joint.parentOffset
		pivots[address] = pivot
		worlds[address] = pivot * joint.childOffset:Inverse()
	end
	return pivots, worlds
end

local function restOfControl(control: Control, pivots: { [string]: CFrame }, root: CFrame): CFrame?
	local pivot: CFrame
	if control.joint ~= nil then
		local found = pivots[control.joint]
		if found == nil then
			return nil
		end
		pivot = found
	else
		pivot = root
	end
	local offset = control.offset
	if offset ~= nil then
		return pivot * CFrame.new(offset[1], offset[2], offset[3])
	end
	return pivot
end

function RigSolve.restPivots(rig: Rig): { [string]: CFrame }
	local pivots = restOf(rig, hierarchyOf(rig, sortedKeys(rig.joints)))
	return pivots
end

function RigSolve.controlRest(rig: Rig, name: string): CFrame?
	local controlRig = rig.controlRig
	local control = if controlRig ~= nil then controlRig.controls[name] else nil
	if control == nil then
		return nil
	end
	return restOfControl(control, RigSolve.restPivots(rig), rig.root)
end

local function chainProblem(
	name: string,
	chain: Chain,
	rig: Rig,
	controls: { [string]: ControlPlan },
	claimed: { [string]: ChainPlan }
): string?
	local links = chain.joints
	if chain.solver == "Aim" then
		if #links ~= 1 then
			return `The IK chain '{name}' aims one joint, so it takes exactly one; it has {#links}.`
		end
	elseif chain.solver == "TwoBone" and #links ~= 3 then
		return `The IK chain '{name}' solves two bones, so it takes exactly three joints; it has {#links}.`
	elseif #links < 2 then
		return `The IK chain '{name}' needs at least two joints.`
	end
	for index, address in links do
		local joint = rig.joints[address]
		if joint == nil then
			return `The IK chain '{name}' needs '{address}', which this rig does not have.`
		end
		if index > 1 and joint.parent ~= links[index - 1] then
			return `The IK chain '{name}' is not one limb: '{address}' does not hang from '{links[index - 1]}'.`
		end
		local other = claimed[address]
		if other ~= nil then
			return `'{address}' is in both the IK chains '{other.name}' and '{name}', so only '{other.name}' solves it.`
		end
	end
	if controls[chain.target] == nil then
		return `The IK chain '{name}' reaches for '{chain.target}', which this rig cannot place.`
	end
	return nil
end

local function tipOf(chain: Chain, rig: Rig, pivots: { [string]: CFrame }): CFrame?
	if chain.solver ~= "Aim" then
		return nil
	end
	local address = chain.joints[#chain.joints]
	local joint = if address ~= nil then rig.joints[address] else nil
	local pivot = if address ~= nil then pivots[address] else nil
	local controlRig = rig.controlRig
	local control = if controlRig ~= nil then controlRig.controls[chain.target] else nil
	if joint == nil or pivot == nil or control == nil then
		return nil
	end
	local rest = restOfControl(control, pivots, rig.root)
	if rest == nil then
		return nil
	end
	local onPivot = pivot:Inverse() * rest
	local point = chain.tip
	if point == nil then
		return onPivot
	end
	local on = joint.childOffset:Inverse() * Vector3.new(point[1], point[2], point[3])
	return CFrame.new(on) * onPivot.Rotation
end

local function tipRestOf(chain: Chain, rig: Rig, tip: CFrame?): TipRest?
	if chain.solver ~= "Aim" or tip == nil then
		return nil
	end
	local joint = rig.joints[chain.joints[#chain.joints]]
	if joint == nil then
		return nil
	end
	local given = chain.tip
	return {
		point = if given ~= nil
			then Vector3.new(given[1], given[2], given[3])
			else joint.childOffset * tip.Position,
		turn = tip.Rotation,
		part = joint.childOffset,
	}
end

local LENGTH_SNAP = math.cos(math.rad(30))

local function lengthOn(childOffset: CFrame, tip: CFrame): Vector3?
	local line = tip.Position
	if line.Magnitude < 1e-4 then
		return nil
	end
	line = line.Unit
	local part = childOffset:Inverse()
	local best: Vector3? = nil
	local nearest = LENGTH_SNAP
	for _, axis in { part.RightVector, part.UpVector, part.LookVector } do
		local dot = axis:Dot(line)
		if math.abs(dot) > nearest then
			best = if dot > 0 then axis else -axis
			nearest = math.abs(dot)
		end
	end
	return best
end

local function lengthOf(chain: Chain, rig: Rig, tip: CFrame?): Vector3?
	if chain.solver ~= "Aim" or tip == nil then
		return nil
	end
	local joint = rig.joints[chain.joints[#chain.joints]]
	if joint == nil then
		return nil
	end
	return lengthOn(joint.childOffset, tip)
end

local function hingeOf(chain: Chain, rig: Rig, pivots: { [string]: CFrame }): Vector3?
	local controlRig = rig.controlRig
	local pole = if chain.solver == "TwoBone"
			and chain.pole ~= nil
			and controlRig ~= nil
		then controlRig.controls[chain.pole]
		else nil
	local middle, tip = pivots[chain.joints[2]], pivots[chain.joints[3]]
	if pole == nil or middle == nil or tip == nil then
		return nil
	end
	local rest = restOfControl(pole, pivots, rig.root)
	local lower = tip.Position - middle.Position
	if rest == nil or lower.Magnitude < 1e-6 then
		return nil
	end
	lower = lower.Unit
	local toPole = rest.Position - middle.Position
	toPole -= lower * toPole:Dot(lower)
	if toPole.Magnitude < 1e-6 then
		return nil
	end
	return middle:VectorToObjectSpace(toPole.Unit:Cross(lower))
end

local function settingsOf(
	chain: Chain,
	rig: Rig,
	tip: CFrame?,
	pivots: { [string]: CFrame }
): IkFk.Settings
	local aims = chain.solver == "Aim"
	return {
		poleAngle = chain.poleAngle,
		stretch = chain.stretch,
		softness = chain.softness,
		iterations = chain.iterations,
		tolerance = chain.tolerance,
		tip = tip,
		share = if aims then chain.foldShare else nil,
		orientTip = if aims then chain.roll else nil,
		slideIn = if aims then chain.slideIn else nil,
		length = lengthOf(chain, rig, tip),
		hinge = hingeOf(chain, rig, pivots),
	}
end

local function keyedSettings(
	settings: IkFk.Settings,
	base: IkFk.Settings,
	name: string,
	solver: string,
	tip: TipRest?,
	doc: Document,
	t: number,
	options: any
)
	settings.stretch = ChainKeys.valueAt(doc, name, "ikStretch", t, options) or base.stretch
	if solver ~= "Aim" then
		return
	end
	settings.share = ChainKeys.valueAt(doc, name, "ikFold", t, options) or base.share
	settings.slideIn = ChainKeys.valueAt(doc, name, "ikSlideIn", t, options) or base.slideIn
	settings.orientTip = ChainKeys.valueAt(doc, name, "ikRoll", t, options) or base.orientTip
	settings.lean = ChainKeys.valueAt(doc, name, "ikLean", t, options)
	local x = ChainKeys.valueAt(doc, name, "ikTipX", t, options)
	local y = ChainKeys.valueAt(doc, name, "ikTipY", t, options)
	local z = ChainKeys.valueAt(doc, name, "ikTipZ", t, options)
	if tip ~= nil and (x ~= nil or y ~= nil or z ~= nil) then
		local point = tip.point
		local on = tip.part:Inverse() * Vector3.new(x or point.X, y or point.Y, z or point.Z)
		local keyedTip = CFrame.new(on) * tip.turn
		settings.tip = keyedTip
		settings.length = lengthOn(tip.part, keyedTip)
	else
		settings.tip = base.tip
		settings.length = base.length
	end
end

local function movesOf(chain: Chain, doc: Document, name: string): { [string]: boolean }
	local moves: { [string]: boolean } = {}
	local stretches = (chain.stretch ~= nil and chain.stretch > 1)
		or ChainKeys.channelOf(doc, name, "ikStretch") ~= nil
	if chain.solver == "Aim" then
		if
			stretches
			or (chain.foldShare or 0) > 0
			or chain.slideIn == true
			or ChainKeys.channelOf(doc, name, "ikFold") ~= nil
			or ChainKeys.channelOf(doc, name, "ikSlideIn") ~= nil
		then
			moves[chain.joints[1]] = true
		end
	elseif stretches then
		for index = 2, #chain.joints do
			moves[chain.joints[index]] = true
		end
	end
	return moves
end

function RigSolve.tipOf(rig: Rig, name: string): CFrame
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	if chain == nil then
		return IDENTITY
	end
	return tipOf(chain, rig, RigSolve.restPivots(rig)) or IDENTITY
end

local function soleOf(
	chain: Chain,
	plant: Control,
	rig: Rig,
	pivots: { [string]: CFrame }
): Vector3?
	local plantRest = restOfControl(plant, pivots, rig.root)
	local last = pivots[chain.joints[#chain.joints]]
	if plantRest == nil or last == nil then
		return nil
	end
	return last:PointToObjectSpace(plantRest.Position)
end

function RigSolve.tips(rig: Rig): { [string]: CFrame }
	local out: { [string]: CFrame } = {}
	local controlRig = rig.controlRig
	if controlRig == nil then
		return out
	end
	local pivots: { [string]: CFrame }? = nil
	for name, chain in controlRig.chains do
		if chain.solver == "Aim" then
			pivots = pivots or RigSolve.restPivots(rig)
			out[name] = tipOf(chain, rig, pivots :: { [string]: CFrame })
		end
	end
	return out
end

function RigSolve.settingsOf(rig: Rig, name: string): IkFk.Settings?
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	if chain == nil then
		return nil
	end
	local pivots = RigSolve.restPivots(rig)
	return settingsOf(chain, rig, tipOf(chain, rig, pivots), pivots)
end

function RigSolve.settingsAt(
	doc: Document,
	rig: Rig,
	name: string,
	t: number,
	options: Options?
): IkFk.Settings?
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	if chain == nil then
		return nil
	end
	local pivots = RigSolve.restPivots(rig)
	local tip = tipOf(chain, rig, pivots)
	local base = settingsOf(chain, rig, tip, pivots)
	local settings = table.clone(base)
	keyedSettings(
		settings,
		base,
		name,
		chain.solver,
		tipRestOf(chain, rig, tip),
		doc,
		t,
		optionsFor(doc, options)
	)
	return settings
end

function RigSolve.tipReader(
	rig: Rig,
	name: string
): (doc: Document, t: number, options: Options?) -> CFrame
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	local tip = if chain ~= nil then tipOf(chain, rig, RigSolve.restPivots(rig)) else nil
	local rest = if chain ~= nil then tipRestOf(chain, rig, tip) else nil
	if tip == nil or rest == nil then
		return function()
			return IDENTITY
		end
	end
	local fixed = tip :: CFrame
	local at = rest :: TipRest
	return function(doc: Document, t: number, options: Options?): CFrame
		local evalOptions = optionsFor(doc, options)
		local x = ChainKeys.valueAt(doc, name, "ikTipX", t, evalOptions :: any)
		local y = ChainKeys.valueAt(doc, name, "ikTipY", t, evalOptions :: any)
		local z = ChainKeys.valueAt(doc, name, "ikTipZ", t, evalOptions :: any)
		if x == nil and y == nil and z == nil then
			return fixed
		end
		local point = at.point
		return CFrame.new(at.part:Inverse() * Vector3.new(x or point.X, y or point.Y, z or point.Z))
			* at.turn
	end
end

function RigSolve.tipAt(doc: Document, rig: Rig, name: string, t: number, options: Options?): CFrame
	return RigSolve.tipReader(rig, name)(doc, t, options)
end

function RigSolve.tipsAt(
	doc: Document,
	rig: Rig,
	t: number,
	tips: { [string]: CFrame }?,
	options: Options?
): { [string]: CFrame }
	local base = tips or RigSolve.tips(rig)
	local out = base
	for name in base do
		for _, family in ChainKeys.TIP do
			if ChainKeys.channelOf(doc, name, family) ~= nil then
				if out == base then
					out = table.clone(base)
				end
				out[name] = RigSolve.tipAt(doc, rig, name, t, options)
				break
			end
		end
	end
	return out
end

function RigSolve.tipPoint(rig: Rig, name: string): Vector3?
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	if chain == nil then
		return nil
	end
	local rest = tipRestOf(chain, rig, tipOf(chain, rig, RigSolve.restPivots(rig)))
	return if rest ~= nil then rest.point else nil
end

function RigSolve.chainKeyAt(
	doc: Document,
	rig: Rig,
	name: string,
	family: string,
	t: number,
	options: Options?
): number?
	local controlRig = rig.controlRig
	local chain = if controlRig ~= nil then controlRig.chains[name] else nil
	if chain == nil then
		return nil
	end
	local keyed = ChainKeys.valueAt(doc, name, family, t, optionsFor(doc, options) :: any)
	if keyed ~= nil then
		return keyed
	end
	local key = ChainKeys.of(family)
	local point = if key ~= nil and key.axis ~= nil then RigSolve.tipPoint(rig, name) else nil
	return ChainKeys.rigValue(chain, family, point)
end

local function newSolved(): Solved
	return {
		transforms = {},
		pivots = {},
		worlds = {},
		controls = {},
		weights = {},
		plants = {},
		grips = {},
		strengths = {},
	}
end

local function childCounts(rig: Rig): { [string]: number }
	local counts: { [string]: number } = {}
	for _, joint in rig.joints do
		local parent = joint.parent
		if parent ~= nil then
			counts[parent] = (counts[parent] or 0) + 1
		end
	end
	return counts
end

local function under(rig: Rig, address: string, released: string): boolean
	local current: string? = address
	while current ~= nil do
		if current == released then
			return true
		end
		local joint = rig.joints[current]
		current = if joint ~= nil then joint.parent else nil
	end
	return false
end

local function looseOf(doc: Document, rig: Rig, grip: Grip): { { number } }
	local spans: { { number } } = {}
	local releases = doc.releases
	if releases == nil then
		return spans
	end
	local watched = { grip.target }
	local space = grip.space
	if space.kind == "Joint" and space.joint ~= nil then
		table.insert(watched, space.joint)
	end
	local open: { [string]: number } = {}
	for _, entry in releases do
		local hit = false
		for _, address in watched do
			if under(rig, address, entry.joint) then
				hit = true
				break
			end
		end
		if not hit then
			continue
		end
		if entry.kind == "Attach" then
			local from = open[entry.joint]
			if from ~= nil then
				table.insert(spans, { from, entry.t })
				open[entry.joint] = nil
			end
		elseif open[entry.joint] == nil then
			open[entry.joint] = entry.t
		end
	end
	for _, from in open do
		table.insert(spans, { from, math.huge })
	end
	return spans
end

type Want = { name: string, grip: Grip, joint: string, via: boolean }

local function pullSolver(count: number): IkFk.Solver
	if count == 1 then
		return "Aim"
	elseif count == 3 then
		return "TwoBone"
	end
	return "FABRIK"
end

local function prepare(doc: Document, rig: Rig): Prepared
	local joints = rig.joints
	local jointSlots = sortedKeys(joints)
	local slotOf: { [string]: number } = {}
	for index, address in jointSlots do
		slotOf[address] = index
	end
	local hierarchy = hierarchyOf(rig, jointSlots)
	local restPivots, restWorlds = restOf(rig, hierarchy)

	local controlRig = rig.controlRig
	local controls: { [string]: ControlPlan } = {}
	local controlSlots: { string } = {}
	if controlRig ~= nil then
		for _, name in sortedKeys(controlRig.controls) do
			local control = controlRig.controls[name]
			local restWorld = restOfControl(control, restPivots, rig.root)
			local parent = control.parent
			if restWorld == nil or (parent ~= nil and joints[parent] == nil) then
				continue
			end
			table.insert(controlSlots, name)
			local parentRest = if parent ~= nil then restWorlds[parent] else rig.root
			local node: Node = { kind = "Control", name = name }
			local plan: ControlPlan = {
				name = name,
				parent = parent,
				restLocal = parentRest:Inverse() * restWorld,
				slot = #jointSlots + #controlSlots,
				node = node,
			}
			node.control = plan
			controls[name] = plan
		end
	end

	local notes: { string } = {}
	local gripsDoc = doc.grips
	local wants: { Want } = {}
	local pulled: { [string]: boolean } = {}
	local counts = if gripsDoc ~= nil then childCounts(rig) else {}
	if gripsDoc ~= nil then
		local ownChain: { [string]: string } = {}
		if controlRig ~= nil then
			for _, name in sortedKeys(controlRig.chains) do
				for _, address in controlRig.chains[name].joints do
					ownChain[address] = ownChain[address] or name
				end
			end
		end
		for _, name in sortedKeys(gripsDoc) do
			local grip = gripsDoc[name]
			local target = grip.target
			local space = grip.space
			if joints[target] == nil then
				table.insert(
					notes,
					`The grip '{name}' holds '{target}', which this rig does not have, so it holds nothing.`
				)
				continue
			end
			if space.kind == "Joint" and (space.joint == nil or joints[space.joint] == nil) then
				table.insert(
					notes,
					`The grip '{name}' rides on '{space.joint or "?"}', which this rig does not have, so it holds nothing.`
				)
				continue
			end
			if space.kind == "Parent" or space.slot ~= nil then
				table.insert(
					notes,
					`The grip '{name}' rides on no joint of this rig, the rig root or World, so it holds nothing.`
				)
				continue
			end
			local joint, via = target, false
			if ownChain[target] == nil then
				local parent = joints[target].parent
				if parent == nil or joints[parent] == nil then
					table.insert(
						notes,
						`The grip '{name}' holds '{target}', which hangs from no joint, so nothing can bend to take it there.`
					)
					continue
				end
				if ownChain[parent] ~= nil or (counts[parent] or 0) == 1 then
					joint, via = parent, true
				end
			end
			table.insert(wants, { name = name, grip = grip, joint = joint, via = via })
			local chainName = ownChain[joint]
			if chainName ~= nil then
				pulled[chainName] = true
			end
		end
	end

	local chains: { ChainPlan } = {}
	local chainOf: { [string]: ChainPlan } = {}
	local ikBlend = doc.ikBlend
	local ikPlant = doc.ikPlant
	if controlRig ~= nil and (ikBlend ~= nil or ikPlant ~= nil or next(pulled) ~= nil) then
		for _, name in sortedKeys(controlRig.chains) do
			local chain = controlRig.chains[name]
			local plant: string? = nil
			if ikPlant ~= nil and ikPlant[name] ~= nil then
				local wanted = chain.plant
				if wanted ~= nil and controls[wanted] ~= nil then
					plant = wanted
				elseif wanted ~= nil then
					table.insert(
						notes,
						`The IK chain '{name}' is planted on '{wanted}', which this rig cannot place, so it is not planted.`
					)
				else
					table.insert(
						notes,
						`The IK chain '{name}' is planted in this animation, but it has no plant on this rig, so it is not planted. Add one in Rig Setup.`
					)
				end
			end
			if (ikBlend == nil or ikBlend[name] == nil) and plant == nil and not pulled[name] then
				continue
			end
			local problem = chainProblem(name, chain, rig, controls, chainOf)
			if problem ~= nil then
				table.insert(notes, problem)
				continue
			end
			local links: { TwoBone.Link } = {}
			for index, address in chain.joints do
				local joint = joints[address]
				links[index] = {
					parentOffset = joint.parentOffset,
					childOffset = joint.childOffset,
					limit = if chain.limits ~= nil then chain.limits[address] else nil,
					stiffness = if chain.stiffness ~= nil then chain.stiffness[address] else nil,
				}
			end
			local pole = chain.pole
			local node: Node = { kind = "Chain", name = name }
			local tip = tipOf(chain, rig, restPivots)
			local base = settingsOf(chain, rig, tip, restPivots)
			local sole = if plant ~= nil
				then soleOf(chain, controlRig.controls[plant], rig, restPivots) :: Vector3
				else Vector3.zero
			local plan: ChainPlan = {
				name = name,
				links = table.clone(chain.joints),
				solver = chain.solver,
				target = chain.target,
				pole = if pole ~= nil and controls[pole] ~= nil then pole else nil,
				moves = movesOf(chain, doc, name),
				shape = { parentWorld = IDENTITY, links = links },
				settings = table.clone(base),
				base = base,
				tip = tipRestOf(chain, rig, tip),
				keyed = ChainKeys.keyed(doc, name),
				plant = plant,
				sole = sole,
				fk = table.create(#links, IDENTITY),
				node = node,
			}
			node.chain = plan
			table.insert(chains, plan)
			for _, address in plan.links do
				chainOf[address] = plan
			end
		end
	end

	local gripPlans: { [string]: GripPlan } = {}
	for _, want in wants do
		local plan = chainOf[want.joint]
		if plan == nil then
			local links = { want.joint }
			local current = want.joint
			while true do
				local parent = joints[current].parent
				if
					parent == nil
					or joints[parent] == nil
					or (counts[parent] or 0) ~= 1
					or chainOf[parent] ~= nil
				then
					break
				end
				table.insert(links, 1, parent)
				current = parent
			end
			local shapeLinks: { TwoBone.Link } = {}
			for index, address in links do
				local joint = joints[address]
				shapeLinks[index] =
					{ parentOffset = joint.parentOffset, childOffset = joint.childOffset }
			end
			local node: Node = { kind = "Chain", name = want.name }
			local made: ChainPlan = {
				name = want.name,
				links = links,
				solver = pullSolver(#links),
				target = "",
				moves = {},
				shape = { parentWorld = IDENTITY, links = shapeLinks },
				settings = {},
				base = {},
				keyed = false,
				sole = Vector3.zero,
				fk = table.create(#links, IDENTITY),
				synthetic = true,
				node = node,
			}
			node.chain = made
			table.insert(chains, made)
			for _, address in links do
				chainOf[address] = made
			end
			plan = made
		end
		local chainPlan = plan :: ChainPlan
		local count = table.find(chainPlan.links, want.joint) :: number
		local whole = count == #chainPlan.links and chainPlan.synthetic ~= true
		local shape = chainPlan.shape
		if not whole then
			shape = {
				parentWorld = IDENTITY,
				links = table.move(chainPlan.shape.links, 1, count, 1, table.create(count)),
			}
		end
		local hold = want.grip.hold
		local node: Node = { kind = "Grip", name = want.name }
		local gripPlan: GripPlan = {
			name = want.name,
			target = want.grip.target,
			space = want.grip.space,
			hold = if hold ~= nil then CFrame.new(hold[1], hold[2], hold[3]) else IDENTITY,
			joint = want.joint,
			via = want.via,
			chain = chainPlan,
			count = count,
			shape = shape,
			solver = if whole then chainPlan.solver else pullSolver(count),
			settings = {},
			loose = looseOf(doc, rig, want.grip),
			drags = want.grip.reach ~= "Stop",
			slot = 0,
			node = node,
		}
		if gripPlan.drags then
			chainPlan.moves[chainPlan.links[1]] = true
		end
		node.grip = gripPlan
		gripPlans[want.name] = gripPlan
		local pulls = chainPlan.pulls or {}
		chainPlan.pulls = pulls
		table.insert(pulls, gripPlan)
	end

	local placerOf: { [string]: Node } = {}
	local nodes: { Node } = {}
	for _, address in jointSlots do
		local plan = chainOf[address]
		if plan ~= nil then
			placerOf[address] = plan.node
		else
			local node: Node = { kind = "Joint", name = address }
			placerOf[address] = node
			table.insert(nodes, node)
		end
	end
	for _, name in controlSlots do
		table.insert(nodes, controls[name].node)
	end
	for _, plan in chains do
		table.insert(nodes, plan.node)
	end
	local pulls: { GripPlan } = {}
	for index, name in sortedKeys(gripPlans) do
		local plan = gripPlans[name]
		plan.slot = index
		pulls[index] = plan
		table.insert(nodes, plan.node)
	end

	local spaced: { [string]: boolean } = {}
	local affected: { string } = {}
	for _, address in SpaceSolve.spaced(rig :: any, doc :: any) do
		spaced[address] = true
	end
	for _, address in jointSlots do
		if spaced[address] or chainOf[address] ~= nil then
			table.insert(affected, address)
		end
	end

	return {
		doc = doc,
		revision = doc.revision or 0,
		jointsTable = doc.joints,
		controlsTable = doc.controls,
		ikBlendTable = doc.ikBlend,
		ikPlantTable = doc.ikPlant,
		startingTable = doc.startingSpaces,
		layersTable = doc.layers,
		active = #affected > 0,
		affected = affected,
		spaced = spaced,
		jointSlots = jointSlots,
		controlSlots = controlSlots,
		slotOf = slotOf,
		controls = controls,
		chains = chains,
		chainOf = chainOf,
		gripsTable = doc.grips,
		grips = gripPlans,
		pulls = pulls,
		holding = table.create(#pulls, true),
		placerOf = placerOf,
		nodes = nodes,
		hierarchy = hierarchy,
		note = notes[1],
		targets = table.create(#jointSlots + #controlSlots, PARENT),
		froms = {},
		sinces = table.create(#jointSlots + #controlSlots, 0),
		blends = table.create(#jointSlots + #controlSlots, 1),
		orders = {},
		last = nil,
		deferred = {},
		solved = newSolved(),
	}
end

local cache: { [Rig]: Prepared } = setmetatable({}, { __mode = "k" }) :: any

local function preparedFor(doc: Document, rig: Rig): Prepared
	local p = cache[rig]
	if
		p ~= nil
		and p.doc == doc
		and p.revision == (doc.revision or 0)
		and p.jointsTable == doc.joints
		and p.controlsTable == doc.controls
		and p.ikBlendTable == doc.ikBlend
		and p.ikPlantTable == doc.ikPlant
		and p.startingTable == doc.startingSpaces
		and p.layersTable == doc.layers
		and p.gripsTable == doc.grips
	then
		return p
	end
	local fresh = prepare(doc, rig)
	cache[rig] = fresh
	return fresh
end

function RigSolve.invalidate(rig: Rig?)
	if rig ~= nil then
		cache[rig] = nil
	else
		table.clear(cache)
	end
end

function RigSolve.rigged(doc: Document, rig: Rig): boolean
	return preparedFor(doc, rig).active
end

local function strengthOf(doc: Document, pull: GripPlan, t: number, options: Options): number
	for _, span in pull.loose do
		if t >= span[1] - SAME and t < span[2] - SAME then
			return 0
		end
	end
	local channels = doc.gripStrength
	return IkFk.weight(if channels ~= nil then channels[pull.name] else nil, t, options :: any)
end

local function statesAt(p: Prepared, doc: Document, t: number, options: Options?)
	local targets, froms, sinces, blends = p.targets, p.froms, p.sinces, p.blends
	local tracks = doc.joints
	local starting = doc.startingSpaces
	for index, address in p.jointSlots do
		local track = tracks[address]
		local target, from, since, weight = stateOf(
			if track ~= nil then track.spaces else nil,
			if starting ~= nil then starting[address] else nil,
			t
		)
		targets[index], froms[index], sinces[index], blends[index] = target, from, since, weight
	end
	local controls = doc.controls
	local offset = #p.jointSlots
	for index, name in p.controlSlots do
		local track = if controls ~= nil then controls[name] else nil
		local target, from, since, weight =
			stateOf(if track ~= nil then track.spaces else nil, nil, t)
		local slot = offset + index
		targets[slot], froms[slot], sinces[slot], blends[slot] = target, from, since, weight
	end
	local holding = p.holding
	for index, pull in p.pulls do
		holding[index] = strengthOf(doc, pull, t, options or NO_OPTIONS) > 0
	end
end

local function describe(node: Node): string
	if node.kind == "Joint" then
		return `'{node.name}'`
	elseif node.kind == "Control" then
		return `the control '{node.name}'`
	elseif node.kind == "Grip" then
		return `the grip '{node.name}'`
	end
	local chain = node.chain
	if chain ~= nil and chain.synthetic then
		return `the limb the grip '{node.name}' bends`
	end
	return `the IK chain '{node.name}'`
end

local function describeCycle(path: { Node }, hows: { string }): string
	if #path == 1 then
		return `{describe(path[1])} {hows[1]} itself, so it has nothing to be placed from. Put it in another space.`
	end
	local phrases: { string } = {}
	for index, node in path do
		local following = path[index % #path + 1]
		table.insert(phrases, `{describe(node)} {hows[index]} {describe(following)}`)
	end
	local list = table.concat(phrases, ", ", 1, #phrases - 1) .. " and " .. phrases[#phrases]
	local who = if #path == 2 then "neither can" else "none of them can"
	for _, node in path do
		if node.kind == "Grip" then
			return `{list}, so {who} be placed first. Have the grip '{node.name}' hold onto something it does not move, or let go of it by then.`
		end
	end
	return `{list}, so {who} be placed first. Put one of them in another space.`
end

local function edgesOf(p: Prepared, rig: Rig, node: Node): ({ Edge }, string?)
	local edges: { Edge } = {}
	local function after(address: string, how: string)
		local placer = p.placerOf[address]
		if placer == nil then
			return
		end
		table.insert(edges, {
			node = placer,
			how = if placer.kind == "Chain" then `{how} '{address}' of` else how,
		})
	end
	local function follows(owner: string, target: SpaceTarget?, how: string): string?
		if target == nil or target.kind ~= "Joint" or target.slot ~= nil then
			return nil
		end
		local followed = target.joint
		if followed == nil or rig.joints[followed] == nil then
			return `{owner} follows '{followed or "?"}', which this rig does not have.`
		end
		after(followed, how)
		return nil
	end
	local targets, froms = p.targets, p.froms

	local control = node.control
	local chain = node.chain
	local grip = node.grip
	if grip ~= nil then
		local space = grip.space
		if space.kind == "Joint" and space.joint ~= nil then
			after(space.joint, "rides on")
		end
	elseif control ~= nil then
		local owner = describe(node)
		for _, target in { targets[control.slot], froms[control.slot] } do
			if target.kind == "Parent" and control.parent ~= nil then
				after(control.parent, "hangs from")
			end
			local problem = follows(owner, target, "follows")
			if problem ~= nil then
				return edges, problem
			end
		end
	elseif chain ~= nil then
		local first = rig.joints[chain.links[1]]
		if first.parent ~= nil then
			after(first.parent, "hangs from")
		end
		for _, address in chain.links do
			local slot = p.slotOf[address]
			local how = `places '{address}' in the space of`
			local problem = follows(`'{address}'`, targets[slot], how)
				or follows(`'{address}'`, froms[slot], how)
			if problem ~= nil then
				return edges, problem
			end
		end
		if not chain.synthetic then
			table.insert(edges, { node = p.controls[chain.target].node, how = "reaches for" })
		end
		if chain.pole ~= nil then
			table.insert(edges, { node = p.controls[chain.pole].node, how = "bends toward" })
		end
		if chain.plant ~= nil then
			table.insert(edges, { node = p.controls[chain.plant].node, how = "is planted on" })
		end
		for _, pull in chain.pulls or {} do
			if p.holding[pull.slot] then
				table.insert(edges, { node = pull.node, how = "is pulled onto" })
			end
		end
	else
		local address = node.name
		local parent = rig.joints[address].parent
		local slot = p.slotOf[address]
		local target, from = targets[slot], froms[slot]
		if
			parent ~= nil
			and (target.kind == "Parent" or (from ~= nil and from.kind == "Parent"))
		then
			after(parent, "hangs from")
		end
		local owner = `'{address}'`
		local problem = follows(owner, target, "follows") or follows(owner, from, "follows")
		if problem ~= nil then
			return edges, problem
		end
	end
	return edges, nil
end

local function computeOrder(p: Prepared, rig: Rig): Order
	local order: Order = {
		targets = table.clone(p.targets),
		froms = table.clone(p.froms),
		holding = table.clone(p.holding),
		nodes = nil,
		problem = nil,
	}
	local ordered: { Node } = {}
	local mark: { [Node]: number } = {}
	local path: { Node } = {}
	local hows: { string } = {}

	local function visit(node: Node): string?
		mark[node] = 1
		table.insert(path, node)
		local edges, problem = edgesOf(p, rig, node)
		if problem ~= nil then
			return problem
		end
		for _, edge in edges do
			local seen = mark[edge.node]
			hows[#path] = edge.how
			if seen == 1 then
				local from = table.find(path, edge.node) :: number
				local cycle = table.move(path, from, #path, 1, {})
				local words = table.move(hows, from, #path, 1, {})
				return describeCycle(cycle, words)
			elseif seen == nil then
				local inner = visit(edge.node)
				if inner ~= nil then
					return inner
				end
			end
		end
		table.remove(path)
		hows[#path + 1] = nil
		mark[node] = 2
		table.insert(ordered, node)
		return nil
	end

	for _, node in p.nodes do
		if mark[node] == nil then
			local problem = visit(node)
			if problem ~= nil then
				order.problem = problem
				return order
			end
		end
	end
	order.nodes = ordered
	return order
end

local function matches(order: Order, p: Prepared): boolean
	local targets, froms = p.targets, p.froms
	local orderTargets, orderFroms = order.targets, order.froms
	for slot = 1, #targets do
		if orderTargets[slot] ~= targets[slot] or orderFroms[slot] ~= froms[slot] then
			return false
		end
	end
	local holding, orderHolding = p.holding, order.holding
	for index = 1, #holding do
		if orderHolding[index] ~= holding[index] then
			return false
		end
	end
	return true
end

local function orderOf(p: Prepared, rig: Rig): Order
	local last = p.last
	if last ~= nil and matches(last, p) then
		return last
	end
	for _, order in p.orders do
		if matches(order, p) then
			p.last = order
			return order
		end
	end
	if #p.orders >= MOST_ORDERS then
		table.clear(p.orders)
	end
	local order = computeOrder(p, rig)
	table.insert(p.orders, order)
	p.last = order
	return order
end

local function frameOf(
	rig: Rig,
	target: SpaceTarget,
	restFrame: CFrame,
	worlds: { [string]: CFrame },
	name: string,
	isControl: boolean,
	t: number
): (CFrame?, string?)
	local kind = target.kind
	if kind == "Parent" then
		return restFrame, nil
	elseif kind == "World" then
		return rig.world or IDENTITY, nil
	end
	local who = if isControl then `the control '{name}'` else `'{name}'`
	if target.slot ~= nil then
		local placed = if rig.elsewhere then rig.elsewhere(target, t) else nil
		if placed == nil then
			return nil,
				`{who} follows the rig in slot '{target.slot}', which only its scene can place.`
		end
		return placed, nil
	end
	if kind == "RigRoot" then
		return rig.root, nil
	end
	local followed = target.joint
	local world = if followed then worlds[followed] else nil
	if world == nil then
		return nil, `{who} follows '{followed or "?"}', which this rig does not have.`
	end
	return world, nil
end

local function pivotIn(
	rig: Rig,
	worlds: { [string]: CFrame },
	restFrame: CFrame,
	value: CFrame,
	target: SpaceTarget,
	from: SpaceTarget?,
	weight: number,
	held: CFrame,
	name: string,
	isControl: boolean,
	t: number
): (CFrame?, string?)
	local frame, missing = frameOf(rig, target, restFrame, worlds, name, isControl, t)
	if frame == nil then
		return nil, missing
	end
	local pivot = frame * value
	if from ~= nil then
		local fromFrame, lost = frameOf(rig, from, restFrame, worlds, name, isControl, t)
		if fromFrame == nil then
			return nil, lost
		end
		pivot = (fromFrame * held):Lerp(pivot, weight)
	end
	return pivot, nil
end

local function placeJoint(
	p: Prepared,
	doc: Document,
	rig: Rig,
	address: string,
	t: number,
	options: Options
): string?
	local solved = p.solved
	local worlds = solved.worlds
	local joint = rig.joints[address]
	local parent = joint.parent
	local parentWorld = (if parent ~= nil then worlds[parent] else nil)
		or joint.parentWorld
		or rig.root
	local restPivot = parentWorld * joint.parentOffset
	local slot = p.slotOf[address]
	local target, from = p.targets[slot], p.froms[slot]
	local value = fkValue(doc, address, t, options)

	local transform: CFrame
	local pivot: CFrame
	if target.kind == "Parent" and from == nil then
		transform = value
		pivot = restPivot * value
	else
		local held = if from ~= nil
			then fkValue(doc, address, p.sinces[slot] - BEFORE, options)
			else IDENTITY
		local found, problem = pivotIn(
			rig,
			worlds,
			restPivot,
			value,
			target,
			from,
			p.blends[slot],
			held,
			address,
			false,
			t
		)
		if found == nil then
			return problem
		end
		pivot = found
		transform = restPivot:Inverse() * pivot
		if target.kind ~= "Parent" and (from == nil or from.kind ~= "Parent") then
			table.insert(p.deferred, address)
		end
	end
	solved.transforms[address] = transform
	solved.pivots[address] = pivot
	worlds[address] = pivot * joint.childOffset:Inverse()
	return nil
end

local function placeControl(
	p: Prepared,
	doc: Document,
	rig: Rig,
	plan: ControlPlan,
	t: number,
	options: Options
): string?
	local solved = p.solved
	local worlds = solved.worlds
	local slot = plan.slot
	local target, from = p.targets[slot], p.froms[slot]
	local controls = doc.controls
	local track = if controls ~= nil then controls[plan.name] else nil
	local value = if track ~= nil then Pose.evaluate(track, t, options :: any) else IDENTITY

	local restFrame = IDENTITY
	if target.kind == "Parent" or (from ~= nil and from.kind == "Parent") then
		local parent = plan.parent
		restFrame = ((if parent ~= nil then worlds[parent] else nil) or rig.root) * plan.restLocal
	end

	if target.kind == "Parent" and from == nil then
		solved.controls[plan.name] = restFrame * value
		return nil
	end
	local held = if from ~= nil and track ~= nil
		then Pose.evaluate(track, p.sinces[slot] - BEFORE, options :: any)
		else IDENTITY
	local world, problem = pivotIn(
		rig,
		worlds,
		restFrame,
		value,
		target,
		from,
		p.blends[slot],
		held,
		plan.name,
		true,
		t
	)
	if world == nil then
		return problem
	end
	solved.controls[plan.name] = world
	return nil
end

local function gripFrameOf(rig: Rig, worlds: { [string]: CFrame }, space: SpaceTarget): CFrame?
	if space.slot ~= nil then
		return nil
	elseif space.kind == "Joint" then
		return if space.joint ~= nil then worlds[space.joint] else nil
	elseif space.kind == "RigRoot" then
		return rig.root
	elseif space.kind == "World" then
		return rig.world or IDENTITY
	end
	return nil
end

function RigSolve.inBox(value: CFrame, box: { number }?): CFrame
	if box == nil then
		return value
	end
	local x, y, z = value.X, value.Y, value.Z
	local hx, hy, hz = box[1] / 2, box[2] / 2, box[3] / 2
	local cx, cy, cz = math.clamp(x, -hx, hx), math.clamp(y, -hy, hy), math.clamp(z, -hz, hz)
	if cx == x and cy == y and cz == z then
		return value
	end
	return value.Rotation + Vector3.new(cx, cy, cz)
end

local function placeGrip(
	p: Prepared,
	doc: Document,
	rig: Rig,
	plan: GripPlan,
	t: number,
	options: Options
): string?
	local solved = p.solved
	local frame = gripFrameOf(rig, solved.worlds, plan.space)
	if frame == nil then
		return `the grip '{plan.name}' rides on '{plan.space.joint or "?"}', which this rig does not have.`
	end
	local grips = doc.grips
	local grip = if grips ~= nil then grips[plan.name] else nil
	local value = if grip ~= nil
		then RigSolve.inBox(Pose.evaluate(grip :: any, t, options :: any), grip.box)
		else IDENTITY
	solved.grips[plan.name] = frame * value
	return nil
end

local function shareOf(
	channels: { [string]: Modifiers.Channel }?,
	name: string,
	t: number,
	options: Options
): number
	local channel = if channels ~= nil then channels[name] else nil
	if channel == nil then
		return 1
	end
	return IkFk.weight(channel, t, options :: any)
end

local REACH = 1e-4

local function dragged(
	joints: { [string]: SpaceSolve.RigJoint },
	links: { string },
	count: number,
	parentWorld: CFrame,
	bent: { CFrame },
	held: CFrame,
	goal: Vector3
): { CFrame }
	local above = parentWorld
	local pivot = parentWorld
	for index = 1, count do
		local joint = joints[links[index]]
		pivot = above * joint.parentOffset * bent[index]
		above = pivot * joint.childOffset:Inverse()
	end
	local short = goal - (pivot * held).Position
	if short.Magnitude <= REACH then
		return bent
	end
	local out = table.clone(bent)
	local frame = parentWorld * joints[links[1]].parentOffset
	out[1] = CFrame.new(frame:VectorToObjectSpace(short)) * bent[1]
	return out
end

local function pullOn(
	p: Prepared,
	doc: Document,
	rig: Rig,
	plan: ChainPlan,
	pull: GripPlan,
	parentWorld: CFrame,
	transforms: { CFrame },
	t: number,
	options: Options
): { CFrame }
	local solved = p.solved
	local strength = strengthOf(doc, pull, t, options)
	solved.strengths[pull.name] = strength
	local grip = solved.grips[pull.name]
	if strength <= 0 or grip == nil then
		return transforms
	end
	local joints = rig.joints
	local links = plan.links
	local count = pull.count

	local above = parentWorld
	local pivot = parentWorld
	local first = parentWorld
	for index = 1, count do
		local joint = joints[links[index]]
		pivot = above * joint.parentOffset * transforms[index]
		above = pivot * joint.childOffset:Inverse()
		if index == 1 then
			first = pivot
		end
	end
	local held: CFrame
	local turned = joints[pull.joint]
	if pull.via then
		local slot = p.slotOf[pull.target]
		if p.targets[slot].kind ~= "Parent" or p.froms[slot] ~= nil then
			solved.strengths[pull.name] = 0
			return transforms
		end
		local target = joints[pull.target]
		held = turned.childOffset:Inverse()
			* target.parentOffset
			* fkValue(doc, pull.target, t, options)
			* target.childOffset:Inverse()
			* pull.hold
	else
		held = turned.childOffset:Inverse() * pull.hold
	end
	local now = pivot * held
	local turn = strength * shareOf(doc.gripTurn, pull.name, t, options)
	local move = strength * shareOf(doc.gripMove, pull.name, t, options)
	local goal = CFrame.new(now.Position:Lerp(grip.Position, move))
		* now.Rotation:Lerp(grip.Rotation, turn)

	local settings = pull.settings
	local whole = pull.shape == plan.shape
	local base = if whole then plan.settings else nil
	settings.stretch = if base ~= nil then base.stretch else nil
	settings.softness = if base ~= nil then base.softness else nil
	settings.iterations = if base ~= nil then base.iterations else nil
	settings.tolerance = if base ~= nil then base.tolerance else nil
	settings.share = if base ~= nil then base.share else nil
	settings.slideIn = if base ~= nil then base.slideIn else nil
	settings.length = if base ~= nil then base.length else nil
	settings.lean = if base ~= nil then base.lean else nil
	settings.hinge = if base ~= nil then base.hinge else nil
	settings.orientTip = true
	local pole = if plan.pole ~= nil then solved.controls[plan.pole] else nil
	local aimsWhole = base ~= nil and pull.solver == "Aim" and pole ~= nil
	settings.pole = if aimsWhole and pole ~= nil then pole.Position else nil
	settings.poleAngle = if aimsWhole and base ~= nil then base.poleAngle else nil
	settings.bend = nil
	if pole ~= nil then
		local toPole = first:VectorToObjectSpace(pole.Position - first.Position)
		settings.bend = if toPole.Magnitude > 1e-6 then toPole.Unit else nil
	end
	local aimed: CFrame
	if pull.solver == "Aim" then
		settings.tip = held
		aimed = goal
	else
		settings.tip = nil
		aimed = goal * held:Inverse()
	end

	local shape = pull.shape
	shape.parentWorld = parentWorld
	local from = transforms
	if count < #transforms then
		from = table.move(transforms, 1, count, 1, table.create(count))
	end
	local bent = IkFk.evaluate(shape, pull.solver, from, aimed, 1, settings)
	if pull.drags then
		bent = dragged(joints, links, count, parentWorld, bent, held, goal.Position)
	end
	if count == #transforms then
		return bent
	end
	local out = table.clone(transforms)
	table.move(bent, 1, count, 1, out)
	return out
end

local GROUND = 1e-4

local function endPivot(
	joints: { [string]: SpaceSolve.RigJoint },
	links: { string },
	parentWorld: CFrame,
	transforms: { CFrame }
): CFrame
	local above = parentWorld
	local pivot = parentWorld
	for index, address in links do
		local joint = joints[address]
		pivot = above * joint.parentOffset * transforms[index]
		above = pivot * joint.childOffset:Inverse()
	end
	return pivot
end

local function placeChain(
	p: Prepared,
	doc: Document,
	rig: Rig,
	plan: ChainPlan,
	t: number,
	options: Options
): string?
	local solved = p.solved
	local worlds = solved.worlds
	local joints = rig.joints
	local links = plan.links
	local first = joints[links[1]]
	local parent = first.parent
	local parentWorld = (if parent ~= nil then worlds[parent] else nil)
		or first.parentWorld
		or rig.root

	local fk = plan.fk
	local above = parentWorld
	for index, address in links do
		local joint = joints[address]
		local restPivot = above * joint.parentOffset
		local slot = p.slotOf[address]
		local target, from = p.targets[slot], p.froms[slot]
		local value = fkValue(doc, address, t, options)
		local pivot: CFrame
		if target.kind == "Parent" and from == nil then
			fk[index] = value
			pivot = restPivot * value
		else
			local held = if from ~= nil
				then fkValue(doc, address, p.sinces[slot] - BEFORE, options)
				else IDENTITY
			local found, problem = pivotIn(
				rig,
				worlds,
				restPivot,
				value,
				target,
				from,
				p.blends[slot],
				held,
				address,
				false,
				t
			)
			if found == nil then
				return problem
			end
			pivot = found
			fk[index] = restPivot:Inverse() * pivot
		end
		above = pivot * joint.childOffset:Inverse()
	end

	local w = 0
	if not plan.synthetic then
		local blend = doc.ikBlend
		w = IkFk.weight(if blend ~= nil then blend[plan.name] else nil, t, options :: any)
		solved.weights[plan.name] = w
	end
	local turn, move = w, w
	if plan.keyed and w > 0 then
		turn = w * (ChainKeys.valueAt(doc, plan.name, "ikTurn", t, options :: any) or 1)
		move = w * (ChainKeys.valueAt(doc, plan.name, "ikMove", t, options :: any) or 1)
	end
	local plant = plan.plant
	local planted = 0
	if plant ~= nil then
		local plants = doc.ikPlant
		planted = IkFk.weight(if plants ~= nil then plants[plan.name] else nil, t, options :: any)
		solved.plants[plan.name] = planted
	end

	local transforms = fk
	local pulls = plan.pulls
	if turn > 0 or move > 0 or planted > 0 or pulls ~= nil then
		local shape = plan.shape
		shape.parentWorld = parentWorld
		local settings = plan.settings
		if plan.keyed then
			keyedSettings(settings, plan.base, plan.name, plan.solver, plan.tip, doc, t, options)
		end
		settings.pole = if plan.pole ~= nil then solved.controls[plan.pole].Position else nil
		if turn > 0 or move > 0 then
			transforms = IkFk.evaluate(
				shape,
				plan.solver,
				fk,
				solved.controls[plan.target],
				turn,
				settings,
				move
			)
		end
		if planted > 0 then
			local last = endPivot(joints, links, parentWorld, transforms)
			local ground = solved.controls[plant :: string]
			local up = ground.UpVector
			local height = (last * plan.sole - ground.Position):Dot(up)
			if height < -GROUND then
				transforms = IkFk.evaluate(
					shape,
					plan.solver,
					transforms,
					last * (settings.tip or IDENTITY) + up * -height,
					planted,
					settings
				)
			end
		end
		if pulls ~= nil then
			for _, pull in pulls do
				transforms = pullOn(p, doc, rig, plan, pull, parentWorld, transforms, t, options)
			end
		end
	end

	above = parentWorld
	for index, address in links do
		local joint = joints[address]
		local transform = transforms[index]
		local pivot = above * joint.parentOffset * transform
		above = pivot * joint.childOffset:Inverse()
		solved.transforms[address] = transform
		solved.pivots[address] = pivot
		worlds[address] = above
	end
	return nil
end

local function placePlain(p: Prepared, doc: Document, rig: Rig, t: number, options: Options)
	local solved = p.solved
	local worlds = solved.worlds
	for _, address in p.hierarchy do
		local joint = rig.joints[address]
		local parent = joint.parent
		local parentWorld = (if parent ~= nil then worlds[parent] else nil)
			or joint.parentWorld
			or rig.root
		local value = fkValue(doc, address, t, options)
		local pivot = parentWorld * joint.parentOffset * value
		solved.transforms[address] = value
		solved.pivots[address] = pivot
		worlds[address] = pivot * joint.childOffset:Inverse()
	end
	local controls = doc.controls
	for name, plan in p.controls do
		local track = if controls ~= nil then controls[name] else nil
		local value = if track ~= nil then Pose.evaluate(track, t, options :: any) else IDENTITY
		local parent = plan.parent
		solved.controls[name] = ((if parent ~= nil then worlds[parent] else nil) or rig.root)
			* plan.restLocal
			* value
	end
	for _, plan in p.chains do
		if not plan.synthetic then
			solved.weights[plan.name] = 0
		end
		if plan.plant ~= nil then
			solved.plants[plan.name] = 0
		end
	end
	for _, plan in p.grips do
		placeGrip(p, doc, rig, plan, t, options)
		solved.strengths[plan.name] = 0
	end
end

local function readsOf(p: Prepared, rig: Rig, order: Order): { [Node]: boolean }?
	local found = order.reads
	if found == nil then
		local slotted = false
		for slot, target in order.targets do
			local from = order.froms[slot]
			if target.slot ~= nil or (from ~= nil and from.slot ~= nil) then
				slotted = true
				break
			end
		end
		if slotted then
			found = false
		else
			local reads: { [Node]: boolean } = {}
			local function visit(node: Node)
				if reads[node] then
					return
				end
				reads[node] = true
				for _, edge in (edgesOf(p, rig, node)) do
					visit(edge.node)
				end
			end
			for _, address in p.affected do
				visit(p.placerOf[address])
				local parent = rig.joints[address].parent
				local above = if parent ~= nil then p.placerOf[parent] else nil
				if above ~= nil then
					visit(above)
				end
			end
			found = reads
		end
		order.reads = found
	end
	return if found then found else nil
end

local function settle(p: Prepared, rig: Rig)
	local solved = p.solved
	local worlds = solved.worlds
	for _, address in p.deferred do
		local joint = rig.joints[address]
		local parent = joint.parent
		local parentWorld = (if parent ~= nil then worlds[parent] else nil)
			or joint.parentWorld
			or rig.root
		solved.transforms[address] = (parentWorld * joint.parentOffset):Inverse()
			* solved.pivots[address]
	end
end

local function solveWith(
	p: Prepared,
	doc: Document,
	rig: Rig,
	t: number,
	options: Options,
	affectedOnly: boolean?
): (Solved, string?)
	statesAt(p, doc, t, options)
	table.clear(p.deferred)
	local order = orderOf(p, rig)
	local nodes = order.nodes
	local problem: string? = nil
	if nodes == nil then
		problem = `At {seconds(t)}, {order.problem}`
	else
		local reads = if affectedOnly then readsOf(p, rig, order) else nil
		for _, node in nodes do
			if reads ~= nil and not reads[node] then
				continue
			end
			local control, chain, grip = node.control, node.chain, node.grip
			if control ~= nil then
				problem = placeControl(p, doc, rig, control, t, options)
			elseif grip ~= nil then
				problem = placeGrip(p, doc, rig, grip, t, options)
			elseif chain ~= nil then
				problem = placeChain(p, doc, rig, chain, t, options)
			else
				problem = placeJoint(p, doc, rig, node.name, t, options)
			end
			if problem ~= nil then
				break
			end
		end
	end
	if problem ~= nil then
		placePlain(p, doc, rig, t, options)
	else
		settle(p, rig)
	end
	return p.solved, problem
end

function RigSolve.solve(doc: Document, t: number, rig: Rig, options: Options?): (Solved, string?)
	return solveWith(preparedFor(doc, rig), doc, rig, t, optionsFor(doc, options))
end

function RigSolve.sample(
	doc: Document,
	t: number,
	rig: Rig,
	options: Options?,
	into: Sample?
): (Sample, string?)
	local out: Sample = into or {}
	table.clear(out)
	local p = preparedFor(doc, rig)
	local resolved = optionsFor(doc, options)
	local solved, problem = solveWith(p, doc, rig, t, resolved)
	local transforms = solved.transforms
	for address in doc.joints do
		out[address] = transforms[address] or fkValue(doc, address, t, resolved)
	end
	local layers = doc.layers
	if layers ~= nil and #layers > 0 then
		local soloing = LayerEval.soloing(doc :: any, resolved)
		for _, layer in layers do
			if LayerEval.plays(layer, soloing) then
				for address in layer.joints do
					if out[address] == nil then
						out[address] = transforms[address] or fkValue(doc, address, t, resolved)
					end
				end
			end
		end
	end
	for _, address in p.affected do
		out[address] = transforms[address]
	end
	return out, problem
end

function RigSolve.pose(
	doc: Document,
	address: string,
	t: number,
	rig: Rig,
	options: Options?
): CFrame
	local p = preparedFor(doc, rig)
	local resolved = optionsFor(doc, options)
	if not p.active or rig.joints[address] == nil then
		return fkValue(doc, address, t, resolved)
	end
	local solved = solveWith(p, doc, rig, t, resolved)
	return solved.transforms[address]
end

function RigSolve.value(
	doc: Document,
	address: string,
	t: number,
	rig: Rig,
	options: Options?
): CFrame
	local p = preparedFor(doc, rig)
	local resolved = optionsFor(doc, options)
	local joint = rig.joints[address]
	if not p.active or joint == nil or p.chainOf[address] == nil then
		return fkValue(doc, address, t, resolved)
	end
	local solved, problem = solveWith(p, doc, rig, t, resolved)
	local slot = p.slotOf[address]
	local target = p.targets[slot]
	if problem ~= nil or p.froms[slot] ~= nil then
		return fkValue(doc, address, t, resolved)
	end
	local parent = joint.parent
	local parentWorld = (if parent ~= nil then solved.worlds[parent] else nil)
		or joint.parentWorld
		or rig.root
	local frame =
		frameOf(rig, target, parentWorld * joint.parentOffset, solved.worlds, address, false, t)
	if frame == nil then
		return fkValue(doc, address, t, resolved)
	end
	return frame:Inverse() * solved.pivots[address]
end

function RigSolve.check(doc: Document, rig: Rig): string?
	local p = prepare(doc, rig)
	local times: { number } = { 0 }
	local function switchesOf(track: Pose.JointTrack?)
		local spaces: { SpaceSegment }? = if track ~= nil then track.spaces else nil
		for _, switch in spaces or {} do
			table.insert(times, switch.t)
			if #p.pulls > 0 and (switch.blend or 0) > 0 then
				table.insert(times, switch.t + (switch.blend :: number))
			end
		end
	end
	for _, address in p.jointSlots do
		switchesOf(doc.joints[address])
	end
	local controls = doc.controls
	if controls ~= nil then
		for _, name in p.controlSlots do
			switchesOf(controls[name])
		end
	end
	if #p.pulls > 0 then
		local length = math.max(doc.length, 0)
		local strengths = doc.gripStrength
		local fps = if doc.fps ~= nil and doc.fps > 0 then doc.fps else 60
		table.insert(times, length)
		for _, pull in p.pulls do
			local channel = if strengths ~= nil then strengths[pull.name] else nil
			if channel ~= nil then
				for _, key in channel.keys do
					table.insert(times, key.t)
				end
				if channel.modifiers ~= nil and #channel.modifiers > 0 then
					for frame = 0, math.ceil(length * fps) do
						table.insert(times, frame / fps)
					end
				end
			end
			for _, span in pull.loose do
				table.insert(times, span[1])
				if span[2] ~= math.huge then
					table.insert(times, span[2])
				end
			end
		end
		table.sort(times)
		for index = #times, 2, -1 do
			if times[index] - times[index - 1] > SAME then
				table.insert(times, (times[index - 1] + times[index]) / 2)
			end
		end
	end
	table.sort(times)
	for _, t in times do
		statesAt(p, doc, t)
		local order = orderOf(p, rig)
		if order.nodes == nil then
			return `At {seconds(t)}, {order.problem}`
		end
	end
	return p.note
end

local function withSwitch(doc: Document, address: string, t: number, target: SpaceTarget): Document
	local trial = table.clone(doc)
	trial.joints = table.clone(doc.joints)
	local original = doc.joints[address]
	local track: Pose.JointTrack = if original ~= nil
		then table.clone(original)
		else { rotationMode = "XYZ", channels = {} }
	local spaces: { SpaceSegment } = {}
	for _, switch in (if original ~= nil then original.spaces else nil) or {} do
		if switch.t < t then
			table.insert(spaces, switch)
		end
	end
	table.insert(spaces, { t = t, target = target })
	track.spaces = spaces
	trial.joints[address] = track
	return trial
end

function RigSolve.compensate(
	doc: Document,
	t: number,
	rig: Rig,
	address: string,
	target: SpaceTarget,
	options: Options?
): (CFrame?, string?)
	local joint = rig.joints[address]
	if joint == nil then
		return nil, `This rig has no joint '{address}'.`
	end
	local trial = withSwitch(doc, address, t, target)
	local tried = prepare(trial, rig)
	statesAt(tried, trial, t, options)
	local loop = orderOf(tried, rig)
	if loop.nodes == nil then
		return nil, `At {seconds(t)}, {loop.problem}`
	end
	local solved, problem = RigSolve.solve(doc, t, rig, options)
	if problem ~= nil then
		return nil, problem
	end
	local parentWorld = (if joint.parent ~= nil then solved.worlds[joint.parent] else nil)
		or joint.parentWorld
		or rig.root
	local frame, missing =
		frameOf(rig, target, parentWorld * joint.parentOffset, solved.worlds, address, false, t)
	if frame == nil then
		return nil, missing
	end
	return SpaceSolve.hold(solved.pivots[address], frame), nil
end

function RigSolve.controlValue(
	doc: Document,
	t: number,
	rig: Rig,
	name: string,
	world: CFrame?,
	options: Options?
): (CFrame?, string?)
	local p = preparedFor(doc, rig)
	local plan = p.controls[name]
	if plan == nil then
		return nil, `This rig cannot place the control '{name}'.`
	end
	local solved, problem = solveWith(p, doc, rig, t, optionsFor(doc, options))
	if problem ~= nil then
		return nil, problem
	end
	local controls = doc.controls
	local track = if controls ~= nil then controls[name] else nil
	local target, from = stateOf(if track ~= nil then track.spaces else nil, nil, t)
	if from ~= nil then
		return nil,
			`The control '{name}' is blending between two spaces at {seconds(t)}. Key it after the blend.`
	end
	local parent = plan.parent
	local restFrame = ((if parent ~= nil then solved.worlds[parent] else nil) or rig.root)
		* plan.restLocal
	local frame, missing = frameOf(rig, target, restFrame, solved.worlds, name, true, t)
	if frame == nil then
		return nil, missing
	end
	return frame:Inverse() * (world or restFrame), nil
end

function RigSolve.jointValue(
	doc: Document,
	t: number,
	rig: Rig,
	address: string,
	transform: CFrame,
	options: Options?
): (CFrame?, string?)
	local joint = rig.joints[address]
	if joint == nil then
		return transform, nil
	end
	local track = doc.joints[address]
	local starting = doc.startingSpaces
	local target, from = stateOf(
		if track ~= nil then track.spaces else nil,
		if starting ~= nil then starting[address] else nil,
		t
	)
	if from ~= nil then
		return nil,
			`'{address}' is blending between two spaces at {seconds(t)}. Key it after the blend.`
	end
	if target.kind == "Parent" then
		return transform, nil
	end
	local solved, problem = RigSolve.solve(doc, t, rig, options)
	if problem ~= nil then
		return nil, problem
	end
	local parentWorld = (if joint.parent ~= nil then solved.worlds[joint.parent] else nil)
		or joint.parentWorld
		or rig.root
	local restPivot = parentWorld * joint.parentOffset
	local frame, missing = frameOf(rig, target, restPivot, solved.worlds, address, false, t)
	if frame == nil then
		return nil, missing
	end
	return SpaceSolve.hold(restPivot * transform, frame), nil
end

function RigSolve.gripValue(
	doc: Document,
	t: number,
	rig: Rig,
	space: SpaceTarget,
	world: CFrame,
	options: Options?
): (CFrame?, string?)
	local solved, problem = RigSolve.solve(doc, t, rig, options)
	if problem ~= nil then
		return nil, problem
	end
	local frame = gripFrameOf(rig, solved.worlds, space)
	if frame == nil then
		return nil, `A grip cannot ride on '{space.joint or space.kind}' on this rig.`
	end
	return frame:Inverse() * world, nil
end

function RigSolve.gripLimb(doc: Document, rig: Rig, name: string): ({ string }?, string?)
	local plan = preparedFor(doc, rig).grips[name]
	if plan == nil then
		return nil, nil
	end
	local chain = plan.chain
	local links = table.move(chain.links, 1, plan.count, 1, table.create(plan.count))
	return links, if chain.synthetic then nil else chain.name
end

local function knotsOf(
	p: Prepared,
	doc: Document,
	rig: Rig,
	address: string,
	options: Options
): ({ number }, { number })
	local length = math.max(doc.length, 0)
	local times: { number } = { 0, length }
	local steep: { number } = {}
	local seen: { [string]: boolean } = {}
	local starting = doc.startingSpaces or {}
	local scan = if options.fps ~= nil and options.fps > 0 then options.fps else 60

	local function knotsOfChannel(channel: Modifiers.Channel)
		if movesTime(channel) then
			return
		end
		for _, key in channel.keys do
			table.insert(times, key.t)
		end
		Interp.easingKnots(channel, options.presets, times, steep)
		Modifiers.clampKnots(channel, 0, length, scan, options :: any, times)
	end
	local function keysOf(track: Pose.JointTrack?)
		if track == nil then
			return
		end
		for _, channel in track.channels do
			knotsOfChannel(channel)
		end
	end
	local function switchesOf(track: Pose.JointTrack?)
		local spaces: { SpaceSegment }? = if track ~= nil then track.spaces else nil
		for _, switch in spaces or {} do
			table.insert(times, switch.t)
			local blend = switch.blend or 0
			if blend > 0 then
				table.insert(times, switch.t + blend)
			end
		end
	end

	local visitJoint: (address: string, world: boolean) -> ()
	local visitChain: (plan: ChainPlan) -> ()
	local visitControl: (name: string) -> ()
	local visitGrip: (plan: GripPlan) -> ()

	local function follows(track: Pose.JointTrack?, initial: SpaceTarget?)
		local targets: { SpaceTarget } = {}
		if initial ~= nil then
			table.insert(targets, initial)
		end
		local spaces: { SpaceSegment }? = if track ~= nil then track.spaces else nil
		for _, switch in spaces or {} do
			table.insert(targets, switch.target)
		end
		for _, target in targets do
			if target.kind == "Joint" and target.slot == nil and target.joint ~= nil then
				visitJoint(target.joint, true)
			end
		end
	end

	visitJoint = function(name: string, world: boolean)
		local key = (if world then "w:" else "t:") .. name
		local joint = rig.joints[name]
		if seen[key] or joint == nil then
			return
		end
		seen[key] = true
		if world then
			visitJoint(name, false)
			if joint.parent ~= nil then
				visitJoint(joint.parent, true)
			end
			return
		end
		local track = doc.joints[name]
		keysOf(track)
		for _, layer in doc.layers or {} do
			if layer.mute ~= true and LayerEval.factor(layer, name) > 0 then
				keysOf(layer.joints[name])
			end
		end
		switchesOf(track)
		local chain = p.chainOf[name]
		if p.spaced[name] or chain ~= nil then
			if joint.parent ~= nil then
				visitJoint(joint.parent, true)
			end
			follows(track, starting[name])
		end
		if chain ~= nil then
			visitChain(chain)
		end
	end

	visitChain = function(plan: ChainPlan)
		local key = "k:" .. plan.name
		if seen[key] then
			return
		end
		seen[key] = true
		for _, link in plan.links do
			visitJoint(link, false)
		end
		local weight = if doc.ikBlend ~= nil then doc.ikBlend[plan.name] else nil
		if weight ~= nil then
			knotsOfChannel(weight)
		end
		for _, family in ChainKeys.FAMILIES do
			local channel = ChainKeys.channelOf(doc, plan.name, family)
			if channel ~= nil then
				knotsOfChannel(channel)
			end
		end
		if not plan.synthetic then
			visitControl(plan.target)
		end
		if plan.pole ~= nil then
			visitControl(plan.pole)
		end
		if plan.plant ~= nil then
			visitControl(plan.plant)
		end
		for _, pull in plan.pulls or {} do
			visitGrip(pull)
		end
	end

	visitGrip = function(plan: GripPlan)
		local key = "g:" .. plan.name
		if seen[key] then
			return
		end
		seen[key] = true
		local grips = doc.grips
		local grip = if grips ~= nil then grips[plan.name] else nil
		keysOf(grip :: any)
		local box = if grip ~= nil then grip.box else nil
		if box ~= nil and grip ~= nil then
			for index, axis in Pose.POSITION_CHANNELS do
				local channel = grip.channels[axis]
				if channel == nil or movesTime(channel) then
					continue
				end
				local half = box[index] / 2
				local modifiers = table.clone(channel.modifiers or {})
				table.insert(
					modifiers,
					{ kind = "Limits", minValue = -half, maxValue = half } :: any
				)
				local held: Modifiers.Channel = {
					keys = channel.keys,
					interp = channel.interp,
					modifiers = modifiers,
				}
				Modifiers.clampKnots(held, 0, length, scan, options :: any, times)
			end
		end
		for _, family in { doc.gripStrength or {}, doc.gripTurn or {}, doc.gripMove or {} } do
			local channel = family[plan.name]
			if channel ~= nil then
				knotsOfChannel(channel)
			end
		end
		local space = plan.space
		if space.kind == "Joint" and space.joint ~= nil then
			visitJoint(space.joint, true)
		end
		if plan.via then
			visitJoint(plan.target, false)
		end
		for _, span in plan.loose do
			table.insert(times, span[1])
			if span[2] < math.huge then
				table.insert(times, span[2])
			end
		end
	end

	visitControl = function(name: string)
		local key = "c:" .. name
		if seen[key] then
			return
		end
		seen[key] = true
		local track = if doc.controls ~= nil then doc.controls[name] else nil
		keysOf(track)
		switchesOf(track)
		local plan = p.controls[name]
		if plan ~= nil and plan.parent ~= nil then
			visitJoint(plan.parent, true)
		end
		follows(track, nil)
	end

	visitJoint(address, false)
	return uniqueTimes(times, length), uniqueTimes(steep, length)
end

local function rateOf(channel: any, best: number?): number?
	local function consider(rate: any)
		if
			type(rate) == "number"
			and rate > 0
			and rate < math.huge
			and (best == nil or rate > best)
		then
			best = rate
		end
	end
	consider(channel.bakeRate)
	for _, modifier in channel.modifiers or {} do
		if modifier.mute ~= true then
			consider(modifier.bakeRate)
		end
	end
	return best
end

function RigSolve.flatten(doc: Document, rig: Rig, options: Options?): Document
	local p = prepare(doc, rig)
	if not p.active then
		return doc
	end
	local evalOptions: Options = {
		presets = if options ~= nil and options.presets ~= nil
			then options.presets
			else doc.presets,
		fps = if options ~= nil and options.fps ~= nil then options.fps else doc.fps,
		solo = false,
	}
	local flat: Document = LayerEval.flatten(doc :: any, evalOptions) :: any

	local memo: { [number]: { [string]: CFrame } } = {}
	local function solvedAt(t: number): { [string]: CFrame }
		local found = memo[t]
		if found == nil then
			local solved = solveWith(p, doc, rig, t, evalOptions, true)
			found = {}
			for _, address in p.affected do
				found[address] = solved.transforms[address]
			end
			memo[t] = found
		end
		return found :: { [string]: CFrame }
	end

	local joints: { [string]: Pose.JointTrack } = table.clone(flat.joints)
	for _, address in p.affected do
		local own = flat.joints[address]
		local mode: Pose.RotationMode = if own ~= nil then own.rotationMode else "XYZ"
		local names: { string } = {}
		local chain = p.chainOf[address]
		local moves = p.spaced[address] or (chain ~= nil and chain.moves[address] == true)
		for _, name in POSITION do
			if moves or (own ~= nil and own.channels[name] ~= nil) then
				table.insert(names, name)
			end
		end
		table.move(
			if mode == "Quaternion" then QUATERNION else EULER,
			1,
			if mode == "Quaternion" then 4 else 3,
			#names + 1,
			names
		)

		local knots, steep = knotsOf(p, doc, rig, address, evalOptions)
		local previous: Pose.Values? = nil
		local base = doc.joints[address]
		if base ~= nil then
			local seed: { [string]: number } = {}
			for _, name in if mode == "Quaternion" then QUATERNION else EULER do
				local channel = base.channels[name]
				if channel ~= nil then
					seed[name] = Modifiers.evaluate(channel, knots[1], evalOptions :: any)
				end
			end
			previous = seed :: any
		end
		local values: { { [string]: number } } = {}
		for index, t in knots do
			local at = Pose.toValues(solvedAt(t)[address], mode, previous)
			values[index] = at :: any
			previous = at
		end

		local channels: { [string]: LayerEval.FlatChannel } = {}
		for _, name in names do
			local keys = table.create(#knots)
			for index, t in knots do
				keys[index] = { t = t, v = values[index][name] or 0, interp = "Linear" }
			end
			local rate: number? = nil
			if own ~= nil then
				local shaping = if table.find(POSITION, name) ~= nil then { name } else ROTATIONS
				for _, source in shaping do
					local channel = own.channels[source]
					if channel ~= nil then
						rate = rateOf(channel, rate)
					end
				end
			end
			channels[name] = {
				keys = keys,
				bakeRate = rate,
				steep = if #steep > 0 then steep else nil,
			}
		end
		local track: LayerEval.FlatTrack = {
			rotationMode = mode,
			channels = channels,
			sample = function(t: number): CFrame
				return solvedAt(t)[address]
			end,
		}
		joints[address] = track :: any
	end

	local out = table.clone(flat)
	out.joints = joints
	out.layers = nil
	return out
end

return RigSolve
