--!strict
--!native
--!optimize 2

local Pose = require(script.Parent.Pose)

local SpaceSolve = {}

export type SpaceKind = "Parent" | "World" | "RigRoot" | "Joint"

export type SpaceTarget = {
	kind: SpaceKind,
	joint: string?,
	slot: string?,
}

export type SpaceSegment = {
	t: number,
	target: SpaceTarget,
	blend: number?,
	onEnd: string?,
}

export type RigJoint = {
	parent: string?,
	parentOffset: CFrame,
	childOffset: CFrame,
	parentWorld: CFrame?,
	spaces: { SpaceSegment }?,
	starting: SpaceTarget?,
}

export type Elsewhere = (target: SpaceTarget, t: number) -> CFrame?

export type Rig = {
	root: CFrame,
	world: CFrame?,
	joints: { [string]: RigJoint },
	elsewhere: Elsewhere?,
}

export type State = {
	target: SpaceTarget,
	from: SpaceTarget?,
	since: number?,
	weight: number,
}

export type Solved = {
	transforms: { [string]: CFrame },
	pivots: { [string]: CFrame },
	worlds: { [string]: CFrame },
}

export type ValueAt = (address: string, t: number) -> CFrame

export type Document = {
	joints: { [string]: Pose.JointTrack },
	startingSpaces: { [string]: SpaceTarget }?,
}

SpaceSolve.PARENT = table.freeze({ kind = "Parent" }) :: SpaceTarget

SpaceSolve.BEFORE = 1e-6

SpaceSolve.LEAD = 1e-4

function SpaceSolve.toTransform(
	value: CFrame,
	kind: SpaceKind,
	parentWorld: CFrame,
	parentOffset: CFrame,
	spaceWorld: CFrame?
): CFrame
	if kind == "Parent" or spaceWorld == nil then
		return value
	end
	return (parentWorld * parentOffset):Inverse() * spaceWorld * value
end

function SpaceSolve.toValue(
	transform: CFrame,
	kind: SpaceKind,
	parentWorld: CFrame,
	parentOffset: CFrame,
	spaceWorld: CFrame?
): CFrame
	if kind == "Parent" or spaceWorld == nil then
		return transform
	end
	return spaceWorld:Inverse() * parentWorld * parentOffset * transform
end

function SpaceSolve.hold(pivotWorld: CFrame, spaceFrame: CFrame): CFrame
	return spaceFrame:Inverse() * pivotWorld
end

local function ease(u: number): number
	if u <= 0 then
		return 0
	elseif u >= 1 then
		return 1
	end
	return u * u * (3 - 2 * u)
end

function SpaceSolve.stateAt(spaces: { SpaceSegment }?, starting: SpaceTarget?, t: number): State
	local initial = starting or SpaceSolve.PARENT
	if spaces == nil then
		return { target = initial, weight = 1 }
	end
	local index = 0
	for position, switch in spaces do
		if switch.t <= t then
			index = position
		else
			break
		end
	end
	if index == 0 then
		return { target = initial, weight = 1 }
	end
	local switch = spaces[index]
	local blend = switch.blend or 0
	if blend > 0 and t < switch.t + blend then
		return {
			target = switch.target,
			from = if index > 1 then spaces[index - 1].target else initial,
			since = switch.t,
			weight = ease((t - switch.t) / blend),
		}
	end
	return { target = switch.target, weight = 1 }
end

local function seconds(t: number): string
	return string.format("%.2f s", t)
end

type Edge = { joint: string, how: string }

local function edgesOf(rig: Rig, address: string, state: State, t: number): ({ Edge }, string?)
	local edges: { Edge } = {}
	local joint = rig.joints[address]
	if joint.parent ~= nil and rig.joints[joint.parent] ~= nil then
		table.insert(edges, { joint = joint.parent, how = "hangs from" })
	end
	for _, target in { state.target, state.from } do
		if target.kind == "Joint" and target.slot == nil then
			local followed = target.joint
			if followed == nil or rig.joints[followed] == nil then
				return edges,
					`At {seconds(t)}, '{address}' follows '{followed or "?"}', which this rig does not have.`
			end
			table.insert(edges, { joint = followed, how = "follows" })
		end
	end
	return edges, nil
end

local function describeCycle(path: { string }, hows: { string }, t: number): string
	if #path == 1 then
		return `At {seconds(t)}, '{path[1]}' {hows[1]} itself, so it has nothing to be placed from. Put it in another space.`
	end
	local phrases: { string } = {}
	for index, address in path do
		local nextAddress = path[index % #path + 1]
		table.insert(phrases, `'{address}' {hows[index]} '{nextAddress}'`)
	end
	local list = table.concat(phrases, ", ", 1, #phrases - 1) .. " and " .. phrases[#phrases]
	local who = if #path == 2 then "neither can" else "none of them can"
	return `At {seconds(t)}, {list}, so {who} be placed first. Put one of them in another space.`
end

local function order(rig: Rig, states: { [string]: State }, t: number): ({ string }?, string?)
	local addresses: { string } = {}
	for address in rig.joints do
		table.insert(addresses, address)
	end
	table.sort(addresses)

	local ordered: { string } = {}
	local mark: { [string]: number } = {}
	local path: { string } = {}
	local hows: { string } = {}

	local function visit(address: string): string?
		mark[address] = 1
		table.insert(path, address)
		local edges, problem = edgesOf(rig, address, states[address], t)
		if problem ~= nil then
			return problem
		end
		for _, edge in edges do
			local seen = mark[edge.joint]
			hows[#path] = edge.how
			if seen == 1 then
				local from = table.find(path, edge.joint) :: number
				local cycle = table.move(path, from, #path, 1, {})
				local words = table.move(hows, from, #path, 1, {})
				return describeCycle(cycle, words, t)
			elseif seen == nil then
				local inner = visit(edge.joint)
				if inner ~= nil then
					return inner
				end
			end
		end
		table.remove(path)
		hows[#path + 1] = nil
		mark[address] = 2
		table.insert(ordered, address)
		return nil
	end

	for _, address in addresses do
		if mark[address] == nil then
			local problem = visit(address)
			if problem ~= nil then
				return nil, problem
			end
		end
	end
	return ordered, nil
end

local function statesAt(rig: Rig, t: number): { [string]: State }
	local states: { [string]: State } = {}
	for address, joint in rig.joints do
		states[address] = SpaceSolve.stateAt(joint.spaces, joint.starting, t)
	end
	return states
end

local function switchTimes(rig: Rig): { number }
	local times: { number } = { 0 }
	for _, joint in rig.joints do
		for _, switch in joint.spaces or {} do
			table.insert(times, switch.t)
		end
	end
	table.sort(times)
	return times
end

function SpaceSolve.check(rig: Rig): string?
	for _, t in switchTimes(rig) do
		local _, problem = order(rig, statesAt(rig, t), t)
		if problem ~= nil then
			return problem
		end
	end
	return nil
end

local function frameOf(
	rig: Rig,
	target: SpaceTarget,
	restPivot: CFrame,
	worlds: { [string]: CFrame },
	address: string,
	t: number
): (CFrame?, string?)
	local kind = target.kind
	if kind == "Parent" then
		return restPivot, nil
	elseif kind == "World" then
		return rig.world or CFrame.identity, nil
	end
	if target.slot ~= nil then
		local placed = if rig.elsewhere then rig.elsewhere(target, t) else nil
		if placed == nil then
			return nil,
				`'{address}' follows the rig in slot '{target.slot}', which only its scene can place.`
		end
		return placed, nil
	end
	if kind == "RigRoot" then
		return rig.root, nil
	end
	local followed = target.joint
	local world = if followed then worlds[followed] else nil
	if world == nil then
		return nil, `'{address}' follows '{followed or "?"}', which this rig does not have.`
	end
	return world, nil
end

function SpaceSolve.solve(rig: Rig, t: number, valueAt: ValueAt): (Solved?, string?)
	local states = statesAt(rig, t)
	local ordered, problem = order(rig, states, t)
	if ordered == nil then
		return nil, problem
	end

	local transforms: { [string]: CFrame } = {}
	local pivots: { [string]: CFrame } = {}
	local worlds: { [string]: CFrame } = {}
	for _, address in ordered do
		local joint = rig.joints[address]
		local parentWorld = (if joint.parent then worlds[joint.parent] else nil)
			or joint.parentWorld
			or rig.root
		local restPivot = parentWorld * joint.parentOffset
		local state = states[address]
		local value = valueAt(address, t)

		local transform: CFrame
		local pivot: CFrame
		if state.target.kind == "Parent" and state.from == nil then
			transform = value
			pivot = restPivot * value
		else
			local frame, missing = frameOf(rig, state.target, restPivot, worlds, address, t)
			if frame == nil then
				return nil, missing
			end
			pivot = frame * value
			local from = state.from
			if from ~= nil then
				local fromFrame, lost = frameOf(rig, from, restPivot, worlds, address, t)
				if fromFrame == nil then
					return nil, lost
				end
				local held = fromFrame
					* valueAt(address, (state.since :: number) - SpaceSolve.BEFORE)
				pivot = held:Lerp(pivot, state.weight)
			end
			transform = restPivot:Inverse() * pivot
		end
		transforms[address] = transform
		pivots[address] = pivot
		worlds[address] = pivot * joint.childOffset:Inverse()
	end
	return { transforms = transforms, pivots = pivots, worlds = worlds }, nil
end

function SpaceSolve.compensate(
	rig: Rig,
	t: number,
	valueAt: ValueAt,
	address: string,
	target: SpaceTarget
): (CFrame?, string?)
	local joint = rig.joints[address]
	if joint == nil then
		return nil, `This rig has no joint '{address}'.`
	end
	local solved, problem = SpaceSolve.solve(rig, t, valueAt)
	if solved == nil then
		return nil, problem
	end
	local states = statesAt(rig, t)
	states[address] = { target = target, weight = 1 }
	local _, loop = order(rig, states, t)
	if loop ~= nil then
		return nil, loop
	end
	local parentWorld = (if joint.parent then solved.worlds[joint.parent] else nil)
		or joint.parentWorld
		or rig.root
	local frame, missing =
		frameOf(rig, target, parentWorld * joint.parentOffset, solved.worlds, address, t)
	if frame == nil then
		return nil, missing
	end
	return SpaceSolve.hold(solved.pivots[address], frame), nil
end

function SpaceSolve.withDocument(rig: Rig, doc: Document): Rig
	local joints: { [string]: RigJoint } = {}
	local starting = doc.startingSpaces or {}
	for address, joint in rig.joints do
		local track = doc.joints[address]
		local copy = table.clone(joint)
		copy.spaces = if track then track.spaces else nil
		copy.starting = starting[address]
		joints[address] = copy
	end
	return { root = rig.root, world = rig.world, joints = joints, elsewhere = rig.elsewhere }
end

local function leavesParent(spaces: { SpaceSegment }?, starting: SpaceTarget?): boolean
	if starting ~= nil and starting.kind ~= "Parent" then
		return true
	end
	for _, switch in spaces or {} do
		if switch.target.kind ~= "Parent" then
			return true
		end
	end
	return false
end

function SpaceSolve.spaced(rig: Rig, doc: Document): { string }
	local list: { string } = {}
	local starting = doc.startingSpaces or {}
	for address in rig.joints do
		local track = doc.joints[address]
		if leavesParent(if track then track.spaces else nil, starting[address]) then
			table.insert(list, address)
		end
	end
	table.sort(list)
	return list
end

return SpaceSolve
