--!strict
--!native
--!optimize 2

local TwoBone = {}

export type JointLimit = {
	x: { number }?,
	y: { number }?,
	z: { number }?,
}

export type Link = {
	parentOffset: CFrame,
	childOffset: CFrame,
	transform: CFrame?,
	limit: JointLimit?,
	stiffness: number?,
}

export type Chain = {
	parentWorld: CFrame,
	links: { Link },
}

export type Settings = {
	pole: Vector3?,
	poleAngle: number?,
	stretch: number?,
	softness: number?,
	orientTip: (boolean | number)?,
	hinge: Vector3?,
	bend: Vector3?,
	iterations: number?,
	tolerance: number?,
	tip: CFrame?,
	share: number?,
	slideIn: (boolean | number)?,
	length: Vector3?,
	lean: number?,
}

export type Result = {
	transforms: { CFrame },
	reached: boolean,
	distance: number,
	stretch: number,
	passes: number,
}

TwoBone.BEND = Vector3.new(0, 0, -1)

TwoBone.REACHED = 1e-4

local EPSILON = 1e-6

local abs, sqrt, exp, cos, sin, acos, atan2 =
	math.abs, math.sqrt, math.exp, math.cos, math.sin, math.acos, math.atan2
local min, max = math.min, math.max

local function unit(v: Vector3): Vector3?
	local length = v.Magnitude
	if length < EPSILON then
		return nil
	end
	return v / length
end

local function perpendicular(v: Vector3): Vector3
	local other = if abs(v.X) < 0.9 then Vector3.xAxis else Vector3.yAxis
	return v:Cross(other).Unit
end

local function across(v: Vector3, axis: Vector3): Vector3?
	return unit(v - axis * v:Dot(axis))
end

local function arc(a: Vector3, b: Vector3): CFrame
	local axis = a:Cross(b)
	local sine = axis.Magnitude
	local cosine = a:Dot(b)
	if sine < EPSILON then
		if cosine > 0 then
			return CFrame.identity
		end
		return CFrame.fromAxisAngle(perpendicular(a), math.pi)
	end
	return CFrame.fromAxisAngle(axis / sine, atan2(sine, cosine))
end

local function basis(x: Vector3, y: Vector3): CFrame
	return CFrame.fromMatrix(Vector3.zero, x, y, x:Cross(y))
end

local function place(position: Vector3, rotation: CFrame): CFrame
	return CFrame.new(position) * rotation.Rotation
end

local function between(a: Vector3, b: Vector3): number
	local x, y, z = a.X - b.X, a.Y - b.Y, a.Z - b.Z
	return sqrt(x * x + y * y + z * z)
end

local function turn(v: Vector3, axis: Vector3, angle: number): Vector3
	if angle == 0 then
		return v
	end
	return v * cos(angle) + axis:Cross(v) * sin(angle)
end

type Posed = {
	bases: { CFrame },
	frames: { CFrame },
}

local function pose(chain: Chain): Posed
	local bases: { CFrame } = {}
	local frames: { CFrame } = {}
	local parentEnd = chain.parentWorld
	for index, link in chain.links do
		local base = parentEnd * link.parentOffset
		local frame = base * (link.transform or CFrame.identity)
		bases[index] = base
		frames[index] = frame
		parentEnd = frame * link.childOffset:Inverse()
	end
	return { bases = bases, frames = frames }
end

TwoBone.STRAIGHT = math.rad(1)

local function bentBy(upper: Vector3, lower: Vector3): number
	return atan2(upper:Cross(lower).Magnitude, upper:Dot(lower))
end

local function restBend(links: { Link }): number
	local middle = links[1].childOffset:Inverse() * links[2].parentOffset
	local tip = middle * links[2].childOffset:Inverse() * links[3].parentOffset
	local upper = middle.Position
	local lower = tip.Position - upper
	if upper.Magnitude < EPSILON or lower.Magnitude < EPSILON then
		return 0
	end
	return bentBy(upper, lower)
end

type Fold = {
	toMiddle: CFrame,
	upper: Vector3,
	lower: Vector3,
	hinge: Vector3,
	fixed: number,
	spread: number,
	open: number,
}

local function foldOf(links: { Link }, hinge: Vector3?): Fold?
	if hinge == nil or hinge.Magnitude < EPSILON or restBend(links) < TwoBone.STRAIGHT then
		return nil
	end
	local axis = hinge.Unit
	local toMiddle = links[1].childOffset:Inverse() * links[2].parentOffset
	local upper = toMiddle:VectorToObjectSpace(toMiddle.Position)
		+ (links[2].transform or CFrame.identity).Position
	local lower = (
		links[2].childOffset:Inverse()
		* links[3].parentOffset
		* (links[3].transform or CFrame.identity)
	).Position
	local upperAlong, lowerAlong = upper:Dot(axis), lower:Dot(axis)
	local upperAcross = upper - axis * upperAlong
	local lowerAcross = lower - axis * lowerAlong
	local spread = 2 * upperAcross.Magnitude * lowerAcross.Magnitude
	local open = atan2(axis:Dot(lowerAcross:Cross(upperAcross)), lowerAcross:Dot(upperAcross))
	if spread < EPSILON or open > TwoBone.STRAIGHT then
		return nil
	end
	return {
		toMiddle = toMiddle,
		upper = upper,
		lower = lower,
		hinge = axis,
		fixed = upper:Dot(upper) + lower:Dot(lower) + 2 * upperAlong * lowerAlong,
		spread = spread,
		open = open,
	}
end

function TwoBone.bendOf(chain: Chain, settings: Settings?): (Vector3, Vector3, Vector3, Vector3)
	local posed = pose(chain)
	local root = posed.frames[1].Position
	local middle = posed.frames[2].Position
	local tip = posed.frames[3].Position
	local upper = unit(middle - root)
	local lower = unit(tip - middle)
	local axis = unit(tip - root) or upper or Vector3.yAxis
	local fold = foldOf(chain.links, settings and settings.hinge)
	if fold ~= nil then
		local folds = unit(axis:Cross(posed.bases[2]:VectorToWorldSpace(fold.hinge)))
		if folds ~= nil then
			return folds, axis, root, middle
		end
	end
	local normal: Vector3? = nil
	if upper and lower and bentBy(upper, lower) >= TwoBone.STRAIGHT then
		normal = unit(lower:Cross(upper))
	end
	if normal == nil then
		local hint =
			posed.frames[1]:VectorToWorldSpace((settings and settings.bend) or TwoBone.BEND)
		normal = unit((upper or axis):Cross(hint)) or perpendicular(upper or axis)
	end
	local side = unit((normal :: Vector3):Cross(axis)) or perpendicular(axis)
	return side, axis, root, middle
end

local function steering(links: { Link }, bend: number): number
	local rest = restBend(links)
	if rest < TwoBone.STRAIGHT then
		return 1
	end
	local share = math.clamp((bend - rest) / rest, 0, 1)
	return share * share * (3 - 2 * share)
end

local function transformsFor(chain: Chain, bases: { CFrame }, worlds: { CFrame }): { CFrame }
	local links = chain.links
	local out: { CFrame } = {}
	local parentEnd = chain.parentWorld
	for index = 1, 3 do
		local base = if index == 1 then bases[1] else parentEnd * links[index].parentOffset
		out[index] = base:Inverse() * worlds[index]
		parentEnd = worlds[index] * links[index].childOffset:Inverse()
	end
	return out
end

local function folded(
	posed: Posed,
	fold: Fold,
	target: CFrame,
	options: Settings
): ({ CFrame }?, number)
	local frames, bases = posed.frames, posed.bases
	local root = frames[1].Position
	local goal = target.Position
	local distance = between(goal, root)
	local longest = sqrt(max(0, fold.fixed + fold.spread))
	local shortest = sqrt(max(0, fold.fixed - fold.spread))
	local reach = min(distance, longest)
	local softness = options.softness or 0
	if softness > 0 then
		local width = min(softness, 1 - EPSILON) * longest
		local start = longest - width
		if distance > start then
			reach = start + width * (1 - exp(-(distance - start) / width))
		end
	end
	local scale = 1
	local stretch = options.stretch or 1
	if stretch > 1 and distance > reach and reach >= EPSILON then
		scale = min(stretch, distance / reach)
	end
	reach = max(reach, shortest)

	local cosine = math.clamp((reach * reach - fold.fixed) / fold.spread, -1, 1)
	local bent = CFrame.fromAxisAngle(fold.hinge, fold.open + acos(cosine))
	local line = fold.upper + bent * fold.lower
	local along = unit(line)
	local side = unit(line:Cross(fold.hinge))
	if along == nil or side == nil then
		return nil, 1
	end
	local direction = if distance >= EPSILON
		then (goal - root) / distance
		else bases[2]:VectorToWorldSpace(along)
	local foldSide: Vector3? = nil
	if options.pole then
		local toPole = options.pole - root
		toPole -= direction * toPole:Dot(direction)
		local away = toPole.Magnitude
		if away >= EPSILON then
			local outward = toPole / away
			local sine = math.clamp(-fold.upper:Dot(along:Cross(side)) * scale / away, -1, 1)
			foldSide = outward * sqrt(1 - sine * sine) + direction:Cross(outward) * sine
		end
	end
	if foldSide == nil then
		local swung = arc(bases[2]:VectorToWorldSpace(along), direction)
			* bases[2]:VectorToWorldSpace(side)
		foldSide = across(swung, direction) or perpendicular(direction)
	end
	local bendSide = turn(foldSide :: Vector3, direction, options.poleAngle or 0)

	local middleTurn = basis(direction, bendSide) * basis(along, side):Inverse()
	local lowerTurn = middleTurn * bent
	local tipRotation = if options.orientTip ~= false
		then target.Rotation
		else lowerTurn * frames[2].Rotation:Inverse() * frames[3].Rotation
	return {
		place(root, middleTurn * fold.toMiddle.Rotation:Inverse()),
		place(root + middleTurn * fold.upper * scale, lowerTurn),
		place(root + middleTurn * line * scale, tipRotation),
	},
		scale
end

function TwoBone.solve(chain: Chain, target: CFrame, settings: Settings?): Result
	assert(#chain.links == 3, "TwoBone.solve takes a chain of exactly three joints")
	local options: Settings = settings or {}
	local posed = pose(chain)
	local bases, frames = posed.bases, posed.frames
	local upperFrame, lowerFrame, tipFrame = frames[1], frames[2], frames[3]

	local root = upperFrame.Position
	local middle0 = lowerFrame.Position
	local end0 = tipFrame.Position
	local upperLength = between(middle0, root)
	local lowerLength = between(end0, middle0)
	local goal = target.Position
	local orientTip = options.orientTip ~= false

	local function finish(worlds: { CFrame }, scale: number): Result
		local transforms = transformsFor(chain, bases, worlds)
		local distance = (worlds[3].Position - goal).Magnitude
		return {
			transforms = transforms,
			reached = distance <= TwoBone.REACHED,
			distance = distance,
			stretch = scale,
			passes = 1,
		}
	end

	local fold = foldOf(chain.links, options.hinge)
	if fold ~= nil and upperLength >= EPSILON and lowerLength >= EPSILON then
		local worlds, scale = folded(posed, fold, target, options)
		if worlds ~= nil then
			return finish(worlds, scale)
		end
	end

	if upperLength < EPSILON or lowerLength < EPSILON then
		local turnBy = CFrame.identity
		local lowerTurn = CFrame.identity
		if lowerLength >= EPSILON then
			local want = unit(goal - middle0)
			if want then
				lowerTurn = arc((end0 - middle0) / lowerLength, want)
			end
		elseif upperLength >= EPSILON then
			local want = unit(goal - root)
			if want then
				turnBy = arc((middle0 - root) / upperLength, want)
				lowerTurn = turnBy
			end
		end
		local middle = root + turnBy * (middle0 - root)
		local finalEnd = middle + lowerTurn * (end0 - middle0)
		local tipRotation = if orientTip then target.Rotation else lowerTurn * tipFrame.Rotation
		return finish({
			place(root, turnBy * upperFrame.Rotation),
			place(middle, lowerTurn * lowerFrame.Rotation),
			place(finalEnd, tipRotation),
		}, 1)
	end

	local a0 = (middle0 - root) / upperLength
	local b0 = (end0 - middle0) / lowerLength
	local axis0 = unit(end0 - root) or a0
	local startNormal: Vector3
	local lowerNormal: Vector3
	if bentBy(a0, b0) >= TwoBone.STRAIGHT then
		startNormal = b0:Cross(a0).Unit
		lowerNormal = startNormal
	else
		local toPole = if options.pole then across(options.pole - root, a0) else nil
		local hint = toPole or upperFrame:VectorToWorldSpace(options.bend or TwoBone.BEND)
		startNormal = unit(a0:Cross(hint)) or perpendicular(a0)
		lowerNormal = unit(b0:Cross(hint)) or startNormal
	end

	local toGoal = goal - root
	local distance = between(goal, root)
	local direction = if distance >= EPSILON then toGoal / distance else axis0
	local length = upperLength + lowerLength
	local reach = min(distance, length)
	local softness = options.softness or 0
	if softness > 0 then
		local width = min(softness, 1 - EPSILON) * length
		local start = length - width
		if distance > start then
			reach = start + width * (1 - exp(-(distance - start) / width))
		end
	end
	local scale = 1
	local stretch = options.stretch or 1
	if stretch > 1 and distance > reach and reach >= EPSILON then
		scale = min(stretch, distance / reach)
	end
	local l1, l2 = upperLength * scale, lowerLength * scale
	reach = max(reach * scale, abs(l1 - l2))

	local swung = arc(axis0, direction) * startNormal
	local keep = (across(swung, direction) or perpendicular(direction)):Cross(direction)
	local poleAngle = options.poleAngle or 0
	local toPole = if options.pole then across(options.pole - root, direction) else nil
	local bendSide = turn(keep, direction, poleAngle)
	if toPole ~= nil then
		local inner = (l1 * l1 + l2 * l2 - reach * reach) / (2 * l1 * l2)
		local share = steering(chain.links, math.pi - acos(math.clamp(inner, -1, 1)))
		bendSide = turn(toPole, direction, poleAngle)
		if share < 1 then
			local apart = atan2(direction:Dot(keep:Cross(bendSide)), keep:Dot(bendSide))
			bendSide = turn(keep, direction, apart * share)
		end
	end
	local normal1 = direction:Cross(bendSide)

	local cosine = if reach >= EPSILON
		then (l1 * l1 + reach * reach - l2 * l2) / (2 * l1 * reach)
		else 0
	cosine = math.clamp(cosine, -1, 1)
	local sine = sqrt(max(0, 1 - cosine * cosine))
	local middle = root + (direction * cosine + bendSide * sine) * l1
	local finalEnd = root + direction * reach
	local a1 = (middle - root) / l1
	local b1 = unit(finalEnd - middle) or a1
	local upperTurn = basis(a1, normal1) * basis(a0, startNormal):Inverse()
	local lowerTurn = basis(b1, normal1) * basis(b0, lowerNormal):Inverse()

	local tipRotation = if orientTip then target.Rotation else lowerTurn * tipFrame.Rotation
	return finish({
		place(root, upperTurn * upperFrame.Rotation),
		place(middle, lowerTurn * lowerFrame.Rotation),
		place(finalEnd, tipRotation),
	}, scale)
end

return TwoBone
