--!strict

local Signal = {}

--[=[
	@class Connection

	What Signal:Connect and Signal:Once return.
]=]
local Connection = {}
Connection.__index = Connection

--[=[
	@prop Connected boolean
	@within Connection
	@readonly

	False once the connection is disconnected.
]=]

export type Connection = typeof(setmetatable(
	{} :: {
		Connected: boolean,
		_handler: ((...any) -> ())?,
		_signal: any,
	},
	Connection
))

--[=[
	@class Signal

	An event the engine fires, used like an RBXScriptSignal.
]=]
local Methods = {}
Methods.__index = Methods

export type Signal = typeof(setmetatable(
	{} :: {
		_connections: { Connection },
	},
	Methods
))

--[=[
	@method Disconnect
	@within Connection

	Stops the handler from being called again. Does nothing when already disconnected.
]=]
function Connection.Disconnect(self: Connection)
	if not self.Connected then
		return
	end
	self.Connected = false
	self._handler = nil
	local signal = self._signal :: Signal
	self._signal = nil
	local index = table.find(signal._connections, self)
	if index then
		table.remove(signal._connections, index)
	end
end

local function connect(self: Signal, handler: (...any) -> ()): Connection
	if type(handler) ~= "function" then
		error(`[ApexEngine] Connect expects a function, got {type(handler)}`, 3)
	end
	local connection = setmetatable({
		Connected = true,
		_handler = handler,
		_signal = self,
	}, Connection) :: Connection
	table.insert(self._connections, connection)
	return connection
end

--[=[
	@method Connect
	@within Signal

	Calls the handler on each fire, in connection order, each call in its own thread.

	@param handler (...any) -> ()
	@return Connection
]=]
function Methods.Connect(self: Signal, handler: (...any) -> ()): Connection
	return connect(self, handler)
end

--[=[
	@method Once
	@within Signal

	Like Connect, but disconnects before the first call, so the handler runs at most once.

	@param handler (...any) -> ()
	@return Connection
]=]
function Methods.Once(self: Signal, handler: (...any) -> ()): Connection
	local connection: Connection
	connection = connect(self, function(...)
		connection:Disconnect()
		handler(...)
	end)
	return connection
end

--[=[
	@method Wait
	@within Signal
	@yields

	Waits for the next fire.

	@return ...any -- the values the fire carried
]=]
function Methods.Wait(self: Signal): ...any
	local thread = coroutine.running()
	self:Once(function(...)
		task.spawn(thread, ...)
	end)
	return coroutine.yield()
end

function Signal.new(): Signal
	return setmetatable({ _connections = {} }, Methods) :: Signal
end

function Signal.fire(signal: Signal, ...: any)
	local connections = signal._connections
	if #connections == 0 then
		return
	end
	for _, connection in table.clone(connections) do
		local handler = connection._handler
		if connection.Connected and handler then
			task.spawn(handler, ...)
		end
	end
end

return Signal
