-- Repository metadata is fetched only for a failed raw asset. No shipped file
-- inventories or guessed cross-repository mirrors. Successful identities cache
-- for this session; HTTP failures have a bounded retry delay.
local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local digits = {}
for index = 1, #alphabet do digits[alphabet:byte(index)] = index - 1 end

return function(context)
    local now, blockedUntil = context.Clock or os.clock, 0
    local Assets = {}
    local metadata,failures={},{}
    local function encode(value)return (value:gsub("[^%w_.~/%-]",function(c)return string.format("%%%02X",c:byte())end))end
    function Assets.RawCandidate(_url)return nil end
    function Assets.Resolve(url)
        if context.Recovery then
            local sha,size,repository=context.Recovery.Blob(url)
            if sha then return sha,size,repository end
        end
        if metadata[url]then return table.unpack(metadata[url])end
        if now()<(failures[url]or 0)or now()<blockedUntil then return end
        local owner,repo,ref,path=tostring(url):match("^https://raw%.githubusercontent%.com/([%w_.%-]+)/([%w_.%-]+)/([^/]+)/(.+)$")
        if not owner then return end
        path=path:gsub("%%(%x%x)",function(hex)return string.char(tonumber(hex,16))end)
        if path:find("[%c\\]")or path:match("^/")then return end
        for segment in path:gmatch("[^/]+")do if segment==".."or segment=="."then return end end
        local ext=path:lower():match("%.([^./]+)$")
        if not ({anim=true,mp3=true,ogg=true,wav=true,png=true,jpg=true,jpeg=true,webp=true,rbxm=true})[ext]then return end
        failures[url]=now()+60
        local body,reason=context.Fetch("https://api.github.com/repos/"..owner.."/"..repo.."/contents/"..encode(path).."?ref="..encode(ref),nil,1)
        if not body then
            if tostring(reason):find("403",1,true)or tostring(reason):find("429",1,true)then blockedUntil=now()+600 end
            return
        end
        local ok,entry=pcall(context.DecodeJson,body)
        if not ok or type(entry)~="table"or entry.type~="file"or type(entry.sha)~="string"or #entry.sha~=40
            or not entry.sha:match("^%x+$")or type(entry.size)~="number"or entry.size<=0 or entry.size>64000000 then return end
        metadata[url]={entry.sha,entry.size,owner.."/"..repo}
        return table.unpack(metadata[url])
    end
    function Assets.DecodeBase64(content, expected)
        if type(content) ~= "string" or type(expected) ~= "number" or expected < 0 or expected > 64000000 then return nil, "invalid blob size" end
        local bytes = buffer.create(expected)
        local count, accumulator, bits, padding = 0, 0, 0, 0
        for index = 1, #content do
            local code = content:byte(index)
            local digit = digits[code]
            if digit ~= nil then
                if padding > 0 then return nil, "base64 data after padding" end
                accumulator = accumulator * 64 + digit
                bits += 6
                if bits >= 8 then
                    bits -= 8
                    local power = 2 ^ bits
                    local byte = math.floor(accumulator / power)
                    accumulator %= power
                    if count >= expected then return nil, "blob size mismatch" end
                    buffer.writeu8(bytes, count, byte)
                    count += 1
                end
