        for _, owner in ipairs({rig, humanoid}) do
            for _, name in ipairs({"Stunned", "IsStunned", "Stun", "Ragdolled", "KnockedDown"}) do
                local value = owner:GetAttribute(name)
                if value == true or type(value) == "number" and value > 0 then return true end
            end
        end
