    ["UhhhhhhReanim/System/runtime/steve110/main/code_layout.lua"] = [=====[
-- Fingerprint executable tokens without changing the source that is executed.
-- Quoted/long strings and compiler directives retain their exact bytes.
return function(source,maximum,yielding)
    local tokens,total={},0
    local function add(value)
        local text=#value..":"..value
        total+=#text
        if total>(maximum or 8*1024*1024)then return false end
        table.insert(tokens,text)return true
    end
    local at,nextYield=1,16384
    local function longEnd(start)
        local equals=source:sub(start):match("^%[(=*)%[")
        if equals==nil then return nil end
        local _,last=source:find("]"..equals.."]",start+2+#equals,true)
        return last or false
    end
    while at<=#source do
        if yielding and at>=nextYield then yielding()nextYield=at+16384 end
        local c=source:sub(at,at)
        if c:match("%s")then at+=1
        elseif source:sub(at,at+1)=="--"then
            local finish=longEnd(at+2)
            if finish==false then return nil end
            if finish then at=finish+1 else
                local last=source:find("[\r\n]",at)or #source+1
                if source:sub(at+2,at+2)=="!"and not add(source:sub(at,last-1))then return nil end
                at=last
            end
        elseif c=="\""or c=="'"then
            local start=at at+=1 local closed=false
            while at<=#source do
                local item=source:sub(at,at)
                if item=="\\"then at+=2
                elseif item==c then at+=1 closed=true break
                else at+=1 end
            end
            if not closed or not add(source:sub(start,at-1))then return nil end
        elseif c=="`"then
            return nil -- Interpolated strings keep exact-source identity.
        elseif c=="["then
            local finish=longEnd(at)
            if finish==false then return nil end
            if finish then
                if not add(source:sub(at,finish))then return nil end at=finish+1
            else if not add(c)then return nil end at+=1 end
        elseif c:match("[%w_]")then
            local finish=at
            while source:sub(finish+1,finish+1):match("[%w_]")do finish+=1 end
            if not add(source:sub(at,finish))then return nil end at=finish+1
        else
            if not add(c)then return nil end at+=1
        end
    end
    return table.concat(tokens,"|")
end
