    ["UhhhhhhReanim/System/runtime/steve110/main/creator_compat.lua"] = [=====[
-- BlaaBlaa stable Animation Creator data, rewritten for the shared animator.
-- Read the returned data only; never invoke the generator's preview callbacks.
return function(ctx)
    local api={}
    local joints={
        {"Neck","Head","Torso"},{"Left Shoulder","Left Arm","Torso"},
        {"Right Shoulder","Right Arm","Torso"},{"Left Hip","Left Leg","Torso"},
        {"Right Hip","Right Leg","Torso"},{"RootJoint","Torso","HumanoidRootPart"},
    }
    local known={}for _,joint in ipairs(joints)do known[joint[1]]=true end
    function api.IsCreator(value)
        return type(value)=="table"and value.ModuleType=="DANCE"
            and value.Description=="Created with Animation Creator"
    end
    function api.Entries(value)
        -- The stable generator exports a single module, while Steve packs
        -- export an array of factories. Do not reinterpret unrelated tables.
        if api.IsCreator(value)then return {function()return value end}end
        return value
    end
    local function finite(value,label,lo,hi)
        assert(type(value)=="number"and value==value and value>=lo and value<=hi,"invalid Creator "..label)
        return value
    end
    function api.Track(module)
        assert(api.IsCreator(module),"this is not a BlaaBlaa Animation Creator export")
        local duration=finite(module._dur,"duration",.01,3600)
        local source=module._kfs
        assert(type(source)=="table"and #source>0 and #source<=10000,"Creator needs 1 to 10000 keyframes")
        local count=0
        for index in pairs(source)do
            assert(type(index)=="number"and index%1==0 and index>=1 and index<=#source,"invalid Creator keyframe array")
            count+=1
        end
        assert(count==#source,"sparse Creator keyframe array")
        local keys,seen,active={},{},{}
        for _,key in ipairs(source)do
            assert(type(key)=="table"and type(key.Poses)=="table","invalid Creator keyframe")
            local time=finite(key.Time,"key time",0,duration)
            assert(not seen[time],"two Creator keyframes occupy the same time")seen[time]=true
            local poses={}
            for name,rotation in pairs(key.Poses)do
                assert(known[name]and type(rotation)=="table","unsupported Creator limb: "..tostring(name))
                local copy={}
                for _,axis in ipairs({"X","Y","Z"})do copy[axis]=finite(rotation[axis]or 0,"rotation",-36000,36000)end
                poses[name]=copy active[name]=true
            end
            table.insert(keys,{Time=time,Poses=poses})
        end
        table.sort(keys,function(a,b)return a.Time<b.Time end)
        assert(next(active),"Creator export has no limb poses")
        local track={Name=module.Name,Keyframes={},Markers={},RigType="R6",Looped=true,FPS=30,
            Studio={Version=1,ActiveLayer=0,Length=duration,Layers={},Curves={},Camera={},Props={},Targets={}}}
        -- Euler curves preserve rotations through more than half a turn.
        -- CFrame interpolation alone would silently choose a shorter arc.
        for _,joint in ipairs(joints)do if active[joint[1]]then
            track.Studio.Curves[joint[2]]={rotationMode="XYZ",channels={
                rx={interp="Linear",keys={}},ry={interp="Linear",keys={}},rz={interp="Linear",keys={}},
            }}
        end end
        for _,key in ipairs(keys)do
            local frame={Time=key.Time,Poses={}}
            for _,joint in ipairs(joints)do if active[joint[1]]then
                local rotation=key.Poses[joint[1]]or {X=0,Y=0,Z=0}
                local x,y,z=math.rad(rotation.X),math.rad(rotation.Y),math.rad(rotation.Z)
                table.insert(frame.Poses,{Name=joint[2],Parent=joint[3],Weight=1,
                    CFrame=CFrame.Angles(x,y,z),EasingStyle="Linear",EasingDirection="InOut"})
                local channels=track.Studio.Curves[joint[2]].channels
                for axis,value in pairs({rx=x,ry=y,rz=z})do table.insert(channels[axis].keys,{t=key.Time,v=value})end
            end end
            table.insert(track.Keyframes,frame)
        end
        return ctx.Files().Canonical(track)
    end
    function api.Adapt(module)
        if not api.IsCreator(module)or module._UhhhhhhCreatorPort then return module end
        local track=api.Track(module)
        local animator
        local function dispose()
            if animator then animator:Destroy(false)animator=nil end
        end
        module.Init=function(character)
            dispose()
            animator=ctx.AnimLib.Animator.fromTrack(character,track,{Looped=true,AutoFadeIn=0,
                UseGlobalPlaybackSpeed=true,UseDanceMusicSync=false,MarkerNotifications=false})
            animator:Play()animator:Step(0)
        end
        module.Update=function(dt)if animator then animator:Update(dt)end end
        module.Destroy=dispose
        module._UhhhhhhEditableTrack=track
        module._UhhhhhhCreatorPort=true
        return module
    end
    return api
end
