    ["UhhhhhhReanim/System/runtime/steve110/main/dropdown_bounds.lua"] = [=====[
-- Shared native popup/window geometry. Keep fitting separate from input and
-- tween state so menus, dragging and restore positions use the same bounds.
local Bounds={}
function Bounds.Window(viewport,position,size,anchor)
    local sw,sh=math.max(1,viewport.X),math.max(1,viewport.Y)
    local w,h=math.max(0,size.X),math.max(0,size.Y)
    anchor=anchor or Vector2.new(.5,.5)
    -- A fitting window stays wholly visible. An oversized one can still pan
    -- horizontally, but its top edge/header must remain reachable.
    local left,right=anchor.X*w,sw-(1-anchor.X)*w
    if left>right then left,right=right,left end
    local top,bottom=anchor.Y*h,sh-(1-anchor.Y)*h
    if top>bottom then bottom=top end
    return Vector2.new(math.clamp(position.X,left,right),math.clamp(position.Y,top,bottom))
end
function Bounds.Position(viewport,position,size,anchor,parentSize,parentOrigin)
    parentSize,parentOrigin=parentSize or viewport,parentOrigin or Vector2.zero
    local point=parentOrigin+Vector2.new(parentSize.X*position.X.Scale+position.X.Offset,
        parentSize.Y*position.Y.Scale+position.Y.Offset)
    local fitted=Bounds.Window(viewport,point,size,anchor)
    if (point-fitted).Magnitude<1e-7 then return position end
    return UDim2.new(position.X.Scale,fitted.X-parentOrigin.X-parentSize.X*position.X.Scale,
        position.Y.Scale,fitted.Y-parentOrigin.Y-parentSize.Y*position.Y.Scale)
end
function Bounds.Row(width,caption,value)
    width=math.max(1,width)
    local bw=math.min(width,math.max(60,value.X+8))
    local bh=math.max(25,value.Y+8)
    local stacked=caption.X+bw+8>width
    return stacked and caption.Y+4+bh or math.max(25,caption.Y,bh),
        stacked and width or math.max(1,width-bw-8),bw,bh,stacked
end
function Bounds.Place(viewport,anchor,anchorSize,width,height)
    local sw,sh=math.max(1,viewport.X),math.max(1,viewport.Y)
    local mx,my=math.min(6,(sw-1)/2),math.min(6,(sh-1)/2)
    local w,h=math.clamp(width,1,sw-2*mx),math.clamp(height,1,sh-2*my)
    local x=math.clamp(anchor.X,mx,sw-w-mx)
    local below=math.max(0,sh-my-anchor.Y-anchorSize.Y)
    local above=math.max(0,anchor.Y-my)
    local y=anchor.Y+anchorSize.Y
    if h<=below then
        -- Enough space below keeps the control and its selected value visible.
    elseif h<=above then y=anchor.Y-h
    elseif math.max(above,below)>=1 then
        -- Scroll the list in the larger available side instead of sliding an
        -- oversized popup over the control which opened it.
        if above>below then h=math.min(h,above)y=anchor.Y-h
        else h=math.min(h,below)end
    end
    return x,math.clamp(y,my,sh-h-my),w,h
end
return Bounds
