-- Sample what is displayed. Netless velocity is transport, not a prediction
-- offset for afterimages or visualizer anchors.
local Pose={}
local finite=require(script.Parent.head_tracking).Finite
local r15=require(script.Parent.reanimation.gelatek_r15)
function Pose.Read(part)
    if not part then return nil end
    local ok,value=pcall(function()return part:GetRenderCFrame()end)
    if ok and finite(value)then return value end
    local cf=part.CFrame
    return finite(cf)and cf or nil
end
function Pose.Anchor(figure,mode)
    if not figure or not figure.Parent then return nil end
    local root=figure:FindFirstChild("HumanoidRootPart")or figure.PrimaryPart
    local basis=Pose.Read(root)
    if not basis then return nil end
    local ok,scale=pcall(figure.GetScale,figure)
    scale=ok and tonumber(scale)or 1
    if not scale or scale~=scale or scale<=0 or scale==math.huge then scale=1 end
    local part=mode=="Head"and figure:FindFirstChild("Head")
        or mode=="Torso"and(figure:FindFirstChild("UpperTorso")or figure:FindFirstChild("Torso")or figure:FindFirstChild("LowerTorso"))
    local pose=part and Pose.Read(part)
    local position=pose and pose.Position
    if mode=="Blue Root Part"then position=basis.Position
    elseif mode=="Middle (Original)"then
        local head=Pose.Read(figure:FindFirstChild("Head"))or basis
