    ["UhhhhhhReanim/System/runtime/steve110/main/fork_credits.lua"] = [=====[
-- One data-driven source page. Original contributor/asset credits stay intact.
return function(ctx)
    local page
    local sources = ctx.Sources
    local button = ctx.UI.CreateButton(ctx.Parent, "Forks + source audit (" .. #sources.Entries .. ") >", 16)
    button.Activated:Connect(function()
        if not page then
            page = ctx.UI.CreatePage()
            page.Name, page.Visible, page.Interactable = "ForkSourceAudit", false, false
            ctx.UI.CreateButton(page, "< Back to credits", 16).Activated:Connect(function()
                ctx.UI.Workspace.Back(page, ctx.Parent)
            end)
            ctx.UI.CreateText(page, "Forks + source audit", 20, Enum.TextXAlignment.Left)
            local heading = ctx.UI.CreateText(page,
                sources.PublicForks .. " public forks; " .. #sources.Entries .. " relevant repositories checked on " .. sources.AuditDate
                .. ". Repository owners are hosts; individual code, animation and music credits remain with their authors. Repository code licenses do not establish permission for every music or animation asset.",
                12, Enum.TextXAlignment.Left)
            heading.RichText = false
            for _, row in ipairs(sources.Entries) do
                ctx.UI.CreateSeparator(page)
                local title = ctx.UI.CreateText(page, row.Name, 15, Enum.TextXAlignment.Left)
                title.RichText = false
                local details = ctx.UI.CreateText(page,
                    "Revision: " .. row.Head:sub(1, 12) .. " | Repository code license: " .. row.License .. "\n" .. row.Review,
                    12, Enum.TextXAlignment.Left)
                details.RichText = false
                ctx.UI.CreateButton(page, "Copy repository link", 12).Activated:Connect(function()
                    local ok = ctx.Copy and pcall(ctx.Copy, row.URL)
                    ctx.Notify(ok and "Copied source link" or "Clipboard unavailable: " .. row.URL)
                end)
                if ctx.Yield then ctx.Yield() end
            end
        end
        ctx.UI.Workspace.Open(page, ctx.Parent)
    end)
    return button
end

