    ["UhhhhhhReanim/System/runtime/steve110/main/fork_themes.lua"] = [=====[
-- Palette ports from Awes' beta and BlaaBlaa's stable GUI. Native Steve
-- themes keep their indices; saved names keep custom/new choices stable.
return function(theme,saved)
    local previousNames={}
    for i,preset in ipairs(theme.Themes)do previousNames[i]=preset.Name end
    local previousCustom=#previousNames+1
    local presets={
        {Name="Awes RED",Source="Awes955",Fore=Color3.new(1,.3,.3),Text=Color3.new(1,1,1)},
        {Name="Homer Simpson",Source="Awes955 / BlaaBlaa",Fore=Color3.new(0,0,0),Back=Color3.new(1,.95,0),Text=Color3.new(0,0,0)},
        {Name="Ocean",Source="BlaaBlaa",Fore=Color3.fromRGB(0,120,255),Back=Color3.fromRGB(0,10,40),
            Text=Color3.fromRGB(150,210,255),SndClick="rbxassetid://9114175929"},
        {Name="Pipis",Source="BlaaBlaa",Fore=Color3.fromHex("B0977A"),Back=Color3.fromHex("2A2018"),Text=Color3.fromHex("F0E8D6")},
        {Name="NitroX",Source="BlaaBlaa",Fore=Color3.fromHex("3ECC3E"),Back=Color3.fromHex("0A120A"),Text=Color3.fromHex("AAEAAA")},
        {Name="FastTracker II Blue (classic)",Source="Awes955 / BlaaBlaa",Fore=Color3.fromHex("333780"),
            Back=Color3.fromHex("666EFF"),Text=Color3.new(1,1,1)},
    }
    local selected=saved.UIThemeKey
    local index=tonumber(saved.UITheme)or 1
    if saved.UIThemeFormat~=3 or type(selected)~="string"then
        if saved.UIThemeFormat==2 then
            selected=index==previousCustom and "__custom"or previousNames[index]
        else
            -- Original Uhhhhhh settings. Other forks' separate config folders
            -- are not silently imported or guessed from an ambiguous number.
            selected=({"RGB/Default","ALONE","Oxide-ish","Patchma hub","Genesis V4 - Neptunian V",
                "Mr. Crimson","r/masterhacker","Homer Simpson","Immortality Lord","RGB LIGHT/Lightning Cannon",
                "ALONE LIGHT","The Roserika","FastTracker II Blue","Cherry Blossom","Sakura","Tommorow Night 80s","__custom"})[index]
        end
    end
    if saved.RoserikaStyleVersion~=1 then
        if saved.UITheme==nil or index==1 then selected="Roserika"end
        saved.RoserikaStyleVersion=1
    end
    local byName={}
    for i,preset in ipairs(theme.Themes)do byName[preset.Name]=i end
    for _,preset in ipairs(presets)do if not byName[preset.Name]then
        table.insert(theme.Themes,preset)byName[preset.Name]=#theme.Themes
    end end
    local api={Names={},ByName=byName,Custom=#theme.Themes+1}
    for _,preset in ipairs(theme.Themes)do table.insert(api.Names,preset.Name)end
    table.insert(api.Names,"User Defined (see README)")
    function api.Select(value)
        assert(type(value)=="number"and value%1==0 and value>=1 and value<=api.Custom,"unknown UI theme")
        saved.UITheme=value saved.UIThemeKey=value==api.Custom and "__custom"or theme.Themes[value].Name
        saved.UIThemeFormat=3
        return value
    end
    function api.Source(value)
        local preset=theme.Themes[value]
        return preset and (preset.Source or "Steve / Uhhhhhh")or "Your custom theme"
    end
    api.Select(selected=="__custom"and api.Custom or byName[selected]or 1)
    return api
end
