    ["UhhhhhhReanim/System/runtime/steve110/main/hat_bindings.lua"] = [=====[
-- Reversible controller accessory mounts shared by movesets and the editor.
-- Existing owned hats are reused; a declared hat is never silently substituted.
return function(ctx)
    local specifications=require(script.Parent.hat_spec)
    local api={Owners=setmetatable({}, {__mode="k"})}
    local function id(value)return tostring(value or ""):match("%d+")or ""end
    local function mesh(accessory)
        local handle=accessory:FindFirstChild("Handle")if not handle then return "",""end
        if handle:IsA("MeshPart")then return id(handle.MeshId),id(handle.TextureID)end
        local shape=handle:FindFirstChildOfClass("SpecialMesh")
        return shape and id(shape.MeshId)or "",shape and id(shape.TextureId)or ""
    end
    local function match(accessory,selector)
        local m,t=mesh(accessory)
        return (not selector.Name or selector.Name==accessory.Name)
            and (not selector.MeshId or id(selector.MeshId)==m)
            and (not selector.TextureId or id(selector.TextureId)==t)
    end
    function api.List(rig)
        local rows,order={},{}
        for _,accessory in ipairs(rig and rig:GetChildren()or {})do
            if accessory:IsA("Accessory")and accessory:FindFirstChild("Handle")then table.insert(rows,accessory)order[accessory]=#rows end
        end
        table.sort(rows,function(a,b)return a.Name==b.Name and order[a]<order[b]or a.Name<b.Name end)return rows
    end
    function api.Find(selector,rig)
        if type(selector)=="string"then selector={Name=selector}end
        assert(type(selector)=="table"and (selector.Name or selector.MeshId or selector.TextureId),"select a hat by name, mesh or texture")
        local matches={}
        for _,accessory in ipairs(api.List(rig or ctx.Real()))do if match(accessory,selector)then table.insert(matches,accessory)end end
        if selector.Occurrence then return matches[selector.Occurrence]end
        assert(#matches<=1,"hat selection is ambiguous; provide Occurrence")return matches[1]
    end
    local function frame(value)
        assert(typeof(value)=="CFrame","hat offset must be a CFrame")
        for _,n in ipairs({value:GetComponents()})do assert(n==n and math.abs(n)<100000,"hat offset must be finite")end
        return value
    end
    function api.Release(owner)
        local records=api.Owners[owner]if not records then return end api.Owners[owner]=nil
        for i=#records,1,-1 do
            local record=records[i]
            if record.Override then
                local at=table.find(ctx.Hat.HatCFrameOverride,record.Override)
                if at then table.remove(ctx.Hat.HatCFrameOverride,at)end
            end
            if record.Motor then record.Motor:Destroy()end
            if record.Cloned then record.Accessory:Destroy()
            else
                for joint,enabled in pairs(record.Joints)do if joint.Parent and joint.Enabled==false then joint.Enabled=enabled end end
            end
        end
    end
    function api.Mount(owner,rig,selector,target,offset)
        assert(owner and rig,"mount hats during the module's Init")
        if type(target)=="string"then
            local schema=ctx.Schema.Get(rig)
            local node=schema.ByName[schema.Aliases[target]or target]
            target=node and node.Part or rig:FindFirstChild(target,true)
        end
        assert(typeof(target)=="Instance"and target:IsA("BasePart")and target:IsDescendantOf(rig),"hat target must be a part in the current controller")
        offset=frame(offset or CFrame.identity)
        local source=assert(api.Find(selector),"the requested hat is not on your real character")
        local accessory=api.Find(selector,rig)
        local state=ctx.Schema.Get(rig)
        local targetNode=state.ByPart[target]
        local record={Joints={},Rig=rig,Spec=specifications.Canonical({{
            Selector=selector,Part=targetNode and targetNode.Name or target.Name,Offset=offset}})[1]}
        local ok,reason=pcall(function()
            if not accessory then
                accessory=source:Clone()assert(accessory,"hat is not cloneable")record.Cloned=true
                for _,object in ipairs(accessory:GetDescendants())do
                    if object:IsA("LuaSourceContainer")or object:IsA("JointInstance")then object:Destroy()
                    elseif object:IsA("BasePart")then object.CanCollide=false object.CanTouch=false object.CanQuery=false object.Anchored=false object.Massless=true end
                end
                accessory.Parent=rig
            end
            record.Accessory=accessory
            local handle=assert(accessory:FindFirstChild("Handle"),"hat has no Handle")
            for _,records in pairs(api.Owners)do for _,existing in ipairs(records)do
                assert(existing.Accessory~=accessory,"this hat is already mounted by another binding; release it first")
            end end
            for _,joint in ipairs(rig:GetDescendants())do
                if joint:IsA("JointInstance")and (joint.Part0==handle or joint.Part1==handle)and joint.Enabled then
                    record.Joints[joint]=joint.Enabled joint.Enabled=false
                end
            end
            local motor=ctx.New("Motor6D")record.Motor=motor
            motor.Name="UhhhhhhHatMount"motor.Part0=target motor.Part1=handle motor.C0=offset motor.C1=CFrame.identity motor.Parent=target
            local m,t=mesh(source)
            local row={Name=source.Name,MeshId=m~=""and m or nil,TextureId=t~=""and t or nil,
                Limb=handle,C0=CFrame.identity,C1=CFrame.identity}
            -- Index wins for identical accessory names where a map is available.
            local occurrence=type(selector)=="table"and selector.Occurrence or 1 local count=0
            for _,mapped in ipairs(ctx.Hat.GetHatMap()or {})do
                if mapped.Name==source.Name and (m==""or id(mapped.MeshId)==m)and(t==""or id(mapped.TextureId)==t)then
                    count+=1 if count==occurrence and mapped.Index then row={Index=mapped.Index,Limb=handle,C0=CFrame.identity,C1=CFrame.identity}break end
                end
            end
            table.insert(ctx.Hat.HatCFrameOverride,row)record.Override=row
        end)
        if not ok then
            if record.Motor then record.Motor:Destroy()end
            if record.Cloned and accessory then accessory:Destroy()else
                for joint,enabled in pairs(record.Joints)do if joint.Parent then joint.Enabled=enabled end end
            end
            error(reason,0)
        end
        api.Owners[owner]=api.Owners[owner]or {}table.insert(api.Owners[owner],record)
        return record.Motor,record.Accessory
    end
    function api.Apply(owner,rig,specs)
        api.Release(owner)
        local ok,reason=pcall(function()
            for _,spec in ipairs(specs or {})do
                local offset=spec.Offset
                if type(offset)=="table"then offset=CFrame.new(table.unpack(offset))end
                api.Mount(owner,rig,spec.Selector or spec.Name,spec.Part or spec.Limb,offset)
            end
        end)
        if not ok then api.Release(owner)error(reason,0)end
    end
    function api.Specs(rig)
        local result={}
        for _,records in pairs(api.Owners)do
            for _,record in ipairs(records)do
                if record.Rig==rig then result=specifications.Merge(result,{record.Spec})end
            end
        end
        return result
    end
    function api.Destroy()
        local owners={}for owner in pairs(api.Owners)do table.insert(owners,owner)end
        for _,owner in ipairs(owners)do api.Release(owner)end
    end
    return api
end
