-- Portable hat mounts for animation files and maker projects. Instance handles
-- stay in the live binding service; project data contains selectors and offsets.
local HatSpec = {}

local function text(value, label, maximum)
    assert(type(value) == "string" and #value > 0 and #value <= maximum,
        "invalid hat " .. label)
    return value
end

local function identity(selector)
    return table.concat({selector.Name or "", selector.MeshId or "",
        selector.TextureId or "", tostring(selector.Occurrence or 1)}, "\0")
end

function HatSpec.Canonical(specifications)
    assert(type(specifications) == "table" and #specifications <= 64,
        "a clip supports at most 64 hat bindings")
    local result, count = {}, 0
    for key in pairs(specifications) do
        assert(type(key) == "number" and key % 1 == 0 and key >= 1 and key <= #specifications,
            "hat bindings must be an array")
        count += 1
    end
    assert(count == #specifications, "hat bindings must not contain gaps")
    for _, specification in ipairs(specifications) do
        assert(type(specification) == "table", "invalid hat binding")
        local source = specification.Selector or specification.Name
        if type(source) == "string" then source = {Name = source} end
        assert(type(source) == "table", "choose a hat by name, mesh or texture")
        local selector = {}
        if source.Name ~= nil then selector.Name = text(source.Name, "name", 256) end
        for _, field in ipairs({"MeshId", "TextureId"}) do
            if source[field] ~= nil then
                local value = text(tostring(source[field]), field, 128):match("%d+")
                assert(value, "hat " .. field .. " needs an asset ID")
                selector[field] = value
            end
        end
        assert(selector.Name or selector.MeshId or selector.TextureId, "hat selector is empty")
        if source.Occurrence ~= nil then
            local occurrence = source.Occurrence
            assert(type(occurrence) == "number" and occurrence % 1 == 0
                and occurrence >= 1 and occurrence <= 64, "invalid hat occurrence")
            selector.Occurrence = occurrence
        end
        local offset = specification.Offset or CFrame.identity
        if typeof(offset) == "CFrame" then offset = {offset:GetComponents()} end
        assert(type(offset) == "table" and #offset == 12, "hat offset needs 12 CFrame components")
        local components = {}
        for index, value in ipairs(offset) do
            assert(type(value) == "number" and value == value and math.abs(value) < 100000,
                "hat offset must be finite")
            components[index] = value
        end
        table.insert(result, {Selector = selector,
            Part = text(specification.Part or specification.Limb, "attachment part", 2048),
            Offset = components})
    end
    return result
end

function HatSpec.Merge(first, second)
    local result, seen = HatSpec.Canonical(first or {}), {}
    for _, spec in ipairs(result) do seen[identity(spec.Selector)] = spec end
    for _, spec in ipairs(HatSpec.Canonical(second or {})) do
        local previous = seen[identity(spec.Selector)]
        if previous then
            assert(previous.Part == spec.Part, "clips mount the same hat to different parts")
            for index, value in ipairs(spec.Offset) do
                assert(math.abs(previous.Offset[index] - value) < 1e-7,
                    "clips use different offsets for the same hat; align their bindings first")
            end
        else
            table.insert(result, spec)
            seen[identity(spec.Selector)] = spec
        end
    end
    return HatSpec.Canonical(result)
end

return HatSpec
