-- Retarget the controller's Neck motion onto the original avatar's mount.
-- Part size is used only to update a saved mount after its joint was removed.
local Alignment = {}
local finite = require(script.Parent.head_tracking).Finite

local function sized(frame, previous, current)
    if not finite(frame) or not previous or not current then return nil end
    local function ratio(a,b)
        if type(a) ~= "number" or type(b) ~= "number" or a <= 0 or b <= 0
            or a ~= a or b ~= b or a == math.huge or b == math.huge then return nil end
        return b / a
    end
    local x,y,z=ratio(previous.X,current.X),ratio(previous.Y,current.Y),ratio(previous.Z,current.Z)
    if not x or not y or not z then return nil end
    local p=frame.Position
    return CFrame.new(p.X*x,p.Y*y,p.Z*z)*frame.Rotation
end

function Alignment.Capture(character, joints, util, previous, requireEnabled)
    local head=character and character:FindFirstChild("Head")
    local torso=character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
    if not head or not torso or not head:IsA("BasePart") or not torso:IsA("BasePart") then
        return nil,"original Head or torso missing"
    end
    local found, count, disabled = nil, 0, false
    for _,joint in ipairs(joints or {}) do
        if joint.Parent then
            local p0,p1=util.GetCharacterJointParts(joint)
            if (p0==torso and p1==head) or (p0==head and p1==torso) then
                count+=1
                local c0,c1=util.GetCharacterJointFrames(joint)
                if requireEnabled and joint.Enabled==false then disabled=true end
                if finite(c0) and finite(c1) then
                    found={BodyMount=p0==torso and c0 or c1,HeadMount=p0==head and c0 or c1,
                        Source=joint.ClassName.." Neck",Joint=joint}
                end
            end
        end
    end
    if count>1 then return nil,"multiple original Neck mounts" end
    if disabled then return nil,"controller Neck is disabled" end
    if count==1 and not found then return nil,"invalid original Neck frames" end
    if not found and not requireEnabled then
        local a,b=torso:FindFirstChild("NeckRigAttachment"),head:FindFirstChild("NeckRigAttachment")
        if a and b and a:IsA("Attachment") and b:IsA("Attachment") and finite(a.CFrame) and finite(b.CFrame) then
            found={BodyMount=a.CFrame,HeadMount=b.CFrame,Source="original NeckRigAttachments"}
        elseif previous and previous.Character==character and previous.Head==head and previous.Torso==torso then
            local bodyMount=sized(previous.BodyMount,previous.TorsoSize,torso.Size)
            local headMount=sized(previous.HeadMount,previous.HeadSize,head.Size)
            if bodyMount and headMount then found={BodyMount=bodyMount,HeadMount=headMount,Source="saved original Neck"} end
        end
    end
    if not found then return nil,"original Neck mount unavailable" end
    found.Character,found.Head,found.Torso=character,head,torso
    found.HeadSize,found.TorsoSize=head.Size,torso.Size
    return found
end

local function scaled(frame, ratio)
    return CFrame.new(frame.Position*ratio)*frame.Rotation
end

function Alignment.Controller(character, joints, util, snapshot, previous)
    -- Validate the live topology first. Disabled/independent Neck poses belong
    -- to ragdoll or VR and must not inherit a cached joint's rest mount.
    local found,why=Alignment.Capture(character,joints,util,nil,true)
    if not found then return nil,why end
    if snapshot and snapshot.Rig==character then
        local record=previous and previous.Snapshot==snapshot and previous.SnapshotRecord
        if not record or record.Instance~=found.Joint then
            -- Do not rescan accessory records on every animation frame.
            for _,candidate in ipairs(snapshot.Joints or {}) do
                if candidate.Instance==found.Joint then record=candidate break end
            end
        end
        if record and record.Instance==found.Joint and record.Part0==found.Joint.Part0 and record.Part1==found.Joint.Part1
            and finite(record.C0) and finite(record.C1) then
            local ok,scale=pcall(character.GetScale,character)
            local ratio=ok and tonumber(scale) and tonumber(snapshot.Scale) and scale/snapshot.Scale
            if ratio and ratio>0 and ratio<math.huge then
                found.BodyMount=scaled(record.Part0==found.Torso and record.C0 or record.C1,ratio)
                found.HeadMount=scaled(record.Part0==found.Head and record.C0 or record.C1,ratio)
                found.Snapshot,found.SnapshotRecord=snapshot,record
                return found
            end
        end
    end
    -- First PD transport can run before ControllerReset captures its baseline.
    -- Keep that initial mount until the snapshot arrives. In particular, do
    -- not mistake a dance's animated C0/C1 for a new rest pose every frame.
    if previous and previous.Character==character and previous.Head==found.Head
        and previous.Torso==found.Torso and previous.Joint==found.Joint then
        local bodyMount=sized(previous.BodyMount,previous.TorsoSize,found.TorsoSize)
        local headMount=sized(previous.HeadMount,previous.HeadSize,found.HeadSize)
        if bodyMount and headMount then found.BodyMount,found.HeadMount=bodyMount,headMount end
    end
    return found
end

function Alignment.Resolve(physical, controller, torsoTarget, controllerTorsoPose, controllerHeadPose, spacingScale)
    if not physical or not controller or not finite(physical.BodyMount) or not finite(physical.HeadMount)
        or not finite(controller.BodyMount) or not finite(controller.HeadMount)
        or not finite(torsoTarget) or not finite(controllerTorsoPose) or not finite(controllerHeadPose) then
        return nil,"invalid Neck alignment inputs"
    end
    -- Compare the live controller pivot with its own rest pivot in body space.
    -- This removes R6's rotated C0/C1 basis before applying motion to R15/custom
    -- mounts; the original Head's actual C1 supplies its centre and orientation.
    local live=controllerTorsoPose:ToObjectSpace(controllerHeadPose)*controller.HeadMount
    local shift=live.Position-controller.BodyMount.Position
    local turn=live.Rotation*controller.BodyMount.Rotation:Inverse()
    spacingScale=tonumber(spacingScale) or 1
    if spacingScale<=0 or spacingScale>=math.huge or spacingScale~=spacingScale then return nil,"invalid character spacing scale" end
    -- Model:ScaleTo scales the controller's rest mounts too. Preserve the
    -- user's character-spacing scale while correcting the avatar proportions.
    local desired=CFrame.new(physical.BodyMount.Position*spacingScale+shift)*turn*physical.BodyMount.Rotation
    local result=torsoTarget*desired*scaled(physical.HeadMount,spacingScale):Inverse()
    if not finite(result) then return nil,"invalid aligned Head pose" end
    return result
end

return Alignment
