    ["UhhhhhhReanim/System/runtime/steve110/main/intro_artwork.lua"] = [=====[
-- Original logo code is copied in vendor/Uhhhhhh.lua.
-- Only flat text layout and scene transitions live here.
local Intro = {}

function Intro.Footer(context)
    local util, new = context.Util, context.Util.Instance
    local footer = new("Frame", context.Parent)
    footer.Name = "IntroFooter"
    footer.AnchorPoint, footer.Position = Vector2.new(.5, 1), UDim2.fromScale(.5, 1)
    footer.BackgroundTransparency, footer.ClipsDescendants = 1, true
    footer.Active, footer.Interactable, footer.ZIndex = false, false, 5
    local function label(name, text, size)
        local row = new("TextLabel", footer)
        row.Name, row.Text = name, text or ""
        row.BackgroundTransparency, row.BorderSizePixel = 1, 0
        row.Font, row.TextSize = context.Font or Enum.Font.Code, size
        row.TextColor3 = context.Color
        row.RichText, row.TextWrapped, row.TextScaled = false, true, false
        row.TextTruncate = Enum.TextTruncate.AtEnd
        row.TextXAlignment, row.TextYAlignment = Enum.TextXAlignment.Center, Enum.TextYAlignment.Center
        row.Active, row.Interactable = false, false
        if util.ForceTextSize then util.ForceTextSize(row) end
        return row
    end
    local title = label("IntroTitle", context.Title, context.TitleSize or 16)
    local caption = label("IntroCaption", context.Credit, context.CaptionSize or 12)
    local busy = false
    local lastSize, lastTitle, lastCaption, lastTitleSize, lastCaptionSize, lastTitleFont, lastCaptionFont
    local function layout()
        if busy or not footer.Parent then return end
        local size = context.Parent.AbsoluteSize
        if size == lastSize and title.Text == lastTitle and caption.Text == lastCaption
            and title.TextSize == lastTitleSize and caption.TextSize == lastCaptionSize
            and title.Font == lastTitleFont and caption.Font == lastCaptionFont then return end
        busy = true
        local padding = math.ceil(math.max(title.TextSize, caption.TextSize) * .6)
        local gap = math.ceil(caption.TextSize * .3)
        local width = math.max(1, size.X - padding * 2)
        local function height(row)
            local bounds = util.GetTextSize(row.Text, row.TextSize, row.Font, Vector2.new(width, math.huge))
            local line = util.GetTextSize("Ag", row.TextSize, row.Font, Vector2.new(math.huge, math.huge)).Y
            return math.ceil(math.min(bounds.Y, math.max(line, row.TextSize) * 2))
        end
        local titleHeight, captionHeight = height(title), height(caption)
        local footerHeight = padding * 2 + titleHeight + gap + captionHeight
        footer.Size = UDim2.new(1, 0, 0, footerHeight)
        title.Position, title.Size = UDim2.fromOffset(padding, padding), UDim2.new(1, -padding * 2, 0, titleHeight)
        caption.Position, caption.Size = UDim2.fromOffset(padding, padding + titleHeight + gap), UDim2.new(1, -padding * 2, 0, captionHeight)
        if context.Artwork then context.Artwork.Size = UDim2.new(1, 0, 0, math.max(0, size.Y - footerHeight)) end
        lastSize, lastTitle, lastCaption = size, title.Text, caption.Text
        lastTitleSize, lastCaptionSize, lastTitleFont, lastCaptionFont = title.TextSize, caption.TextSize, title.Font, caption.Font
        busy = false
    end
    util.LinkDestroyI2C(footer, context.Parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout))
    for _, row in ipairs({title, caption}) do
        for _, property in ipairs({"Text", "TextSize", "Font"}) do
            util.LinkDestroyI2C(footer, row:GetPropertyChangedSignal(property):Connect(layout))
        end
    end
    layout()
    local lastSlot, lastReady
    return function(time, ready, color)
        if title.TextColor3 ~= color then title.TextColor3, caption.TextColor3 = color, color end
        local slot = math.floor(time / 3) % (ready and 4 or 3)
        if slot == lastSlot and ready == lastReady then return end
        lastSlot, lastReady = slot, ready
        if slot == 0 then caption.Text = context.Credit
        elseif slot == 1 then caption.Text = context.Discord
        elseif slot == 2 then caption.Text = ready and "Click, tap or press Enter to start!" or "Loading..."
        elseif type(context.Quotes) == "table" and #context.Quotes > 0 then caption.Text = context.Quotes[math.random(1, #context.Quotes)]
        else caption.Text = context.Credit end
        -- Preserve immediate geometry with deferred property signals; their
        -- later layout call sees the same inputs and does no repeated measure.
        layout()
    end
end

function Intro.Text(context)
    local Util = context.Util
    local canvas = Util.Instance("ScrollingFrame", context.Parent)
    canvas.Name, canvas.LayoutOrder = "AsciiArtCanvas", #context.Parent:GetChildren()
    canvas.BackgroundTransparency, canvas.BorderSizePixel = 1, 0
    canvas.ClipsDescendants = true
    canvas.ScrollingDirection = Enum.ScrollingDirection.X
    canvas.AutomaticCanvasSize = Enum.AutomaticSize.None
    local text = Util.Instance("TextLabel", canvas)
    text.Name, text.BackgroundTransparency, text.BorderSizePixel = "AsciiArt", 1, 0
    text.Font, text.TextSize = context.Font or Enum.Font.Code, context.Size or 12
    text.TextColor3 = Color3.new(1, 1, 1)
    text.RichText, text.TextWrapped, text.TextScaled = false, false, false
    text.TextXAlignment, text.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
    text.Active, text.Interactable, text.Text = true, true, ""
    if context.Theme then context.Theme.ApplyLabel(text) end
    local busy = false
    local function measure()
        if busy or not text.Parent then return end
        busy = true
        local bounds = Util.GetTextSize(text.Text, text.TextSize, text.Font, Vector2.new(math.huge, math.huge))
        local width, height = math.ceil(bounds.X) + 4, math.ceil(bounds.Y) + 6
        local overflow = width > canvas.AbsoluteSize.X
        -- Borderless artwork uses natural dimensions, outside control padding.
        -- Long lines can be panned horizontally; every line contributes height.
        canvas.Size = UDim2.new(1, 10, 0, height + (overflow and 4 or 0))
        canvas.CanvasSize = UDim2.fromOffset(width, height)
        canvas.ScrollBarThickness = overflow and 2 or 0
        text.Size = UDim2.fromOffset(width, height)
        text.Position = UDim2.fromOffset(math.max(0, (canvas.AbsoluteSize.X - width) / 2), 0)
        busy = false
    end
    for _, property in ipairs({"Text", "TextSize", "Font"}) do
        Util.LinkDestroyI2C(canvas, text:GetPropertyChangedSignal(property):Connect(measure))
    end
    Util.LinkDestroyI2C(canvas, canvas:GetPropertyChangedSignal("AbsoluteSize"):Connect(measure))
    measure()
    return text
end

function Intro.new(context)
    local intro, workspace, chrome = context.Intro, context.Workspace, context.Chrome
    local scene = {Busy = false, State = intro.Visible and "scene" or "workspace"}
    local serial, tween, completion, headerCompletion = 0, nil, nil, nil
    intro.Parent = context.Parent
    intro.BackgroundTransparency, intro.ZIndex = 0, 20
    intro.Size = UDim2.fromScale(1, 1)
    local function animate(entering)
        if scene.Busy or not intro.Parent then return false end
        if entering and scene.State == "scene" or not entering and scene.State == "workspace" then return false end
        serial += 1
        local ticket = serial
        scene.Busy, scene.State = true, entering and "entering" or "leaving"
        intro.Interactable = false
        local headerTween
        if entering then
            -- Keep the current page until the opaque scene covers it.
            if workspace.SaveCurrentScroll then workspace.SaveCurrentScroll() end
            if workspace.Bar then workspace.Bar.Interactable = false end
            if workspace.CurrentPage then workspace.CurrentPage.Interactable = false end
            intro.Position, intro.Visible = UDim2.new(-.5, -2, .5, 0), true
        else
            -- Restore the SAME retained page underneath the opaque scene
            -- before its first leaving frame or the header geometry changes.
            workspace.SetEnabled(true)
            headerTween = chrome.Wake()
        end
        local function play()
        if ticket ~= serial or not intro.Parent then return end
        if not entering and workspace.RestoreCurrentScroll then workspace.RestoreCurrentScroll() end
        tween = context.TweenService:Create(intro,
