-- One entrance action for pointer, keyboard and gamepad. Gameplay input is
-- untouched after the intro closes, while typing, or before loading finishes.
return function(ctx)
    local connections,stopped={},false
    local function enter()
        if stopped or not ctx.Frame.Parent or not ctx.Visible(ctx.Frame)or not ctx.Ready()then return false end
        return ctx.Activate()
    end
    connections[#connections+1]=ctx.Frame.InputEnded:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then enter()end
    end)
    connections[#connections+1]=ctx.Input.InputBegan:Connect(function(input,processed)
        if processed or ctx.Input:GetFocusedTextBox()then return end
        local key=input.KeyCode
        if key==Enum.KeyCode.Return or key==Enum.KeyCode.Space or key==Enum.KeyCode.ButtonA then enter()end
    end)
    local function destroy()
        if stopped then return end stopped=true
        for _,connection in ipairs(connections)do connection:Disconnect()end
        table.clear(connections)
    end
    ctx.Frame.Destroying:Once(destroy)
    return {Destroy=destroy}
end
