    ["UhhhhhhReanim/System/runtime/steve110/main/loading_budget.lua"] = [=====[
-- Nooby-style loading profiles with bounded work between yields. Never starts
-- a parallel copy of the module runtime or changes a playing reanimator.
return function(ctx)
    local api={Modes={"Balanced","Slow","Fast"},Count=0,Yields=0}
    local clock=ctx.Clock or os.clock local wait=ctx.Wait or task.wait
    local settings=ctx.Saved
    if not table.find(api.Modes,settings.ModuleLoading)then
        settings.ModuleLoading=settings.ModuleLoadMode==4 and "Slow"or "Balanced"
    end
    function api.Reset()api.Count,api.Yields=0,0 api.Started=clock()end
    function api.Checkpoint(force)
        api.Count+=1
        local mode=settings.ModuleLoading
        local budget=mode=="Slow"and .001 or mode=="Fast"and .008 or .003
        local limit=mode=="Slow"and 1 or mode=="Fast"and 24 or 6
        if force or api.Count>=limit or clock()-(api.Started or 0)>=budget then
            wait(mode=="Slow"and .04 or nil)
            api.Yields+=1 api.Count=0 api.Started=clock()
            return true
        end
        return false
    end
    api.Reset()return api
end
