    state=function(p,refresh)
        local s=states[p.Id]
        if s and not refresh then return s end
        local revision,body,reason
        local ok,err=pcall(function()
            local ref=encode(p.Branch or "main"):gsub("/","%%2F")
            local metadata,failure=deps.Fetch("https://api.github.com/repos/"..p.Repo.."/commits/"..ref,nil,1)
            assert(metadata,failure)
