            assert(type(body)=="string"and (#parse(p,revision,body)>0 or body:match("^%s*$")),failure or "invalid catalog")
        end)
        if ok then
            s={Revision=revision,List=body,Paths=s and s.Revision==revision and s.Paths or nil,Fresh=true}
        else
            local cached=deps.Saved and deps.Saved.MarketProviderCache and deps.Saved.MarketProviderCache[p.Id]
            if not s and type(cached)=="table"and cached.Fetched==true and cached.Schema==2
                and type(cached.Revision)=="string"and #cached.Revision==40
                and cached.Revision:match("^%x+$")and type(cached.List)=="string"then
                s={Revision=cached.Revision,List=cached.List}
            end
            s=s or {List=""}
            s.Fresh=false
            s.Error=tostring(err)
        end
        states[p.Id]=s
        if ok and deps.Saved then
            deps.Saved.MarketProviderCache=deps.Saved.MarketProviderCache or {}
            deps.Saved.MarketProviderCache[p.Id]={Revision=s.Revision,List=s.List,Fetched=true,Schema=2}
        end
