                end
            end
        end
        return catalog,names,byFile
    end
    function api.LegacyReplacement(filename)
        local p=Providers[1]
        local s=states[p.Id]
        for _,item in ipairs(parse(p,s and s.Revision or p.Revision,s and s.List or "")) do
            if item.Type=="file" and item.Path:gsub("/",".")==filename then return item.File end
        end
        return nil
    end
    function api.Status()
        local parts={}
        for _,p in ipairs(Providers) do
            local s=states[p.Id]
            table.insert(parts,p.Id..(not enabled(p)and ": disabled" or s and s.Fresh and ": current" or s and s.Revision and ": cached (refresh to retry)" or ": unavailable (open or refresh to retry)"))
        end
