-- Install once, report real completion, and apply the finished batch once.
return function(deps)
    local installer={States={},Pending=0,Ready={},Disposed=false}
    local scheduled,applying=false,false
    local function publish(state)
        for _,changed in pairs(state.Listeners) do pcall(changed,state) end
    end
    function installer.State(item)
        local state=installer.States[item.File]
        if not state then
            state={Item=item,Phase=deps.IsInstalled(item) and "ready" or "available",Listeners={}}
            installer.States[item.File]=state
        end
        return state
    end
    function installer.Watch(item,owner,changed)
        local state=installer.State(item)
        state.Listeners[owner]=changed changed(state)
        return function()state.Listeners[owner]=nil end
    end
    function installer.Caption(state)
        if state.Phase=="installing" then return "Installing..." end
        if state.Phase=="loading" then return "Loading add-ons..." end
        if state.Phase=="failed" then return "Retry install" end
        if state.Phase=="ready" then return "Update add-on" end
        return state.Item.Type=="folder" and "Install pack" or "Install add-on"
    end
    local function applyBatch()
        if scheduled or applying or installer.Pending>0 or #installer.Ready==0 or installer.Disposed then return end
        scheduled=true
        deps.Task.defer(function()
            scheduled=false
            if installer.Disposed or installer.Pending>0 then return end
            local ready=installer.Ready installer.Ready={}
            applying=true
            local ok,reason=pcall(deps.Apply)
            if installer.Disposed then applying=false return end
            local failures=0
            for _,state in ipairs(ready) do
                local loaded,why=ok,reason
                if ok and deps.CheckLoaded then
                    local checked,result,detail=pcall(deps.CheckLoaded,state.Records)
                    loaded,why=checked and result,checked and detail or result
                end
                state.Phase=loaded and "ready" or "failed"
                if not loaded then failures+=1 end
                state.Message=loaded and "Installed. Available in Dances or Movesets."
                    or ("Downloaded, but could not load: "..tostring(why):sub(1,180))
                publish(state)
            end
            if ok and failures==0 then deps.Notify("Add-ons installed and loaded")
            elseif ok then deps.Notify("Downloads finished; "..failures.." add-on(s) could not load. Open the add-on for details.")
            else deps.Notify("Add-ons downloaded; loading failed: "..tostring(reason):sub(1,160)) end
            applying=false
            applyBatch()
        end)
    end
    function installer.Install(item,force,targetPath)
        local state=installer.State(item)
        if installer.Disposed or state.Phase=="installing" or state.Phase=="loading" then return state end
        state.Phase,state.Done,state.Failed,state.Error="installing",0,0,nil
        state.Message="Preparing download..." installer.Pending+=1 publish(state)
        deps.Task.spawn(function()
            local finished=false
            local function finish()
                if finished or installer.Disposed then return end finished=true
                installer.Pending-=1
                if state.Failed>0 then
                    state.Phase="failed"
                    state.Message="Install failed: "..tostring(state.Error):sub(1,200)..". Select Retry install."
                    deps.Notify(item.Name..": "..state.Message)
                else
                    local ok,why=pcall(deps.Commit,item)
                    if ok then
                        state.Phase="loading" state.Message="Download complete. Loading add-ons..."
                        table.insert(installer.Ready,state)
                    else state.Phase="failed" state.Message="Could not finish install: "..tostring(why):sub(1,180) end
                end
                publish(state) applyBatch()
            end
            local ok,records=pcall(deps.Prepare,item,targetPath)
            if not ok or type(records)~="table" or #records==0 then
                state.Failed,state.Error=1,ok and "No installable modules found" or records
                finish() return
            end
            state.Records,state.Total=records,#records
            state.Message="Installing 0 / "..#records.." files..." publish(state)
            for _,record in ipairs(records) do
                local completed=false
                local function done(success,why)
                    if completed or installer.Disposed then return end completed=true
                    state.Done+=1
                    if not success then state.Failed+=1 state.Error=why or "Download failed" end
                    state.Message=string.format("Installing %d / %d files...",state.Done,state.Total)
                    publish(state)
                    if state.Done==state.Total then finish() end
                end
                local queued,why=pcall(deps.Download,record,force,done)
                if not queued then done(false,why) end
            end
        end)
        return state
    end
    function installer.Dispose()
        installer.Disposed=true installer.Ready={}
        for _,state in pairs(installer.States) do table.clear(state.Listeners) end
    end
    return installer
end
