-- Repository media manifests establish identity; filenames alone do not establish mirrors.
local Recovery={}
local deps,manifests,urls,attempts,choices={},{},{},{},{}
local links={}
local function commit(value)
    return type(value)=="string"and #value==40 and value:match("^%x+$")~=nil
end
local function validProvider(provider)
    return type(provider)=="table"and type(provider.Id)=="string"and provider.Id~=""
        and type(provider.Repo)=="string"and provider.Repo:match("^[%w_.%-]+/[%w_.%-]+$")~=nil
        and type(provider.Prefix)=="string"
end
local function safe(path)
    if type(path)~="string" or path=="" or path:find("[@%c\\]") or path:sub(1,1)=="/" then return false end
    for segment in path:gmatch("[^/]+") do if segment=="." or segment==".." then return false end end
    return true
end
local function encode(path)
    return (path:gsub("[^%w%-%._~/]",function(c)return string.format("%%%02X",c:byte())end))
end
local function logical(path)
    local name=path:match("[^/]+$")
    -- The store uploader prefixes media with an eight-character token.
    if path:find("/assets/",1,true) and name:match("^%w%w%w%w%w%w%w%w_") then name=name:sub(10) end
    return name:lower()
end
function Recovery.Configure(options)
    for key,value in pairs(options or {}) do deps[key]=value end
    choices={}
end
function Recovery.Register(provider,revision,tree)
    if not validProvider(provider)then return end
    if type(tree)~="table" or tree.truncated or type(tree.tree)~="table" then return end
    if not commit(revision)then return end
    local key=provider.Id.."/"..revision
    if manifests[key] then return manifests[key] end
    local manifest={Provider=provider,Packs={},Paths={}}
    for _,entry in ipairs(tree.tree) do
        local path=entry.path
        local extension=type(path)=="string" and path:lower():match("%.([^./]+)$")
        local media=extension=="anim" or extension=="mp3" or extension=="ogg" or extension=="wav"
            or extension=="png" or extension=="jpg" or extension=="jpeg" or extension=="webm" or extension=="mp4"
        if entry.type=="blob" and media and safe(path) and path:sub(1,#provider.Prefix)==provider.Prefix
            and type(entry.sha)=="string" and #entry.sha==40 and entry.sha:match("^%x+$")
            and type(entry.size)=="number" and entry.size>0 and entry.size<=64000000 then
            local relative=path:sub(#provider.Prefix+1)
            local pack=relative:match("^([^/]+)/")
            if pack then
                local group=manifest.Packs[pack] or {Names={},Hashes={}}
                manifest.Packs[pack]=group
                local name=logical(path)
                local asset={SHA=entry.sha,Size=entry.size,Repo=provider.Repo}
                asset.URL="https://raw.githubusercontent.com/"..asset.Repo.."/"..revision.."/"..encode(path)
                manifest.Paths[relative:lower()]=manifest.Paths[relative:lower()] or {}
                table.insert(manifest.Paths[relative:lower()],asset)
                group.Names[name]=group.Names[name] or {}
                table.insert(group.Names[name],asset)
                group.Hashes[name.."/"..entry.sha]=extension=="anim" and "anim" or "media"
                urls[asset.URL]=asset
            end
        end
    end
    manifests[key]=manifest
    choices={}
    links={}
    return manifest
end
local function manifest(provider,revision)
    if not validProvider(provider)then return end
    if revision==nil then
        revision=provider.Revision
        if not commit(revision)and type(deps.ResolveRevision)=="function"then
            local ok,resolved=pcall(deps.ResolveRevision,provider)
            revision=ok and resolved or nil
        end
    end
    -- Saved packs can load before the catalog has fetched any peer commits.
    -- An unavailable/unpinned provider is a recovery miss, not a Lua error.
    if not commit(revision)then return end
    local key=provider.Id.."/"..revision
    if manifests[key] then return manifests[key] end
    if not deps.Fetch or not deps.Decode or (attempts[key] or 0)>os.clock() then return end
    attempts[key]=os.clock()+60
    local ok,result=pcall(function()
        local body=assert(deps.Fetch("https://api.github.com/repos/"..provider.Repo.."/git/trees/"..revision.."?recursive=1",nil,1))
        local tree=deps.Decode(body)
        assert(type(tree.tree)=="table"and not tree.truncated,"incomplete repository tree")
        return Recovery.Register(provider,revision,tree)
    end)
    if ok then return result end
end
function Recovery.Pack(context)
    if type(context)~="table"then return end
    local provider,pack=tostring(context.SourceLabel or ""):match("Market/([^/]+)/([^/]+)/")
    if provider==context.Provider then return pack end
    local found
    for _,reference in pairs(type(context.Assets)=="table"and context.Assets or {}) do
        if type(reference)=="string" then
            local p,name=reference:match("^Market/([^/]+)/([^/]+)/")
            if p==context.Provider then
                if found and found~=name then return end
                found=name
            end
        end
    end
    return found
end
local function unique(candidates)
    local found
    for _,asset in ipairs(candidates or {}) do
        if found and found.SHA~=asset.SHA then return nil,"ambiguous" end
        found=asset
    end
    return found
end
function Recovery.Resolve(context,filename)
    local pack=Recovery.Pack(context)
    if not pack or not safe(filename) then return end
    local sources=deps.Providers or {}
    local own
    for _,provider in ipairs(sources) do
        if provider.Id==context.Provider then own=manifest(provider,context.Revision) break end
    end
    local group=own and own.Packs[pack]
    local name=filename:match("[^/]+$"):lower()
    local prefix="Market/"..context.Provider.."/"..pack.."/Recovered/"
    if group then
        local exact,reason=unique(own.Paths[(pack.."/"..(context.Directory and context.Directory.."/" or "")..filename):lower()])
        if reason then return nil,reason end
        if exact then return prefix..filename.."@"..exact.URL end
        -- Explicit relative paths do not become unrelated basename requests.
        if filename:find("/",1,true) then return prefix..filename.."@LOCAL/"..filename end
        local direct,why=unique(group.Names[name])
        if why then return nil,why end
        if direct then return prefix..filename.."@"..direct.URL end
        -- Two distinct named shared blobs, including an animation, are required.
        local key=context.Provider.."/"..(context.Revision or "").."/"..pack.."/"..name
        if choices[key] then return choices[key] end
        local candidates={}
        for _,provider in ipairs(sources) do
            if provider.Id~=context.Provider then
                local function collect(target)
                    if not target then return end
                    links[group]=links[group] or {}
                    local peers=links[group][target]
                    if not peers then
                        peers={}
                        for _,other in pairs(target.Packs) do
                            local matches,animation=0,false
                            for hash,kind in pairs(group.Hashes) do
                                if other.Hashes[hash] then matches+=1 animation=animation or kind=="anim" end
                            end
                            if matches>=2 and animation then table.insert(peers,other) end
                        end
                        links[group][target]=peers
                    end
                    for _,other in ipairs(peers) do
                        for _,asset in ipairs(other.Names[name] or {}) do table.insert(candidates,asset) end
                    end
                end
                for _,target in pairs(manifests) do
                    if target.Provider.Id==provider.Id then collect(target) end
                end
                if #candidates==0 then
                    collect(manifest(provider))
                end
            end
        end
        local asset,why=unique(candidates)
        if why then return nil,why end
        if asset then
            local reference=prefix..filename.."@"..asset.URL
            choices[key]=reference
            return reference
        end
    end
    -- Cache misses do not invent URLs or optionality for required dependencies.
    return prefix..filename.."@LOCAL/"..filename
end
function Recovery.Blob(url)
    local asset=urls[url]
    if asset then return asset.SHA,asset.Size,asset.Repo end
end
return Recovery
