-- Fit the native menu to the viewport; the independent editor keeps its size.
local Bounds=require(script.Parent.dropdown_bounds)
return function(ctx)
    local api={Names={"Compact","Comfortable","Tall"}}
    local sizes={{360,281},{400,480},{420,620}}
    local selected=table.find(api.Names,ctx.Saved.MenuSize)or 2
    ctx.Saved.MenuSize=api.Names[selected]
    function api.Select(index)
        assert(sizes[index],"unknown menu size")selected=index ctx.Saved.MenuSize=api.Names[index]
    end
    function api.Index()return selected end
    function api.Size()
        local screen=ctx.Screen()local wanted=sizes[selected]
        -- Consume the normal margins before allowing the preferred minimum to
        -- overflow a smaller viewport (e.g. a phone in landscape).
        local width=math.max(1,screen.X-math.min(20,math.max(0,screen.X-180)))
        local height=math.max(1,screen.Y-math.min(60,math.max(0,screen.Y-140)))
        return UDim2.fromOffset(math.min(wanted[1],width),math.min(wanted[2],height))
    end
    function api.Fit(window)
        local size=api.Size()
        local main=window.Main
        local transitioning=window.IsTransitioning and window.IsTransitioning()
        -- Native SetSize writes Main.Size before checking Minimized. Preserve
        -- the collapsed strip and do not enter its yielding tween wait during
        -- a transition. Restore reads Window.Size; the next settled fit also
        -- repairs a tween whose goal was captured before the viewport changed.
        local staleMain=main and main.Size and main.Size~=size
        if window.Size~=size or not window.Minimized and not transitioning and staleMain then
            if window.Minimized or transitioning then window.Size=size else window.SetSize(size)end
        end
        if not main or not main.Position then return end
        local screen=ctx.Screen()
        local parent=main.Parent
        local parentSize=parent and parent.AbsoluteSize or screen
        if not parentSize or parentSize.X<=0 or parentSize.Y<=0 then parentSize=screen end
        local origin=Vector2.zero
        if parent and parent:IsA("GuiObject")then
            local root=main:FindFirstAncestorWhichIsA("ScreenGui")
            origin=parent.AbsolutePosition-(root and root.AbsolutePosition or Vector2.zero)
        end
        local anchor=main.AnchorPoint or Vector2.new(.5,.5)
        local restoreSize=Vector2.new(parentSize.X*size.X.Scale+size.X.Offset,parentSize.Y*size.Y.Scale+size.Y.Offset)
        local closedSize=Vector2.new(math.min(window.MinimizedSizeX or 112,screen.X),math.min(30,screen.Y))
        if window.PositionOpen then window.PositionOpen=Bounds.Position(screen,window.PositionOpen,restoreSize,anchor,parentSize,origin)end
        if window.PositionClosed then window.PositionClosed=Bounds.Position(screen,window.PositionClosed,closedSize,anchor,parentSize,origin)end
        if transitioning then return end
        local currentSize=window.Minimized and main.AbsoluteSize or restoreSize
        if not currentSize then currentSize=closedSize end
        local fitted=Bounds.Position(screen,main.Position,currentSize,anchor,parentSize,origin)
        if fitted~=main.Position then main.Position=fitted end
    end
    return api
end
