    ["UhhhhhhReanim/System/runtime/steve110/main/module_playback_state.lua"] = [=====[
-- Presentation state for the current selection. "Playing" means the caller's
-- local module-init flag, not server replication or successful physical motion.
local State = {}

local function short(value, maximum)
    local text = tostring(value or "")
    text = text:match("[^\r\n]+") or ""
    text = text:gsub("[%z\1-\8\11\12\14-\31\127]", ""):gsub("\t", " ")
    if #text <= maximum then return text end
    local last = maximum
    while last > 0 do
        local nextByte = text:byte(last + 1)
        if not nextByte or nextByte < 128 or nextByte >= 192 then break end
        last -= 1
    end
    return text:sub(1, last) .. "…"
end

function State.Read(module, context)
    local m = type(module) == "table" and module or {}
    local ctx = context or {}
    local selected = ctx.Selected == true
    local moveset = m.ModuleType == "MOVESET"
    local name = short(m.Name, 80)
    if name == "" then name = moveset and "Moveset" or "Dance" end
    local failure = m._UhhhhhhRuntimeFailure or m._UhhhhhhAssetFailure
    if not failure and type(m._UhhhhhhMissingAssets) == "table" and #m._UhhhhhhMissingAssets > 0 then
        failure = "Missing files: " .. table.concat(m._UhhhhhhMissingAssets, ", ")
    end
    failure = failure and short(failure, 240) or nil
    if failure == "" then failure = "The module could not start." end

    local status, label, action, running
    if failure then
        status, label = "Failed", "Failed: " .. name
        action = moveset and "Retry Moveset" or "Retry Dance"
        running = false
    elseif not selected then
        status, label = "Idle", "Not selected: " .. name
        action = moveset and "Use Moveset" or "Play Dance"
        running = false
    elseif not ctx.Controller then
        status, label = "Queued", "Reanimate first: " .. name .. " is selected"
        action = moveset and "* SELECTED *" or "Stop Dance"
        running = false
    elseif ctx.Playing == true then
        status, label = "Playing", "Playing: " .. name
        action = moveset and "* ACTIVE *" or "Stop Dance"
        running = true
    else
        status = "Loading"
        label = (ctx.Loading == true and "Loading assets: " or "Starting: ") .. name
        action = moveset and "* SELECTED *" or "Stop Dance"
        running = false
    end
    return {Status = status, Label = label, ActionText = action, Running = running,
        Selected = selected, Failure = failure}
end

return State
