-- Nooby-style isolated module previews. Only authored animation data is played;
-- the module's Init/Update callbacks and the real character are never invoked.
return function(ctx)
    local api={Serial=0,LoadSerial=0,Loop=true,Rotate=true}
    function api.Stop()
        api.Serial+=1 api.LoadSerial+=1
        if api.Connection then api.Connection:Disconnect()api.Connection=nil end
        if api.Animator then api.Animator:Destroy(false)api.Animator=nil end
        if api.Model then api.Model:Destroy()api.Model=nil end
        if api.Host then api.Host:Destroy()api.Host=nil end
        if api.Page then api.Page:Destroy()api.Page=nil end
    end
    function api.Open(module,parent)
        api.Stop()
        local ticket=api.Serial local UI=ctx.UI
        local origin=parent
        local page=UI.CreatePage()page.Name="AnimationPreview"api.Page=page
        UI.CreateButton(page,"< Hurry back",20).Activated:Connect(function()
            UI.Workspace.Back(page,origin,true)api.Stop()
        end)
        UI.CreateText(page,module.Name.." · Preview",18,Enum.TextXAlignment.Left)
        UI.Workspace.Open(page,origin)
        parent=page
        origin.Destroying:Once(function()if ticket==api.Serial then api.Stop()end end)
        page.Destroying:Once(function()if ticket==api.Serial then api.Stop()end end)
        local host=UI.CreateCanvas(parent)api.Host=host host.Name="IsolatedAnimationPreview"
        local viewport=ctx.New("ViewportFrame",host)
        viewport.Size=UDim2.new(1,0,0,200)viewport.BackgroundTransparency=.85 viewport.BorderSizePixel=0
        viewport.Ambient=Color3.new(.7,.7,.7)viewport.LightColor=Color3.new(1,1,1)
        viewport.LayoutOrder=-1
        if ctx.Theme then ctx.Theme.ApplyFrame(viewport,{Depthed=true})end
        local world=ctx.New("WorldModel",viewport)
        local camera=ctx.New("Camera",viewport)camera.FieldOfView=45 viewport.CurrentCamera=camera
        local status=UI.CreateText(host,"Choose a clip and press Play. Preview loads on demand.",11,Enum.TextXAlignment.Left)status.RichText=false
        local sources=ctx.Sources()
        local rows=sources.List(module)local index=1 local labels={}
        for _,row in ipairs(rows)do table.insert(labels,row.Name)end
        local editorTrack,play,loading
        UI.CreateButton(parent,"Open in animation editor >",18).Activated:Connect(function()
            if ctx.Edit then ctx.Edit(editorTrack,module)end
        end)
        local function prepareRig(model)
            assert(model,"no preview rig is available")
            for _,object in ipairs(model:GetDescendants())do
                if object:IsA("LuaSourceContainer")or object:IsA("Sound")or object:IsA("Tool")then object:Destroy()
                elseif object:IsA("BasePart")then
                    object.CanCollide=false object.CanTouch=false object.CanQuery=false object.Anchored=true object.LocalTransparencyModifier=0
                    object.Transparency=object.Name=="HumanoidRootPart"and 1 or 0
                elseif object:IsA("Motor6D")then object.Enabled=true
