            local humanoid=model:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.RigType==Enum.HumanoidRigType.R15 then pcall(humanoid.BuildRigFromAttachments,humanoid)end
            local root=model:FindFirstChild("HumanoidRootPart")or model.PrimaryPart
            if root then root.Anchored=true end
            model:PivotTo(CFrame.identity)
            return root
        end
        if #rows==0 then
            local ok,model=pcall(ctx.Clone,nil)
            if ok and model then
                api.Model=model
                local prepared=pcall(prepareRig,model)
                if prepared then
                    local box,size=model:GetBoundingBox()local angle=0
                    api.Connection=ctx.Signal:Connect(function(dt)
                        if ticket~=api.Serial or not host.Parent or ctx.Visible and not ctx.Visible(host)then return end
                        if api.Rotate then angle+=dt*.4 end
                        local dimensions=viewport.AbsoluteSize
                        local aspect=math.max(.2,dimensions.X/math.max(1,dimensions.Y))
                        local radius=math.max(size.Y/2,size.X/(2*aspect))/math.tan(math.rad(camera.FieldOfView)/2)+size.Z/2
                        radius=math.max(2,radius*1.15)
                        camera.CFrame=CFrame.lookAt(box.Position+Vector3.new(math.sin(angle)*radius,size.Y*.08,math.cos(angle)*radius),box.Position)
                    end)
                else model:Destroy()api.Model=nil end
            end
            status.Text="No authored clip is exposed. Open the editor and use Record for this module's procedural motion."
            return page
        end
        UI.CreateDropdown(host,"Preview clip",labels,1).Changed:Connect(function(value)
            index=value api.LoadSerial+=1 loading=false if play then play()end
        end)
        local paused,elapsed,angle,loaded=false,0,0,nil
        loading=false
        play=function()
            if loading then return end
            if loaded==rows[index]and api.Animator then paused=not paused return end
