        end
        UI.CreateButton(host,"Play / pause preview",17).Activated:Connect(play)
        UI.CreateButton(host,"Stop preview",17).Activated:Connect(function()paused=true elapsed=0 if api.Animator then api.Animator:Step(0)end end)
        UI.CreateButton(host,"Next preview clip",17).Activated:Connect(function()index=index%#rows+1 play()end)
        UI.CreateSwitch(host,"Loop preview",api.Loop).Changed:Connect(function(on)api.Loop=on end)
        UI.CreateSwitch(host,"Rotate preview",api.Rotate).Changed:Connect(function(on)api.Rotate=on end)
        parent.Destroying:Once(function()if ticket==api.Serial then api.Stop()end end)
        play()
        return page
    end
    api.Destroy=api.Stop return api
