-- Shared native sound transition. Repository downloads finish before the
-- current sound is touched; generation checks prevent cancelled work resuming.
return function(ctx)
    local player,sound=ctx.Player,ctx.Sound
    local tasks=ctx.Task or task
    player.Serial=0 player.Switching=false
    local function alive(ticket)
        return ticket==player.Serial and (not ctx.Alive or ctx.Alive())
    end
    function player.CancelPending() player.Serial+=1 player.Switching=false player.PendingRepositoryRow=nil end
    function player.RebuildRepositoryRows()
        local old=player.Database[player.LastMusic or 0]
        local rows=table.clone(player.NativeDatabase)
        for _,row in ipairs(ctx.Repositories.DatabaseRows()) do table.insert(rows,row) end
        player.Database=rows player.LastMusic=nil
        for i,row in ipairs(rows) do if old and row[1]==old[1] then player.LastMusic=i break end end
        if player.PendingRepositoryRow and not ctx.Repositories.CanUse(player.PendingRepositoryRow) then player.CancelPending() end
        local playing=player.CurrentRepositoryRow or (old and old.RepositoryTrack)
        if playing and not ctx.Repositories.SourceEnabled(playing) then
            player.CancelPending() sound:Stop() player.CurrentRepositoryRow=nil
            local ticket=player.Serial
            tasks.defer(function()if alive(ticket) then player.PlayMusic()end end)
        end
    end
    return function(index,allowRemote)
        if player.Switching then return false,"music is already loading" end
        player.Serial+=1 local ticket=player.Serial player.Switching=true
        local ok,success,reason=pcall(function()
            local candidates={}
            if index~=nil then
                assert(type(index)=="number" and index%1==0 and player.Database[index],"choose an available song")
                candidates[1]=index
            else
                for i,entry in ipairs(player.Database) do
                    local exists,value=pcall(ctx.IsFile,entry[1])
                    if i~=player.LastMusic and ((exists and value) or (allowRemote and entry.RepositoryTrack)) then table.insert(candidates,i) end
                end
                if #candidates==0 and player.LastMusic then candidates[1]=player.LastMusic end
            end
            local selected,id,name,lastError
            local remoteAttempts=0
            while #candidates>0 and alive(ticket) do
                local at=index and 1 or (ctx.Random or math.random)(#candidates)
                local candidate=table.remove(candidates,at)
                local entry=player.Database[candidate]
                if entry then
                    local prepared,why=true,nil
                    if entry.RepositoryTrack then
                        player.PendingRepositoryRow=entry.RepositoryTrack
                        remoteAttempts+=1
                        if remoteAttempts>3 and not index then continue end
                        prepared,why=ctx.Repositories.Prepare(entry.RepositoryTrack,function()return not alive(ticket)end)
                    end
                    if not alive(ticket) then return false,"music selection cancelled" end
                    if prepared then
                        local registered,value=pcall(ctx.Asset,entry[1])
                        if registered and type(value)=="string" and value~="" then selected,id,name=candidate,value,entry[2] break end
                        why=registered and "audio registration unavailable" or tostring(value)
                    end
                    lastError=why
                end
            end
            if not alive(ticket) then return false,"music selection cancelled" end
            if not id then return false,lastError or "song is still caching or unavailable" end
            local old={Id=sound.SoundId,Name=sound.Name,Time=sound.TimePosition,Playing=sound.IsPlaying,Looped=sound.Looped}
            local swapped,failure=pcall(function()
                sound:Stop() sound.SoundId=id sound.Name=name sound.Looped=false
                tasks.wait()
                if not alive(ticket) then return end
                sound.TimePosition=0 sound:Play()
            end)
            if not alive(ticket) then return false,"music selection cancelled" end
            if not swapped then
                pcall(function()
                    sound.SoundId=old.Id sound.Name=old.Name sound.Looped=old.Looped sound.TimePosition=old.Time
                    if old.Playing then sound:Play() else sound:Stop() end
                end)
                return false,tostring(failure)
            end
            player.LastMusic=selected
            player.CurrentRepositoryRow=player.Database[selected].RepositoryTrack
            if player.OnSongChanged then pcall(player.OnSongChanged,old.Id,player.Database[selected][1])end
            return true
        end)
        if ticket==player.Serial then player.Switching=false player.PendingRepositoryRow=nil end
        if not ok then return false,tostring(success) end
        return success,reason
    end
end
