-- Native Steve controls and one scrollable source page beside UI Music.
return function(ctx)
    local UI,api=ctx.UI,ctx.Catalog
    local view={}
    local page=UI.CreatePage()
    local pane=UI.CreateCanvas(page)
    local selected
    local function notify(message)ctx.Notify(tostring(message))end
    local function plain(parent,value,size)
        local label=UI.CreateText(parent,value,size or 12,Enum.TextXAlignment.Left)
        label.RichText=false return label
    end
    local function escaped(value)return (value:gsub("&","&amp;"):gsub("<","&lt;"):gsub(">","&gt;"))end
    local function clear()ctx.Clear(pane)end
    local function button(label,fn)
        local b=UI.CreateButton(pane,label,18)b.Activated:Connect(fn)return b
    end
    local function openPage()
        UI.Workspace.Open(page,ctx.Main)
    end
    local function run(fn)
        local ok,reason=pcall(fn)
        if not ok then notify(reason) end
    end
    local show,add
    add=function()
        clear() button("&lt; Back to music sources",show)
        plain(pane,"add repository music",16)
        local repo=UI.CreateTextbox(pane,"GitHub repository","owner/repository")
        local name=UI.CreateTextbox(pane,"Source name","optional name")
        local branch=UI.CreateTextbox(pane,"Branch / commit","main")branch.Text="main"
        local mode=1
        local format=UI.CreateDropdown(pane,"Catalog type",{"music.json","Audio folder"},1)
        local path=UI.CreateTextbox(pane,"Catalog / folder","music.json")path.Text="music.json"
        format.Changed:Connect(function(value)
            mode=value
            if path.Text=="music.json" or path.Text=="music" then path.Text=value==1 and "music.json" or "music" end
        end)
        plain(pane,"A music.json catalog carries song titles and artists. Audio folders find .mp3, .ogg and .wav files; artist names stay unstated until supplied.")
        view.Form={Repo=repo,Name=name,Branch=branch,Format=format,Path=path}
        view.SaveButton=button("Save music source",function()run(function()
            local source=api.Add({Repo=repo.Text,Name=name.Text~="" and name.Text or repo.Text,
                Branch=branch.Text~="" and branch.Text or "main",Mode=mode==1 and "manifest" or "folder",Path=path.Text})
            selected=source.Id show()notify("saved :D refresh the source to list its songs")
        end)end)
    end
    local function refresh(source)
        if api.Loading then notify("a music catalog is already loading")return end
        notify("checking "..source.Name.." music...")
        local ok,reason=api.Refresh(source)
        if page.Parent and page.Visible then show() end
        notify(ok and "music catalog refreshed :D choose a song from UI Music" or reason)
    end
    show=function()
        clear()button("&lt; Back to Uhhhhhh",function()UI.Workspace.Open(ctx.Main,page)end)
        plain(pane,"music sources",16)
        if ctx.Transport then
            local transport=ctx.Transport local sound=ctx.Sound
            local function action(fn)return function()run(function()
                local ok,reason=fn()if ok==false then notify(reason)end
            end)end end
            button("Previous song",action(transport.Previous))
            button("Pause / resume",action(transport.Pause))
            button("Next song",action(function()return transport.Advance(true)end))
            UI.CreateDropdown(pane,"Playback order",transport.Modes,table.find(transport.Modes,transport.Settings.Mode)).Changed:Connect(function(index)
                transport.Settings.Mode=transport.Modes[index]or "Random"if ctx.Save then ctx.Save()end
            end)
            local seek=UI.CreateTextbox(pane,"Seek to seconds","0",13)
            seek.FocusLost:Connect(action(function()return transport.Seek(tonumber(seek.Text))end))
            UI.CreateSlider(pane,"Menu music volume",transport.Settings.Volume,0,1,.05).Changed:Connect(function(value)
                transport.Settings.Volume=value if ctx.VolumeChanged then ctx.VolumeChanged(value)end if ctx.Save then ctx.Save()end
            end)
            UI.CreateSlider(pane,"Menu music speed",transport.Settings.Speed,.25,2,.05).Changed:Connect(function(value)
                transport.Settings.Speed=value sound.PlaybackSpeed=value if ctx.Save then ctx.Save()end
            end)
        end
        plain(pane,"Songs from enabled sources appear in UI Music. Audio downloads when you choose a song; the current song keeps playing if a download fails.")
        local names,at={},1
        for i,source in ipairs(api.Sources) do
            local state=api.States[source.Id] or {}
            table.insert(names,(api.Enabled(source) and "[on] " or "[off] ")..escaped(source.Name).." ("..#(state.Tracks or {})..")")
            if source.Id==selected then at=i end
        end
        if #names>0 then
            local choose=UI.CreateDropdown(pane,"Repository",names,at)
            local source=api.Sources[at] selected=source.Id view.SourceSelect=choose
            choose.Changed:Connect(function(index)selected=api.Sources[index].Id show()end)
            plain(pane,source.Repo.." / "..source.Branch.."\n"..(source.Origin=="Marketplace" and "Marketplace catalog: " or "")..source.Mode.." / "..source.Path)
            local enabled=UI.CreateSwitch(pane,"Use this music source",api.Enabled(source))view.Enable=enabled
            enabled.Changed:Connect(function(value)api.SetEnabled(source,value)show()end)
            view.RefreshButton=button("Refresh this music source",function()refresh(source)end)
            local state=api.States[source.Id]
            if state and state.Error then plain(pane,"Last refresh: "..state.Error:sub(1,320)) end
            if state and state.CacheError then plain(pane,"Catalog saved for this session; cache write failed: "..state.CacheError:sub(1,220)) end
            if source.MarketEnabled==false then plain(pane,"This marketplace is disabled. Enable it in marketplace repositories, or add its music as a separate source.") end
            if state and #state.Tracks>0 then
                local songs={"-- Choose --"}
                for _,row in ipairs(state.Tracks) do table.insert(songs,escaped(row.Name.." — "..row.Artist)) end
                local song=UI.CreateDropdown(pane,"Play from this source",songs,1)view.TrackSelect=song
                local credits=plain(pane,"Song credits appear here when selected.")
                song.Changed:Connect(function(index)
                    if index<2 then return end
                    local row=state.Tracks[index-1]
                    credits.Text=row.Name.."\nArtist: "..row.Artist.."\nSource: "..row.SourceURL
                    if type(row.Credit)=="string" then credits.Text..="\n"..row.Credit:sub(1,512) end
                    if type(row.License)=="string" then credits.Text..="\nLicense: "..row.License:sub(1,160) end
                    if not api.CanUse(row) then notify("enable this music source first")return end
                    local ok,reason=ctx.Play(row.Key)if not ok then notify(reason)end
                end)
            end
            if source.Custom then view.RemoveButton=button("Remove this music source",function()api.Remove(source)selected=nil show()end) end
        else plain(pane,"No repository sources yet. Add a music catalog or audio folder below.") end
        view.AddButton=button("Add music repository",add)
        view.CancelButton=button("Cancel music download / refresh",function()api.Cancel()ctx.Cancel()notify("music request cancelled")end)
        plain(pane,"Marketplace repositories can publish music.json beside their catalog. Opening this page imports their settings; refresh only the source you want.")
    end
    view.Open=function()
        if ctx.Markets then local providers,enabled=ctx.Markets()api.SetMarkets(providers,enabled)end
        show()openPage()
    end
    view.Page=page view.Show=show
    local open=UI.CreateButton(ctx.Main,"Music sources &gt;",18)open.Activated:Connect(view.Open)
    view.Button=open return view
end
