    ["UhhhhhhReanim/System/runtime/steve110/main/music_transport.lua"] = [=====[
-- Nooby-inspired transport controls over the existing source-aware player.
-- Automatic progression only uses cached songs; explicit choices may download.
return function(ctx)
    local api={Modes={"Random","Sequential","Repeat"},History={},Cursor=0}
    local saved=ctx.Saved
    saved.MusicTransport=type(saved.MusicTransport)=="table"and saved.MusicTransport or {}
    local settings=saved.MusicTransport api.Settings=settings
    if not table.find(api.Modes,settings.Mode)then settings.Mode="Random"end
    settings.Volume=math.clamp(tonumber(settings.Volume)or 1,0,1)
    settings.Speed=math.clamp(tonumber(settings.Speed)or 1,.25,2)
    local player,sound=ctx.Player,ctx.Sound
    local suppress=false
    local function append(path)
        if api.History[api.Cursor]==path then return end
        while #api.History>api.Cursor do table.remove(api.History)end
        table.insert(api.History,path)
        while #api.History>64 do table.remove(api.History,1)end api.Cursor=#api.History
    end
    player.OnSongChanged=function(_previous,current)
        if not suppress then append(current)end
    end
    local function play(index,remember)
        local previous=player.Database[player.LastMusic or 0]
        if remember and previous then append(previous[1])end
        suppress=not remember
        local ok,why=player.PlayMusic(index,false)
        suppress=false
        if ok and remember then
            append(player.Database[player.LastMusic][1])
        end
        return ok,why
    end
    function api.Advance(manual)
        if #player.Database==0 then return false,"no available songs"end
        if not manual and settings.Mode=="Repeat"then sound.TimePosition=0 sound:Play()return true end
        if settings.Mode=="Sequential"then
            local last=player.LastMusic or 0
            for offset=1,#player.Database do
                local index=(last+offset-1)%#player.Database+1
                local entry=player.Database[index]
                local ok,cached=pcall(ctx.IsFile,entry[1])
                if manual or(ok and cached)then
                    local played,why=play(index,true)if played then return true end
                    if manual then return false,why end
                end
            end
            return false,"no cached song is available"
        end
        return play(nil,true)
    end
    function api.Previous()
        local current=player.Database[player.LastMusic or 0]
        if current and api.History[api.Cursor]~=current[1]then
            table.insert(api.History,current[1])api.Cursor=#api.History
        end
        if sound.TimePosition>3 then sound.TimePosition=0 return true end
        for at=api.Cursor-1,1,-1 do
            for index,row in ipairs(player.Database)do if row[1]==api.History[at]then
                local ok,why=play(index,false)if ok then api.Cursor=at end return ok,why
            end end
        end
        return false,"no earlier song in this session"
    end
    function api.Seek(seconds)
        assert(type(seconds)=="number"and seconds==seconds and math.abs(seconds)<1e8,"enter finite playback seconds")
        assert(sound.IsLoaded and sound.TimeLength>0,"the song has not loaded")
        sound.TimePosition=math.clamp(seconds,0,math.max(0,sound.TimeLength-.01))return true
    end
    function api.Pause()
        if sound.IsPlaying then sound:Pause()else sound:Resume()end return true
    end
    sound.PlaybackSpeed=settings.Speed
    return api
end
