    ["UhhhhhhReanim/System/runtime/steve110/main/navigation_label.lua"] = [=====[
-- Match navigation captions, not names such as Playback or Teleport Back.
return function(value)
    if type(value)~="string"then return value end
    return (value:gsub("^(%s*&lt;%s*)[Bb][Aa][Cc][Kk]%f[%A]","%1Hurry back")
        :gsub("^(%s*<%s*)[Bb][Aa][Cc][Kk]%f[%A]","%1Hurry back")
        :gsub("^(%s*)[Bb][Aa][Cc][Kk]%f[%A]","%1Hurry back"))
end
