    ["UhhhhhhReanim/System/runtime/steve110/main/ownership_probe.lua"] = [=====[
-- Preserve the executor's ownership contract for physical writers. The engine
-- getter is diagnostic only: a client/executor nil result must not change the
-- existing follower gate. Sleep, age and hidden peer IDs are not owner proofs.
return function(context)
    local ctx=context or {}
    local api={EngineReadable=nil,EngineError=nil}
    local function valid(part)
        return typeof(part)=="Instance"and part:IsA("BasePart")and part.Parent~=nil
    end
    local function rootOf(part)
        local root=part
        pcall(function()local candidate=part.AssemblyRootPart if valid(candidate)then root=candidate end end)
        return root
    end
    local function engine(part,force)
        if api.EngineReadable==false and not force then return false end
        local ok,owner=pcall(function()return part:GetNetworkOwner()end)
        if ok and (owner==nil or typeof(owner)=="Instance"and owner:IsA("Player"))then
            api.EngineReadable,api.EngineError=true,nil
            return true,owner
        end
        api.EngineReadable=false
        api.EngineError=ok and "GetNetworkOwner returned an unsupported value"or tostring(owner):sub(1,240)
        return false
    end
    local function native(part)
        if type(ctx.IsNetworkOwner)~="function"then return false end
        local ok,value=pcall(ctx.IsNetworkOwner,part)
        if ok and type(value)=="boolean"then return true,value end
        return false,nil
    end
    function api.Read(part,requireVerified)
        if not valid(part)then return false,"missing part",nil end
        local root=rootOf(part)
        if part.Anchored or root.Anchored then return false,"anchored assembly",root end
        local readable,value=native(root)
        if readable then return value,"isnetworkowner assembly",root end
        if root~=part then
            readable,value=native(part)
            if readable then return value,"isnetworkowner part",root end
        end
        if not requireVerified then
            local ok,age=pcall(function()return root.ReceiveAge end)
            if ok and type(age)=="number"then return age==0,"ReceiveAge inference (unverified)",root end
        end
        return nil,"ownership unavailable",root
    end
    function api.Snapshot(part)
        if not valid(part)then return {Available=false,Reason="missing part"}end
        local root=rootOf(part)
        local observed,source=api.Read(part,true)
        local result={Available=true,Owned=observed,Source=source,Root=root.Name,
            EngineReadable=api.EngineReadable,EngineError=api.EngineError}
        local readable,owner=engine(root,true)
        result.EngineReadable=readable
        result.EngineError=api.EngineError
        if readable then
            result.EngineOwner=owner and owner.Name or "server"
            result.EngineOwned=owner==ctx.Player
        end
        local rootOk,rootValue=native(root)
        local partOk,partValue=native(part)
        result.ExecutorRootReadable,result.ExecutorPartReadable=rootOk,partOk
        if rootOk then result.ExecutorRootOwned=rootValue end
        if partOk then result.ExecutorPartOwned=partValue end
        result.Conflicting=readable and rootOk and (result.EngineOwned~=rootValue)
            or rootOk and partOk and rootValue~=partValue or false
        local ageOk,age=pcall(function()return root.ReceiveAge end)
        if ageOk and type(age)=="number"then result.ReceiveAge=age end
        if type(ctx.GetHiddenProperty)=="function"then
            local ok,sleep=pcall(ctx.GetHiddenProperty,root,"NetworkIsSleeping")
            if ok and type(sleep)=="boolean"then result.Sleeping=sleep end
            local ownerOk,peer=pcall(ctx.GetHiddenProperty,root,"NetworkOwnerV3")
            result.HiddenOwnerReadable=ownerOk
            if ownerOk then
                -- SystemAddress has no portable documented peer mapping. Do
                -- not interpret it as a player ID or export a network address.
                result.HiddenOwnerType=typeof(peer)
                if type(peer)=="number"then result.HiddenOwnerSentinel=peer end
            end
        end
        return result
    end
    return api
end
