    ["UhhhhhhReanim/System/runtime/steve110/main/pose_sampler.lua"] = [=====[
-- Exact sparse-channel sampling. Index once, binary search each joint instead
-- of searching every frame's pose array for every joint on every sample.
return function(ease)
    local api={Entries={},Builds=0,Hits=0,Count=0,Poses=0,Serial=0}
    local function remove(track)
        local entry=api.Entries[track]
        if entry then api.Poses-=entry.Poses api.Count-=1 api.Entries[track]=nil end
    end
    function api.Invalidate(track)
        if track then remove(track)else table.clear(api.Entries)api.Poses,api.Count=0,0 end
    end
    local function oldest()
        local chosen,serial
        for track,entry in pairs(api.Entries)do if not serial or entry.Used<serial then chosen,serial=track,entry.Used end end
        return chosen
    end
    local function build(track)
        local channels,times,total={}, {},0
        for _,frame in ipairs(track.Keyframes)do
            local last={}
            for _,pose in ipairs(frame.Poses)do
                if not channels[pose.Name]then channels[pose.Name]={}times[pose.Name]={}end
                if pose.Weight>0 then last[pose.Name]=pose end
            end
            for name,pose in pairs(last)do
                if not times[name][frame.Time]then
                    times[name][frame.Time]=true
                    table.insert(channels[name],{Frame=frame,Pose=pose})total+=1
                end
            end
        end
        for _,channel in pairs(channels)do table.sort(channel,function(a,b)return a.Frame.Time<b.Frame.Time end)end
        while api.Count>=8 or api.Count>0 and api.Poses+total>500000 do remove(oldest())end
        local entry={Channels=channels,Frames=track.Keyframes,Length=#track.Keyframes,Poses=total,Used=api.Serial}
        api.Entries[track]=entry api.Count+=1 api.Poses+=total api.Builds+=1
        return entry
    end
    function api.Sample(track,t)
        api.Serial+=1
        local entry=api.Entries[track]
        if not entry or entry.Frames~=track.Keyframes or entry.Length~=#track.Keyframes then
            remove(track)entry=build(track)
        else api.Hits+=1 end
        entry.Used=api.Serial
        local result={}
        for name,channel in pairs(entry.Channels)do
            local low,high=1,#channel
            while low<=high do
                local middle=math.floor((low+high)/2)
                if channel[middle].Frame.Time<=t then low=middle+1 else high=middle-1 end
            end
            local a,b=channel[high],channel[low]
            local cf=CFrame.identity
            if a and b then
                local alpha=(t-a.Frame.Time)/(b.Frame.Time-a.Frame.Time)
                cf=a.Pose.CFrame:Lerp(b.Pose.CFrame,ease(alpha,a.Pose.EasingStyle,a.Pose.EasingDirection))
            elseif a or b then cf=(a or b).Pose.CFrame end
            result[name]=cf
        end
        return result
    end
    return api
end
