BindToRenderStep(function(_, dt)
local t = os.clock()
local MainSizeYOffset = Main.Size.Y.Offset
local WindowSizeXOffset = Window.Size.X.Offset
local WindowSizeYOffset = Window.Size.Y.Offset
local WindowSidebarSize = math.max(0, Window.SidebarSize)
local cornerRadius = Theme.Current:GetAttribute("CornerRadius")
if MainSizeYOffset > 30 + cornerRadius then
WindowClip.Visible = true
local ContentYSize = WindowSizeYOffset - 30 - cornerRadius
WindowContent.Size = UDim2.new(0, WindowSizeXOffset - WindowSidebarSize, 0, ContentYSize)
if WindowSidebarSize > 0 then
WindowSidebar.Size = UDim2.new(0, WindowSidebarSize, 0, ContentYSize)
WindowSidebar.Visible = true
else
WindowSidebar.Visible = false
end
else
WindowClip.Visible = false
end
if t - uinotif.LastNotif < 4 or uinotif.Progress < 1 then
uinotif.Animation = math.max(0, uinotif.Animation - dt * 2)
else
uinotif.Animation = math.min(1, uinotif.Animation + dt * 2)
end
if uinotif.Animation < 1 then
UINotifyFrame.Visible = true
local notifyScreen = Util.GetScreenSize()
local notifyWidth = math.max(1, math.min(440, notifyScreen.X - 20))
local notifyLimit = math.max(1, notifyScreen.Y - 8)
local notifyPadding = math.min(8, notifyWidth / 4)
if uinotif.LayoutText ~= uinotif.Text or uinotif.LayoutWidth ~= notifyWidth
or uinotif.LayoutLimit ~= notifyLimit or uinotif.LayoutTextSize ~= NotifyText.TextSize or uinotif.LayoutFont ~= NotifyText.Font then
local textSize = Util.GetTextSize(uinotif.Text, NotifyText.TextSize, NotifyText.Font, Vector2.new(math.max(1, notifyWidth - notifyPadding * 2), math.huge))
uinotif.LayoutText, uinotif.LayoutWidth, uinotif.LayoutLimit = uinotif.Text, notifyWidth, notifyLimit
uinotif.LayoutTextSize, uinotif.LayoutFont = NotifyText.TextSize, NotifyText.Font
UINotifyFrame.Size = UDim2.fromOffset(notifyWidth, math.min(notifyLimit, math.max(30, textSize.Y + 12)))
end
local notifyHeight = UINotifyFrame.Size.Y.Offset
NotifyText.Size = UDim2.new(1, -notifyPadding * 2, 1, -math.min(12, notifyHeight / 2))
local notifyX = Main.Position.X.Scale * notifyScreen.X + Main.Position.X.Offset
local notifyY = Main.Position.Y.Scale * notifyScreen.Y + Main.Position.Y.Offset + MainSizeYOffset / 2 + notifyHeight / 2 + 10 + math.pow(uinotif.Animation, 3) * -40
UINotifyFrame.Position = UDim2.fromOffset(
math.clamp(notifyX, notifyWidth / 2 + 4, math.max(notifyWidth / 2 + 4, notifyScreen.X - notifyWidth / 2 - 4)),
math.clamp(notifyY, notifyHeight / 2 + 4, math.max(notifyHeight / 2 + 4, notifyScreen.Y - notifyHeight / 2 - 4)))
Progress.Size = UDim2.new(1, -cornerRadius * 2, 1, 0)
if uinotif.Progress >= 1 then
Progress.BackgroundTransparency = math.min(t - uinotif.LastNotif, 0.5) * 2 * 0.3 + 0.7
else
Progress.BackgroundTransparency = 1
end
local c = Theme.Current:GetAttribute("OutlineColor")
local s = math.sin(t * 3) * 0.5 + 0.5
if uinotif.Progress > 0 then
uinotif.ProgressSm = uinotif.Progress + (uinotif.ProgressSm - uinotif.Progress) * math.exp(-16 * dt)
ProgressTop.BackgroundTransparency = 0
ProgressBot.BackgroundTransparency = 0
ProgressTop.Size = UDim2.new(uinotif.ProgressSm, 0, 0, 4)
ProgressBot.Size = UDim2.new(uinotif.ProgressSm, 0, 0, 4)
else
uinotif.ProgressSm = 1
ProgressTop.BackgroundTransparency = s
ProgressBot.BackgroundTransparency = s
ProgressTop.Size = UDim2.new(1, 0, 0, 4)
ProgressBot.Size = UDim2.new(1, 0, 0, 4)
end
ProgressTop.BackgroundColor3 = c
ProgressBot.BackgroundColor3 = c
NotifyText.Text = uinotif.Text
else
UINotifyFrame.Visible = false
end
end, Main, true)

return Window
end

local UI = {}
Prefabs.UI = UI

local function bindTextLayout(text, update)
local queued = false
Util.LinkDestroyI2C(text, text.Changed:Connect(function(property)
if property ~= "Text" and property ~= "ContentText" and property ~= "TextSize"
and property ~= "Font" and property ~= "FontFace" and property ~= "TextWrapped"
and property ~= "RichText" and property ~= "PlaceholderText" and property ~= "AbsoluteSize" then return end
if queued then return end
queued = true
task.defer(function()
queued = false
if text.Parent then update() end
end)
end))
end

