Button.TextYAlignment = Enum.TextYAlignment.Center
Button.TextWrapped = true
Button.TextSize = 15
Theme.ApplyLabel(Button)
Button.Text = " [ + ] " .. text
local ListClip = Util.Instance("Frame", Container)
ListClip.AnchorPoint = Vector2.new(0, 0)
ListClip.Position = UDim2.new(0, 0, 0, 20)
ListClip.Size = UDim2.new(1, 0, 0, 0)
ListClip.BackgroundTransparency = 1
ListClip.AutomaticSize = Enum.AutomaticSize.None
ListClip.ClipsDescendants = true
local function update()
Container.AutomaticSize = ListClip.AutomaticSize
Container.Size = ListClip.Size + UDim2.new(0, 0, 0, 20)
end
ListClip:GetPropertyChangedSignal("AutomaticSize"):Connect(update)
ListClip:GetPropertyChangedSignal("Size"):Connect(update)
local ListBox = Util.Instance("Frame", ListClip)
ListBox.AnchorPoint = Vector2.new(0, 0)
ListBox.Position = UDim2.new(0, 0, 0, 0)
ListBox.Size = UDim2.new(1, 0, 0, 20)
ListBox.BackgroundTransparency = 1
ListBox.AutomaticSize = Enum.AutomaticSize.Y
Util.AddPadding(ListBox, 2, 2, 0, 0)
local UIList = Util.Instance("UIListLayout", ListBox)
UIList.FillDirection = Enum.FillDirection.Vertical
UIList.HorizontalAlignment = Enum.HorizontalAlignment.Center
UIList.VerticalAlignment = Enum.VerticalAlignment.Top
UIList.Padding = UDim.new(0, 0)
UIList.SortOrder = Enum.SortOrder.LayoutOrder
Util.LinkDestroyI2I(ListBox, Container)
UI.Separator(ListBox)
UI.Separator(ListBox).LayoutOrder = 65536
local opened = false
Button.Activated:Connect(function()
opened = not opened
if opened then
Button.Text = " [ - ] " .. text
local tween = TweenService:Create(ListClip, TweenInfo.new(0.5), {
Size = UDim2.new(1, 0, 0, ListBox.AbsoluteSize.Y)
})
tween.Completed:Connect(function(oh)
if oh == Enum.PlaybackState.Completed then
ListClip.AutomaticSize = Enum.AutomaticSize.Y
ListClip.Size = UDim2.new(1, 0, 0, 0)
end
end)
tween:Play()
Theme.PlaySound("EXPAND")
else
Button.Text = " [ + ] " .. text
ListClip.Size = UDim2.new(1, 0, 0, ListBox.AbsoluteSize.Y)
ListClip.AutomaticSize = Enum.AutomaticSize.None
TweenService:Create(ListClip, TweenInfo.new(0.5), {
Size = UDim2.new(1, 0, 0, 0)
}):Play()
Theme.PlaySound("COLLAPSE")
end
end)
return ListBox
end
