UDim2.new(0, 0, 0, 0),
UDim2.new(1, -20, 0, 20),
"Left", "Center",
20, ""
)
MakeText(
Vector2.new(1, 0),
UDim2.new(1, 0, 0, 0),
UDim2.new(0, 20, 0, 20),
"Center", "Center",
20, ">"
)
local TextDesc = MakeText(
Vector2.new(0, 0),
UDim2.new(0, 0, 0, 22),
UDim2.new(1, 0, 0, 12),
"Left", "Center",
12, ""
)
local function updateEntryName()
Container.Name = TextName.Text .. "\n" .. TextDesc.Text
end
ListBox:GetAttributeChangedSignal("Name"):Connect(function()
TextName.Text = ListBox:GetAttribute("Name")
updateEntryName()
end)
ListBox:GetAttributeChangedSignal("Description"):Connect(function()
TextDesc.Text = ListBox:GetAttribute("Description")
updateEntryName()
end)
local function MakeButton(xpos, xoff, xsize, text)
local Button = Util.Instance("TextButton", ListBox)
Button.AnchorPoint = Vector2.new(xpos, 0)
Button.Position = UDim2.new(xpos, xoff, 0, 38)
Button.Size = UDim2.new(0, xsize, 0, 19)
Button.BackgroundTransparency = 0
Button.BackgroundColor3 = Color3.new(1, 1, 1)
Button.BorderSizePixel = 0
Button.Text = ""
Button.AutoButtonColor = true
Theme.ApplyFrame(Button)
Util.AddPadding(Button, 0, 0, 2, 2)
local ButtonText = Util.Instance("TextLabel", Button)
ButtonText.AnchorPoint = Vector2.new(0, 0)
ButtonText.Position = UDim2.new(0, 0, 0, 0)
ButtonText.Size = UDim2.new(1, 0, 1, 0)
ButtonText.BackgroundTransparency = 1
ButtonText.RichText = true
ButtonText.Font = Data.TextFont
ButtonText.TextColor3 = Color3.new(1, 1, 1)
ButtonText.TextTransparency = 0
ButtonText.TextXAlignment = Enum.TextXAlignment.Center
ButtonText.TextYAlignment = Enum.TextYAlignment.Center
ButtonText.TextWrapped = true
ButtonText.TextSize = 15
ButtonText.Text = text
Theme.ApplyLabel(ButtonText)
return Button, ButtonText
end
local Favorite, FavoriteText = MakeButton(0, 2, 40, "")
Favorite.Activated:Connect(function()
ListBox:SetAttribute("FavoriteClick", ListBox:GetAttribute("FavoriteClick") + 1)
end)
ListBox:GetAttributeChangedSignal("Favorite"):Connect(function()
FavoriteText.Text = if ListBox:GetAttribute("Favorite") then "\xf0\x9f\x8c\x9f" else "\xe2\xad\x90"
end)
local Execute, ExecuteText = MakeButton(1, -2, 120, "")
Execute.Activated:Connect(function()
ListBox:SetAttribute("RunningClick", ListBox:GetAttribute("RunningClick") + 1)
end)
ListBox:GetAttributeChangedSignal("Running"):Connect(function()
ExecuteText.Text = if ListBox:GetAttribute("Running") then Data.Lang:Get("MODULE_STOP") else Data.Lang:Get("MODULE_PLAY")
end)
ListBox:SetAttribute("Name", "your name here")
ListBox:SetAttribute("Description", "your description here. lorem ipsum dolor sat on a meat")
ListBox:SetAttribute("Favorite", false)
ListBox:SetAttribute("Running", false)
ListBox:SetAttribute("FavoriteClick", -65536)
ListBox:SetAttribute("RunningClick", -65536)
return ListBox
end

table.freeze(UI)
table.freeze(Prefabs)

return Prefabs
