    ["UhhhhhhReanim/System/runtime/steve110/main/reanimation/camera_subject.lua"] = [=====[
-- Give Roblox's camera a stable controller subject without replacing the
-- game's camera solver, cutscenes, spectate targets or camera input.
local Subject={}
function Subject.new(context)
    local ctx=context or {}
    local api={}
    local camera,original,assigned,physical,controller,writing
    local cameraConnections,worldConnection={},nil
    local function inside(value,model)
        return typeof(value)=="Instance"and model and value:IsDescendantOf(model)
    end
    local function restore()
        for _,connection in ipairs(cameraConnections)do connection:Disconnect()end
        table.clear(cameraConnections)
        if camera and assigned and camera.CameraSubject==assigned then
            pcall(function()
                if original and original.Parent then camera.CameraSubject=original end
            end)
        end
        camera,original,assigned=nil,nil,nil
    end
    function api.Step()
        if writing then return end
        local current=ctx.World and ctx.World.CurrentCamera
        if current~=camera then
            restore()camera=current
            if camera then
                for _,property in ipairs({"CameraSubject","CameraType"})do
                    table.insert(cameraConnections,camera:GetPropertyChangedSignal(property):Connect(api.Step))
                end
            end
        end
        local humanoid=controller and controller.Parent and controller:FindFirstChildOfClass("Humanoid")
        if not camera or not humanoid or ctx.Enabled and not ctx.Enabled()
            or camera.CameraType==Enum.CameraType.Scriptable then return end
        local subject=camera.CameraSubject
        if inside(subject,physical)then
            original,assigned=subject,humanoid
            writing=true
            local ok=pcall(function()camera.CameraSubject=humanoid end)
            writing=false
            if not ok then assigned=nil end
        end
    end
    function api.Clear()
        if worldConnection then worldConnection:Disconnect()worldConnection=nil end
        restore()physical,controller=nil,nil
    end
    function api.Bind(real,figure)
        if controller==figure and camera and ctx.World and camera==ctx.World.CurrentCamera then
            -- The game can replace the physical avatar while our controller
            -- survives. Keep its stable subject and restore to the new avatar.
            physical=real
            if assigned then original=real and real:FindFirstChildOfClass("Humanoid")or original end
            api.Step()return
        end
        api.Clear()physical,controller=real,figure
        if ctx.World then
            worldConnection=ctx.World:GetPropertyChangedSignal("CurrentCamera"):Connect(api.Step)
        end
        api.Step()
    end
    return api
end
return Subject
