-- Living-body accessory ownership mode. Roblox remains the ownership authority.
local NoDeath={}
function NoDeath.Session(deps)
    local s={Hats={},Parts={},Links={},Saved={},Stable={},Owned={},Dirty=true}
    local known,connections={},{}
    local function save(object,key,value)
        local properties=s.Saved[object]
        if not properties then properties={}; s.Saved[object]=properties end
        if properties[key]==nil then properties[key]={object[key]} end
        object[key]=value
    end
    function s.NativeOwner(part)
        if not part or not part.Parent or part.Anchored then return false end
        if type(deps.NetworkOwner)~="function" then return nil end
        local ok,result=pcall(deps.NetworkOwner,part)
        if not ok or type(result)~="boolean" then return nil end
        return result
    end
    local function accessoryOf(part)
        local accessory=part and part:FindFirstAncestorOfClass("Accessory")
        return accessory and accessory.Parent==s.Character and accessory or nil
    end
    function s.Owns(handle)
        local accessory=accessoryOf(handle)
        if not accessory then return false end
        local root=handle.AssemblyRootPart
        if not root or not root:IsDescendantOf(accessory) then return false end
        return s.NativeOwner(root)
    end
    local function detach(link)
        if known[link] then return end
        local p0,p1
        if link:IsA("JointInstance") or link:IsA("WeldConstraint") then
            p0,p1=link.Part0,link.Part1
        elseif link:IsA("Constraint") then
            local ok,a0,a1=pcall(function() return link.Attachment0,link.Attachment1 end)
            if ok then
                p0=a0 and a0:FindFirstAncestorWhichIsA("BasePart")
                p1=a1 and a1:FindFirstAncestorWhichIsA("BasePart")
            end
        end
        local a0,a1=accessoryOf(p0),accessoryOf(p1)
        if not (p0 and p1 and a0~=a1 and (a0 or a1)) then return end
        known[link]=true
        table.insert(s.Links,{Link=link,Parent=link.Parent})
        link.Parent=nil
    end
    function s.Scan()
        local character=s.Character
        if not character or not character.Parent then return end
        table.clear(s.Hats); table.clear(s.Parts)
        local descendants=character:GetDescendants()
        for _,item in ipairs(descendants) do
            if item:IsA("Accessory") and item.Parent==character then
                local handle=item:FindFirstChild("Handle")
                if handle and handle:IsA("BasePart") then table.insert(s.Hats,item) end
            elseif item:IsA("BasePart") then
                table.insert(s.Parts,item)
                if accessoryOf(item) then
                    save(item,"CanCollide",false); save(item,"CanTouch",false)
                else
                    -- Keep floor collisions if the server owns the living body.
                    save(item,"LocalTransparencyModifier",1)
                end
            elseif item:IsA("LocalScript") and item.Name=="Animate" then
                save(item,"Enabled",false)
            end
        end
        for _,item in ipairs(descendants) do detach(item) end
        for _,hat in ipairs(s.Hats) do
            local handle=hat:FindFirstChild("Handle")
            save(handle,"Massless",handle.Massless)
            save(handle,"CustomPhysicalProperties",handle.CustomPhysicalProperties)
            save(handle,"LocalTransparencyModifier",handle.LocalTransparencyModifier)
            if s.Owns(handle)==true then
                handle.AssemblyLinearVelocity=Vector3.new(0,deps.NetlessVelocity(),0)
                handle.AssemblyAngularVelocity=Vector3.zero
            end
        end
        s.Dirty=false
    end
    function s.Attach(character)
        s.Character=character
        s.Humanoid=character:FindFirstChildOfClass("Humanoid")
        s.Root=character:FindFirstChild("HumanoidRootPart")
        assert(s.Humanoid and s.Root and s.Humanoid.Health>0,"No death needs a living character")
        save(s.Humanoid,"AutoRotate",false); save(s.Humanoid,"PlatformStand",true)
        table.insert(connections,character.DescendantAdded:Connect(function() s.Dirty=true end))
        table.insert(connections,character.DescendantRemoving:Connect(function() s.Dirty=true end))
        s.Scan()
    end
    function s.Sample()
        local owned,total,unknown=0,0,0
        for _,hat in ipairs(s.Hats) do
            local handle=hat:FindFirstChild("Handle")
            if hat.Parent==s.Character and handle and handle.Parent then
                total+=1
                local ours=s.Owns(handle)
                s.Owned[handle]=ours==true
                s.Stable[handle]=ours==true and (s.Stable[handle] or 0)+1 or 0
                if s.Stable[handle]>=3 then owned+=1 end
                if ours==nil then unknown+=1 end
            end
        end
        return owned,total,unknown
    end
    function s.Follow(target)
        local root=s.Root
        if root and root.Parent and target and s.NativeOwner(root)==true then
            root.CFrame=target.CFrame
            root.AssemblyLinearVelocity=target.AssemblyLinearVelocity
            root.AssemblyAngularVelocity=Vector3.zero
        end
    end
    function s.Restore()
        for _,connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
        for _,hat in ipairs(s.Hats) do
            local handle=hat:FindFirstChild("Handle")
            if handle and s.Owns(handle)==true then
                pcall(function()
                    handle.AssemblyLinearVelocity=s.Root.AssemblyLinearVelocity
                    handle.AssemblyAngularVelocity=Vector3.zero
                    handle:SetAttribute("_Uhhhhhh_ClaimTime",nil)
                    handle:SetAttribute("_Uhhhhhh_LastPosition",nil)
                end)
            end
        end
        for _,entry in ipairs(s.Links) do
            if entry.Parent and (entry.Parent==s.Character or entry.Parent:IsDescendantOf(s.Character)) then
                pcall(function() entry.Link.Parent=entry.Parent end)
            end
        end
        for object,properties in pairs(s.Saved) do
            if object.Parent then
                for key,old in pairs(properties) do pcall(function() object[key]=old[1] end) end
            end
        end
        table.clear(connections); table.clear(s.Links); table.clear(s.Saved)
        table.clear(s.Owned); table.clear(s.Stable)
    end
    return s
end
function NoDeath.Run(deps)
    local player,reanimate,hats=deps.Player,deps.Reanimate,deps.HatReanimator
    local now=deps.Clock or os.clock
    local session,characterConnection,pending
    local nextRadius,nextStatus,warmup,handedOff=0,0,0,false
