        local targets=reanimate.Character:GetDescendants()
        for _,part in ipairs(session.Parts) do
            if part.CanCollide and not part:FindFirstAncestorOfClass("Accessory") then
                for _,target in ipairs(targets) do
                    if target:IsA("BasePart") and target.CanCollide then
                        local link=Instance.new("NoCollisionConstraint")
                        link.Part0,link.Part1=part,target
                        link.Parent=reanimate.Character
                        table.insert(noCollisions,link)
                    end
                end
            end
        end
    end
    local function rebuild()
        table.clear(deps.Hats)
        for _,hat in ipairs(session.Hats) do table.insert(deps.Hats,hat) end
        deps.ResetMap(); deps.RefreshMap(session.Character); separateController()
    end
    local function attach(character)
        clearNoCollisions()
        if session then session.Restore() end
        session=NoDeath.Session(deps); session.Attach(character)
        hats._NoDeathOwned=session.Owned
        hats.ActiveRealCharacter=character; hats.RigGeneration+=1
        hats.HasPermadeath,hats.HasHatCollide=false,false
        hats.Status.Permadeath="No death: body stays alive."
        hats.Status.HatCollide="No death skips body destruction and void methods."
        rebuild()
        warmup,handedOff=now(),false
    end
    local function handoff()
        local controller=reanimate.Character
        local humanoid=controller and controller:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end
        hats.DontFireCharAddOnThisChar=controller
        player.Character=controller
        if deps.Camera then
            deps.Camera.CameraType=Enum.CameraType.Custom
            deps.Camera.CameraSubject=humanoid
        end
