    end
    hats.NoDeathActive=true; table.clear(hats.FlingTargets)
    local ok,reason=xpcall(function()
        local physical=player.Character
        local root=physical and physical:FindFirstChild("HumanoidRootPart")
        assert(root,"No death needs the current physical character")
        reanimate.CreateCharacter(root.CFrame)
        characterConnection=player.CharacterAdded:Connect(function(character)
            if character~=reanimate.Character and (not session or character~=session.Character) then pending=character end
        end)
