-- Awes955's ragdoll follower motion policy, shared with native lifecycle code.
local Motion={}
local function finite(value)return type(value)=="number"and value==value and math.abs(value)<1e12 end
local function valid(cf)
    if typeof(cf)~="CFrame"then return false end
    for _,value in ipairs({cf:GetComponents()})do if not finite(value)then return false end end
    return true
end
