-- Nooby's RootPart placement method, adapted as a shared extension.
-- Source: Elliot12-wq/Uh-reanimation-modded-by-nooby, af5ec0cd06b493b126d666fea8adb30947e34fc0.
-- Retains its smoothing, streaming leash, teleport reset and finite fallback.
return function()
local STREAM_DEPTH = 16
local DEEP_DEPTH = 64
local FLOOR_MARGIN = 32
local DEFAULT_FPDH = -500
local SMOOTH_TIME_XZ = 0.20
local SMOOTH_TIME_Y = 0.40
local STREAM_LEASH = 8
local DEEP_LEASH = 48
local TELEPORT_DIST = 200
local MAX_DT = 0.1
local DEFAULT_DT = 1 / 60
local MAX_COORD = 1e8
local MAX_VEL = 1e5
local MAX_FAILS = 30
local OMEGA_XZ = 2 / SMOOTH_TIME_XZ
local OMEGA_Y = 2 / SMOOTH_TIME_Y
local sqrt, min, max = math.sqrt, math.min, math.max
local ready = false
local sx, sy, sz = 0, 0, 0
local vx, vy, vz = 0, 0, 0
local lastT = nil
local fails = 0
local function finite(n)
return type(n) == "number" and n == n and n > -MAX_COORD and n < MAX_COORD
end
local function readPosition(part)
return part.Position
end
local function samplePart(part)
if typeof(part) ~= "Instance" or part.Parent == nil then return nil end
local ok, pos = pcall(readPosition, part)
if not ok or typeof(pos) ~= "Vector3" then return nil end
local x, y, z = pos.X, pos.Y, pos.Z
if finite(x) and finite(y) and finite(z) then return x, y, z end
return nil
end
local function damp(cur, target, vel, omega, dt)
local x = omega * dt
local e = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x)
local change = cur - target
local temp = (vel + omega * change) * dt
return target + (change + temp) * e, (vel - omega * temp) * e
end
local function step(ctx)
local fpdh = ctx.FallenPartsDestroyHeight
if not finite(fpdh) then fpdh = DEFAULT_FPDH end
local floorY = fpdh + FLOOR_MARGIN
local px, py, pz = samplePart(ctx.RootPart)
if px == nil then px, py, pz = samplePart(ctx.Torso) end
local t = ctx.Time
local dt = DEFAULT_DT
if finite(t) and lastT ~= nil and t >= lastT then
dt = min(t - lastT, MAX_DT)
end
if finite(t) then lastT = t end
if px ~= nil then
local streaming = ctx.Streaming == true
local tx, tz = px, pz
local ty = max(py - (streaming and STREAM_DEPTH or DEEP_DEPTH), floorY)
local dx, dy, dz = tx - sx, ty - sy, tz - sz
local dist = sqrt(dx * dx + dy * dy + dz * dz)
local stateOk = finite(sx) and finite(sy) and finite(sz)
and finite(vx) and finite(vy) and finite(vz)
if not ready or dist > TELEPORT_DIST or not stateOk then
sx, sy, sz = tx, ty, tz
vx, vy, vz = 0, 0, 0
ready = true
else
sx, vx = damp(sx, tx, vx, OMEGA_XZ, dt)
sz, vz = damp(sz, tz, vz, OMEGA_XZ, dt)
sy, vy = damp(sy, ty, vy, OMEGA_Y, dt)
local leash = streaming and STREAM_LEASH or DEEP_LEASH
dx, dy, dz = tx - sx, ty - sy, tz - sz
local rem = sqrt(dx * dx + dy * dy + dz * dz)
if rem > leash then
local k = (rem - leash) / rem
sx, sy, sz = sx + dx * k, sy + dy * k, sz + dz * k
end
if vx > MAX_VEL or vx < -MAX_VEL or vy > MAX_VEL or vy < -MAX_VEL or vz > MAX_VEL or vz < -MAX_VEL then
vx, vy, vz = 0, 0, 0
end
end
if sy < floorY then
sy = floorY
if vy < 0 then vy = 0 end
end
elseif not ready then
sx, sy, sz = 0, floorY, 0
vx, vy, vz = 0, 0, 0
ready = true
else
vx, vy, vz = 0, 0, 0
end
return CFrame.new(sx, sy, sz)
end
return {
Name = "Nooby's style",
GetRootCFrame = function(ctx)
local ok, cf = pcall(step, ctx)
if ok and typeof(cf) == "CFrame" then
fails = 0
return cf
end
fails = fails + 1
if fails > MAX_FAILS then
error("Nooby's style failed repeatedly: " .. tostring(cf), 0)
end
if ready and finite(sx) and finite(sy) and finite(sz) then
return CFrame.new(sx, sy, sz)
end
return CFrame.new(0, DEFAULT_FPDH + FLOOR_MARGIN, 0)
end,
}
end
