    ["UhhhhhhReanim/System/runtime/steve110/main/reanimation/npc.lua"] = [=====[
-- NPC selection and pose copying adapted from Nooby's NPC reanimator.
-- Source: Elliot12-wq/Uh-reanimation-modded-by-nooby, af5ec0c, lines 262988-263604.
-- Uses this fork's controller, joint writer and cleanup. Ownership is observed;
-- the server decides which assemblies the client can simulate.
return function(ctx)
    local world, player, reanimate = ctx.World, ctx.Player, ctx.Reanimate
    local settings = ctx.Saved.Reanimator
    settings.NPCRadius = math.clamp(tonumber(settings.NPCRadius) or 200, 20, 1000)
    if settings.NPCAutoPick == nil then settings.NPCAutoPick = true end
    if settings.NPCAutoRescan == nil then settings.NPCAutoRescan = true end
    local api = {Name = "NPC (beta)", Running = false, Status = "choose an NPC",
        ManagedLifecycle = true, FlingTargets = {}, List = {}, _TempNotFling = {}}
    local clock = ctx.Clock or os.clock
    local humanoids, scanConnections, connections = nil, {}, {}
    local active, scanAge, rejected = nil, 0, setmetatable({}, {__mode = "k"})
    local guard = require(script.Parent.collision_guard).new()
    local fling = require(script.Parent.Parent.fling_fallback)
    local flingHome
    local realHumanoid, realFlags

    local function restoreReal()
        if realHumanoid and realHumanoid.Parent then
            pcall(function()
                realHumanoid.PlatformStand,realHumanoid.AutoRotate=realFlags.PlatformStand,realFlags.AutoRotate
            end)
        end
        realHumanoid,realFlags=nil,nil
    end

    local function holdReal()
        local current=player.Character
        if current==reanimate.Character then return end
        local humanoid=current and current:FindFirstChildOfClass("Humanoid")
        if humanoid==realHumanoid then api.RealCharacter=current return end
        restoreReal()
        api.RealCharacter=current
        if humanoid then
            realHumanoid=humanoid
            realFlags={PlatformStand=humanoid.PlatformStand,AutoRotate=humanoid.AutoRotate}
            humanoid.PlatformStand,humanoid.AutoRotate=true,false
        end
    end

    local function root(model)
        return model and (model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart)
    end

    local function owned(part)
        if not part or part.Anchored or part:IsGrounded() then return false end
        local ok, answer = pcall(ctx.Owned, part)
        return ok and answer == true
    end

    function api.Check(model)
        if not model or not model:IsA("Model") or not model:IsDescendantOf(world) then return nil, "NPC was removed" end
        if ctx.Players:GetPlayerFromCharacter(model) or model == player.Character or model == reanimate.Character
            or player.Character and model:IsDescendantOf(player.Character)
            or reanimate.Character and model:IsDescendantOf(reanimate.Character) then
            return nil, "player characters are excluded"
        end
        local humanoid, part = model:FindFirstChildOfClass("Humanoid"), root(model)
        if not humanoid or humanoid.Health <= 0 or not part then return nil, "NPC needs a living humanoid and root" end
        if not owned(part) then return nil, "NPC root is not locally owned" end
        local joints = {}
        for _, joint in ipairs(model:GetDescendants()) do
            if joint:IsA("Motor6D") and joint.Part0 and joint.Part1
                and joint.Part0.Parent == model and joint.Part1.Parent == model then
                table.insert(joints, joint)
            end
        end
        if #joints == 0 then return nil, "NPC has no supported Motor6D joints" end
        return {Model = model, Humanoid = humanoid, Root = part, Joints = joints}
    end

    local function unhook()
        for _, connection in ipairs(scanConnections) do connection:Disconnect() end
        table.clear(scanConnections)
        humanoids = nil
    end

    local function hook()
        if humanoids then return end
        humanoids = {}
        local indexed=humanoids
        for _, object in ipairs(world:GetDescendants()) do
            if object:IsA("Humanoid") then indexed[object] = true end
        end
        table.insert(scanConnections, world.DescendantAdded:Connect(function(object)
            if object:IsA("Humanoid") then indexed[object] = true end
        end))
        table.insert(scanConnections, world.DescendantRemoving:Connect(function(object) indexed[object] = nil end))
    end

    function api.Scan()
        hook()
        local origin = root(reanimate.Character) or root(player.Character)
        if not origin then api.List = {} return api.List end
        local result = {}
        for humanoid in pairs(humanoids) do
            local model = humanoid.Parent
            local part = model and root(model)
            if part and not rejected[model] then
                local distance = (part.Position - origin.Position).Magnitude
                if distance <= settings.NPCRadius and api.Check(model) then
                    table.insert(result, {Model = model, Distance = distance})
                end
            end
        end
        table.sort(result, function(a, b) return a.Distance < b.Distance end)
        while #result > 50 do table.remove(result) end
        api.List = result
        return result
    end

    function api.Detach(reason)
        local previous = active
        active, api.ActiveNPC, api.Cur = nil, nil, nil
        guard.Clear()
        if previous then
            for joint, snapshot in pairs(previous.Poses) do
                if joint.Parent then
                    pcall(ctx.Write, joint, snapshot.C0 * snapshot.Transform * snapshot.C1:Inverse())
                    pcall(function() joint.Enabled = snapshot.Enabled joint.Transform = snapshot.Transform end)
                end
            end
            for object, properties in pairs(previous.Properties) do
                if object.Parent then
                    for property, value in pairs(properties) do pcall(function() object[property] = value end) end
                end
            end
            if owned(previous.Root) then
                previous.Root.AssemblyLinearVelocity = Vector3.zero
                previous.Root.AssemblyAngularVelocity = Vector3.zero
            end
        end
        api.Status = reason or "NPC released"
    end

    function api.Attach(model)
        local candidate, reason = api.Check(model)
        if not candidate then return false, reason end
        local controller = reanimate.Character
        if not controller then return false, "start NPC reanimation first" end
        local references = {}
        local available = {[candidate.Root] = true}
        local remaining = table.clone(candidate.Joints)
        for _ = 1, #remaining do
            local progress = false
            for index = #remaining, 1, -1 do
                local joint = remaining[index]
                local p0, p1 = controller:FindFirstChild(joint.Part0.Name), controller:FindFirstChild(joint.Part1.Name)
                if available[joint.Part0] and p0 and p1 then
                    table.insert(references, {Joint = joint, Parent = joint.Part0, Part = joint.Part1, Source0 = p0, Source1 = p1})
                    available[joint.Part1] = true
                    table.remove(remaining, index)
                    progress = true
                end
            end
            if not progress then break end
        end
        if #references == 0 then return false, "NPC joints do not match the current controller rig" end
        api.Detach()
        active = candidate
        active.Hum=candidate.Humanoid
        api.Cur=active
        active.References, active.Poses, active.Properties = references, {}, {}
        active.Properties[candidate.Humanoid] = {AutoRotate = candidate.Humanoid.AutoRotate,
            PlatformStand = candidate.Humanoid.PlatformStand}
        candidate.Humanoid.AutoRotate, candidate.Humanoid.PlatformStand = false, true
        for _, reference in ipairs(references) do
            local joint = reference.Joint
            active.Poses[joint] = {C0 = joint.C0, C1 = joint.C1, Transform = joint.Transform, Enabled = joint.Enabled}
            joint.Enabled = false
        end
        guard.Bind(model)
        api.ActiveNPC, api.Target = model, model
        api.PausedPick = false
        api.Status = "controlling " .. model.Name .. " · ownership observed locally"
        return true
    end

    function api.Fling(target, duration)
        if not api.Running or not settings.NPCFling then return false, "enable NPC target fling first" end
        local part = target and (target:IsA("BasePart") and target or root(target))
        if not part or not owned(root(player.Character)) then return false, "your real root or the target is unavailable" end
        if #api.FlingTargets >= 16 then return false, "the fling queue is full" end
        duration = math.clamp(tonumber(duration) or 2, .1, 10)
        table.insert(api.FlingTargets, {Part = part, Duration = duration})
        return true
    end

    local function restoreFling()
        local previous = flingHome
        flingHome = nil
        if previous and previous.Root.Parent then
            if owned(previous.Root) then
                previous.Root.CFrame = previous.CFrame
                previous.Root.AssemblyLinearVelocity, previous.Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            end
            previous.Root.CanCollide = previous.Collide
        end
    end

    function api.Step(dt)
        if api.Running then holdReal()end
        local controllerRoot = root(reanimate.Character)
        if not controllerRoot then return end
        scanAge += dt
        if active and (not active.Model:IsDescendantOf(world) or not owned(active.Root) or active.Humanoid.Health <= 0) then
            rejected[active.Model] = true
            api.Detach("NPC removed, dead or no longer locally owned")
        end
        if scanAge >= 2.5 then
            scanAge = 0
            if settings.NPCAutoRescan then api.Scan() end
            if not active and settings.NPCAutoPick and not api.PausedPick then
                for _, row in ipairs(api.Scan()) do if api.Attach(row.Model) then break end end
            end
        end
        if active then
            guard.Enforce()
            active.Root.CFrame = controllerRoot.CFrame
            active.Root.AssemblyLinearVelocity = controllerRoot.AssemblyLinearVelocity
            active.Root.AssemblyAngularVelocity = Vector3.zero
