                if not reference.Joint.Parent or not reference.Part.Parent then
                    api.Detach("NPC lost a joint")
                    break
                end
                local offset = reference.Source0.CFrame:ToObjectSpace(reference.Source1.CFrame)
                ctx.Write(reference.Joint, offset)
                reference.Part.CFrame = reference.Parent.CFrame * offset
            end
        end
        local current, now = api.FlingTargets[1], clock()
        if current then
            current.Expires = current.Expires or now + current.Duration
            local realRoot = root(player.Character)
            holdReal()
            if not settings.NPCFling or not current.Part.Parent or not owned(realRoot) or now >= current.Expires then
                table.remove(api.FlingTargets, 1)
            else
                flingHome = flingHome or {Root = realRoot, CFrame = realRoot.CFrame, Collide = realRoot.CanCollide}
                realRoot.CanCollide = true
