        local ok, reason = xpcall(function()
            local realRoot = root(player.Character)
            reanimate.CreateCharacter(realRoot and realRoot.CFrame)
            api.RealCharacter = player.Character
            api.Running, reanimate.Starting = true, false
            if api.Target then
                local attached, why = api.Attach(api.Target)
                if not attached then api.Status = why end
            end
            local failure
            table.insert(connections, ctx.RunService.PreSimulation:Connect(function(dt)
                if failure or reanimate.Stopping then return end
                local success, why = pcall(api.Step, dt)
                if not success then failure = why end
            end))
            while not reanimate.Stopping and not failure and ctx.Alive() do ctx.RunService.Heartbeat:Wait() end
