        restoreReal()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections) table.clear(api.FlingTargets)
        unhook()
        api.Running, api.RealCharacter = false, nil
        reanimate.DestroyCharacter()
        reanimate.Starting = false
        if not ok then api.Status = tostring(reason) ctx.Notify("NPC: " .. api.Status) end
        ctx.Complete(api)
    end

    function api.Config(parent)
        local UI = ctx.UI
        UI.CreateText(parent, "Experimental: controls a locally owned NPC. Games can reclaim ownership; a local pose does not prove other players see it.", 12, Enum.TextXAlignment.Left)
        local rows = {}
        local picker, label = UI.CreateCallbackDropdown(parent, "Owned NPCs", api.Target and api.Target.Name or "Choose", function()
            rows = api.Scan()
            local names = {}
            for _, row in ipairs(rows) do table.insert(names, row.Model.Name .. " · " .. math.floor(row.Distance) .. " studs") end
            if #names == 0 then names[1] = "No owned NPCs in range" end
            return names
        end)
        picker.Event:Connect(function(index)
            local row = rows[index]
            if row then
                api.Target = row.Model
                label.Text = row.Model.Name
                if api.Running then local ok, why = api.Attach(row.Model) if not ok then ctx.Notify(why) end end
            end
        end)
        UI.CreateSlider(parent, "NPC scan radius", settings.NPCRadius, 20, 1000, 10).Changed:Connect(function(value)
            settings.NPCRadius = value ctx.Save()
        end)
        for _, row in ipairs({{"Auto pick another owned NPC", "NPCAutoPick"}, {"Refresh NPCs while running", "NPCAutoRescan"},
            {"Target fling with your real character", "NPCFling"}}) do
            UI.CreateSwitch(parent, row[1], settings[row[2]] == true).Changed:Connect(function(value)
                settings[row[2]] = value ctx.Save()
            end)
        end
        UI.CreateButton(parent, "Rescan NPCs", 18).Activated:Connect(function() table.clear(rejected) api.Scan() end)
        UI.CreateButton(parent, "Release NPC", 18).Activated:Connect(function() api.Target = nil api.PausedPick = true api.Detach() end)
        local status = UI.CreateText(parent, api.Status, 11, Enum.TextXAlignment.Left)
        status.RichText = false
        ctx.AddToRenderStep(function() if status.Text ~= api.Status then status.Text = api.Status end end, status)
        parent.Destroying:Once(function() if not api.Running then unhook() end end)
    end

    function api.ShowHitboxes()
        if active then for _, reference in ipairs(active.References) do ctx.ShowHitbox(reference.Part) end end
    end

    function api.Destroy()
        reanimate.Stopping = api.Running or reanimate.Stopping
        api.Detach() restoreFling() restoreReal() unhook()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
    end
    function api.CancelFling()table.clear(api.FlingTargets)restoreFling()end
    return api
end
