-- Nooby's force-respawn intent, integrated with the real/controller split.
-- A death request is not reported as a successful server respawn: CharacterAdded
-- must supply a different real character, or this operation times out.
return function(ctx)
    local api={Status="ready",Settings=ctx.Saved.Recovery or {},Serial=0,Attempts=0}
    ctx.Saved.Recovery=api.Settings
    api.Settings.Timeout=math.clamp(tonumber(api.Settings.Timeout)or 20,5,90)
    api.Settings.Enabled=api.Settings.Enabled==true
    local clock=ctx.Clock or os.clock
    local connections={}local lastRequest=-math.huge local pending,stuck
    local function real()
        local current=ctx.Reanimate.Current
        return current and (current.ActiveRealCharacter or current.RealCharacter)or ctx.Player.Character
    end
    function api.Request(reason)
        local now=clock()
        if pending then return false,"a respawn request is already pending"end
        if now-lastRequest<5 then return false,"wait a moment before requesting another respawn"end
        local character=real()
        -- Game commands can recover a missing or already-destroyed avatar.
        -- Requiring a live Humanoid first makes that recovery impossible.
        local humanoid=character and character~=ctx.Reanimate.Character and character:FindFirstChildOfClass("Humanoid")
        if not ctx.GameReset and not humanoid then
            return false,"the real character or its humanoid is unavailable"
        end
        lastRequest=now api.Attempts+=1 api.Serial+=1
        pending={Character=character,Started=now,Ticket=api.Serial}
        api.Status="requesting respawn: "..tostring(reason or "manual")
        if ctx.GameReset then
            local ok,accepted=pcall(ctx.GameReset)
            if ok and accepted then api.Status="game reset requested; waiting for a new real character"return true end
            if not humanoid then
                pending=nil
                api.Status="game reset failed: "..tostring(ok and "command was not accepted"or accepted)
                return false,api.Status
            end
        end
        -- Keep failure information instead of swallowing executor signal errors.
        local worked,why=pcall(function()
            humanoid.EvaluateStateMachine=true humanoid.BreakJointsOnDeath=true
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,true)
            humanoid.Health=0 humanoid:ChangeState(Enum.HumanoidStateType.Dead)
        end)
        if ctx.Replicate then
            local ok,err=pcall(function()ctx.Replicate(humanoid.ServerBreakJoints)end)
            if not ok then api.LastSignalError=tostring(err)end
        end
        pcall(function()character:BreakJoints()end)
        if not worked then api.Status="death request failed: "..tostring(why)pending=nil return false,api.Status end
        return true
    end
    function api.Cancel()pending=nil stuck=nil api.Serial+=1 api.Status="recovery cancelled"end
    function api.Step()
        local now=clock()
        if pending then
            local character=ctx.Player.Character
            if character and character~=pending.Character and character~=ctx.Reanimate.Character then
                api.Status="respawn observed"pending=nil stuck=nil
            elseif now-pending.Started>=12 then
                api.Status="respawn not observed; the game may require its own reset command"
                pending=nil stuck=nil
            end
            return
        end
        if not api.Settings.Enabled or not ctx.Reanimate.Starting then stuck=nil return end
        local current=ctx.Reanimate.Current
        if current and current.Name~=api.BackendName then api.BackendName=current.Name stuck=nil end
        local character=real()
        -- Repeated changes mean startup is making progress, not stuck.
        if character~=api.LastCharacter then api.LastCharacter=character stuck=now return end
        stuck=stuck or now
        if now-stuck>=api.Settings.Timeout and now-lastRequest>=5 then
            stuck=now
            if api.Attempts<3 then api.Request("startup stalled")
            else api.Settings.Enabled=false api.Status="automatic recovery paused after 3 attempts"end
        end
    end
    table.insert(connections,ctx.Signal:Connect(api.Step))
    table.insert(connections,ctx.Player.CharacterAdded:Connect(function(character)
        if pending and character~=pending.Character and character~=ctx.Reanimate.Character then
            api.Status="respawn observed"pending=nil stuck=nil
        end
    end))
    function api.Destroy()api.Cancel()for _,connection in ipairs(connections)do connection:Disconnect()end table.clear(connections)end
    return api
end
