    local snapshots,deadStates={},{}
    local function save(object,key,value)
        snapshots[object]=snapshots[object]or {}
        if snapshots[object][key]==nil then snapshots[object][key]={object[key]}end
        if object[key]~=value then object[key]=value end
    end
    local function valid(c)return c.Tool.Parent and c.Handle.Parent==c.Tool end
    local function drop(c,now)
        if c.Drops>=5 then return end
        -- A second drop retries the actual equip/drop transaction, rather than
        -- declaring a still-gripped client-side handle to be claimed.
        local backpack=ctx.Player:FindFirstChild("Backpack")
        if c.Tool.Parent==ctx.Workspace and backpack then
            save(c.Tool,"Parent",backpack)c.Redrop=true
        else save(c.Tool,"Parent",ctx.Workspace)end
        c.Drops+=1 c.NextDrop=now+.75
    end
    function api.Bind(character,now)
        api.Character=character api.Humanoid=character and character:FindFirstChildOfClass("Humanoid")
        api.Phase="waiting"api.Started=now
        -- Claimed tools survive the corpse's replacement; don't kill the new avatar.
        if #api.Claims>0 or api.Attempts>0 then api.Phase="claimed"end
    end
    function api.Step(now)
        for i=#api.Claims,1,-1 do
            local c=api.Claims[i]
            if not valid(c)then
                local handle=c.Tool:FindFirstChild("Handle")
                if c.Tool.Parent and handle and handle:IsA("BasePart")then c.Handle=handle
                else table.remove(api.Claims,i)end
            end
        end
        if api.Phase=="waiting"then
            api.Humanoid=api.Character and api.Character:FindFirstChildOfClass("Humanoid")
            if not api.Character or not api.Humanoid or (api.Humanoid.Health or 0)<=0 then
                api.Status="Corpse Claim: waiting for a live character"return {}
            end
            local found,seen={},{}
            for _,parent in pairs({api.Character,ctx.Player:FindFirstChild("Backpack")})do
                for _,tool in ipairs(parent:GetChildren())do
                    local handle=tool:IsA("Tool")and tool:FindFirstChild("Handle")
                    if handle and handle:IsA("BasePart")and not seen[tool]then seen[tool]=true table.insert(found,tool)end
                end
            end
            table.sort(found,function(a,b)return a.Name<b.Name end)
            for i=1,math.min(6,#found)do
                local tool=found[i]local handle=tool:FindFirstChild("Handle")
                save(tool,"Enabled",true)save(tool,"RequiresHandle",false)save(tool,"Parent",api.Character)
                save(handle,"CanTouch",false)save(handle,"CanCollide",false)save(handle,"CanQuery",false)
                table.insert(api.Claims,{Tool=tool,Handle=handle,Limb=ctx.Limbs[i],Drops=0,NextDrop=0})
            end
            if #api.Claims==0 then api.Status="Corpse Claim: no handled tools; waiting"return {}end
            api.Phase="arming"api.Started=now
        end
        if api.Phase=="arming"then
            if #api.Claims==0 then api.Phase="waiting"api.Status="Corpse Claim: tools disappeared before arming"return {}end
            local ready=true
            for _,c in ipairs(api.Claims)do
                if valid(c)and Claim.IsFree(c.Handle,c.Tool)then ready=false end
            end
