-- Direct Handles may release an avatar's grip, never the Tool's own welds or
-- a connection to unrelated world geometry. A locally disabled grip is not
-- evidence that the resulting assembly is free or locally owned.
local Guard={}
local function endpoint(attachment)
    local part=attachment
    while part and not part:IsA("BasePart")do part=part.Parent end
    return part
end
local function ownerTool(part,tools)
    if not part or not part:IsA("BasePart")then return end
    local parent=part.Parent
    while parent do
        if tools[parent]then return parent end
        if parent:IsA("Tool")then return end
        parent=parent.Parent
    end
end
local function avatarPart(part,character)
    if not part or not part:IsA("BasePart")then return false end
    local parent=part.Parent
    while parent and parent~=character do
        if parent:IsA("Tool")or parent:IsA("Accessory")or parent:IsA("Accoutrement")then return false end
        parent=parent.Parent
    end
    return parent==character
end
local function shellPart(part,character)
    if not part or not part:IsA("BasePart")then return false end
    local parent=part.Parent
    while parent and parent~=character do
        if parent:IsA("Tool")then return false end
        parent=parent.Parent
    end
    return parent==character
end
function Guard.ReleaseTools(tools,character,save)
    if not character then return 0 end
    local selected={}for _,tool in ipairs(tools)do if tool.Parent==character then selected[tool]=true end end
    if not next(selected)then return 0 end
    local released=0
    for _,joint in ipairs(character:GetDescendants())do
        local a,b
        if joint:IsA("JointInstance")or joint:IsA("WeldConstraint")then a,b=joint.Part0,joint.Part1
        elseif joint.ClassName=="RigidConstraint"or joint.ClassName=="AnimationConstraint"then
            a,b=endpoint(joint.Attachment0),endpoint(joint.Attachment1)
        end
        if ownerTool(a,selected)and avatarPart(b,character)or ownerTool(b,selected)and avatarPart(a,character)then
            if joint.Enabled~=false then save(joint,"Enabled",false)released+=1 end
        end
    end
    return released
end
function Guard.IsFree(handle,tool)
    if not handle or not handle.Parent or not tool or not tool.Parent or not handle:IsDescendantOf(tool)then
        return false,"missing handle"
    end
    local root=handle.AssemblyRootPart
    if root and root~=handle and not root:IsDescendantOf(tool)then return false,"joined to "..root.Name end
    local ok,parts=pcall(handle.GetConnectedParts,handle,true)
    if not ok or type(parts)~="table"then return false,"assembly query unavailable"end
    for _,part in ipairs(parts)do
        if part~=handle and not part:IsDescendantOf(tool)then return false,"joined to "..part.Name end
    end
    return true
end
function Guard.CanPark(part,character)
    if not shellPart(part,character)then return false end
    local root=part.AssemblyRootPart
    if root and not shellPart(root,character)then return false end
    local ok,parts=pcall(part.GetConnectedParts,part,true)
    if not ok or type(parts)~="table"then return false end
    for _,connected in ipairs(parts)do
        if not shellPart(connected,character)then return false end
    end
    return true
end
return Guard
