--!optimize 2
LU_NATIVE_COMPILE=true
local Util=require(script.Parent.util)
local RunService=Util.Service("RunService")
local function clipped(object)
    if not object:IsA("GuiObject")then return false end
    local pos,size=object.AbsolutePosition,object.AbsoluteSize local parent=object.Parent
    while parent do
        if parent:IsA("GuiObject")and(parent.ClipsDescendants or parent:IsA("ScrollingFrame"))then
            local p,s=parent.AbsolutePosition,parent.AbsoluteSize
            if pos.X+size.X<=p.X or pos.Y+size.Y<=p.Y or pos.X>=p.X+s.X or pos.Y>=p.Y+s.Y then return true end
        end
        parent=parent.Parent
    end
    return false
end
local queue=require(script.Parent.ui_render_queue)({Visible=Util.IsGuiVisible,Clipped=clipped,
    Error=function(message,callback)warn(Util.Traceback("Uhhhhhh :: Render Step Function Error",message,callback,2))end})
local bindName="Uhhhhhh_Render"..Util.RandomString()
function Util.DestroyUIRender()
    RunService:UnbindFromRenderStep(bindName)queue.Clear()
end
RunService:BindToRenderStep(bindName,Enum.RenderPriority.Last.Value-69,function(dt)
    local policy=Util.UIPerformance if policy then policy.Tick(dt)end
    local profiler=Util.FrameProfiler local started=profiler and profiler.Begin("UI render")
    debug.profilebegin("Uhhhhhh :: Render Step")
    queue.Step(dt,policy and policy.Rate or math.huge)
    debug.profileend()
    if started then profiler.Finish("UI render",started)end
end)
return queue.Add
