-- Data-only music catalogs. A repository never supplies executable music code.
local Music={}
local cacheRoot="UhhhhhhReanim/Muzik/Repositories/"
local function text(value,limit,default)
    value=value==nil and default or value
    assert(type(value)=="string" and #value>0 and #value<=(limit or 120) and not value:find("%c"),"invalid music text")
    return value
end
local function safe(path,empty)
    if type(path)~="string" or (#path==0 and not empty) or path:find("[%c\\:@?#%%]") or path:sub(1,1)=="/" then return false end
    for segment in path:gmatch("[^/]+") do if segment=="." or segment==".." then return false end end
    return not path:find("//",1,true)
end
local function hash(value)
    local a,b=5381,52711
    for i=1,#value do a=(a*33+value:byte(i))%4294967296 b=(b*37+value:byte(i))%4294967296 end
    return string.format("%08x%08x",a,b)
end
local function encode(value)
    return (value:gsub("[^%w_.~%-]",function(c)return string.format("%%%02X",c:byte())end))
end
local function encodePath(value)
    return (value:gsub("[^/]+",encode))
end
local function extension(path)
    return path:lower():match("%.(mp3)$") or path:lower():match("%.(ogg)$") or path:lower():match("%.(wav)$")
end
function Music.Validate(value)
    assert(type(value)=="table","enter music repository settings")
    local repo=text(value.Repo,160):gsub("^https://github%.com/",""):gsub("/+$",""):gsub("%.git$","")
    assert(repo:match("^[%w_.%-]+/[%w_.%-]+$") and not repo:find("..",1,true),"use owner/repository or its GitHub URL")
    local branch=text(value.Branch,160,"main")
    assert(safe(branch) and branch:match("^[%w_./%-]+$"),"invalid branch or commit")
    local mode=value.Mode or "manifest"
    assert(mode=="manifest" or mode=="folder" or mode=="bundled","choose music.json or an audio folder")
    local path=value.Path or (mode=="manifest" and "music.json" or "")
    path=path:gsub("/+$","") assert(safe(path,mode~="manifest"),"invalid music catalog/folder path")
    if mode=="manifest" then assert(path:lower():match("%.json$"),"music catalogs use .json") end
    local name=text(value.Name,80,repo)
    local id="Music_"..hash(repo:lower().."\n"..branch.."\n"..mode.."\n"..path)
    return {Id=id,Name=name,Repo=repo,Branch=branch,Mode=mode,Path=path,Custom=value.Custom==true,
        Tracks=value.Tracks,Origin=value.Origin}
end
function Music.IsAudio(bytes,ext)
    if type(bytes)~="string" or #bytes<128 then return false end
    if ext=="ogg" then return bytes:sub(1,4)=="OggS" end
    if ext=="wav" then return bytes:sub(1,4)=="RIFF" and bytes:sub(9,12)=="WAVE" end
    return ext=="mp3" and (bytes:sub(1,3)=="ID3" or (bytes:byte(1)==255 and bit32.band(bytes:byte(2),224)==224))
end
function Music.new(deps)
    local saved=deps.Saved
    saved.MusicRepositories=type(saved.MusicRepositories)=="table" and saved.MusicRepositories or {}
    saved.DisabledMusicSources=type(saved.DisabledMusicSources)=="table" and saved.DisabledMusicSources or {}
    local api={Sources={},Rows={},States={},Generation=0,Loading=false}
    local markets={}
    local maximum=deps.MaximumBytes or 32*1024*1024
    local function changed()
        if deps.Changed then deps.Changed() end
        if api.Changed then api.Changed() end
    end
    local function raw(source,path,revision)
        return "https://raw.githubusercontent.com/"..source.Repo.."/"..encode(revision or source.Branch).."/"..encodePath(path)
    end
    function api.Enabled(source)
        return source.MarketEnabled~=false and saved.DisabledMusicSources[source.Id]~=true
    end
    local function track(source,value,revision)
        assert(type(value)=="table","invalid music track")
        local title=text(value.Name or value.Title,120)
        local artist=text(value.Artist,120,"Artist unstated")
        local file=value.File
        local url=value.URL or value.Url
        local ext
        if file then
            assert(safe(file),"invalid music file path") ext=extension(file)
            url=raw(source,file,revision)
        else
            assert(type(url)=="string" and #url<=2048 and url:match("^https://[^/]+/") and not url:find("[%c%s]"),"music needs a repository File or HTTPS URL")
            local host=url:match("^https://([^/]+)") assert(not host:find("@",1,true),"invalid music URL")
            ext=extension((url:match("^[^?#]+")))
        end
        assert(ext,"only .mp3, .ogg and .wav music is supported")
        local size=value.Size
        if size~=nil then assert(type(size)=="number" and size==size and size>=128 and size<=maximum and size%1==0,"invalid music file size") end
        local key=source.Id.."/"..hash(url)
        local credit=value.Credit~=nil and text(value.Credit,512) or nil
        local license=value.License~=nil and text(value.License,160) or nil
        local sourceURL=value.SourceURL and text(value.SourceURL,2048) or ("https://github.com/"..source.Repo)
        assert(sourceURL:match("^https://[^/]+"),"invalid music attribution URL")
        return {Key=key,SourceId=source.Id,Source=source.Name,Name=title,Artist=artist,
            Label=title.." — "..artist.." ["..source.Name.."]",URL=url,Extension=ext,Size=size,
            File=cacheRoot..source.Id.."/"..hash(url).."."..ext,
            Credit=credit,License=license,SourceURL=sourceURL}
    end
    local function parse(source,values,revision)
        assert(type(values)=="table" and #values<=512,"a music source supports up to 512 tracks")
        local tracks,seen={},{}
        for _,value in ipairs(values) do
            local row=track(source,value,revision)
            assert(not seen[row.Key],"duplicate music file in catalog") seen[row.Key]=true table.insert(tracks,row)
        end
        return tracks
    end
    local function loadSaved(source)
        local ok,state=pcall(function()
            local bytes=deps.Read(cacheRoot.."Catalogs/"..source.Id..".json")
            assert(#bytes<=1024*1024,"cached music catalog is too large")
            local document=deps.Decode(bytes)
            assert(document.Version==1 and document.SourceId==source.Id,"invalid cached music catalog")
            return {Tracks=parse(source,document.Tracks,source.Branch)}
        end)
        if ok then return state end
    end
    local function saveCatalog(source,rows)
        if not deps.Encode then return end
        local values={}
        for _,row in ipairs(rows) do table.insert(values,{Name=row.Name,Artist=row.Artist,URL=row.URL,Size=row.Size,
            Credit=row.Credit,License=row.License,SourceURL=row.SourceURL}) end
        pcall(deps.MakeFolder,"UhhhhhhReanim/Muzik")pcall(deps.MakeFolder,cacheRoot)pcall(deps.MakeFolder,cacheRoot.."Catalogs")
        local path=cacheRoot.."Catalogs/"..source.Id..".json"
        local bytes=deps.Encode({Version=1,SourceId=source.Id,Tracks=values})
        assert(type(bytes)=="string" and #bytes<=1024*1024,"cached music catalog exceeds 1 MiB")
        deps.Write(path,bytes)assert(deps.Read(path)==bytes,"music catalog cache verification failed")
    end
    function api.Rebuild()
        local sources,seen={},{}
        local function add(value)
            local ok,source=pcall(Music.Validate,value)
            if not ok or seen[source.Id] then return end
            seen[source.Id]=true source.Custom=value.Custom==true source.MarketEnabled=value.MarketEnabled
            table.insert(sources,source)
