-- Shared authoring/playback joint identities. Custom models, nested parts,
-- accessory motors and Bones use one map; duplicate names use relative paths.
return function(ctx)
    local api={States=setmetatable({}, {__mode="k"}),Scans=0}
    local function segment(object)
        local name=object.Name:gsub("%%","%%25"):gsub("/","%%2f"):gsub("#","%%23")
        local ordinal,total=0,0
        for _,sibling in ipairs(object.Parent:GetChildren())do
            if sibling.Name==object.Name then total+=1 if sibling==object then ordinal=total end end
        end
        return name..(total>1 and "#"..ordinal or "")
    end
    local function path(object,rig)
        local parts={} local current=object
        while current and current~=rig do table.insert(parts,1,segment(current))current=current.Parent end
        return current==rig and "@/"..table.concat(parts,"/")or nil
    end
    local function endpoints(joint)
        if joint:IsA("Motor6D")then return joint.Part0,joint.Part1 end
        if joint.ClassName=="AnimationConstraint"and ctx.JointParts then return ctx.JointParts(joint)end
    end
    local function excluded(object,rig)
        local node=object
        while node and node~=rig do
            if node:IsA("Model")and (node:GetAttribute("_UhhhhhhLegacyR6Driver")
                or node:GetAttribute("_UhhhhhhAnimationOnly"))then return true end
            node=node.Parent
        end
        return false
    end
    function api.Release(rig)
        local state=api.States[rig]if not state then return end
        api.States[rig]=nil
        for _,connection in ipairs(state.Connections)do connection:Disconnect()end
        for _,connection in ipairs(state.Watches)do connection:Disconnect()end
    end
    function api.Get(rig)
        if not rig then return nil end
        local state=api.States[rig]
        if not state then
            state={Dirty=true,Connections={},Watches={},Revision=0}api.States[rig]=state
            local function dirty()state.Dirty=true end
            for _,event in ipairs({"DescendantAdded","DescendantRemoving"})do
                table.insert(state.Connections,rig[event]:Connect(dirty))
            end
            table.insert(state.Connections,rig.Destroying:Connect(function()api.Release(rig)end))
        end
        if not state.Dirty then return state end
        for _,connection in ipairs(state.Watches)do connection:Disconnect()end table.clear(state.Watches)
        local nodes,counts,byPart,watches={}, {},{},{}
        local function watch(object,property)
            watches[object]=watches[object]or {}
            if watches[object][property]then return end watches[object][property]=true
            local ok,event=pcall(function()return object:GetPropertyChangedSignal(property)end)
            if ok then table.insert(state.Watches,event:Connect(function()state.Dirty=true end))end
        end
        local function watchPath(object)
            while object and object~=rig do watch(object,"Name")object=object.Parent end
        end
        for _,object in ipairs(rig:GetDescendants())do
            if excluded(object,rig)then continue end
            local p0,p1=endpoints(object)
            if object:IsA("Motor6D")then watch(object,"Part0")watch(object,"Part1")
            elseif object.ClassName=="AnimationConstraint"then
                watch(object,"Attachment0")watch(object,"Attachment1")
                watch(object,"Part0")watch(object,"Part1")
            end
            if p0 and p1 and p0:IsDescendantOf(rig)and p1:IsDescendantOf(rig)then
                table.insert(nodes,{Joint=object,Part=p1,ParentPart=p0,Kind="Motor"})
                counts[p1.Name]=(counts[p1.Name]or 0)+1
                watchPath(p0)watchPath(p1)watchPath(object)
            elseif object:IsA("Bone")then
                table.insert(nodes,{Joint=object,Part=object,ParentPart=object.Parent,Kind="Bone"})
                counts[object.Name]=(counts[object.Name]or 0)+1
                watchPath(object)
            end
        end
        local map,aliases={},{}
        for _,node in ipairs(nodes)do
            local part=node.Part
            -- Nested joints keep their identity when another hat or bone is
            -- added later. A formerly unique "Handle" must not change names.
            node.Name=part.Parent==rig and counts[part.Name]==1 and part.Name or path(part,rig)
            -- A malformed rig may have two motors driving the same part.
            if map[node.Name]then
                node.Name=path(node.Joint,rig).."/joint"
            end
            node.DisplayName=part.Name node.Path=path(part,rig)
            map[node.Name]=node byPart[part]=node
            if counts[part.Name]==1 then aliases[part.Name]=node.Name end
        end
        for _,node in ipairs(nodes)do
            local parent=byPart[node.ParentPart]
            node.Parent=parent and parent.Name or node.ParentPart.Name
        end
        table.sort(nodes,function(a,b)return a.Name<b.Name end)
        state.Nodes,state.ByName,state.ByPart,state.Aliases=nodes,map,byPart,aliases
        state.Revision+=1 state.Dirty=false api.Scans+=1
        return state
    end
    function api.Map(rig)
        local result={}local state=api.Get(rig)
        for name,node in pairs(state and state.ByName or {})do result[name]=node.Joint end
        return result
    end
    function api.Info(rig)
        local state=api.Get(rig)if not state then return end
        local info={Rig=rig,Root=rig:GetPivot(),Scale=rig:GetScale(),Joints={}}
        for _,node in ipairs(state.Nodes)do
            local joint,part,parent=node.Joint,node.Part,node.ParentPart
            local c0,c1,parentWorld,size
            if node.Kind=="Bone"then
                c0,c1=joint.CFrame,CFrame.identity
                parentWorld=parent:IsA("Bone")and parent.TransformedWorldCFrame or parent.CFrame
                size=Vector3.new(.4,.4,.4)
            else
                if ctx.JointFrames then c0,c1=ctx.JointFrames(joint)else c0,c1=joint.C0,joint.C1 end
                parentWorld,size=parent.CFrame,part.Size
            end
            table.insert(info.Joints,{Name=node.Name,Parent=node.Parent,ParentWorld=parentWorld,C0=c0,C1=c1,
                Size=size,Transform=joint.Transform,Kind=node.Kind})
        end
        return info
    end
    function api.Frame(rig,name)
        local state=api.Get(rig)local node=state and state.ByName[state.Aliases[name]or name]
        if not node then return end
        local joint,parent=node.Joint,node.ParentPart
        local base
        if node.Kind=="Bone"then
            base=(parent:IsA("Bone")and parent.TransformedWorldCFrame or parent.CFrame)*joint.CFrame
        else
            local c0=ctx.JointFrames and ctx.JointFrames(joint)or joint.C0
            base=parent.CFrame*c0
        end
        return {Base=base,Part=node.Part,Joint=joint,Rig=rig,Scale=rig:GetScale()}
    end
    function api.Parts(rig)
        local state=api.Get(rig)local result={}
        for _,node in ipairs(state and state.Nodes or {})do
            if node.Kind~="Bone"then table.insert(result,{Name=node.Name,Part=node.Part})end
        end
        return result
    end
    function api.Destroy()
        local rigs={}for rig in pairs(api.States)do table.insert(rigs,rig)end
        for _,rig in ipairs(rigs)do api.Release(rig)end
    end
    return api
end
