-- Shared UI budgets, inspired by Nooby's LowEnd/Governor controls. Physics,
-- animation evaluation and camera/control bindings use their original signals.
return function(ctx)
    local saved=ctx.Saved
    saved.Performance=type(saved.Performance)=="table"and saved.Performance or {}
    local settings=saved.Performance
    local modes={"Automatic","Full","Low End"}
    if not table.find(modes,settings.UI)then settings.UI="Automatic"end
    local api={Settings=settings,Modes=modes,Rows={},Enabled=false,Rate=60,Age=0,Frames=0,Seconds=0,Slow=0,Good=0}
    local clock=ctx.Clock or os.clock
    function api.SetMode(mode)
        assert(table.find(modes,mode),"unknown UI performance mode")
        settings.UI=mode api.Slow,api.Good=0,0
        api.Rate=mode=="Low End"and 30 or mode=="Full"and math.huge or 60
    end
    -- Use the effective budget, including Automatic's sustained-frame decision.
    -- This only controls decoration; pose, camera and physics keep their clocks.
    function api.ReducedEffects()return api.Rate<=30 end
    function api.Tick(dt)
        if type(dt)~="number"or dt~=dt or dt<=0 then return end
        api.Frames+=1 api.Seconds+=dt
        if settings.UI=="Automatic"then
            if dt>1/40 then api.Slow+=dt api.Good=0 else api.Good+=dt api.Slow=math.max(0,api.Slow-dt)end
            if api.Slow>=2 then api.Rate=30 end
            if api.Good>=5 then api.Rate=60 api.Slow=0 end
        end
    end
    function api.Begin(label)
        if api.Enabled then return clock()end
    end
    function api.Finish(label,started)
        if not started then return end
        local elapsed=math.max(0,clock()-started)
        local row=api.Rows[label]or {Calls=0,Total=0,Peak=0}
        row.Calls+=1 row.Total+=elapsed row.Peak=math.max(row.Peak,elapsed)api.Rows[label]=row
    end
    function api.Reset()
        table.clear(api.Rows)api.Frames,api.Seconds=0,0
    end
    function api.Report()
        local lines={string.format("UI: %s, budget %s Hz; %.1f FPS observed",settings.UI,
            api.Rate==math.huge and "native"or tostring(api.Rate),api.Seconds>0 and api.Frames/api.Seconds or 0)}
        local rows={}for name,row in pairs(api.Rows)do table.insert(rows,{Name=name,Row=row})end
        table.sort(rows,function(a,b)return a.Row.Total>b.Row.Total end)
        for _,entry in ipairs(rows)do local row=entry.Row
            table.insert(lines,string.format("%s: %.3f ms/call, %.3f ms peak, %d calls",entry.Name,row.Total/math.max(1,row.Calls)*1000,row.Peak*1000,row.Calls))
        end
        return table.concat(lines,"\n")
    end
    api.SetMode(settings.UI)
    return api
end
