-- Client observations only. This never resets a character, writes physics,
-- fires a remote, installs a spy, or starts a background task.
local State = {}
local function text(value, limit)
    if value == nil then return nil end
    local value = tostring(value)
    limit = limit or 240
    if #value <= limit then return value end
    local stop = limit
    while stop > 0 and value:byte(stop + 1) >= 128 and value:byte(stop + 1) < 192 do stop -= 1 end
    return value:sub(1, stop) .. "…"
end
local function number(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge and value or nil
end
local function point(value)
    if not value then return nil end
    local x, y, z = number(value.X), number(value.Y), number(value.Z)
    if x and y and z then return {X = x, Y = y, Z = z} end
end
local function name(object)
    if not object then return nil end
    local ok, value = pcall(function() return object:GetFullName() end)
    return text(ok and value or object.Name, 320)
end

function State.Follow(clock)
    clock = clock or os.clock
    local api = {Phase = "ready", Generation = 0, Following = 0, Total = 0,
        Joined = 0, Unowned = 0, Missing = 0, History = {}, EverFollowed = false}
    local label = "Ready"
    local function set(phase, following, total, joined, unowned, missing, reason, newBody)
        local changed = phase ~= api.Phase or newBody
        local countsChanged = following ~= api.Following or total ~= api.Total
            or joined ~= api.Joined or unowned ~= api.Unowned or missing ~= api.Missing
        api.Phase, api.Following, api.Total = phase, following, total
        api.Joined, api.Unowned, api.Missing = joined, unowned, missing
        api.Reason, api.ObservedAt = text(reason), clock()
        if changed then
            if #api.History == 16 then table.remove(api.History, 1) end
            table.insert(api.History, {At = api.ObservedAt, Phase = phase, Generation = api.Generation,
                Following = following, Total = total, Joined = joined, Unowned = unowned, Missing = missing})
        end
        if changed or countsChanged then
            if phase == "waiting" then label = "Waiting for loose, owned parts"
            elseif phase == "lost" then label = "Following lost — check reanimation details"
            elseif phase == "following" then label = string.format("Following locally: %d / %d", following, total)
            elseif phase == "partial" then label = string.format("Partial following: %d / %d", following, total)
            elseif phase == "failed" then label = "Failed — check reanimation details"
            elseif phase == "stopped" then label = "Stopped"
            else label = "Ready" end
        end
    end
    function api.Begin(generation)
        api.Generation, api.EverFollowed = generation, false
        set("waiting", 0, 0, 0, 0, 0, nil, true)
    end
    function api.Update(following, total, joined, unowned, missing)
        local phase
        if following > 0 then
            api.EverFollowed = true
            if joined > 0 or unowned > 0 or missing > 0 then phase = "partial" else phase = "following" end
        else phase = api.EverFollowed and "lost" or "waiting" end
        set(phase, following, total, joined, unowned, missing)
    end
    function api.Finish(ok, reason)
        set(ok and "stopped" or "failed", 0, api.Total, api.Joined, api.Unowned, api.Missing, reason)
    end
    function api.Label() return label end
    return api
end

function State.CopyFollow(health)
    if type(health) ~= "table" then return nil end
    local result = {Phase = text(health.Phase), Generation = number(health.Generation),
        Following = number(health.Following), Total = number(health.Total), Joined = number(health.Joined),
        Unowned = number(health.Unowned), Missing = number(health.Missing),
        ObservedAt = number(health.ObservedAt), Reason = text(health.Reason), History = {}}
    for i = math.max(1, #(health.History or {}) - 15), #(health.History or {}) do
        local row = health.History[i]
        table.insert(result.History, {At = number(row.At), Phase = text(row.Phase), Generation = number(row.Generation),
            Following = number(row.Following), Total = number(row.Total), Joined = number(row.Joined),
            Unowned = number(row.Unowned), Missing = number(row.Missing)})
    end
    return result
end

function State.Snapshot(ctx)
    return function()
        local reanimate = ctx.Reanimate
        local backend = reanimate.Current or reanimate.LastBackend
        local controller = reanimate.Character
        local physical = backend and (backend.ActiveRealCharacter or backend.RealCharacter) or ctx.Player.Character
        local result = {Schema = 1, Build = text(ctx.Build()), ObservedAt = number((ctx.Clock or os.clock)()),
            PlaceId = number(ctx.Game.PlaceId), GameId = number(ctx.Game.GameId), PlaceVersion = number(ctx.Game.PlaceVersion),
            ClientObservedOnly = true, Ready = ctx.Ready() == true, Starting = reanimate.Starting == true,
            Stopping = reanimate.Stopping == true, Active = reanimate.Current ~= nil,
            Backend = backend and text(backend.Name), BackendStatus = backend and text(backend.Status),
            Follow = backend and State.CopyFollow(backend.FollowHealth),
            Controller = name(controller), PhysicalCharacter = name(physical), Parts = {}, Animators = {}}
        for animator in pairs(ctx.Animators or {}) do
            if #result.Animators == 12 then result.AnimatorsTruncated = true break end
            local row = {}
            local read, failure = pcall(function()
                local track = animator.track
                local duration = track and number(track.Time)
                local transport = number(animator._lastTrackTime)
                row.Owner = animator._UhhhhhhModuleOwner and text(animator._UhhhhhhModuleOwner.Name)
                row.Playing, row.Paused, row.Looped = animator.playing == true, animator.paused == true, animator.looped == true
                row.TimePosition, row.TrackTime, row.Duration = number(animator.timePosition), transport, duration
                if transport then
                    row.SampleTime = row.Looped and duration and duration > 0 and transport % duration or transport
                end
                row.Rig = name(animator.rig)
                if animator._syncSound then row.SoundTime = number(animator._syncSound.TimePosition) end
            end)
            if not read then row.Error = text(failure) end
            table.insert(result.Animators, row)
        end
        if ctx.Playback then
            local ok, value = pcall(ctx.Playback)
            if ok and type(value) == "table" then
                result.Playback = {Selected = text(value.Selected), Playing = value.Playing == true,
                    RuntimeError = text(value.RuntimeError), AssetError = text(value.AssetError)}
            else result.PlaybackError = text(value) end
        end
        if not physical then return result end
        local ok, reason = pcall(function()
            local humanoid = physical:FindFirstChildOfClass("Humanoid")
            if humanoid then
                local stateOk, state = pcall(humanoid.GetState, humanoid)
                result.Humanoid = {Health = number(humanoid.Health), Rig = text(humanoid.RigType),
                    State = stateOk and text(state) or "unavailable", PlatformStand = humanoid.PlatformStand == true}
            end
            local function capture(part,label,diagnostic)
                local row = {Name = text(label or part.Name),PartName=text(part.Name)}
                local read, failure = pcall(function()
                    local assembly = part.AssemblyRootPart or part
                    row.Position, row.Assembly = point(part.Position), name(assembly)
                    row.Anchored = part.Anchored == true
                    local ageOk, age = pcall(function() return part.ReceiveAge end)
                    if ageOk then row.ReceiveAge = number(age) else row.ReceiveAgeError = text(age) end
                    if ctx.Ownership then
                        local probed, owned, source = pcall(ctx.Ownership, part)
                        if probed then
                            if type(owned) == "boolean" then row.OwnedLocal = owned end
                            row.OwnershipSource = text(source) or "ownership unavailable"
                        else row.OwnershipSource = "probe failed: " .. text(owned) end
                    end
                    if ctx.OwnershipDetail then
                        local detailOk,detail=pcall(ctx.OwnershipDetail,part)
                        if detailOk and type(detail)=="table"then
                            local observed={}
                            for _,key in ipairs({"EngineReadable","EngineOwned","ExecutorRootReadable","ExecutorRootOwned",
                                "ExecutorPartReadable","ExecutorPartOwned","Conflicting","Sleeping","HiddenOwnerReadable"})do
                                if type(detail[key])=="boolean"then observed[key]=detail[key]end
                            end
                            for _,key in ipairs({"EngineOwner","EngineError","HiddenOwnerType"})do observed[key]=text(detail[key])end
                            observed.HiddenOwnerSentinel=number(detail.HiddenOwnerSentinel)
                            row.OwnershipDetail=observed
                        elseif not detailOk then row.OwnershipDetailError=text(detail)end
                    end
                    if diagnostic then
                        row.TargetPosition = point(diagnostic.TargetPosition)
                        row.Skipped, row.SharesWith = diagnostic.Skipped == true, text(diagnostic.SharesWith)
                        row.ExpectedShared=diagnostic.ExpectedShared==true
