            if result.PhysicalParts then
                table.sort(result.PhysicalParts,function(a,b)return a.Name<b.Name end)
            end
            table.sort(result.Parts, function(a, b) return a.Name < b.Name end)
        end)
        if not ok then result.CharacterError = text(reason) end
        return result
    end
end
return State

