    ["UhhhhhhReanim/System/runtime/steve110/main/session_tools.lua"] = [=====[
-- Bounded, cancelable public-server lookup; teleport runs only from a user action.
return function(ctx)
    local settings=type(ctx.SaveData.SessionTools)=="table"and ctx.SaveData.SessionTools or {}ctx.SaveData.SessionTools=settings
    local modes={"Random","Fewest players","Most players","Lowest reported ping"}
    settings.Mode=table.find(modes,settings.Mode)and settings.Mode or modes[1]
    settings.SkipVisited=settings.SkipVisited~=false
    settings.Visited=type(settings.Visited)=="table"and settings.Visited or {}
    local api={Settings=settings,Modes=modes,Busy=false,Status="ready",Servers={}}
    local generation,stopped,loadedAt=0,false,nil
    local clock=ctx.Clock or os.time
    local connection
    local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
    local function key(id)return tostring(ctx.PlaceId).."/"..id end
    local function trim()
        local now=clock()local list={}
        for id,time in pairs(settings.Visited)do
            if type(id)~="string"or not finite(time)or now-time>=3600 or time>now+60 then settings.Visited[id]=nil
            else table.insert(list,{id,time})end
        end
        table.sort(list,function(a,b)return a[2]>b[2]end)
        for i=257,#list do settings.Visited[list[i][1]]=nil end
    end
    trim()
    function api.Candidates()
        trim()local rows={}
        for _,server in ipairs(api.Servers)do
            if server.id~=ctx.JobId and server.playing<server.maxPlayers
                and (not settings.SkipVisited or not settings.Visited[key(server.id)])then table.insert(rows,server)end
        end
        return rows
    end
    function api.Load(force)
        if stopped then return false,"closed"end
        if api.Busy or api.Pending then return false,"a server action is already running"end
        if not finite(ctx.PlaceId)or ctx.PlaceId<=0 then return false,"place id unavailable"end
        if not force and loadedAt and clock()-loadedAt<60 then return true end
        generation+=1 local mine=generation api.Busy=true api.Status="looking for public servers..."
        local servers,seen,cursors={}, {},{}local cursor=nil local more=false
        for page=1,3 do
            local ok,data=pcall(ctx.FetchPage,cursor)
            if mine~=generation or stopped then return false,"lookup canceled"end
            if not ok or type(data)~="table"or type(data.data)~="table"then
                api.Busy=false api.Status="server lookup failed: "..tostring(ok and "invalid response"or data)return false,api.Status
            end
            for index=1,math.min(100,#data.data)do
                local server=data.data[index]
                if type(server)=="table"and type(server.id)=="string"and #server.id>0 and #server.id<=128
                    and not seen[server.id]and finite(server.playing)and finite(server.maxPlayers)
                    and server.playing>=0 and server.maxPlayers>0 then
                    seen[server.id]=true table.insert(servers,{id=server.id,playing=server.playing,maxPlayers=server.maxPlayers,
                        ping=finite(server.ping)and server.ping>=0 and server.ping or nil})
                end
            end
            cursor=data.nextPageCursor
            more=type(cursor)=="string"and #cursor>0
            if not more or cursors[cursor]then break end
            cursors[cursor]=true
        end
        api.Servers=servers loadedAt=clock()api.Busy=false
        api.Status=string.format("%d public servers listed%s",#servers,more and " (first 3 pages)"or "")
        return true
    end
    function api.CancelLookup()
        if api.Pending then return false,"teleport already requested"end
        generation+=1 api.Busy=false api.Status="lookup canceled"return true
    end
    function api.Pick()
        local rows=api.Candidates()if #rows==0 then return nil end
        local mode=settings.Mode
        table.sort(rows,function(a,b)
            local aa,bb
            if mode=="Fewest players"then aa,bb=a.playing,b.playing
            elseif mode=="Most players"then aa,bb=-a.playing,-b.playing
            elseif mode=="Lowest reported ping"then aa,bb=a.ping or math.huge,b.ping or math.huge end
            if aa and aa~=bb then return aa<bb end
            return a.id<b.id
        end)
        if mode=="Random"then return rows[(ctx.Random or math.random)(#rows)]end
        return rows[1]
    end
    local function teleport(id)
        if stopped or api.Busy or api.Pending then return false,"a server action is already running"end
        if type(id)~="string"or #id==0 then return false,"server id unavailable"end
        if settings.AutoExecute then
            if not ctx.QueueTeleport then return false,"teleport resume is unavailable"end
            local queued,reason=ctx.QueueTeleport(settings.ResumeSource)
            if not queued then api.Status=reason return false,reason end
        end
        local previous=settings.Visited[key(id)]
        local pending={Id=id,Previous=previous}api.Pending=pending
        settings.Visited[key(id)]=clock()trim()
        local ok,reason=pcall(ctx.Teleport,id)
        if not ok then
            settings.Visited[key(id)]=previous api.Pending=nil api.Status="teleport failed: "..tostring(reason)
            return false,api.Status
        end
        if api.Pending==pending then api.Status="teleport requested"end
        if ctx.Save then ctx.Save()end
        return true
    end
    function api.Hop()
        local ok,reason=api.Load(false)if not ok then return false,reason end
        local candidate=api.Pick()
        if not candidate then api.Status="no joinable unvisited server found; refresh or turn off skip visited"return false,api.Status end
        return teleport(candidate.id)
    end
    function api.Rejoin()return teleport(ctx.JobId)end
    function api.ClearVisited()table.clear(settings.Visited)if ctx.Save then ctx.Save()end end
    if ctx.TeleportFailed then connection=ctx.TeleportFailed:Connect(function(player,_,message,placeId,options)
        local pending=api.Pending
        if not pending or player~=ctx.Player or placeId~=ctx.PlaceId then return end
        local ok,id=pcall(function()return options and options.ServerInstanceId end)
        if ok and type(id)=="string"and id~=""and id~=pending.Id then return end
        settings.Visited[key(pending.Id)]=pending.Previous api.Pending=nil
        api.Status="teleport failed: "..tostring(message)
        if ctx.Save then ctx.Save()end
    end)end
    function api.Destroy()
        stopped=true generation+=1 api.Busy=false
        if connection then connection:Disconnect()end
    end
    return api
end
