-- Uploaded preferences are data. Cache/install state is not a default profile.
return function(profile)
    assert(type(profile)=="table","default settings must be a table")
    local api={Profile=profile}
    local function copy(value)
        if type(value)~="table"then return value end
        local result={}
        for key,item in pairs(value)do result[key]=copy(item)end
        return result
    end
    function api.Apply(saved)
        if type(saved)~="table"or next(saved)==nil then return copy(profile),true end
        return saved,false
    end
    -- Use the module's declared SaveConfig/LoadConfig contract. An explicit
    -- saved choice wins; new modules keep their non-effect defaults intact.
    local effectFlags={Effects=false,Particles=false,Trails=false,Wings=false,
        CameraShake=false,AfterimageEnabled=false,AfterimageGlowEnabled=false,
        VisualizerEnabled=false,NoEffects=true}
    function api.ModuleConfig(module,saved,effectsOff)
        if type(saved)=="table"and next(saved)~=nil then return saved end
        if effectsOff==nil then effectsOff=profile.CharacterEffectsDefaultOff end
        if effectsOff~=true or type(module.SaveConfig)~="function"
            or type(module.LoadConfig)~="function"then return saved end
        local ok,current=pcall(module.SaveConfig)
        if not ok or type(current)~="table"then return saved end
        local result=table.clone(current)
        local changed=false
        for key,value in pairs(effectFlags)do
            if type(result[key])=="boolean"and result[key]~=value then
                result[key]=value changed=true
            end
        end
        return changed and result or saved
    end
    return api
end
