-- Ordinary mode keeps Steve's control prefabs and familiar settings names.
-- Small settings groups are inline canvases, not another trip through a menu.
local definitions={
    {"reanimation","Reanimator Config",nil},
    {"character","Reanimate Character Settings",nil},
    {"options","Other Options",nil},
    {"motion","Procedural Movement","character"},
    {"gelatekDiagnostics","Gelatek Diagnostics","options"},
    {"playback","Playback",false},
}
local function build(ctx)
    local UI,main=ctx.UI,ctx.Main
    local nav={Pages={},Entries={},Mounted={},Definitions=definitions}
    local function reveal(entry,from)
        UI.Workspace.Open(entry.Page,from or entry.Parent or main)
        if entry.Anchor and UI.Workspace.CurrentPage~=entry.Page then
            UI.Workspace.Back(UI.Workspace.CurrentPage,entry.Page)
        end
        if entry.Anchor then task.defer(function()
            if UI.Workspace.CurrentPage~=entry.Page or not entry.Anchor.Parent then return end
            local page=entry.Page
            local y=page.CanvasPosition.Y+entry.Anchor.AbsolutePosition.Y-page.AbsolutePosition.Y-10
            page.CanvasPosition=Vector2.new(page.CanvasPosition.X,math.max(0,y))
        end)end
    end
    function nav.Open(key,from)reveal(assert(nav.Entries[key],"unknown settings page: "..tostring(key)),from)end
    function nav.Link(parent,key,label)
        local entry=assert(nav.Entries[key],"unknown settings page: "..tostring(key))
        local button=UI.CreateButton(parent,(label or entry.Title).." &gt;",20)
        button.Activated:Connect(function()nav.Open(key,UI.Workspace.ResolvePage(parent)or parent)end)
        return button
    end
    function nav.Attach(key,parent)
        local entry=assert(nav.Entries[key])entry.Parent=parent
        if UI.Workspace.Pages[entry.Page]then UI.Workspace.Pages[entry.Page].Parent=parent end
        UI.Workspace.Owners[entry.Page]=UI.Workspace.Owners[parent]
    end
    function nav.Mount(key,builder)
        if nav.Mounted[key]then return end
        nav.Mounted[key]=true builder(assert(nav.Pages[key]))
    end
    for _,definition in ipairs(definitions)do
        local key,title,parentKey=table.unpack(definition)
        local page=UI.CreatePage()page.Name="Settings_"..key
        local entry={Page=page,Title=title,Parent=type(parentKey)=="string"and nav.Pages[parentKey]or main}
        nav.Pages[key],nav.Entries[key]=page,entry
        if parentKey==nil then UI.Workspace.RegisterRoot("settings/"..key,title,page,Color3.new(.9,.55,.22))end
        if type(parentKey)=="string"then UI.Workspace.Owners[page]=UI.Workspace.Owners[entry.Parent]end
        UI.CreateButton(page,"&lt; Back",20).Activated:Connect(function()
            local state=UI.Workspace.Pages[page]
            UI.Workspace.Back(page,state and state.Parent or entry.Parent)
        end)
        UI.CreateText(page,title,15,Enum.TextXAlignment.Center)
        UI.CreateSeparator(page)
    end
    -- Keep each cluster together even when its controls are created much later.
    local function orderCanvas(canvas,page,order)
        local container=canvas
        while container.Parent and container.Parent~=page do container=container.Parent end
        container.LayoutOrder=order
    end
    local function group(owner,key,title,order)
        local page=nav.Pages[owner]
        local canvas=UI.CreateCanvas(page)canvas.Name="SettingsGroup_"..key orderCanvas(canvas,page,order)
        if key=="camera"or key=="appearance"or key=="teleport"then
