        end
        nav.Pages[key]=canvas
        nav.Entries[key]={Page=page,Anchor=canvas,Title=title,Parent=nav.Entries[owner].Parent,Hidden=true}
        return canvas
    end
    local core=group("character","locomotion","Character",10)
    nav.Pages.interaction=core nav.Entries.interaction=nav.Entries.locomotion
    group("character","camera","Camera",20)
