    ["UhhhhhhReanim/System/runtime/steve110/main/studio_autosave.lua"] = [=====[
-- Two independent recovery slots. A failed or interrupted write keeps the last
-- readable slot. Drafts never overwrite the user's named animation.
return function(deps)
    local api={Age=0,DirtyAt=0,Sequence=0,Enabled=true,Revision=-1,Pending=true}
    local files=deps.Files
    local function read(slot)
        local ok,record=pcall(function()
            local bytes=deps.Read(slot)
            assert(type(bytes)=="string" and #bytes<=36*1024*1024,"invalid draft")
            local sequence,body=bytes:match("^UHH_DRAFT_1 (%d+)\n(.*)$")
            assert(sequence and body,"incomplete draft")
            return {Sequence=tonumber(sequence),Track=files.FromText(body)}
        end)
        return ok and record or nil
    end
    function api.Recover()
        local a,b=read("a"),read("b")
        local record=a and b and (a.Sequence>=b.Sequence and a or b)or a or b
        if record then api.Sequence=math.max(api.Sequence,record.Sequence)end
        return record
    end
    function api.Save(editor,force)
        if not api.Enabled or not editor or not editor.Track or editor.Gesture then return false end
        if not force and api.Revision==editor.Revision and api.Document==editor.DocumentSerial then return false end
        local sequence=api.Sequence+1 local slot=sequence%2==1 and "a" or "b"
        local bytes="UHH_DRAFT_1 "..sequence.."\n"..files.ToText(editor.Track)
        deps.Write(slot,bytes)
        assert(deps.Read(slot)==bytes,"autosave write did not round-trip")
        api.Sequence,api.Revision,api.Document=sequence,editor.Revision,editor.DocumentSerial
        api.LastSaved=deps.Clock and deps.Clock()or os.time()
        api.Error=nil return true
    end
    function api.Tick(dt,editor)
        if not api.Enabled or not editor or not editor.Track then return end
        api.Age+=math.max(0,dt)
        if api.Seen~=editor.Revision or api.SeenDocument~=editor.DocumentSerial then
            api.Seen,api.SeenDocument=editor.Revision,editor.DocumentSerial api.DirtyAt=api.Age
        end
        if api.Age-api.DirtyAt<2 or api.Age-(api.Attempt or -30)<15 then return end
        api.Attempt=api.Age
        local ok,reason=pcall(api.Save,editor,false)
        if not ok then api.Error=tostring(reason)if deps.Report then deps.Report(api.Error)end end
    end
    return api
end
