    local breadcrumb=studio.Label(results,"Local files",12,4,380,26,14,"BrowserBreadcrumb")
    local search=studio.Box(results,"","Search names, descriptions or sources",10,38,400,"AssetSearch")
    local refresh=studio.Button(results,"Refresh",0,38,78,function()view:Open(view.Source,{Pack=view.Pack,Refresh=true})end,"RefreshAssets")
    local back=studio.Button(results,"Catalog",0,4,78,function()view:Open("market")end,"BackToCatalog")
    local sourceMenu
    sourceMenu=studio.Button(results,"Sources",10,4,88,function()
        local entries={}
        for _,choice in ipairs(choices)do table.insert(entries,{choice[1],function()view:Open(choice[2])end})end
        table.insert(entries,{"Manage marketplaces",studio.Repositories})studio.Choices(sourceMenu,entries)
    end,"ChooseBrowserSource")
    local summary=studio.Label(results,"",12,70,380,23,12,"BrowserSummary")
    local list=studio.Scroll(results,"AssetRows")
    local empty=studio.Label(results,"",18,125,380,90,14,"BrowserEmpty") empty.TextWrapped=true
    local actions=studio.Panel(results,"BrowserActions")
    local random=studio.Button(actions,"Random",6,5,86,function()view:Random()end,"RandomResult")
    local stop=studio.Button(actions,"Stop",98,5,70,function()
