    end,"StopBrowserPlayback")
    local inspect=studio.Button(actions,"Details",174,5,78,function()view:ShowDetails()end,"ShowAssetDetails")
    local done=studio.Button(actions,"Editor",0,5,78,function()studio.OpenEditor()end,"ReturnToEditor")
    local heading=studio.Label(info,"Select an animation",12,10,270,52,17,"AssetTitle") heading.TextWrapped=true
    local meta=studio.Label(info,"",12,66,270,48,12,"AssetMetadata") meta.TextWrapped=true
    local description=studio.Label(info,"",12,120,270,170,12,"AssetDescription")
    description.TextWrapped=true description.TextYAlignment=Enum.TextYAlignment.Top
    local detailStatus=studio.Label(info,"",12,296,270,55,12,"AssetLoadStatus") detailStatus.TextWrapped=true
    local primary=studio.Button(details,"Open",12,0,270,function()view:Primary()end,"OpenAsset")
    local edit
    edit=studio.Button(details,"Edit animation",12,0,270,function()
        local row=model.Selected()
        if row and row.Pack then view:Open("pack",{Pack=row.Pack})
