    local hide=studio.Button(details,"Hide",150,0,130,function()view:Hide()end,"HideAsset")
    local configure=studio.Button(details,"Settings / retry",12,0,270,function()view:Configure()end,"ConfigureAsset")
    local function api() return assert(ctx.Sources(),"Marketplace is still starting") end
    local function appendModules(modules)
        local rows={} local source=api()
        for _,module in ipairs(modules) do
            local hidden=source.IsHidden(module)
            if (view.Source=="hidden" and hidden) or (view.Source~="hidden" and not hidden
                and (view.Source~="favorites" or source.IsFavorite(module))) then
                local row=model.Module(module)
                if not row.Author and source.Author then row.Author=source.Author(module)end
                table.insert(rows,row)
            end
        end
        return rows
    end
    function view:SetRows(rows,message)
        model.Set(rows)
        summary.Text=tostring(#model.Filtered).." results"..(message and " · "..message or "")
        self:DrawRows() self:DrawDetails()
    end
    function view:Suspend()
        model.State().Scroll=list.CanvasPosition.Y model.Serial+=1
        if self.Unwatch then self.Unwatch() self.Unwatch=nil end
        if self.InstallUnwatch then self.InstallUnwatch() self.InstallUnwatch=nil end
        self.InstallItem,self.InstallState=nil,nil
    end
    function view:Open(source,options)
        options=options or {}
        source=source or self.Source
        local pack=options.Pack or (source=="pack" and self.Pack)
        self:Suspend() self.Source,self.Pack=source,pack
        if source=="local" then self.Tracks={} end
        if self.Width then self:Layout(self.Width,self.Height) end
        local key=source=="pack" and ("pack/"..pack.File.."@"..pack.Revision) or source
        local state=model.SelectSource(key)
        local serial=model.Serial
        self.SearchSync=true search.Text=state.Query self.SearchSync=false
        list.CanvasPosition=Vector2.new(0,state.Scroll)
        back.Visible=source=="pack"
        breadcrumb.Text=source=="pack" and pack.Name or ({["local"]="Local files",market="Add-ons",
            loaded="Loaded animations",playing="Playing now",favorites="Favorites",hidden="Hidden animations"})[source]
        self:SetRows(model.Rows,"Loading...")
        for i,choice in ipairs(choices) do
            studio.Opacity(sourceButtons[i],(choice[2]==source or (source=="pack" and choice[2]=="market")) and 0 or .55)
        end
        if source=="pack" then
            self.Unwatch=api().Watch(pack,root,function(value)
                if serial~=model.Serial then return end
                self.PackState=value
                local note=value.Busy and "Loading more names..." or "Names loaded; media loads on play"
                if value.Error then note=note.." · "..tostring(value.Error) end
                self:SetRows(appendModules(value.Modules),note)
            end,options.Refresh)
        else
            studio.Async(function()
                if source=="local" then
                    local rows={} for _,name in ipairs(ctx.Files.List()) do table.insert(rows,model.File(name)) end return rows
                elseif source=="market" then
                    local rows={} for _,item in ipairs(api().Catalog(options.Refresh)) do table.insert(rows,model.Pack(item)) end return rows
                elseif source=="playing"then
                    local rows={}
                    for _,clip in ipairs(studio.SourceTools().List())do if clip.Playing then
                        table.insert(rows,{Id="playing/"..tostring(clip.Id),Name=clip.Name,Kind="CLIP",Source=clip.Source,Clip=clip,Author=clip.Author})
                    end end
                    return rows
                else return appendModules(api().Modules()) end
            end,function(rows)
                if serial~=model.Serial then return end
                self:SetRows(rows,source=="market" and api().Status() or nil)
                self.ScrollRestore=true list.CanvasPosition=Vector2.new(0,state.Scroll) self.ScrollRestore=false
                self:DrawRows()
            end)
        end
    end
    function view:DrawRows()
        if not self.Bounds then return end
        local rows=model.Filtered
        list.CanvasSize=UDim2.fromOffset(0,#rows*layout.RowHeight)
        empty.Text=#rows==0 and (self.Source=="local" and ("No matches in "..ctx.Files.Root) or "No matching animations yet. Search also checks descriptions and source names.") or ""
        local first,last=layout.VirtualRange(#rows,layout.RowHeight,list.CanvasPosition.Y,list.AbsoluteSize.Y)
        local used=0
        for i=first,last do
            used+=1 local row=rows[i] local pooled=self.Pool[used]
            if not pooled then
                local button=studio.Button(list,"",0,0,300,function()
                    local current=pooled.Record
                    if current then self:Select(current) end
                end,"AssetRow")
                local name=studio.Label(button,"",8,0,250,28,14,"AssetRowName")
                local kind=studio.Label(button,"",0,0,84,28,11,"AssetRowKind")
                name.Active=false kind.Active=false
                pooled={Button=button,Name=name,Kind=kind} self.Pool[used]=pooled
            end
            pooled.Record=row pooled.Button.Visible=true
            pooled.Name.Text=row.Name pooled.Kind.Text=row.Kind
            studio.Opacity(pooled.Button,model.State().Selected==row.Id and 0 or .65)
            studio.Rect(pooled.Button,2,(i-1)*layout.RowHeight,self.Bounds.Results.W-12,28)
            studio.Rect(pooled.Name,8,0,math.max(80,self.Bounds.Results.W-120),28)
            studio.Rect(pooled.Kind,self.Bounds.Results.W-108,0,84,28)
        end
        for i=used+1,#self.Pool do self.Pool[i].Button.Visible=false end
    end
    function view:Select(row)
        local previous=model.State().Selected
        model.Pick(row.Id) self:DrawRows() self:DrawDetails()
        if row.File or row.Clip then
            self:LoadTrack(row,function()self:DrawDetails()end)
            if previous==row.Id and self.LastPick and os.clock()-self.LastPick<.4 then self:Edit() end
        end
        self.LastPick=os.clock()
    end
    function view:LoadTrack(row,done)
        if self.Tracks[row.Id] then done(self.Tracks[row.Id]) return end
        local serial=model.Serial
        studio.Status("Reading "..row.Name.."...")
        studio.Async(function()return row.Clip and studio.SourceTools().Read(row.Clip)or ctx.Files.Import(row.File)end,function(track)
            if serial~=model.Serial then return end
            self.Tracks[row.Id]=track
            done(track)
        end)
    end
    function view:DrawDetails()
        local row=model.Selected()
        local item=row and row.Pack or (self.Source=="pack" and self.Pack)
        if self.InstallItem~=item then
            if self.InstallUnwatch then self.InstallUnwatch() self.InstallUnwatch=nil end
            self.InstallItem,self.InstallState=item,nil
            if item and api().WatchInstall then
                self.InstallUnwatch=api().WatchInstall(item,root,function(state)
                    self.InstallState=state self:DrawDetails()
                    if studio.Visible and studio.Mode=="browser" and state.Message then studio.Status(state.Message) end
                end)
            end
        end
        heading.Text=row and row.Name or "Select an animation"
        meta.Text=row and (row.Kind.."\n"..(row.Author and ("by "..row.Author.." · ")or "")..(row.Source or "")) or ""
        description.Text=row and row.Description or "Choose a source on the left. Search works with partial names and descriptions."
        detailStatus.Text=""
        primary.Visible=row~=nil
        edit.Visible=row and (row.File~=nil or row.Module~=nil or row.Clip~=nil or row.Pack~=nil) or false
        edit.Text=row and row.Pack and "Stream pack" or "Edit a copy"
        favorite.Visible=row and row.Module~=nil or false hide.Visible=favorite.Visible configure.Visible=favorite.Visible
        if details.Parent then self:LayoutDetails(details.AbsoluteSize.X,details.AbsoluteSize.Y)end
        local installButton=self.InstallButton
        if installButton then
            installButton.Text=self.InstallState and api().InstallCaption(self.InstallState) or "Install this pack"
        end
        if not row then return end
        if row.File or row.Clip then
            local track=self.Tracks[row.Id]
            if track then
                heading.Text=track.Name
