            hide.Text=api().IsHidden(m) and "Unhide" or "Hide"
            primary.Text=m.ModuleType=="MOVESET" and "Use moveset" or "Play dance"
            detailStatus.Text=m._UhhhhhhRuntimeFailure or m._UhhhhhhAssetFailureNotice or (#m.Assets.." media dependencies; loaded on demand")
        else
