        if row.Pack then self:Open("pack",{Pack=row.Pack})return end
        local serial=model.Serial
        studio.EditCopy(row.Clip or row,function()return serial==model.Serial end)
    end
    function view:Favorite()
        local row=assert(model.Selected(),"Select an animation") assert(row.Module,"Select a dance or moveset")
        api().ToggleFavorite(row.Module) self:DrawDetails()
        if self.Source=="favorites" then self:SetRows(appendModules(api().Modules())) end
    end
    function view:Hide()
        local row=assert(model.Selected(),"Select an animation") assert(row.Module,"Select a dance or moveset")
        api().ToggleHidden(row.Module)
