    function view:Random()
        assert(ctx.CanPlay(),"Start reanimation before playing")
        local options={}
        for _,row in ipairs(model.Filtered) do
            if row.Module and row.Module.ModuleType=="DANCE" and not api().IsHidden(row.Module) then table.insert(options,row) end
        end
        if #options==0 then api().Random() return end
        local row=options[math.random(1,#options)] api().Play(row.Module) model.Pick(row.Id)
        self:DrawRows() self:DrawDetails() studio.Status("Selected "..row.Name)
    end
    function view:Configure()
        local row=assert(model.Selected(),"Select a module") assert(row.Module,"Select a dance or moveset")
        studio.Dialog("Module settings",530,function(panel)
            local scroll=studio.Scroll(panel,"ModuleSettings") studio.Rect(scroll,10,45,panel.AbsoluteSize.X-20,390)
            scroll.AutomaticCanvasSize=Enum.AutomaticSize.Y
            local listLayout=ctx.Util.Instance("UIListLayout",scroll) listLayout.SortOrder=Enum.SortOrder.LayoutOrder
            api().Configure(row.Module,scroll)
            studio.Button(panel,"Retry media",12,445,220,function()api().Retry(row.Module)return "Retry queued; play the animation again"end)
            studio.Button(panel,"Close",panel.AbsoluteSize.X-122,445,110,studio.CloseDialog)
        end)
    end
    local install=studio.Button(sources,"Install this pack",8,0,190,function()
        assert(view.Pack,"Open a marketplace pack first")
        local state=api().Install(view.Pack)
        return state and state.Message or "Installing..."
    end,"InstallPack")
    view.InstallButton=install
    function view:ShowDetails()
        if self.Bounds.Right>0 then return end
        studio.Dialog("Animation details",570,function(panel)
            details.Parent=panel details.Visible=true studio.Rect(details,10,40,panel.AbsoluteSize.X-20,465)
            self:LayoutDetails(panel.AbsoluteSize.X-20,465)
            studio.Button(panel,"Close",panel.AbsoluteSize.X-120,514,104,studio.CloseDialog)
            studio.DialogCleanup=function()details.Parent=root self:Layout(self.Width,self.Height)end
        end)
    end
    function view:LayoutDetails(width,height)
        local rows={}
        if primary.Visible then table.insert(rows,{primary})end
        if edit.Visible then table.insert(rows,{edit})end
        if favorite.Visible then table.insert(rows,{favorite,hide})end
        if configure.Visible then table.insert(rows,{configure})end
        local actionHeight=#rows*34+10
        studio.Rect(info,0,0,width,math.max(0,height-actionHeight-8)) info.CanvasSize=UDim2.fromOffset(0,358)
        studio.Rect(heading,12,8,width-24,50) studio.Rect(meta,12,65,width-24,48)
        studio.Rect(description,12,122,width-24,170)
        studio.Rect(detailStatus,12,296,width-24,54)
        for i,row in ipairs(rows)do studio.Row(details,row,12,height-actionHeight+(i-1)*34,width-24,28)end
    end
    function view:Layout(width,height)
        self.Width,self.Height=width,height self.Bounds=layout.Browser(width,height)
        local b=self.Bounds studio.Place(sources,b.Sources) studio.Place(results,b.Results)
        if details.Parent==root then studio.Place(details,b.Details) self:LayoutDetails(b.Right,height) end
        for i,button in ipairs(sourceButtons) do studio.Rect(button,8,48+(i-1)*35,b.Left-16,26) end
        studio.Rect(manage,8,264,b.Left-16,26)
        studio.Rect(sourceHelp,12,302,b.Left-24,78)
        studio.Rect(install,8,390,b.Left-16,28) install.Visible=self.Source=="pack"
        sources.CanvasSize=UDim2.fromOffset(0,self.Source=="pack"and 432 or 388)
        local rw=b.Results.W
        sourceMenu.Visible=b.Left==0
        studio.Rect(sourceMenu,10,4,88,26)
        local captionX=b.Left==0 and 108 or 12
        studio.Rect(breadcrumb,captionX,4,math.max(0,rw-captionX-100),26) studio.Rect(back,rw-88,4,78,26)
        studio.Rect(search,10,38,math.max(50,rw-106),26) studio.Rect(refresh,rw-88,38,78,26)
        studio.Rect(summary,12,70,rw-24,23) studio.Rect(list,6,99,rw-12,height-145)
        studio.Rect(empty,18,125,rw-36,90) studio.Rect(actions,0,height-39,rw,39)
        studio.Rect(done,rw-88,5,78,26)
        inspect.Visible=b.Right==0
        local actionButtons={random,stop}if inspect.Visible then table.insert(actionButtons,inspect)end table.insert(actionButtons,done)
        studio.Row(actions,actionButtons,6,5,rw-12,28)
