    ["UhhhhhhReanim/System/runtime/steve110/main/studio_clone.lua"] = [=====[
-- Clone the selected module's declared dependencies. Commit main.lua last.
return function(deps)
    local api={}
    function api.Clone(module,cancelled,progress)
        local function active()assert(not cancelled or not cancelled(),"clone cancelled")end
        active()
        local source,context=deps.Source(module)
        assert(type(source)=="string"and #source<=4*1024*1024,"module source is unavailable or too large")
        context=context or {Assets={}}
        local key=deps.Unique(module.Name)
        local assets,mapping,seen,total={}, {},{},0
        for _,reference in ipairs(module.Assets or {})do
            active()
            if not seen[reference]then
                assert(#assets<256,"this module has over 256 media files; clone individual clips instead")
                seen[reference]=true
                local bytes=deps.ReadAsset(reference,cancelled)
                total+=#bytes assert(total<=256*1024*1024,"module clone exceeds 256 MiB; clone individual clips instead")
                local basename=(reference:match("^[^@]+")or reference):match("[^/]+$")or "asset"
                basename=basename:gsub('[^%w_.%-]','_'):sub(-112)
                local localRef="StudioClones/"..key.."/"..(#assets+1).."_"..basename
                table.insert(assets,{Reference=localRef,Bytes=bytes})mapping[reference]=localRef
                if progress then progress(#assets,#module.Assets)end
            end
        end
        local remap={}
        for name,reference in pairs(context.Assets or {})do if mapping[reference]then remap[name]=mapping[reference]end end
        for reference,localRef in pairs(mapping)do remap[reference]=localRef end
        for reference,localRef in pairs(mapping)do
            local name=reference:match("^[^@]+")or reference remap[name]=localRef
            local leaf=name:match("[^/]+$")
            if leaf and remap[leaf]==nil then remap[leaf]=localRef
            elseif leaf and remap[leaf]~=localRef then remap[leaf]=false end
        end
        for name,reference in pairs(remap)do if not reference then remap[name]=nil end end
        local cloneContext={Assets=remap,Directory=context.Directory,Provider=context.Provider or "Local clone",
            Revision=context.Revision,SourceLabel="Cloned: "..(module._UhhhhhhSource or module.Name),
            Author=deps.Author and deps.Author(module)}
        local contextKey="Clones/"..key
        local wrapped="-- UHH_MARKET_CONTEXT "..contextKey.."\n-- Editable copy; original source and credits follow.\n"
            .."local factories=(function()\n"..source.."\nend)()\nlocal copies={}\n"
            .."for i,factory in ipairs(factories)do copies[i]=function(...)local m=factory(...)\n"
            .."m.Name=m.Name..' (copy)' m.Hash=nil m.InternalName='StudioClone/'.."..string.format("%q",key).."..'/'..(m.InternalName or i)\n"
            .."return m end end\nreturn copies\n"
        active()
        return deps.Commit(key,wrapped,assets,cloneContext,contextKey)
    end
    return api
end
