-- Original editor authoring model. ApexEngine supplies its MPL curve evaluator.
return function(ctx)
    local api={Channels={"px","py","pz","rx","ry","rz"}}
    local indexes=setmetatable({},{__mode="k"})
    local function engine(path)return ctx.Require("main/apex_engine/"..path)end
    local function finite(n,lo,hi)
        assert(type(n)=="number"and n==n and n>=lo and n<=hi,"authoring value is out of range")return n
    end
    local function copy(value,seen,budget,depth)
        if type(value)~="table"then
            assert(type(value)=="string"or type(value)=="boolean"or type(value)=="number","expected authoring data")
