    local function floating(name,panel,grip)
        studio.Drag(grip,function()
            if panel.Parent~=root then return nil end -- The narrow-window Values drawer is modal.
            local p,s=panel.Position,panel.AbsoluteSize
            local bounds=studio.Floating[name]
            if not bounds then
                bounds={X=p.X.Offset,Y=p.Y.Offset,W=name=="Timeline"and math.min(s.X,900)or s.X,H=s.Y}
                studio.Floating[name]=bounds
            end
            panel.ZIndex=140
            return {X=bounds.X,Y=bounds.Y}
        end,function(start,delta)
            local bounds=studio.Floating[name]
            bounds.X,bounds.Y=start.X+delta.X,start.Y+delta.Y
            view:Layout(view.Width,view.Height)view:DrawTimeline()
        end)
    end
