    viewport.InputBegan:Connect(function(input)
        if not view.Picking or not studio.Visible or studio.Mode~="editor"then return end
        if studio.Modal or studio.Popup or studio.MakerDock or(view.Workbench and view.Workbench.Tab=="IK")then return end
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        if view.TransformDrag then return end -- Another finger cannot replace a captured gesture.
        local point=view:Point(input)
        local vp,vs=viewport.AbsolutePosition,viewport.AbsoluteSize
        if point.Y<vp.Y+(view.CaptionHeight or 90)or point.X<vp.X or point.X>vp.X+vs.X or point.Y>vp.Y+vs.Y then return end
        view:DrawGizmo()
        if view.NativeGizmo then
            local axis=view.NativeGizmo.HitTest(point,function(world)return view:Project(world)end,
                input.UserInputType==Enum.UserInputType.Touch and 18 or 9)
            if axis then
                studio.Run(function()view:StartTransform(input,axis)end)return
            end
        end
        for _,button in pairs(view.Handles)do
            local p,s=button.AbsolutePosition,button.AbsoluteSize
            if button.Visible and point.X>=p.X and point.X<=p.X+s.X
                and point.Y>=p.Y and point.Y<=p.Y+s.Y then return end
        end
        studio.Run(function()
            assert(ctx.SelectionParts and ctx.Camera,"World limb picking is unavailable")
            local camera=assert(ctx.Camera(),"Camera is unavailable")
            local ray=view:Ray(point)
            local hit=ctx.Require("main/studio_selection").Nearest(ctx.SelectionParts(editor.DetectedRig),ray.Origin,ray.Direction)
            assert(hit,"No body part under the pointer; start reanimation or use the joint tree")
            assert(table.find(editor:Joints(),hit.Name),"Body part does not belong to this clip's rig")
            view:SelectJoint(hit.Name,hit.Part)
            view:StartTransform(input)
            return "Selected "..hit.Name
        end)
    end)
    local dragging,scrubQueued,pendingTime,releaseScrub
    function view:CancelScrub(commit)
        if commit and pendingTime then at(pendingTime)end
        if releaseScrub then releaseScrub()releaseScrub=nil end
        dragging=nil pendingTime=nil
    end
    local function pointerTime(input)
        pendingTime=math.clamp((view:Point(input).X-grid.AbsolutePosition.X+grid.CanvasPosition.X-8)/view.Zoom,0,editor.Track.Time)
        if scrubQueued then return end
        scrubQueued=true
        task.defer(function()
            scrubQueued=false
            if pendingTime and root.Parent and studio.Visible and studio.Mode=="editor"then at(pendingTime)end
        end)
    end
    scrub.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            studio.CancelInteractions()dragging=input releaseScrub=studio.HoldScroll(studio.Body)pointerTime(input)
        end
    end)
    studio.Connect(root,ctx.Input.InputChanged,function(input)
        local drag=view.TransformDrag
        if drag and (input==drag.Input or (drag.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement))then
            local ok=studio.Run(function()view:MoveTransform(input)end)
            if not ok then view:FinishTransform(false)end
        elseif studio.Visible and studio.Mode=="editor"then
            view:DrawGizmo()
            if view.NativeGizmo and input.UserInputType==Enum.UserInputType.MouseMovement then
                view.HoverAxis=view.NativeGizmo.HitTest(view:Point(input),function(world)return view:Project(world)end,9)
            end
        end
        if dragging and studio.Visible and studio.Mode=="editor" and (input.UserInputType==Enum.UserInputType.MouseMovement or input==dragging) then
            studio.Run(function()pointerTime(input)end)
        end
    end)
    studio.Connect(root,ctx.Input.InputEnded,function(input)
        if input==dragging then view:CancelScrub(true)end
        local drag=view.TransformDrag
        if drag and (input==drag.Input or (drag.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1))then
            studio.Run(function()view:MoveTransform(input)end)view:FinishTransform(true)
        end
    end)
    if ctx.Input.WindowFocusReleased then studio.Connect(root,ctx.Input.WindowFocusReleased,function()
        view:CancelScrub()view:FinishTransform(false)
    end) end
    local function updateFormCanvas()
        local height
        if view.Inspector=="events" then height=160+#editor.Track.Markers*(view.EventRowHeight or 32)
        else height=math.max(330,(view.Inspector=="clip"and view.ClipFormHeight or view.PoseFormHeight or 315)+15)end
        form.CanvasSize=UDim2.fromOffset(0,height)
        studio.ClampScroll(form)
