    function view:LayoutValues(width,height)
        self.ValueLabelWidths=self.ValueLabelWidths or setmetatable({},{__mode="k"})
        studio.Rect(valuesGrip,10,0,width-20,24)
        for i,tab in ipairs(tabs) do studio.Rect(tab,6+(i-1)*(width-12)/3,28,(width-18)/3,26) end
        studio.Rect(form,0,60,width,math.max(0,height-102))
        studio.Rect(keyButton,8,height-34,width-16,26) keyButton.Visible=self.Inspector=="joint"
        -- The scroll bar reserves real width. Reflow existing fields rather
        -- than shrinking three numeric columns below a usable input width.
        local contentWidth=math.max(1,width-form.ScrollBarThickness)
        local padding=math.min(10,contentWidth*.1)
        local available=math.max(1,contentWidth-padding*2)
        local gap,minimum=6,60
        local columns=math.clamp(math.floor((available+gap)/(minimum+gap)),1,3)
        local column=(available-gap*(columns-1))/columns
        local rows=math.ceil(3/columns)
        local groupY=53
        for group,prefix in ipairs({"p","r"}) do
            studio.Rect(poseGroupLabels[group],padding,groupY,available,22)
            for i,axis in ipairs({"x","y","z"}) do
                local x=padding+((i-1)%columns)*(column+gap)
                local y=groupY+math.floor((i-1)/columns)*50
                studio.Rect(self.AxisLabels[prefix..axis],x,y+22,column,16)
                studio.Rect(self.Fields[prefix..axis],x,y+40,column,26)
            end
            groupY+=76+(rows-1)*50
        end
        local weightY=groupY+2
        studio.Rect(weightCaption,padding,weightY,available,20)
        local fieldY,directionY=weightY+25,weightY+60
        if available>=64+8+80 then
            studio.Rect(self.Fields.weight,padding,fieldY,64,26)
            studio.Rect(self.StyleButton,padding+72,fieldY,available-72,26)
        else
            studio.Rect(self.Fields.weight,padding,fieldY,available,26)
            studio.Rect(self.StyleButton,padding,fieldY+32,available,26)
            directionY=fieldY+64
        end
        studio.Rect(self.DirectionButton,padding,directionY,available,26)
        self.PoseFormHeight=directionY+48
        studio.Rect(poseForm,0,0,contentWidth,self.PoseFormHeight)
        studio.Rect(clipName,padding,34,available,26)
        studio.Rect(fpsCaption,padding,69,available,20)
        local clipY=94
        if available>=minimum*2+8 then
            local fpsWidth=math.min(90,(available-8)/2)
            studio.Rect(fps,padding,clipY,fpsWidth,26)
            studio.Rect(loop,padding+fpsWidth+8,clipY,available-fpsWidth-8,26)
        else
            studio.Rect(fps,padding,clipY,available,26)
            clipY+=32 studio.Rect(loop,padding,clipY,available,26)
        end
        clipY+=40 studio.Rect(applyClip,padding,clipY,available,26)
        clipY+=44 studio.Rect(timingCaption,padding,clipY,available,20)
        clipY+=25
        if available>=minimum*2+8 then
            local half=(available-8)/2
            studio.Rect(duration,padding,clipY,half,26)
            studio.Rect(retime,padding+half+8,clipY,half,26)
        else
            studio.Rect(duration,padding,clipY,available,26)
            clipY+=32 studio.Rect(retime,padding,clipY,available,26)
        end
        local metric=self.ClipNoteMetric
        if not metric or metric.Width~=available or metric.Text~=projectNote.Text
            or metric.TextSize~=projectNote.TextSize or metric.Measure~=ctx.MeasureText then
            metric={Width=available,Text=projectNote.Text,TextSize=projectNote.TextSize,Measure=ctx.MeasureText,Height=40}
            if ctx.MeasureText then
                local ok,bounds=pcall(ctx.MeasureText,projectNote.Text,projectNote.TextSize,available)
                if ok and bounds then metric.Height=math.max(metric.Height,math.ceil(bounds.Y)+4)end
            end
            self.ClipNoteMetric=metric
        end
        clipY+=42 studio.Rect(projectNote,padding,clipY,available,metric.Height)
        self.ClipFormHeight=clipY+metric.Height+15
        studio.Rect(clipForm,0,0,contentWidth,self.ClipFormHeight)
        self.ValuesContentWidth=contentWidth
        self.EventRowHeight=contentWidth>=60+30+8+16 and 32 or 64
        studio.Rect(eventsForm,0,0,contentWidth,160+#editor.Track.Markers*self.EventRowHeight)
        studio.Rect(eventName,padding,34,available,26)
        studio.Rect(eventValue,padding,68,available,26)
        studio.Rect(addEvent,padding,104,available,26)
        studio.Rect(eventList,0,146,contentWidth,#editor.Track.Markers*self.EventRowHeight)
        for _,parent in ipairs({poseForm,clipForm,eventsForm})do for _,label in ipairs(parent:GetChildren())do
            if label:IsA("TextLabel")then
                local p,s=label.Position,label.Size
                local axis=false for _,candidate in pairs(self.AxisLabels)do if candidate==label then axis=true break end end
                if not axis and not fluidValueLabels[label]and p.X.Scale==0 and s.X.Scale==0 then
                    self.ValueLabelWidths[label]=self.ValueLabelWidths[label]or s.X.Offset
                    studio.Rect(label,p.X.Offset,p.Y.Offset,math.max(0,math.min(self.ValueLabelWidths[label],contentWidth-p.X.Offset-padding)),s.Y.Offset)
                end
            end
        end end
        updateFormCanvas()
    end
