    function view:SetSelectionVisible(visible)
        if self.SelectionBox then self.SelectionBox.Visible=visible and self.SelectionBox.Adornee~=nil end
        if not visible then
            for _,button in pairs(self.Handles)do button.Visible=false end
            if self.NativeGizmo then self.NativeGizmo.Hide()end
        else self:DrawGizmo()end
    end
    function view:SelectJoint(name,pickedPart)
        self:FinishTransform(false)
        self.Selected=name self.Inspector="joint"
        -- Reveal a clicked joint even when its parent was collapsed.
        for _,joint in ipairs(editor:Hierarchy())do self.Collapsed[joint.Name]=nil end
        updatePose() self:Refresh()
        self:UpdateSelection(pickedPart)
    end
    function view:UpdateSelection(pickedPart)
        local name=self.Selected
        self.OutlinedJoint=name
        if ctx.SelectionParts then
            local part=pickedPart
            if not part then
                for _,entry in ipairs(ctx.SelectionParts(editor.DetectedRig))do if entry.Name==name then part=entry.Part break end end
            end
            if part then
                if not self.SelectionBox then
                    self.SelectionBox=ctx.Util.Instance("SelectionBox",ctx.ScreenGui)
                    self.SelectionBox.Name="EditorSelectedJoint"self.SelectionBox.LineThickness=.035
                    self.SelectionBox.Color3=Color3.fromRGB(255,188,66)self.SelectionBox.SurfaceTransparency=1
                end
                self.SelectionBox.Adornee=part self:SetSelectionVisible(studio.Visible and studio.Mode=="editor")
            elseif self.SelectionBox then self.SelectionBox.Visible=false end
        end
    end
    function view:DrawTree()
        if not studio.Visible or studio.Mode~="editor"then return end
        local valid,visible={},{}
        for _,name in ipairs(editor:Joints())do valid[name]=true end
        for name,pooled in pairs(self.TreePool)do
            if not valid[name]then
                studio.Destroy(pooled.Button)if pooled.Collapse then studio.Destroy(pooled.Collapse)end self.TreePool[name]=nil
            end
        end
        local query=jointSearch.Text:lower() local count=0
        for _,joint in ipairs(self:JointRows(query~="")) do
            local name,depth=joint.Name,math.min(joint.Depth,6)
            if name:lower():find(query,1,true) then
                local x=4+depth*10
                visible[name]=true
                local pooled=self.TreePool[name]
                if not pooled then
                    local row=studio.Button(tree,name,0,0,100,function()self:SelectJoint(name)end,"Joint_"..name)
                    studio.FontSize(row,12)row.TextXAlignment=Enum.TextXAlignment.Left
                    pooled={Button=row}self.TreePool[name]=pooled
                end
                if joint.Children>0 then
                    if not pooled.Collapse then pooled.Collapse=studio.Button(tree,"",0,0,20,function()
                        self.Collapsed[name]=not self.Collapsed[name] self:DrawTree() self:DrawTimeline()
                    end,"Collapse_"..name)end
                    pooled.Collapse.Text=self.Collapsed[name]and "▸"or "▾"pooled.Collapse.Visible=true
                    studio.Rect(pooled.Collapse,x,count*29,20,26)
                elseif pooled.Collapse then pooled.Collapse.Visible=false end
                local row=pooled.Button row.Visible=true
                studio.Rect(row,x+20,count*29,math.max(0,self.Bounds.Left-x-38),26)
                studio.Opacity(row,name==self.Selected and 0 or .65)
                count+=1
            end
        end
        for name,pooled in pairs(self.TreePool)do if not visible[name]then
            pooled.Button.Visible=false if pooled.Collapse then pooled.Collapse.Visible=false end
        end end
        tree.CanvasSize=UDim2.fromOffset(0,count*29)
    end
    function view:JointRows(expanded)
        local out,skip={},nil
        for _,joint in ipairs(editor:Hierarchy()) do
            if skip and joint.Depth<=skip then skip=nil end
            if not skip then
                table.insert(out,joint)
                if not expanded and self.Collapsed[joint.Name] then skip=joint.Depth end
            end
        end
        return out
    end
    function view:DrawTimeline()
        if not self.Width or not root.Parent or not root.Visible or not studio.Visible or studio.Mode~="editor" then return end
        local all=self:JointRows() local rows=#all+1
        local canvasWidth=math.max(grid.AbsoluteSize.X,editor.Track.Time*self.Zoom+80)
        grid.CanvasSize=UDim2.fromOffset(canvasWidth,rows*layout.JointRowHeight)
        names.CanvasSize=UDim2.fromOffset(0,rows*layout.JointRowHeight)
        studio.ClampScroll(grid)studio.ClampScroll(names)
        local first,last=layout.VirtualRange(rows,layout.JointRowHeight,grid.CanvasPosition.Y,grid.AbsoluteSize.Y)
        local from=(grid.CanvasPosition.X-8)/self.Zoom local to=(grid.CanvasPosition.X+grid.AbsoluteSize.X-8)/self.Zoom
        local used,labels=0,0
        local function keyWidget(t,row,name,count)
            used+=1 local pooled=self.KeyPool[used]
            if not pooled then
                local button=studio.Button(grid,"◆",0,0,14,function()
                    if pooled then
                        if pooled.PointerActivated then pooled.PointerActivated=nil return end
                        at(pooled.Time,pooled.Joint)
                    end
                end,"TimelineKey")
                studio.FontSize(button,12)pooled={Button=button} self.KeyPool[used]=pooled
                button.InputBegan:Connect(function(input)
                    if view.KeySelection then studio.Run(function()view.KeySelection.BeginKey(pooled,input)end)end
                end)
            end
            pooled.Time,pooled.Joint=t,name
            local button=pooled.Button
            button.Text=self.KeySelection and self.KeySelection.IsSelected(t,name)and "◈"or (count>1 and "◇"or "◆")
            local displayed=self.KeySelection and self.KeySelection.PreviewTime(t,name)or t
            studio.Opacity(button,1) button.Visible=true
            studio.Rect(button,8+displayed*self.Zoom-7,(row-1)*layout.JointRowHeight+3,14,19)
        end
        for row=first,last do
            labels+=1 local pooled=self.LabelPool[labels]
            if not pooled then
                local label=studio.Node("TextButton",names,"TrackLabel") studio.FontSize(label,12)label.Text=""
                label.Activated:Connect(function()if pooled.Joint then studio.Run(function()view:SelectJoint(pooled.Joint)end)end end)
                pooled={Button=label} self.LabelPool[labels]=pooled
            end
            local label=pooled.Button
            local joint=all[row-1] local name=joint and joint.Name
            pooled.Joint=name
            label.Text=joint and (string.rep("  ",math.min(joint.Depth,6))..name) or "All joints" label.Visible=true
            studio.Rect(label,8,(row-1)*layout.JointRowHeight,self.Bounds.LabelWidth-16,layout.JointRowHeight)
            local line=self.RowLines[labels]
            if not line then
                line=studio.Node("Frame",grid,"TrackGuide") line.BackgroundTransparency=.88
                line.ZIndex=grid.ZIndex ctx.Theme.ApplyFrame(line,{FillText=true}) self.RowLines[labels]=line
            end
            line.Visible=true studio.Rect(line,0,row*layout.JointRowHeight-1,canvasWidth,1)
            local samples=name and editor.TimelineIndex[name] or editor.TimelineFrames
            for _,key in ipairs(layout.Keys(samples,from,to,self.Zoom)) do keyWidget(key.Time,row,name,key.Count) end
        end
        for i=used+1,#self.KeyPool do self.KeyPool[i].Button.Visible=false end
        for i=labels+1,#self.LabelPool do self.LabelPool[i].Button.Visible=false end
        for i=labels+1,#self.RowLines do self.RowLines[i].Visible=false end
        local minimum=64/self.Zoom
        local power=10^math.floor(math.log10(minimum))local step=power*10
        for _,multiple in ipairs({1,2,5,10})do if power*multiple>=minimum then step=power*multiple break end end
        local ticks=0
        for i=math.floor(from/step),math.ceil(to/step) do
            local t=i*step
            ticks+=1 local label=self.RulerPool[ticks]
            if not label then label=studio.Label(ruler,"",0,0,55,22,11,"RulerTick")self.RulerPool[ticks]=label end
            label.Visible=true label.Text=string.format("%.1f",t)
            studio.Rect(label,t*self.Zoom-grid.CanvasPosition.X+11,0,55,22)
        end
        for i=ticks+1,#self.RulerPool do self.RulerPool[i].Visible=false end
        self:Tick()
    end
    function view:Tick()
        if not studio.Visible or studio.Mode~="editor" then return end
        clock.Text=string.format("%.3f / %.3f s",editor.Time,editor.Track.Time)
        if ctx.Input:GetFocusedTextBox()~=seek then seek.Text=string.format("%.3f",editor.Time) end
        frameLabel.Text=string.format("Frame %d · %g fps",math.round(editor.Time*editor.FPS),editor.FPS)
        studio.Rect(playhead,8+editor.Time*self.Zoom,0,2,math.max(grid.AbsoluteSize.Y,grid.CanvasSize.Y.Offset))
        self:DrawGizmo()
    end
    function view:DrawEvents()
        if not studio.Visible or studio.Mode~="editor"then return end
        local used=0
        if self.Inspector=="events" then
            local rowHeight=self.EventRowHeight or 32
            local first,last=layout.VirtualRange(#editor.Track.Markers,rowHeight,math.max(0,form.CanvasPosition.Y-146),form.AbsoluteSize.Y)
            for i=first,last do
                used+=1 local marker=editor.Track.Markers[i] local pooled=self.EventPool[used]
                if not pooled then
                    local seek=studio.Button(eventList,"",8,0,200,function()at(pooled.Time)end)
                    local remove=studio.Button(eventList,"×",0,0,30,function()
                        editor:Edit(function(track)ctx.Files.Track.removeMarker(track,pooled.Index)end)refresh()
                    end)
                    pooled={Seek=seek,Remove=remove} self.EventPool[used]=pooled
                end
                pooled.Index,pooled.Time=i,marker.Time
                pooled.Seek.Text=string.format("%.2f  %s",marker.Time,marker.Name)
                pooled.Seek.Visible=true pooled.Remove.Visible=true
                local width=self.ValuesContentWidth or values.AbsoluteSize.X-form.ScrollBarThickness
                local y=(i-1)*rowHeight
                if rowHeight==32 then
                    studio.Rect(pooled.Seek,8,y,math.max(1,width-62),26)
                    studio.Rect(pooled.Remove,width-46,y,30,26)
                else
                    studio.Rect(pooled.Seek,8,y,math.max(1,width-16),26)
                    studio.Rect(pooled.Remove,8,y+32,math.max(1,width-16),26)
                end
            end
        end
        for i=used+1,#self.EventPool do self.EventPool[i].Seek.Visible=false self.EventPool[i].Remove.Visible=false end
    end
    function view:Refresh()
        local all=editor:Joints()
        if not table.find(all,self.Selected) then self.Selected=all[1] end
        self.Loop=editor.Track.Looped~=false
        clipName.Text=editor.Track.Name fps.Text=tostring(editor.FPS) duration.Text=tostring(editor.Track.Time)
        loop.Text="Loop: "..(self.Loop and "On" or "Off")
        poseForm.Visible=self.Inspector=="joint" clipForm.Visible=self.Inspector=="clip" eventsForm.Visible=self.Inspector=="events"
        updateFormCanvas()
        if self.Document~=editor.DocumentSerial then self.Document=editor.DocumentSerial self.RotationRefs={} self:Command("fit",true) end
        if self.OutlinedJoint~=self.Selected then self:UpdateSelection()end
        updatePose() self:DrawTree() self:DrawTimeline() self:Layout(self.Width,self.Height) self:Tick() self:DrawEvents()
        if self.Workbench then self.Workbench.Refresh()end
    end
    function view:Command(command,noRefresh)
        if self.KeySelection and table.find({"select-all","copy-keys","paste-keys","duplicate-selected","delete-selected"},command)then
            return self.KeySelection.Command(command)
        end
        if command=="tool-select"then return self:SetTool("Select")
        elseif command=="tool-move"then return self:SetTool("Move")
        elseif command=="tool-rotate"then return self:SetTool("Rotate")end
        self:FinishTransform(false)
        if command=="undo" then editor:Undo()
        elseif command=="redo" then editor:Undo(true)
        elseif command=="copy" then
            assert(self.Selected,"Select a joint") local cf,pose=editor:PoseAt(self.Selected,editor.Time) self.Clipboard={cf,pose}
        elseif command=="paste" then
