        studio.Button(parent,"+ Effect",10,32,100,function()edit(nil)end,"AddTimelineEffect")
        studio.Button(parent,"Music",120,32,90,function()studio.Maker('vfx')end,"EditTimelineMusic")
        local list=studio.Scroll(parent,"EffectsTracks")studio.Rect(list,8,66,w-16,h-74)
        local length=math.max(editor.Track.Time,1)local labelWidth=math.min(160,w*.3)local usable=w-labelWidth-45
        list.CanvasSize=UDim2.fromOffset(0,#(editor.Track.Effects or {})*36+28)
        for i,effect in ipairs(editor.Track.Effects or {})do
            studio.Label(list,effect.Kind..' / '..effect.Anchor,2,(i-1)*36,labelWidth-8,30,12)
            local duration=effect.Kind=='Burst'and effect.Lifetime or effect.Duration
            local left=labelWidth+effect.At/length*usable local width=math.max(24,duration/length*usable)
            local button=studio.Button(list,string.format('%.2fs',effect.At),left,(i-1)*36+2,width,function()
                local item=api.Bars[i]
                if item.Pointer then item.Pointer=nil return end
                editor:Seek(effect.At)edit(i)
            end,'EffectBlock_'..i)
            local handle=studio.Node('TextButton',button,'EffectResize_'..i)handle.Text='│'
            handle.AnchorPoint=Vector2.new(1,0)handle.Position=UDim2.fromScale(1,0)handle.Size=UDim2.new(0,10,1,0)
            local item={Button=button,Handle=handle,Left=left,Width=width,At=effect.At,Duration=duration,Index=i}
            api.Bars[i]=item
            local function begin(input,resize)
                if workbench.Drag or(input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch)then return end
                item.Pointer=true editor:BeginDocumentGesture()
                workbench.Drag={Kind='effect',Input=input,Origin=view:Point(input),Index=i,Resize=resize,
                    Start=effect.At,Duration=duration,Width=usable,LabelWidth=labelWidth,Length=length,Item=item,Row=(i-1)*36+2,ReleaseScroll=studio.HoldScroll(list,parent,studio.Body)}
            end
            button.InputBegan:Connect(function(input)
                local x=view:Point(input).X-button.AbsolutePosition.X
                begin(input,x>=button.AbsoluteSize.X-12)
