            handle.InputBegan:Connect(function(input)begin(input,true)end)
        end
        if #(editor.Track.Effects or {})==0 then
            studio.Label(list,"Add an effect, choose a limb and preview it beside the maker.",4,6,w-40,50,13).TextWrapped=true
        end
    end
    studio.Connect(view.Root,studio.Context.Input.InputChanged,function(input)
        local d=workbench.Drag if not d or d.Kind~='effect'then return end
        if input~=d.Input and not(d.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement)then return end
        local ok=studio.Run(function()
            local delta=(view:Point(input).X-d.Origin.X)/math.max(1,d.Width)*d.Length
            editor:UpdateDocumentGesture(function(track)
                local effect=track.Effects[d.Index]
                if d.Resize then
                    local field=effect.Kind=='Burst'and 'Lifetime'or 'Duration'
                    effect[field]=math.clamp(math.round((d.Duration+delta)*editor.FPS)/editor.FPS,.05,10)
                else effect.At=math.clamp(math.round((d.Start+delta)*editor.FPS)/editor.FPS,0,3600)end
                local duration=effect.Kind=='Burst'and effect.Lifetime or effect.Duration
                studio.Rect(d.Item.Button,d.LabelWidth+effect.At/d.Length*d.Width,d.Row,math.max(24,duration/d.Length*d.Width),26)
                d.Item.Button.Text=string.format('%.2fs',effect.At)
            end)view:Tick()
        end)
        if not ok then workbench.Cancel()end
    end)
    studio.Connect(view.Root,studio.Context.Input.InputEnded,function(input)
        local d=workbench.Drag if not d or d.Kind~='effect'then return end
        if input==d.Input or(d.Input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)then
            if d.ReleaseScroll then d.ReleaseScroll()end
            workbench.Drag=nil studio.Run(function()editor:EndGesture(true)view:Refresh()end)
        end
    end)
    return api
end
