-- Visible IK targets and editable local camera/prop tracks.
return function(studio,view,editor,workbench)
    local ctx=studio.Context local files=ctx.Files local doc=files.Document
    local IK=ctx.Require("main/studio_ik")local transform=ctx.Require("main/studio_transform")
    local api={Chain=1,SceneKind="camera",Prop=1}
    local targetButton=studio.Button(view.Viewport,"◎",0,0,30,nil,"IKTarget")targetButton.Visible=false
    local function info()return assert(ctx.RigInfo and ctx.RigInfo(editor.Track),"start reanimation to use IK")end
    local function chains()return IK.Chains[editor.DetectedRig or "R6"]or IK.Custom(info())end
    local function chain()return assert(chains()[api.Chain]or chains()[1],"this rig has no IK chain")end
    local function target(track,create)
        local s=create and doc.Ensure(track)or track.Studio
        if s then for i,t in ipairs(s.Targets)do if t.Chain==chain().Name then return t,i end end end
        if create then
            local rig=info()local p=rig.Root:PointToObjectSpace(IK.EndPoint(rig,editor:EvaluatedPoses(),chain()))
            local t={Chain=chain().Name,Position={p.X,p.Y,p.Z},Weight=1}table.insert(s.Targets,t)return t,#s.Targets
        end
    end
    local function solve(track,rig,t,poses)
        local world=rig.Root:PointToWorldSpace(Vector3.new(table.unpack(t.Position)))
        local result,error=IK.Solve(rig,poses,chain(),world,t.Weight)
        for _,name in ipairs(chain().Joints)do result[name]=editor:LayerPose(name,result[name],editor.Time)end
        IK.Write(track,editor:Keys(track),chain(),result,math.round(editor.Time*editor.FPS)/editor.FPS)
        for _,name in ipairs(chain().Joints)do local row=doc.Curves(track,false)[name]
            if row then local values=doc.Values(result[name],row.rotationMode)for axis in pairs(row.channels)do doc.KeyCurve(track,name,axis,editor.Time,values[axis])end end
        end
        doc.Invalidate(track)return error
    end
    function api.DrawTarget()
        targetButton.Visible=false
        if not studio.Visible or studio.Mode~="editor"or workbench.Tab~="IK"or studio.Modal or studio.Popup then return end
        local t=target(editor.Track,false)if not t then return end
        local ok,rig=pcall(info)if not ok then return end
        local p=rig.Root:PointToWorldSpace(Vector3.new(table.unpack(t.Position)))
        local projected,visible=view:Project(p)local vp,vs=view.Viewport.AbsolutePosition,view.Viewport.AbsoluteSize
        local x,y=projected.X-vp.X,projected.Y-vp.Y
        if visible and projected.Z>0 and x>=15 and x<vs.X-15 and y>=(view.CaptionHeight or 90)+10 and y<vs.Y-15 then
            targetButton.Visible=true studio.Rect(targetButton,x-15,y-13,30,26)
        end
