return function(ctx)
    local api={Root="UhhhhhhReanim/Projects/",ModuleRoot="UhhhhhhReanim/Modules/StudioMade/"}
    local function ensure(path)
        local current=""
        for segment in path:gmatch("[^/]+")do
            current..=segment.."/"if not ctx.IsFolder(current)then ctx.MakeFolder(current)end
        end
    end
    local function name(value)
        assert(type(value)=="string"and value~=""and #value<=128 and not value:find('[\\/:%c<>"|?*]')and value~="."and value~="..","use a short filename")
        return value
    end
    function api.Write(file,bytes,overwrite)
        file=name(file)local path=api.Root..file ensure(api.Root)
        assert(overwrite or not ctx.IsFile(path),"file exists; choose another project name")
        ctx.Write(path,bytes)assert(ctx.Read(path)==bytes,"project write did not round-trip")return path
    end
    function api.Read(file)return ctx.Read(api.Root..name(file))end
    function api.List()
        ensure(api.Root)local out={}
        for _,path in ipairs(ctx.List(api.Root))do
            local leaf=path:gsub("\\","/"):match("[^/]+$")
            if leaf and not leaf:match("^__uhh_maker_")and leaf:match("%.uhmaker%.json$")then table.insert(out,leaf)end
        end
        table.sort(out)return out
    end
    function api.SaveDraft(kind,sequence,bytes)
        assert(kind=="dance"or kind=="moveset","invalid maker draft")
        local slot=sequence%2==1 and "a"or "b"
        return api.Write("__uhh_maker_"..kind.."_"..slot..".uhmaker.json","UHH_MAKER_DRAFT_1 "..sequence.."\n"..bytes,true)
    end
    function api.RecoverDraft(kind,decode)
        assert(kind=="dance"or kind=="moveset","invalid maker draft")
        local best
        for _,slot in ipairs({"a","b"})do
            local ok,value=pcall(function()
                local bytes=api.Read("__uhh_maker_"..kind.."_"..slot..".uhmaker.json")
                local seq,body=bytes:match("^UHH_MAKER_DRAFT_1 (%d+)\n(.*)$")assert(seq and body,"incomplete maker draft")
                local project=decode(body)assert(project.Kind==kind,"wrong maker draft")return {Sequence=tonumber(seq),Project=project}
            end)
            if ok and(not best or value.Sequence>best.Sequence)then best=value end
        end
        return best
    end
    function api.Export(project,bytes)
        local stem=project.Name:gsub('[^%w_%-]','_'):sub(1,72)if stem==""then stem="my_module"end
        ensure(api.ModuleRoot)
        local folder
        for i=1,1000 do
            local candidate=api.ModuleRoot..stem..(i==1 and ""or "_"..i).."/"
            if not ctx.IsFolder(candidate)then folder=candidate break end
        end
        assert(folder,"choose another module name")ensure(folder)
        local path=folder.."project.uhmaker.json"
        local source="-- Made with Uhhhhhh's simple maker. Original clip credits are in project.uhmaker.json.\n"
            .."local tools=AnimLib.GetMakerTools()\nlocal project=tools.Decode(readfile("..string.format("%q",path).."))\n"
            .."return {function()return tools.Module(project)end}\n"
        ctx.Write(path,bytes)assert(ctx.Read(path)==bytes,"module project write did not round-trip")
        ctx.Write(folder.."main.lua",source)assert(ctx.Read(folder.."main.lua")==source,"module script write did not round-trip")
        return folder
    end
    return api
end
