-- Preserve native theme colors where readable; contrast fallback is Studio-only.
-- A single coalesced theme observer avoids per-label background/frame callbacks.
local TextTheme={}
local function luminance(c)
    local function linear(v)return v<=.04045 and v/12.92 or ((v+.055)/1.055)^2.4 end
    return .2126*linear(c.R)+.7152*linear(c.G)+.0722*linear(c.B)
end
function TextTheme.Contrast(a,b)
    local x,y=luminance(a),luminance(b)
    return (math.max(x,y)+.05)/(math.min(x,y)+.05)
end
function TextTheme.Choose(foreground,background,gradient)
    local backgrounds={background}
    if type(gradient)=="string"and #gradient>0 then
        local values=string.split(gradient,",")
        for i=1,#values,4 do
            local r,g,b=tonumber(values[i+1]),tonumber(values[i+2]),tonumber(values[i+3])
            if r and g and b then table.insert(backgrounds,Color3.fromRGB(r,g,b))end
        end
    end
    local function score(c)
        local worst=math.huge
        for _,back in ipairs(backgrounds)do worst=math.min(worst,TextTheme.Contrast(c,back))end
        return worst
    end
    if score(foreground)>=4.5 then return foreground,false end
    local best,value=foreground,score(foreground)
    for _,candidate in ipairs({Color3.new(0,0,0),Color3.new(1,1,1)})do
        local current=score(candidate)
        if current>value then best,value=candidate,current end
    end
    return best,best~=foreground
end
function TextTheme.new(ctx)
    local style,nodes=ctx.Theme.Current,setmetatable({},{__mode="k"})
    local chosen,fallback,queued,force
    local function apply(control)
        if chosen then
            control.TextColor3=chosen
            if fallback and control:IsA("TextBox")then control.PlaceholderColor3=chosen end
        end
    end
    local function update()
        queued=false
        if not ctx.Root.Parent or not style then return end
        local nextColor,nextFallback=TextTheme.Choose(style:GetAttribute("TextColor"),style:GetAttribute("BackgroundColor"),style:GetAttribute("BackgroundGradient"))
        local changed=not chosen or chosen.R~=nextColor.R or chosen.G~=nextColor.G or chosen.B~=nextColor.B or fallback~=nextFallback
        chosen,fallback=nextColor,nextFallback
        if changed or force then for control in pairs(nodes)do if control.Parent then apply(control)end end end
        force=false
    end
    if style and style.GetAttributeChangedSignal then
        for _,name in ipairs({"TextColor","BackgroundColor","BackgroundGradient"})do
            ctx.Util.LinkDestroyI2C(ctx.Root,style:GetAttributeChangedSignal(name):Connect(function()
                force=force or name=="TextColor"
                if not queued then queued=true task.defer(update)end
            end))
        end
        update()
    end
    return function(control)
        ctx.Theme.ApplyLabel(control)nodes[control]=true apply(control)
    end
end
return TextTheme
