-- Small local effects, described as data. No supplied scripts are executed.
local VFX={}
local function number(v,default,low,high)
    v=tonumber(v)or default assert(v==v and v>=low and v<=high,"effect value must be "..low.." to "..high)return v
end
function VFX.Validate(effect)
    assert(type(effect)=="table","invalid effect")
    local kind=effect.Kind or "Burst"assert(kind=="Burst"or kind=="Trail"or kind=="Light","choose Burst, Trail or Light")
    local anchor=tostring(effect.Anchor or "Torso")assert(#anchor>0 and #anchor<=128,"invalid effect limb")
    local hex=tostring(effect.Color or "FFD96A"):gsub("^#","")assert(hex:match("^%x%x%x%x%x%x$"),"use a six digit color, e.g. FFD96A")
    return {Kind=kind,Anchor=anchor,Color=hex:upper(),At=number(effect.At,0,0,3600),
        Count=math.floor(number(effect.Count,24,1,150)),Size=number(effect.Size,.3,.01,10),
        Lifetime=number(effect.Lifetime,.6,.05,10),Speed=number(effect.Speed,5,0,100),
        Duration=number(effect.Duration,.5,.05,10)}
end
function VFX.List(effects)
    assert(type(effects)=="table"and #effects<=32,"up to 32 effects per clip")
    local out={}for _,effect in ipairs(effects)do table.insert(out,VFX.Validate(effect))end return out
end
function VFX.Runtime(rig,effects,new)
    new=new or Instance.new
    local api={Items={},Time=-1,Alive=true}
    for sourceIndex,effect in ipairs(VFX.List(effects or {}))do
        local part=rig:FindFirstChild(effect.Anchor,true)
        if part and part:IsA("BasePart")then
            local item={Spec=effect,Owned={},Until=-1,SourceIndex=sourceIndex}
            local function make(class,parent)
                local object=new(class)object.Name="UhhhhhhMakerEffect"object.Parent=parent
                table.insert(item.Owned,object)return object
            end
            local attachment=make("Attachment",part)
            local color=Color3.fromHex(effect.Color)
            if effect.Kind=="Burst"then
                local emitter=make("ParticleEmitter",attachment)
                emitter.Texture="rbxasset://textures/particles/sparkles_main.dds"
                emitter.Enabled=false emitter.Rate=0 emitter.Color=ColorSequence.new(color)
                emitter.Size=NumberSequence.new(effect.Size)emitter.Lifetime=NumberRange.new(effect.Lifetime)
                emitter.Speed=NumberRange.new(effect.Speed)emitter.SpreadAngle=Vector2.new(180,180)
                emitter.LightEmission=.6 item.Object=emitter
            elseif effect.Kind=="Trail"then
                attachment.Position=Vector3.new(-effect.Size/2,0,0)
                local other=make("Attachment",part)other.Position=Vector3.new(effect.Size/2,0,0)
                local trail=make("Trail",attachment)trail.Attachment0=attachment trail.Attachment1=other
                trail.Color=ColorSequence.new(color)trail.Lifetime=effect.Lifetime
                trail.Enabled=false trail.LightEmission=.6 item.Object=trail
            else
                local light=make("PointLight",attachment)light.Color=color light.Enabled=false
                light.Brightness=math.min(effect.Size*3,10)light.Range=math.min(effect.Speed+4,40)item.Object=light
            end
            table.insert(api.Items,item)
        end
    end
    function api.Reset()
        api.Time=-1
        for _,item in ipairs(api.Items)do
            item.Until=-1 item.Object.Enabled=false
            if item.Spec.Kind=="Burst"then item.Object:Clear()end
        end
    end
    function api.UpdateTimes(values)
        local changed=false
        for _,item in ipairs(api.Items)do
            local value=values[item.SourceIndex]
            if value then
                if item.Spec.At~=value.At or item.Spec.Duration~=value.Duration or item.Spec.Lifetime~=value.Lifetime then
                    item.Spec.At,item.Spec.Duration,item.Spec.Lifetime=value.At,value.Duration,value.Lifetime
                    if item.Spec.Kind=="Burst"then item.Object.Lifetime=NumberRange.new(value.Lifetime)
                    elseif item.Spec.Kind=="Trail"then item.Object.Lifetime=value.Lifetime end
                    changed=true
                end
            end
        end
        if changed then api.Reset()end
    end
    function api.Step(time)
        if not api.Alive then return end
        if time<api.Time then api.Reset()end
        for _,item in ipairs(api.Items)do
            if item.Spec.At>api.Time and item.Spec.At<=time then
                if item.Spec.Kind=="Burst"then
                    if time<item.Spec.At+item.Spec.Lifetime then item.Object:Emit(item.Spec.Count)end
                else item.Until=item.Spec.At+item.Spec.Duration item.Object.Enabled=time<item.Until end
            end
            if item.Spec.Kind~="Burst"and time>=item.Until then item.Object.Enabled=false end
        end
        api.Time=time
    end
    function api.Destroy()
        api.Alive=false
        for _,item in ipairs(api.Items)do for i=#item.Owned,1,-1 do item.Owned[i]:Destroy()end end
        table.clear(api.Items)
    end
    return api
end
return VFX
