    root.Position=UDim2.fromScale(.5,.5) root.Size=UDim2.new(1,-28,1,-34)
    root.BackgroundTransparency=1 root.BorderSizePixel=0 root.Visible=false root.ZIndex=80
    studio.Root=root
    local labelTheme=ctx.Require("main/studio_theme").new({Theme=Theme,Util=Util,Root=root})
