        target.Position=UDim2.fromOffset(x,y) target.Size=UDim2.fromOffset(math.max(0,width),math.max(0,height))
    end
    studio.Rect=rect
    function studio.Place(object,r) rect(object,r.X,r.Y,r.W,r.H) object.Visible=r.W>0 and r.H>0 end
    function studio.FontSize(object,size)
        object.TextSize=size
        -- Native Theme.ApplyLabel registers only TextLabels. Buttons and inputs
        -- need the same preferred-size policy, and labels need their final size.
        if Util.ForcedTextSizes then Util.ForcedTextSizes[object]=size end
        if Util.ApplyPreferredTextSize then Util.ApplyPreferredTextSize(object,size)end
    end
    function studio.Node(class,parent,name)
        local object=Util.Instance(class,parent)
        object.Name=name or class object.ZIndex=(parent.ZIndex or 80)+1
        object.BackgroundTransparency=1 object.BorderSizePixel=0
        if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            object.Font=ctx.Font object.TextSize=13 object.RichText=false
            object.TextColor3=Color3.new(1,1,1) object.TextWrapped=false
            object.TextXAlignment=Enum.TextXAlignment.Left object.TextYAlignment=Enum.TextYAlignment.Center
            object.TextTruncate=Enum.TextTruncate.AtEnd
            labelTheme(object)
            studio.FontSize(object,13)
