        object.ClipsDescendants=true object.Active=true
        Theme.ApplyFrame(object,{Depthed=true}) return object
    end
    function studio.Label(parent,text,x,y,width,height,size,name)
        local object=studio.Node("TextLabel",parent,name) object.Text=tostring(text)
        studio.FontSize(object,size or 13)rect(object,x,y,width,height) return object
    end
    function studio.Button(parent,text,x,y,width,callback,name)
        text=ctx.Require("main/navigation_label")(text)
        local surface=studio.Panel(parent,(name or "Button").."Surface")surface.ClipsDescendants=false
        local object=studio.Node("TextButton",surface,name) object.Text=text
        studio.Surfaces[object]=surface object.Size=UDim2.fromScale(1,1)
        object.TextXAlignment=Enum.TextXAlignment.Center object.AutoButtonColor=true
        surface.BackgroundTransparency=.12
        object:GetPropertyChangedSignal("Visible"):Connect(function()surface.Visible=object.Visible end)
        rect(object,x,y,width,26)
        object.Activated:Connect(function()
            if Theme.PlaySound then Theme.PlaySound("CLICK") end
            studio.Run(callback)
        end)
        return object
    end
    function studio.Box(parent,text,placeholder,x,y,width,name)
        local surface=studio.Panel(parent,(name or "Box").."Surface")surface.ClipsDescendants=false
        local object=studio.Node("TextBox",surface,name) object.Text=tostring(text or "")
        studio.Surfaces[object]=surface object.Size=UDim2.fromScale(1,1)
