    function studio.BindLayout(owner,callback)
        local queued=false
        local function update()
            if queued then return end queued=true
            task.defer(function()
                queued=false
                if owner.Parent then callback(owner.AbsoluteSize.X,owner.AbsoluteSize.Y)end
            end)
        end
        studio.Connect(owner,owner:GetPropertyChangedSignal("AbsoluteSize"),update)
        update()return update
    end
    function studio.Form(parent,options)return ctx.Require("main/studio_flow")(studio,parent,options)end
    function studio.HoldScroll(...)
        local held,seen={},{}
        for _,object in ipairs({...})do
            if not seen[object]then seen[object]=true
                table.insert(held,{Object=object,Enabled=object.ScrollingEnabled})object.ScrollingEnabled=false
            end
