    end
    local header=studio.Panel(root,"StudioHeader") header.ZIndex=101
    local title=studio.Label(header,"Animation Editor",12,0,500,32,16,"StudioTitle")
    local menu=studio.Panel(root,"StudioMenuBar") menu.ZIndex=100
    local toolsbar=studio.Scroll(root,"StudioTools")toolsbar.ScrollingDirection=Enum.ScrollingDirection.X
toolsbar.CanvasSize=UDim2.fromOffset(1120,0)
    local body=studio.Scroll(root,"StudioBody")body.ClipsDescendants=true body.ZIndex=82
