    function studio.Status(message)
        status.Text=tostring(message or "Ready")
        if studio.DialogStatus then studio.DialogStatus.Text=status.Text end
    end
    if ctx.Files.ReadDraft and ctx.Files.WriteDraft then
        studio.Autosave=ctx.Require("main/studio_autosave")({Files=ctx.Files,
            Read=ctx.Files.ReadDraft,Write=ctx.Files.WriteDraft,
