    local maximize=studio.Button(header,"Maximize",0,3,88,function()
        if studio.Maximized then
            root.Size=studio.NormalSize or UDim2.new(1,-28,1,-34)
            root.Position=studio.NormalPosition or UDim2.fromScale(.5,.5)
