        studio.LayoutNow()
    end,"MaximizeStudio")
    local resize=studio.Node("TextButton",root,"ResizeStudio") resize.Text="◢" resize.ZIndex=150 studio.FontSize(resize,18)
    local resizing,resizeStart,resizeSize
    studio.Drag(title,function()return root.AbsolutePosition end,function(start,delta)
        local screen,size=ctx.ScreenGui.AbsoluteSize,root.AbsoluteSize
        local x=math.clamp(start.X+delta.X,4,math.max(4,screen.X-size.X-4))
        local y=math.clamp(start.Y+delta.Y,4,math.max(4,screen.Y-size.Y-4))
        root.Position=UDim2.fromOffset(x+size.X/2,y+size.Y/2)
    end)
    resize.InputBegan:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
            studio.CancelInteractions()
            studio.Maximized=false
            resizing=input resizeStart=input.Position resizeSize=root.AbsoluteSize
        end
    end)
    studio.Connect(root,Input.InputChanged,function(input)
        local drag=studio.Dragging
        if drag and studio.Visible and (input.UserInputType==Enum.UserInputType.MouseMovement or input==drag.Input)then
            studio.Run(function()drag.Move(drag.State,input.Position-drag.Origin)end)
        end
        if resizing and (input.UserInputType==Enum.UserInputType.MouseMovement or input==resizing) then
            local delta=input.Position-resizeStart
            local screen=ctx.ScreenGui.AbsoluteSize
