    ["UhhhhhhReanim/System/runtime/steve110/main/teleport_resume.lua"] = [=====[
-- Nooby-style auto execute after teleport, explicitly enabled in server tools.
-- Code is queued only when a real hop/rejoin is requested. A failed teleport
-- cannot cause duplicate copies to accumulate in the executor's queue.
return function(ctx)
    local api = {}

    function api.Build(source)
        source = tostring(source or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if source == "" then source = "UhhhhhhReanim/System/launch.lua" end
        assert(#source <= 2048 and not source:find("%c"), "enter a short script path or HTTPS URL")
        local expression
        if source:match("^https://[^%s]+$") then
            expression = "game:HttpGet(" .. string.format("%q", source) .. ")"
        else
            assert(not source:find("\\", 1, true) and source:sub(1, 1) ~= "/"
                and not source:find(":", 1, true), "use a relative executor file path")
            for part in source:gmatch("[^/]+") do assert(part ~= ".." and part ~= ".", "invalid script path") end
            expression = "readfile(" .. string.format("%q", source) .. ")"
        end
        return "if not _G.UhhhhhhLoaded then\n"
            .. " local ok, why = pcall(function()\n"
            .. "  local fn, err = loadstring(" .. expression .. ")\n"
            .. "  assert(fn, err)\n  fn()\n end)\n"
            .. " if not ok then warn('Uhhhhhh teleport resume: ' .. tostring(why)) end\nend\n"
    end

    function api.Queue(source)
        if type(ctx.Queue) ~= "function" then return false, "this executor has no queue_on_teleport capability" end
        local ok, code = pcall(api.Build, source)
        if not ok then return false, tostring(code) end
        if api.Queued == code then return true end
        if api.Queued then return false, "a different resume script is already queued for this session" end
        local accepted, why = pcall(ctx.Queue, code)
        if not accepted or why == false then return false, "could not queue teleport resume: " .. tostring(why) end
        api.Queued = code
        return true
    end

    return api
end
