local Theme = {}

local HttpService = Util.Service("HttpService")

local GLOW_TEXTURE = "rbxassetid://6429584813"


local CurrentStyle = Util.Instance("BoolValue")
CurrentStyle:SetAttribute("OutlineColor", Color3.new(1, 1, 1))
CurrentStyle:SetAttribute("BackgroundColor", Color3.new(0, 0, 0))
CurrentStyle:SetAttribute("TextColor", Color3.new(1, 1, 1))
