CurrentStyle:SetAttribute("GlowTransparency", 0.1)
CurrentStyle:SetAttribute("GlowSize", 32)
CurrentStyle:SetAttribute("WindowOutlineSize", 1)
CurrentStyle:SetAttribute("OutlineGradient", "")
CurrentStyle:SetAttribute("BackgroundGradient", "")
CurrentStyle:SetAttribute("OutlineGradientRotation", 0)
CurrentStyle:SetAttribute("BackgroundGradientRotation", 0)
Theme.Current = CurrentStyle
local _EventHandlers = {}
function Theme.OnChanged(attrname, callback)
local last = CurrentStyle:GetAttribute(attrname)
callback(last)
local sig = _EventHandlers[attrname]
if not sig then
sig = Signal()
_EventHandlers[attrname] = sig
CurrentStyle:GetAttributeChangedSignal(attrname):Connect(function()
local now = CurrentStyle:GetAttribute(attrname)
if last ~= now then last = now sig:Fire(last) end
end)
end
return sig:Connect(callback)
end
local _colorStuffSignals = {}
local function _registerColorStuff(obj, colprop, col, gradcol, gradrot, depthed)
local gradient = Util.Instance("UIGradient", obj)
gradient.Enabled = false
gradient.Transparency = NumberSequence.new(0)
local oldgc
local function getc(c, gc, gr)
if gc and #gc > 0 then
if oldgc ~= gc then
local split = string.split(gc, ",")
if #split >= 8 and #split % 4 == 0 then
local first = true
local time = -1
local kfs = {}
local fin = false
for i=1, #split, 4 do
local t, r, g, b = tonumber(split[i]), tonumber(split[i + 1]), tonumber(split[i + 2]), tonumber(split[i + 3])
if not t and r and g and b then warn("invalid number property") break end
if t < 0 or t > 1 then warn("t isnt between 0 and 1") break end
if first then
if t ~= 0 then warn("keyframes start at t=0") break end
first = false
end
if time >= t then warn("keyframe ts should be in ascending order") break end
if time == 1 then warn("keyframe after t=1") fin = false break end
if t == 1 then fin = true end
time = t
kfs[#kfs + 1] = ColorSequenceKeypoint.new(t, Color3.fromRGB(r, g, b))
end
if fin then
gradient.Color = ColorSequence.new(kfs)
gradient.Enabled = true
end
else
warn("wrong number of properties: " .. #split)
end
end
oldgc = gc
gradient.Rotation = gr
c = Color3.new(1, 1, 1)
else
if oldgc then
gradient.Enabled = false
oldgc = nil
end
end
return c
end
local update
if depthed then
function update(c, gc, gr)
c = getc(c, gc, gr)
obj[colprop] = Color3.new(c.R * 0.9, c.G * 0.9, c.B * 0.9)
end
else
function update(c, gc, gr)
c = getc(c, gc, gr)
obj[colprop] = c
end
end
local _key = col .. "-" .. gradcol .. "-" .. gradrot
local sig = _colorStuffSignals[_key]
if not sig then
sig = Signal()
_colorStuffSignals[_key] = sig
local alreadyDeferred = false
local function fire()
local c, gc, gr = CurrentStyle:GetAttribute(col), CurrentStyle:GetAttribute(gradcol), CurrentStyle:GetAttribute(gradrot)
sig:Fire(c, gc, gr)
alreadyDeferred = false
end
local function deferFire()
if alreadyDeferred then return end
alreadyDeferred = true
task.defer(fire)
end
Theme.OnChanged(col, deferFire)
Theme.OnChanged(gradcol, deferFire)
Theme.OnChanged(gradrot, deferFire)
end
update(CurrentStyle:GetAttribute(col), CurrentStyle:GetAttribute(gradcol), CurrentStyle:GetAttribute(gradrot))
Util.LinkDestroyI2C(obj, sig:Connect(update))
end
