Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("OutlineColor"):Connect(deferUpdate))
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("BackgroundColor"):Connect(deferUpdate))
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("GlowTransparency"):Connect(deferUpdate))
end
end
local function _getTextColor(options)
local col = CurrentStyle:GetAttribute("TextColor")
if options.Tint then
local alpha = options.TintAlpha or 0.5
col = col:Lerp(options.Tint, alpha)
end
return col
end
local function _applyTextBoxColors(obj, options)
local col = _getTextColor(options)
obj.TextColor3 = col
local h, s, v = col:ToHSV()
obj.PlaceholderColor3 = Color3.fromHSV(h, s, 0.5 + (v - 0.5) * 0.4)
end
function Theme.ApplyLabel(obj, options)
options = options or {}
if obj:IsA("TextLabel") or obj:IsA("TextButton") then
obj.TextColor3 = _getTextColor(options)
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("TextColor"):Connect(function()
obj.TextColor3 = _getTextColor(options)
end))
end
if obj:IsA("TextBox") then
_applyTextBoxColors(obj, options)
Util.LinkDestroyI2C(obj, CurrentStyle:GetAttributeChangedSignal("TextColor"):Connect(function()
_applyTextBoxColors(obj, options)
end))
end
Util.ForceTextSize(obj)
end

