function Theme.Update(t)
local low=Util.UIPerformance and Util.UIPerformance.ReducedEffects()
if low then t=0 end
local OutlineColor = Theme.OutlineColor
local BackgroundColor = Theme.BackgroundColor
local OutlineGradient, BackgroundGradient = Theme.OutlineGradient, Theme.BackgroundGradient
local r1, r2 = Theme.OutlineGradientRotation, Theme.BackgroundGradientRotation
if Theme.Animated then
if OutlineColor then
local si = math.sin(math.pi * 2 * t / 10)
local h, s, v = OutlineColor:ToHSV()
if s < 0.2 then
v *= 0.8 + si * 0.2
else
h += si * 0.01
end
OutlineColor = Util.LoopedHSV(h, s, v)
else
OutlineColor = Util.LoopedHSV(t / 10, 0.8, 1)
end
if BackgroundColor then
local si = math.sin(math.pi * 2 * t / 10)
local h, s, v = BackgroundColor:ToHSV()
if s < 0.2 then
if v > 0.5 then
v *= 0.95 + si * 0.05
else
v *= 1.05 + si * 0.05
end
else
h += si * 0.01
end
BackgroundColor = Util.LoopedHSV(h, s, v)
else
BackgroundColor = Color3.new(0, 0, 0)
end
if r1 < 0 then r1 = (t * 120) % 360 end
if r2 < 0 then r2 = (t * 120) % 360 end
else
if not OutlineColor then
OutlineColor = Util.LoopedHSV(math.floor(t * 2) / 20, 0.8, 1)
end
if not BackgroundColor then
BackgroundColor = Color3.new(0, 0, 0)
end
OutlineGradient = nil
BackgroundGradient = nil
if r1 < 0 then r1 = 67 end
if r2 < 0 then r2 = 67 end
end
CurrentStyle:SetAttribute("OutlineColor", OutlineColor)
CurrentStyle:SetAttribute("BackgroundColor", BackgroundColor)
CurrentStyle:SetAttribute("TextColor", Theme.TextColor or Color3.new(1, 1, 1))
CurrentStyle:SetAttribute("GlowTransparency", low and 1 or Theme.GlowTransparency)
