CurrentStyle:SetAttribute("CornerRadius", Theme.CornerRadius)
CurrentStyle:SetAttribute("WindowOutlineSize", Theme.WindowOutlineSize)
CurrentStyle:SetAttribute("OutlineGradient", OutlineGradient)
CurrentStyle:SetAttribute("BackgroundGradient", BackgroundGradient)
CurrentStyle:SetAttribute("OutlineGradientRotation", r1)
CurrentStyle:SetAttribute("BackgroundGradientRotation", r2)
end

