-- Uses the same native controls, theme service and retained-page transitions.
-- Preview changes appearance only; apply owns the saved selection.
return function(ctx)
    local UI,catalog,saved=ctx.UI,ctx.Catalog,ctx.Saved
    local api={Active=false,Previewing=false,Chosen=saved.UITheme}
    local page=UI.CreatePage()page.Name="ThemeGallery"
    UI.Workspace.RegisterRoot("themes","Themes",page,Color3.new(1,.6,0))
    api.Page=page
    local main,mainText=UI.CreateButton(ctx.Main,"Themes & appearance &gt;",18)
    local function revert()
        if api.Previewing then api.Previewing=false ctx.Set(saved.UITheme,true)end
    end
    local back=UI.CreateButton(page,"&lt; Back",20)
    back.Activated:Connect(function()revert()api.Active=false UI.Workspace.Back(page,ctx.Main)end)
    UI.CreateText(page,"<b>THEMES & APPEARANCE</b>",17,Enum.TextXAlignment.Center)
    UI.CreateText(page,"Try a theme on the window and editor. Apply keeps it; Cancel brings your saved theme back.",12,Enum.TextXAlignment.Left)
    local picker=UI.CreateDropdown(page,"UI Theme",catalog.Names,saved.UITheme)
    local credit=UI.CreateText(page,"",11,Enum.TextXAlignment.Left)credit.RichText=false
    local status=UI.CreateText(page,"",12,Enum.TextXAlignment.Left)status.RichText=false
    local apply=UI.CreateButton(page,"Apply theme",18)
    local cancel=UI.CreateButton(page,"Cancel preview",18)
    local function describe()
        credit.Text=catalog.Source(api.Chosen)
        if mainText then mainText.Text="Theme: "..catalog.Names[saved.UITheme].." &gt;"end
    end
    function api.Begin()
        revert()api.Active=true api.Chosen=saved.UITheme picker.Value=api.Chosen
        status.Text="Saved: "..catalog.Names[saved.UITheme]describe()
    end
    function api.Open()api.Begin()UI.Workspace.Open(page,ctx.Main)end
    function api.Refresh()
        api.Previewing=false api.Chosen=saved.UITheme picker.Value=api.Chosen
        status.Text="Saved: "..catalog.Names[saved.UITheme]describe()
    end
    picker.Changed:Connect(function(value)
        if not api.Active or value~=picker.Value or value==api.Chosen then return end
        api.Chosen=value api.Previewing=true ctx.Set(value,true)
        status.Text="Previewing: "..catalog.Names[value].." — Apply to keep"describe()
    end)
    apply.Activated:Connect(function()
        if not api.Active then return end
        local previous=saved.UITheme
        api.Previewing=false ctx.Set(api.Chosen,false)
        local ok,success,reason=pcall(ctx.Save)
        if not ok or not success then
            local chosen=api.Chosen
            ctx.Set(previous,false)api.Chosen=chosen picker.Value=chosen api.Previewing=true ctx.Set(chosen,true)
            status.Text="Could not save: "..tostring(ok and reason or success)..". Your saved theme is unchanged."
        else status.Text="Theme saved :D"end
        describe()
    end)
    cancel.Activated:Connect(function()revert()api.Chosen=saved.UITheme picker.Value=api.Chosen
        status.Text="Preview cancelled"describe()
    end)
    main.Activated:Connect(api.Open)
    if ctx.Interface then UI.CreateButton(ctx.Interface,"Preview themes &gt;",18).Activated:Connect(api.Open)end
    ctx.Util.LinkDestroyI2C(page,page:GetPropertyChangedSignal("Visible"):Connect(function()
        if not page.Visible then revert()api.Active=false elseif not api.Active then api.Begin()end
    end))
    if ctx.Window then
        ctx.Util.LinkDestroyI2C(page,ctx.Window:GetPropertyChangedSignal("Visible"):Connect(function()
            if not ctx.Window.Visible then revert()api.Active=false elseif page.Visible then api.Begin()end
        end))
    end
    page.Destroying:Once(revert)
    describe()
    return api
end
