    ["UhhhhhhReanim/System/runtime/steve110/main/track_cache.lua"] = [=====[
-- File-track cache bounded by both clip count and pose count. Large clips still
-- load normally; they simply do not occupy a second retained copy in this cache.
return function(ctx)
    local api = {Entries = {}, Count = 0, Poses = 0}
    local clock = ctx.Clock or os.clock
    local maximumTracks, maximumPoses = ctx.MaximumTracks or 16, ctx.MaximumPoses or 150000

    function api.Remove(key)
        local entry = api.Entries[key]
        if entry then
            api.Count -= 1 api.Poses -= entry.Poses
            api.Entries[key] = nil
        end
    end

    function api.Get(key)
        local entry = api.Entries[key]
        if entry then entry.Used = clock() return entry.Track end
    end

    function api.Put(key, track)
        api.Remove(key)
        local poses = 0
        for _, frame in ipairs(track.Keyframes) do poses += #frame.Poses end
        if poses > maximumPoses then return false end
        while api.Count >= maximumTracks or api.Poses + poses > maximumPoses do
            local oldest, time
            for candidate, entry in pairs(api.Entries) do
                if not time or entry.Used < time then oldest, time = candidate, entry.Used end
            end
            if not oldest then break end
            api.Remove(oldest)
        end
        api.Entries[key] = {Track = ctx.Clone(track), Poses = poses, Used = clock()}
        api.Count += 1 api.Poses += poses
        return true
    end

    function api.TrimIdle(age)
        local before, cutoff = api.Count, clock() - (age or 120)
        local remove = {}
        for key, entry in pairs(api.Entries) do if entry.Used < cutoff then table.insert(remove, key) end end
        for _, key in ipairs(remove) do api.Remove(key) end
        return before - api.Count
    end

    function api.Clear()
        table.clear(api.Entries) api.Count, api.Poses = 0, 0
    end

    return api
end
