-- UI-only scheduling and viewport culling. Core camera/control bindings do not
-- enter this queue. Accumulated dt preserves UI transition duration at a cap.
return function(ctx)
    local api={Callbacks={},Time=0,Destroyed=false}
    local function visible(entry)
        local linked=entry.Owner
        return entry.Always or not linked or not linked:IsA("GuiObject")or ctx.Visible(linked)
    end
    local function hidden(entry)
        return not visible(entry)or not entry.Always and entry.Owner and ctx.Clipped and ctx.Clipped(entry.Owner)
    end
    local function observeHidden(entry,isHidden)
        if not entry.Active or entry.Always or not entry.OnHidden then return end
        if not isHidden then entry.Hidden=false return end
        if entry.Hidden then return end
        -- Record the transition before calling user code: removal/clear or an
        -- exception must not cause another notification on every hidden frame.
        entry.Hidden=true
        local ok,reason=pcall(entry.OnHidden,api.Time)
        if not ok and ctx.Error then ctx.Error(reason,entry.OnHidden)end
    end
    local function call(entry,dt)
        if not entry.Active or not visible(entry)or api.Time<(entry.RetryAt or 0)then return end
        local ok,reason=pcall(entry.Callback,api.Time,dt)
        if ok then entry.RetryAt=nil
        else entry.RetryAt=api.Time+1 if ctx.Error then ctx.Error(reason,entry.Callback)end end
    end
    function api.Remove(entry)
        entry.Active=false
        if entry.Connection then entry.Connection:Disconnect()entry.Connection=nil end
        if api.Stepping then api.Compact=true return end
        local at=table.find(api.Callbacks,entry)if at then table.remove(api.Callbacks,at)end
    end
    function api.Add(callback,owner,always,onHidden)
        if api.Destroyed then return callback end
        local entry={Callback=callback,Owner=owner,Always=always==true,Age=0,Active=true,OnHidden=onHidden}
        table.insert(api.Callbacks,entry)
        if owner then entry.Connection=owner.Destroying:Once(function()api.Remove(entry)end)end
        -- Keep legacy three-argument registration timing, including always-run
        -- callbacks. Only opted-in entries observe initial clipping/visibility.
        if onHidden and hidden(entry)then observeHidden(entry,true)else call(entry,.001)end
        return callback
    end
    function api.Step(dt,rate)
        if api.Destroyed then return end
        api.Time+=dt api.Stepping=true
        for i=1,#api.Callbacks do
            if api.Destroyed then break end
            local entry=api.Callbacks[i]
            if entry.Active then
                entry.Age+=dt
                if hidden(entry)then
                    entry.Age=0 observeHidden(entry,true)
                else
                    observeHidden(entry,false)
                    if entry.Always or entry.Age+1e-9>=1/(rate or math.huge)then
                        local age=entry.Age entry.Age=0 call(entry,age)
                    end
                end
            end
        end
        api.Stepping=false
        if api.Compact then
            local at=1
            for i=1,#api.Callbacks do local entry=api.Callbacks[i]
                if entry.Active then api.Callbacks[at]=entry at+=1 end
            end
            for i=#api.Callbacks,at,-1 do api.Callbacks[i]=nil end api.Compact=false
        end
    end
    function api.Clear()
        api.Destroyed=true
        for _,entry in ipairs(api.Callbacks)do
            entry.Active=false if entry.Connection then entry.Connection:Disconnect()end
        end
        table.clear(api.Callbacks)
    end
    return api
end
