--!optimize 2
LU_NATIVE_COMPILE = true

local UNC = require(script.Parent.compat)
local Assets = require(script.Parent.assetmanager)

local Util = {}

function Util.FormatSecondsToTime(seconds)
local hours = math.floor(seconds / 3600)
local minutes = math.floor(seconds / 60) % 60
local seconds = seconds % 60
return string.format("%02d:%02d:%02d.%02d", hours, minutes, seconds, (seconds % 1) * 100)
end

local service_cache = {}
