local Players = Util.Service("Players")
local Player = Players.LocalPlayer
function Util.QueryPlayerSelector(query, excludespeaker)
if #query == 0 then return end
query = query:lower()
local t = {}
for _,player in Players:GetPlayers() do
if player ~= Player or not excludespeaker then
local a = player.DisplayName:lower():find(query)
local b = player.Name:lower():find(query)
if a then table.insert(t, {player, 1, a}) end
if b then table.insert(t, {player, 0, b}) end
end
end
table.sort(t, function(a, b)
if a[2] == b[2] then
return a[3] < b[3]
end
return a[2] < b[2]
end)
if t[1] then
return t[1][1]
end
return nil
end

