SCREENGUI.ClipToDeviceSafeArea = false
SCREENGUI.ResetOnSpawn = false
SCREENGUI.ScreenInsets = Enum.ScreenInsets.None
if order >= 0 then
SCREENGUI.DisplayOrder = 2147483647 - 16 + order
else
