contentText = contentText:gsub("<.->", "")
end
local textsizemul = GuiService.PreferredTextSize.Name
local outputsize = size
if textsizemul == "Large" then
outputsize = size - 4
elseif textsizemul == "Larger" then
outputsize = size - 9
elseif textsizemul == "Largest" then
outputsize = size - 14
end
local textbounds = TextService:GetTextSize(contentText, size, font, bounds)
return textbounds * (size / outputsize)
end
else
local RunService = Util.Service("RunService")
local textBoundsTestGui = Util.CreateScreenGui()
