textBoundsTest.Size = UDim2.new(1, 0, 1, 0)
textBoundsTest.TextXAlignment = Enum.TextXAlignment.Left
textBoundsTest.TextYAlignment = Enum.TextYAlignment.Top
textBoundsTest.TextWrapped = true
textBoundsTest.TextScaled = false
textBoundsTest.Visible = false
