end
textBoundsTestDoneEvent.Name = "WAIT"
textBoundsTest.Size = UDim2.new(0, 1, 0, 1)
textBoundsTest.TextSize = size or 15
textBoundsTest.Font = font or Enum.Font.Code
textBoundsTest.RichText = not not richtext
textBoundsTest.Text = text
RunService.PreRender:Wait()
RunService.Heartbeat:Wait()
textBoundsTest.Size = UDim2.new(0, bounds.X, 0, bounds.Y)
RunService.PreRender:Wait()
RunService.Heartbeat:Wait()
local bounds = textBoundsTest.TextBounds
textBoundsTestDoneEvent.Name = "."
textBoundsTestDoneEvent:Fire()
return bounds
end
end

local UserInputService = Util.Service("UserInputService")
function Util.CreateDragger(frame, dragobj, content, eventfuncs)
local dragref = nil
local offset = Vector2.new(0, 0)
local SCREENGUI = frame:FindFirstAncestorWhichIsA("ScreenGui")
local lol1 = dragobj.InputBegan:Connect(function(input)
if dragref then return end
if input.UserInputState ~= Enum.UserInputState.Begin then return end
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
if content then content.Interactable = false end
local screen = Util.GetScreenSize()
local ch = (Vector2.new(input.Position.X, input.Position.Y) + SCREENGUI.AbsolutePosition) / screen
offset = Util.UDim2ToVector2Scale(frame.Position) - ch
dragref = input
end
end)
local lol2 = UserInputService.InputChanged:Connect(function(input)
if dragref then
if input.UserInputType == Enum.UserInputType.MouseMovement or (input.UserInputType == Enum.UserInputType.Touch and dragref == input) then
local screen = Util.GetScreenSize()
local ch = (Vector2.new(input.Position.X, input.Position.Y) + SCREENGUI.AbsolutePosition) / screen
local pos = ch + offset
local dowsize = Util.UDim2ToVector2Offset(frame.Size)
local imjollx = (dowsize.X * 0.5 - 100) / screen.X
local imjolly = dowsize.Y * -0.5 / screen.Y
local boxy = 31 / screen.Y
pos = Vector2.new(
math.clamp(pos.X, -imjollx, 1 + imjollx),
math.clamp(pos.Y, -imjolly, 1 - imjolly - boxy)
)
frame.Position = Util.Vector2ToUDim2Scale(pos)
end
end
end)
local lol3 = UserInputService.InputEnded:Connect(function(input)
if dragref and dragref == input then
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
if content then content.Interactable = true end
dragref = nil
if eventfuncs and eventfuncs.OnDragStopped then
eventfuncs.OnDragStopped(frame)
end
end
end
end)
return function()
lol1:Disconnect()
lol2:Disconnect()
lol3:Disconnect()
end
end

function Util.CreateInteraction(obj, callbacks)
local now = os.clock
local tap, tapPos, taptime
obj.InputBegan:Connect(function(input)
if input.UserInputState ~= Enum.UserInputState.Begin then return end
if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
tap = input
tapPos = input.Position
taptime = now()
end
end)
obj.InputEnded:Connect(function(input)
if input == tap then
if now() - taptime < 0.25 and (input.Position - tapPos).Magnitude < 10 then
if callbacks.Click then
callbacks.Click()
end
end
end
end)
end

