    ["UhhhhhhReanim/System/runtime/steve110/main/user_pack_assets.lua"] = [=====[
-- Folder-pack media isolation. Inspired by Awes955's folder loader; no global
-- basename copies and no arbitrary .txt files executed as modules.
local Packs = {}
local ROOT = "UhhhhhhReanim/Modules/"
local media = {anim=true,mp3=true,ogg=true,wav=true,png=true,jpg=true,jpeg=true,
    bmp=true,webp=true,obj=true,fbx=true,glb=true,gltf=true,rbxm=true,json=true,txt=true}
local function clean(value)
    if type(value) ~= "string" or value:find("%c") then return nil end
    value = value:gsub("\\", "/"):gsub("/+", "/")
    for segment in value:gmatch("[^/]+") do
        if segment == "." or segment == ".." then return nil end
    end
    return value
end
function Packs.Relative(path)
    path = clean(path)
    if not path then return nil end
    local start = path:find(ROOT, 1, true)
    if not start or (start > 1 and path:sub(start-1,start-1) ~= "/") then return nil end
    local relative = path:sub(start + #ROOT)
    if relative == "" or relative:find("[:@]") then return nil end
    return relative
end
function Packs.IsScript(path)
    path = path:lower()
    return path:match("%.lua$") ~= nil or path:match("%.luau$") ~= nil
        or path:match("%.lua%.txt$") ~= nil or path:match("%.luau%.txt$") ~= nil
end
local function isMedia(path)
    return not Packs.IsScript(path) and not path:lower():match("%.uhmaker%.json$")
        and media[path:lower():match("%.([^./]+)$")] == true
end
function Packs.new(deps)
    local api = {Files={},Scopes={},All={}}
    local function report(message) if deps.Report then deps.Report(message) end end
    function api.Scan()
        local files,visited,seen = {},{},{}
        local folders=0
        local function scan(folder,depth)
            if visited[folder] then return end
            visited[folder]=true folders+=1
            if depth>32 or folders>4096 then report("User module folder limit at "..folder) return end
            local ok,entries=pcall(deps.List,folder)
            if not ok or type(entries)~="table" then report("Could not list "..folder) return end
            local ordered={}
            for _,entry in pairs(entries) do if type(entry)=="string" then table.insert(ordered,entry) end end
            table.sort(ordered)
            for _,entry in ipairs(ordered) do
                local path=clean(entry)
                if path and not path:find("/",1,true) then path=folder..path end
                local relative=path and Packs.Relative(path)
                if not relative then report("Skipped invalid module path: "..tostring(entry)) continue end
                path=ROOT..relative
                -- A returned directory must belong to the folder being listed.
                if path:sub(1,#folder)~=folder then report("Skipped unrelated module path: "..path) continue end
                local folderOk,directory=pcall(deps.IsFolder,path)
                if folderOk and directory then scan(path:gsub("/+$","").."/",depth+1)
                elseif not seen[path] then
                    local fileOk,exists=pcall(deps.IsFile,path)
                    if fileOk and exists then
                        if #files>=16384 then report("User module file limit reached") return end
                        seen[path]=true table.insert(files,path)
                        if deps.Yield and #files%64==0 then deps.Yield() end
                    end
                end
            end
        end
        scan(ROOT,0) table.sort(files) api.Files=files
        return files
    end
    local function scopeFor(relative)
        return relative:match("^([^/]+/)") or ""
    end
    function api.Stage(files)
        api.Scopes={} api.All={}
        -- Index first, then stage all media before a module factory can read it.
        for _,path in ipairs(files) do
            local relative=Packs.Relative(path)
            if relative and isMedia(relative) then
                local scope=scopeFor(relative)
                local group=api.Scopes[scope] or {Exact={},Folded={},Leaves={}}
                api.Scopes[scope]=group
                local name=relative:sub(#scope+1)
                local record={Reference="USER/"..relative,Source=path}
                group.Exact[name]=record
                api.All[relative]=record
                for index,key in pairs({Folded=name:lower(),Leaves=(name:match("[^/]+$") or name):lower()}) do
                    local map=group[index]
                    if map[key]~=nil and map[key]~=record then map[key]=false else map[key]=record end
                end
            end
        end
        for _,group in pairs(api.Scopes) do for _,record in pairs(group.Exact) do
            local ok,reason=pcall(function()
                local bytes=deps.Read(record.Source)
                assert(type(bytes)=="string" and #bytes<=(deps.MaximumAssetBytes or 64*1024*1024),"media exceeds 64 MiB")
                local destination=deps.Path(record.Reference)
                local existed,previous=pcall(deps.Read,destination)
                if existed and previous==bytes then record.Ready=true return end
                deps.Folders(destination)
                local wrote,failure=pcall(function()
                    deps.Write(destination,bytes)
                    assert(deps.Read(destination)==bytes,"media write verification failed")
                end)
                if not wrote then
                    if existed then pcall(deps.Write,destination,previous)
                    elseif deps.Delete then pcall(deps.Delete,destination) end
                    error(failure,0)
                end
                if deps.Invalidate then deps.Invalidate(destination) end
                record.Ready=true
            end)
            if not ok then record.Error=tostring(reason) report("Local media "..record.Source..": "..tostring(reason)) end
            if deps.Yield then deps.Yield() end
        end end
    end
    function api.Context(path)
        local relative=Packs.Relative(path)
        assert(relative,"invalid user module path")
        local scope=scopeFor(relative)
        local group=api.Scopes[scope] or {Exact={},Folded={},Leaves={}}
        local directory=relative:sub(#scope+1):match("^(.*)/[^/]+$") or ""
        local assets={}
        for name,record in pairs(group.Exact) do assets[name]=record.Reference end
        for name,record in pairs(group.Leaves) do if record and assets[name]==nil then assets[name]=record.Reference end end
        if scope=="" then for name,record in pairs(api.All) do assets[name]=record.Reference end end
        if directory~="" then
            local prefix=directory.."/"
            for name,record in pairs(group.Exact) do
                if name:sub(1,#prefix)==prefix then assets[name:sub(#prefix+1)]=record.Reference end
            end
        end
        return {LocalPack=true,Group=group,All=scope=="" and api.All or nil,
            Directory=directory,
            Assets=assets,Provider="Local folder",ModuleFile=relative,SourceLabel="Installed: "..relative}
    end
    function api.Resolve(context,reference)
        assert(type(reference)=="string","asset reference must be text")
        if reference:find("@",1,true) or reference:sub(1,5)=="USER/" then return reference end
        local normalized=clean(reference)
        if not normalized or normalized:sub(1,1)=="/" or normalized:find(":",1,true) then return reference,true end
        local group=context.Group
        local localName=context.Directory~="" and context.Directory.."/"..normalized or normalized
        local record=group.Exact[localName] or group.Exact[normalized]
            or (context.All and context.All[normalized])
        if not record then
            local value=group.Folded[localName:lower()]
            if value==nil then value=group.Folded[normalized:lower()] end
            if value==nil and not normalized:find("/",1,true) then value=group.Leaves[normalized:lower()] end
            if value==false then return reference,true end
            record=value
        end
        if record then return record.Reference,not record.Ready end
        -- A pack can deliberately use stock or explicitly hosted media.
        return reference
    end
    return api
end
return Packs
