-- Nooby-inspired reversible visual options. Avatars stay parented so selection,
-- animation providers and game scripts can still find their real character.
return function(ctx)
    local api={LowDetail=false,HidePlayers=false,Status="normal detail"}
    local records,connections,playerConnections={}, {},{}
    local playerCharacters,otherCharacters={},{}
    local pending,scheduled={},false
    local spawn=ctx.Defer or task.defer
    local stopped=false
    local count=0
    local worldTextures={Decal={"Texture"},Texture={"Texture"},MeshPart={"TextureID"},SpecialMesh={"TextureId"},
        SurfaceAppearance={"ColorMap","MetalnessMap","NormalMap","RoughnessMap"}}
    local effects={ParticleEmitter=true,Trail=true,Beam=true,Smoke=true,Fire=true,Sparkles=true}
    local function inCharacter(object)
        local current=object
        while current and current~=ctx.World do
            if current.Name=="UhhhhhhEditorProps"or current.Name=="UhhhhhhStudioPreview"
                or current.Name=="_UhhhhhhDanceEffectVisualizer"or current.Name=="_UhhhhhhDanceEffectAfterimage"then return true end
            if current:IsA("Tool")or current:IsA("Accessory")or current:IsA("Accoutrement")then return true end
            if current:IsA("Model")and current:FindFirstChildOfClass("Humanoid")then return true end
            if current==ctx.Player.Character or current==ctx.Reanimate.Character then return true end
            current=current.Parent
        end
        return false
    end
    local function otherPlayer(object)
        local current=object
        while current and current~=ctx.World do
            if otherCharacters[current]then return true end
            current=current.Parent
        end
        return false
    end
    local function release(object,property)
        local props=records[object]local record=props and props[property]
        if not record then return end
        props[property]=nil record.Connection:Disconnect()
        pcall(function()if object[property]==record.Written then object[property]=record.Original end end)
        if next(props)==nil then records[object]=nil count-=1 end
    end
    local function write(object,property,value)
        local props=records[object]local record=props and props[property]
        if record then return end
        local ok,original=pcall(function()return object[property]end)
        if not ok or original==nil then return end
        local changed=pcall(function()object[property]=value end)if not changed then return end
        if not props then props={}records[object]=props count+=1 end
        record={Original=original,Written=value}props[property]=record
        record.Connection=object:GetPropertyChangedSignal(property):Connect(function()
            if stopped or not records[object]or records[object][property]~=record then return end
            pcall(function()
                if object[property]~=record.Written then
                    record.Original=object[property]object[property]=record.Written
                end
            end)
        end)
    end
    local function process(object)
        if stopped then return end
        local desired={}
        if object:IsDescendantOf(ctx.World)then
            if api.HidePlayers and otherPlayer(object)then
                if object:IsA("BasePart")then desired.LocalTransparencyModifier=1
                elseif object:IsA("Decal")or object:IsA("Texture")then desired.Transparency=1
                elseif effects[object.ClassName]or object:IsA("Light")or object:IsA("BillboardGui")or object:IsA("SurfaceGui")or object:IsA("Highlight")then desired.Enabled=false end
            end
            if api.LowDetail and not inCharacter(object)then
                for _,property in ipairs(worldTextures[object.ClassName]or {})do desired[property]=""end
                if effects[object.ClassName]then desired.Enabled=false end
                if object:IsA("BasePart")then desired.CastShadow=false end
            end
        end
        local old=records[object]
        if old then
            local properties={}for property in pairs(old)do table.insert(properties,property)end
            for _,property in ipairs(properties)do if desired[property]==nil then release(object,property)end end
        end
        for property,value in pairs(desired)do write(object,property,value)end
    end
    local function drain()
        if stopped then return end
        local count=0
        for object in pairs(pending)do
            pending[object]=nil process(object)count+=1
            if count>=256 then break end
        end
        if next(pending)then spawn(drain)else scheduled=false end
    end
    local function queue(object)
        if stopped or not(api.LowDetail or api.HidePlayers or records[object])then return end
        pending[object]=true
        if not scheduled then scheduled=true spawn(drain)end
    end
    function api.Refresh()
        for object in pairs(records)do queue(object)end
        if api.LowDetail or api.HidePlayers then for _,object in ipairs(ctx.World:GetDescendants())do queue(object)end end
    end
    function api.SetLowDetail(on)api.LowDetail=on==true api.Refresh()end
    function api.SetHidePlayers(on)api.HidePlayers=on==true api.Refresh()end
    local function watch(player)
        if playerConnections[player]then return end
        local function characterAdded(character)
            local previous=playerCharacters[player]
            if previous then
                otherCharacters[previous]=nil
                for _,object in ipairs(previous:GetDescendants())do queue(object)end
            end
            playerCharacters[player]=character
            if player~=ctx.Player then otherCharacters[character]=true end
            for _,object in ipairs(character:GetDescendants())do queue(object)end
        end
        playerConnections[player]=player.CharacterAdded:Connect(characterAdded)
        if player.Character then characterAdded(player.Character)end
    end
    for _,player in ipairs(ctx.Players:GetPlayers())do watch(player)end
    table.insert(connections,ctx.Players.PlayerAdded:Connect(watch))
    table.insert(connections,ctx.Players.PlayerRemoving:Connect(function(player)
        if playerConnections[player]then playerConnections[player]:Disconnect()playerConnections[player]=nil end
        local character=playerCharacters[player]
        if character then otherCharacters[character]=nil playerCharacters[player]=nil end
        if player.Character then for _,object in ipairs(player.Character:GetDescendants())do queue(object)end end
    end))
    table.insert(connections,ctx.World.DescendantAdded:Connect(queue))
    table.insert(connections,ctx.World.DescendantRemoving:Connect(function(object)
        local properties=records[object]if not properties then return end
        local names={}for property in pairs(properties)do table.insert(names,property)end
        for _,property in ipairs(names)do release(object,property)end
        pending[object]=nil
    end))
    function api.Destroy()
        if stopped then return end stopped=true
        for _,connection in ipairs(connections)do connection:Disconnect()end
        for _,connection in pairs(playerConnections)do connection:Disconnect()end
        local objects={}for object in pairs(records)do table.insert(objects,object)end
        for _,object in ipairs(objects)do
            local properties={}for property in pairs(records[object]or {})do table.insert(properties,property)end
            for _,property in ipairs(properties)do release(object,property)end
        end
        table.clear(connections)table.clear(playerConnections)table.clear(pending)stopped=true
        table.clear(playerCharacters)table.clear(otherCharacters)
    end
    function api.Count()return count end
    return api
end
