-- Extend the original window, leaving its staged minimize/restore implementation intact.
return function(context)
    local Util, Theme, Window, Workspace = context.Util, context.Theme, context.Window, context.Workspace
    local clock = context.Clock or os.clock
    local top, title
    for _, child in ipairs(Window.Main:GetChildren()) do
        if child:IsA("Frame") and child ~= Window.Content.Parent then
            for _, control in ipairs(child:GetChildren()) do
                if control:IsA("TextLabel") then top, title = child, control break end
            end
        end
        if top then break end
    end
    assert(top and title, "native title bar missing")
    title.Font = context.Font or Enum.Font.Code
    title.RichText = false
    local clip = Window.Content.Parent
    -- UICorner on the native Frame does not mask its descendants. Keep the
    -- native outline/glow outside one rounded compositing surface, and reuse
    -- the existing title/content objects inside it (including all tweens).
    local surface = Util.Instance("CanvasGroup", Window.Main)
    surface.Name = "RoundedWindowContent"
    surface.Size, surface.Position = UDim2.fromScale(1, 1), UDim2.fromOffset(0, 0)
    surface.BackgroundTransparency, surface.BorderSizePixel = 1, 0
    surface.GroupTransparency, surface.ZIndex = 0, 0
    surface.Interactable = true
    local surfaceCorner = Util.Instance("UICorner", surface)
    top.Parent, clip.Parent = surface, surface
    top.ZIndex = 31 -- reveal above the full-window opaque scene
    local amount = Util.Instance("NumberValue", Window.Main)
    amount.Value = Window.Minimized and 1 or (Workspace.Enabled and 1 or 0)
    local line = Util.Instance("TextButton", surface)
    line.Name, line.Text, line.AutoButtonColor = "IdleHeaderLine", "", false
    line.BorderSizePixel, line.ZIndex, line.Visible = 0, 30, false
    line.AnchorPoint = Vector2.new(.5, 0)
    line.Position = UDim2.new(.5, 0, 0, 0)
    Util.Instance("UICorner", line).CornerRadius = UDim.new(1, 0)
    line.Size = UDim2.new(1, 0, 0, 3)
    Theme.ApplyFrame(line, {Fill = true})
    -- Touch keeps a generous invisible hit target while displaying only the hairline.
    local reveal = Util.Instance("TextButton", surface)
    reveal.Name, reveal.Text, reveal.AutoButtonColor = "RevealHeader", "", false
    reveal.BackgroundTransparency, reveal.BorderSizePixel, reveal.ZIndex = 1, 0, 40
    reveal.Active, reveal.Interactable = true, true
    reveal.Size, reveal.Visible = UDim2.new(1, 0, 0, 20), false
    local lastUsed, hover, pressed, goal, tween = clock(), false, false, amount.Value, nil
    local hovered = {}
    local chrome = {Line = line, Reveal = reveal, Amount = amount, Surface = surface}
    local corner, thickness = 5, 3
    local function expand(value)
        if goal == value then return tween end
        goal = value
        if tween then tween:Cancel() end
        tween = context.TweenService:Create(amount, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Value = value})
        tween:Play()
        return tween
    end
    function chrome.Wake()
        lastUsed = clock()
        return expand(1)
    end
    local function connect(signal, callback)
        Util.LinkDestroyI2C(Window.Main, signal:Connect(callback))
    end
    for _, area in ipairs({top, Workspace.Bar, line, reveal}) do
        connect(area.MouseEnter, function() hovered[area] = true; hover = true; chrome.Wake() end)
        connect(area.MouseLeave, function() hovered[area] = nil; hover = next(hovered) ~= nil; lastUsed = clock() end)
        connect(area.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                pressed = true chrome.Wake()
            end
        end)
    end
    connect(reveal.Activated, chrome.Wake)
    connect(context.Input.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
            pressed = false lastUsed = clock()
            if input.UserInputType == Enum.UserInputType.Touch then hover = false; table.clear(hovered) end
        end
    end)
    if context.Input.WindowFocusReleased then
        connect(context.Input.WindowFocusReleased, function()
            pressed, hover, lastUsed = false, false, clock()
            table.clear(hovered)
        end)
    end
    Util.LinkDestroyI2C(Window.Main, Theme.OnChanged("CornerRadius", function(value)
        corner = math.max(0, tonumber(value) or 5)
        surfaceCorner.CornerRadius = UDim.new(0, corner)
    end))
    Util.LinkDestroyI2C(Window.Main, Theme.OnChanged("WindowOutlineSize", function(value)
        thickness = math.clamp((tonumber(value) or 1) + 2, 2, 4)
    end))
    Workspace.OnEnabledChanged = function()
        if Workspace.Enabled then chrome.Wake() else expand(hover and 1 or 0) end
        -- Intro owns the full content canvas; enabling the workspace pops the
        -- title and tabs out together without rebuilding any menu controls.
        Workspace.Bar.Visible = Workspace.Enabled
    end
    local lastWidth, geometry = nil, {}
    context.Render(function()
        local enabled = Workspace.Enabled
        if Window.Minimized then
            expand(1)
        elseif hover or pressed then
            expand(1)
        elseif not enabled and clock() - lastUsed >= 3 then
            expand(0)
        elseif clock() - lastUsed >= 3 then
            expand(0)
        end
        local alpha = math.clamp(amount.Value, 0, 1)
        if Window.Minimized then alpha = 1 end
        local headerHeight = enabled and thickness + (30 - thickness) * alpha or 30 * alpha
        local tabHeight = enabled and 40 * alpha or 0
        line.Visible, reveal.Visible = alpha < 0.1 and not Window.Minimized, alpha < 0.5 and not Window.Minimized
        top.Visible = alpha > 0.01
        local width, height, sidebar = Window.Size.X.Offset, Window.Size.Y.Offset, math.max(0, Window.SidebarSize)
        if geometry.Alpha ~= alpha or geometry.Width ~= width or geometry.Height ~= height
            or geometry.Corner ~= corner or geometry.Thickness ~= thickness or geometry.Enabled ~= enabled or geometry.Sidebar ~= sidebar then
            geometry.Alpha, geometry.Width, geometry.Height = alpha, width, height
            geometry.Corner, geometry.Enabled, geometry.Sidebar = corner, enabled, sidebar
            geometry.Thickness = thickness
            line.Size = UDim2.new(1, -2 * math.max(corner + 2, 4), 0, thickness)
            top.Size = UDim2.new(1, 0, 0, headerHeight)
            clip.Position = UDim2.new(0.5, 0, 0, headerHeight)
            clip.Size = UDim2.new(1, 0, 1, -headerHeight - corner)
            geometry.Content = UDim2.fromOffset(width - sidebar, height - headerHeight - corner)
            Workspace.Bar.Position = UDim2.fromOffset(5.5, 4 * alpha)
            Workspace.Bar.Size = UDim2.new(1, -13, 0, 32 * alpha)
            Workspace.Slot.Position = UDim2.fromOffset(0, tabHeight)
            Workspace.Slot.Size = UDim2.new(1, 0, 1, -tabHeight)
        end
        -- The unchanged native renderer also sizes this; reuse the cached value.
        if Window.Content.Size ~= geometry.Content then Window.Content.Size = geometry.Content end
        Workspace.Bar.Visible = enabled and alpha > 0.01
        Workspace.Bar.Interactable = enabled and alpha > 0.5
        if width ~= lastWidth then
            lastWidth = width
            -- Fit the long title at its normal scale instead of clipping it.
            local measured = Util.GetTextSize(title.Text, 18, title.Font, Vector2.new(math.huge, math.huge)).X
            title.TextSize = math.clamp(math.floor(18 * math.max(width - 40, 1) / math.max(measured, 1)), 10, 18)
        end
    end, Window.Main, true)
    Window.Main.Destroying:Once(function() if tween then tween:Cancel() end end)
    return chrome
end
