Util.IsGuiVisible = function(guiObject)
	if not guiObject or not guiObject:IsA("GuiObject") then
		return false
	end
	local original = guiObject
	local position, size = guiObject.AbsolutePosition, guiObject.AbsoluteSize
	local left, top = position.X, position.Y
	local right, bottom = left + size.X, top + size.Y
	if size.X <= 0 or size.Y <= 0 then return false end
	while guiObject do
		if guiObject == Util.DraggedWindow and original ~= guiObject then return false end
		if not guiObject.Visible then
			return false
		end
		-- Roblox clips these pixels, but Visible remains true when a decoration
		-- scrolls offscreen. Stop its Lua renderer as well, including ASCII effects.
		if guiObject ~= original and (guiObject.ClipsDescendants or guiObject:IsA("ScrollingFrame")) then
			local p, s = guiObject.AbsolutePosition, guiObject.AbsoluteSize
			left, top = math.max(left, p.X), math.max(top, p.Y)
			right, bottom = math.min(right, p.X + s.X), math.min(bottom, p.Y + s.Y)
			if right <= left or bottom <= top then return false end
		end
		guiObject = guiObject:FindFirstAncestorWhichIsA("GuiObject")
	end
	local screen = original:FindFirstAncestorOfClass("ScreenGui")
	if screen and not screen.Enabled then return false end
	return true
end
Util.IsGuiInteractable = function(guiObject)
	if not guiObject or not guiObject:IsA("GuiObject") then
		return false
	end
	while guiObject do
		if not guiObject.Visible or not guiObject.Interactable then
			return false
		end
		guiObject = guiObject:FindFirstAncestorWhichIsA("GuiObject")
	end
	return true
end
