			stevetherealone.Text = ""
			stevetherealone.Visible = false
		elseif t < 2.652 then
			local a = (t - 2.152) / 0.5
			local z = 20 * ((a * 100) // 20)
			stevetherealone.Text = ""
			stevetherealone.Visible = true
			stevetherealone.Size = UDim2.fromOffset(z, z)
