			stevetherealone.Size = UDim2.fromOffset(x, y)
			stevetherealone.Position = UDim2.new(0.5, 0, 0.5, 0)
		end
	end
	stevetherealone:Destroy()
	Triforce1:Destroy()
	Triforce2:Destroy()
