	else
		DevTheme.Set(index)
	end
	if UISound and UISound.Click then
		UISound.Click.SoundId = DevTheme.ClickSoundId
	end
	if not preview and DevTheme.OnThemeSelected then DevTheme.OnThemeSelected(index)end
end

