        return Steve110.Require("main/reanimation/hat_nodeath").Run({
            Player=Player,RunService=RunService,Reanimate=Reanimate,HatReanimator=HatReanimator,
            Camera=Camera,NetworkOwner=env.isnetworkowner or isnetworkowner,
