        if not backend or not backend.GetStatus or Reanimate.Starting or Reanimate.Stopping then return end
        local message=backend.Name..": "..backend.GetStatus()
        if ReanimateText.Text~=message then ReanimateText.Text=message end
    end,ReanimateText)
	local ReanimateStartButton, ReanimateStartButtonText = UI.CreateButton(MainPage, "* Reanimate *", 20)
	ReanimateStartButton.Activated:Connect(function()
		if not Reanimate.Current and SelectedReanimator == HatReanimator
			and HatReanimator.Permadeath and HatReanimator.PermadeathMethod == 3
			and not RejectCharacterDeletionsDisabled then
			Util.UINotify("Old Gelatek Head Break needs RejectCharacterDeletions = Disabled (currently "
				.. tostring(RejectCharacterDeletionsState) .. ").")
			return
		end
		ReanimateStartButton.Interactable = false
		if Reanimate.Current then
			ReanimateStartButtonText.Text = "Stopping..."
			if type(Reanimate.SuspendPhysicsHead) == "function" then
				Reanimate.SuspendPhysicsHead("manual deanimate")
			end
			Reanimate.Stopping = true
			repeat
				task.wait()
			until not Reanimate.Stopping
			if Reanimate.Current then
				Reanimate.Current.Running = nil
				Reanimate.Current = nil
			end
			HumanoidLASetHookState(false)
			ReanimateText.Text = "Running: NONE"
			task.wait(1)
			ReanimateStartButtonText.Text = "* Reanimate *"
		else
			if type(Reanimate.ResumePhysicsHead) == "function" then
				Reanimate.ResumePhysicsHead()
			end
			ReanimateStartButtonText.Text = "Starting..."
			Reanimate.Starting = true
			Reanimate.Current = SelectedReanimator
			Reanimate.LastBackend = SelectedReanimator
			HumanoidLASetHookState(Reanimate.UseLoadAnimationHook)
			ReanimateText.Text = "Running: " .. Reanimate.Current.Name
			local __TheoStarted = Reanimate.Current
			task.spawn(__TheoStarted.Start)
			repeat
				task.wait()
			until not Reanimate.Starting
			local __TheoExternal = __TheoStarted.ManagedLifecycle or __TheoStarted == GelatekReanimator or __TheoStarted == LooseBodyReanimators.Ragdoll or __TheoStarted == LooseBodyReanimators.Tools
			if __TheoExternal and not __TheoStarted.Running then
				__TheoStarted.Running = nil
				Reanimate.Current = nil
				HumanoidLASetHookState(false)
				ReanimateText.Text = "Running: NONE"
				ReanimateStartButtonText.Text = "* Reanimate *"
			else
				__TheoStarted.Running = true
				task.wait(1)
				ReanimateStartButtonText.Text = "* Deanimate *"
			end
		end
		ReanimateStartButton.Interactable = true
	end)
	__TheoLifecycle.Complete = function(backend)
		if backend then backend.Running = nil end
		if Reanimate.Stopping then
			Reanimate.Stopping = false
			return
		end
		if Reanimate.Current == backend then
			Reanimate.Current = nil
			HumanoidLASetHookState(false)
			ReanimateText.Text = "Running: NONE"
			ReanimateStartButtonText.Text = "* Reanimate *"
			ReanimateStartButton.Interactable = true
		end
	end
	UI.CreateSwitch(UI.Navigation.Pages.diagnostics, "Show Controller Character", Reanimate.ShowControllerCharacter).Changed:Connect(function(value)
		Reanimate.ShowControllerCharacter = value
		SaveData.ShowControllerCharacter = value
		Reanimate.ApplyControllerVisibility()
	end)
	UI.CreateText(
		UI.Navigation.Pages.diagnostics,
		"shows the controller body locally for Limb, Hats, and Gelatek; HumanoidRootPart stays hidden",
		10,
		Enum.TextXAlignment.Center
	)
	UI.CreateSwitch(UI.Navigation.Pages.diagnostics, "Show Reanimate Hitboxes", Reanimate.ShowHitboxes).Changed:Connect(function(value)
		Reanimate.ShowHitboxes = value
		SaveData.ShowReanimateHitboxes = value
		ReanimateShowHitboxes()
	end)
	UI.CreateText(
		UI.Navigation.Pages.diagnostics,
		"red = bound real torso/root | cyan = controller rootpart | thick green = mapped Hat limbs | thin green = collidable hats",
		10,
		Enum.TextXAlignment.Center
	)
	UI.CreateButton(UI.Navigation.Pages.diagnostics, "Refresh Reanimate Character", 10).Activated:Connect(function()
		if not Reanimate.Character then return end
		-- Serialize refresh with Destroy/Init, rather than replacing a model in
		-- the middle of a yielding community module's animation update.
		__TheoManualRefreshSerial += 1
	end)
end
