if type(SaveData.AnimLibOptions) ~= "table" then
	SaveData.AnimLibOptions = {}
end
local SavedAnimLibOptions = SaveData.AnimLibOptions
SavedAnimLibOptions.Speed = math.clamp(tonumber(SavedAnimLibOptions.Speed) or 1, 0.25, 2)
SavedAnimLibOptions.FadeIn = math.clamp(tonumber(SavedAnimLibOptions.FadeIn) or 0, 0, 1)
SavedAnimLibOptions.JointPreset = type(SavedAnimLibOptions.JointPreset) == "string" and SavedAnimLibOptions.JointPreset
	or "Full Body"
SavedAnimLibOptions.SyncToDanceMusic = SavedAnimLibOptions.SyncToDanceMusic == true
SavedAnimLibOptions.ApplySpeedToMusic = SavedAnimLibOptions.ApplySpeedToMusic == true
SavedAnimLibOptions.MarkerNotifications = SavedAnimLibOptions.MarkerNotifications == true
SavedAnimLibOptions.ResetPoseOnStop = SavedAnimLibOptions.ResetPoseOnStop == true
SavedAnimLibOptions.OverrideWalkSpeed = SavedAnimLibOptions.OverrideWalkSpeed == true
SavedAnimLibOptions.WalkSpeed =
	math.clamp(tonumber(SavedAnimLibOptions.WalkSpeed) or 16, 0, 500)
-- Migrate the old render-only Krystal neck overlay into the physics head
-- driver. Keep the old keys in the save for rollback compatibility, but the
-- runtime and GUI use only the new Immersive VR-derived settings.
if SavedAnimLibOptions.PhysicsHeadTracking == nil then
	SavedAnimLibOptions.PhysicsHeadTracking = SavedAnimLibOptions.KrystalHeadTracking == true
end
if SavedAnimLibOptions.PhysicsHeadBlendAnimation == nil then
	SavedAnimLibOptions.PhysicsHeadBlendAnimation = SavedAnimLibOptions.KrystalHeadOverride == false
end
SavedAnimLibOptions.PhysicsHeadTracking = SavedAnimLibOptions.PhysicsHeadTracking == true
SavedAnimLibOptions.PhysicsHeadBlendAnimation = SavedAnimLibOptions.PhysicsHeadBlendAnimation == true
SavedAnimLibOptions.PhysicsHeadStrength = math.clamp(
	tonumber(SavedAnimLibOptions.PhysicsHeadStrength)
		or tonumber(SavedAnimLibOptions.KrystalHeadStrength)
		or 1,
	0,
	1
)
SavedAnimLibOptions.PhysicsHeadSmoothing = math.clamp(
	tonumber(SavedAnimLibOptions.PhysicsHeadSmoothing)
		or tonumber(SavedAnimLibOptions.KrystalHeadSmoothing)
		or 10,
	1,
	30
)
SavedAnimLibOptions.KeepAccessoriesWhenHiding = SavedAnimLibOptions.KeepAccessoriesWhenHiding ~= false
if type(SavedAnimLibOptions.DisabledAnimationParts) ~= "table" then
	SavedAnimLibOptions.DisabledAnimationParts = {}
end
for partName, disabled in SavedAnimLibOptions.DisabledAnimationParts do
	if type(partName) ~= "string" or disabled ~= true then
		SavedAnimLibOptions.DisabledAnimationParts[partName] = nil
	end
end
if type(SavedAnimLibOptions.ReplicationWriters) ~= "table" then
	SavedAnimLibOptions.ReplicationWriters = {}
end
local ReplicationWriterDefaults = {
	GelatekTorso = "Gelatek Physics",
	GelatekHead = "ReplicateCurrentAngle6D",
	LimbTorso = "ReplicateCurrentAngle6D",
	LimbHead = "ReplicateCurrentAngle6D",
	LimbRightArm = "ReplicateCurrentAngle6D",
	LimbLeftArm = "ReplicateCurrentAngle6D",
	LimbRightLeg = "ReplicateCurrentAngle6D",
	LimbLeftLeg = "ReplicateCurrentAngle6D",
}
for key, value in pairs(ReplicationWriterDefaults) do
	if SavedAnimLibOptions.ReplicationWriters[key] == nil
		or SavedAnimLibOptions.ReplicationWriters[key] == "CurrentAngle6D"
	then
		SavedAnimLibOptions.ReplicationWriters[key] = value
	end
end
if SavedAnimLibOptions.ReplicationWriters.GelatekTorso == "PhysicsRepRootPart" then
	SavedAnimLibOptions.ReplicationWriters.GelatekTorso = "PhysicsRepRootRef"
