local function EnsureAssetFolders(path)
	local parent = path:match("^(.*)/[^/]+$")
	local current = ""
	for segment in parent:gmatch("[^/]+") do
		current = current == "" and segment or current .. "/" .. segment
		if not isfolder(current) then makefolder(current) end
	end
end
