local _Assetdownloadingcount, _Assetdownloadingfail = 0, 0
local function _UpdateDownloadStatus()
	local prog = 1 / ((_Assetdownloadingcount + _Assetdownloadingfail) / 2 + 1)
	if _Assetdownloadingcount > 0 then
		Util.UINotify("Downloading " .. _Assetdownloadingcount .. " assets...", prog)
	else
		if _AssetLastFailure and Util.CommunityDiagnostics.Enabled() then
			Util.UINotify(_AssetLastFailure.Message,1)
		else
			Util.UINotify("Downloads finished", 1)
		end
	end
end
local function RecordContentFailure(kind, name, source, reason)
    if kind == "asset-download" then
        source = tostring(source):match("https?://([^/]+)") or source
        reason = tostring(reason):gsub("https?://[^%s]+", "[source]"):sub(1, 280)
    end
    if kind == "asset-download" or kind == "asset-register" or kind == "user-module" then
        Util.CommunityDiagnostics.Report(kind, name, source, reason)
        return
    end
    warn(("Uhhhhhh %s: %s (%s): %s"):format(
        tostring(kind), tostring(name), tostring(source), tostring(reason)))
end

local function EncodeAssetPath(path)
	path = tostring(path):gsub("\\", "/")
	local encoded = {}
	local index = 1
	while index <= #path do
		local character = path:sub(index, index)
		local escape = path:sub(index, index + 2)
		if character == "%" and escape:match("^%%%x%x$") then
			table.insert(encoded, escape)
			index += 3
		elseif character:match("[%w%-%._~/]") then
			table.insert(encoded, character)
			index += 1
		else
			table.insert(encoded, string.format("%%%02X", string.byte(character)))
			index += 1
		end
	end
	return table.concat(encoded)
end

local function NormalizeDownloadUrl(source)
    source = tostring(source)
    local owner, repository, kind, tail = source:match("^https?://github%.com/([^/]+)/([^/]+)/([^/]+)/(.+)$")
    if owner and (kind == "raw" or kind == "blob") then
        source = "https://raw.githubusercontent.com/" .. owner .. "/" .. repository .. "/" .. tail
    end
    if source:match("^https://raw%.githubusercontent%.com/") then
        source = source:gsub("/refs/heads/", "/", 1):gsub("/refs/tags/", "/", 1)
        source = source:match("^[^?]+") -- GitHub's ?raw=true is unnecessary on the raw host.
    end
    local host, path = source:match("^(https?://[^/]+)/(.*)$")
    if not host then return source end
    local pathname, query = path:match("^(.-)%?(.*)$")
    if pathname then return host .. "/" .. EncodeAssetPath(pathname) .. "?" .. query end
    return host .. "/" .. EncodeAssetPath(path)
end

local GitHubAssets = Steve110.Require("main/asset_sources")({
    Recovery=Steve110.Require("main/market_recovery"),
    Fetch = HttpFetchBody, DecodeJson = function(body) return HttpService:JSONDecode(body) end,
    Yield = task.wait,
})

local function AssetSourceCandidates(sources)
    if type(sources) == "string" then sources = {sources} end
    local candidates, seen = {}, {}
    local function add(url)
        if not seen[url] then seen[url] = true; table.insert(candidates, url) end
    end
    for _, source in ipairs(sources or {}) do
        local url = NormalizeDownloadUrl(source)
        local relative = url:match("^https://raw%.githubusercontent%.com/STEVE%-916%-create/Uhhhhhh/main/community/(.+)$")
            or url:match("^https://raw%.githubusercontent%.com/STEVE%-916%-create/Uhhhhhh/master/community/(.+)$")
        local storeUrl = GitHubAssets.RawCandidate(url)
        if storeUrl then add(storeUrl) end
        if not storeUrl and relative and not relative:match("%.lua$") and not relative:match("%.lua%.txt$") then
            add("https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh-Store/main/"..relative)
        end
        local prefix = "https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
        -- Current community is a gitlink/submodule, not a raw directory. This
        -- also repairs explicit @URL assets, which bypassed the MARKET fallback.
        if url:sub(1, #prefix) == prefix then
            local ref, relative = url:sub(#prefix + 1):match("^([^/]+)/(community/.+)$")
            if ref and (ref == "main" or ref == "master") then add(prefix .. STEVE_AUDITED_REVISION .. "/" .. relative) end
        end
        add(url)
    end
    return candidates
end

local function AssetDownloadAgent(sources, filename, path, force, transform, consumer, localCopies, completed)
    local streamTicket = StreamCache.Ticket(path)
    if not StreamCache.Current(path, streamTicket) then
        if completed then completed(false,"Download cancelled") end return false
    end
    if not force and HasCachedAsset(path) then
        if completed then completed(true) end return true
    end
    if _Assetdownloading[path] then
        if completed then table.insert(_Assetdownloading[path],completed) end return false
    end
    local retry = _Assetretry[path]
    if force then retry = nil end
    if retry and os.clock() < retry.NextAttempt then
        if completed then completed(false,retry.LastError) end return false
    end
    sources = AssetSourceCandidates(sources)
    _Assetdownloading[path] = completed and {completed} or {}
    _Assetdownloadingcount += 1
    CONTENT_DOWNLOAD_ACTIVE += 1 -- includes queued content; cosmetic HTTP yields to it
    _UpdateDownloadStatus()
    ContentQueue.Push(function()
        local cancelled = not StreamCache.Current(path, streamTicket)
        local allMissing = #sources > 0 or localCopies ~= nil
        local ran, downloaded, failure = pcall(function()
            if cancelled then return end
            local body
            local fetchFailures={}
            for _,copy in ipairs(localCopies or {}) do
                if copy~=path and HasCachedAsset(copy) then
                    local read,bytes=pcall(readfile,copy)
                    if read and ValidateContentBytes(path,bytes) then body=bytes; allMissing=false; break end
                end
            end
            local seenBlobs = {}
            for _, source in ipairs(body and {} or sources) do
                local candidate, reason = HttpFetchBody(source, nil, 1)
                if candidate and ValidateContentBytes(path, candidate) then allMissing = false; body = candidate; break end
                reason = candidate and "response is not valid " .. (path:match("%.[^./]+$") or "asset") .. " bytes" or tostring(reason)
                local fallback, fallbackReason = GitHubAssets.Fetch(source, seenBlobs)
                if fallback and ValidateContentBytes(path, fallback) then allMissing = false; body = fallback; break end
                if fallbackReason then reason ..= " / blob fallback: " .. tostring(fallbackReason) end
                local missing = reason:match("HTTP[^%d]*404") or reason:find("status=404", 1, true)
                    or reason:find("404: Not Found", 1, true)
                if not missing then allMissing = false end
                local location=source:match("https?://[^/]+/(.+)") or source
                table.insert(fetchFailures,location..": "..reason:sub(1,280))
            end
            if not StreamCache.Current(path, streamTicket) then cancelled = true; return end
            -- Put the cause before the route details; do not report an
            -- arbitrary executor line number as the asset failure itself.
            if not body then
                if localCopies and #sources==0 then
                    return false,"No valid cached copy or verified upstream recovery route"
                end
                return false,(allMissing and "HTTP 404: upstream file not found" or "All asset sources failed")
                    .. " ("..table.concat(fetchFailures," | ")..")"
            end
            if transform then body = transform(body) end
            if path:match("%.lua$") or path:match("%.luau$") or path:match("%.lua%.txt$") then
                body=RepairCommunitySource(body)
                local compiled, compileError = loadstring(body, "@market/" .. filename)
                assert(compiled, "Module compile failed: " .. tostring(compileError))
            end
            StreamCache.Reserve(path, #body, streamTicket)
            EnsureAssetFolders(path)
            if not StreamCache.Current(path, streamTicket) then cancelled = true; return end
            local hadOriginal, original = pcall(readfile, path)
            local written, writeError = pcall(function()
                writefile(path, body)
                assert(readfile(path) == body, "asset write verification failed")
            end)
            if not written then
                if hadOriginal then pcall(writefile, path, original) end
                error(writeError)
            end
            if not StreamCache.Current(path, streamTicket) then
                cancelled = true; StreamCache.Discard(path); return
            end
            ContentCache.Verified(path)
            _AssetContentIds[path], _AssetRegistrationWarned[path] = nil, nil
            return true
        end)
        if not ran then failure,downloaded=downloaded,false end
        -- Always release dedupe, counters and worker capacity, including a thrown
        -- filesystem/URL/transport error. A failed job must not block the queue.
        local callbacks=_Assetdownloading[path]
        _Assetdownloading[path] = nil
        _Assetdownloadingcount = math.max(0, _Assetdownloadingcount - 1)
        CONTENT_DOWNLOAD_ACTIVE = math.max(0, CONTENT_DOWNLOAD_ACTIVE - 1)
        if downloaded or cancelled then
            _Assetretry[path] = nil
            if _AssetLastFailure and _AssetLastFailure.Path==path then _AssetLastFailure=nil end
        else
            ContentCache.Invalidate(path)
            local failures = (retry and retry.Failures or 0) + 1
            -- Repeated 404s cannot be fixed by re-downloading every few frames.
            -- Keep them retryable, but back off and retain quiet diagnostics.
            local delay = allMissing and 300 or math.min(3 * 2 ^ math.min(failures - 1, 4), 45)
            _Assetretry[path] = {Failures = failures, NextAttempt = os.clock() + delay, LastError = tostring(failure), Missing=allMissing}
            _AssetLastFailure={Path=path,Message=(filename:match("([^/]+)$") or filename)..": "..tostring(failure):sub(1,210)}
            if not consumer and (not retry or retry.LastError ~= tostring(failure)) then
                RecordContentFailure("asset-download", path, table.concat(sources, " | "), tostring(failure))
            end
            _Assetdownloadingfail += 1
            task.delay(0.75, function()
                _Assetdownloadingfail = math.max(0, _Assetdownloadingfail - 1)
                _UpdateDownloadStatus()
            end)
        end
        _UpdateDownloadStatus()
        for _,callback in ipairs(callbacks or {}) do
            pcall(callback,downloaded==true and not cancelled,cancelled and "Download cancelled" or failure)
        end
    end)
    return false
end

local function AssetDownload(filename, consumer)
	local cacheFilename = filename
	filename = filename:gsub("^STREAM/[^/]+/", "")
	local requested = filename
	if filename:sub(1,5)=="USER/" and not filename:find("@",1,true) then
		local path=AssetGetPathFromFilename(cacheFilename)
		return AssetDownloadAgent({},filename,path,nil,nil,consumer,{path})
	end
	local split = string.split(filename, "@")
	if #split > 1 then
		filename = table.remove(split, 1)
        local explicit = table.concat(split, "@")
        if explicit:sub(1,6)=="LOCAL/" then
            local original=explicit:sub(7)
            return AssetDownloadAgent({},filename,AssetGetPathFromFilename(cacheFilename),nil,nil,consumer,
                {AssetGetPathFromFilename(filename),AssetGetPathFromFilename(original)})
        end
		if explicit:sub(1, 7) == "MARKET/" then
			explicit = "https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/main/community/"
				.. EncodeAssetPath(explicit:sub(8))
		end
		return AssetDownloadAgent(
			{ explicit },
			filename,
			AssetGetPathFromFilename(cacheFilename),nil,nil,consumer
		)
	end

	local sources = {}
	if requested:sub(1, 7) == "MARKET/" then
		local relative = requested:sub(8)
		filename = relative
		table.insert(
			sources,
			"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
				.. STEVE_AUDITED_REVISION
				.. "/community/"
				.. EncodeAssetPath(relative)
		)
		table.insert(
			sources,
			"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/main/community/"
				.. EncodeAssetPath(relative)
		)
	else
		table.insert(
			sources,
			"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/"
				.. STEVE_AUDITED_REVISION
				.. "/content/"
				.. EncodeAssetPath(filename)
		)
		-- Community/user content can legitimately reference a file added after
		-- the audited startup revision. Main is a download fallback only; the
		-- executable built-in module source remains pinned separately.
		table.insert(
			sources,
			"https://raw.githubusercontent.com/STEVE-916-create/Uhhhhhh/main/content/"
				.. EncodeAssetPath(filename)
		)
	end

	return AssetDownloadAgent(
		sources,
		filename,
		AssetGetPathFromFilename(cacheFilename),nil,nil,consumer
	)
end

local function AssetGetContentId(filename)
	local path = AssetGetPathFromFilename(filename)
	if not HasCachedAsset(path) then
		return ""
	end
	if _AssetContentIds[path] then
		return _AssetContentIds[path]
	end
	local failure = "unknown"
	for attempt = 1, 4 do
		local s, id = pcall(getcustomasset, path)
		if s and type(id) == "string" and #id > 0 then
			_AssetContentIds[path] = id
			_AssetRegistrationWarned[path] = nil
			return id
		end
		failure = s and "empty content id" or tostring(id)
		if attempt < 4 then
			task.wait(0.05 * attempt)
		end
	end
	if not _AssetRegistrationWarned[path] then
		_AssetRegistrationWarned[path] = true
		RecordContentFailure("asset-register", filename, path, failure)
	end
	return ""
end
local function AssetEnsure(list,consumer)
	local ok,failedFile,failedReason,missing = true,nil,nil,false
	for _, filename in list do
		if not AssetDownload(filename,consumer) then
			ok = false
            local path=AssetGetPathFromFilename(filename)
            local retry=_Assetretry[path]
            if not failedFile and retry and not _Assetdownloading[path] then
                failedFile=tostring(filename):match("([^/@]+)@") or tostring(filename):match("([^/]+)$") or filename
                failedReason=retry.LastError
                missing=retry.Missing==true
            end
		end
	end
	return ok,failedFile,failedReason,missing
end
local function ProtectedChat(content)
	pcall(function()
		TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration").TargetTextChannel
			:SendAsync(content, Util.RandomString(64))
	end)
end
local OnPlayerChatted = Util.Instance("BindableEvent")
TextChatService.MessageReceived:Connect(function(message)
	if message.Status ~= Enum.TextChatMessageStatus.Sending and message.TextSource and message.TextSource.UserId then
		local plr, msg =
			Players:GetPlayerByUserId(message.TextSource.UserId),
			message.Text:gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&quot;", '"'):gsub("&apos;", "'"):gsub("&amp;", "&")
		if plr then
			OnPlayerChatted:Fire(plr, msg)
			if msg == "67" then
				Util.UINotify("SON :sob::sob::sob::sob:")
			end
			if msg == "1.1.0" then
				Util.UINotify("the overhaul update is real?")
			end
		end
	end
end)
task.wait()

local MovementStyles = {}
local DanceableDances = {}
local MainNavButtons = {}

local CurrentMovementStyle = nil
local MovementStyleIndex = 2
local _MovementStyleIndex = nil
local CurrentDance = nil
local _CurrentDance = nil
local OldReanimCharacter = nil

Reanimate.ReadModulePlayback = function(m)
    local figure=Reanimate.Character
    local moveset=m and m.ModuleType=="MOVESET"
    local selected=m~=nil and (moveset and MovementStyles[MovementStyleIndex]==m or not moveset and CurrentDance==m)
    local active=selected and figure and m._UhhhhhhRuntimeReady==true
        and (moveset and CurrentMovementStyle==m and figure:GetAttribute("MovementInit")==true
            or not moveset and _CurrentDance==m and figure:GetAttribute("IsDancing")==true)
    return Steve110.Require("main/module_playback_state").Read(m,{Selected=selected,Controller=figure,
        Playing=active==true,Loading=m and m._UhhhhhhLoadingAssets==true})
end

local function SetAnimLibOption(name, value)
	SavedAnimLibOptions[name] = value
	AnimLib.Settings[name] = value
	if name == "DisabledAnimationParts" then
		AnimLib.ApplyDisabledAnimationParts()
	end
	local saved, reason = SaveSettingsNow()
	if not saved then
		warn("AnimLib option save failed " .. tostring(name) .. ": " .. tostring(reason))
	end
end

local DEFAULT_CONTROLLER_WALKSPEED = 16

local function GetControllerHumanoid(figure)
	if typeof(figure) ~= "Instance" then
		return nil
	end
	return figure:FindFirstChildOfClass("Humanoid")
end

local function ResetMovesetWalkSpeed(figure)
	local humanoid = GetControllerHumanoid(figure)
	if not humanoid then
		return
	end
	if AnimLib.Settings.OverrideWalkSpeed then
		humanoid.WalkSpeed = AnimLib.Settings.WalkSpeed
	else
		-- Content is not required to restore WalkSpeed in Destroy().
		-- Reset at the framework boundary so speed cannot leak into the next
		-- moveset just because that next moveset never writes WalkSpeed.
		humanoid.WalkSpeed = DEFAULT_CONTROLLER_WALKSPEED
	end
end

local function EnforceWalkSpeedOverride(figure)
	if not AnimLib.Settings.OverrideWalkSpeed then
		return
	end
	local humanoid = GetControllerHumanoid(figure)
	if humanoid and humanoid.WalkSpeed ~= AnimLib.Settings.WalkSpeed then
		humanoid.WalkSpeed = AnimLib.Settings.WalkSpeed
	end
end

local function ResetDancePose(figure, force)
	if not force and not AnimLib.Settings.ResetPoseOnStop then
		return
	end
	if typeof(figure) ~= "Instance" then
		return
	end
	for _, descendant in figure:GetDescendants() do
		if descendant:IsA("Motor6D") then
			descendant.Transform = CFrame.identity
		end
	end
end

;(function()
-- Controller tracking is a Neck overlay; the Gelatek bridge transports the real Head.
local HeadTracking = Steve110.Require("main/head_tracking")
local PhysicsHeadDriver = {
	Character = nil,
	Head = nil,
	Root = nil,
	Torso = nil,
	Neck = nil,
	NeckWasEnabled = nil,
	OwnsNeck = false,
	AntiGravity = nil,
	RootToHeadOffset = Vector3.new(0, 1.5, 0),
	SmoothedRelative = CFrame.identity,
	TargetCFrame = nil,
	Status = "Physics head: disabled",
	Source = "Camera",
	Suspended = false,
	SuspendReason = nil,
	OwnerId = "UhhhhhhPhysicsHead_" .. Util.RandomString(24),
}

local function IsFinitePhysicsHeadCFrame(value)
	if typeof(value) ~= "CFrame" then
		return false
	end
	local position = value.Position
	return position.X == position.X
		and position.Y == position.Y
		and position.Z == position.Z
		and position.X > -math.huge
		and position.X < math.huge
		and position.Y > -math.huge
		and position.Y < math.huge
		and position.Z > -math.huge
		and position.Z < math.huge
end

local function FindPhysicsHeadParts(figure)
	if typeof(figure) ~= "Instance" then
		return nil
	end
	if PhysicsHeadDriver.Character == figure and PhysicsHeadDriver.Head and PhysicsHeadDriver.Head.Parent == figure
		and PhysicsHeadDriver.Root and PhysicsHeadDriver.Root.Parent == figure
		and PhysicsHeadDriver.Torso and PhysicsHeadDriver.Torso.Parent == figure
		and PhysicsHeadDriver.Neck and PhysicsHeadDriver.Neck.Parent then
		local part0, part1 = Util.GetCharacterJointParts(PhysicsHeadDriver.Neck)
		if part0 == PhysicsHeadDriver.Torso and part1 == PhysicsHeadDriver.Head then
			return PhysicsHeadDriver.Head, PhysicsHeadDriver.Root, PhysicsHeadDriver.Torso, PhysicsHeadDriver.Neck
		end
	end
	local head = figure:FindFirstChild("Head")
	local root = figure:FindFirstChild("HumanoidRootPart")
	local torso = figure:FindFirstChild("Torso")
		or figure:FindFirstChild("UpperTorso")
		or figure:FindFirstChild("LowerTorso")
	if not head
		or not head:IsA("BasePart")
		or not root
		or not root:IsA("BasePart")
		or not torso
		or not torso:IsA("BasePart")
	then
		return nil
	end
	local neck = torso:FindFirstChild("Neck")
	if neck and Util.IsCharacterJoint(neck) then
		local _, part1 = Util.GetCharacterJointParts(neck)
		if part1 == head then
			return head, root, torso, neck
		end
	end
	for _, descendant in figure:GetDescendants() do
		if descendant.Name == "Neck" and Util.IsCharacterJoint(descendant) then
			local part0, part1 = Util.GetCharacterJointParts(descendant)
			if part1 == head then
				return head, root, part0 or torso, descendant
			end
		end
	end
	return nil
end

local function GetAnimatedHeadWorld(head, neck)
	if neck then
		local part0, part1 = Util.GetCharacterJointParts(neck)
		local c0, c1 = Util.GetCharacterJointFrames(neck)
		local transform = CFrame.identity
		pcall(function()
			if typeof(neck.Transform) == "CFrame" then
				transform = neck.Transform
			end
		end)
		local success, world = pcall(function()
			assert(part0 and part1 == head and c0 and c1)
			return part0.CFrame * c0 * transform * c1:Inverse()
		end)
		if success and IsFinitePhysicsHeadCFrame(world) then
			return world
		end
	end
	return nil
end

local function WritePhysicsHeadCFrame(head, target)
	if not head or not head.Parent or not IsFinitePhysicsHeadCFrame(target) then
		return false
	end
	local success = pcall(function()
		head.CFrame = target
		head.AssemblyLinearVelocity = Vector3.zero
		head.AssemblyAngularVelocity = Vector3.zero
	end)
	if not success then
		pcall(function()
			head.CFrame = target
			head.Velocity = Vector3.zero
			head.RotVelocity = Vector3.zero
		end)
	end
	return success
end

local function ReleasePhysicsHead()
	local head = PhysicsHeadDriver.Head
	local neck = PhysicsHeadDriver.Neck
	if PhysicsHeadDriver.OwnsNeck and neck and neck.Parent then
		local owner = nil
		pcall(function()
			owner = neck:GetAttribute("_UhhhhhhPhysicsHeadOwner")
		end)
		-- If our attribute vanished during a Character/reset transition, still
		-- restore the Neck we recorded as ours. Only yield when another owner
		-- explicitly replaced us.
		if owner == nil or owner == PhysicsHeadDriver.OwnerId then
			local reconnect = GetAnimatedHeadWorld(head, neck)
			if reconnect then
				WritePhysicsHeadCFrame(head, reconnect)
			end
			pcall(function()
				neck.Enabled = PhysicsHeadDriver.NeckWasEnabled ~= false
				if owner == PhysicsHeadDriver.OwnerId then
					neck:SetAttribute("_UhhhhhhPhysicsHeadOwner", nil)
				end
			end)
		end
	end
	if PhysicsHeadDriver.AntiGravity then
		PhysicsHeadDriver.AntiGravity:Destroy()
	end
	PhysicsHeadDriver.Character = nil
	PhysicsHeadDriver.Head = nil
	PhysicsHeadDriver.Root = nil
	PhysicsHeadDriver.Torso = nil
	PhysicsHeadDriver.Neck = nil
	PhysicsHeadDriver.NeckWasEnabled = nil
	PhysicsHeadDriver.OwnsNeck = false
	PhysicsHeadDriver.AntiGravity = nil
	PhysicsHeadDriver.RootToHeadOffset = Vector3.new(0, 1.5, 0)
	PhysicsHeadDriver.SmoothedRelative = CFrame.identity
	PhysicsHeadDriver.TargetCFrame = nil
end

local function SuspendPhysicsHead(reason)
	PhysicsHeadDriver.Suspended = true
	PhysicsHeadDriver.SuspendReason = tostring(reason or "character transition")
	ReleasePhysicsHead()
	PhysicsHeadDriver.Status = "Physics head: suspended / " .. PhysicsHeadDriver.SuspendReason
end

local function ResumePhysicsHead()
	PhysicsHeadDriver.Suspended = false
	PhysicsHeadDriver.SuspendReason = nil
	PhysicsHeadDriver.Status = AnimLib.Settings.PhysicsHeadTracking
		and "Physics head: rebinding on next physics step"
		or "Physics head: disabled"
end

local function AcquirePhysicsHead(figure, head, root, torso, neck, scale)
	if PhysicsHeadDriver.Character == figure
		and PhysicsHeadDriver.Head == head
		and PhysicsHeadDriver.Neck == neck
		and PhysicsHeadDriver.OwnsNeck
	then
		local stillOwner = false
		local stillDisabled = false
		pcall(function()
			stillOwner = neck:GetAttribute("_UhhhhhhPhysicsHeadOwner") == PhysicsHeadDriver.OwnerId
			stillDisabled = neck.Enabled == false
		end)
		if stillOwner and stillDisabled then
			return true
		end
		ReleasePhysicsHead()
		PhysicsHeadDriver.Status = "Physics head: Neck ownership changed; yielding"
		return false
	end
	ReleasePhysicsHead()
	local owner = nil
	local enabled = true
	local readable = pcall(function()
		owner = neck:GetAttribute("_UhhhhhhPhysicsHeadOwner")
		enabled = neck.Enabled
	end)
	if not readable or (owner and owner ~= PhysicsHeadDriver.OwnerId) or not enabled then
		PhysicsHeadDriver.Status = "Physics head: yielding to another Neck owner"
		return false
	end
	PhysicsHeadDriver.Character = figure
	PhysicsHeadDriver.Head = head
	PhysicsHeadDriver.Root = root
	PhysicsHeadDriver.Torso = torso
	PhysicsHeadDriver.Neck = neck
	PhysicsHeadDriver.NeckWasEnabled = enabled
	PhysicsHeadDriver.OwnsNeck = true
	PhysicsHeadDriver.RootToHeadOffset = Vector3.new(0, 1.5, 0)
	local humanoid = figure:FindFirstChildOfClass("Humanoid")
	if humanoid and humanoid.RigType == Enum.HumanoidRigType.R15 then
		local offset = root.CFrame:PointToObjectSpace(head.Position) / math.max(scale, 0.05)
		if offset.X == offset.X and offset.Y == offset.Y and offset.Z == offset.Z then
			PhysicsHeadDriver.RootToHeadOffset = offset
		end
	end
	PhysicsHeadDriver.SmoothedRelative = CFrame.identity
	local claimed = pcall(function()
		neck:SetAttribute("_UhhhhhhPhysicsHeadOwner", PhysicsHeadDriver.OwnerId)
		neck.Enabled = false
	end)
	if not claimed then
		ReleasePhysicsHead()
		PhysicsHeadDriver.Status = "Physics head: Neck could not be disabled"
		return false
	end
	local antiGravity = Instance.new("BodyForce")
	antiGravity.Name = "_UhhhhhhPhysicsHeadAntiGravity"
	antiGravity.Parent = head
	PhysicsHeadDriver.AntiGravity = antiGravity
	return true
end

local function CFrameClose(a, b)
	if typeof(a) ~= "CFrame" or typeof(b) ~= "CFrame" then return false end
	local delta = a:ToObjectSpace(b)
	local _, angle = delta:ToAxisAngle()
	return delta.Position.Magnitude < 0.0001 and math.abs(angle) < 0.0001
end

-- This deliberately follows the successful Krystal overlay architecture:
-- animation writes Neck.Transform first, tracking contributes a local delta second.
-- No controller Neck is disabled and no controller Head is converted into a loose part.
local function GetHeadTrackingSource(torso)
	local camera = Reanimate.Camera and Reanimate.Camera.CFrame
	if not HeadTracking.Finite(camera) or camera == CFrame.identity then
		camera = workspace.CurrentCamera and workspace.CurrentCamera.CFrame or torso.CFrame
	end
	local headset
	if VRService.VREnabled then
		local ok, userFrame = pcall(VRService.GetUserCFrame, VRService, Enum.UserCFrame.Head)
		if ok and HeadTracking.Finite(userFrame) then headset = userFrame end
	end
	return camera, headset
end

local function RestorePhysicsHeadOverlay(neck)
	neck = neck or PhysicsHeadDriver.Neck
	if neck and neck.Parent and PhysicsHeadDriver.LastAppliedTransform then
		pcall(function()
			if CFrameClose(neck.Transform, PhysicsHeadDriver.LastAppliedTransform) then
				neck.Transform = PhysicsHeadDriver.UnderlyingTransform or CFrame.identity
			end
		end)
	end
	PhysicsHeadDriver.LastAppliedTransform = nil
	PhysicsHeadDriver.UnderlyingTransform = CFrame.identity
	PhysicsHeadDriver.TargetCFrame = nil
end

-- Override the old release/acquire semantics: tracking is now a Motor6D overlay,
-- so release means restore the animation transform, not reconnect a detached Head.
ReleasePhysicsHead = function()
	RestorePhysicsHeadOverlay()
	if PhysicsHeadDriver.AntiGravity then pcall(PhysicsHeadDriver.AntiGravity.Destroy, PhysicsHeadDriver.AntiGravity) end
	PhysicsHeadDriver.Character = nil
	PhysicsHeadDriver.Head = nil
	PhysicsHeadDriver.Root = nil
	PhysicsHeadDriver.Torso = nil
	PhysicsHeadDriver.Neck = nil
	PhysicsHeadDriver.NeckWasEnabled = nil
	PhysicsHeadDriver.OwnsNeck = false
	PhysicsHeadDriver.AntiGravity = nil
	PhysicsHeadDriver.SmoothedRelative = CFrame.identity
end

local function ApplyPhysicsHeadOverlay(dt)
	if PhysicsHeadDriver.Suspended then
		RestorePhysicsHeadOverlay()
		PhysicsHeadDriver.Status = "Head overlay: suspended / " .. tostring(PhysicsHeadDriver.SuspendReason or "transition")
		return
	end
	if not AnimLib.Settings.PhysicsHeadTracking then
		RestorePhysicsHeadOverlay()
		PhysicsHeadDriver.Status = "Head overlay: disabled"
		return
	end
	if CurrentMovementStyle and CurrentMovementStyle.Name == "Immersive VR" then
		RestorePhysicsHeadOverlay()
		PhysicsHeadDriver.Status = "Head overlay: native Immersive VR owns Head"
		return
	end

	local figure = Reanimate.Character
	local head, root, torso, neck = FindPhysicsHeadParts(figure)
	if not head or not root or not torso or not neck or not neck:IsA("Motor6D") then
		RestorePhysicsHeadOverlay()
		PhysicsHeadDriver.Status = "Head overlay: waiting for Motor6D Neck"
		return
	end

	if PhysicsHeadDriver.Neck ~= neck or PhysicsHeadDriver.Character ~= figure then
		RestorePhysicsHeadOverlay()
		PhysicsHeadDriver.Character = figure
		PhysicsHeadDriver.Head = head
		PhysicsHeadDriver.Root = root
		PhysicsHeadDriver.Torso = torso
		PhysicsHeadDriver.Neck = neck
	end

	local scale = 1
	pcall(function()
		scale = figure:GetAttribute("UhhhhhhCharacterSpacingScale") or figure:GetScale()
	end)
	scale = math.max(tonumber(scale) or 1, 0.05)

	-- Read whatever AnimLib/dance wrote this frame. Avoid feeding our previous
	-- overlay back into itself if Roblox has not replaced Transform yet.
	local animationTransform = neck.Transform
	if PhysicsHeadDriver.LastAppliedTransform and CFrameClose(animationTransform, PhysicsHeadDriver.LastAppliedTransform) then
		animationTransform = PhysicsHeadDriver.UnderlyingTransform or CFrame.identity
	end
	PhysicsHeadDriver.UnderlyingTransform = animationTransform

	local camera, headset = GetHeadTrackingSource(torso)
	local applied, source = HeadTracking.Solve(torso.CFrame, neck.C0, neck.C1, animationTransform,
		camera, headset, scale, AnimLib.Settings.PhysicsHeadStrength, AnimLib.Settings.PhysicsHeadBlendAnimation)
	if not HeadTracking.Finite(applied) then
		PhysicsHeadDriver.Status = "Head overlay: rejected invalid local transform"
		return
	end

	neck.Transform = applied
	PhysicsHeadDriver.LastAppliedTransform = applied
	PhysicsHeadDriver.Source = source
	PhysicsHeadDriver.TargetCFrame = head.CFrame
	local blend = AnimLib.Settings.PhysicsHeadBlendAnimation
	if PhysicsHeadDriver.StatusSource ~= source or PhysicsHeadDriver.StatusBlend ~= blend
		or PhysicsHeadDriver.Status:sub(1, 20) ~= "Head overlay: active" then
		PhysicsHeadDriver.StatusSource, PhysicsHeadDriver.StatusBlend = source, blend
		PhysicsHeadDriver.Status = "Head overlay: active / " .. source
			.. (blend and " / animation + tracking" or " / tracking override")
	end
end

-- One write after animation evaluation: a second render writer used to reapply
-- stale animation and tracking during the same frame.
local PhysicsHeadPreSimulation = RunService.PreSimulation:Connect(ApplyPhysicsHeadOverlay)

Util.LinkDestroyI2C(SCREENGUI, PhysicsHeadPreSimulation)
SCREENGUI.Destroying:Once(function()
	ReleasePhysicsHead()
end)
AnimLib.ReleasePhysicsHead = ReleasePhysicsHead
AnimLib.SuspendPhysicsHead = SuspendPhysicsHead
AnimLib.ResumePhysicsHead = ResumePhysicsHead
Reanimate.ReleasePhysicsHead = ReleasePhysicsHead
Reanimate.SuspendPhysicsHead = SuspendPhysicsHead
Reanimate.ResumePhysicsHead = ResumePhysicsHead

-- Adapted from the visualizer and character-afterimage effects in Valtta's
-- bundled Eyes Closed community dance. These are global, saved dance effects
-- now, so they can be used without coupling them to one animation module.
local DanceEffects = {
	Character = nil,
	RingPart = nil,
	RingBars = {},
	Ghosts = {},
	GhostTimer = 0,
	SmoothedLoudness = 0,
	AnchorSource = "Waiting for a dance",
}
DanceEffects.Pose=Steve110.Require("main/effect_pose")
local DanceEffectRingSegments = 64

local function GetDanceEffectAccent()
	local color = ParseDanceEffectColor(SavedDanceEffectsOptions.Accent)
	return color or Color3.fromRGB(0, 255, 255)
end

local function DestroyDanceEffectVisualizer()
	if DanceEffects.RingPart then
		DanceEffects.RingPart:Destroy()
	end
	DanceEffects.RingPart = nil
	DanceEffects.RingBars = {}
	DanceEffects.SmoothedLoudness = 0
end

local function DestroyDanceEffectGhosts()
	for _, ghost in DanceEffects.Ghosts do
		if ghost.Model then
			ghost.Model:Destroy()
		end
	end
	DanceEffects.Ghosts = {}
	DanceEffects.GhostTimer = 0
end

local function ResetDanceEffects(figure)
	DestroyDanceEffectVisualizer()
	DestroyDanceEffectGhosts()
	DanceEffects.Character = figure
	DanceEffects.AnchorSource = "Waiting for a dance"
end

local function IsFiniteDanceEffectPosition(value)
	return typeof(value) == "Vector3"
		and value.X == value.X
		and value.Y == value.Y
		and value.Z == value.Z
		and value.X > -math.huge
		and value.X < math.huge
		and value.Y > -math.huge
		and value.Y < math.huge
		and value.Z > -math.huge
		and value.Z < math.huge
end

local function IsFiniteDanceEffectCFrame(value)
	if typeof(value) ~= "CFrame" then
		return false
	end
	for _, component in { value:GetComponents() } do
		if type(component) ~= "number" or component ~= component or component <= -math.huge or component >= math.huge then
			return false
		end
	end
	return true
end

local function GetDanceEffectScale(figure)
	local scale = 1
	local success, value = pcall(function()
		return figure:GetScale()
	end)
	if success and type(value) == "number" and value == value and value > 0 and value < math.huge then
		scale = value
	end
	return scale
end

local function GetDanceEffectAnchor(figure, anchorMode)
    return DanceEffects.Pose.Anchor(figure,anchorMode)
end

local function GetDanceEffectAnchorRotation(anchorCFrame)
	if not SavedDanceEffectsOptions.StayVertical then
		return anchorCFrame.Rotation
	end
	local look = anchorCFrame.LookVector
	local flatLook = Vector3.new(look.X, 0, look.Z)
	if flatLook.Magnitude < 0.0001 then
		local right = anchorCFrame.RightVector
		local flatRight = Vector3.new(right.X, 0, right.Z)
		if flatRight.Magnitude >= 0.0001 then
			flatLook = Vector3.yAxis:Cross(flatRight.Unit)
		end
	end
	if flatLook.Magnitude < 0.0001 then
		return CFrame.identity
	end
	return CFrame.lookAt(Vector3.zero, flatLook.Unit, Vector3.yAxis)
end

local function CreateDanceEffectBar(parent, index, face)
	local angleDirection = face == Enum.NormalId.Bottom and -1 or 1
	local angle = angleDirection * (index / DanceEffectRingSegments) * math.pi * 2
	local bar = Instance.new("Frame")
	bar.Name = "Bar" .. index
	bar.AnchorPoint = Vector2.new(0.5, 1)
	bar.BackgroundColor3 = GetDanceEffectAccent()
	bar.BorderSizePixel = 0
	bar.Position = UDim2.fromOffset(128 + 88 * math.cos(angle) - 2.5, 128 + 88 * math.sin(angle))
	bar.Size = UDim2.fromOffset(5, 2)
	bar.Rotation = math.deg(angle) + 90
	bar.Parent = parent
	local stroke = Instance.new("UIStroke")
	stroke.Color = GetDanceEffectAccent():Lerp(Color3.new(1, 1, 1), 0.45)
	stroke.Thickness = 1.5
	stroke.Transparency = 0.2
	stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	stroke.Parent = bar
	return bar, stroke
end

local function BuildDanceEffectFace(part, face)
	local surface = Instance.new("SurfaceGui")
	surface.Name = "DanceEffectRing_" .. face.Name
	surface.Face = face
	surface.LightInfluence = 0
	surface.Brightness = 4
	surface.AlwaysOnTop = false
	surface.MaxDistance = 100
	surface.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
	surface.CanvasSize = Vector2.new(256, 256)
	surface.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	surface.Parent = part
	local background = Instance.new("Frame")
	background.Size = UDim2.fromScale(1, 1)
	background.BackgroundTransparency = 1
	background.BorderSizePixel = 0
	background.Parent = surface
	local bars = {}
	for index = 1, DanceEffectRingSegments do
		local bar, stroke = CreateDanceEffectBar(background, index, face)
		bars[index] = { Bar = bar, Stroke = stroke }
	end
	return bars
end

local function BuildDanceEffectVisualizer()
	DestroyDanceEffectVisualizer()
	local part = Instance.new("Part")
	part.Name = "_UhhhhhhDanceEffectVisualizer"
	part.Anchored = true
	part.CanCollide = false
	part.CanTouch = false
	part.CanQuery = false
	part.CastShadow = false
	part.Transparency = 1
	part.Size = Vector3.new(8, 0.01, 8)
	-- Keep the anchored visualizer outside Reanimate.Character. The character's
	-- PreSimulation collision controller rewrites CanCollide on every direct
	-- BasePart child, which otherwise makes this invisible ring collidable in
	-- seated/physics states even though it starts with CanCollide = false.
	part.Parent = workspace
	DanceEffects.RingPart = part
	local top = BuildDanceEffectFace(part, Enum.NormalId.Top)
	local bottom = BuildDanceEffectFace(part, Enum.NormalId.Bottom)
	for index = 1, DanceEffectRingSegments do
		DanceEffects.RingBars[index] = {
			Top = top[index].Bar,
			TopStroke = top[index].Stroke,
			Bottom = bottom[index].Bar,
			BottomStroke = bottom[index].Stroke,
		}
	end
end

local function CloneDanceEffectInstance(source)
	local wasArchivable = source.Archivable
	local success, clone = pcall(function()
		if not wasArchivable then
			source.Archivable = true
		end
		return source:Clone()
	end)
	if not wasArchivable then
		pcall(function()
			source.Archivable = false
		end)
	end
	if not success then
		return nil
	end
	return clone
end

local function CloneDanceEffectPart(source, accent, imageScale, baseTransparency)
	local part = CloneDanceEffectInstance(source)
	if
		not part
		or not part:IsA("BasePart")
		or part.ClassName ~= source.ClassName
	then
		if part then
			part:Destroy()
		end
		return nil
	end
	-- MeshPart.MeshId cannot be assigned directly from ordinary scripts.
	-- ApplyMesh is the supported way to reassert the source geometry if a
	-- cloned avatar MeshPart was sanitized by the current experience/executor.
	if part:IsA("MeshPart") and source:IsA("MeshPart") then
		pcall(part.ApplyMesh, part, source)
	end
	for _, child in part:GetDescendants() do
		if child:IsA("DataModelMesh") then
			pcall(function()
				child.TextureId = ""
			end)
			pcall(function()
				child.VertexColor = Vector3.new(accent.R, accent.G, accent.B)
			end)
			-- FileMesh geometry uses SpecialMesh.Scale instead of the ordinary
			-- part-size path. Built-in Head/Brick/Sphere/Cylinder mesh types are
			-- already scaled by their parent part and must not be scaled twice.
			if child:IsA("SpecialMesh") and child.MeshType == Enum.MeshType.FileMesh then
				pcall(function()
					child.Scale *= imageScale
					child.Offset *= imageScale
				end)
			end
		elseif not child:IsA("Bone") then
			child:Destroy()
		end
	end
	if part:IsA("MeshPart") then
		pcall(function()
			part.TextureID = ""
		end)
	end
	part.Name = source.Name
	part.Anchored = true
	part.CanCollide = false
	part.CanTouch = false
	part.CanQuery = false
	part.CastShadow = false
	part.Material = Enum.Material.Neon
	part.Color = accent
	part.Transparency = baseTransparency
	part.LocalTransparencyModifier = 0
	part.AssemblyLinearVelocity = Vector3.zero
	part.AssemblyAngularVelocity = Vector3.zero
    pcall(Util.ClearPhysicsRepRootRef,part)
	-- Shrink around this body's own center. Scaling the complete ghost model
	-- would pull limbs toward a shared pivot, causing a leg afterimage to drift
	-- away from the center of the live leg.
	part.Size = source.Size * imageScale
	part.CFrame = DanceEffects.Pose.Read(source) or source.CFrame
	return part
end

-- Keep afterimages limited to the avatar skeleton. Community modules often
-- parent their props and visual-effect parts directly below the character, so
-- scanning every BasePart also cloned swords, rings, trails, and similar
-- addon geometry. The name filter covers the standard R6/R15 body layouts;
-- GetBodyPartR15 additionally rejects a lookalike part on R15 characters.
local DanceEffectBodyPartNames = {
	Head = true,
	Torso = true,
	UpperTorso = true,
	LowerTorso = true,
	["Left Arm"] = true,
	["Right Arm"] = true,
	["Left Leg"] = true,
	["Right Leg"] = true,
	LeftUpperArm = true,
	LeftLowerArm = true,
	LeftHand = true,
	RightUpperArm = true,
	RightLowerArm = true,
	RightHand = true,
	LeftUpperLeg = true,
	LeftLowerLeg = true,
	LeftFoot = true,
	RightUpperLeg = true,
	RightLowerLeg = true,
	RightFoot = true,
}

local function IsDanceEffectBodyPart(figure, source)
	if
		not source:IsA("BasePart")
		or source.Parent ~= figure
		or DanceEffectBodyPartNames[source.Name] ~= true
	then
		return false
	end
	local humanoid = figure:FindFirstChildOfClass("Humanoid")
	if humanoid and humanoid.RigType == Enum.HumanoidRigType.R15 then
		local success, bodyPart = pcall(humanoid.GetBodyPartR15, humanoid, source)
		if success then
			return bodyPart ~= Enum.BodyPartR15.Unknown
		end
	end
	return true
end

local function IsDanceEffectBodyPartVisible(source)
	return SavedDanceEffectsOptions.AfterimageHiddenParts[source.Name] ~= true
end

local function GetDetectedDanceEffectBodyParts(figure)
	local names = {}
	if typeof(figure) ~= "Instance" or not figure:IsA("Model") or not figure.Parent then
		return names
	end
	for _, source in figure:GetChildren() do
		if IsDanceEffectBodyPart(figure, source) then
			table.insert(names, source.Name)
		end
	end
	table.sort(names)
	return names
end

do
-- Hidden physical parts use a dedicated target controller at the safe edge of
-- the void. Each reanimator redirects its existing replicated physics writer to
-- these targets; the animated controller itself is never moved or transformed.
local BodyHideR15ToR6 = {
	UpperTorso = "Torso",
	LowerTorso = "Torso",
	LeftUpperArm = "Left Arm",
	LeftLowerArm = "Left Arm",
	LeftHand = "Left Arm",
	RightUpperArm = "Right Arm",
	RightLowerArm = "Right Arm",
	RightHand = "Right Arm",
	LeftUpperLeg = "Left Leg",
	LeftLowerLeg = "Left Leg",
	LeftFoot = "Left Leg",
	RightUpperLeg = "Right Leg",
	RightLowerLeg = "Right Leg",
	RightFoot = "Right Leg",
}

local BodyHideAttachmentParts = {
	HatAttachment = "Head",
	HairAttachment = "Head",
	FaceFrontAttachment = "Head",
	FaceCenterAttachment = "Head",
	NeckAttachment = "Torso",
	BodyFrontAttachment = "Torso",
	BodyBackAttachment = "Torso",
	WaistFrontAttachment = "Torso",
	WaistBackAttachment = "Torso",
	WaistCenterAttachment = "Torso",
	LeftShoulderAttachment = "Left Arm",
	LeftGripAttachment = "Left Arm",
	RightShoulderAttachment = "Right Arm",
	RightGripAttachment = "Right Arm",
	LeftFootAttachment = "Left Leg",
	RightFootAttachment = "Right Leg",
}

local BodyHideTargetController = Instance.new("Model")
BodyHideTargetController.Name = "_Uhhhhhh_BodyHideTargetController"
BodyHideTargetController.Archivable = false
BodyHideTargetController.Parent = workspace
local BodyHideTargetParts = {}

local function IsFiniteBodyHideNumber(value)
	return type(value) == "number"
		and value == value
		and value > -math.huge
		and value < math.huge
end

local function GetBodyHideTargetY()
	local destroyHeight = FallenPartsDestroyHeight
	if not IsFiniteBodyHideNumber(destroyHeight) then
		destroyHeight = -500
	end
	return destroyHeight + 5
end

local function GetCanonicalBodyHidePartName(partName)
	if type(partName) ~= "string" then
		return nil
	end
	return BodyHideR15ToR6[partName] or partName
end

local function IsBodyHidePartSelected(partName)
	local canonical = GetCanonicalBodyHidePartName(partName)
	return canonical ~= nil
		and (
			SavedAnimLibOptions.HiddenBodyParts[partName] == true
			or SavedAnimLibOptions.HiddenBodyParts[canonical] == true
		)
end

local function ShouldRedirectBodyHidePart(partName, accessory)
	return IsBodyHidePartSelected(partName)
		and (accessory ~= true or not AnimLib.Settings.KeepAccessoriesWhenHiding)
end

local function GetBodyHideAccessoryAnchorName(physicalPart, normalTarget)
	local function ReadWeldAnchor(handle)
		if typeof(handle) ~= "Instance" or not handle:IsA("BasePart") then
			return nil
		end
		local weld = handle:FindFirstChild("AccessoryWeld")
		if weld and weld:IsA("JointInstance") then
			local part0, part1 = weld.Part0, weld.Part1
			if part0 and part0 ~= handle then
				return part0.Name
			elseif part1 and part1 ~= handle then
				return part1.Name
			end
		end
		return nil
	end

	local anchorName = ReadWeldAnchor(normalTarget) or ReadWeldAnchor(physicalPart)
	if anchorName then
		return anchorName
	end
	for _, candidate in { physicalPart, normalTarget } do
		if typeof(candidate) == "Instance" and candidate:IsA("BasePart") then
			for _, child in candidate:GetChildren() do
				if child:IsA("Attachment") and BodyHideAttachmentParts[child.Name] then
					return BodyHideAttachmentParts[child.Name]
				end
			end
		end
	end
	return nil
end

local function GetBodyHideTargetPart(partName, normalCFrame)
	local canonical = GetCanonicalBodyHidePartName(partName)
	if not canonical or typeof(normalCFrame) ~= "CFrame" then
		return nil
	end
	local target = BodyHideTargetParts[canonical]
	if not target or not target.Parent then
		target = Instance.new("Part")
		target.Name = canonical .. " Void Target"
		target.Size = Vector3.one
		target.Transparency = 1
		target.Anchored = true
		target.CanCollide = false
		target.CanQuery = false
		target.CanTouch = false
		target.CastShadow = false
		target.Archivable = false
		target.Parent = BodyHideTargetController
		BodyHideTargetParts[canonical] = target
	end
	local position = normalCFrame.Position
	local x = IsFiniteBodyHideNumber(position.X) and position.X or 0
	local z = IsFiniteBodyHideNumber(position.Z) and position.Z or 0
	target.CFrame = CFrame.new(x, GetBodyHideTargetY(), z) * normalCFrame.Rotation
	return target
end

local function ResolveBodyHideTargetPart(physicalPart, normalTarget, explicitPartName, accessory)
	if typeof(normalTarget) ~= "Instance" or not normalTarget:IsA("BasePart") then
		return normalTarget
	end
	local isAccessory = accessory == true
	if accessory == nil and typeof(physicalPart) == "Instance" then
		isAccessory = physicalPart:FindFirstAncestorWhichIsA("Accessory") ~= nil
	end
	local partName = explicitPartName
		or (isAccessory and GetBodyHideAccessoryAnchorName(physicalPart, normalTarget))
		or (typeof(physicalPart) == "Instance" and physicalPart.Name)
	if not ShouldRedirectBodyHidePart(partName, isAccessory) then
		return normalTarget
	end
	return GetBodyHideTargetPart(partName, normalTarget.CFrame) or normalTarget
end

local function GetBodyHideTargetInfo(physicalPart, normalTarget, explicitPartName, accessory)
	local isAccessory = accessory == true
	if accessory == nil and typeof(physicalPart) == "Instance" then
		isAccessory = physicalPart:FindFirstAncestorWhichIsA("Accessory") ~= nil
	end
	local partName = explicitPartName
		or (isAccessory and GetBodyHideAccessoryAnchorName(physicalPart, normalTarget))
		or (typeof(physicalPart) == "Instance" and physicalPart.Name)
	local canonical = GetCanonicalBodyHidePartName(partName)
	return ShouldRedirectBodyHidePart(partName, isAccessory), canonical
end

local function ResolveBodyHideTargetCFrame(physicalPart, normalCFrame, explicitPartName, accessory)
	if typeof(normalCFrame) ~= "CFrame" then
		return normalCFrame
	end
	local isAccessory = accessory == true
	if accessory == nil and typeof(physicalPart) == "Instance" then
		isAccessory = physicalPart:FindFirstAncestorWhichIsA("Accessory") ~= nil
	end
	local partName = explicitPartName
		or (typeof(physicalPart) == "Instance" and physicalPart.Name)
	if not ShouldRedirectBodyHidePart(partName, isAccessory) then
		return normalCFrame
	end
	local target = GetBodyHideTargetPart(partName, normalCFrame)
	return target and target.CFrame or normalCFrame
end

Reanimate.GetBodyHideCanonicalName = GetCanonicalBodyHidePartName
Reanimate.ShouldBodyHidePart = IsBodyHidePartSelected
Reanimate.ResolveBodyHideTargetPart = ResolveBodyHideTargetPart
Reanimate.ResolveBodyHideTargetCFrame = ResolveBodyHideTargetCFrame

local BodyHideGlobal = (getgenv and getgenv()) or shared or _G
local PreviousBodyHideTargetInfo = BodyHideGlobal.UhhhhhhTBZGetBodyHideTargetInfo
local PreviousAccessoryBodyHideDetach =
	BodyHideGlobal.UhhhhhhTBZShouldDetachAccessoryForBodyHide

BodyHideGlobal.UhhhhhhTBZGetBodyHideTargetInfo = GetBodyHideTargetInfo
BodyHideGlobal.UhhhhhhTBZShouldDetachAccessoryForBodyHide =
	function(physicalHandle, normalTarget)
		if AnimLib.Settings.KeepAccessoriesWhenHiding ~= true then
			return false, nil
		end

		local anchorName =
			GetBodyHideAccessoryAnchorName(physicalHandle, normalTarget)
		if not anchorName then
			return false, nil
		end

		return IsBodyHidePartSelected(anchorName), anchorName
	end

SCREENGUI.Destroying:Once(function()
	if BodyHideGlobal.UhhhhhhTBZGetBodyHideTargetInfo == GetBodyHideTargetInfo then
		BodyHideGlobal.UhhhhhhTBZGetBodyHideTargetInfo = PreviousBodyHideTargetInfo
	end
	if BodyHideGlobal.UhhhhhhTBZShouldDetachAccessoryForBodyHide then
		BodyHideGlobal.UhhhhhhTBZShouldDetachAccessoryForBodyHide =
			PreviousAccessoryBodyHideDetach
	end
	BodyHideTargetController:Destroy()
end)

end

local function GetDanceEffectGhostSource(figure)
    local realCharacter=Reanimate.GetActiveRealCharacter and Reanimate.GetActiveRealCharacter()or Player.Character
    if realCharacter and realCharacter~=figure and realCharacter.Parent then
        for _,source in ipairs(realCharacter:GetChildren())do
            if IsDanceEffectBodyPart(realCharacter,source)and IsDanceEffectBodyPartVisible(source)then return realCharacter end
        end
    end
    return figure
end

local DanceEffectR6CharacterMeshParts = {
	[Enum.BodyPart.Head] = { "Head", Vector3.new(2, 1, 1) },
	[Enum.BodyPart.Torso] = { "Torso", Vector3.new(2, 2, 1) },
	[Enum.BodyPart.LeftArm] = { "Left Arm", Vector3.new(1, 2, 1) },
	[Enum.BodyPart.RightArm] = { "Right Arm", Vector3.new(1, 2, 1) },
	[Enum.BodyPart.LeftLeg] = { "Left Leg", Vector3.new(1, 2, 1) },
	[Enum.BodyPart.RightLeg] = { "Right Leg", Vector3.new(1, 2, 1) },
}

local function ApplyDanceEffectR6CharacterMeshes(sourceFigure, ghost, accent, imageScale)
	local sourceHumanoid = sourceFigure:FindFirstChildOfClass("Humanoid")
	if not sourceHumanoid or sourceHumanoid.RigType ~= Enum.HumanoidRigType.R6 then
		return
	end
	for _, sourceAppearance in sourceFigure:GetChildren() do
		if sourceAppearance:IsA("CharacterMesh") then
			local mapping = DanceEffectR6CharacterMeshParts[sourceAppearance.BodyPart]
			local meshId = tonumber(sourceAppearance.MeshId)
			if mapping and meshId and meshId > 0 then
				local partName, standardSize = mapping[1], mapping[2]
				local sourcePart = sourceFigure:FindFirstChild(partName)
				local ghostPart = ghost:FindFirstChild(partName)
				if sourcePart and sourcePart:IsA("BasePart") and ghostPart and ghostPart:IsA("BasePart") then
					-- CharacterMesh normally needs a Humanoid, but an effect Humanoid can
					-- rewrite collision/state on its model. Convert the package geometry
					-- to a local SpecialMesh instead so every ghost remains visual-only.
					for _, child in ghostPart:GetChildren() do
						if child:IsA("DataModelMesh") then
							child:Destroy()
						end
					end
					local packageMesh = Instance.new("SpecialMesh")
					packageMesh.Name = "_UhhhhhhR6CharacterMesh"
					packageMesh.MeshType = Enum.MeshType.FileMesh
					packageMesh.MeshId = "rbxassetid://" .. math.floor(meshId)
					packageMesh.TextureId = ""
					packageMesh.VertexColor = Vector3.new(accent.R, accent.G, accent.B)
					packageMesh.Scale = Vector3.new(
						sourcePart.Size.X / standardSize.X,
						sourcePart.Size.Y / standardSize.Y,
						sourcePart.Size.Z / standardSize.Z
					) * imageScale
					packageMesh.Parent = ghostPart
				end
			end
		end
	end
end

local function SpawnDanceEffectGhost(figure)
	local accent = GetDanceEffectAccent()
	local imageScale = math.clamp(tonumber(SavedDanceEffectsOptions.AfterimageScale) or 0.86, 0.25, 1.5)
	local baseTransparency = math.clamp(
		(tonumber(SavedDanceEffectsOptions.AfterimageTransparency) or 55) / 100,
		0,
		1
	)
	local sourceFigure = GetDanceEffectGhostSource(figure)
	local ghost = Instance.new("Model")
	ghost.Name = "_UhhhhhhDanceEffectAfterimage"
	local partCount = 0
	local lightParent = nil
	for _, source in sourceFigure:GetDescendants() do
		if IsDanceEffectBodyPart(sourceFigure, source)
			and IsDanceEffectBodyPartVisible(source)
			and partCount < 20
		then
			local part = CloneDanceEffectPart(source, accent, imageScale, baseTransparency)
			if part then
				part.Parent = ghost
				partCount += 1
				if source.Name == "Torso" or source.Name == "UpperTorso" then
					lightParent = part
				end
			end
		end
	end
	if partCount == 0 then
		ghost:Destroy()
		return
	end
	ApplyDanceEffectR6CharacterMeshes(sourceFigure, ghost, accent, imageScale)
	lightParent = lightParent or ghost:FindFirstChildWhichIsA("BasePart")
	if lightParent then
		local light = Instance.new("PointLight")
		light.Enabled = SavedDanceEffectsOptions.AfterimageGlowEnabled
		light.Brightness = SavedDanceEffectsOptions.AfterimageGlowBrightness
		light.Range = SavedDanceEffectsOptions.AfterimageGlowRange * imageScale
		light.Color = accent
		light.Shadows = false
		light.Parent = lightParent
	end
	ghost.Parent = workspace
	-- These are private, static clones, not live character assemblies. Index
	-- once instead of rebuilding descendant arrays for every ghost every frame.
	local parts, lights = {}, {}
	for _, item in ghost:GetDescendants() do
		if item:IsA("BasePart") then table.insert(parts, item)
		elseif item:IsA("PointLight") then table.insert(lights, item) end
	end
	table.insert(DanceEffects.Ghosts, { Model = ghost, Elapsed = 0, ImageScale = imageScale, Parts = parts, Lights = lights })
end

local function UpdateDanceEffectGhosts(dt)
	local accent = GetDanceEffectAccent()
	local fadeSpeed = math.clamp(tonumber(SavedDanceEffectsOptions.AfterimageFadeSpeed) or 1, 0.25, 4)
	local baseTransparency = math.clamp(
		(tonumber(SavedDanceEffectsOptions.AfterimageTransparency) or 55) / 100,
		0,
		1
	)
	local lightVisibility = math.clamp((1 - baseTransparency) / 0.45, 0, 2.25)
	local glowEnabled = SavedDanceEffectsOptions.AfterimageGlowEnabled
	local glowBrightness = math.clamp(
		tonumber(SavedDanceEffectsOptions.AfterimageGlowBrightness) or 1.5,
		0,
		10
	)
	local glowRange = math.clamp(tonumber(SavedDanceEffectsOptions.AfterimageGlowRange) or 7, 0, 30)
	local index = 1
	while index <= #DanceEffects.Ghosts do
		local ghost = DanceEffects.Ghosts[index]
		ghost.Elapsed += dt
		local alpha = ghost.Elapsed * fadeSpeed
		if alpha >= 1 or not ghost.Model.Parent then
			ghost.Model:Destroy()
			table.remove(DanceEffects.Ghosts, index)
		else
			for _, descendant in ghost.Parts do
				if descendant.Parent then
					descendant.Transparency = baseTransparency + alpha * (1 - baseTransparency)
					descendant.Color = accent:Lerp(Color3.new(0, 0, 0), alpha * 0.75)
				end
			end
			for _, descendant in ghost.Lights do
				if descendant.Parent then
					descendant.Color = accent
					descendant.Enabled = glowEnabled and glowBrightness > 0 and glowRange > 0
					descendant.Brightness = glowBrightness * lightVisibility * (1 - alpha)
					descendant.Range = glowRange * (ghost.ImageScale or 1)
				end
			end
			index += 1
		end
	end
end

local function UpdateDanceEffectVisualizer(dt, figure)
	local root = nil
	local position = nil
	local scale = 1
	local anchorCFrame = nil
	local anchorMode = SavedDanceEffectsOptions.AnchorMode
	if anchorMode == "Blue Root Part" then
		-- The cyan hitbox always represents the controller rig's root. Keep this
		-- selection explicit even when DyPos would normally prefer Player.Character.
		position, root, scale, anchorCFrame = GetDanceEffectAnchor(figure, anchorMode)
		if position then
			DanceEffects.AnchorSource = "Cyan reanimated root - Blue Root Part"
		end
	elseif SavedDanceEffectsOptions.DynamicPosition then
		local realCharacter = Reanimate.GetActiveRealCharacter and Reanimate.GetActiveRealCharacter()or Player.Character
		if realCharacter and realCharacter ~= figure then
			position, root, scale, anchorCFrame = GetDanceEffectAnchor(realCharacter, anchorMode)
			if position then
				DanceEffects.AnchorSource = "Real character - " .. anchorMode
			end
		end
		if not position then
			position, root, scale, anchorCFrame = GetDanceEffectAnchor(figure, anchorMode)
			if position then
				DanceEffects.AnchorSource = "Red character - " .. anchorMode .. " (fallback)"
			end
		end
	else
		position, root, scale, anchorCFrame = GetDanceEffectAnchor(figure, anchorMode)
		if position then
			DanceEffects.AnchorSource = "Red character - " .. anchorMode
		end
	end
	if
		not root
		or not root:IsA("BasePart")
		or not IsFiniteDanceEffectPosition(position)
		or not IsFiniteDanceEffectCFrame(anchorCFrame)
	then
		DanceEffects.AnchorSource = "No valid character anchor"
		DestroyDanceEffectVisualizer()
		return
	end
	if not DanceEffects.RingPart or not DanceEffects.RingPart.Parent then
		BuildDanceEffectVisualizer()
	end
	local size = SavedDanceEffectsOptions.Size
	-- Defend against game scripts or state controllers changing these flags
	-- after construction. This effect must remain visual-only.
	DanceEffects.RingPart.CanCollide = false
	DanceEffects.RingPart.CanTouch = false
	DanceEffects.RingPart.CanQuery = false
	DanceEffects.RingPart.Size = Vector3.new(8 * scale * size, 0.01, 8 * scale * size)
	local offset = anchorCFrame:VectorToWorldSpace(
		Vector3.new(SavedDanceEffectsOptions.OffsetX * scale, 0, SavedDanceEffectsOptions.OffsetZ * scale)
	)
	position += offset + Vector3.new(0, SavedDanceEffectsOptions.OffsetY * scale, 0)
	DanceEffects.RingPart.CFrame = CFrame.new(position)
		* GetDanceEffectAnchorRotation(anchorCFrame)
		* CFrame.Angles(
			math.rad(SavedDanceEffectsOptions.RotationX),
			math.rad(SavedDanceEffectsOptions.RotationY),
			math.rad(SavedDanceEffectsOptions.RotationZ)
		)

	local playing = UISound.DanceMusic.IsPlaying
	local loudness = playing and math.clamp(UISound.DanceMusic.PlaybackLoudness / 550, 0, 1) or 0
	if playing and loudness < 0.01 then
		local time = UISound.DanceMusic.TimePosition
		loudness = 0.35 + math.abs(math.sin(time * 2.1)) * 0.25
	end
	local smoothingAlpha = 1 - math.exp(-12 * math.max(tonumber(dt) or 0, 0))
	DanceEffects.SmoothedLoudness += (loudness - DanceEffects.SmoothedLoudness) * smoothingAlpha
	local time = playing and UISound.DanceMusic.TimePosition or os.clock()
	local accent = GetDanceEffectAccent()
	local strokeColor = accent:Lerp(Color3.new(1, 1, 1), 0.45)
	for index, pair in DanceEffects.RingBars do
		local fraction = (index - 1) / DanceEffectRingSegments
		local phase = fraction * math.pi * 2
		local band = math.abs(math.sin(time * 2.1 + phase * 0.5)) * 0.55
			+ math.abs(math.sin(time * 5.3 + phase * 1.2 + 1.1)) * 0.3
			+ math.abs(math.sin(time * 11.7 + phase * 2.5 + 2.3)) * 0.15
		local amplitude = math.clamp(DanceEffects.SmoothedLoudness * (0.55 + band * 0.75), 0.06, 1)
		local barSize = UDim2.fromOffset(5, math.max(2, math.floor(amplitude * 30)))
		local barColor = accent:Lerp(Color3.new(1, 1, 1), amplitude * 0.45)
		pair.Top.Size = barSize
		pair.Top.BackgroundColor3 = barColor
		pair.TopStroke.Color = strokeColor
		pair.Bottom.Size = barSize
		pair.Bottom.BackgroundColor3 = barColor
		pair.BottomStroke.Color = strokeColor
	end
end

local function UpdateDanceEffects(dt)
	local figure = Reanimate.Character
	local active = CurrentDance ~= nil and figure and figure.Parent
	if DanceEffects.Character ~= figure then
		ResetDanceEffects(figure)
	end
	if not active then
		if DanceEffects.RingPart or #DanceEffects.Ghosts > 0 or DanceEffects.GhostTimer > 0 then
			ResetDanceEffects(figure)
		end
		return
	end
	if SavedDanceEffectsOptions.VisualizerEnabled then
		UpdateDanceEffectVisualizer(dt, figure)
	elseif DanceEffects.RingPart then
		DestroyDanceEffectVisualizer()
	end
	if SavedDanceEffectsOptions.AfterimageEnabled then
		local spawnRate = math.clamp(tonumber(SavedDanceEffectsOptions.AfterimageSpawnRate) or 1, 0.25, 4)
		DanceEffects.GhostTimer += dt * spawnRate
		if DanceEffects.GhostTimer >= 0.5 then
			DanceEffects.GhostTimer %= 0.5
			SpawnDanceEffectGhost(figure)
		end
		UpdateDanceEffectGhosts(dt)
	elseif #DanceEffects.Ghosts > 0 or DanceEffects.GhostTimer > 0 then
		DestroyDanceEffectGhosts()
	end
end

RunService:BindToRenderStep("Uhhhhhh_DanceEffects",Enum.RenderPriority.Last.Value+3,UpdateDanceEffects)
SCREENGUI.Destroying:Once(function()RunService:UnbindFromRenderStep("Uhhhhhh_DanceEffects")end)

local DanceRestartQueued = false
local function RestartCurrentDance()
	if DanceRestartQueued then
		return
	end
	local selected = CurrentDance
	if not selected then
		Util.UINotify("No dance is currently selected")
		return
	end
	DanceRestartQueued = true
	CurrentDance = nil
	task.spawn(function()
		local timeout = os.clock() + 2
		repeat
			RunService.Heartbeat:Wait()
		until _CurrentDance == nil or os.clock() >= timeout
		if CurrentDance == nil and Reanimate.Character then
			CurrentDance = selected
		end
		DanceRestartQueued = false
	end)
end

