	if not table.find(presetNames, AnimLib.Settings.JointPreset) then
		AnimLib.Settings.JointPreset = "Custom"
		SavedAnimLibOptions.JointPreset = "Custom"
	end
	local updating = false
	local switches = {}
	local bodyPicker
	local mixerOptions=UI.CreateCanvas(page)
	local presetSelect = UI.CreateDropdown(
		mixerOptions,
		"Quick Preset",
		presetNames,
		table.find(presetNames, AnimLib.Settings.JointPreset) or 1
	)
	local statusText = UI.CreateText(mixerOptions, "", 11, Enum.TextXAlignment.Center)

	local function saveMixer()
		local saved, reason = SaveSettingsNow()
		if not saved then
			warn("Joint Mixer save failed: " .. tostring(reason))
			Util.UINotify("Joint Mixer changed, but settings could not be saved")
		end
	end

	local function refreshControls()
		updating = true
		local animatedCount = 0
		for _, group in AnimLib.JointGroups do
			local animated = AnimLib.IsJointGroupAnimated(group.Key)
			animatedCount += animated and 1 or 0
			if switches[group.Key] then
				switches[group.Key].Value = animated
			end
		end
		presetSelect.Value = table.find(presetNames, AnimLib.Settings.JointPreset) or 1
		updating = false
		statusText.Text = string.format(
			"%d / %d limbs animated  •  LIVE",
			animatedCount,
			#AnimLib.JointGroups
		)
		if bodyPicker then bodyPicker.Refresh()end
	end

	presetSelect.Changed:Connect(function(index)
		if updating or presetNames[index]==AnimLib.Settings.JointPreset then
			return
		end
		AnimLib.ApplyJointPreset(presetNames[index] or "Custom")
		AnimLib.ApplyDisabledAnimationParts()
		saveMixer()
		refreshControls()
	end)
	local function changeGroup(key,value)
		AnimLib.SetJointGroupAnimated(key,value)
		AnimLib.Settings.JointPreset="Custom"SavedAnimLibOptions.JointPreset="Custom"
		AnimLib.ApplyDisabledAnimationParts()saveMixer()refreshControls()
	end
	bodyPicker=Steve110.Require("main/joint_picker")({UI=UI,Util=Util,Theme=DevTheme,Parent=page,
		Font=Steve110.Require("main/data").TextFont,Read=AnimLib.IsJointGroupAnimated,Change=changeGroup})
	-- Put the body before the presets/status even though their callbacks are
	-- prepared first. Canvas returns the inner list in the native prefab.
	local optionsContainer=mixerOptions
	while optionsContainer.Parent and optionsContainer.Parent~=page do optionsContainer=optionsContainer.Parent end
	optionsContainer.LayoutOrder=bodyPicker.Root.Parent.LayoutOrder+1

	UI.CreateText(page, "<b>ANIMATED JOINT GROUPS</b>", 13, Enum.TextXAlignment.Left)
	for _, group in AnimLib.JointGroups do
		local groupKey = group.Key
		local control = UI.CreateSwitch(page, "Animate " .. group.Label, AnimLib.IsJointGroupAnimated(groupKey))
		switches[groupKey] = control
		control.Changed:Connect(function(value)
			if updating or AnimLib.IsJointGroupAnimated(groupKey)==(value==true)then
				return
			end
			changeGroup(groupKey,value==true)
		end)
	end

	UI.CreateSeparator(page)
	UI.CreateButton(page, "Animate All Six Limbs", 16).Activated:Connect(function()
		AnimLib.ApplyJointPreset("Full Body")
		saveMixer()
		refreshControls()
	end)
	UI.CreateButton(page, "Disable All Six Limbs", 16).Activated:Connect(function()
		for _, group in AnimLib.JointGroups do
			AnimLib.SetJointGroupAnimated(group.Key, false)
		end
		AnimLib.Settings.JointPreset = "Custom"
		SavedAnimLibOptions.JointPreset = "Custom"
		AnimLib.ApplyDisabledAnimationParts()
		saveMixer()
		refreshControls()
	end)
	UI.CreateButton(page, "Reset Disabled Joint Poses", 16).Activated:Connect(function()
		AnimLib.ResetDisabledJointPoses(Reanimate.Character)
		Util.UINotify("Disabled joint poses reset")
	end)
	UI.CreateText(
		page,
		"Changes apply live to dance pose writing; physical reanimation and visibility stay as they are. Each R15 limb includes all of its segments.",
		9,
		Enum.TextXAlignment.Center
	)
	refreshControls()
end)()

