            Dispatch,
            debug.traceback,
            selectedRecord.Instance,
            BuildCleanupSource(),
            "Remove"
        )

    if not ok then
        warn("Uhhhhhh :: Server Reanim cleanup failed\n" .. tostring(result))
        Notice("Cleanup dispatch failed. Check the console.")
    elseif result ~= false then
        Notice("Server FakeChar cleanup dispatched.")
    end
end)

