local function BuildFavoritePage(page, modules, kindName, hidden)
	Util.ClearAllChildrenGui(page.List)
	local collection = hidden and "hidden" or "favorite"
	local heading = UI.CreateText(page.List, "<b>" .. string.upper(collection .. " " .. kindName) .. "</b>", 18, Enum.TextXAlignment.Center)
	heading.Parent.Name = collection .. " " .. string.lower(kindName) .. " heading"
	local favorites = {}
	for _, m in modules do
		if (hidden and IsHidden(m)) or (not hidden and IsFavorite(m)) then
			table.insert(favorites, m)
		end
	end
	table.sort(favorites, function(a, b)
		return tostring(a.Name):lower() < tostring(b.Name):lower()
	end)

	if #favorites == 0 then
		local empty = UI.CreateText(
			page.List,
			"[*] No " .. collection .. " " .. string.lower(kindName) .. " [*]",
			15,
			Enum.TextXAlignment.Center
		)
		empty.Parent.Name = "no " .. collection .. " " .. string.lower(kindName)
		return 0
	end

	for _, m in favorites do
		local item = UI.CreateItemListItem(page.List)
		UI.CreateText(item, "[*] " .. m.Name .. " &gt;", 19, Enum.TextXAlignment.Left)
		UI.CreateText(
			item,
			string.split(m.Description, "\n")[1],
			11,
			Enum.TextXAlignment.Left
		)
		item.Parent.Name = collection .. " " .. kindName .. " " .. m.Name .. " " .. m.Description
		local query = page.Search.Box.Text:lower()
		item.Parent.Visible = query == "" or item.Parent.Name:lower():find(query, 1, true) ~= nil
		Util.LinkDestroyI2C(
			item,
			item.Activated:Connect(function()
				OpenModuleDetails(m, page)
			end)
		)
	end
	return #favorites
end

FavoriteSystem.Refresh = function()
	UI.Workspace.SnapshotAll()
	if RefreshKeybinds then RefreshKeybinds() end
	for m, container in pairs(moduleListRows) do
		if container.Parent then
			RefreshMainModuleRow(m, container)
		else
			moduleListRows[m] = nil
		end
	end
	local pages = FavoriteSystem.Pages
	if not pages then
		return
	end
	local danceCount = BuildFavoritePage(pages.Dances, DanceableDances, "Dances")
	local movesetCount = BuildFavoritePage(pages.Movesets, MovementStyles, "Movesets")
	local hiddenDanceCount = BuildFavoritePage(pages.HiddenDances, DanceableDances, "Dances", true)
	local hiddenMovesetCount = BuildFavoritePage(pages.HiddenMovesets, MovementStyles, "Movesets", true)
	if FavoriteSystem.CategoryLabels then
		FavoriteSystem.CategoryLabels.Dances.Text = "Dances (" .. danceCount .. ") &gt;"
		FavoriteSystem.CategoryLabels.Movesets.Text = "Movesets (" .. movesetCount .. ") &gt;"
	end
	if FavoriteSystem.HiddenCategoryLabels then
		FavoriteSystem.HiddenCategoryLabels.Dances.Text = "Dances (" .. hiddenDanceCount .. ") &gt;"
		FavoriteSystem.HiddenCategoryLabels.Movesets.Text = "Movesets (" .. hiddenMovesetCount .. ") &gt;"
	end
	UI.Workspace.RestoreAll()
end

