        item:GetAttributeChangedSignal("FavoriteClick"):Connect(function()
            FavoriteSystem.ToggleFavorite(m)
            item:SetAttribute("Favorite", FavoriteSystem.IsFavorite(m))
        end)
        item:GetAttributeChangedSignal("RunningClick"):Connect(function()
            if Reanimate.ReadModulePlayback(m).Failure then RetryAnimationAssets(m)end
            MovementStyleIndex = table.find(MovementStyles, m)
            if not Reanimate.Character then Util.UINotify("Moveset selected. Start reanimation to play it.")end
        end)
        item:SetAttribute("Running", Reanimate.ReadModulePlayback(m).Running)
		item.Parent.Name = m.Name .. " " .. m.Description
		FavoriteSystem.RegisterMainItem(m, item.Parent)
		Util.LinkDestroyI2C(
			item,
			item.Activated:Connect(function()
				FavoriteSystem.OpenModuleDetails(m, MovesetsPage)
			end)
		)
		return m.Name
	end
end

local function AddDance(m)
	if type(m) == "table" then
		if not m.Name or not m.Description or not m.Assets or not m.Config or not m.Init or not m.Update or not m.Destroy then
			return
		end
		GetModuleHash(m)
		if m.LoadConfig then
            local config=SettingsDefaults.ModuleConfig(m,SaveData.ModuleConfigs[ModuleIdentity.PreferenceKey(m)],SaveData.CharacterEffectsDefaultOff)
            if config then pcall(m.LoadConfig,config)end
		end
		table.insert(DanceableDances, m)
		local item = StevePrefabs.UI.ItemListItem(DancesPage.List)
        item.Name = "_UhhhhhhModuleCard"
        item:SetAttribute("Name", m.Name)
        item:SetAttribute("Description", string.split(m.Description, "\n")[1])
        item:SetAttribute("Favorite", FavoriteSystem.IsFavorite(m))
        item:GetAttributeChangedSignal("FavoriteClick"):Connect(function()
            FavoriteSystem.ToggleFavorite(m)
            item:SetAttribute("Favorite", FavoriteSystem.IsFavorite(m))
        end)
        item:GetAttributeChangedSignal("RunningClick"):Connect(function()
            local state=Reanimate.ReadModulePlayback(m)
            m._UhhhhhhRandomSelection=nil
            if state.Failure then RetryAnimationAssets(m)end
            if state.Running then CurrentDance=nil else CurrentDance=m end
            if CurrentDance and not Reanimate.Character then Util.UINotify("Dance selected. Start reanimation to play it.")end
        end)
        item:SetAttribute("Running", Reanimate.ReadModulePlayback(m).Running)
		item.Parent.Name = m.Name .. " " .. m.Description
		FavoriteSystem.RegisterMainItem(m, item.Parent)
		Util.LinkDestroyI2C(
			item,
			item.Activated:Connect(function()
				FavoriteSystem.OpenModuleDetails(m, DancesPage)
			end)
		)
		return m.Name
	end
end
local REQUIRED_MODULE_FIELDS = {
	"Name",
	"Description",
	"Assets",
	"Config",
	"Init",
	"Update",
	"Destroy",
}

local function ValidateModuleObject(m)
	if type(m) ~= "table" then
		return false, "Module return value is not a table. Got " .. typeof(m) .. " instead."
	end
	if m.ModuleType ~= "MOVESET" and m.ModuleType ~= "DANCE" then
		return false, "Unknown ModuleType `" .. tostring(m.ModuleType) .. "`."
	end
	for _, field in REQUIRED_MODULE_FIELDS do
		if m[field] == nil then
			return false, "Missing required field `" .. field .. "`."
		end
	end
	if type(m.Name) ~= "string" or m.Name == "" then
		return false, "`Name` must be a non-empty string."
	end
	if type(m.Description) ~= "string" then
		return false, "`Description` must be a string."
	end
	if type(m.Assets) ~= "table" then
		return false, "`Assets` must be a table."
	end
	for _, callback in { "Config", "Init", "Update", "Destroy" } do
		if type(m[callback]) ~= "function" then
			return false, "`" .. callback .. "` must be a function."
		end
	end
    local ok,reason=pcall(function()AnimLib.GetCreatorTools().Adapt(m)end)
    if not ok then return false,"Animation Creator data: "..tostring(reason)end
	return true
end

local function AddModule(func, marketContext, sourceLabel)
	if type(func) ~= "function" then
		return nil, "Module entry is not a function. Got " .. typeof(func) .. " instead."
	end
	local bindOwner=GiveFunctionsToFunction(func, marketContext)
	local ran, m = xpcall(func, debug.traceback)
	if not ran then
		return nil, "Module execution failed: " .. tostring(m)
	end
	local valid, validationError = ValidateModuleObject(m)
	if not valid then
		return nil, validationError
	end
    bindOwner(m)

    ResolveModuleAssets(m, marketContext, sourceLabel)
    m._UhhhhhhModuleFile=marketContext and marketContext.ModuleFile
    m._UhhhhhhModuleContext=marketContext
    GetModuleHash(m)
    local canonical,isNew=ModuleIdentity.Register(m,func,marketContext,sourceLabel)
    if not isNew then
        -- A factory may construct animators before returning its module. Only
        -- those owned by the discarded duplicate are safe to release here.
        if canonical~=m then
            for animator in pairs(AnimLib.ActiveAnimators or {})do
                if animator._UhhhhhhModuleOwner==m then pcall(function()animator:Destroy(false)end)end
            end
        end
        return nil,nil,"Merged identical "..m.ModuleType:lower().." `"..canonical.Name.."`; source credits retained."
    end

	local name
	if m.ModuleType == "MOVESET" then
		name = AddMoveset(m)
	else
		name = AddDance(m)
	end
	return name
end
local function AddModules(list, marketContext, sourceLabel, executedSource)
    Util.ModuleBudget.Reset()
	list=AnimLib.GetCreatorTools().Entries(list)
    ModuleIdentity.TagFactories(list,executedSource)
	local names = {}
	local logging = ""
	if type(list) == "table" then
		for i = 1, #list do
			local name, logging2, note = AddModule(list[i], marketContext, sourceLabel)
			if name then
				table.insert(names, name)
			end
			if logging2 then
				logging ..= "\n[ERROR] M" .. i .. ": " .. logging2
			end
			if note then
				logging ..= "\n[LOG] M" .. i .. ": " .. note
			end
			Util.ModuleBudget.Checkpoint()
		end
	else
		logging ..= "\n[LOG] Module return value is not a table array of module functions. Skipping."
	end
	logging ..= "\n[LOG] Loaded " .. #names .. " modules."
	return names, logging
end
task.spawn(function()
