	while task.wait(5) do
		for _, m in MovementStyles do
			SaveConfig(m)
		end
		for _, m in DanceableDances do
			SaveConfig(m)
		end
	end
end)
local __TheoGelatekPoseCharacter = nil
local __TheoGelatekPoseCache = setmetatable({}, { __mode = "k" })
local __TheoGelatekPoseSerial = 0

local function __TheoClearGelatekPoseCache()
	table.clear(__TheoGelatekPoseCache)
	__TheoGelatekPoseCharacter = nil
	__TheoGelatekPoseSerial += 1
end

local function __TheoCaptureGelatekControllerPose(character, dt)
	if not __TheoIsExternal()
		or typeof(character) ~= "Instance"
		or not character.Parent
	then
		__TheoClearGelatekPoseCache()
		return
	end

	if __TheoGelatekPoseCharacter ~= character then
		table.clear(__TheoGelatekPoseCache)
		__TheoGelatekPoseCharacter = character
	end

    if character:GetAttribute("MovementInit") == true or character:GetAttribute("IsDancing") == true then
        local poseIndex = GelatekReanimator.AccessoryLifetime.ControllerIndex(character)
        for _, descendant in ipairs(poseIndex and poseIndex.Motors or {}) do
            if descendant:IsA("Motor6D") and descendant.Part0 and descendant.Part1 then
                __TheoGelatekPoseCache[descendant] = Reanimate.CharacterMotion.BaseTransform(descendant)
            end
        end
        __TheoGelatekPoseSerial += 1
    else
        __TheoClearGelatekPoseCache()
    end
    -- This cache preserves legacy Heartbeat-authored transforms for the next
    -- animation batch. Physical following commits once after simulation.
end

local function __TheoHasPlayingRobloxTrack(character)
	local humanoid =
		character and character:FindFirstChildOfClass("Humanoid")
	local animator =
		humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then
		return false
	end

	local ok, tracks = pcall(function()
		return animator:GetPlayingAnimationTracks()
	end)
	if not ok or type(tracks) ~= "table" then
		return false
	end

	for _, track in tracks do
		local playing = false
		pcall(function()
			playing = track.IsPlaying == true
		end)
		if playing then
			return true
		end
	end
	return false
end

-- The pose cache is local to this module; the backend receives an explicit
-- reader rather than looking up nonexistent globals in its own environment.
__TheoContext.GetGelatekPoseDebug = function(character)
	local count = 0
	for _ in pairs(__TheoGelatekPoseCache) do count += 1 end
	return {Character = __TheoGelatekPoseCharacter, Serial = __TheoGelatekPoseSerial,
		CachedJoints = count, RobloxTrackActive = __TheoHasPlayingRobloxTrack(character)}
end

local function StopControllerAnimations(character)
    if not character then return end
    local tracksSeen = {}
    for _, instance in ipairs(character:GetDescendants()) do
        if instance:IsA("Animator") or instance:IsA("Humanoid") or instance:IsA("AnimationController") then
            local ok, tracks = pcall(function() return instance:GetPlayingAnimationTracks() end)
            if ok and type(tracks) == "table" then
                for _, track in ipairs(tracks) do
                    if not tracksSeen[track] then
                        tracksSeen[track] = true
                        pcall(function() track:Stop(0) end)
                    end
                end
            end
        end
    end
    -- Stop and UNBIND orphan custom writers too. Stop alone leaves a bound
    -- Animator:Step callback that can overwrite the next moveset's transforms.
    local animators = {}
    for animator in pairs(AnimLib.ActiveAnimators or {}) do
        local rig = animator.rig or animator._rig
        if rig == character or (typeof(rig) == "Instance" and rig:IsDescendantOf(character)) then
            table.insert(animators, animator)
        end
    end
    for _, animator in ipairs(animators) do
        pcall(function() animator:Stop(true) end)
        pcall(function() animator:Unbind() end)
        pcall(function() animator:Destroy(true) end)
    end
end

local function TeardownAnimationRuntime(character, keepSelectedDance)
    Reanimate.CharacterMotion.BeforePose(character)
    if Reanimate.CharacterMotion.FrameCache then Reanimate.CharacterMotion.FrameCache.Clear() end
    -- Clear public state BEFORE user Destroy callbacks, even when they fail.
    local oldStyle, oldDance = CurrentMovementStyle, _CurrentDance
    CurrentMovementStyle, _CurrentDance, _MovementStyleIndex = nil, nil, nil
    if not keepSelectedDance then CurrentDance = nil end
    __TheoClearGelatekPoseCache()
    if character then character:SetAttribute("_UhhhhhhAnimationRefresh", true) end
    if type(AnimLib.ReleasePhysicsHead) == "function" then pcall(AnimLib.ReleasePhysicsHead) end
    SetOverrideMovesetMusic(nil)
    SetOverrideDanceMusic(nil)
    -- Halt tracks immediately, then let modules release their own effects and
    -- connections. A second sweep catches any animator left behind by Destroy.
    StopControllerAnimations(character)
    if oldStyle then pcall(oldStyle.Destroy, Reanimate.ControllerRigAdapter.ModuleRig(character,oldStyle,false)) end
    if oldDance then pcall(oldDance.Destroy, Reanimate.ControllerRigAdapter.ModuleRig(character,oldDance,false)) end
    if oldStyle then Reanimate.HatBindings.Release(oldStyle)oldStyle._UhhhhhhPoseBaseline=nil end
    if oldDance then Reanimate.HatBindings.Release(oldDance)oldDance._UhhhhhhPoseBaseline=nil end
    StopControllerAnimations(character)
    if character then
        ResetDancePose(character, true)
        for _, name in ipairs({"MovementInit", "MovesetInternalName", "IsDancing", "DanceInternalName"}) do
            character:SetAttribute(name, nil)
        end
    end
    Reanimate.ControllerRigAdapter.Release(character)
    HatReanimator.HatWeldOverride = {}
    table.clear(HatReanimator.HatCFrameOverride)
end

local function RefreshAnimationCharacter(character)
    if not character or Reanimate.Character ~= character then return Reanimate.Character end
    local ok, refreshed, reason = pcall(function()
        if __TheoIsExternal() then return GelatekReanimator.RefreshCharacter(character) end
        Reanimate.CreateCharacter()
        return Reanimate.Character
    end)
    if not ok or not refreshed then
        -- Do not fall through next frame and initialize on a half-refreshed
        -- controller. Keep animation suspended until manual refresh/reanimate.
        pcall(function() character:SetAttribute("_UhhhhhhAnimationRefreshFailed", true) end)
        error("Controller refresh failed: " .. tostring(ok and reason or refreshed))
    end
    pcall(function() character:SetAttribute("_UhhhhhhAnimationRefresh", nil) end)
    pcall(function() refreshed:SetAttribute("_UhhhhhhAnimationRefreshFailed", nil) end)
    ResetMovesetWalkSpeed(refreshed)
    return refreshed
end

-- Retire module-owned writers while their original R6/native rig still exists.
-- A replacement controller must never be handed to an old module's Destroy.
__TheoLifecycle.RetireController = function(character)
    if not character or character:GetAttribute("_UhhhhhhAnimationRetiring") then return end
    character:SetAttribute("_UhhhhhhAnimationRetiring", true)
    TeardownAnimationRuntime(character, true)
end

local function StopModuleAnimations(m)
    m._UhhhhhhRuntimeReady,m._UhhhhhhLoadingAssets=false,false
    Reanimate.HatBindings.Release(m)
    local owned={}
    for animator in pairs(AnimLib.ActiveAnimators or {}) do
        if animator._UhhhhhhModuleOwner==m then table.insert(owned,animator) end
    end
    for _,animator in ipairs(owned) do
        pcall(function() animator:Stop(false) end)
        pcall(function() animator:Unbind() end)
        pcall(function() animator:Destroy(false) end)
    end
end

local function RestoreModulePose(m,character)
    local baseline=m._UhhhhhhPoseBaseline
    m._UhhhhhhPoseBaseline=nil
    if not baseline then ResetDancePose(character,true) return end
    for joint,pose in pairs(baseline.Joints) do
        if joint.Parent then
            joint.C0,joint.C1,joint.Enabled,joint.Transform=pose.C0,pose.C1,pose.Enabled,pose.Transform
        end
    end
    local h=character and character:FindFirstChildOfClass("Humanoid")
    if h and baseline.WalkSpeed then h.WalkSpeed=baseline.WalkSpeed end
end

local function FailAnimationModule(m, character, reason)
    if m._UhhhhhhRuntimeFailure then return end
    m._UhhhhhhRuntimeFailure = tostring(reason)
    m._UhhhhhhRuntimeReady,m._UhhhhhhLoadingAssets=false,false
    Reanimate.CharacterMotion.BeforePose(character)
    __TheoClearGelatekPoseCache()
    pcall(m.Destroy, Reanimate.ControllerRigAdapter.ModuleRig(character,m,false))
    StopModuleAnimations(m)
    RestoreModulePose(m,character)
    if m.ModuleType == "MOVESET" then
        character:SetAttribute("MovementInit", nil)
        character:SetAttribute("MovesetInternalName", nil)
        SetOverrideMovesetMusic(nil)
    else
        character:SetAttribute("IsDancing", nil)
        character:SetAttribute("DanceInternalName", nil)
        SetOverrideDanceMusic(nil)
    end
    m._UhhhhhhRandomUnavailable = true
    local detail=tostring(reason):match("^[^\r\n]+") or tostring(reason)
    local phase=detail:match("^(%w+): ")
    if phase then detail=detail:sub(#phase+3) end
    detail=detail:gsub('^.-%]:%d+: ', ''):gsub('^.-:%d+: ', '')
    local notification=m.Name .. (phase and " "..phase or "") .. " failed: " .. detail:sub(1,180)
        .. ". Open its details to retry or choose another entry."
    Util.CommunityDiagnostics.Report("module-failed", m.Name, m._UhhhhhhSource or "User module", reason,
        m._UhhhhhhRandomSelection and notification or nil)
    if not m._UhhhhhhRandomSelection then Util.UINotify(notification)end
    if m.ModuleType == "DANCE" and m._UhhhhhhRandomSelection and CurrentDance == m then
        m._UhhhhhhRandomSelection = nil
        FavoriteSystem.PlayRandomDance(true)
    end
end

local function EnsureAnimationModule(m, character)
    local assets=m.Assets
    if StreamRuntime and m._UhhhhhhStream then
        local ok,result=pcall(StreamRuntime.Prepare,m)
        if not ok then FailAnimationModule(m,character,"Stream preparation: "..tostring(result)); return false end
        assets=result
    end
    if m._UhhhhhhRuntimeFailure then return false end
    if m._UhhhhhhAssetFailure then return false end
    if m._UhhhhhhMissingAssets then
        FailAnimationModule(m, character, "Files absent from upstream pack: " .. table.concat(m._UhhhhhhMissingAssets, ", "))
        return false
    end
    local ready,filename,reason,missing=AssetEnsure(assets,m)
    local active=StreamRuntime and StreamRuntime.Active[m]
    for _,reference in ipairs(active and active.OptionalAssets or m.OptionalAssets or {}) do
        if not AssetDownload(reference,m) then
            local path=AssetGetPathFromFilename(reference)
            if _Assetdownloading[path] then ready=false
            else
                local failure=_Assetretry[path]
                if failure then
                    m._UhhhhhhOptionalNotices=m._UhhhhhhOptionalNotices or {}
                    if m._UhhhhhhOptionalNotices[reference]~=failure.LastError then
                        m._UhhhhhhOptionalNotices[reference]=failure.LastError
                        Util.CommunityDiagnostics.Report("optional-asset",m.Name,m._UhhhhhhSource,
                            (reference:match("([^/@]+)@") or reference)..": "..tostring(failure.LastError)
                            .."; action unavailable; remaining moveset can play.")
                    end
                end
            end
        end
    end
    if ready then m._UhhhhhhAssetFailureNotice=nil
    elseif filename then
        local notice=tostring(filename)..": "..tostring(reason)
        if missing then m._UhhhhhhAssetFailure=notice end
        if m._UhhhhhhAssetFailureNotice~=notice then
            m._UhhhhhhAssetFailureNotice=notice
            local label=m.Name..(m._UhhhhhhSource and " ["..m._UhhhhhhSource.."]" or "")
            local notification=label.." needs "..notice:sub(1,160)
                ..(missing and (m._UhhhhhhSource and m._UhhhhhhSource:sub(1,7)=="Stream:"
                    and ". Use Retry streamed assets, or select another entry."
                    or ". Open its details to retry the download, or select another entry.")
                    or ". Download will retry after the backoff; you can select another entry.")
            Util.CommunityDiagnostics.Report("asset-failed",m.Name,m._UhhhhhhSource or "User module",notice,
                (not missing or m._UhhhhhhRandomSelection)and notification or nil)
            if missing and not m._UhhhhhhRandomSelection then Util.UINotify(notification)end
            if m.ModuleType == "DANCE" and m._UhhhhhhRandomSelection and CurrentDance == m then
                m._UhhhhhhRandomUnavailable, m._UhhhhhhRandomSelection = true, nil
                FavoriteSystem.PlayRandomDance(true)
            end
        end
    end
    m._UhhhhhhLoadingAssets=not ready and not m._UhhhhhhAssetFailure and not m._UhhhhhhRuntimeFailure
    return ready
end

local function RunAnimationModule(m, callback, character, dt)
    if m._UhhhhhhRuntimeFailure then return false end
    if callback=="Init"then m._UhhhhhhRuntimeReady=false end
    local profiler=Util.FrameProfiler
    local started=profiler and profiler.Begin("Animation modules")
    local oldOwner=AnimLib.ModuleOwner
    AnimLib.ModuleOwner=m
    local ok, reason = xpcall(function()
        local target=Reanimate.ControllerRigAdapter.ModuleRig(character,m)
        Reanimate.CharacterMotion.BeforePose(character)
        Reanimate.ControllerRigAdapter.Prepare(target)
        if callback=="Init" then
            local h=character:FindFirstChildOfClass("Humanoid")
            local baseline={Joints={},WalkSpeed=h and h.WalkSpeed}
            for _,joint in ipairs(character:GetDescendants()) do
                if joint:IsA("Motor6D") then
                    baseline.Joints[joint]={C0=joint.C0,C1=joint.C1,Enabled=joint.Enabled,Transform=joint.Transform}
                end
            end
            m._UhhhhhhPoseBaseline=baseline
        end
        if callback == "Update" then m.Update(dt, target) else m.Init(target) end
        if callback=="Init"then
            local specs=SaveData.RigHatBindings[ModuleIdentity.PreferenceKey(m) or m.InternalName or m.Name]or m.Hats
            if specs then Reanimate.HatBindings.Apply(m,target,specs)end
        end
        Reanimate.ControllerRigAdapter.Apply(target)
    end, debug.traceback)
    AnimLib.ModuleOwner=oldOwner
    if started then profiler.Finish("Animation modules",started) end
    if not ok then FailAnimationModule(m, character, callback .. ": " .. tostring(reason))
    elseif callback=="Init"then m._UhhhhhhRuntimeReady=true m._UhhhhhhLoadingAssets=false end
    return ok
end

local function StepAnimationRuntime(character,dt)
    if CurrentMovementStyle then
        if character:GetAttribute("MovementInit") then
            RunAnimationModule(CurrentMovementStyle,"Update",character,dt)
        elseif EnsureAnimationModule(CurrentMovementStyle,character) then
            HatReanimator.HatWeldOverride={}
            table.clear(HatReanimator.HatCFrameOverride)
            character:SetAttribute("MovementInit",true)
            character:SetAttribute("MovesetInternalName",CurrentMovementStyle.InternalName)
            RunAnimationModule(CurrentMovementStyle,"Init",character)
        else SetOverrideMovesetMusic(nil) end
    else
        character:SetAttribute("MovementInit",nil)
        _MovementStyleIndex=nil
    end
    -- Dance selection must work even while a moveset has failed or is loading.
    if CurrentDance~=_CurrentDance then
        if _CurrentDance then
            pcall(_CurrentDance.Destroy,Reanimate.ControllerRigAdapter.ModuleRig(character,_CurrentDance,false))
            StopModuleAnimations(_CurrentDance)
            _CurrentDance._UhhhhhhPoseBaseline=nil
            ResetDancePose(character)
        end
        _CurrentDance=CurrentDance
        if _CurrentDance then _CurrentDance._UhhhhhhRuntimeFailure=nil end
        character:SetAttribute("IsDancing",nil)
        character:SetAttribute("DanceInternalName",nil)
        SetOverrideDanceMusic(nil)
    end
    if _CurrentDance then
        if character:GetAttribute("IsDancing") then
            RunAnimationModule(_CurrentDance,"Update",character,dt)
        elseif EnsureAnimationModule(_CurrentDance,character) then
            character:SetAttribute("IsDancing",true)
            character:SetAttribute("DanceInternalName",_CurrentDance.InternalName)
            RunAnimationModule(_CurrentDance,"Init",character)
        else SetOverrideDanceMusic(nil) end
    end
end

-- This connection is created before moveset-specific AnimLib bindings. On
-- PreSimulation it restores legacy Heartbeat-written Transform first; a modern
-- AnimLib animator bound to PreSimulation then writes its fresh pose afterward.
RunService.PreSimulation:Connect(function()
	if not __TheoIsExternal() then
		return
	end

	local character = Reanimate.Character
	if not character or not character.Parent then return end

	-- If a community moveset intentionally uses Roblox AnimationTracks, let the
	-- Roblox Animator own Transform normally. Do not replay the manual cache.
	local replay = character == __TheoGelatekPoseCharacter
        and (character:GetAttribute("MovementInit") == true or character:GetAttribute("IsDancing") == true)
        and not __TheoHasPlayingRobloxTrack(character)
	if replay then for joint, transform in pairs(__TheoGelatekPoseCache) do
		if joint
			and joint.Parent
			and joint:IsDescendantOf(character)
			and typeof(transform) == "CFrame"
		then
			pcall(function()
				joint.Transform = transform
			end)
		end
	end end
    Reanimate.CharacterMotion.ApplyIK(character)
end)

task.spawn(function()
	local _oldcharacterreference = nil
	local __TheoSeenRefreshSerial = __TheoManualRefreshSerial
	local errorsandwarnings = {}
	local currenterrorid = 1
	while SCREENGUI.Parent do
		local dt = RunService.Heartbeat:Wait()
		xpcall(function(dt)
            if StreamRuntime then StreamRuntime.Tick() end
			local ReanimCharacter = Reanimate.Character
			if ReanimCharacter and ReanimCharacter:GetAttribute("_UhhhhhhAnimationRetiring") then return end
			if ReanimCharacter and ReanimCharacter:GetAttribute("_UhhhhhhAnimationRefreshFailed") == true
				and __TheoSeenRefreshSerial == __TheoManualRefreshSerial then return end
			if ReanimCharacter and __TheoSeenRefreshSerial ~= __TheoManualRefreshSerial then
				__TheoSeenRefreshSerial = __TheoManualRefreshSerial
                if CurrentMovementStyle then CurrentMovementStyle._UhhhhhhRuntimeFailure = nil end
                if CurrentDance then CurrentDance._UhhhhhhRuntimeFailure = nil end
				TeardownAnimationRuntime(_oldcharacterreference or ReanimCharacter, true)
				ReanimCharacter = RefreshAnimationCharacter(ReanimCharacter)
				_oldcharacterreference = ReanimCharacter
			end
			SaveData.MovesetIndex = MovementStyleIndex
			if ReanimCharacter then
				if _oldcharacterreference ~= ReanimCharacter then
					TeardownAnimationRuntime(_oldcharacterreference, true)
					ResetMovesetWalkSpeed(ReanimCharacter)
				end
				if MovementStyleIndex ~= _MovementStyleIndex then
					local switching = _MovementStyleIndex ~= nil or CurrentMovementStyle ~= nil
					TeardownAnimationRuntime(ReanimCharacter, not switching)
					if switching then
						ReanimCharacter = RefreshAnimationCharacter(ReanimCharacter)
					else
						ReanimCharacter:SetAttribute("_UhhhhhhAnimationRefresh", nil)
					end
					ResetMovesetWalkSpeed(ReanimCharacter)
					_MovementStyleIndex = MovementStyleIndex
					CurrentMovementStyle = MovementStyles[MovementStyleIndex]
                    if CurrentMovementStyle then CurrentMovementStyle._UhhhhhhRuntimeFailure = nil end
					SetOverrideMovesetMusic(nil)
				end
                StepAnimationRuntime(ReanimCharacter,dt)
				EnforceWalkSpeedOverride(ReanimCharacter)
                Reanimate.CharacterMotion.ApplyIK(ReanimCharacter)
				__TheoCaptureGelatekControllerPose(ReanimCharacter, dt)
			else
				-- Keep a queued dance selected while retiring only its old controller writers.
				__TheoClearGelatekPoseCache()
				_MovementStyleIndex = nil
				SetOverrideMovesetMusic(nil)
				SetOverrideDanceMusic(nil)
				if CurrentMovementStyle then
					local oldMovementStyle = CurrentMovementStyle
					CurrentMovementStyle = nil
					StopModuleAnimations(oldMovementStyle)
					oldMovementStyle._UhhhhhhPoseBaseline=nil
					pcall(oldMovementStyle.Destroy, Reanimate.ControllerRigAdapter.ModuleRig(_oldcharacterreference,oldMovementStyle,false))
				end
				if _CurrentDance then
					local oldDance = _CurrentDance
					_CurrentDance = nil
					StopModuleAnimations(oldDance)
					oldDance._UhhhhhhPoseBaseline=nil
					pcall(oldDance.Destroy, Reanimate.ControllerRigAdapter.ModuleRig(_oldcharacterreference,oldDance,false))
					ResetDancePose(_oldcharacterreference)
				end
			end
			_oldcharacterreference = ReanimCharacter
		end, function(m)
			m = debug.traceback("ANIMLOOP :: " .. m)
			local id = errorsandwarnings[m]
			if not id then
				errorsandwarnings[m] = { currenterrorid, 0 }
				currenterrorid += 1
				warn("ERROR #" .. errorsandwarnings[m][1] .. ": " .. m)
			else
				id[2] += 1
				if id[2] <= 8192 and math.sqrt(id[2]) % 1 == 0 then
					warn("ERROR #" .. id[1] .. " repeated " .. id[2] .. " times")
				end
			end
		end, dt)
	end
end)
