-- Keep the marketplace's many page/controller locals out of the already-large
-- runtime chunk.  Some executor Luau builds enforce the 200-register limit
-- while compiling this embedded source, even though syntax-only checks pass.
;(function()
(function()
    local page = UI.CreatePage()
    page.ZIndex, page.Position = 2, UDim2.new(0.5, 360, 0.5, 0)
    page.Interactable, page.Visible = false, false
    UI.CreateButton(page, "&lt; Back", 20).Activated:Connect(function()
        UI.Workspace.Back(page, UI.Navigation.Pages.diagnostics)
    end)
    UI.CreateText(page, "Addon error details", 20, Enum.TextXAlignment.Left)
    UI.CreateText(page, "Addon failures are quiet by default. Broken random dances are skipped; core errors are not hidden.", 12, Enum.TextXAlignment.Left)
    local debugSwitch = UI.CreateSwitch(page, "Show addon errors (debug)", Util.CommunityDiagnostics.Enabled())
    debugSwitch.Changed:Connect(function(value)
        SaveData.CommunityDiagnosticsEnabled = value == true
        SaveSettingsNow()
    end)
    local text = UI.CreateText(page, "", 12, Enum.TextXAlignment.Left)
    text.RichText = false
    local function refresh() text.Text = Util.CommunityDiagnostics.Describe() end
    UI.CreateButton(page, "Refresh details", 16).Activated:Connect(refresh)
    UI.CreateButton(page, "Copy error log", 16).Activated:Connect(function()
        local copied = pcall(setclipboard, Util.CommunityDiagnostics.Describe())
        Util.UINotify(copied and "Copied addon error log" or "Clipboard unavailable; read the details below")
    end)
    UI.CreateButton(page, "Clear error log", 16).Activated:Connect(function()
        Util.CommunityDiagnostics.Clear()
        refresh()
    end)
    UI.CreateButton(UI.Navigation.Pages.diagnostics, "Addon error details &gt;", 18).Activated:Connect(function()
        refresh()
        UI.Workspace.Open(page, UI.Navigation.Pages.diagnostics)
    end)
end)()
StreamRuntime = Steve110.Require("main/market_stream")({
    UI = UI, Cache = StreamCache, Task = task, Fetch = HttpFetchBody, Compile = CompileAnimationModule,
    Bind = GiveFunctionsToFunction, Folder = MarketCatalog.Folder, RetryAssets=RetryAnimationAssets,
    ClearRows = Util.ClearAllChildrenGui, Notify = Util.UINotify,
    OpenDetails = function(m,parent) FavoriteSystem.OpenModuleDetails(m,parent) end,
    Random = function() FavoriteSystem.PlayRandomDance() end,
    OpenWorkspace=function(item,parent)
        return AnimLib.GetStudioWorkspace().OpenBrowser("pack",{Pack=item})
    end,
    Changed = function() FavoriteSystem.Refresh() end,
    TagFactories=function(list,source)
        list=AnimLib.GetCreatorTools().Entries(list)
        return ModuleIdentity.TagFactories(list,source)
    end,
    Register = function(m,descriptor,factory,context)
        GetModuleHash(m)
        local canonical,isNew=ModuleIdentity.Register(m,factory,context,m._UhhhhhhSource)
        if not isNew then
            if canonical~=m then
                for animator in pairs(AnimLib.ActiveAnimators or {})do
                    if animator._UhhhhhhModuleOwner==m then pcall(function()animator:Destroy(false)end)end
                end
            end
            return canonical
        end
        local added=m.ModuleType=="DANCE" and AddDance(m) or AddMoveset(m)
        if not added then return nil end
        return m
    end,
    Report = function(kind, name, source, reason)
        Util.CommunityDiagnostics.Report(kind, name, source, reason)
    end,
    DeferInstalled = function(item)
        SaveData.MarketPackModes = SaveData.MarketPackModes or {}
        SaveData.MarketPackModes[item.File:gsub("/*$", "") .. "/"] = "stream"
        SaveSettingsNow()
    end,
    Build = function(factory, context)
        assert(type(factory) == "function", "Entry is not a function")
        local bindOwner=GiveFunctionsToFunction(factory, context)
        local m = factory()
        local valid, reason = ValidateModuleObject(m)
        if not valid then return nil, reason end
        bindOwner(m)
        ResolveModuleAssets(m, context)
        GetModuleHash(m)
        return m
    end,
    IsSelected = function(m)
        return Reanimate.Character~=nil and (m.ModuleType == "DANCE" and CurrentDance == m
            or m.ModuleType == "MOVESET" and MovementStyles[MovementStyleIndex] == m)
    end,
    Play = function(m)
        if not Reanimate.Character then Util.UINotify("Start reanimation before playing a streamed entry"); return false end
        if m.ModuleType == "DANCE" then CurrentDance = m
        else
            m.StreamPreviousStyle = MovementStyleIndex
            MovementStyleIndex = table.find(MovementStyles,m)
        end
        return true
    end,
    Stop = function(m)
        if _CurrentDance == m or CurrentMovementStyle == m then
            TeardownAnimationRuntime(Reanimate.Character, CurrentDance ~= m)
        elseif CurrentDance == m then CurrentDance = nil end
        if m.ModuleType == "DANCE" then UISound.DanceMusic.SoundId = "" end
        local index = table.find(MovementStyles, m)
        if m.ModuleType=="MOVESET" and index and MovementStyleIndex==index then
            local previous=m.StreamPreviousStyle
            if not previous or previous==index or not MovementStyles[previous] or MovementStyles[previous]._UhhhhhhStream then
                previous=nil
                for i,style in ipairs(MovementStyles) do if style~=m and not style._UhhhhhhStream then previous=i break end end
            end
            MovementStyleIndex=previous or 1
            UISound.MovesetMusic.SoundId = ""
        end
    end,
})
SCREENGUI.Destroying:Connect(function() StreamRuntime.Clear() end)
local function GetMarketList(refresh) return MarketCatalog.Get(refresh) end
local MarketInstaller=Steve110.Require("main/market_install")({
    Task=task, Notify=Util.UINotify,
    IsInstalled=function(item)
        if item.Type~="folder" then return isfile("UhhhhhhReanim/Modules/"..item.File) end
        return SaveData.MarketPackModes and SaveData.MarketPackModes[item.File:gsub("/*$", "").."/"]=="installed"
    end,
    Prepare=function(item,targetPath)
        if item.Type~="folder" and not item.NeedsContext then
            return {{Source=item.Source,File=item.File,Path=targetPath or ("UhhhhhhReanim/Modules/"..item.File)}}
        end
        local modules, context, key = MarketCatalog.Folder(item)
        context.Directories={}
        for _,module in ipairs(modules)do context.Directories[module.File]=(module.Relative or ""):match("^(.*)/[^/]+$")end
        local contextPath="UhhhhhhReanim/MarketContexts/"..key..".json"
        local data=HttpService:JSONEncode(context)
        EnsureAssetFolders(contextPath)
        writefile(contextPath,data)
        assert(readfile(contextPath)==data,"Pack context write failed")
        local records={}
        for _,module in ipairs(modules) do
            table.insert(records,{Source=module.Source,File=module.File,Path="UhhhhhhReanim/Modules/"..module.File,
                Transform=function(body)return "-- UHH_MARKET_CONTEXT "..key.."\n"..body end})
        end
        return records
    end,
    Download=function(record,force,done)
        AssetDownloadAgent(record.Source,record.File,record.Path,force,record.Transform,nil,nil,done)
    end,
    Commit=function(item)
        if item.Type=="folder" then
            SaveData.MarketPackModes=SaveData.MarketPackModes or {}
            SaveData.MarketPackModes[item.File:gsub("/*$", "").."/"]="installed"
            SaveSettingsNow()
        end
    end,
    Apply=function()ForceModuleReload("SKIPHASH")end,
    CheckLoaded=function(records)
        for _,record in ipairs(records) do
            local names=UserModulesListor[record.File]
            if not names or #names==0 then return false,"Check Addon error details for "..record.File end
        end
        return true
    end,
})
SCREENGUI.Destroying:Connect(MarketInstaller.Dispose)
local function InstallMarketItem(item, force, targetPath)return MarketInstaller.Install(item,force,targetPath)end
local function AddMarketInstallControls(page,item,targetPath)
    local button,label=UI.CreateButton(page,"Install add-on",20)
    local status=UI.CreateText(page,"",13,Enum.TextXAlignment.Left) status.RichText=false
    local release=MarketInstaller.Watch(item,page,function(state)
        label.Text=MarketInstaller.Caption(state) status.Text=state.Message or ""
    end)
    page.Destroying:Connect(release)
    button.Activated:Connect(function()InstallMarketItem(item,true,targetPath)end)
end
