AnimLib.StudioSources={
    Catalog=GetMarketList,Status=MarketCatalog.Status,Providers=MarketCatalog.Registry,
    Author=function(module)
        if module.Author or module.User then return module.Author or module.User end
        if module._UhhhhhhModuleContext and module._UhhhhhhModuleContext.Author then return module._UhhhhhhModuleContext.Author end
        local key=(module._UhhhhhhSource or ""):match("^[^:]+:%s*(.+)$")
        if not key then return nil end
        local rows,_,byFile=MarketCatalog.Get(false)
        if byFile[key]then return byFile[key].User end
        -- Older installed pack contexts predate author metadata. Resolve only
        -- a matching catalog path; an unrelated file name cannot claim credit.
        local best,length=nil,0
        for _,item in ipairs(rows)do
            local prefix=item.File:gsub("/*$","").."/"
            if item.Type=="folder"and key:sub(1,#prefix)==prefix and #prefix>length then
                best,length=item.User,#prefix
            end
        end
        return best
    end,
    Modules=function()
        local modules={} for _,m in ipairs(DanceableDances)do table.insert(modules,m)end
        for _,m in ipairs(MovementStyles)do table.insert(modules,m)end return modules
    end,
    Watch=function(item,owner,changed,retry)return StreamRuntime.Watch(item,owner,changed,retry)end,
    IsFavorite=FavoriteSystem.IsFavorite,IsHidden=FavoriteSystem.IsHidden,
    ToggleFavorite=FavoriteSystem.ToggleFavorite,ToggleHidden=FavoriteSystem.ToggleHidden,
    Play=function(m)
        assert(Reanimate.Character,"Start reanimation before playing")
        if m.ModuleType=="DANCE" then m._UhhhhhhRandomSelection=nil CurrentDance=m
        else
            if m._UhhhhhhStream then m.StreamPreviousStyle=MovementStyleIndex end
            MovementStyleIndex=assert(table.find(MovementStyles,m),"Moveset is no longer loaded")
        end
    end,
    Stop=function()StreamRuntime.Stop()CurrentDance=nil end,
    Random=FavoriteSystem.PlayRandomDance,
    Configure=function(m,parent)m.Config(parent)end,
    WriteClonedClip=function(reference,track)
        assert(type(reference)=="string"and reference:match("^StudioClones/")and MarketCatalog.SafePath(reference)
            and not reference:find("@",1,true),"only local cloned assets can be replaced")
        local extension=reference:match("%.([^.]+)$")local files=AnimLib.GetFileTools()
        local bytes
        if extension=="anim"then bytes=buffer.tostring(files.ToBuffer(track))
        elseif extension=="json"then bytes=files.ToJSON(track)
        elseif extension=="txt"then bytes=files.ToText(track)
        else error("choose an editable animation asset",0)end
        local path=AssetGetPathFromFilename(reference)assert(isfile(path),"the cloned asset no longer exists")
        local original=readfile(path)
        local ok,reason=pcall(function()writefile(path,bytes)assert(readfile(path)==bytes,"cloned clip write failed")end)
        if not ok then pcall(writefile,path,original)error(reason,0)end
        AnimLib.Track.clearfilecache(path)ContentCache.Verified(path)
        return path
    end,
    Clone=function(module,cancelled,progress)
        local clone=Steve110.Require("main/studio_clone")({
            Source=function(m)
                if m._UhhhhhhStream and m._UhhhhhhStream.Source then return m._UhhhhhhStream.Source,m._UhhhhhhStream.Context end
                local file=m._UhhhhhhModuleFile or (m._UhhhhhhSource or ""):match("^Installed:%s*(.+)$")
                assert(file and MarketCatalog.SafePath(file),"stream or install the marketplace module first")
                local bytes=readfile("UhhhhhhReanim/Modules/"..file)
                return bytes,m._UhhhhhhModuleContext or ReadMarketContext(bytes,file)
            end,
            Unique=function(name)
                local stem=tostring(name):gsub('[^%w_%-]','_'):sub(1,64)if stem==""then stem="module"end
                for i=1,1000 do
                    local key=stem..(i==1 and ""or "_"..i)
                    if not isfolder("UhhhhhhReanim/Modules/StudioClones/"..key)then return key end
                end
                error("choose another copy name",0)
            end,
            ReadAsset=function(reference,cancel)
                local deadline=os.clock()+45 local path=AssetGetPathFromFilename(reference)
                repeat
                    assert(not cancel or not cancel(),"clone cancelled")
                    if AssetDownload(reference,"editor-clone")then return readfile(path)end
                    local failure=_Assetretry[path]
                    if failure and not _Assetdownloading[path]then error(failure.LastError,0)end
                    task.wait(.05)
                until os.clock()>deadline
                error("media download timed out",0)
            end,
            Author=AnimLib.StudioSources.Author,
            Commit=function(key,source,assets,context,contextKey)
                local folder="UhhhhhhReanim/Modules/StudioClones/"..key.."/"
                for _,asset in ipairs(assets)do
                    local path=AssetGetPathFromFilename(asset.Reference)
                    EnsureAssetFolders(path)writefile(path,asset.Bytes)
                    assert(readfile(path)==asset.Bytes,"cloned media write failed")ContentCache.Verified(path)
                end
                local metadataPath="UhhhhhhReanim/MarketContexts/"..contextKey..".json"
                local json=HttpService:JSONEncode(context)EnsureAssetFolders(metadataPath)writefile(metadataPath,json)
                assert(readfile(metadataPath)==json,"cloned source context write failed")
                EnsureAssetFolders(folder.."main.lua")writefile(folder.."main.lua",source)
                assert(readfile(folder.."main.lua")==source,"cloned module write failed")
                return folder
            end,
        })
        return clone.Clone(module,cancelled,progress)
    end,
    Retry=RetryAnimationAssets,
    Install=function(item)return InstallMarketItem(item,true)end,
    WatchInstall=MarketInstaller.Watch,InstallCaption=MarketInstaller.Caption,
}

end)()

