for path, content in pairs(files) do
    local parent = path:match("^(.*)/[^/]+$")
    local current = ""
    for segment in parent:gmatch("[^/]+") do
        current = current == "" and segment or current .. "/" .. segment
        ensure(current)
    end
    writefile(path, content)
    assert(readfile(path) == content, "Install write verification failed: " .. path)
end

-- Remove the obsolete generated snapshot; installed user packs remain intact.
local obsolete = "UhhhhhhReanim/System/runtime/steve110/main/market_manifest.lua"
if type(delfile) == "function" and isfile(obsolete) then pcall(delfile, obsolete) end

if not isfile("UhhhhhhReanim/System/config.json") then
    local config = isfile("Theos Dancezzzzz/Bridge/config.json")
        and readfile("Theos Dancezzzzz/Bridge/config.json") or readfile("UhhhhhhReanim/System/config.default.json")
    config = config:gsub("Theos Dancezzzzz/Bridge", "UhhhhhhReanim/System")
    writefile("UhhhhhhReanim/System/config.json", config)
    assert(readfile("UhhhhhhReanim/System/config.json") == config, "Config migration write verification failed")
end
assert(not _G.UhhhhhhLoaded, "Uhhhhhh is already loaded; rejoin first")
local chunk, err = loadstring(readfile("UhhhhhhReanim/System/launch.lua"))
assert(type(chunk) == "function", "compile failed: " .. tostring(err))
table.clear(files)
files = nil
if task and type(task.defer) == "function" then
    task.defer(chunk)
    return
end
return chunk()
